src/core/agent/agentBackend.ts:
// The internal agent protocol both backends implement (PLAN.md D1): the
// Muse Code host (MSP over `muse serve`, M2–M6) and the Model API backend
// (direct HTTPS with an in-process tool harness, M7). The conversation
// controller and the webview see only these interfaces and the AgentEvent
// union, never which backend is active.

import type {
  AgentEvent,
  ItemSnapshot,
  QuestionAnswer,
  RequirementRef,
  SessionGoal,
  TodoItem,
} from '../../shared/agentEvents'
import type { GoalCommandVerb, SubagentAction } from '../../shared/constants'
import type { SubscriptionUsage } from '../../shared/usage'
import type {
  ScheduleCadence,
  ScheduledPrompt,
  ScheduleRunConfirmation,
} from '../../shared/schedule'
import type { ApprovalMode } from '../../shared/permissionModes'
import type { SessionExport } from '../export/sessionTransfer'

export type BackendKind = 'museCode' | 'modelApi'

/** How a backend process ended, as the conversations need to know it (PLAN.md D25). */
export interface HostExit {
  /** For the log and the notice: the code or signal, and what it means. */
  readonly description: string
  /** The extension closed it on purpose (a restart, a sign-out): not a crash. */
  readonly isExpected: boolean
  /** The process refuses to run as configured (a bad setting, an old build): restarting will not help. */
  readonly isPersistent: boolean
}

// The three errors below cross from a host to the conversation controller.
// The Model API host runs from a bundle of its own, loaded on first use
// (M57, PLAN.md D6), which carries its own copy of these classes, so
// `instanceof` misses an error that host threw. Callers test with the
// `is…` guards instead, which read the name and the field every copy sets;
// the lint config refuses `instanceof` on these classes in src/.
const SESSION_NOT_LOADED_ERROR = 'SessionNotLoadedError'
const PROMPT_SETTLED_ERROR = 'PromptSettledError'
const GOAL_REFUSED_ERROR = 'GoalRefusedError'
const MUSE_CODE_FAULT_ERROR = 'MuseCodeFaultError'
const DECISION_NOT_APPLIED_ERROR = 'DecisionNotAppliedError'
const STEER_REFUSED_ERROR = 'SteerRefusedError'

/** An `Error` of either bundle carrying the given name. */
function isNamedError(error: unknown, name: string): error is Error {
  return error instanceof Error && error.name === name
}

/**
 * A command named a session the host no longer holds (MSP `sessionNotLoaded`:
 * evicted, or closed by the host). The caller resumes it and retries.
 */
export class SessionNotLoadedError extends Error {
  public constructor(
    public readonly sessionId: string,
    message: string,
  ) {
    super(message)
    this.name = SESSION_NOT_LOADED_ERROR
  }
}

/** Whether a host refused a command for a session it no longer holds. */
export function isSessionNotLoadedError(error: unknown): error is SessionNotLoadedError {
  return (
    isNamedError(error, SESSION_NOT_LOADED_ERROR) &&
    'sessionId' in error &&
    typeof error.sessionId === 'string'
  )
}

/** Why the host refused a decision or answer that arrived too late (PLAN.md D26). */
export type PromptSettledReason = 'alreadySettled' | 'movedOn' | 'gone'

const PROMPT_SETTLED_REASONS: readonly unknown[] = [
  'alreadySettled',
  'movedOn',
  'gone',
] satisfies readonly PromptSettledReason[]

/**
 * The prompt was answered elsewhere, advanced to another stage, or is no
 * longer pending when this decision or answer arrived. Nothing is wrong: the
 * card follows the host's own resolve / update events.
 */
export class PromptSettledError extends Error {
  public constructor(
    public readonly reason: PromptSettledReason,
    message: string,
  ) {
    super(message)
    this.name = PROMPT_SETTLED_ERROR
  }
}

/** Whether a host refused a decision or answer because its prompt had settled. */
export function isPromptSettledError(error: unknown): error is PromptSettledError {
  return (
    isNamedError(error, PROMPT_SETTLED_ERROR) &&
    'reason' in error &&
    PROMPT_SETTLED_REASONS.includes(error.reason)
  )
}

/**
 * A fault inside Muse Code that no choice of the user's caused (PLAN.md D26,
 * captured live 2026-10-02 on Muse Code 1.4.2):
 * - `approvalReplay`: every `turn/start` of the session fails with "approval
 *   replay failed: decision stage evidence contains an unrecorded human
 *   resolution" after a turn stopped while a multi-stage approval had a
 *   decided stage. A restart of `muse serve` lets the session run again.
 * - `approvalLedger`: `approval/decide` applied the decision, then answered
 *   "approval decide settlement failed: approval ledger durability fence…"
 *   (meta-models/muse-code-sdk#29); after the replay fault it does so for
 *   every decision of that session.
 */
export type MuseCodeFault = 'approvalReplay' | 'approvalLedger'

const MUSE_CODE_FAULTS: readonly unknown[] = [
  'approvalReplay',
  'approvalLedger',
] satisfies readonly MuseCodeFault[]

export class MuseCodeFaultError extends Error {
  public constructor(
    public readonly fault: MuseCodeFault,
    message: string,
  ) {
    super(message)
    this.name = MUSE_CODE_FAULT_ERROR
  }
}

/** Whether Muse Code failed a command on a fault of its own (`MuseCodeFaultError`). */
export function isMuseCodeFaultError(error: unknown): error is MuseCodeFaultError {
  return (
    isNamedError(error, MUSE_CODE_FAULT_ERROR) &&
    'fault' in error &&
    MUSE_CODE_FAULTS.includes(error.fault)
  )
}

/**
 * A decision that failed, and that the host confirmed did not apply: its
 * stage is still the one waiting. Only then may the card offer the choice
 * again (one decision per stage, PLAN.md D26).
 */
export class DecisionNotAppliedError extends Error {
  public constructor(message: string) {
    super(message)
    this.name = DECISION_NOT_APPLIED_ERROR
  }
}

/** Whether a failed decision is known not to have applied. */
export function isDecisionNotAppliedError(error: unknown): error is DecisionNotAppliedError {
  return isNamedError(error, DECISION_NOT_APPLIED_ERROR)
}

/**
 * A steer the backend refused outright, so none of it reached the running
 * turn: Muse Code found no turn to take it (MSP `commandRejected` with a
 * no-turn reason), or the Model API session took nothing. Only then may the
 * message go as a new turn instead. Any other steer failure may have
 * reached the turn, and nothing more is sent (CLI recovery, 2026-10-03).
 */
export class SteerRefusedError extends Error {
  public constructor(message: string) {
    super(message)
    this.name = STEER_REFUSED_ERROR
  }
}

/** Whether a steer was refused with nothing taken (a `SteerRefusedError` of either bundle). */
export function isSteerRefusedError(error: unknown): error is SteerRefusedError {
  return isNamedError(error, STEER_REFUSED_ERROR)
}

/**
 * Why a goal command was refused (M45, PLAN.md D38), as MSP's `commandRejected`
 * reasons say it (captured live 2026-09-25): `missing_goal` (there is none)
 * and `invalid_goal_state` (a finished goal cannot be paused, resumed or
 * edited). The Model API backend refuses in the same words.
 */
export type GoalRefusal = 'noGoal' | 'wrongState'

const GOAL_REFUSALS: readonly unknown[] = ['noGoal', 'wrongState'] satisfies readonly GoalRefusal[]

export class GoalRefusedError extends Error {
  public constructor(
    public readonly refusal: GoalRefusal,
    message: string,
  ) {
    super(message)
    this.name = GOAL_REFUSED_ERROR
  }
}

/** Whether a host refused a goal command (a `GoalRefusedError` of either bundle). */
export function isGoalRefusedError(error: unknown): error is GoalRefusedError {
  return (
    isNamedError(error, GOAL_REFUSED_ERROR) &&
    'refusal' in error &&
    GOAL_REFUSALS.includes(error.refusal)
  )
}

/** A goal command (M45): MSP `goal/<verb>`; `set` and `edit` carry the objective. */
export type GoalCommand =
  | { readonly verb: Extract<GoalCommandVerb, 'set' | 'edit'>; readonly objective: string }
  | { readonly verb: Extract<GoalCommandVerb, 'pause' | 'resume' | 'clear'> }

/** What a goal command started: the turn it woke or joined, when it names one. */
export interface GoalCommandOutcome {
  readonly turnId: string | undefined
}

export interface HostInfo {
  readonly kind: BackendKind
  readonly serverName: string
  readonly serverVersion: string
  /** Capabilities the host granted at handshake (`sessionMcp`, …). */
  readonly grantedCapabilities: readonly string[]
  /** False where the host is known to refuse `rename` and `forkSession` (D26). */
  readonly canEditSessions: boolean
}

export interface ModelSummary {
  readonly modelId: string
  readonly displayLabel: string
  readonly contextLimit: number | undefined
  readonly isDefault: boolean
  readonly isActive: boolean
}

export interface SkillSummary {
  readonly selector: string
  readonly displayName: string
  readonly description: string
  readonly argumentHint: string | undefined
}

/** A per-session MCP server over streamable HTTP (MSP `SessionMcpServerConfig`). */
export interface SessionMcpHttpServer {
  readonly url: string
  readonly headers: Readonly<Record<string, string>>
}

/** A per-session MCP server the host starts as a child process (MSP `stdio`; M63c, an ACP client's). */
export interface SessionMcpStdioServer {
  readonly command: string
  readonly args: readonly string[]
  readonly env: Readonly<Record<string, string>>
}

export type SessionMcpServer = SessionMcpHttpServer | SessionMcpStdioServer

export interface StartSessionOptions {
  readonly workspaceRoot: string
  readonly modelId: string
  readonly approvalMode: string
  /** Tool servers, keyed by name: the IDE's, or an ACP client's; needs the `sessionMcp` grant. */
  readonly mcpServers?: Readonly<Record<string, SessionMcpServer>>
  /** A new conversation kept in a side-chat surface (M53). */
  readonly sideChat?: boolean
}

/**
 * A PDF sent whole (M54, PLAN.md D47): the Model API's `input_file`. MSP
 * 1.3.0 has no such part (meta-models/muse-code-sdk#48), so the Muse Code
 * host refuses it rather than send what `turn/start` rejects.
 */
export interface DocumentPart {
  readonly type: 'file'
  readonly base64Data: string
  readonly mediaType: string
  readonly name: string
  readonly sizeBytes: number
  /** Read from the page tree when cheap (core/pdf.ts); undefined when unknown. */
  readonly pageCount: number | undefined
}

/** An image part (MSP `TurnInputPart` of type `image`). */
export interface ImagePart {
  readonly type: 'image'
  readonly base64Data: string
  readonly mediaType: string
  readonly width: number
  readonly height: number
}

/** An explicitly picked, bounded UTF-8 file, carried as named text (M54). */
export interface TextFilePart {
  readonly type: 'textFile'
  readonly name: string
  readonly mediaType: string
  readonly text: string
  readonly sizeBytes: number
}

/** One ordered content part of a turn (MSP `TurnInputPart`, and the Model API's document). */
export type TurnPart =
  | ImagePart
  | DocumentPart
  | TextFilePart
  | { readonly type: 'text'; readonly text: string }
  | { readonly type: 'skill'; readonly selector: string; readonly arguments?: string }

/** An image a turn sent, as the backend kept it (M53): what a rewind puts back in the composer. */
export interface SentImage {
  readonly mediaType: string
  readonly base64Data: string
}

export interface TurnSubmission {
  readonly turnId: string
  /** `started`, `queued` or `steered` (open on the wire). */
  readonly disposition: string
  /** Backend-reserved transcript user ID for exact live-card replay (Model API). */
  readonly userMessageId?: string
}

export interface CompactOutcome {
  readonly status: string
  readonly reason: string | undefined
}

export interface ApprovalDecision {
  readonly approvalId: string
  readonly choiceId: string
  readonly requirementId: RequirementRef
  /** Only for choices with `acceptsFeedback`; delivered to the model. */
  readonly feedback?: string
}

export interface OutputPageRequest {
  readonly itemId: string
  readonly outputRef: string
  readonly offsetBytes: number
  readonly lengthBytes: number
}

export interface OutputPage {
  readonly content: string
  readonly encoding: string
  readonly mediaType: string
  readonly offsetBytes: number
  readonly byteLen: number
  readonly eof: boolean
}

export type SessionEventListener = (event: AgentEvent) => void

export interface ListSessionsOptions {
  readonly workspaceRoot: string
  readonly limit: number
  readonly cursor?: string
}

/** A stored session as the host lists it (the MSP `Session` object, narrowed). */
export interface SessionRecord {
  readonly sessionId: string
  readonly sideChat?: boolean
  readonly name?: string | undefined
  readonly title?: string | undefined
  readonly firstUserPrompt?: string | undefined
  readonly createdAt: string
  readonly updatedAt: string
  readonly lastActivityAt?: string | undefined
  readonly branch?: string | undefined
  readonly status: string
  readonly turnCount: number
  readonly forkedFrom?: { readonly sessionId: string } | null | undefined
  readonly workspaceRoot?: string | null | undefined
  /**
   * Its history came from an imported file (M84, PLAN.md D49): the panel
   * opens it in a mode that asks, whatever the initial mode.
   */
  readonly imported?: boolean
}

export interface SessionPage {
  readonly sessions: readonly SessionRecord[]
  readonly nextCursor: string | undefined
}

/** What a resumed or forked session's history yields for the transcript. */
export interface SessionHistoryOutcome {
  /** `inline`, `snapshot`, `anchoredSnapshot` or `none` (then `items` is empty). */
  readonly mode: string
  readonly sideChat?: boolean
  readonly items: readonly ItemSnapshot[]
  readonly name: string | undefined
  readonly todos: readonly TodoItem[]
  /**
   * The session goal (M45): `null` when the history says there is none,
   * undefined when it cannot say (Muse Code's inline history carries no
   * goal; its snapshot does).
   */
  readonly goal?: SessionGoal | null
}

/** A session loaded by resume or minted by fork (M6). */
export interface LoadedSession {
  readonly session: AgentSession
  readonly record: SessionRecord
  readonly history: SessionHistoryOutcome
  /** The turn running in the session as it was loaded, if any (D26). */
  readonly activeTurnId: string | undefined
}

/** A stored session changed (a full row) or was unloaded. */
export type SessionListEvent =
  | { readonly type: 'changed'; readonly record: SessionRecord }
  | { readonly type: 'closed'; readonly sessionId: string; readonly reason: string }

/** One live conversation on a host. */
export interface AgentSession {
  readonly sessionId: string
  readonly modelId: string
  onEvent(listener: SessionEventListener): () => void
  /**
   * Submit a turn. `displayText` is the transcript's presentation form of
   * the prompt, used when the parts carry more than the user typed (M5).
   */
  sendTurn(parts: readonly TurnPart[], displayText?: string): Promise<TurnSubmission>
  /**
   * A `/review` turn run as the built-in Reviewer, with its own prompt and
   * only the tools that read (M70, PLAN.md D49). The Model API backend has
   * one; Muse Code, which has no Reviewer the extension can pick, reviews
   * with an ordinary turn held in Plan mode instead.
   */
  readonly review?: (parts: readonly TurnPart[], displayText: string) => Promise<TurnSubmission>
  /**
   * Inject input into the running turn. A `SteerRefusedError` says none of
   * it was taken (no turn to steer); any other failure may have reached it.
   */
  steer(expectedTurnId: string, parts: readonly TurnPart[]): Promise<TurnSubmission>
  cancel(): Promise<void>
  setModel(modelId: string): Promise<void>
  /** The session's standing reasoning-effort default (wire vocabulary). */
  setReasoningEffort(reasoningEffort: string): Promise<void>
  /** One of the four MSP approval modes (shared/permissionModes.ts). */
  setApprovalMode(mode: string): Promise<void>
  compact(): Promise<CompactOutcome>
  decideApproval(decision: ApprovalDecision): Promise<void>
  answerQuestions(userInputId: string, answers: readonly QuestionAnswer[]): Promise<void>
  /** Decline the prompt: the tool call resolves with a cancelled result the model sees (M16). */
  cancelQuestions(userInputId: string): Promise<void>
  /**
   * Answer with an explanation instead of the options (MSP `userInput/clarify`,
   * M46): the model reads it and decides again.
   */
  clarifyQuestions(userInputId: string, text: string): Promise<void>
  /**
   * Move a running tool call to the background, its row's id naming it (MSP
   * `task/background`, the TUI's Ctrl+B, M46): the turn goes on without it.
   */
  moveToBackground(taskId: string): Promise<void>
  /** Stop one background task (`task/stop`), or every one (`task/stopAll`), M46. */
  stopTask(taskId: string): Promise<void>
  stopAllTasks(): Promise<void>
  /**
   * The user's own shell command, the TUI's `!` (MSP `session/userShell`,
   * M46): it runs outside any turn, its row arrives as a `userShell` item,
   * and the model sees it with its next request.
   */
  runUserShell(command: string): Promise<void>
  /** An owner command on a native subagent (M18): MSP `subagent/<action>`. */
  controlSubagent(subagentId: string, action: SubagentAction): Promise<void>
  /** A note to a running subagent (`subagent/sendMessage`) or a follow-up task for one that finished (`subagent/followupTask`), M18. */
  messageSubagent(subagentId: string, body: string, isFollowup: boolean): Promise<void>
  /**
   * The session goal's verbs (M45, PLAN.md D38): MSP `goal/<verb>`. Admission
   * only: the goal itself arrives as `goalChanged`. A refusal is a
   * `GoalRefusedError`.
   */
  controlGoal(command: GoalCommand): Promise<GoalCommandOutcome>
  /** Extension-owned schedules only. Muse Code's native cron has no MSP control verbs (M52). */
  readonly schedules?: {
    create(cadence: ScheduleCadence, prompt: string): Promise<ScheduledPrompt>
    list(): Promise<readonly ScheduledPrompt[]>
    cancel(id: string): Promise<boolean>
    /** Admit one due occurrence after host-side price confirmation. */
    run(
      id: string,
      occurrenceMs: number,
      confirmed: ScheduleRunConfirmation,
    ): Promise<TurnSubmission>
  }
  readOutput(request: OutputPageRequest): Promise<OutputPage>
  listSkills(): Promise<readonly SkillSummary[]>
  /** Resolves to the canonical name, or undefined when it arrives as an event. */
  rename(name: string): Promise<string | undefined>
  /**
   * The images a turn of this session sent, where the backend keeps them
   * (M53, PLAN.md D46): the Model API's replay holds them. Muse Code echoes
   * attachment metadata only (MSP `Item.attachments`), so its sessions do
   * not offer this and a rewind warns that the bytes cannot be restored.
   */
  readonly sentImages?: (turnId: string, itemId: string) => readonly SentImage[] | undefined
  /**
   * Replace the todo list from outside a turn (M79): a plan's steps before
   * its first turn. The Model API backend keeps the list itself. MSP 1.3.0
   * has no such command (the list is `session/todoListChanged`, written by
   * the model's own tool), so Muse Code sessions do not offer it.
   */
  readonly setTodos?: (items: readonly TodoItem[]) => void
  /**
   * Told when the backend reports this session's own event log failed, so
   * it can take no new message (CLI recovery): Muse Code 1.4.2 answered a
   * command with "event log failed: …". The Model API keeps no such log.
   */
  readonly onLogDamaged?: (listener: () => void) => () => void
  dispose(): void
}

/** One backend process or connection, multiplexing sessions. */
export interface AgentHost {
  readonly info: HostInfo
  onExit(listener: (exit: HostExit) => void): () => void
  listModels(sessionId?: string): Promise<readonly ModelSummary[]>
  startSession(options: StartSessionOptions): Promise<AgentSession>
  listSessions(options: ListSessionsOptions): Promise<SessionPage>
  /** A session's transcript without loading it (a subagent's child session, M14). */
  readSession(
    sessionId: string,
    options?: { readonly recoverGoal?: boolean },
  ): Promise<SessionHistoryOutcome>
  resumeSession(
    sessionId: string,
    modelId: string,
    mcpServers?: Readonly<Record<string, SessionMcpServer>>,
    options?: { readonly requireSideChat?: boolean },
  ): Promise<LoadedSession>
  forkSession(
    sessionId: string,
    modelId: string,
    lastTurnId?: string,
    options?: { readonly sideChat?: boolean },
  ): Promise<LoadedSession>
  onSessionListEvent(listener: (event: SessionListEvent) => void): () => void
  /**
   * The subscription usage the host last observed (M8); undefined when there
   * is none: a key-billed backend, or a CLI that has not seen a usage frame
   * yet (it reports one after a turn).
   */
  readUsage(): Promise<SubscriptionUsage | undefined>
  /** A fresh observation arrived (MSP `usage/changed`). */
  onUsageChanged(listener: (usage: SubscriptionUsage) => void): () => void
  /**
   * Resume a parsed export as a new session (M84, PLAN.md D49): the host
   * sanitizes it (fresh ids, the caller's asking mode and model, no rules,
   * goals, schedules or patches, each imported turn untrusted data) and
   * loads it. Only the Model API backend offers it.
   */
  readonly importSession?:
    | ((
        doc: SessionExport,
        options: { readonly approvalMode: ApprovalMode; readonly modelId: string },
      ) => Promise<LoadedSession>)
    | undefined
  readonly sessionCount: number
  close(): Promise<void>
}

src/core/agent/approvalRules.ts:
// The one approval a client answers without asking (PLAN.md D24): in "Edit
// automatically", a plain file write, allowed once. Never a protected
// write, an escalation, a staged command, a request replayed from history
// (M46) or anything in another mode. The panel's controller and the ACP
// agent (D62) both ask this module, so the rule exists once; the panel
// adds its own condition (one panel holding the session).
//
// The Auto reviewer on Muse Code (M90, PLAN.md D69) may answer one more
// kind, allowed once, after a reviewer turn said ALLOW: an approval Muse
// Code raised in Auto for the running parent turn that nothing here settles
// (`isReviewableApproval`). The panel's controller asks the reviewer.
//
// A custom agent's child (M76) carries its own `permission-mode` on its
// approval requests. The mode its approvals are answered under is one pure
// function of its parent's mode and its own (`childPermissionMode`), so
// both clients apply the same table.

import type { AgentEvent, ApprovalChoice } from '../../shared/agentEvents'
import {
  IDE_PAID_TOOLS,
  MODEL_API_SUBAGENT_TOOLS,
  type PermissionMode,
} from '../../shared/constants'

const EDIT_AUTOMATICALLY_MODE: PermissionMode = 'acceptEdits'
// Approval subjects that are a plain file write: the Model API's own, and
// Muse Code's `fileAccess` with write access (MSP `ApprovalSubject`).
const FILE_WRITE_SUBJECT = 'fileWrite'
const FILE_ACCESS_SUBJECT = 'fileAccess'
const WRITE_ACCESS = 'write'
const APPROVED_DECISION = 'approved'
const ONCE_SCOPE = 'once'
const AUTO_MODE: PermissionMode = 'auto'
// The subject kinds MSP names (msp.d.ts ApprovalSubject); an unknown kind is
// never answered by a client (tdd SS5.2), so the reviewer never sees one.
const REVIEWABLE_SUBJECTS: ReadonlySet<string> = new Set([
  'shell',
  'fileAccess',
  'network',
  'unixSocket',
  'process',
  'tool',
])
// What the reviewer never answers: a child task, and a paid call (its own
// popup asks, AGENTS.md rule 12).
const CHILD_TASK_TOOLS: ReadonlySet<string> = new Set(Object.values(MODEL_API_SUBAGENT_TOOLS))

// The modes from least to most automatic. Plan refuses; Manual asks for
// every write; Edit automatically answers ordinary writes itself; Auto and
// Bypass already run ordinary writes without a card (permissions.ts). The
// host's own narrowing of the approval mode (narrowApprovalMode) follows
// the same order, which the table test holds the two to.
const AUTOMATION_ORDER: readonly PermissionMode[] = [
  'plan',
  'manual',
  'acceptEdits',
  'auto',
  'bypassPermissions',
]

/**
 * The mode a child's approvals are answered under (M76 review, RV70x): the
 * less automatic of its parent's mode and its own `permission-mode`, the
 * parent's when the agent names none. So a Manual parent caps every child,
 * a Manual child asks under any parent, and an Edit automatically child
 * keeps its automation under an Auto or Bypass parent, which permits it.
 */
export function childPermissionMode(
  parent: PermissionMode,
  child: PermissionMode | undefined,
): PermissionMode {
  if (child === undefined) {
    return parent
  }
  return AUTOMATION_ORDER.indexOf(child) < AUTOMATION_ORDER.indexOf(parent) ? child : parent
}

/** The request's allow-once choice, when it offers one: never an "always" one. */
export function allowOnceChoice(
  event: Pick<Extract<AgentEvent, { type: 'approvalRequested' }>, 'availableChoices'>,
): ApprovalChoice | undefined {
  return event.availableChoices.find(
    (choice) => choice.decision === APPROVED_DECISION && choice.scope === ONCE_SCOPE,
  )
}

/**
 * Whether the Auto reviewer on Muse Code may be asked about an approval
 * (M90, PLAN.md D69): one Muse Code raised in Auto for `parentTurnId`,
 * the running parent turn (so never a child's), with an allow-once choice.
 * Never a request replayed to a later surface, a protected write, one the
 * CLI's own judge escalated, a subject kind MSP does not name, a child task
 * or a paid call.
 */
export function isReviewableApproval(
  event: Extract<AgentEvent, { type: 'approvalRequested' }>,
  mode: PermissionMode,
  parentTurnId: string | undefined,
): boolean {
  if (
    mode !== AUTO_MODE ||
    childPermissionMode(mode, event.permissionMode) !== AUTO_MODE ||
    event.isReplayed === true ||
    event.isProtectedWrite ||
    event.isJudgeEscalated ||
    event.turnId === undefined ||
    event.turnId !== parentTurnId ||
    !REVIEWABLE_SUBJECTS.has(event.subject.kind)
  ) {
    return false
  }
  const tools = [event.toolName, event.subject.toolName]
  return (
    tools.every(
      (tool) => tool === undefined || (!CHILD_TASK_TOOLS.has(tool) && !IDE_PAID_TOOLS.has(tool)),
    ) && allowOnceChoice(event) !== undefined
  )
}

/**
 * The allow-once choice "Edit automatically" takes for a request answered
 * under `mode` (the client's own, for the parent conversation); undefined
 * for anything the user must see.
 */
export function editAutomaticallyChoice(
  event: Extract<AgentEvent, { type: 'approvalRequested' }>,
  mode: PermissionMode,
): ApprovalChoice | undefined {
  if (
    childPermissionMode(mode, event.permissionMode) !== EDIT_AUTOMATICALLY_MODE ||
    event.isReplayed === true ||
    event.isProtectedWrite ||
    event.isJudgeEscalated
  ) {
    return undefined
  }
  const { subject } = event
  const isFileWrite =
    subject.kind === FILE_WRITE_SUBJECT ||
    (subject.kind === FILE_ACCESS_SUBJECT && subject.access === WRITE_ACCESS)
  return isFileWrite && subject.stages === undefined ? allowOnceChoice(event) : undefined
}

src/core/attachments.ts:
// Images, PDFs and picked UTF-8 text (M54, PLAN.md D47), waiting to go out with the next
// message. The host owns the bytes (the webview only shows chips) so a
// pasted screenshot never round-trips through postMessage twice, and the
// turn's parts are built here. PDF and image types are checked by bytes;
// text needs a picker-approved extension plus strict UTF-8 decoding.

import { Buffer } from 'node:buffer'
import path from 'node:path'
import {
  BASE64_DATA_URL_OVERHEAD_CHARS,
  BASE64_INPUT_BLOCK_BYTES,
  BASE64_OUTPUT_BLOCK_CHARS,
  MAX_ATTACHMENTS_PER_MESSAGE,
  MAX_DOCUMENT_BYTES,
  MAX_ENCODED_MEDIA_CHARS,
  MAX_IMAGE_BYTES,
  MAX_MODEL_API_TEXT_ATTACHMENT_BYTES,
  MAX_TEXT_ATTACHMENT_BYTES,
  MODEL_API_MEDIA_PER_REQUEST,
  MODEL_API_PDF_PAGE_IMAGES,
  MSP_ATTACHMENT_FRAME_BUDGET_BYTES,
  PDF_EXTENSION,
  PDF_MEDIA_TYPE,
  TEXT_ATTACHMENT_EXTENSIONS,
  TEXT_ATTACHMENT_MEDIA_TYPE,
  UI_TEXT,
} from '../shared/constants'
import type { AttachmentSummary } from '../shared/protocol'
import { readImageInfo } from './imageDimensions'
import { isPdf, pdfPageCount } from './pdf'
import type { TurnPart } from './agent/agentBackend'
import { textFileInput } from './textAttachment'

export type AddAttachmentResult =
  | { readonly ok: true; readonly attachment: AttachmentSummary }
  | { readonly ok: false; readonly reason: string }

interface StoredAttachment {
  readonly summary: AttachmentSummary
  readonly bytes: Uint8Array
  readonly text?: string
  readonly mspPartBytes?: number
  readonly modelApiTextBytes?: number
}

const FIRST_PRINTABLE_CODE_POINT = 0x20

/** Whether text holds a control character other than a tab or a line break: not a text file. */
export function hasBinaryControlCharacters(content: string): boolean {
  for (const character of content) {
    if ('\t\n\r'.includes(character)) {
      continue
    }
    const codePoint = character.codePointAt(0) ?? FIRST_PRINTABLE_CODE_POINT
    if (codePoint < FIRST_PRINTABLE_CODE_POINT) {
      return true
    }
  }
  return false
}

/**
 * The images a message's attachments stand for in Meta's per-request budget
 * (M54): one per image, and a PDF's page images, at most its first 50. A
 * PDF whose pages could not be counted weighs the full 50, so the host
 * never accepts a set that would force a newly attached file out of view.
 */
function imageWeight(summary: AttachmentSummary): number {
  if (summary.mediaType === TEXT_ATTACHMENT_MEDIA_TYPE) {
    return 0
  }
  return summary.mediaType === PDF_MEDIA_TYPE
    ? Math.min(summary.pageCount ?? MODEL_API_PDF_PAGE_IMAGES, MODEL_API_PDF_PAGE_IMAGES)
    : 1
}

export class AttachmentStore {
  private readonly entries = new Map<string, StoredAttachment>()

  public constructor(
    private readonly newId: () => string,
    private readonly maxEncodedMediaChars: number = MAX_ENCODED_MEDIA_CHARS,
  ) {}

  /** Encoded data URL characters held for this message's images and PDFs. */
  private mediaChars(): number {
    return Array.from(this.entries.values(), (entry) =>
      entry.summary.mediaType === TEXT_ATTACHMENT_MEDIA_TYPE
        ? 0
        : this.encodedChars(entry.bytes, entry.summary.mediaType),
    ).reduce((total, length) => total + length, 0)
  }

  private encodedChars(bytes: Uint8Array, mediaType: string): number {
    const base64Length =
      BASE64_OUTPUT_BLOCK_CHARS * Math.ceil(bytes.byteLength / BASE64_INPUT_BLOCK_BYTES)
    return BASE64_DATA_URL_OVERHEAD_CHARS + mediaType.length + base64Length
  }

  /** Serialized MSP attachment parts, before prompt/context and command envelope. */
  private mspAttachmentBytes(): number {
    return Array.from(this.entries.values(), (entry) => entry.mspPartBytes ?? 0).reduce(
      (total, length) => total + length,
      0,
    )
  }

  /** Conservative text-only share of the Model API context window. */
  private modelApiTextBytes(): number {
    return Array.from(this.entries.values(), (entry) => entry.modelApiTextBytes ?? 0).reduce(
      (total, length) => total + length,
      0,
    )
  }

  private fitsMediaBytes(bytes: Uint8Array, mediaType: string): boolean {
    return this.mediaChars() + this.encodedChars(bytes, mediaType) <= this.maxEncodedMediaChars
  }

  private weight(): number {
    return Array.from(this.entries.values(), (entry) => imageWeight(entry.summary)).reduce(
      (total, weight) => total + weight,
      0,
    )
  }

  private addDocument(name: string, bytes: Uint8Array): AddAttachmentResult {
    if (bytes.byteLength > MAX_DOCUMENT_BYTES) {
      return { ok: false, reason: UI_TEXT.documentTooLarge }
    }
    const pageCount = pdfPageCount(bytes)
    const summary: AttachmentSummary = {
      id: this.newId(),
      name,
      mediaType: PDF_MEDIA_TYPE,
      sizeBytes: bytes.byteLength,
      ...(pageCount !== undefined && { pageCount }),
    }
    // A message Meta would refuse whole (more than 50 images) is refused here, with the reason.
    if (this.weight() + imageWeight(summary) > MODEL_API_MEDIA_PER_REQUEST) {
      return { ok: false, reason: UI_TEXT.documentsOverBudget }
    }
    if (!this.fitsMediaBytes(bytes, PDF_MEDIA_TYPE)) {
      return { ok: false, reason: UI_TEXT.mediaTotalTooLarge }
    }
    this.entries.set(summary.id, { summary, bytes })
    return { ok: true, attachment: summary }
  }

  private addImage(
    name: string,
    bytes: Uint8Array,
    shouldCheckMspBudget: boolean,
  ): AddAttachmentResult {
    if (bytes.byteLength > MAX_IMAGE_BYTES) {
      return { ok: false, reason: UI_TEXT.attachmentTooLarge }
    }
    const info = readImageInfo(bytes)
    if (info === undefined) {
      return { ok: false, reason: UI_TEXT.attachmentUnsupported }
    }
    if (this.weight() + 1 > MODEL_API_MEDIA_PER_REQUEST) {
      return { ok: false, reason: UI_TEXT.documentsOverBudget }
    }
    if (!this.fitsMediaBytes(bytes, info.mediaType)) {
      return { ok: false, reason: UI_TEXT.mediaTotalTooLarge }
    }
    const summary: AttachmentSummary = {
      id: this.newId(),
      name,
      mediaType: info.mediaType,
      width: info.width,
      height: info.height,
      sizeBytes: bytes.byteLength,
    }
    const base64Length =
      BASE64_OUTPUT_BLOCK_CHARS * Math.ceil(bytes.byteLength / BASE64_INPUT_BLOCK_BYTES)
    const mspPartBytes =
      Buffer.byteLength(
        JSON.stringify({
          type: 'image',
          base64Data: '',
          mediaType: info.mediaType,
          width: info.width,
          height: info.height,
        }),
      ) + base64Length
    if (
      shouldCheckMspBudget &&
      this.mspAttachmentBytes() + mspPartBytes > MSP_ATTACHMENT_FRAME_BUDGET_BYTES
    ) {
      return { ok: false, reason: UI_TEXT.commandTooLarge }
    }
    this.entries.set(summary.id, { summary, bytes, mspPartBytes })
    return { ok: true, attachment: summary }
  }

  private addText(
    name: string,
    bytes: Uint8Array,
    shouldCheckMspBudget: boolean,
  ): AddAttachmentResult {
    if (bytes.byteLength > MAX_TEXT_ATTACHMENT_BYTES) {
      return { ok: false, reason: UI_TEXT.textFileTooLarge }
    }
    let content: string
    try {
      content = new TextDecoder('utf-8', { fatal: true }).decode(bytes)
    } catch {
      return { ok: false, reason: UI_TEXT.textFileInvalid }
    }
    if (hasBinaryControlCharacters(content)) {
      return { ok: false, reason: UI_TEXT.textFileInvalid }
    }
    const summary: AttachmentSummary = {
      id: this.newId(),
      name,
      mediaType: TEXT_ATTACHMENT_MEDIA_TYPE,
      sizeBytes: bytes.byteLength,
    }
    const modelText = textFileInput({
      type: 'textFile',
      name,
      mediaType: TEXT_ATTACHMENT_MEDIA_TYPE,
      sizeBytes: bytes.byteLength,
      text: content,
    })
    const modelApiTextBytes = Buffer.byteLength(modelText)
    const mspPartBytes = Buffer.byteLength(
      JSON.stringify({
        type: 'text',
        text: modelText,
      }),
    )
    if (
      shouldCheckMspBudget &&
      this.mspAttachmentBytes() + mspPartBytes > MSP_ATTACHMENT_FRAME_BUDGET_BYTES
    ) {
      return { ok: false, reason: UI_TEXT.textFilesOverBudget }
    }
    if (
      !shouldCheckMspBudget &&
      this.modelApiTextBytes() + modelApiTextBytes > MAX_MODEL_API_TEXT_ATTACHMENT_BYTES
    ) {
      return { ok: false, reason: UI_TEXT.textFilesOverModelApiBudget }
    }
    this.entries.set(summary.id, { summary, bytes, text: content, mspPartBytes, modelApiTextBytes })
    return { ok: true, attachment: summary }
  }

  /**
   * An image, or a PDF when `acceptsDocuments` (the Model API backend); the
   * caller refuses a PDF on Muse Code with its own reason first (M54).
   */
  public add(
    name: string,
    bytes: Uint8Array,
    canAcceptDocuments = false,
    canAcceptText = false,
  ): AddAttachmentResult {
    if (this.entries.size >= MAX_ATTACHMENTS_PER_MESSAGE) {
      return { ok: false, reason: UI_TEXT.attachmentLimit }
    }
    if (isPdf(bytes)) {
      return canAcceptDocuments
        ? this.addDocument(name, bytes)
        : { ok: false, reason: UI_TEXT.pdfNeedsModelApi }
    }
    if (name.toLowerCase().endsWith(PDF_EXTENSION)) {
      return { ok: false, reason: UI_TEXT.invalidPdf }
    }
    return canAcceptText && TEXT_ATTACHMENT_EXTENSIONS.has(path.extname(name).toLowerCase())
      ? this.addText(name, bytes, !canAcceptDocuments)
      : this.addImage(name, bytes, !canAcceptDocuments)
  }

  public remove(id: string): boolean {
    return this.entries.delete(id)
  }

  public clear(): void {
    this.entries.clear()
  }

  public get size(): number {
    return this.entries.size
  }

  public list(): readonly AttachmentSummary[] {
    return Array.from(this.entries.values(), (entry) => entry.summary)
  }

  /**
   * Image and document parts for the given ids (unknown ids are skipped).
   * They stay until `release`: a message the host refused keeps them for
   * another try.
   */
  public partsFor(ids: readonly string[]): readonly TurnPart[] {
    const parts: TurnPart[] = []
    for (const id of ids) {
      const entry = this.entries.get(id)
      if (entry === undefined) {
        continue
      }
      const { summary } = entry
      if (entry.text !== undefined) {
        parts.push({
          type: 'textFile',
          name: summary.name,
          mediaType: summary.mediaType,
          sizeBytes: summary.sizeBytes,
          text: entry.text,
        })
        continue
      }
      const base64Data = Buffer.from(entry.bytes).toString('base64')
      parts.push(
        summary.width === undefined || summary.height === undefined
          ? {
              type: 'file',
              base64Data,
              mediaType: summary.mediaType,
              name: summary.name,
              sizeBytes: summary.sizeBytes,
              pageCount: summary.pageCount,
            }
          : {
              type: 'image',
              base64Data,
              mediaType: summary.mediaType,
              width: summary.width,
              height: summary.height,
            },
      )
    }
    return parts
  }

  /** The message carrying these attachments was accepted: they are gone from the composer. */
  public release(ids: readonly string[]): void {
    for (const id of ids) {
      this.entries.delete(id)
    }
  }
}

src/core/backends/modelapi/client.ts:
// A thin, schema-validated client for the four Model API endpoints the
// backend uses (PLAN.md D2): `GET /models`, `POST /responses/input_tokens`,
// the streamed `POST /responses` and `POST /images/generations` (M34).
// Errors follow the documented envelope and retry policy
// (dev.meta.ai/docs/error-handling): 429 / 500 / 503 are
// retried with exponential backoff and jitter, honouring `Retry-After`,
// before any of the response has been read; everything else surfaces as a
// `ModelApiError`. `fetch`, the clock and the key are injected.

import { createHash } from 'node:crypto'

import {
  MODEL_API_MAX_RETRIES,
  HTTP_TOO_MANY_REQUESTS,
  IMAGE_REQUEST_TIMEOUT_MS,
  MODEL_API_RETRY_BASE_MS,
  MODEL_API_RETRY_JITTER_MS,
  MODEL_API_RETRY_MAX_MS,
  MODEL_API_RETRYABLE_STATUSES,
  MODEL_API_REQUEST_TIMEOUT_MS,
  MODEL_API_STREAM_IDLE_MS,
  MILLISECONDS_PER_SECOND,
  UI_TEXT,
} from '../../../shared/constants'
import { fill } from '../../../shared/l10n/text'
import { DeadlineError, withDeadline } from '../../timeouts'
import type { CoreLogger } from '../../logging'
import {
  describeNetworkFailure,
  type NetworkAdvice,
  networkFailureMessage,
} from '../../networkFailure'
import {
  type CreateImageBody,
  type EditImageBody,
  type CreateResponseBody,
  errorBodySchema,
  eventTypeSchema,
  type ImagesResponse,
  imagesResponseSchema,
  inputTokensSchema,
  modelListSchema,
  type StreamEvent,
  streamEventSchema,
} from './schemas'
import { parseSse } from './sse'

export interface ModelApiClientDeps {
  readonly fetch: typeof fetch
  readonly baseUrl: string
  /** Read per request so a key pasted later applies without a restart. */
  readonly apiKey: () => Promise<string | undefined>
  readonly sleep: (ms: number) => Promise<void>
  /** Epoch ms, for a `Retry-After` given as a date. */
  readonly now: () => number
  /** 0 ≤ n < 1, for the retry jitter; injected so tests are deterministic. */
  readonly random: () => number
  readonly log: CoreLogger
  /** How long a reply stream may send nothing; the constant unless a test shortens it. */
  readonly streamIdleMs?: number
  /**
   * Whose settings a request that never reached Meta names (M56): VS Code's
   * unless the ACP agent says its own (PLAN.md D62, Q66).
   */
  readonly networkAdvice?: NetworkAdvice
}

export class ModelApiError extends Error {
  public constructor(
    message: string,
    /** HTTP status, or 0 when the request never got a response. */
    public readonly status: number,
    /** The envelope's `error.type` (`rate_limit_error`, …), when any. */
    public readonly kind: string | undefined,
    /** The envelope's `error.code` (`invalid_api_key`, …), when any. */
    public readonly code: string | undefined,
  ) {
    super(message)
    this.name = 'ModelApiError'
  }
}

/** Thrown when the key is absent: the caller decides how to prompt. */
export class MissingApiKeyError extends Error {
  public constructor() {
    super('No Model API key is stored')
    this.name = 'MissingApiKeyError'
  }
}

const JSON_MEDIA_TYPE = 'application/json'
const EVENT_STREAM_MEDIA_TYPE = 'text/event-stream'
const RETRY_AFTER_HEADER = 'retry-after'
const NETWORK_FAILURE_STATUS = 0
const SSE_DONE_SENTINEL = '[DONE]'

/** Closing a parser that already failed rejects with that failure, which the stream reported. */
function ignoreClosingError(): void {
  // Nothing to add: the stream's own error already went to its caller.
}

/** The documented error envelope, or the status text when the body is not one. */
async function describeFailure(response: Response): Promise<ModelApiError> {
  let body: unknown
  try {
    body = await response.json()
  } catch {
    body = undefined
  }
  const parsed = errorBodySchema.safeParse(body)
  if (!parsed.success) {
    return new ModelApiError(
      `HTTP ${String(response.status)} ${response.statusText}`.trim(),
      response.status,
      undefined,
      undefined,
    )
  }
  const { error } = parsed.data
  return new ModelApiError(
    error.message,
    response.status,
    error.type ?? undefined,
    error.code ?? undefined,
  )
}

/**
 * `Retry-After` in milliseconds: a delay in seconds, or an HTTP date (RFC
 * 9110 §10.2.3 allows both; PLAN.md D25), measured from `now`.
 */
export function retryAfterMs(header: string | null, now: number): number | undefined {
  if (header === null || header.trim() === '') {
    return undefined
  }
  const seconds = Number(header)
  if (Number.isFinite(seconds)) {
    return seconds >= 0 ? seconds * MILLISECONDS_PER_SECOND : undefined
  }
  const at = Date.parse(header)
  return Number.isNaN(at) ? undefined : Math.max(at - now, 0)
}

/** One retry the client is about to make, for the transcript's notice. */
export interface RetryNotice {
  readonly attempt: number
  readonly maxAttempts: number
  readonly delayMs: number
  readonly reason: string
}

/**
 * The retries one model call has used (the review of PR #28): a stream sent
 * again whole and the HTTP retries inside each of its requests draw on the
 * same MODEL_API_MAX_RETRIES.
 */
export interface RetryBudget {
  retriesUsed: number
}

/** In-memory identity of an explicitly confirmed scheduled Model API run. */
export interface ConfirmedModelRequest {
  readonly modelId: string
  readonly keyDigest: string
  /** The paid gate and session model must still match before every HTTP try. */
  readonly isStillAllowed: () => boolean
  /** Only after identity and gate checks, immediately before the first HTTP try. */
  readonly onRequestStarted: () => void
}

/** Owned synchronous admission and attempt observation; no fields cross the HTTP wire. */
export interface ResponseAttemptGuard {
  (keyDigest: string | undefined): void
  /** After every final fence and request build, adjacent to the actual fetch call. */
  readonly onRequestStarted?: () => void
}

function isAborted(signal: AbortSignal | undefined): boolean {
  return signal?.aborted === true
}

/** Rejects as soon as `signal` aborts, instead of sleeping the retry delay out. */
function whenAborted(signal: AbortSignal): { readonly promise: Promise<never>; dispose(): void } {
  let onAbort: (() => void) | undefined
  const promise = new Promise<never>((_resolve, reject) => {
    onAbort = () => {
      reject(new ModelApiError('cancelled', NETWORK_FAILURE_STATUS, undefined, undefined))
    }
    signal.addEventListener('abort', onAbort, { once: true })
  })
  return {
    promise,
    dispose: () => {
      if (onAbort !== undefined) {
        signal.removeEventListener('abort', onAbort)
      }
    },
  }
}

export class ModelApiClient {
  /** Stream event types already logged as ignored (M39). */
  private readonly ignoredEventTypes = new Set<string>()

  public constructor(private readonly deps: ModelApiClientDeps) {}

  /** The retry delay, cut short by the turn's Stop. */
  private async pause(ms: number, signal: AbortSignal | undefined): Promise<void> {
    if (signal === undefined) {
      await this.deps.sleep(ms)
      return
    }
    if (signal.aborted) {
      throw new ModelApiError('cancelled', NETWORK_FAILURE_STATUS, undefined, undefined)
    }
    const aborted = whenAborted(signal)
    try {
      await Promise.race([this.deps.sleep(ms), aborted.promise])
    } finally {
      aborted.dispose()
    }
  }

  private async headers(): Promise<{
    readonly values: Record<string, string>
    readonly keyDigest: string
  }> {
    const key = await this.deps.apiKey()
    if (key === undefined) {
      throw new MissingApiKeyError()
    }
    return {
      values: { Authorization: `Bearer ${key}`, 'Content-Type': JSON_MEDIA_TYPE },
      keyDigest: createHash('sha256').update(key).digest('hex'),
    }
  }

  private backoffMs(attempt: number, suggestedMs: number | undefined): number {
    const exponential = Math.min(MODEL_API_RETRY_BASE_MS * 2 ** attempt, MODEL_API_RETRY_MAX_MS)
    const jitter = Math.floor(this.deps.random() * MODEL_API_RETRY_JITTER_MS)
    return Math.min((suggestedMs ?? exponential) + jitter, MODEL_API_RETRY_MAX_MS)
  }

  /**
   * One request with the documented retry policy. The response is handed
   * back unread on success; a non-2xx status becomes a `ModelApiError`.
   */
  private async request(
    path: string,
    init: {
      readonly method: 'GET' | 'POST'
      readonly body?: unknown
      readonly accept: string
      /**
       * `rateLimitOnly` for a request that bills per call (M34, the review
       * of PR #27): a 429 was refused before any work and is retried; a
       * lost connection or a server error may have been done and billed,
       * so it is not.
       */
      readonly retries?: 'all' | 'rateLimitOnly'
    },
    signal: AbortSignal | undefined,
    onRetry?: (notice: RetryNotice) => void,
    budget?: RetryBudget,
    admitAttempt?: ResponseAttemptGuard,
    confirmed?: ConfirmedModelRequest,
  ): Promise<Response> {
    const isRateLimitOnly = init.retries === 'rateLimitOnly'
    const fixedHeaders =
      admitAttempt === undefined && confirmed === undefined ? await this.headers() : undefined
    const url = `${this.deps.baseUrl}${path}`
    const retry = async (attempt: number, delay: number, reason: string) => {
      if (budget !== undefined) {
        budget.retriesUsed = attempt + 1
      }
      onRetry?.({
        attempt: attempt + 1,
        maxAttempts: MODEL_API_MAX_RETRIES + 1,
        delayMs: delay,
        reason,
      })
      await this.pause(delay, signal)
    }
    // How long the answer took, retries included, at trace level (M39).
    const startedAt = this.deps.now()
    for (let attempt = budget?.retriesUsed ?? 0; ; attempt += 1) {
      let credentials: Awaited<ReturnType<ModelApiClient['headers']>>
      try {
        credentials = fixedHeaders ?? (await this.headers())
      } catch (error: unknown) {
        if (isAborted(signal)) {
          throw new ModelApiError('cancelled', NETWORK_FAILURE_STATUS, undefined, undefined)
        }
        if (error instanceof MissingApiKeyError) {
          admitAttempt?.(undefined)
        }
        throw error
      }
      if (isAborted(signal)) {
        throw new ModelApiError('cancelled', NETWORK_FAILURE_STATUS, undefined, undefined)
      }
      if (
        confirmed !== undefined &&
        (credentials.keyDigest !== confirmed.keyDigest || !confirmed.isStillAllowed())
      ) {
        throw new Error(UI_TEXT.scheduleConfirmationExpired)
      }
      // Local consent refusal is outside the transport retry catch: it never
      // becomes another billable attempt.
      admitAttempt?.(credentials.keyDigest)
      if (isAborted(signal)) {
        throw new ModelApiError('cancelled', NETWORK_FAILURE_STATUS, undefined, undefined)
      }
      if (confirmed !== undefined && !confirmed.isStillAllowed()) {
        throw new Error(UI_TEXT.scheduleConfirmationExpired)
      }
      const headers = { ...credentials.values, Accept: init.accept }
      const requestInit: RequestInit = {
        method: init.method,
        headers,
        ...(init.body !== undefined && { body: JSON.stringify(init.body) }),
        ...(signal !== undefined && { signal }),
      }
      confirmed?.onRequestStarted()
      admitAttempt?.onRequestStarted?.()
      let response: Response
      try {
        response = await this.deps.fetch(url, requestInit)
      } catch (error: unknown) {
        if (error instanceof ModelApiError || signal?.aborted === true) {
          throw error instanceof ModelApiError
            ? error
            : new ModelApiError(
                error instanceof Error ? error.message : String(error),
                NETWORK_FAILURE_STATUS,
                undefined,
                undefined,
              )
        }
        // Never reached the server: its causes say why, and the message
        // names the setting or store to check (M56, PLAN.md D43).
        const reason = networkFailureMessage(error, this.deps.networkAdvice)
        if (isRateLimitOnly || attempt >= MODEL_API_MAX_RETRIES) {
          throw new ModelApiError(reason, NETWORK_FAILURE_STATUS, undefined, undefined)
        }
        const delay = this.backoffMs(attempt, undefined)
        this.deps.log.warn(
          `Model API request failed to send (${describeNetworkFailure(error).detail}); retrying in ${String(delay)} ms`,
        )
        await retry(attempt, delay, reason)
        continue
      }
      if (response.ok) {
        this.deps.log.trace(
          `Model API ${init.method} ${path} answered ${String(response.status)} in ${String(this.deps.now() - startedAt)} ms`,
        )
        return response
      }
      const failure = await describeFailure(response)
      const isRetryable = isRateLimitOnly
        ? response.status === HTTP_TOO_MANY_REQUESTS
        : MODEL_API_RETRYABLE_STATUSES.has(response.status)
      if (!isRetryable || attempt >= MODEL_API_MAX_RETRIES) {
        throw failure
      }
      const delay = this.backoffMs(
        attempt,
        retryAfterMs(response.headers.get(RETRY_AFTER_HEADER), this.deps.now()),
      )
      this.deps.log.warn(
        `Model API answered ${String(response.status)} (${failure.message}); retrying in ${String(delay)} ms`,
      )
      await retry(attempt, delay, `HTTP ${String(response.status)}: ${failure.message}`)
    }
  }

  /** A billed image request: only a 429 is retried, with a deadline of its own. */
  private async imageRequest(
    path: string,
    body: CreateImageBody,
    signal: AbortSignal,
    admitAttempt?: ResponseAttemptGuard,
  ): Promise<ImagesResponse> {
    const response = await this.request(
      path,
      { method: 'POST', body, accept: JSON_MEDIA_TYPE, retries: 'rateLimitOnly' },
      AbortSignal.any([signal, AbortSignal.timeout(IMAGE_REQUEST_TIMEOUT_MS)]),
      undefined,
      undefined,
      admitAttempt,
    )
    return imagesResponseSchema.parse(await response.json())
  }

  /** Bind a one-use child consent to the stored key without retaining it. */
  public async currentKeyDigest(): Promise<string> {
    const credentials = await this.headers()
    return credentials.keyDigest
  }

  /** The wait before retry number `attempt` (0-based): the same backoff and jitter as a request's. */
  public retryDelayMs(attempt: number): number {
    return this.backoffMs(attempt, undefined)
  }

  /** Waits `ms`, or rejects as soon as the turn's Stop aborts `signal`. */
  public async waitBeforeRetry(ms: number, signal: AbortSignal): Promise<void> {
    await this.pause(ms, signal)
  }

  /** The chat model ids the key can use, as the catalogue lists them. */
  public async listModels(): Promise<readonly string[]> {
    // No turn to stop it: a deadline instead, so a panel never waits for ever (D25).
    const response = await this.request(
      '/models',
      { method: 'GET', accept: JSON_MEDIA_TYPE },
      AbortSignal.timeout(MODEL_API_REQUEST_TIMEOUT_MS),
    )
    const parsed = modelListSchema.parse(await response.json())
    return parsed.data.map((model) => model.id)
  }

  /** Tokens the rendered input would occupy; not billed (dev.meta.ai/docs/token-counting). */
  public async countInputTokens(body: Omit<CreateResponseBody, 'stream'>): Promise<number> {
    const response = await this.request(
      '/responses/input_tokens',
      { method: 'POST', body, accept: JSON_MEDIA_TYPE },
      AbortSignal.timeout(MODEL_API_REQUEST_TIMEOUT_MS),
    )
    return inputTokensSchema.parse(await response.json()).input_tokens
  }

  /**
   * One generated image (M34): `POST /images/generations`, validated. Billed
   * per image returned; a failed or filtered one is not. The turn's Stop and
   * a deadline of its own end the wait.
   */
  public async createImage(
    body: CreateImageBody,
    signal: AbortSignal,
    admitAttempt?: ResponseAttemptGuard,
  ): Promise<ImagesResponse> {
    return await this.imageRequest('/images/generations', body, signal, admitAttempt)
  }

  /** One edited image (M44): `POST /images/edits`, billed and retried as a generation is. */
  public async editImage(
    body: EditImageBody,
    signal: AbortSignal,
    admitAttempt?: ResponseAttemptGuard,
  ): Promise<ImagesResponse> {
    return await this.imageRequest('/images/edits', body, signal, admitAttempt)
  }

  /**
   * The streamed response as validated events. Unknown event types are
   * skipped; a malformed known one or a non-JSON frame ends the stream with
   * an error, since the reply can no longer be trusted.
   */
  public async *streamResponse(
    body: CreateResponseBody,
    signal: AbortSignal,
    onRetry?: (notice: RetryNotice) => void,
    budget?: RetryBudget,
    admitAttempt?: ResponseAttemptGuard,
    confirmed?: ConfirmedModelRequest,
  ): AsyncGenerator<StreamEvent> {
    if (
      confirmed !== undefined &&
      (body.model !== confirmed.modelId || !confirmed.isStillAllowed())
    ) {
      throw new Error(UI_TEXT.scheduleConfirmationExpired)
    }
    // Nothing from the server for this long, headers or a frame, ends the
    // turn (M39); the request is aborted too, which frees the connection.
    const idleMs = this.deps.streamIdleMs ?? MODEL_API_STREAM_IDLE_MS
    const stalled = fill(UI_TEXT.modelApiStalled, {
      seconds: Math.round(idleMs / MILLISECONDS_PER_SECOND),
    })
    const stall = new AbortController()
    const within = async <T>(waiting: Promise<T>): Promise<T> => {
      try {
        return await withDeadline(waiting, idleMs, stalled)
      } catch (error: unknown) {
        if (error instanceof DeadlineError) {
          stall.abort()
          throw new ModelApiError(stalled, NETWORK_FAILURE_STATUS, undefined, undefined)
        }
        throw error
      }
    }
    const response = await within(
      this.request(
        '/responses',
        { method: 'POST', body, accept: EVENT_STREAM_MEDIA_TYPE },
        AbortSignal.any([signal, stall.signal]),
        onRetry,
        budget,
        admitAttempt,
        confirmed,
      ),
    )
    if (response.body === null) {
      throw new ModelApiError('The response had no body', response.status, undefined, undefined)
    }
    const frames = parseSse(response.body)[Symbol.asyncIterator]()
    try {
      for (;;) {
        const next = await within(frames.next())
        if (next.done === true) {
          return
        }
        const frame = next.value
        // OpenAI-style streams end with `data: [DONE]`; a keep-alive may carry no
        // data. Neither is an event (D26).
        if (frame.data.trim() === '' || frame.data === SSE_DONE_SENTINEL) {
          continue
        }
        let json: unknown
        try {
          json = JSON.parse(frame.data)
        } catch {
          throw new ModelApiError(
            // Its length, not its text: the frame is model output, and this
            // message becomes the failed turn's reason in the log (M39).
            `Malformed stream frame (${String(frame.data.length)} characters)`,
            response.status,
            undefined,
            undefined,
          )
        }
        const known = streamEventSchema.safeParse(json)
        if (known.success) {
          yield known.data
          continue
        }
        const typed = eventTypeSchema.safeParse(json)
        if (!typed.success) {
          throw new ModelApiError(
            'Stream frame without a type',
            response.status,
            undefined,
            undefined,
          )
        }
        // Once a type, not once a frame (M39).
        if (this.ignoredEventTypes.has(typed.data.type)) {
          continue
        }
        this.ignoredEventTypes.add(typed.data.type)
        this.deps.log.info(`Model API stream events of type ${typed.data.type} are ignored`)
      }
    } finally {
      // An early end (a malformed frame, a stall, the caller stopping)
      // closes the parser, which releases the response body (the review of
      // PR #20). Not awaited: after a stall its last read may never settle.
      void frames.return(undefined).catch(ignoreClosingError)
    }
  }
}

