// Local scheduled prompts for the Model API backend (PLAN.md M52). Parsing and
// next-fire calculation are pure. The host owns persistence and admission;
// nothing in this module sends a model request.

import {
  CRON_FIELD_COUNT,
  CRON_FIELD_SEGMENT_LIMIT,
  CRON_MAX_DAY,
  CRON_MAX_HOUR,
  CRON_MAX_MINUTE,
  CRON_MAX_MONTH,
  CRON_MAX_WEEKDAY,
  MILLISECONDS_PER_DAY,
  SCHEDULE_DEFAULT_INTERVAL_MS,
  SCHEDULE_MAX_INTERVAL_MS,
  SCHEDULE_MAX_PROMPT_CHARS,
  SCHEDULE_MIN_INTERVAL_MS,
} from '../../../shared/constants'
import type { ScheduleCadence } from '../../../shared/schedule'

export type LoopCommand =
  | { readonly verb: 'create'; readonly cadence: ScheduleCadence; readonly prompt: string }
  | { readonly verb: 'list' }
  | { readonly verb: 'cancel'; readonly id: string }

export type LoopParseResult =
  | { readonly ok: true; readonly command: LoopCommand }
  | { readonly ok: false; readonly reason: 'empty' | 'badCadence' | 'badPrompt' | 'badId' }

const LOOP_PREFIX = /^\/loop(?:\s+([\s\S]*))?$/i
const INTERVAL = /^(\d+)([mhd])$/i
const QUOTED_CRON = /^"([^"]+)"(?:\s+([\s\S]*))?$/
const FIRST_WORD = /^(\S+)(?:\s+([\s\S]*))?$/
const JOB_ID = /^[A-Za-z0-9_-]+$/
const MINUTES_PER_HOUR = 60
const HOURS_PER_DAY = 24
const MINUTE_MS = MILLISECONDS_PER_DAY / (HOURS_PER_DAY * MINUTES_PER_HOUR)
const HOUR_MS = MILLISECONDS_PER_DAY / HOURS_PER_DAY
const INTERVAL_UNITS: Readonly<Record<string, number>> = {
  m: MINUTE_MS,
  h: HOUR_MS,
  d: MILLISECONDS_PER_DAY,
}

interface CronField {
  readonly values: ReadonlySet<number>
  readonly isWildcard: boolean
}

interface ParsedCron {
  readonly minute: CronField
  readonly hour: CronField
  readonly day: CronField
  readonly month: CronField
  readonly weekday: CronField
}

function cronField(
  source: string,
  low: number,
  high: number,
  isWeekday = false,
): CronField | undefined {
  const values = new Set<number>()
  for (const segment of source.split(',')) {
    const [base, stepText, extra] = segment.split('/', CRON_FIELD_SEGMENT_LIMIT)
    if (
      base === undefined ||
      extra !== undefined ||
      (stepText !== undefined && !/^\d+$/.test(stepText))
    ) {
      return undefined
    }
    const step = stepText === undefined ? 1 : Number(stepText)
    if (!Number.isSafeInteger(step) || step < 1) {
      return undefined
    }
    let start: number
    let end: number
    if (base === '*') {
      start = low
      end = high
    } else {
      const range = /^(\d+)(?:-(\d+))?$/.exec(base)
      if (range === null) {
        return undefined
      }
      start = Number(range[1])
      end = range[2] === undefined ? (stepText === undefined ? start : high) : Number(range[2])
    }
    if (start < low || end > high || start > end) {
      return undefined
    }
    for (let value = start; value <= end; value += step) {
      values.add(isWeekday && value === CRON_MAX_WEEKDAY ? 0 : value)
    }
  }
  return values.size === 0 ? undefined : { values, isWildcard: source.includes('*') }
}

function parsedCron(expression: string): ParsedCron | undefined {
  const parts = expression.trim().split(/\s+/)
  if (parts.length !== CRON_FIELD_COUNT) {
    return undefined
  }
  const minute = cronField(parts[0] ?? '', 0, CRON_MAX_MINUTE)
  const hour = cronField(parts[1] ?? '', 0, CRON_MAX_HOUR)
  const day = cronField(parts[2] ?? '', 1, CRON_MAX_DAY)
  const month = cronField(parts[3] ?? '', 1, CRON_MAX_MONTH)
  const weekday = cronField(parts[4] ?? '', 0, CRON_MAX_WEEKDAY, true)
  return minute === undefined ||
    hour === undefined ||
    day === undefined ||
    month === undefined ||
    weekday === undefined
    ? undefined
    : { minute, hour, day, month, weekday }
}

function isCronMatch(cron: ParsedCron, date: Date): boolean {
  const isDay = cron.day.values.has(date.getDate())
  const isWeekday = cron.weekday.values.has(date.getDay())
  // Cron ORs these fields only when neither contains '*'. A step such as
  // '*/2' still has to match its own values when the fields are ANDed.
  const isDayMatch =
    cron.day.isWildcard || cron.weekday.isWildcard ? isDay && isWeekday : isDay || isWeekday
  return (
    cron.minute.values.has(date.getMinutes()) &&
    cron.hour.values.has(date.getHours()) &&
    cron.month.values.has(date.getMonth() + 1) &&
    isDayMatch
  )
}

/** First matching local-time minute after `afterMs`, bounded by expiry. */
function nextCronFire(
  expression: string,
  afterMs: number,
  expiresAtMs: number,
): number | undefined {
  const cron = parsedCron(expression)
  if (cron === undefined) {
    return undefined
  }
  const start = Math.floor(afterMs / MINUTE_MS) * MINUTE_MS + MINUTE_MS
  for (let time = start; time < expiresAtMs; time += MINUTE_MS) {
    if (isCronMatch(cron, new Date(time))) {
      return time
    }
  }
  return undefined
}

/** Returns next eligible occurrence; no backlog or replay of missed intervals. */
export function nextScheduleFire(
  cadence: ScheduleCadence,
  afterMs: number,
  expiresAtMs: number,
): number | undefined {
  if (cadence.kind === 'cron') {
    return nextCronFire(cadence.expression, afterMs, expiresAtMs)
  }
  const next = afterMs + cadence.everyMs
  return next < expiresAtMs ? next : undefined
}

/** A local `/loop` command; undefined when the text is an ordinary prompt. */
export function parseLoopPrompt(text: string): LoopParseResult | undefined {
  const match = LOOP_PREFIX.exec(text.trim())
  if (match === null) {
    return undefined
  }
  const body = (match[1] ?? '').trim()
  if (body === '') {
    return { ok: false, reason: 'empty' }
  }
  if (body.toLowerCase() === 'list') {
    return { ok: true, command: { verb: 'list' } }
  }
  if (/^cancel(?:\s|$)/i.test(body)) {
    const id = body.slice('cancel'.length).trim()
    return JOB_ID.test(id)
      ? { ok: true, command: { verb: 'cancel', id } }
      : { ok: false, reason: 'badId' }
  }
  const quoted = QUOTED_CRON.exec(body)
  if (quoted === null && body.startsWith('"')) {
    return { ok: false, reason: 'badCadence' }
  }
  const words = FIRST_WORD.exec(body)
  const interval = words === null ? null : INTERVAL.exec(words[1] ?? '')
  let cadence: ScheduleCadence
  let prompt: string
  if (quoted !== null) {
    cadence = { kind: 'cron', expression: quoted[1] ?? '' }
    prompt = (quoted[2] ?? '').trim()
    if (parsedCron(cadence.expression) === undefined) {
      return { ok: false, reason: 'badCadence' }
    }
  } else if (interval === null) {
    cadence = { kind: 'interval', everyMs: SCHEDULE_DEFAULT_INTERVAL_MS }
    prompt = body
  } else {
    const unit = INTERVAL_UNITS[(interval[2] ?? '').toLowerCase()]
    const everyMs = Number(interval[1]) * (unit ?? 0)
    if (
      !Number.isSafeInteger(everyMs) ||
      everyMs < SCHEDULE_MIN_INTERVAL_MS ||
      everyMs > SCHEDULE_MAX_INTERVAL_MS
    ) {
      return { ok: false, reason: 'badCadence' }
    }
    cadence = { kind: 'interval', everyMs }
    prompt = (words?.[2] ?? '').trim()
  }
  return prompt === '' || prompt.length > SCHEDULE_MAX_PROMPT_CHARS
    ? { ok: false, reason: 'badPrompt' }
    : { ok: true, command: { verb: 'create', cadence, prompt } }
}

// What a Model API session is when the window is gone (PLAN.md D14): the
// replayed conversation, the transcript, the patches behind Open diff and
// Revert, and the row the history list shows. The host keeps one file per
// session (host/backend/fileSessionStore.ts); this module is the shape,
// its validation, and the store interface the host implements. Pure.

import * as z from 'zod/mini'
import {
  type ItemSnapshot,
  itemSnapshotFields,
  type TodoItem,
  todoItemSchema,
} from '../../../shared/agentEvents'
import {
  AGENT_SOURCES,
  EFFORT_LEVELS,
  PERMISSION_MODES,
  STORED_SESSION_VERSION,
} from '../../../shared/constants'
import { APPROVAL_MODES, type ApprovalMode } from '../../../shared/permissionModes'
import type { AgentRuntime } from '../../context/customAgents'
import type { SessionRecord } from '../../agent/agentBackend'
import { type GoalRecord, goalRecordSchema } from './goalRecord'
import type { SessionBudgetJournal } from './sessionBudget'
import {
  functionCallItemSchema,
  type InputItem,
  MESSAGE_PHASES,
  reasoningItemSchema,
  webSearchActionSchema,
} from './schemas'

export interface StoredReplayItem {
  readonly turnId: string
  readonly item: InputItem
  /** The transcript user card that supplied this exact replay message (M53). */
  readonly userMessageId?: string
  /** Identifies a background task's terminal model note across fork cuts. */
  readonly backgroundTaskId?: string
}

export interface StoredTranscriptItem {
  readonly turnId: string
  readonly item: ItemSnapshot
}

export interface StoredUsage {
  readonly inputTokens: number
  readonly outputTokens: number
  readonly cachedTokens: number
  readonly reasoningTokens: number
}

export interface StoredChild {
  readonly id: string
  readonly role: string
  readonly objective: string
  readonly itemId: string
  readonly parentTurnId: string
  readonly checkpointRecording?: boolean | undefined
  readonly startedAt: number
  readonly state: 'queued' | 'running' | 'interrupted' | 'result_ready' | 'closed'
  readonly result?: {
    readonly summary: string
    readonly text?: string
    readonly errorKind?: string
  }
  readonly terminal?: string
  /** The file policy's revision at the spawn (M78): its results reach the parent only under it. */
  readonly policyRevision?: string
  readonly pendingMessages: readonly string[]
  readonly session: StoredSession
}

/**
 * A completed child's result not yet in a request, with the file policy's
 * revision its child ran under (M78). Plain text is a result saved before
 * revisions were: it is withheld.
 */
export type StoredPendingChildResult =
  string | { readonly childId: string; readonly text: string; readonly policyRevision?: string }

/** One session on disk. Optional fields are absent, never null. */
export interface StoredSession {
  readonly version: typeof STORED_SESSION_VERSION
  readonly sessionId: string
  /** SHA-256 digest of the owning Model API key; absent on legacy files. */
  readonly accountId?: string
  readonly sideChat?: boolean
  /**
   * Built from an imported session-export file (M84, PLAN.md D49), or forked
   * from one: its history is untrusted, so it starts asking whenever it is
   * opened.
   */
  readonly imported?: true
  readonly workspaceRoot: string
  readonly modelId: string
  readonly approvalMode: ApprovalMode
  readonly effort: string
  /**
   * A custom agent's narrowed run (M76): present on a child spawned with an
   * agent, so a resume or fork keeps its prompt, tools and ceiling. Absent
   * on parents, plain children, and sessions saved before M76's review.
   */
  readonly agent?: AgentRuntime
  readonly name?: string
  readonly createdAt: string
  readonly lastActivityAt: string
  readonly turnIds: readonly string[]
  /** Last completed turn covered by the accepted compaction summary (M53). */
  readonly compactedThroughTurnId?: string
  readonly forkedFrom?: string
  readonly firstPrompt?: string
  readonly todos: readonly TodoItem[]
  /** The session goal (M45, PLAN.md D38); absent when there is none. */
  readonly goal?: GoalRecord
  readonly replay: readonly StoredReplayItem[]
  readonly transcript: readonly StoredTranscriptItem[]
  /** Patch documents by output reference (`tool_patch-<itemId>`). */
  readonly outputs: Readonly<Record<string, string>>
  readonly usage: StoredUsage
  /** Dollars the session's own requests spent (M82); absent when none. */
  readonly budgetSpentUsd?: number
  /** Controlled first fork snapshot: copied history predates this conversation's zero spend. */
  readonly budgetIsFreshFork?: true
  /**
   * Observation packing's ledger (M73): the estimated tokens packed sends
   * left out. Absent where the session never packed, and in a file saved
   * before the ledger was kept, which resumes at zero.
   */
  readonly packedTokensAvoided?: number
  /** Children are nested in the parent's file; they do not appear in History. */
  readonly children?: readonly StoredChild[]
  /** Completed children whose results have not entered the next model request. */
  readonly pendingChildResults?: readonly StoredPendingChildResult[]
  readonly spawnCommands?: Readonly<Record<string, string>>
}

/**
 * What the history list needs of a stored session, without its conversation
 * (PLAN.md D26): a window keeps these in memory and loads a session whole
 * only when it is resumed, forked or read.
 */
export interface StoredSessionHeader {
  readonly sessionId: string
  readonly accountId?: string
  readonly sideChat?: boolean
  readonly workspaceRoot: string
  readonly name?: string
  readonly createdAt: string
  readonly lastActivityAt: string
  readonly forkedFrom?: string
  readonly firstPrompt?: string
  readonly turnCount: number
}

/** Where sessions live between windows; the host supplies the files. */
export interface SessionStore {
  /** Shared request liabilities and spend; required for a finite cap. */
  readonly budget?: SessionBudgetJournal
  /** Every readable session's header; a corrupt file is skipped (and logged), never fatal. */
  list(): Promise<readonly StoredSessionHeader[]>
  /** One session in full; undefined when it is gone or no longer reads. */
  load(sessionId: string): Promise<StoredSession | undefined>
  save(session: StoredSession): Promise<void>
  remove(sessionId: string): Promise<void>
}

export function headerOf(stored: StoredSession): StoredSessionHeader {
  return {
    sessionId: stored.sessionId,
    ...(stored.accountId !== undefined && { accountId: stored.accountId }),
    ...(stored.sideChat === true && { sideChat: true }),
    workspaceRoot: stored.workspaceRoot,
    ...(stored.name !== undefined && { name: stored.name }),
    createdAt: stored.createdAt,
    lastActivityAt: stored.lastActivityAt,
    ...(stored.forkedFrom !== undefined && { forkedFrom: stored.forkedFrom }),
    ...(stored.firstPrompt !== undefined && { firstPrompt: stored.firstPrompt }),
    turnCount: stored.turnIds.length,
  }
}

const inputTextPartSchema = z.object({ type: z.literal('input_text'), text: z.string() })
const inputImagePartSchema = z.object({
  type: z.literal('input_image'),
  image_url: z.string(),
  detail: z.literal('auto'),
})
// A PDF the conversation carries (M54): replayed as it went, so its bytes stay with the session.
const inputFilePartSchema = z.object({
  type: z.literal('input_file'),
  filename: z.string(),
  file_data: z.string(),
})
const outputTextPartSchema = z.object({ type: z.literal('output_text'), text: z.string() })
const inputMessageSchema = z.object({
  type: z.literal('message'),
  role: z.enum(['user', 'assistant', 'developer']),
  phase: z.optional(z.enum(MESSAGE_PHASES)),
  content: z.array(
    z.union([inputTextPartSchema, inputImagePartSchema, inputFilePartSchema, outputTextPartSchema]),
  ),
})
const functionCallOutputSchema = z.object({
  type: z.literal('function_call_output'),
  call_id: z.string(),
  // Content parts when an MCP tool returned pictures (M50).
  output: z.union([z.string(), z.array(z.union([inputTextPartSchema, inputImagePartSchema]))]),
})
const webSearchCallReplaySchema = z.object({
  type: z.literal('web_search_call'),
  id: z.optional(z.string()),
  status: z.string(),
  action: z.optional(webSearchActionSchema),
})
const storedInputItemSchema = z.union([
  inputMessageSchema,
  functionCallOutputSchema,
  functionCallItemSchema,
  reasoningItemSchema,
  webSearchCallReplaySchema,
])

const storedUsageSchema = z.object({
  inputTokens: z.number().check(z.nonnegative()),
  outputTokens: z.number().check(z.nonnegative()),
  cachedTokens: z.number().check(z.nonnegative()),
  reasoningTokens: z.number().check(z.nonnegative()),
})

const storedSessionFields = {
  version: z.literal(STORED_SESSION_VERSION),
  sessionId: z.string(),
  // Legacy sessions remain readable for retention, but are never admitted.
  accountId: z.optional(z.string().check(z.regex(/^[a-f0-9]{64}$/))),
  sideChat: z.optional(z.boolean()),
  imported: z.optional(z.literal(true)),
  workspaceRoot: z.string(),
  modelId: z.string(),
  approvalMode: z.enum(APPROVAL_MODES),
  effort: z.string(),
  // Optional, so a session saved before M76's review still reads.
  agent: z.optional(
    z.object({
      id: z.string(),
      source: z.enum(AGENT_SOURCES),
      prompt: z.string(),
      toolAllowlist: z.optional(z.array(z.string())),
      effort: z.enum(EFFORT_LEVELS),
      approvalMode: z.optional(z.enum(APPROVAL_MODES)),
      permissionMode: z.optional(z.enum(PERMISSION_MODES)),
    }),
  ),
  name: z.optional(z.string()),
  createdAt: z.string(),
  lastActivityAt: z.string(),
  turnIds: z.array(z.string()),
  compactedThroughTurnId: z.optional(z.string()),
  forkedFrom: z.optional(z.string()),
  firstPrompt: z.optional(z.string()),
  todos: z.array(todoItemSchema),
  // Optional, so a session saved before M45 still reads.
  goal: z.optional(goalRecordSchema),
  replay: z.array(
    z.object({
      turnId: z.string(),
      item: storedInputItemSchema,
      userMessageId: z.optional(z.string()),
      backgroundTaskId: z.optional(z.string()),
    }),
  ),
  transcript: z.array(
    z.object({
      turnId: z.string(),
      item: z.object({
        ...itemSnapshotFields,
        usage: z.optional(storedUsageSchema),
        costUsd: z.optional(z.number().check(z.nonnegative())),
      }),
    }),
  ),
  outputs: z.record(z.string(), z.string()),
  usage: storedUsageSchema,
  // Optional, so a session saved before M82 still reads; never below zero,
  // which would give the cap room it does not have.
  budgetSpentUsd: z.optional(z.number().check(z.nonnegative())),
  budgetIsFreshFork: z.optional(z.literal(true)),
  // Optional, so a session saved before M73 kept its ledger still reads; a
  // corrupt value is dropped before validation (withoutCorruptEstimate).
  packedTokensAvoided: z.optional(z.int().check(z.nonnegative())),
} as const

export const storedSessionSchema = z.object({
  ...storedSessionFields,
  children: z.optional(
    z.array(
      z.object({
        id: z.string(),
        role: z.string(),
        objective: z.string(),
        itemId: z.string(),
        parentTurnId: z.string(),
        checkpointRecording: z.optional(z.boolean()),
        startedAt: z.number(),
        state: z.enum(['queued', 'running', 'interrupted', 'result_ready', 'closed']),
        result: z.optional(
          z.object({
            summary: z.string(),
            text: z.optional(z.string()),
            errorKind: z.optional(z.string()),
          }),
        ),
        terminal: z.optional(z.string()),
        policyRevision: z.optional(z.string()),
        pendingMessages: z.array(z.string()),
        session: z.object(storedSessionFields),
      }),
    ),
  ),
  pendingChildResults: z.optional(
    z.array(
      z.union([
        z.string(),
        z.object({
          childId: z.string(),
          text: z.string(),
          policyRevision: z.optional(z.string()),
        }),
      ]),
    ),
  ),
  spawnCommands: z.optional(z.record(z.string(), z.string())),
})

export type StoredSessionParse =
  | { readonly ok: true; readonly session: StoredSession }
  | { readonly ok: false; readonly reason: string }

/**
 * A missing or corrupt packed-token estimate restarts at zero without losing
 * the conversation (M73). zod's `catch` would do this too, but it keeps
 * zod's `navigator` probe in the host bundles (scripts/check-host-globals.mjs).
 */
function withoutCorruptEstimate(raw: unknown): unknown {
  if (typeof raw !== 'object' || raw === null || !('packedTokensAvoided' in raw)) {
    return raw
  }
  const value: unknown = raw.packedTokensAvoided
  if (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0) {
    return raw
  }
  const { packedTokensAvoided: _dropped, ...rest } = raw
  return rest
}

/** Validates one parsed JSON document. */
export function parseStoredSession(raw: unknown): StoredSessionParse {
  const result = storedSessionSchema.safeParse(withoutCorruptEstimate(raw))
  if (!result.success) {
    return { ok: false, reason: z.prettifyError(result.error) }
  }
  // Optional fields are absent in a StoredSession, never undefined.
  const {
    accountId,
    name,
    forkedFrom,
    firstPrompt,
    compactedThroughTurnId,
    goal,
    sideChat,
    imported,
    children,
    pendingChildResults,
    spawnCommands,
    budgetSpentUsd,
    budgetIsFreshFork,
    agent,
    packedTokensAvoided,
    ...rest
  } = result.data
  const replay = rest.replay.map(({ backgroundTaskId, userMessageId, ...entry }) => ({
    ...entry,
    ...(userMessageId !== undefined && { userMessageId }),
    ...(backgroundTaskId !== undefined && { backgroundTaskId }),
  }))
  const restoredChildren: StoredChild[] = []
  const storedChildren = children ?? []
  for (const child of storedChildren) {
    const parsedChild = parseStoredSession(child.session)
    if (!parsedChild.ok) {
      return parsedChild
    }
    const { result: childResult, terminal, policyRevision, session: _session, ...childRest } = child
    restoredChildren.push({
      ...childRest,
      session: parsedChild.session,
      ...(policyRevision !== undefined && { policyRevision }),
      ...(childResult !== undefined && {
        result: {
          summary: childResult.summary,
          ...(childResult.text !== undefined && { text: childResult.text }),
          ...(childResult.errorKind !== undefined && { errorKind: childResult.errorKind }),
        },
      }),
      ...(terminal !== undefined && { terminal }),
    })
  }
  return {
    ok: true,
    session: {
      ...rest,
      ...(accountId !== undefined && { accountId }),
      replay,
      ...(name !== undefined && { name }),
      ...(forkedFrom !== undefined && { forkedFrom }),
      ...(firstPrompt !== undefined && { firstPrompt }),
      ...(compactedThroughTurnId !== undefined && { compactedThroughTurnId }),
      ...(goal !== undefined && { goal }),
      ...(budgetSpentUsd !== undefined && { budgetSpentUsd }),
      ...(budgetIsFreshFork === true && { budgetIsFreshFork }),
      ...(sideChat === true && { sideChat: true }),
      ...(imported === true && { imported: true }),
      ...(children !== undefined && { children: restoredChildren }),
      ...(pendingChildResults !== undefined && {
        pendingChildResults: pendingChildResults.map((pending) =>
          typeof pending === 'string'
            ? pending
            : {
                childId: pending.childId,
                text: pending.text,
                ...(pending.policyRevision !== undefined && {
                  policyRevision: pending.policyRevision,
                }),
              },
        ),
      }),
      ...(spawnCommands !== undefined && { spawnCommands }),
      ...(agent !== undefined && { agent }),
      ...(packedTokensAvoided !== undefined && { packedTokensAvoided }),
    },
  }
}

const IDLE = 'idle'

/** The history-list row of a session that is not loaded in this window. */
export function recordOf(stored: StoredSessionHeader): SessionRecord {
  return {
    sessionId: stored.sessionId,
    ...(stored.sideChat === true && { sideChat: true }),
    ...(stored.name !== undefined && { name: stored.name }),
    ...(stored.firstPrompt !== undefined && {
      title: stored.firstPrompt,
      firstUserPrompt: stored.firstPrompt,
    }),
    createdAt: stored.createdAt,
    updatedAt: stored.lastActivityAt,
    lastActivityAt: stored.lastActivityAt,
    status: IDLE,
    turnCount: stored.turnCount,
    forkedFrom: stored.forkedFrom === undefined ? null : { sessionId: stored.forkedFrom },
    workspaceRoot: stored.workspaceRoot,
  }
}

src/core/backends/musecode/credentialFil:
// What the Muse Code CLI's credential file (`auth.json`) says about its
// sign-in, from the file's structure alone (PLAN.md D26, 2026-09-27). The
// schema keeps four facts: the schema version, which providers are named,
// the `storage` lane of each, and whether the Muse provider carries one of
// the credential keys it was captured writing (`api_key`, `access_token`).
// A key's value is replaced by `true` in the parse, and every other field is
// dropped, so no token reaches anything; nothing from the file is stored,
// logged or passed on.
//
// Shapes seen on Muse Code 1.3.0 and 1.4.0-R4302.1 (isolated homes):
// - `{"schema_version": 1, "providers": {}}`: what `muse logout` and MSP
//   `account/logout` leave behind (they rewrite the file, never delete it).
//   Signed out on every OS.
// - Version 1 with `providers.meta` holding its credential, no `storage`:
//   `muse auth set` writes `api_key` alone, a browser sign-in `access_token`,
//   the key and the account's name (Windows and Linux). Signed in there. On
//   macOS nobody captured whether 1.4.0 reads or migrates such a file, so the
//   CLI is asked.
// - Only `providers.meta` speaks for the sign-in: 1.4.0-R4302.1's bundled
//   Slack connector reads its own `providers.slack_connector`, so a file
//   naming other providers alone is left to the CLI, as is a `meta` entry in
//   any other shape (another `storage`, or no captured credential key).
// - Version 2 with `providers.meta.storage: "keychain"`: macOS keeps the
//   token in the login Keychain and the file is a pointer. On Windows and
//   Linux `muse serve` exits 3 at startup with any version-2 file, the empty
//   one included ("unsupported auth schema version 2"), and with a version-1
//   `meta` whose storage is the Keychain ("keychain item for meta is
//   unreadable"); with META_API_KEY set it starts with each of the three.
//   An empty version-2 file on macOS was not captured: the CLI is asked.

import * as z from 'zod/mini'
import {
  MACOS_KEYCHAIN_ITEM_NOT_FOUND_EXIT,
  MUSE_CREDENTIAL_INLINE_SCHEMA,
  MUSE_CREDENTIAL_KEYCHAIN_STORAGE,
  MUSE_CREDENTIAL_POINTER_SCHEMA,
  MUSE_CREDENTIAL_PROVIDER,
} from '../../../shared/constants'

/**
 * - `empty`: a version-1 file naming no provider; the file a sign-out leaves.
 * - `inline`: holds the credential itself, in a captured shape (off macOS).
 * - `keychain`: points to the macOS Keychain (on macOS).
 * - `unsupportedHere`: a macOS file on Windows or Linux (version 2, or the
 *   Keychain lane), where `muse serve` cannot start with it.
 * - `unrecognized`: anything the structure cannot settle here; only the CLI
 *   can say.
 */
export type CredentialFileVerdict =
  'empty' | 'inline' | 'keychain' | 'unsupportedHere' | 'unrecognized'

/**
 * The CLI's own sign-in as the extension sees it: `unknown` when only the
 * CLI could say and it has not (the estimate counts it as signed in, and a
 * turn's `authRequired` corrects it); `unsupportedHere` when the file stops
 * `muse serve` from starting.
 */
export type CliSignIn = 'signedIn' | 'signedOut' | 'unknown' | 'unsupportedHere'

/** Whether the macOS Keychain holds the CLI's item, by attribute lookup only. */
export type KeychainItemPresence = 'present' | 'absent' | 'unknown'

// A credential key's presence, never its value: the parse replaces it with `true`.
const present = z.optional(
  z.pipe(
    z.unknown(),
    z.transform((): true => true),
  ),
)

// Unknown keys are dropped by the parse: a provider keeps its storage lane
// and whether it carries a captured credential key, never a key or a token.
const credentialFileSchema = z.object({
  schema_version: z.number(),
  providers: z.record(
    z.string(),
    z.object({ storage: z.optional(z.string()), api_key: present, access_token: present }),
  ),
})

type ProviderEntry = z.infer<typeof credentialFileSchema>['providers'][string]

/**
 * The shapes captured holding the sign-in in the file (the review of PR #49):
 * no `storage` lane, and `api_key` (`muse auth set`) or `access_token` (a
 * browser sign-in). Any other `meta` entry is the CLI's to place.
 */
function isCapturedInlineEntry(entry: ProviderEntry): boolean {
  return entry.storage === undefined && (entry.api_key === true || entry.access_token === true)
}

export function credentialFileVerdict(
  text: string,
  platform: NodeJS.Platform,
): CredentialFileVerdict {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return 'unrecognized'
  }
  const parsed = credentialFileSchema.safeParse(raw)
  if (!parsed.success) {
    return 'unrecognized'
  }
  const version = parsed.data.schema_version
  if (version !== MUSE_CREDENTIAL_INLINE_SCHEMA && version !== MUSE_CREDENTIAL_POINTER_SCHEMA) {
    return 'unrecognized'
  }
  const isMacOs = platform === 'darwin'
  // Off macOS the version alone stops `muse serve`, whatever the file holds
  // (captured on Windows and Linux for a pointer and for an empty file; the
  // review of PR #49).
  if (version === MUSE_CREDENTIAL_POINTER_SCHEMA && !isMacOs) {
    return 'unsupportedHere'
  }
  const providers = parsed.data.providers
  const muse = Object.hasOwn(providers, MUSE_CREDENTIAL_PROVIDER)
    ? providers[MUSE_CREDENTIAL_PROVIDER]
    : undefined
  if (muse === undefined) {
    // A version-1 file naming no provider is what a sign-out leaves, on every
    // OS. Another provider alone (a connector's token), or an empty
    // version-2 file on macOS (never captured), is the CLI's to say.
    const isSignOutShell =
      version === MUSE_CREDENTIAL_INLINE_SCHEMA && Object.keys(providers).length === 0
    return isSignOutShell ? 'empty' : 'unrecognized'
  }
  if (
    version === MUSE_CREDENTIAL_POINTER_SCHEMA ||
    muse.storage === MUSE_CREDENTIAL_KEYCHAIN_STORAGE
  ) {
    return isMacOs ? 'keychain' : 'unsupportedHere'
  }
  // Whether macOS 1.4.0 reads or migrates a version-1 file holding the
  // credential was never captured: there the CLI says (the review of PR #49).
  return !isMacOs && isCapturedInlineEntry(muse) ? 'inline' : 'unrecognized'
}

/** `security find-generic-password` without `-g`/`-w`: 0 found, 44 not found. */
export function keychainItemPresence(exitCode: number): KeychainItemPresence {
  if (exitCode === 0) {
    return 'present'
  }
  return exitCode === MACOS_KEYCHAIN_ITEM_NOT_FOUND_EXIT ? 'absent' : 'unknown'
}

src/core/backends/musecode/launch.ts:
// Locating the Muse Code CLI and shaping the child process per platform.
// Pure: every filesystem and environment fact is injected, so the Windows,
// macOS and Linux branches are all unit-tested on any OS (PLAN.md D1a).
//
// Verified layouts (Muse Code 1.3.0, 2026-09-22):
//   Windows  %LOCALAPPDATA%\Programs\muse\  muse.cmd, .muse-launcher.ps1,
//            .muse-version, muse-bin-<version>.exe
//   POSIX    ~/.local/bin/                   muse (bash launcher),
//            .muse-version, muse-bin-<version>
// Node refuses to spawn a .cmd without a shell, and a shell string is banned,
// so on Windows the resolver targets muse-bin-<version>.exe directly: the one
// `.muse-version` names, else the newest `muse-bin-*.exe` in the folder. The
// PowerShell launcher is never the command (PLAN.md D25): Windows can only
// end the direct child, so closing a launcher left muse-bin running.

import path from 'node:path'
import type { EnvironmentVariable } from '../../../shared/constants'
import {
  LOOPBACK_NO_PROXY_ENTRIES,
  MUSE_BIN_PREFIX,
  MUSE_CMD_FILE,
  MUSE_CREDENTIAL_FILE_SEGMENTS,
  MUSE_POSIX_EXECUTABLE,
  MUSE_POSIX_INSTALL_SEGMENTS,
  MUSE_VERSION_FILE,
  MUSE_WINDOWS_EXE_SUFFIX,
  MUSE_WINDOWS_INSTALL_SEGMENTS,
  NO_PROXY_SEPARATOR,
  NO_PROXY_SPELLINGS,
  NO_PROXY_VARIABLE,
  PROXY_VARIABLE_SPELLINGS,
  UI_TEXT,
  WINDOWS_PSMODULEPATH_SEGMENTS,
} from '../../../shared/constants'

export interface LaunchProbe {
  readonly platform: NodeJS.Platform
  /** `museSpark.museBinaryPath`; empty means discover. */
  readonly configuredPath: string
  /** Entries of the PATH variable, already split. */
  readonly pathEntries: readonly string[]
  readonly homeDir: string
  /** `%LOCALAPPDATA%` on Windows; undefined elsewhere. */
  readonly localAppData: string | undefined
  readonly fileExists: (filePath: string) => boolean
  /** Returns undefined when the file cannot be read. */
  readonly readTextFile: (filePath: string) => string | undefined
  /** The file names in a directory; empty when it cannot be read. */
  readonly listDirectory: (directory: string) => readonly string[]
  /** `serve` plus the host-posture flags (`serveArguments`, sandbox.ts). */
  readonly serveArgs: readonly string[]
}

export interface MuseLaunch {
  readonly command: string
  readonly args: readonly string[]
  /** The trailing `serve …` part of `args`, for callers that swap it out. */
  readonly serveArgs: readonly string[]
  /** Directory the CLI was found in (for diagnostics and `muse login`). */
  readonly installDir: string
  /** The command a user-facing terminal should run (`muse.cmd` / `muse`). */
  readonly cliPath: string
}

export type LaunchResolution =
  | { readonly ok: true; readonly launch: MuseLaunch }
  | { readonly ok: false; readonly searched: readonly string[]; readonly reason: string }

function pathModule(platform: NodeJS.Platform): path.PlatformPath {
  return platform === 'win32' ? path.win32 : path.posix
}

/**
 * The PATH entries worth probing: an empty or relative entry means the
 * current directory, which for `muse serve` is the workspace (PLAN.md D24).
 */
function absoluteEntries(probe: LaunchProbe, p: path.PlatformPath): readonly string[] {
  return probe.pathEntries.filter((entry) => entry !== '' && p.isAbsolute(entry))
}

function windowsCandidateDirs(probe: LaunchProbe, p: path.PlatformPath): string[] {
  const dirs: string[] = []
  if (probe.configuredPath !== '') {
    dirs.push(p.dirname(probe.configuredPath))
  }
  for (const entry of absoluteEntries(probe, p)) {
    if (probe.fileExists(p.join(entry, MUSE_CMD_FILE))) {
      dirs.push(entry)
    }
  }
  if (probe.localAppData !== undefined) {
    dirs.push(p.join(probe.localAppData, ...MUSE_WINDOWS_INSTALL_SEGMENTS))
  }
  return dirs
}

function resolveWindows(probe: LaunchProbe): LaunchResolution {
  const p = path.win32
  const searched: string[] = []
  if (probe.configuredPath.toLowerCase().endsWith(MUSE_WINDOWS_EXE_SUFFIX)) {
    if (probe.fileExists(probe.configuredPath)) {
      const installDir = p.dirname(probe.configuredPath)
      return {
        ok: true,
        launch: {
          command: probe.configuredPath,
          args: probe.serveArgs,
          serveArgs: probe.serveArgs,
          installDir,
          cliPath: p.join(installDir, MUSE_CMD_FILE),
        },
      }
    }
    searched.push(probe.configuredPath)
  }
  for (const dir of windowsCandidateDirs(probe, p)) {
    searched.push(dir)
    const exe = windowsExecutableIn(probe, p, dir)
    if (exe !== undefined) {
      return {
        ok: true,
        launch: {
          command: exe,
          args: probe.serveArgs,
          serveArgs: probe.serveArgs,
          installDir: dir,
          cliPath: p.join(dir, MUSE_CMD_FILE),
        },
      }
    }
  }
  return { ok: false, searched, reason: UI_TEXT.cliNotFound }
}

/**
 * The `muse-bin-<version>.exe` of an install folder: the version
 * `.muse-version` names, else the newest one present (version order, so
 * 1.10 beats 1.9); undefined when there is none.
 */
function windowsExecutableIn(
  probe: LaunchProbe,
  p: path.PlatformPath,
  dir: string,
): string | undefined {
  const version = probe.readTextFile(p.join(dir, MUSE_VERSION_FILE))?.trim()
  if (version !== undefined && version !== '') {
    const named = p.join(dir, `${MUSE_BIN_PREFIX}${version}${MUSE_WINDOWS_EXE_SUFFIX}`)
    if (probe.fileExists(named)) {
      return named
    }
  }
  const newest = probe
    .listDirectory(dir)
    .filter((name) => {
      const lower = name.toLowerCase()
      return lower.startsWith(MUSE_BIN_PREFIX) && lower.endsWith(MUSE_WINDOWS_EXE_SUFFIX)
    })
    .toSorted((a, b) => b.localeCompare(a, 'en', { numeric: true }))
    .at(0)
  return newest === undefined ? undefined : p.join(dir, newest)
}

function resolvePosix(probe: LaunchProbe): LaunchResolution {
  const p = path.posix
  const candidates: string[] = []
  if (probe.configuredPath !== '') {
    candidates.push(probe.configuredPath)
  }
  for (const entry of absoluteEntries(probe, p)) {
    candidates.push(p.join(entry, MUSE_POSIX_EXECUTABLE))
  }
  candidates.push(p.join(probe.homeDir, ...MUSE_POSIX_INSTALL_SEGMENTS, MUSE_POSIX_EXECUTABLE))
  for (const candidate of candidates) {
    if (probe.fileExists(candidate)) {
      return {
        ok: true,
        launch: {
          command: candidate,
          args: probe.serveArgs,
          serveArgs: probe.serveArgs,
          installDir: p.dirname(candidate),
          cliPath: candidate,
        },
      }
    }
  }
  return {
    ok: false,
    searched: candidates,
    reason: UI_TEXT.cliNotFound,
  }
}

export function resolveMuseLaunch(probe: LaunchProbe): LaunchResolution {
  // A relative setting would resolve against whatever the current directory is.
  if (probe.configuredPath !== '' && !pathModule(probe.platform).isAbsolute(probe.configuredPath)) {
    return {
      ok: false,
      searched: [probe.configuredPath],
      reason: UI_TEXT.cliPathNotAbsolute,
    }
  }
  return probe.platform === 'win32' ? resolveWindows(probe) : resolvePosix(probe)
}

export interface ChildEnvironmentInput {
  readonly platform: NodeJS.Platform
  readonly baseEnv: NodeJS.ProcessEnv
  readonly extraVariables: readonly EnvironmentVariable[]
  readonly systemRoot: string | undefined
  readonly programFiles: string | undefined
}

/**
 * Sets `name` in a copied environment. Windows names are case-insensitive
 * and Node passes the first of several spellings in sort order, so an
 * inherited `PSMODULEPATH` would beat a new `PSModulePath`: every other
 * spelling goes first.
 */
export function setEnvironmentVariable(
  env: NodeJS.ProcessEnv,
  platform: NodeJS.Platform,
  name: string,
  value: string,
): void {
  if (platform === 'win32') {
    const lower = name.toLowerCase()
    for (const key of Object.keys(env)) {
      if (key !== name && key.toLowerCase() === lower) {
        Reflect.deleteProperty(env, key)
      }
    }
  }
  env[name] = value
}

/** Removes `name` (every spelling of it on Windows) from a copied environment. */
export function deleteEnvironmentVariable(
  env: NodeJS.ProcessEnv,
  platform: NodeJS.Platform,
  name: string,
): void {
  const lower = name.toLowerCase()
  for (const key of Object.keys(env)) {
    if (key === name || (platform === 'win32' && key.toLowerCase() === lower)) {
      Reflect.deleteProperty(env, key)
    }
  }
}

/** Reads `name` from a copied environment, ignoring case on Windows. */
export function environmentValue(
  env: NodeJS.ProcessEnv,
  platform: NodeJS.Platform,
  name: string,
): string | undefined {
  if (platform !== 'win32') {
    return env[name]
  }
  const lower = name.toLowerCase()
  const key = Object.keys(env).find((candidate) => candidate.toLowerCase() === lower)
  return key === undefined ? undefined : env[key]
}

/**
 * Windows PowerShell 5.1's own module directories. A pwsh 7 `PSModulePath`
 * inherited by powershell.exe makes it load 7.x modules it cannot use
 * (verified failure: `Get-FileHash` not recognised).
 */
export function windowsPowerShellModulePath(
  systemRoot: string,
  programFiles: string | undefined,
): string {
  const base = programFiles ?? path.win32.join(systemRoot, '..', 'Program Files')
  return [
    path.win32.join(base, ...WINDOWS_PSMODULEPATH_SEGMENTS.programFiles),
    path.win32.join(systemRoot, ...WINDOWS_PSMODULEPATH_SEGMENTS.systemRoot),
  ].join(';')
}

/**
 * The environment for `muse serve`. On Windows `PSModulePath` is reset to the
 * Windows PowerShell module directories: the CLI's launcher runs under
 * powershell.exe 5.1, which cannot load its own modules when a pwsh 7 module
 * path is inherited (verified failure: `Get-FileHash` not recognised).
 *
 * The Model API key from secret storage is deliberately NOT injected: the
 * CLI prefers `META_API_KEY` over its browser session, which would bill the
 * subscription's work to the key (PLAN.md D1, M7). A key already in the
 * user's own environment is inherited untouched, as the CLI documents.
 */
export function buildChildEnvironment(input: ChildEnvironmentInput): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = { ...input.baseEnv }
  if (input.platform === 'win32' && input.systemRoot !== undefined) {
    setEnvironmentVariable(
      env,
      input.platform,
      'PSModulePath',
      windowsPowerShellModulePath(input.systemRoot, input.programFiles),
    )
  }
  for (const variable of input.extraVariables) {
    setEnvironmentVariable(env, input.platform, variable.name, variable.value)
  }
  return env
}

/**
 * `museSpark.environmentVariables` for a terminal that runs the CLI (`muse
 * logout`, `muse mcp login`, Open in Terminal). VS Code adds them to the
 * terminal's own environment, so the CLI there reads the same config home
 * as `muse serve` (the review of PR #49). On Windows one spelling per name,
 * the last one given winning, as for `muse serve`.
 */
export function terminalEnvironment(
  variables: readonly EnvironmentVariable[],
  platform: NodeJS.Platform,
): Record<string, string> {
  const env: Record<string, string> = {}
  for (const variable of variables) {
    setEnvironmentVariable(env, platform, variable.name, variable.value)
  }
  return env
}

/**
 * Keeps loopback off the proxy (M56, PLAN.md D43). Muse Code sends every
 * HTTP request through the proxy its environment names, including its
 * connection to the extension's `ide` server on 127.0.0.1, which a corporate
 * proxy cannot reach (captured 2026-09-25: `POST http://127.0.0.1:<port>/mcp`
 * arrived at the proxy until NO_PROXY listed the address). So wherever a
 * proxy is set, from VS Code or the user's own environment, the loopback
 * names are added to each NO_PROXY spelling already there, or to a new
 * NO_PROXY; entries already listed stay as they are.
 */
export function withLoopbackBypass(
  env: NodeJS.ProcessEnv,
  platform: NodeJS.Platform,
): NodeJS.ProcessEnv {
  const isProxied = PROXY_VARIABLE_SPELLINGS.some(
    (name) => (environmentValue(env, platform, name) ?? '') !== '',
  )
  if (!isProxied) {
    return env
  }
  const bypassed: NodeJS.ProcessEnv = { ...env }
  const present = NO_PROXY_SPELLINGS.filter(
    (name) => environmentValue(bypassed, platform, name) !== undefined,
  )
  // On Windows the two spellings are one variable.
  const targets = platform === 'win32' || present.length === 0 ? [NO_PROXY_VARIABLE] : present
  for (const name of targets) {
    const entries = (environmentValue(bypassed, platform, name) ?? '')
      .split(NO_PROXY_SEPARATOR)
      .map((entry) => entry.trim())
      .filter((entry) => entry !== '')
    const missing = LOOPBACK_NO_PROXY_ENTRIES.filter((entry) => !entries.includes(entry))
    setEnvironmentVariable(
      bypassed,
      platform,
      name,
      [...entries, ...missing].join(NO_PROXY_SEPARATOR),
    )
  }
  return bypassed
}

export interface CredentialPathInput {
  readonly platform: NodeJS.Platform
  readonly homeDir: string
  readonly xdgConfigHome: string | undefined
}

/**
 * Where the CLI stores its browser-login credential. The binary honours
 * `XDG_CONFIG_HOME` on every platform (Windows included) and otherwise uses
 * `~/.config`; `MUSE_AUTH_PATH` is honoured only by the POSIX launcher, so it
 * is deliberately not consulted here.
 */
export function credentialFilePath(input: CredentialPathInput): string {
  const p = pathModule(input.platform)
  const configHome = input.xdgConfigHome ?? p.join(input.homeDir, '.config')
  return p.join(configHome, ...MUSE_CREDENTIAL_FILE_SEGMENTS)
}

src/core/backends/musecode/logText.ts:
// What the log says about text the Muse Code CLI wrote (the review of PR
// #49): its MSP error messages and its stderr are free text that can name a
// path under the user's profile or an account, and the log channel's
// redactor catches only key-shaped strings. So an MSP failure is named by its
// kind and code, and stderr by the lines 1.4.0-R4302.1 was captured writing
// (docs/certification/sign-in-detection.md), in fixed words; anything else
// by its length alone.

import { MspError } from '@muse-code/sdk'
import { wireWordForLog } from '../../logging'
import { DeadlineError } from '../../timeouts'

/** A failure as the log names it: never the CLI's message. */
export function failureForLog(error: unknown): string {
  if (error instanceof MspError) {
    return `${wireWordForLog(error.kind)} (MSP error ${String(error.code)})`
  }
  // The extension's own words, naming the method that went unanswered.
  if (error instanceof DeadlineError) {
    return error.message
  }
  return error instanceof Error ? error.name : 'an unknown failure'
}

// The stderr lines captured from `muse serve` 1.4.0-R4302.1 (Windows and
// Linux, 2026-09-27; scratchpad/m140cred), each named in fixed words.
const CAPTURED_STDERR: readonly {
  readonly pattern: RegExp
  readonly logged: (match: RegExpExecArray) => string
}[] = [
  {
    pattern: /unsupported auth schema version (\d{1,9})/u,
    logged: (match) =>
      `unsupported auth schema version ${match[1] ?? '?'} (the credential file's path is not logged)`,
  },
  {
    pattern: /keychain item for meta is unreadable/u,
    logged: () => 'the Keychain item for meta is unreadable',
  },
  {
    pattern: /startup model-catalog fetch failed/u,
    logged: () => 'the startup model-catalog fetch failed',
  },
]

/** One line the CLI wrote to stderr, as the log names it. */
function stderrLineForLog(line: string): string {
  for (const captured of CAPTURED_STDERR) {
    const match = captured.pattern.exec(line)
    if (match !== null) {
      return captured.logged(match)
    }
  }
  return `a line of ${String(line.length)} characters (not logged: it may name a path or an account)`
}

/** What the CLI wrote to stderr, as the log names it: each line in fixed words. */
export function stderrForLog(chunk: string): string {
  return chunk
    .split(/\r?\n/u)
    .filter((line) => line.trim() !== '')
    .map((line) => stderrLineForLog(line))
    .join('; ')
}

src/core/backends/musecode/mapNotificati:
// Maps Muse Session Protocol notifications onto backend-agnostic AgentEvents.
// Pure and total: an unknown method is `UNKNOWN_METHOD` and params that fail
// their schema are `MALFORMED_PARAMS`, and the caller decides how loudly to
// log either. Only the fields the UI consumes are validated; the wire carries
// far more (see the SDK's msp.d.ts). Shapes were verified against live
// captures on 2026-09-21/22 (docs/certification/m4.md).

import * as z from 'zod/mini'
import {
  type AgentEvent,
  answerSchema,
  approvalChoiceSchema,
  approvalSubjectSchema,
  questionSchema,
  requirementRefSchema,
  todoItemSchema,
} from '../../../shared/agentEvents'
import { UI_TEXT } from '../../../shared/constants'
import { toSessionGoal, toSnapshot, wireGoalSchema, wireItemSchema } from './sessionRecords'

export type MappedNotification =
  | { readonly sessionId: string; readonly event: AgentEvent }
  /** The host already holds this approval's terminal (`change.kind: alreadyTerminal`). */
  | { readonly sessionId: string; readonly closedApprovalId: string }

export const UNKNOWN_METHOD = 'unknown'
export const MALFORMED_PARAMS = 'malformed'
export type MapOutcome = MappedNotification | typeof UNKNOWN_METHOD | typeof MALFORMED_PARAMS

const ALREADY_TERMINAL = 'alreadyTerminal'

export interface WireNotification {
  readonly method: string
  readonly params?: Record<string, unknown> | undefined
}

const itemSchema = wireItemSchema

const sessionScoped = { sessionId: z.string() }

const schemas = {
  'turn/started': z.object({ ...sessionScoped, turnId: z.string() }),
  'item/started': z.object({ ...sessionScoped, item: itemSchema }),
  'item/delta': z.object({
    ...sessionScoped,
    itemId: z.string(),
    delta: z.string(),
    field: z.optional(z.string()),
  }),
  'item/updated': z.object({ ...sessionScoped, item: itemSchema }),
  'item/completed': z.object({ ...sessionScoped, item: itemSchema }),
  'turn/completed': z.object({
    ...sessionScoped,
    turnId: z.string(),
    terminal: z.string(),
    reason: z.optional(z.string()),
    durationMs: z.optional(z.number()),
    error: z.optional(z.object({ kind: z.string(), message: z.string() })),
  }),
  'turn/retryScheduled': z.object({
    ...sessionScoped,
    turnId: z.string(),
    attempt: z.number(),
    maxAttempts: z.number(),
    retryDelayMs: z.number(),
    reason: z.string(),
  }),
  // The session's running totals (D26): `cumulative` counts prompt tokens once
  // under the provider's cache convention; the raw per-completion counters
  // beside it do not sum across providers, so they are not shown.
  'session/tokenUsage': z.object({
    ...sessionScoped,
    modelId: z.optional(z.nullable(z.string())),
    cumulative: z.object({ promptTokens: z.number(), outputTokens: z.number() }),
  }),
  'session/contextUsage': z.object({
    ...sessionScoped,
    usedTokens: z.number(),
    windowTokens: z.optional(z.number()),
    pressure: z.string(),
  }),
  'session/modelChanged': z.object({ ...sessionScoped, modelId: z.string() }),
  'session/statusChanged': z.object({ ...sessionScoped, status: z.string() }),
  'session/nameChanged': z.object({ ...sessionScoped, name: z.string() }),
  'session/reasoningEffortChanged': z.object({ ...sessionScoped, reasoningEffort: z.string() }),
  'session/approvalModeChanged': z.object({ ...sessionScoped, mode: z.string() }),
  'session/todoListChanged': z.object({ ...sessionScoped, items: z.array(todoItemSchema) }),
  // The goal block replaced wholesale; an explicit `null` clears it (tdd
  // SS4.6.2, captured live 2026-09-25, M45). Absent reads as cleared too:
  // the schema types it optional, and it never means "unchanged".
  'session/goalChanged': z.object({
    ...sessionScoped,
    goal: z.optional(z.nullable(wireGoalSchema)),
  }),
  'skill/changed': z.object(sessionScoped),
  'approval/requested': z.object({
    ...sessionScoped,
    approvalId: z.string(),
    itemId: z.string(),
    toolName: z.string(),
    rawArgs: z.string(),
    currentRequirementId: requirementRefSchema,
    subject: approvalSubjectSchema,
    availableChoices: z.array(approvalChoiceSchema),
    judgeEscalated: z.boolean(),
    protectedWrite: z.boolean(),
    // The asking turn, on every captured frame (2026-10-02, stageRaceCapture).
    turnId: z.optional(z.string()),
  }),
  'approval/updated': z.object({
    ...sessionScoped,
    approvalId: z.string(),
    currentRequirementId: requirementRefSchema,
    subject: approvalSubjectSchema,
    availableChoices: z.array(approvalChoiceSchema),
    change: z.optional(z.object({ kind: z.string() })),
  }),
  'approval/resolved': z.object({
    ...sessionScoped,
    approvalId: z.string(),
    itemId: z.string(),
    decision: z.string(),
    resolvedBy: z.string(),
  }),
  'userInput/requested': z.object({
    ...sessionScoped,
    userInputId: z.string(),
    itemId: z.string(),
    questions: z.array(questionSchema),
  }),
  'userInput/settled': z.object({
    ...sessionScoped,
    userInputId: z.string(),
    outcome: z.string(),
    answers: z.array(answerSchema),
    // The explanation a `clarified` prompt settled with (M46); null otherwise.
    clarification: z.optional(z.nullable(z.object({ content: z.string() }))),
  }),
  // A queued submission reclaimed: its turn never runs (tdd SS3.6).
  'turn/unqueued': z.object({ ...sessionScoped, turnId: z.string() }),
  // Another client withdrew a submission; the item itself is re-sent as updated.
  'turn/retracted': z.object({ ...sessionScoped, turnId: z.string() }),
  // Live delivery dropped events between two cursors (spec 208 SS4.8).
  'view/gap': z.object({ ...sessionScoped, after: z.string(), next: z.string() }),
  // The account's provider cannot serve the session's standing model (#25603).
  'session/modelRouteUnserved': z.object({ ...sessionScoped, modelId: z.string() }),
} as const

type MappedMethod = keyof typeof schemas

function isMappedMethod(method: string): method is MappedMethod {
  return Object.hasOwn(schemas, method)
}

/** The default delta field when the host omits one. */
const DEFAULT_DELTA_FIELD = 'text'

export function mapNotification(notification: WireNotification): MapOutcome {
  const { method } = notification
  if (!isMappedMethod(method)) {
    return UNKNOWN_METHOD
  }
  // Parse the new goal frame under its literal method so TypeScript can
  // verify the schema/data relationship without an unchecked cast (M45).
  if (method === 'session/goalChanged') {
    const parsedGoal = schemas[method].safeParse(notification.params)
    if (!parsedGoal.success) {
      return MALFORMED_PARAMS
    }
    const { sessionId, goal } = parsedGoal.data
    return {
      sessionId,
      event: {
        type: 'goalChanged',
        goal: goal === undefined || goal === null ? null : toSessionGoal(goal),
      },
    }
  }
  const parsed = schemas[method].safeParse(notification.params)
  if (!parsed.success) {
    return MALFORMED_PARAMS
  }
  const params = parsed.data
  switch (method) {
    case 'turn/started': {
      const { sessionId, turnId } = params as z.infer<(typeof schemas)['turn/started']>
      return { sessionId, event: { type: 'turnStarted', turnId } }
    }
    case 'item/started': {
      const { sessionId, item } = params as z.infer<(typeof schemas)['item/started']>
      return { sessionId, event: { type: 'itemStarted', item: toSnapshot(item) } }
    }
    case 'item/delta': {
      const { sessionId, itemId, delta, field } = params as z.infer<(typeof schemas)['item/delta']>
      return {
        sessionId,
        event: { type: 'textDelta', itemId, field: field ?? DEFAULT_DELTA_FIELD, delta },
      }
    }
    case 'item/updated': {
      const { sessionId, item } = params as z.infer<(typeof schemas)['item/updated']>
      return { sessionId, event: { type: 'itemUpdated', item: toSnapshot(item) } }
    }
    case 'item/completed': {
      const { sessionId, item } = params as z.infer<(typeof schemas)['item/completed']>
      return { sessionId, event: { type: 'itemCompleted', item: toSnapshot(item) } }
    }
    case 'turn/completed': {
      const { sessionId, turnId, terminal, reason, durationMs, error } = params as z.infer<
        (typeof schemas)['turn/completed']
      >
      return {
        sessionId,
        event: {
          type: 'turnCompleted',
          turnId,
          terminal,
          ...(reason !== undefined && { reason }),
          ...(error !== undefined && { errorKind: error.kind }),
          ...(durationMs !== undefined && { durationMs }),
