    }
    case 'approval/requested': {
      const p = params as z.infer<(typeof schemas)['approval/requested']>
      return {
        sessionId: p.sessionId,
        event: {
          type: 'approvalRequested',
          approvalId: p.approvalId,
          itemId: p.itemId,
