// MSP refusals of a decision or answer that arrived after the prompt had
// moved (D26): nothing is wrong, and the card follows the host's own events.
const PROMPT_SETTLED_KINDS: ReadonlyMap<string, PromptSettledReason> = new Map([
  ['approvalAlreadyResolved', 'alreadySettled'],
  ['userInputAlreadySettled', 'alreadySettled'],
  ['approvalRequirementStale', 'movedOn'],
  ['approvalNotFound', 'gone'],
  ['userInputNotFound', 'gone'],
])

// An approval mode above the host's ceiling (M56, PLAN.md D43): MSP answers
// `session/start` and `session/setApprovalMode` with `commandRejected` and
// this reason, "approval mode exceeds or is incomparable with the sealed
// startup mode or the managed approval-mode set" (captured 2026-09-25).
const APPROVAL_MODE_CEILING = 'approval_mode_ceiling'

/** A refused approval mode as a reason the user can act on; anything else unchanged. */
function ceilingOr(error: unknown): unknown {
  return error instanceof MspError &&
    error.kind === COMMAND_REJECTED &&
    error.data['reason'] === APPROVAL_MODE_CEILING
    ? new Error(UI_TEXT.approvalModeCeiling, { cause: error })
    : error
}

/** A late decision or answer as a `PromptSettledError`; anything else unchanged. */
function settledOr(error: unknown): unknown {
  if (!(error instanceof MspError)) {
    return error
  }
  const reason = PROMPT_SETTLED_KINDS.get(error.kind)
  return reason === undefined ? error : new PromptSettledError(reason, error.message)
}

const FAULT_MARKERS: Readonly<Record<MuseCodeFault, string>> = {
  approvalReplay: MUSE_APPROVAL_REPLAY_FAULT,
  approvalLedger: MUSE_APPROVAL_LEDGER_FAULT,
}

/** Muse Code's own approval fault as a `MuseCodeFaultError`; anything else unchanged. */
function faultOr(error: unknown, fault: MuseCodeFault): unknown {
  return error instanceof MspError &&
    error.kind === MSP_INTERNAL &&
    error.message.includes(FAULT_MARKERS[fault])
    ? new MuseCodeFaultError(fault, error.message)
    : error
}

// A `task/*` command naming a task that is not (or no longer) there, as
// Muse Code 1.3.0 refuses it (captured 2026-09-25, M46): `commandRejected`
// with the reason `invalid_target`.
const INVALID_TARGET = 'invalid_target'

/** A refused `task/*` command in the user's words when the task is gone; anything else unchanged. */
function taskRefusalOr(error: unknown): unknown {
  return error instanceof MspError &&
    error.kind === COMMAND_REJECTED &&
    error.data['reason'] === INVALID_TARGET
    ? new Error(UI_TEXT.taskNotRunning)
    : error
}

// `item/readOutput` encodings: text media is always utf8, binary media base64.
const BASE64_ENCODING = 'base64'
const UTF8_ENCODING = 'utf8'
const STRICT_UTF8 = new TextDecoder('utf-8', { fatal: true })

// The worst-case JSON-RPC envelope around a command's params, for the size check.
const FRAME_ENVELOPE = { jsonrpc: '2.0', id: Number.MAX_SAFE_INTEGER }

/** How long a command may wait (PLAN.md D25); overridable for tests. */
export interface CommandTimeouts {
  readonly normalMs: number
  readonly longMs: number
  /** The watchdog's silence (`MSP_UNRESPONSIVE_SILENCE_MS` unless a test shortens it). */
  readonly unresponsiveSilenceMs?: number
}

const DEFAULT_TIMEOUTS: CommandTimeouts = {
  normalMs: MSP_COMMAND_TIMEOUT_MS,
  longMs: MSP_LONG_COMMAND_TIMEOUT_MS,
}

/**
 * Whether `muse serve` still answers at all (the unresponsive-host watchdog,
 * CLI recovery 2026-10-03). Every frame from it (an answer, an event, a
 * server request) is heard here and clears the count. A command that
 * misses its deadline counts once; at `MSP_UNRESPONSIVE_MISSES` in a row
 * with nothing heard for the silence, Muse Code is not answering: that is
 * logged and told once, and new commands fail at once until a frame comes.
 */
class HostLiveness {
  private lastHeardAt = Date.now()
  private misses = 0
  private isSilent = false

  public constructor(
    private readonly silenceMs: number,
    private readonly log: CoreLogger,
    private readonly onUnresponsive: () => void,
  ) {}

  public get isUnresponsive(): boolean {
    return this.isSilent
  }

  /** A frame arrived from `muse serve`. */
  public heard(): void {
    this.lastHeardAt = Date.now()
    this.misses = 0
    if (!this.isSilent) {
      return
    }
    this.isSilent = false
    this.log.info('Muse Code answers again; commands are sent again')
  }

  /** A command missed its deadline. */
  public missed(method: string): void {
    this.misses += 1
    const silentMs = Date.now() - this.lastHeardAt
    if (this.isSilent || this.misses < MSP_UNRESPONSIVE_MISSES || silentMs < this.silenceMs) {
      return
    }
    this.isSilent = true
    this.log.warn(
      `Muse Code is not answering: ${String(this.misses)} commands in a row missed their deadline (the last ${method}) and nothing came from it for ${String(Math.round(silentMs / MILLISECONDS_PER_SECOND))} s; new commands fail at once until it answers or restarts`,
    )
    this.onUnresponsive()
  }
}

/** What every command on one connection shares: its deadlines, its log and its watchdog. */
interface CommandChannel {
  readonly connection: Connection
  readonly timeouts: CommandTimeouts
  readonly log: CoreLogger
  readonly liveness: HostLiveness
}

/** An MSP refusal that admitted nothing, so the same command may be sent again. */
function isRetryableRefusal(error: unknown): boolean {
  return (
    error instanceof MspError &&
    MSP_RETRYABLE_REFUSALS.some(
      (refusal) => refusal.code === error.code && refusal.kind === error.kind,
    )
  )
}

/**
 * A card that waits on the user, an approval or a question: shown again to a
 * later surface, it is marked replayed, so it is never approved on its own
 * and raises no new notice (M82).
 */
function isPendingPrompt(
  event: AgentEvent,
): event is Extract<AgentEvent, { type: 'approvalRequested' | 'questionRequested' }> {
  return event.type === 'approvalRequested' || event.type === 'questionRequested'
}

function pause(ms: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, ms)
  })
}

/**
 * A turn's parts as MSP takes them. `TurnInputPart` is text, image or skill
 * in 1.3.0. Text files are named text parts; PDFs are refused because an
 * unknown type is `invalidParams` (msp.d.ts, M54, sdk issue #48).
 */
function mspInput(parts: readonly TurnPart[]): readonly TurnPart[] {
  const input: TurnPart[] = []
  let attachmentBytes = 0
  for (const part of parts) {
    if (part.type === 'file') {
      throw new Error(UI_TEXT.pdfNeedsModelApi)
    }
    const inputPart: TurnPart =
      part.type === 'textFile' ? { type: 'text', text: textFileInput(part) } : part
    if (part.type === 'image' || part.type === 'textFile') {
      attachmentBytes +=
        part.type === 'image'
          ? Buffer.byteLength(part.base64Data) +
            Buffer.byteLength(JSON.stringify({ ...part, base64Data: '' }))
          : Buffer.byteLength(JSON.stringify(inputPart))
      if (attachmentBytes > MSP_ATTACHMENT_FRAME_BUDGET_BYTES) {
        throw new Error(UI_TEXT.textFilesOverBudget)
      }
    }
    input.push(inputPart)
  }
  return input
}

/**
 * `Connection.command` without its memory (PLAN.md D26). The SDK keeps the
 * canonical payload of every command for the connection's life, an image
 * turn's base64 included, to check replays across reconnects this
 * extension never makes, so a long session's memory only grew. The same
 * contract otherwise: the command id rides in the params, the ack must echo
 * it, and a refusal that admitted nothing (`overloaded`, `backpressured`)
 * is retried with the same id after a short, growing, jittered wait.
 */
async function sendCommand(
  channel: CommandChannel,
  method: string,
  params: Record<string, unknown>,
  commandId: string,
): Promise<Record<string, unknown>> {
  const { log } = channel
  const commandParams = { ...params, commandId }
  // The host drops an oversized frame without answering it (D26).
  const frame = JSON.stringify({ ...FRAME_ENVELOPE, method, params: commandParams })
  if (Buffer.byteLength(frame) > MSP_FRAME_LIMIT_BYTES) {
    throw new Error(UI_TEXT.commandTooLarge)
  }
  for (let attempt = 1; ; attempt += 1) {
    try {
      const ack = await answered(channel, method, commandParams)
      if (ack['commandId'] !== undefined && ack['commandId'] !== commandId) {
        throw new Error(`${method} ack did not echo its commandId ${commandId}`)
      }
      return ack
    } catch (error: unknown) {
      if (!isRetryableRefusal(error) || attempt >= MSP_COMMAND_ATTEMPTS) {
        throw error
      }
      const ceiling = Math.min(MSP_RETRY_MAX_DELAY_MS, MSP_RETRY_BASE_DELAY_MS * 2 ** (attempt - 1))
      const delayMs = Math.floor(Math.random() * (ceiling + 1))
      log.warn(
        `${method} refused (${failureForLog(error)}); attempt ${String(attempt + 1)} in ${String(delayMs)} ms`,
      )
      await pause(delayMs)
    }
  }
}

/**
 * One request's answer, heard by the watchdog: a result, or an error the
 * host wrote. A late answer, after its deadline, is heard too.
 */
async function answered(
  channel: CommandChannel,
  method: string,
  params: Record<string, unknown>,
): Promise<Record<string, unknown>> {
  try {
    const answer = await channel.connection.request(method, params)
    channel.liveness.heard()
    return answer
  } catch (error: unknown) {
    if (error instanceof MspError) {
      channel.liveness.heard()
    }
    throw error
  }
}

/**
 * A request with a deadline, refused at once while Muse Code is not
 * answering (the watchdog); a missed deadline counts toward that.
 */
async function requestWithin<T>(
  channel: CommandChannel,
  method: string,
  timeoutMs: number,
  request: () => Promise<T>,
): Promise<T> {
  if (channel.liveness.isUnresponsive) {
    channel.log.info(`${method} was not sent: Muse Code is not answering`)
    throw new Error(UI_TEXT.museCodeNotAnswering)
  }
  try {
    return await withDeadline(
      request(),
      timeoutMs,
      `Muse Code did not answer ${method} within ${String(Math.round(timeoutMs / MILLISECONDS_PER_SECOND))} s`,
    )
  } catch (error: unknown) {
    if (error instanceof DeadlineError) {
      channel.liveness.missed(method)
    }
    throw error
  }
}

/**
 * One MSP command with a deadline. `sessionNotLoaded` (the host evicted or
 * closed the session) becomes a `SessionNotLoadedError` the controller
 * answers by resuming the session.
 */
async function commandWithin(
  channel: CommandChannel,
  method: string,
  params: Record<string, unknown>,
  commandId: string = channel.connection.mintCommandId(),
): Promise<unknown> {
  const { log, timeouts } = channel
  const timeoutMs = MSP_LONG_COMMANDS.has(method) ? timeouts.longMs : timeouts.normalMs
  const startedAt = Date.now()
  try {
    const answer = await requestWithin(channel, method, timeoutMs, () =>
      sendCommand(channel, method, params, commandId),
    )
    log.trace(`${method} answered in ${String(Date.now() - startedAt)} ms`)
    return answer
  } catch (error: unknown) {
    log.trace(`${method} failed after ${String(Date.now() - startedAt)} ms`)
    const sessionId = params['sessionId']
    if (
      typeof sessionId === 'string' &&
      error instanceof MspError &&
      error.kind === SESSION_NOT_LOADED
    ) {
      throw new SessionNotLoadedError(sessionId, error.message)
    }
    throw error
  }
}

/** A process exit as the conversations see it (D25). */
export function describeExit(
  exit: { readonly code: number | null; readonly signal: string | null },
  isExpected: boolean,
): HostExit {
  if (exit.code === null) {
    return {
      description: fill(UI_TEXT.museStoppedBySignal, {
        signal: exit.signal ?? UI_TEXT.museUnknownSignal,
      }),
      isExpected,
      isPersistent: false,
    }
  }
  // Exit codes are ids, not amounts: no digit grouping.
  const code = String(exit.code)
  const meaning = Object.entries(UI_TEXT.museExitMeanings).find(([known]) => known === code)?.[1]
  return meaning === undefined
    ? {
        description: fill(UI_TEXT.museExitedWithCode, { code }),
        isExpected,
        isPersistent: false,
      }
    : {
        description: fill(UI_TEXT.museExitMeaning, { meaning, code }),
        isExpected,
        isPersistent: MUSE_EXIT_PERSISTENT_CODES.has(exit.code),
      }
}

export class MuseSession implements AgentSession {
  private readonly listeners = new Set<SessionEventListener>()
  /** One card per prompt and stage, and the open ones for a late listener (D26). */
  private readonly prompts = new PromptLedger()
  /** A stage's callers share its eventual result, and Stop waits for it. */
  private readonly decisionsInFlight = new Map<string, Promise<void>>()
  /**
   * What arrived before anyone listened (D26): the events right after
   * `session/resume` (the re-issued prompts, a running turn's stream) land
   * before the surface that asked for the session has attached. Held until
   * the first listener, released with the handle.
   */
  private early: AgentEvent[] | undefined = []
  /** The surfaces holding this handle (PLAN.md D25): the last release disposes it. */
  private holders = 1
  private isDisposed = false
  /** Told when Muse Code reports this session's event log failed (CLI recovery). */
  private readonly logDamagedListeners = new Set<() => void>()
  private readonly log: CoreLogger
  private readonly timeouts: CommandTimeouts

  public constructor(
    public readonly sessionId: string,
    public readonly modelId: string,
    private readonly channel: CommandChannel,
    private readonly onDispose: () => void,
    /** The host granted `userShell` at the handshake (M46): `!` commands may run. */
    private readonly canRunUserShell: boolean,
  ) {
    this.log = channel.log
    this.timeouts = channel.timeouts
  }

  /** One MSP command against this session with a freshly minted commandId. */
  private async command(method: string, params: Record<string, unknown>): Promise<unknown> {
    try {
      return await commandWithin(this.channel, method, { sessionId: this.sessionId, ...params })
    } catch (error: unknown) {
      this.noteLogFault(error)
      throw error
    }
  }

  /**
   * Muse Code 1.4.2 answers every message of a session whose event log
   * failed with that failure (the owner's session of 2026-10-02/03): the
   * conversation is told, which takes no new message in it after this.
   */
  private noteLogFault(error: unknown): void {
    if (!(error instanceof MspError) || !error.message.includes(MUSE_EVENT_LOG_FAULT)) {
      return
    }
    this.log.warn(
      `Muse Code reported session ${this.sessionId}'s event log failed (${failureForLog(error)}); the session takes no new message`,
    )
    for (const listener of this.logDamagedListeners) {
      listener()
    }
  }

  private finishDispose(): void {
    this.isDisposed = true
    this.listeners.clear()
    this.logDamagedListeners.clear()
    this.onDispose()
  }

  /**
   * A Stop under a multi-stage approval with a stage already decided rejects
   * its waiting stage first, through `approval/decide`: a turn cancelled
   * under such an approval leaves Muse Code 1.4.2 refusing every later
   * `turn/start` of the session (the `approvalReplay` fault, captured live
   * 2026-10-02), while one whose approval was rejected first runs on.
   */
  private async rejectPartlyDecided(): Promise<void> {
    // A click locks the stage before its command settles. Let the host's
    // answer and stage update land before deciding what Stop must reject.
    while (this.decisionsInFlight.size > 0) {
      await Promise.allSettled(this.decisionsInFlight.values())
    }
    for (const approval of this.prompts.partlyDecided()) {
      await this.rejectWaitingStage(approval.approvalId)
    }
  }

  private async rejectWaitingStage(approvalId: string): Promise<void> {
    for (let attempt = 0; attempt < APPROVAL_REJECT_ATTEMPTS; attempt += 1) {
      const approval = this.prompts.pending(approvalId)
      const reject = approval?.availableChoices.find(
        (choice) => choice.decision === REJECT_DECISION,
      )
      if (approval === undefined || reject === undefined) {
        return
      }
      this.log.info(
        `Stop: approval ${approvalId} stage ${String(approval.requirementId.sourceIndex)} is rejected before the turn stops`,
      )
      // Bounded: a Stop never waits long on a host that does not answer.
      const deadlineMs = Math.min(APPROVAL_REJECT_DEADLINE_MS, this.timeouts.normalMs)
      try {
        await withDeadline(
          this.decideApproval({
            approvalId,
            choiceId: reject.choiceId,
            requirementId: approval.requirementId,
          }),
          deadlineMs,
          `the reject before the Stop did not answer within ${String(deadlineMs)} ms`,
        )
        return
      } catch (error: unknown) {
        // A stage that moved on is now the ledger's: rejected on the next pass.
        if (!isPromptSettledError(error) || error.reason !== 'movedOn') {
          this.log.warn(
            `Stop: rejecting approval ${approvalId} failed: ${failureForLog(error)}; the turn stops anyway`,
          )
          return
        }
      }
    }
  }

  /** The single wire decision whose outcome every caller of this stage sees. */
  private async sendApprovalDecision(decision: ApprovalDecision): Promise<void> {
    const { approvalId, requirementId } = decision
    let ack: unknown
    try {
      ack = await this.command('approval/decide', {
        approvalId,
        choiceId: decision.choiceId,
        requirementId,
        ...(decision.feedback !== undefined && { feedback: decision.feedback }),
      })
    } catch (error: unknown) {
      throw await this.decisionFailed(requirementId, error)
    }
    // `terminal: true` closed the whole approval; a trailing stage update the
    // host can still send for it must not reopen the card (the facade's #37538).
    if (approvalDecideResultSchema.safeParse(ack).data?.terminal === true) {
      this.prompts.close(approvalId)
    }
  }

  /** What a failed `approval/decide` means for its card (PLAN.md D26). */
  private async decisionFailed(requirementId: RequirementRef, error: unknown): Promise<unknown> {
    const { approvalId } = requirementId
    if (error instanceof MspError && error.kind === REQUIREMENT_STALE) {
      // The stage moved on. The refusal names the stage the host waits on;
      // the card goes there when Muse Code does not say so itself.
      const waiting = requirementRefSchema.safeParse(error.data['currentRequirementId'])
      const update = waiting.success ? this.prompts.advanceTo(waiting.data) : undefined
      if (update !== undefined) {
        this.log.info(
          `Approval ${approvalId} stage ${String(requirementId.sourceIndex)} was stale; the card moves to stage ${String(update.requirementId.sourceIndex)}, where Muse Code waits`,
        )
        this.emit(update)
      }
      return settledOr(error)
    }
    const settled = settledOr(error)
    if (isPromptSettledError(settled)) {
      this.prompts.close(approvalId)
      return settled
    }
    const fault = faultOr(error, 'approvalLedger')
    if (fault !== error) {
      // The decision applied (#29, and every decision after the replay
      // fault); the card follows the host's resolve.
      return fault
    }
    // No answer (the deadline, a closed connection): the command may still
    // be queued in a busy Muse Code and apply later. On 2026-10-02 one sent
    // at 23:49:40 was taken in at 23:52:33, after two more for the same
    // stage, sent from a card reopened at each deadline, which it refused as
    // stale. The stage stays decided; the card follows the host's events.
    if (!(error instanceof MspError)) {
      this.log.info(
        `Approval ${approvalId} stage ${String(requirementId.sourceIndex)}: no answer; it may still apply, so it is not offered again`,
      )
      return error
    }
    if (await this.isStillWaiting(requirementId)) {
      this.prompts.unmarkDecided(requirementId)
      return new DecisionNotAppliedError(error.message)
    }
    return error
  }

  /**
   * Whether the host, which answered the decision with a refusal, still
   * waits on this very stage: then the decision did not apply and may be
   * made again. A check that fails cannot tell, and the stage stays decided.
   */
  private async isStillWaiting(requirementId: RequirementRef): Promise<boolean> {
    let pending: z.infer<typeof listPendingResultSchema>
    try {
      pending = listPendingResultSchema.parse(await this.command('approval/listPending', {}))
    } catch (error: unknown) {
      this.log.warn(`approval/listPending after a failed decision failed: ${failureForLog(error)}`)
      return false
    }
    return pending.approvals.some((params) => {
      const parsed = pendingStageSchema.safeParse(params)
      return (
        parsed.success &&
        parsed.data.approvalId === requirementId.approvalId &&
        parsed.data.currentRequirementId.sourceIndex === requirementId.sourceIndex
      )
    })
  }

  /**
   * What a failed `turn/steer` means for its message (CLI recovery,
   * 2026-10-03). On 2026-10-02 a steer Muse Code answered after the 60 s
   * deadline had been taken for a refusal and sent again as a new turn, and
   * Muse Code applied both. So only a refusal that says no turn was there is
   * a `SteerRefusedError`; no answer (the deadline, a closed connection) is
   * said as such; any other refusal keeps its own words.
   */
  private steerFailure(expectedTurnId: string, error: unknown): unknown {
    if (error instanceof MspError) {
      const reason = error.data['reason']
      const isNoTurn =
        typeof reason === 'string' &&
        error.kind === COMMAND_REJECTED &&
        MSP_STEER_NO_TURN_REASONS.has(reason)
      return isNoTurn ? new SteerRefusedError(error.message) : faultOr(error, 'approvalReplay')
    }
    if (error instanceof DeadlineError || error instanceof ProtocolError) {
      this.log.warn(
        `turn/steer into turn ${expectedTurnId} got no answer (${failureForLog(error)}); it may still reach the turn, so the message is not sent again`,
      )
      return new Error(UI_TEXT.steerUnconfirmed, { cause: error })
    }
    return error
  }

  /** Muse Code reported this session's event log failed (`noteLogFault`). */
  public onLogDamaged(listener: () => void): () => void {
    this.logDamagedListeners.add(listener)
    return () => {
      this.logDamagedListeners.delete(listener)
    }
  }

  /** One more surface holds this handle (a second panel resumed the same session). */
  public retain(): void {
    this.holders += 1
  }

  /**
   * The first listener gets what arrived before it; a later one (a second
   * surface on the same session) gets the prompts still open, which the
   * host will not announce again.
   */
  public onEvent(listener: SessionEventListener): () => void {
    this.listeners.add(listener)
    const backlog = this.early ?? this.prompts.open()
    this.early = undefined
    for (const event of backlog) {
      listener(isPendingPrompt(event) ? { ...event, isReplayed: true } : event)
    }
    return () => {
      this.listeners.delete(listener)
    }
  }

  /** @internal Called by the host dispatcher. */
  public receive(mapped: MappedNotification): void {
    if ('closedApprovalId' in mapped) {
      this.prompts.close(mapped.closedApprovalId)
      return
    }
    this.emit(mapped.event)
  }

  /** @internal An event for this session's listeners, once, in arrival order. */
  public emit(event: AgentEvent): void {
    if (this.isDisposed) {
      return
    }
    const admitted = this.prompts.admit(event)
    if (admitted === undefined) {
      return
    }
    if (this.early !== undefined) {
      this.early.push(admitted)
      return
    }
    for (const listener of this.listeners) {
      listener(admitted)
    }
  }

  /** Submit one user turn; queued behind a running turn by host default. */
  /**
   * Submit a turn. `displayText` is the transcript's presentation form of the
   * prompt (MSP: durable, never model-visible), used when the parts carry
   * more than the user typed (editor context, M5).
   */
  public async sendTurn(parts: readonly TurnPart[], displayText?: string): Promise<TurnSubmission> {
    let ack: unknown
    try {
      ack = await this.command('turn/start', {
        input: mspInput(parts),
        ...(displayText !== undefined && { displayText }),
      })
    } catch (error: unknown) {
      throw faultOr(error, 'approvalReplay')
    }
    const result = turnStartResultSchema.parse(ack)
    return { turnId: result.turnId, disposition: result.disposition ?? DEFAULT_DISPOSITION }
  }

  /**
   * Inject input into the turn believed to be running. The host rejects the
   * steer when that turn is no longer the running one, so input meant for one
   * turn never leaks into the next. That refusal is a `SteerRefusedError`,
   * after which the caller may send the input as a new turn; a steer with no
   * answer may still reach the turn, and fails in words that say so.
   */
  public async steer(expectedTurnId: string, parts: readonly TurnPart[]): Promise<TurnSubmission> {
    const input = mspInput(parts)
    let result: unknown
    try {
      result = await this.command('turn/steer', { expectedTurnId, input })
    } catch (error: unknown) {
      throw this.steerFailure(expectedTurnId, error)
    }
    return { turnId: turnSteerResultSchema.parse(result).turnId, disposition: 'steered' }
  }

  /** Ask the host to stop the running turn gracefully. */
  public async cancel(): Promise<void> {
    await this.rejectPartlyDecided()
    await this.command('turn/cancel', {})
  }

  /** Stop the running turn immediately. */
  public async interrupt(): Promise<void> {
    await this.rejectPartlyDecided()
    await this.command('turn/interrupt', {})
  }

  /** Durable model selection; applies from the next model call. */
  public async setModel(modelId: string): Promise<void> {
    await this.command('session/setModel', { model: { modelId } })
  }

  /** The session's standing reasoning-effort default (wire vocabulary). */
  public async setReasoningEffort(reasoningEffort: string): Promise<void> {
    await this.command('session/setReasoningEffort', { reasoningEffort })
  }

  /** Select one of the host's preconfigured approval modes. */
  public async setApprovalMode(mode: string): Promise<void> {
    try {
      await this.command('session/setApprovalMode', { mode })
    } catch (error: unknown) {
      throw ceilingOr(error)
    }
  }

  /** Summarise older context; `status` is `noop` with a reason when nothing to do. */
  public async compact(): Promise<CompactOutcome> {
    const result = compactResultSchema.parse(await this.command('session/compact', {}))
    return { status: result.status, reason: result.reason }
  }

  /**
   * Answer a gated tool call: one decision per stage (PLAN.md D26).
   * `requirementId` is the stage token from the request; a stale one is
   * rejected by the host, never silently applied. A second decision for a
   * stage already decided is not sent (a repeated click, a re-rendered card,
   * a second surface), nor one for a stage the approval has left.
   */
  public async decideApproval(decision: ApprovalDecision): Promise<void> {
    const { approvalId, requirementId } = decision
    const key = `${approvalId}\u{0}${String(requirementId.sourceIndex)}`
    const inFlight = this.decisionsInFlight.get(key)
    if (inFlight !== undefined) {
      await inFlight
      return
    }
    const stage = `approval ${approvalId} stage ${String(requirementId.sourceIndex)}`
    if (this.prompts.isClosed(approvalId)) {
      throw new PromptSettledError('alreadySettled', `${stage}: the approval is closed`)
    }
    if (this.prompts.isDecided(requirementId)) {
      this.log.info(`A second decision for ${stage} was not sent: one was sent already`)
      return
    }
    const waiting = this.prompts.pending(approvalId)?.requirementId
    if (waiting !== undefined && waiting.sourceIndex !== requirementId.sourceIndex) {
      // The card is behind the ledger: the update that moves it is on its way.
      this.log.info(
        `A decision for ${stage} was not sent: the approval waits on stage ${String(waiting.sourceIndex)}`,
      )
      throw new PromptSettledError('movedOn', `${stage}: the approval moved on`)
    }
    this.prompts.markDecided(requirementId)
    const pending = this.sendApprovalDecision(decision)
    this.decisionsInFlight.set(key, pending)
    try {
      await pending
    } finally {
      this.decisionsInFlight.delete(key)
    }
  }

  /** Answer every question of a `request_user_input` prompt. */
  public async answerQuestions(
    userInputId: string,
    answers: readonly QuestionAnswer[],
  ): Promise<void> {
    try {
      await this.command('userInput/answer', { userInputId, answers: [...answers] })
    } catch (error: unknown) {
      throw settledOr(error)
    }
  }

  /** Decline a `request_user_input` prompt (`userInput/cancel`, M16). */
  public async cancelQuestions(userInputId: string): Promise<void> {
    try {
      await this.command('userInput/cancel', { userInputId })
    } catch (error: unknown) {
      throw settledOr(error)
    }
  }

  /** Explain instead of choosing (`userInput/clarify`, M46): the model decides again. */
  public async clarifyQuestions(userInputId: string, text: string): Promise<void> {
    try {
      await this.command('userInput/clarify', {
        userInputId,
        clarification: { format: CLARIFICATION_FORMAT, content: text },
      })
    } catch (error: unknown) {
      throw settledOr(error)
    }
  }

  /** `task/background` (M46): the running tool call goes on without its turn waiting. */
  public async moveToBackground(taskId: string): Promise<void> {
    try {
      await this.command('task/background', { taskId })
    } catch (error: unknown) {
      throw taskRefusalOr(error)
    }
  }

  /** `task/stop` (M46): one background task, by its row's id. */
  public async stopTask(taskId: string): Promise<void> {
    try {
      await this.command('task/stop', { taskId })
    } catch (error: unknown) {
      throw taskRefusalOr(error)
    }
  }

  /** `task/stopAll` (M46): every background task; accepted over none too. */
  public async stopAllTasks(): Promise<void> {
    await this.command('task/stopAll', {})
  }

  /**
   * `session/userShell` (M46): the command runs at once, outside any turn;
   * its row and output arrive as a `userShell` item.
   */
  public async runUserShell(command: string): Promise<void> {
    if (!this.canRunUserShell) {
      throw new Error(UI_TEXT.userShellNotGranted)
    }
    await this.command('session/userShell', { commandText: command })
  }

  /** Captured owner verbs on a child (M18); M48's uncaptured verbs stay unavailable. */
  public async controlSubagent(subagentId: string, action: SubagentAction): Promise<void> {
    if (action === 'reopen' || action === 'readResult') {
      throw new Error(`subagent/${action}`)
    }
    await this.command(`subagent/${action}`, { subagentId })
  }

  /** `subagent/sendMessage` (a note while it runs) or `subagent/followupTask` (M18). */
  public async messageSubagent(
    subagentId: string,
    body: string,
    isFollowup: boolean,
  ): Promise<void> {
    await this.command(isFollowup ? 'subagent/followupTask' : 'subagent/sendMessage', {
      subagentId,
      body,
    })
  }

  /**
   * `goal/set`, `edit`, `pause`, `resume` or `clear` (M45, PLAN.md D38).
   * An idle set, edit or resume wakes a goal-driving turn, which then
   * arrives as its own `turn/started`; the goal arrives as
   * `session/goalChanged`.
   */
  public async controlGoal(command: GoalCommand): Promise<GoalCommandOutcome> {
    let ack: unknown
    try {
      ack = await this.command(
        `goal/${command.verb}`,
        command.verb === 'set' || command.verb === 'edit' ? { objective: command.objective } : {},
      )
    } catch (error: unknown) {
      throw goalRefusalOr(error)
    }
    return { turnId: goalCommandResultSchema.parse(ack).turnId }
  }

  /** One page of a stored tool output or patch document (`item/readOutput`). */
  public async readOutput(request: OutputPageRequest): Promise<OutputPage> {
    const result = await this.command('item/readOutput', {
      itemId: request.itemId,
      outputRef: request.outputRef,
      offsetBytes: request.offsetBytes,
      lengthBytes: request.lengthBytes,
    })
    const page = readOutputResultSchema.parse(result)
    if (page.encoding !== BASE64_ENCODING) {
      return page
    }
    // Binary media arrives base64 (tdd SS4.7.4): shown only if it is text after all.
    let text: string
    try {
      text = STRICT_UTF8.decode(Buffer.from(page.content, BASE64_ENCODING))
    } catch {
      throw new Error(`${UI_TEXT.outputIsBinary} (${page.mediaType})`)
    }
    return { ...page, content: text, encoding: UTF8_ENCODING }
  }

  /**
   * Set the durable session name; resolves to the canonical name the host
   * settled, or undefined when it will arrive as `session/nameChanged`.
   * Muse Code 1.3.0 refuses this on Windows (UnsupportedPlatform, PLAN.md M6).
   */
  public async rename(name: string): Promise<string | undefined> {
    const result = sessionRenameResultSchema.parse(await this.command('session/rename', { name }))
    return result.name
  }

  /** The user-invocable skills in this session's workspace and plugins. */
  public async listSkills(): Promise<readonly SkillSummary[]> {
    const result = await this.command('skill/list', {})
    return skillListResultSchema.parse(result).skills.map((skill) => ({
      selector: skill.selector,
      displayName: skill.displayName,
      description: skill.description,
      argumentHint: skill.argumentHint,
    }))
  }

  /** Releases this surface's hold; the last one forgets the session (D25). */
  public dispose(): void {
    if (this.isDisposed) {
      return
    }
    this.holders -= 1
    if (this.holders > 0) {
      return
    }
    // The CLI process can outlive this handle. Stop its work while the
    // connection is still open, even when the turn that started it has ended.
    void this.stopAllTasks().catch((error: unknown) => {
      this.log.warn(
        `task/stopAll before releasing session ${this.sessionId} failed: ${failureForLog(error)}`,
      )
    })
    this.finishDispose()
  }

  /** The host is closing: the handle goes whoever still holds it. */
  public disposeAll(): void {
    if (this.isDisposed) {
      return
    }
    // The process has already closed, so there is no session command to send.
    this.holders = 0
    this.finishDispose()
  }
}

export class MuseCodeHost implements AgentHost {
  private readonly sessions = new Map<string, MuseSession>()
  private readonly exitListeners = new Set<(exit: HostExit) => void>()
  private readonly listListeners = new Set<(event: SessionListEvent) => void>()
  private readonly usageListeners = new Set<(usage: SubscriptionUsage) => void>()
  /** Set by `close()`: the exit that follows is the extension's, not a crash (D25). */
  private isClosing = false
  /**
   * Session starts, resumes and forks in flight (D26). The SDK hands every
   * frame of one read to the handlers before the awaiting command resumes,
   * so the prompts re-issued right after a resume answer arrive before the
   * handle exists. While one is in flight, events for an unknown session
   * wait here for `track`.
   */
  private opening = 0
  private readonly unclaimed = new Map<string, MappedNotification[]>()
  /** Methods already logged as unshown or malformed: one line each per host (D26). */
  private readonly loggedMethods = new Set<string>()
  /** Told once each time Muse Code stops answering (the watchdog, CLI recovery). */
  private readonly unresponsiveListeners = new Set<() => void>()
  /** The deadlines, log and watchdog every command on this connection shares. */
  private readonly channel: CommandChannel
  public readonly info: MuseHostInfo

  public constructor(
    private readonly host: MspHost,
    private readonly log: CoreLogger,
    private readonly timeouts: CommandTimeouts = DEFAULT_TIMEOUTS,
  ) {
    this.channel = {
      connection: host.connection,
      timeouts,
      log,
      liveness: new HostLiveness(
        timeouts.unresponsiveSilenceMs ?? MSP_UNRESPONSIVE_SILENCE_MS,
        log,
        () => {
          for (const listener of this.unresponsiveListeners) {
            listener()
          }
        },
      ),
    }
    const parsed = initializeResultSchema.parse(host.initializeResult)
    const serverVersion = parsed.serverInfo.version
    this.info = {
      kind: 'museCode',
      serverName: parsed.serverInfo.name,
      serverVersion,
      museHome: parsed.museHome,
      grantedCapabilities: parsed.grantedCapabilities ?? [],
      // Muse Code refuses `session/rename` and `session/fork` on Windows
      // (meta-models/muse-code-sdk#30, #31): verified on 1.3.0 (2026-09-22)
      // and 1.4.0 (2026-09-27). No release has fixed them, so every version
      // is limited there until one is verified (D26). A 1.3.0 ceiling showed
      // the failing actions again on 1.4.0 (0.9.1, release-0.9.1.md).
      canEditSessions: parsed.platformOs !== WINDOWS_OS,
    }
    this.log.info(
      `MSP host on ${parsed.platformOs ?? 'an unreported OS'}, schema v${String(parsed.schema?.version ?? 'unreported')} ${parsed.schema?.fingerprint ?? ''}, sessions ${parsed.sessionDurability ?? DURABLE_SESSIONS}`,
    )
    if (parsed.sessionDurability !== undefined && parsed.sessionDurability !== DURABLE_SESSIONS) {
      this.log.warn(
        `This muse serve keeps ${parsed.sessionDurability} sessions: History and resume will not find them after it exits, and Muse Code 1.3.0 sent such a host's turns to no client (PLAN.md D43)`,
      )
    }
    // The SDK's connection keeps one handler; a throw inside it would end the
    // read loop and leave the connection deaf without a word (D25).
    host.connection.onNotification((notification) => {
      this.channel.liveness.heard()
      try {
        this.dispatch(notification)
      } catch (error: unknown) {
        this.log.error(`MSP ${notification.method} could not be handled: ${String(error)}`)
      }
    })
    host.connection.onServerRequest((request) => {
      this.channel.liveness.heard()
      return this.serverRequest(request)
    })
    // A dropped or unreadable frame is logged by kind, never with its content.
    host.connection.onProtocolError((error) => {
      this.log.warn(`MSP protocol error: ${error.message}`)
    })
    // A connection that ends while the process lives (a framing violation)
    // is as good as dead: the process is closed so the exit is reported.
    void host.connection.closed.then(() => {
      if (this.isClosing) {
        return
      }
      this.log.warn('The MSP connection closed while muse serve was running; closing it')
      void this.host.close()
    })
    void host.exited.then((exit) => {
      const described = describeExit(exit, this.isClosing)
      if (described.isExpected) {
        this.log.info(`muse serve exited as asked (${described.description})`)
      } else {
        this.log.warn(`muse serve exited (${described.description})`)
      }
      for (const listener of this.exitListeners) {
        listener(described)
      }
    })
  }

  /** One notification: a host-level event, or a session's. */
  private dispatch(notification: WireNotification): void {
    if (this.dispatchHostEvent(notification.method, notification.params)) {
      return
    }
    this.deliver(notification)
  }

  /** A session's notification to its handle; false when nothing can show it. */
  private deliver(notification: WireNotification, isReplay = false): boolean {
    const mapped = mapNotification(notification)
    if (mapped === UNKNOWN_METHOD || mapped === MALFORMED_PARAMS) {
      this.noteUnmapped(notification.method, mapped)
      return false
    }
    const admitted: MappedNotification =
      isReplay && 'event' in mapped && isPendingPrompt(mapped.event)
        ? { ...mapped, event: { ...mapped.event, isReplayed: true } }
        : mapped
    const session = this.sessions.get(admitted.sessionId)
    if (session !== undefined) {
      session.receive(admitted)
      return true
    }
    if (this.opening > 0) {
      const waiting = this.unclaimed.get(admitted.sessionId) ?? []
      waiting.push(admitted)
      this.unclaimed.set(admitted.sessionId, waiting)
      return true
    }
    this.log.warn(`MSP event ${notification.method} for unknown session ${admitted.sessionId}`)
    return false
  }

  /** Once per method: the extension does not show it, or it failed its schema. */
  private noteUnmapped(
    method: string,
    outcome: typeof UNKNOWN_METHOD | typeof MALFORMED_PARAMS,
  ): void {
    if (this.loggedMethods.has(method)) {
      return
    }
    this.loggedMethods.add(method)
    if (outcome === MALFORMED_PARAMS) {
      this.log.warn(`MSP ${method} had an unexpected shape and was ignored (logged once)`)
    } else {
      this.log.info(`MSP ${method} is not shown by this extension (logged once)`)
    }
  }

  /** A server request: a prompt shown as the notification it mirrors, answered with the receipt. */
  private serverRequest(request: {
    readonly method: string
    readonly params?: Record<string, unknown> | undefined
  }): Promise<Record<string, unknown>> {
    const mirrored = PROMPT_SERVER_REQUESTS.get(request.method)
    if (mirrored === undefined) {
      this.log.warn(`Unsupported MSP server request ${request.method}; refusing`)
      return Promise.reject(
        new MspError({
          code: JSON_RPC_ERRORS.methodNotFound,
          message: `method not found: ${request.method}`,
          data: { kind: 'methodNotFound' },
        }),
      )
    }
    return this.deliver({ method: mirrored, params: request.params })
      ? Promise.resolve(PRESENTED)
      : Promise.reject(new Error(`no surface can show ${request.method}`))
  }

  /**
   * Runs a session start, resume or fork with early events held for its
   * handle (D26); whatever no handle claimed by the end is logged and dropped.
   */
  private async opened<T>(open: () => Promise<T>): Promise<T> {
    this.opening += 1
    try {
      return await open()
    } finally {
      this.opening -= 1
      if (this.opening === 0) {
        for (const [sessionId, waiting] of this.unclaimed) {
          this.log.warn(
            `${String(waiting.length)} MSP events for session ${sessionId} arrived while it was opening and no handle claimed them`,
          )
        }
        this.unclaimed.clear()
      }
    }
  }

  private async command(method: string, params: Record<string, unknown>): Promise<unknown> {
    return await commandWithin(this.channel, method, params)
  }

  /**
   * Host-level notifications bypass the per-session routing: the list
   * stream (`sessionListStream` grant) is about stored sessions, loaded here
   * or not, and `usage/changed` is about the account. True when the method
   * was one of them.
   */
  private dispatchHostEvent(method: string, params: unknown): boolean {
    if (method === USAGE_CHANGED) {
      const parsed = subscriptionUsageSchema.safeParse(params)
      if (parsed.success) {
        for (const listener of this.usageListeners) {
          listener(parsed.data)
        }
      } else {
        this.warnShape(method)
      }
      return true
    }
    if (method !== SESSION_LIST_CHANGED && method !== SESSION_CLOSED) {
      return false
    }
    const event = this.parseListEvent(method, params)
    if (event === undefined) {
      this.warnShape(method)
      return true
    }
    for (const listener of this.listListeners) {
      listener(event)
    }
    return true
  }

  private warnShape(method: string): void {
    this.log.warn(`MSP ${method} had an unexpected shape; ignored`)
  }

  private parseListEvent(method: string, params: unknown): SessionListEvent | undefined {
    if (method === SESSION_LIST_CHANGED) {
      const parsed = sessionListChangedSchema.safeParse(params)
      return parsed.success ? { type: 'changed', record: parsed.data.session } : undefined
    }
    const parsed = sessionClosedSchema.safeParse(params)
    return parsed.success
      ? { type: 'closed', sessionId: parsed.data.sessionId, reason: parsed.data.reason }
      : undefined
  }

  /** Registers the handle for a session this connection now holds. */
  private track(record: { readonly sessionId: string }, modelId: string): MuseSession {
    const existing = this.sessions.get(record.sessionId)
    if (existing !== undefined) {
      // A second surface on the same session: closing one must not deafen the other.
      existing.retain()
      return existing
    }
    const handle = new MuseSession(
      record.sessionId,
      modelId,
      this.channel,
      () => {
        this.sessions.delete(record.sessionId)
      },
      this.info.grantedCapabilities.includes(MSP_USER_SHELL_CAPABILITY),
    )
    this.sessions.set(record.sessionId, handle)
    const waiting = this.unclaimed.get(record.sessionId) ?? []
    for (const mapped of waiting) {
      handle.receive(mapped)
    }
    this.unclaimed.delete(record.sessionId)
    return handle
  }

  private loaded(envelope: SessionEnvelope, modelId: string): LoadedSession {
    return {
      session: this.track(envelope.session, modelId),
      record: envelope.session,
      history: historyOutcome(envelope),
      activeTurnId: envelope.session.activeTurnId ?? undefined,
    }
  }

  /**
   * The pending prompts a resume's pointers name, pulled with
   * `approval/listPending` (the documented dual of the re-issued requests,
   * tdd SS5.7), so the cards appear however the re-issue was delivered; the
   * ledger shows each once (D26).
   */
  private async presentPending(sessionId: string): Promise<void> {
    try {
      const pending = listPendingResultSchema.parse(
        await this.command('approval/listPending', { sessionId }),
      )
      for (const params of pending.approvals) {
        this.deliver({ method: 'approval/requested', params }, true)
      }
      for (const params of pending.userInputs) {
        this.deliver({ method: 'userInput/requested', params })
      }
    } catch (error: unknown) {
      this.log.warn(
        `approval/listPending after resuming ${sessionId} failed: ${failureForLog(error)}`,
      )
    }
  }

  private mcpConfig(
    mcpServers: Readonly<Record<string, SessionMcpServer>> | undefined,
  ): Record<string, unknown> {
    if (mcpServers === undefined) {
      return {}
    }
    return {
      config: {
        mcpServers: Object.fromEntries(
          Object.entries(mcpServers).map(([name, server]) => [
            name,
            // `optional`: a tool-server hiccup never blocks the session.
            'command' in server
              ? {
                  transport: 'stdio',
                  command: server.command,
                  args: server.args,
                  env: server.env,
                  mode: 'optional',
                }
              : {
                  transport: 'streamableHttp',
                  url: server.url,
                  headers: server.headers,
                  mode: 'optional',
                },
          ]),
        ),
      },
    }
  }

  /** Last durable goal event at the view head; an empty history means no goal. */
  private async goalFromView(sessionId: string): Promise<SessionGoal | null> {
    let cursor: string | undefined
    for (let page = 0; page < GOAL_RECOVERY_MAX_PAGES; page += 1) {
      const raw = await requestWithin(this.channel, VIEW_PAGE, this.timeouts.normalMs, () =>
        answered(this.channel, VIEW_PAGE, {
          sessionId,
          limit: GOAL_RECOVERY_PAGE_LIMIT,
          direction: 'backward',
          ...(cursor !== undefined && { cursor }),
        }),
      )
      const result = viewPageResultSchema.parse(raw)
      for (const frame of result.events.toReversed()) {
        if (frame.method !== 'session/goalChanged') {
          continue
        }
        const mapped = mapNotification(frame)
        if (
          typeof mapped === 'string' ||
          !('event' in mapped) ||
          mapped.sessionId !== sessionId ||
          mapped.event.type !== 'goalChanged'
        ) {
          throw new Error('Muse Code returned an invalid goal event in view history')
        }
        return mapped.event.goal
      }
      if (result.nextCursor === null) {
        return null
      }
      if (result.nextCursor === cursor) {
        throw new Error('Muse Code repeated a view history cursor')
      }
      cursor = result.nextCursor
    }
    throw new Error('Muse Code view history exceeded the goal recovery limit')
  }

  public onExit(listener: (exit: HostExit) => void): () => void {
    this.exitListeners.add(listener)
    return () => {
      this.exitListeners.delete(listener)
    }
  }

  /**
   * Told once each time Muse Code stops answering (the watchdog): commands
   * missed their deadlines and nothing came from it for a while. It answers
   * again on its own only if a frame arrives; the window restarts it.
   */
  public onUnresponsive(listener: () => void): () => void {
    this.unresponsiveListeners.add(listener)
    return () => {
      this.unresponsiveListeners.delete(listener)
    }
  }

  /** The subscription window the CLI last observed; absent until a turn has run. */
  public async readUsage(): Promise<SubscriptionUsage | undefined> {
    const result = await this.command(USAGE_READ, {})
    return usageReadResultSchema.parse(result).usage
  }

  public onUsageChanged(listener: (usage: SubscriptionUsage) => void): () => void {
    this.usageListeners.add(listener)
    return () => {
      this.usageListeners.delete(listener)
    }
  }

  /** Stored-session changes on this host (needs the `sessionListStream` grant). */
  public onSessionListEvent(listener: (event: SessionListEvent) => void): () => void {
    this.listListeners.add(listener)
    return () => {
      this.listListeners.delete(listener)
    }
  }

  /** One page of this workspace's stored sessions, newest activity first. */
  public async listSessions(options: ListSessionsOptions): Promise<SessionPage> {
    const result = await this.command('session/list', {
      workspaceRoot: options.workspaceRoot,
      limit: Math.min(options.limit, MSP_SESSION_LIST_MAX_LIMIT),
      ...(options.cursor !== undefined && { cursor: options.cursor }),
    })
    const page = sessionListResultSchema.parse(result)
    return { sessions: page.sessions, nextCursor: page.nextCursor ?? undefined }
  }

  /**
   * Load a stored session on this connection with its history as a folded
   * snapshot where the host's budget allows (the served mode is reported):
   * the items, and the name, todo list and goal beside them (M45).
   * `modelId` is the caller's standing selection: the record's own
   * `modelId` is the metadata fold's and not to be trusted (PLAN.md M6).
   */
  public async resumeSession(
    sessionId: string,
    modelId: string,
    mcpServers?: Readonly<Record<string, SessionMcpServer>>,
  ): Promise<LoadedSession> {
    const { loaded, hasPending } = await this.opened(async () => {
      const envelope = sessionEnvelopeSchema.parse(
        await this.command('session/resume', {
          sessionId,
          history: HISTORY_PREFERENCE_SNAPSHOT,
          ...this.mcpConfig(mcpServers),
        }),
      )
      return {
        loaded: this.loaded(envelope, modelId),
        hasPending: (envelope.pendingRequests ?? []).length > 0,
      }
    })
    if (hasPending) {
      await this.presentPending(sessionId)
    }
    if (loaded.history.goal === undefined) {
      try {
        return {
          ...loaded,
          history: { ...loaded.history, goal: await this.goalFromView(sessionId) },
        }
      } catch {
        // A page failure must not strand an attached session after resume.
        this.log.warn('Muse Code could not recover the goal from view history after resume')
      }
    }
    return loaded
  }

  /** A point-in-time read with items, without loading the session. */
  public async readSession(
    sessionId: string,
    options?: { readonly recoverGoal?: boolean },
  ): Promise<SessionHistoryOutcome> {
    const result = await this.command('session/read', {
      sessionId,
      excludeItems: false,
    })
    const history = historyOutcome(sessionEnvelopeSchema.parse(result))
    return options?.recoverGoal === true && history.goal === undefined
      ? { ...history, goal: await this.goalFromView(sessionId) }
      : history
  }

  /**
   * Copy a session's completed turns (through `lastTurnId`, or all of them)
   * into a new session, loaded here. Muse Code 1.3.0 refuses this on
   * Windows ("invalid fork boundary ... WriteFailed", PLAN.md M6).
   */
  public async forkSession(
    sessionId: string,
    modelId: string,
    lastTurnId?: string,
  ): Promise<LoadedSession> {
    if (!this.info.canEditSessions) {
      throw new Error(UI_TEXT.sessionEditsUnsupported)
    }
    return await this.opened(async () => {
      const result = await this.command('session/fork', {
        sessionId,
        ...(lastTurnId !== undefined && { cutPoint: { lastTurnId } }),
      })
      return this.loaded(sessionEnvelopeSchema.parse(result), modelId)
    })
  }

  /** The visible model catalogue; with a session id the active row is flagged. */
  public async listModels(sessionId?: string): Promise<readonly ModelSummary[]> {
    const result = await this.command('model/list', {
      ...(sessionId !== undefined && { sessionId }),
    })
    return modelListResultSchema.parse(result).models.map((model) => ({
      modelId: model.modelId,
      displayLabel: model.displayLabel,
      contextLimit: model.contextLimit ?? undefined,
      isDefault: model.isDefault,
      isActive: model.isActive ?? false,
    }))
  }

  public async startSession(options: StartSessionOptions): Promise<MuseSession> {
    return await this.opened(async () => {
      let result: unknown
      try {
        result = await this.command('session/start', {
          workspaceRoot: options.workspaceRoot,
          modelId: options.modelId,
          approvalMode: options.approvalMode,
          ...this.mcpConfig(options.mcpServers),
        })
      } catch (error: unknown) {
        throw ceilingOr(error)
      }
      const { session } = sessionStartResultSchema.parse(result)
      return this.track(session, session.modelId ?? options.modelId)
    })
  }

  public get sessionCount(): number {
    return this.sessions.size
  }

  public async close(): Promise<void> {
    // The exit that follows is the extension's own (D25).
    this.isClosing = true
    // Close the process first: the host emits session/statusChanged for every
    // loaded session on the way down, and those must still find their session.
    await this.host.close()
    for (const session of this.sessions.values()) {
      session.disposeAll()
    }
  }
}

src/core/backends/musecode/museConfigVie:
// What Muse Code will load from its own settings file, read-only (M31,
// PLAN.md D30; the extension never writes that file, D17): the MCP servers
// and the hook sources. MSP has no method for either.
//
// Two spellings exist. Meta's docs show `mcp_servers` with `transport`; the
// 1.3.0 binary's own migrate skill writes `mcpServers` with `type` and calls
// `mcp_servers` legacy, and records two faults that make Muse drop every
// user MCP server while the rest of the settings still apply: both keys in
// one file, and `required` beside `mode` on one server. Both spellings are
// read and both faults reported.
//
// Nothing secret is shown: `env` and `headers` are reduced to their names
// and a URL to its scheme and host. The Model API backend (M50, PLAN.md D42)
// starts the same servers from the same reading: `readMcpServerEntries`
// hands it each entry whole beside its view, and the view stays secret-free.
//
// Pure: the host reads the file and shows the view.

import path from 'node:path'
import { MCP_TRANSPORTS, UI_TEXT } from '../../../shared/constants'

const CAMEL_KEY = 'mcpServers'
const LEGACY_KEY = 'mcp_servers'
const HOOKS_KEY = 'hooks'
const MANAGED_HOOKS_KEY = 'managed_hooks_path'
const STDIO = MCP_TRANSPORTS.stdio
const STREAMABLE_HTTP = MCP_TRANSPORTS.streamableHttp
const HTTP_TRANSPORTS: ReadonlySet<string> = new Set(['streamable-http', 'streamable_http', 'http'])
const OPTIONAL_MODE = 'optional'
const REQUIRED_MODE = 'required'

export interface McpServerView {
  readonly name: string
  /** `stdio`, `streamable-http`, or the file's own word for anything else. */
  readonly transport: string
  /** The command's file name, or the URL's scheme and host. */
  readonly target: string
  /** What Muse Code's startup gate reads: only `mode: "optional"` is optional. */
  readonly mode: typeof OPTIONAL_MODE | typeof REQUIRED_MODE
  readonly isEnabled: boolean
  /** Only the names; the values stay in the file. */
  readonly envNames: readonly string[]
  readonly headerNames: readonly string[]
  /** `required` and `mode` both set: Muse drops every user server for it. */
  readonly hasModeConflict: boolean
}

export type McpSettingsView =
  | { readonly status: 'missing' }
  | { readonly status: 'unreadable'; readonly reason: string }
  | {
      readonly status: 'read'
      readonly servers: readonly McpServerView[]
      /** Both `mcpServers` and `mcp_servers`: Muse loads neither. */
      readonly hasKeyConflict: boolean
      /** Every server comes from the legacy `mcp_servers` key. */
      readonly isLegacy: boolean
    }

/** One server as the file holds it: its view, and the entry itself, secrets included. */
export interface McpServerEntry {
  readonly view: McpServerView
  readonly entry: Readonly<Record<string, unknown>>
}

/** `McpSettingsView` with each server's whole entry (M50); never shown. */
export type McpSettingsEntries =
  | { readonly status: 'missing' }
  | { readonly status: 'unreadable'; readonly reason: string }
  | {
      readonly status: 'read'
      readonly entries: readonly McpServerEntry[]
      readonly hasKeyConflict: boolean
      readonly isLegacy: boolean
    }

export interface HookSourcesView {
  /** Hooks in the settings file's own `hooks` block; undefined when there is none. */
  readonly userHookCount: number | undefined
  /** `managed_hooks_path`, when the settings name one. */
  readonly managedHooksPath: string | undefined
}

type JsonObject = Readonly<Record<string, unknown>>

function isObject(value: unknown): value is JsonObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function stringField(entry: JsonObject, key: string): string | undefined {
  const value = entry[key]
  return typeof value === 'string' ? value : undefined
}

function namesOf(value: unknown): readonly string[] {
  return isObject(value) ? Object.keys(value) : []
}

function transportOf(entry: JsonObject): string {
  const declared = stringField(entry, 'type') ?? stringField(entry, 'transport')
  if (declared === undefined) {
    // Claude Code's and Muse's convention: a bare command is stdio.
    return entry['url'] === undefined ? STDIO : STREAMABLE_HTTP
  }
  return HTTP_TRANSPORTS.has(declared) ? STREAMABLE_HTTP : declared
}

/** `https://host`, never a path, query or credentials. */
function urlTarget(url: string): string {
  try {
    const parsed = new URL(url)
    return `${parsed.protocol}//${parsed.host}`
  } catch {
    return UI_TEXT.mcpInvalidUrl
  }
}

function commandTarget(command: unknown): string {
  const first: unknown = Array.isArray(command) ? command[0] : command
  if (typeof first !== 'string' || first === '') {
    return UI_TEXT.mcpNoCommand
  }
  // A Windows path's separators are read on every platform.
  return path.win32.basename(path.posix.basename(first))
}

function serverView(name: string, entry: JsonObject): McpServerView {
  const transport = transportOf(entry)
  const url = stringField(entry, 'url')
  return {
    name,
    transport,
    target: transport === STREAMABLE_HTTP ? urlTarget(url ?? '') : commandTarget(entry['command']),
    mode: stringField(entry, 'mode') === OPTIONAL_MODE ? OPTIONAL_MODE : REQUIRED_MODE,
    isEnabled: entry['enabled'] !== false,
    envNames: namesOf(entry['env']),
    headerNames: namesOf(entry['headers']),
    hasModeConflict: 'required' in entry && 'mode' in entry,
  }
}

function parsed(text: string): JsonObject | string {
  let value: unknown
  try {
    value = JSON.parse(text)
  } catch (error: unknown) {
    return error instanceof Error ? error.message : String(error)
  }
  return isObject(value) ? value : 'the file does not hold a JSON object'
}

/** Each server the settings file declares, whole; `text` undefined when there is no file. */
export function readMcpServerEntries(text: string | undefined): McpSettingsEntries {
  if (text === undefined) {
    return { status: 'missing' }
  }
  const settings = parsed(text)
  if (typeof settings === 'string') {
    return { status: 'unreadable', reason: settings }
  }
  const camel = settings[CAMEL_KEY]
  const legacy = settings[LEGACY_KEY]
  const entries = [camel, legacy].flatMap((block) =>
    isObject(block)
      ? Object.entries(block).flatMap(([name, entry]) =>
          isObject(entry) ? [{ view: serverView(name, entry), entry }] : [],
        )
      : [],
  )
  return {
    status: 'read',
    entries,
    hasKeyConflict: camel !== undefined && legacy !== undefined,
    isLegacy: camel === undefined && legacy !== undefined,
  }
}

/** The MCP servers the settings file declares; `text` undefined when there is no file. */
export function readMcpServers(text: string | undefined): McpSettingsView {
  const read = readMcpServerEntries(text)
  if (read.status !== 'read') {
    return read
  }
  const { entries, hasKeyConflict, isLegacy } = read
  return { status: 'read', servers: entries.map(({ view }) => view), hasKeyConflict, isLegacy }
}

function hookCount(block: unknown): number | undefined {
  if (Array.isArray(block)) {
    return block.length
  }
  return isObject(block) ? Object.keys(block).length : undefined
}

/** The hook sources the settings file names; nothing when it is missing or unreadable. */
export function readHookSources(text: string | undefined): HookSourcesView {
  const settings = text === undefined ? undefined : parsed(text)
  if (settings === undefined || typeof settings === 'string') {
    return { userHookCount: undefined, managedHooksPath: undefined }
  }
  const managed = stringField(settings, MANAGED_HOOKS_KEY)
  return {
    userHookCount: hookCount(settings[HOOKS_KEY]),
    managedHooksPath: managed === undefined || managed === '' ? undefined : managed,
  }
}

// Which approvals and questions a Muse Code session has put on screen
// (PLAN.md D26). The host announces a live prompt twice, as the
// `approval/requested` / `userInput/requested` notification and as its
// `approval/request` / `userInput/request` server-request mirror, and again
// after every `session/resume` (the re-issued server request), while a
// decision the host acknowledged as terminal can still be followed by one
// trailing stage update (the SDK facade's #37538 note). The ledger lets one
// card through per prompt and per stage, none once the approval closed, and
// keeps the open ones so a surface that starts listening late sees them too.
//
// It also holds the decisions sent: one per stage (a second one for the
// same stage is never sent, whichever card or surface it comes from), so a
// Stop knows which approvals are part decided (MuseSession.cancel).

import type { AgentEvent, RequirementRef } from '../../../shared/agentEvents'

type ApprovalRequested = Extract<AgentEvent, { type: 'approvalRequested' }>
type ApprovalUpdated = Extract<AgentEvent, { type: 'approvalUpdated' }>
type QuestionRequested = Extract<AgentEvent, { type: 'questionRequested' }>

function stageKey(requirementId: RequirementRef): string {
  return `${requirementId.approvalId}\u{0}${String(requirementId.sourceIndex)}`
}

/** The stage's own "Always allow" label, when the subject lists stages. */
function prefixLabel(approval: ApprovalRequested, sourceIndex: number): string | undefined {
  return approval.subject.stages?.find((stage) => stage.requirementId.sourceIndex === sourceIndex)
    ?.suggestedPrefix?.label
}

export class PromptLedger {
  /** Open approvals as their card now reads (the request with its latest stage). */
  private readonly approvals = new Map<string, ApprovalRequested>()
  private readonly questions = new Map<string, QuestionRequested>()
  /** Approvals the host closed: on our terminal decision, or `alreadyTerminal`. */
  private readonly closed = new Set<string>()
  /** Stages a decision was sent for (in flight or accepted), by `stageKey`. */
  private readonly decided = new Set<string>()

  /** An approval request arriving: new, the next stage of one shown, or a repeat. */
  private requested(event: ApprovalRequested): AgentEvent | undefined {
    if (this.closed.has(event.approvalId)) {
      return undefined
    }
    const shown = this.approvals.get(event.approvalId)
    this.approvals.set(event.approvalId, event)
    if (shown === undefined) {
      return event
    }
    if (stageKey(shown.requirementId) === stageKey(event.requirementId)) {
      return undefined
    }
    // A re-issued request for the next stage refreshes the card already shown.
    return {
      type: 'approvalUpdated',
      approvalId: event.approvalId,
      requirementId: event.requirementId,
      subject: event.subject,
      availableChoices: event.availableChoices,
    }
  }

  private updated(event: ApprovalUpdated): AgentEvent | undefined {
    if (this.closed.has(event.approvalId)) {
      return undefined
    }
    const shown = this.approvals.get(event.approvalId)
    if (shown !== undefined) {
      this.approvals.set(event.approvalId, {
        ...shown,
        requirementId: event.requirementId,
        subject: event.subject,
        availableChoices: event.availableChoices,
      })
    }
    return event
  }

  private forget(approvalId: string): void {
    this.approvals.delete(approvalId)
    for (const key of this.decided) {
      if (key.startsWith(`${approvalId}\u{0}`)) {
        this.decided.delete(key)
      }
    }
  }

  /** The host closed this approval; any later stage for it is stale. */
  public close(approvalId: string): void {
    this.closed.add(approvalId)
  }

  public isClosed(approvalId: string): boolean {
    return this.closed.has(approvalId)
  }

  /** An open approval as its card reads now (its current stage and choices); undefined when none. */
  public pending(approvalId: string): ApprovalRequested | undefined {
    return this.closed.has(approvalId) ? undefined : this.approvals.get(approvalId)
  }

  /** Whether a decision was already sent for this stage. */
  public isDecided(requirementId: RequirementRef): boolean {
    return this.decided.has(stageKey(requirementId))
  }

  public markDecided(requirementId: RequirementRef): void {
    this.decided.add(stageKey(requirementId))
  }

  /** The decision did not apply (the host still waits on this stage): it may be made again. */
  public unmarkDecided(requirementId: RequirementRef): void {
    this.decided.delete(stageKey(requirementId))
  }

  /**
   * The card moved to the stage a stale refusal named (MSP's
   * `currentRequirementId`), when Muse Code announces none itself: after an
   * "Always allow" rule, 1.4.2 can resolve the stage it shows by that rule
   * and wait on the next one without an `approval/updated` (captured
   * 2026-10-02). A choice tied to the old stage's rule takes the new stage's
   * label, or goes when that stage suggests no rule. The update is admitted
   * like the host's own (`admit`), which moves the ledger with the card.
   */
  public advanceTo(requirementId: RequirementRef): ApprovalUpdated | undefined {
    const shown = this.approvals.get(requirementId.approvalId)
    if (
      shown === undefined ||
      this.closed.has(requirementId.approvalId) ||
      stageKey(shown.requirementId) === stageKey(requirementId)
    ) {
      return undefined
    }
    const oldLabel = prefixLabel(shown, shown.requirementId.sourceIndex)
    const newLabel = prefixLabel(shown, requirementId.sourceIndex)
    const availableChoices = shown.availableChoices.flatMap((choice) => {
      const isStageRule =
        oldLabel !== undefined && (choice.label === oldLabel || choice.rulePreview === oldLabel)
      if (!isStageRule) {
        return [choice]
      }
      return newLabel === undefined ? [] : [{ ...choice, label: newLabel, rulePreview: newLabel }]
    })
    return {
      type: 'approvalUpdated',
      approvalId: requirementId.approvalId,
      requirementId,
      subject: shown.subject,
      availableChoices,
    }
  }

  /**
   * Open approvals with a stage already decided and the current one not:
   * stopping the turn under one of them leaves Muse Code 1.4.2 unable to run
   * the session again (the `approvalReplay` fault), so a Stop rejects them
   * first.
   */
  public partlyDecided(): readonly ApprovalRequested[] {
    const decidedApprovals = new Set<string>()
    for (const key of this.decided) {
      decidedApprovals.add(key.slice(0, key.indexOf('\u{0}')))
    }
    const waiting: ApprovalRequested[] = []
    for (const approval of this.approvals.values()) {
      if (
        decidedApprovals.has(approval.approvalId) &&
        !this.closed.has(approval.approvalId) &&
        !this.decided.has(stageKey(approval.requirementId))
      ) {
        waiting.push(approval)
      }
    }
    return waiting
  }

  /** The event to show for one arriving from the host, or undefined for a repeat. */
  public admit(event: AgentEvent): AgentEvent | undefined {
    switch (event.type) {
      case 'approvalRequested': {
        return this.requested(event)
      }
      case 'approvalUpdated': {
        return this.updated(event)
      }
      case 'approvalResolved': {
        this.forget(event.approvalId)
        this.closed.delete(event.approvalId)
        return event
      }
      case 'questionRequested': {
        if (this.questions.has(event.userInputId)) {
          return undefined
        }
        this.questions.set(event.userInputId, event)
        return event
      }
      case 'questionSettled': {
        this.questions.delete(event.userInputId)
        return event
      }
      default: {
        return event
      }
    }
  }

  /** The prompts still waiting, as a surface that starts listening now should see them. */
  public open(): readonly AgentEvent[] {
    const waiting: AgentEvent[] = []
    for (const approval of this.approvals.values()) {
      if (!this.closed.has(approval.approvalId)) {
        waiting.push(approval)
      }
    }
    return [...waiting, ...this.questions.values()]
  }
}

src/core/backends/musecode/sandbox.ts:
// Muse Code's OS sandbox for shell tools. On Windows the CLI needs a one-time
// elevated `muse sandbox windows setup` (it creates the local sandbox users,
// their capabilities and a Windows Filtering Platform rule under
// C:\ProgramData\muse); until then every shell tool call fails with
// "sandbox enforcement unavailable". `muse sandbox windows check` prints
// `key=value` lines and exits 1 while setup is required (verified 2026-09-22
// on Muse Code 1.3.0). Linux and macOS have no sandbox subcommand and need no
// setup. This module is pure: the host runs the processes it describes.

import path from 'node:path'
import {
  MUSE_DISABLE_SANDBOX_ARG,
  MUSE_DISABLE_SHELL_ARG,
  MUSE_SANDBOX_CHECK_ARGS,
  MUSE_SANDBOX_NETWORK_ARG,
  MUSE_SANDBOX_SETUP_ARGS,
  MUSE_SERVE_ARGS,
  MUSE_TRUST_WORKSPACE_ARG,
  type SandboxNetworkMode,
  SANDBOX_STATUS_READY,
  SANDBOX_STATUS_SETUP_REQUIRED,
  type ShellSandboxMode,
  WINDOWS_POWERSHELL_COMMAND_ARGS,
  WINDOWS_POWERSHELL_RELATIVE_PATH,
} from '../../../shared/constants'
import type { MuseLaunch } from './launch'

const SANDBOX_STATUS_UNKNOWN = 'unknown'

export type SandboxStatus =
  typeof SANDBOX_STATUS_READY | typeof SANDBOX_STATUS_SETUP_REQUIRED | typeof SANDBOX_STATUS_UNKNOWN

export interface SandboxCheck {
  readonly status: SandboxStatus
  /** The CLI's `reason=` line, present while setup is required. */
  readonly reason: string | undefined
  /** The `diagnostic=` lines, one per finding. */
  readonly diagnostics: readonly string[]
}

export interface CliInvocation {
  readonly command: string
  readonly args: readonly string[]
}

const STATUS_KEY = 'status'
const REASON_KEY = 'reason'
const DIAGNOSTIC_KEY = 'diagnostic'
const LINE_BREAK = /\r?\n/
const KEY_VALUE_SEPARATOR = '='

function toStatus(value: string): SandboxStatus {
  return value === SANDBOX_STATUS_READY || value === SANDBOX_STATUS_SETUP_REQUIRED
    ? value
    : SANDBOX_STATUS_UNKNOWN
}

interface SandboxCheckDraft {
  status: SandboxStatus
  reason: string | undefined
  readonly diagnostics: string[]
}

/** Folds one `key=value` line into the draft; lines without a key are noise. */
function applyReportLine(draft: SandboxCheckDraft, line: string): void {
  const separator = line.indexOf(KEY_VALUE_SEPARATOR)
  if (separator <= 0) {
    return
  }
  const key = line.slice(0, separator).trim()
  const value = line.slice(separator + 1).trim()
  switch (key) {
    case STATUS_KEY: {
      draft.status = toStatus(value)
      break
    }
    case REASON_KEY: {
      draft.reason = value
      break
    }
    case DIAGNOSTIC_KEY: {
      draft.diagnostics.push(value)
      break
    }
    default: {
      break
    }
  }
}

/** Parses the `key=value` report of `muse sandbox windows check`. */
export function parseSandboxCheck(output: string): SandboxCheck {
  const draft: SandboxCheckDraft = {
    status: SANDBOX_STATUS_UNKNOWN,
    reason: undefined,
    diagnostics: [],
  }
  for (const line of output.split(LINE_BREAK)) {
    applyReportLine(draft, line)
  }
  return draft
}

/**
 * The CLI the backend spawns, running `args` instead of its `serve …`
 * arguments. Keeps the PowerShell-launcher prefix when the resolver fell
 * back to it.
 */
export function museCliInvocation(launch: MuseLaunch, args: readonly string[]): CliInvocation {
  const prefixLength = launch.args.length - launch.serveArgs.length
  const suffix = launch.args.slice(prefixLength)
  if (suffix.join(' ') !== launch.serveArgs.join(' ')) {
    throw new Error(`Muse launch does not end with ${launch.serveArgs.join(' ')}`)
  }
  return { command: launch.command, args: [...launch.args.slice(0, prefixLength), ...args] }
}

export function sandboxCheckInvocation(launch: MuseLaunch): CliInvocation {
  return museCliInvocation(launch, MUSE_SANDBOX_CHECK_ARGS)
}

export function sandboxSetupInvocation(launch: MuseLaunch): CliInvocation {
  return museCliInvocation(launch, MUSE_SANDBOX_SETUP_ARGS)
}

function isInsideDirectory(directory: string, candidate: string): boolean {
  const root = path.win32.resolve(directory).toLowerCase()
  const target = path.win32.resolve(candidate).toLowerCase()
  return target === root || target.startsWith(`${root}${path.win32.sep}`)
}

/**
 * A Windows workspace under `C:\Users\<user>`, where Muse Code's sandbox runs
 * shell commands in PowerShell's own folder instead (meta-models/muse-code-sdk#26;
 * verified live on 1.3.0 on 2026-09-22 and on 1.4.0 on 2026-09-27). No release
 * has fixed it, so this holds for every version until one is verified; an
 * earlier version ceiling of 1.3.0 hid the warning on 1.4.0, which is still
 * affected (docs/certification/m4.md, release-0.9.1.md).
 */
export function isProfileWorkspace(
  platform: NodeJS.Platform,
  workspaceRoot: string,
  userProfileDir: string | undefined,
): boolean {
  return (
    platform === 'win32' &&
    userProfileDir !== undefined &&
    isInsideDirectory(userProfileDir, workspaceRoot)
  )
}

export interface ShellSandboxProbe {
  /** `museSpark.shellSandbox`. */
  readonly mode: ShellSandboxMode
  readonly platform: NodeJS.Platform
  readonly workspaceRoot: string | undefined
  readonly userProfileDir: string | undefined
}

/**
 * Why the sandbox is on or off: the setting said so, `auto` turned it off
 * for a Windows profile workspace, or nothing spoke and the CLI default
 * (sandbox on) stands.
 */
export type ShellSandboxReason = 'setting' | 'profileWorkspace' | 'default'

export interface ShellSandboxPosture {
  readonly isSandboxed: boolean
  readonly reason: ShellSandboxReason
}

/** The `muse serve` posture for this window (fixed for the host's lifetime). */
export function resolveShellSandbox(probe: ShellSandboxProbe): ShellSandboxPosture {
  if (probe.mode === 'muse') {
    return { isSandboxed: true, reason: 'setting' }
  }
  if (probe.mode === 'off') {
    return { isSandboxed: false, reason: 'setting' }
  }
  const isLimited =
    probe.workspaceRoot !== undefined &&
    isProfileWorkspace(probe.platform, probe.workspaceRoot, probe.userProfileDir)
  return isLimited
    ? { isSandboxed: false, reason: 'profileWorkspace' }
    : { isSandboxed: true, reason: 'default' }
}

/**
 * Whether `museSpark.sandboxNetwork` reaches the host (M56, PLAN.md D43):
 * a mode other than `default`, while the shell sandbox is on. Without the
 * sandbox Muse Code ignores the flag ("--disable-sandbox turns the sandbox
 * off entirely, so no sandbox network policy applies", captured 2026-09-25)
 * and commands have the network the user has.
 */
export function isSandboxNetworkApplied(
  mode: SandboxNetworkMode,
  posture: ShellSandboxPosture,
): boolean {
  return mode !== 'default' && posture.isSandboxed
}

/**
 * The `serve` arguments that install `posture`, the sandbox's network and
 * the workspace's trust on the host. A trusted workspace loads its rules and
 * skills (Muse Code's `--trust-workspace`); an untrusted one gets no rules,
 * no skills and no workspace shell, VS Code's Restricted Mode contract
 * (PLAN.md D13).
 */
export function serveArguments(
  posture: ShellSandboxPosture,
  isWorkspaceTrusted: boolean,
  network: SandboxNetworkMode,
): readonly string[] {
  return [
    ...MUSE_SERVE_ARGS,
    ...(posture.isSandboxed ? [] : [MUSE_DISABLE_SANDBOX_ARG]),
    ...(isSandboxNetworkApplied(network, posture) ? [MUSE_SANDBOX_NETWORK_ARG, network] : []),
    isWorkspaceTrusted ? MUSE_TRUST_WORKSPACE_ARG : MUSE_DISABLE_SHELL_ARG,
  ]
}

/** A PowerShell single-quoted literal; the only escape is a doubled quote. */
function powerShellLiteral(value: string): string {
  return `'${value.replaceAll("'", "''")}'`
}

/**
 * Runs `target` through Windows PowerShell's `Start-Process -Verb RunAs`, the
 * UAC prompt, and waits for it. The elevated process's exit code becomes the
 * PowerShell exit code; a declined prompt makes `Start-Process` throw, which
 * `-NonInteractive` turns into exit code 1. Its output is not capturable
 * across the elevation boundary, so the caller re-runs the check afterwards.
 */
export function elevatedInvocation(systemRoot: string, target: CliInvocation): CliInvocation {
  const argumentList = target.args.map((argument) => powerShellLiteral(argument)).join(',')
  const script = [
    `$process = Start-Process -FilePath ${powerShellLiteral(target.command)}`,
    `-ArgumentList @(${argumentList}) -Verb RunAs -Wait -PassThru;`,
    'exit $process.ExitCode',
  ].join(' ')
  return {
    command: path.win32.join(systemRoot, WINDOWS_POWERSHELL_RELATIVE_PATH),
    args: [...WINDOWS_POWERSHELL_COMMAND_ARGS, script],
  }
}

src/core/backends/musecode/sessionRecord:
// The MSP `Session` object (`session/list` rows, the resume / read / fork
// envelopes and `session/listChanged`) and the history envelope those
// commands serve, narrowed to what the extension reads. Shapes verified
// live 2026-09-22 on Muse Code 1.3.0 (PLAN.md §6 M6, scratchpad probes).

import * as z from 'zod/mini'
import {
  type ItemSnapshot,
  itemSnapshotFields,
  type SessionGoal,
  todoItemSchema,
} from '../../../shared/agentEvents'
import { IDE_PAID_TOOLS, TEXT_ATTACHMENT_MEDIA_TYPE } from '../../../shared/constants'

import { sessionActivityFields } from '../../../shared/sessions'
import type { SessionHistoryOutcome } from '../../agent/agentBackend'
import { readTextFileDisplay } from '../../../shared/textFileDisplay'

/**
 * MSP's `Goal` block (M45, PLAN.md D38) as `session/goalChanged` and a
 * snapshot's `state.goal` carry it (captured live 2026-09-25: the work
 * fields are absent until reported). A `null` work field is read as absent.
 */
export const wireGoalSchema = z.object({
  objective: z.string(),
  status: z.string(),
  percentComplete: z.number(),
  currentWork: z.optional(z.nullable(z.string())),
  nextWork: z.optional(z.nullable(z.string())),
})
type WireGoal = z.infer<typeof wireGoalSchema>

export function toSessionGoal(goal: WireGoal): SessionGoal {
  return {
    objective: goal.objective,
    status: goal.status,
    percentComplete: goal.percentComplete,
    ...(typeof goal.currentWork === 'string' && { currentWork: goal.currentWork }),
    ...(typeof goal.nextWork === 'string' && { nextWork: goal.nextWork }),
  }
}

/**
 * A snapshot's goal, read on its own (the review of PR #29's rule): a goal
 * that is not the captured shape costs the strip, never the resume. `null`
 * is "no goal"; anything unreadable is "cannot say".
 */
function snapshotGoal(raw: unknown): SessionGoal | null | undefined {
  if (raw === null) {
    return null
  }
  const parsed = wireGoalSchema.safeParse(raw)
  return parsed.success ? toSessionGoal(parsed.data) : undefined
}

export const sessionRecordSchema = z.object({
  sessionId: z.string(),
  /** Allocated name; absent until the host names the session. */
  name: z.optional(z.string()),
  /** Derived display title (the first prompt for unnamed sessions). */
  title: z.optional(z.string()),
  firstUserPrompt: z.optional(z.string()),
  ...sessionActivityFields,
  forkedFrom: z.optional(z.nullable(z.object({ sessionId: z.string() }))),
  workspaceRoot: z.optional(z.nullable(z.string())),
  /** The running foreground turn; `null` when idle (msp.d.ts Session.activeTurnId, D26). */
  activeTurnId: z.optional(z.nullable(z.string())),
})

// The wire item is the snapshot with `turnId` nullable (`null` on userShell)
// and the user message's `displayText` (its presentation form, M5).
export const wireItemSchema = z.object({
  ...itemSnapshotFields,
  turnId: z.optional(z.nullable(z.string())),
  displayText: z.optional(z.nullable(z.string())),
})
export type WireItem = z.infer<typeof wireItemSchema>

/**
 * Drops the `null` turn (userShell) so the snapshot's `turnId` stays a
 * string; a user message's `displayText` replaces its model-visible text
 * (the M5 editor context is never shown as typed text).
 */
export function toSnapshot(item: WireItem): ItemSnapshot {
  const { turnId, displayText, ...rest } = item
  const marked =
    typeof displayText === 'string' && item.kind === 'userMessage'
      ? readTextFileDisplay(displayText)
      : undefined
  let syntheticFiles: {
    readonly type: string
    readonly mediaType: string
    readonly name?: string
  }[] = []
  if (marked !== undefined && !item.attachments?.some((attachment) => attachment.type === 'file')) {
    syntheticFiles =
      marked.length === 0
        ? [{ type: 'file', mediaType: TEXT_ATTACHMENT_MEDIA_TYPE }]
        : marked.map((name) => ({ type: 'file', mediaType: TEXT_ATTACHMENT_MEDIA_TYPE, name }))
  }
  return {
    ...rest,
    ...(typeof turnId === 'string' && { turnId }),
    ...(typeof displayText === 'string' && { text: displayText }),
    ...(syntheticFiles.length > 0 && {
      attachments: [...(item.attachments ?? []), ...syntheticFiles],
    }),
    // An image the extension's own `ide` server bought with the key (M44).
    ...(item.tool !== undefined && IDE_PAID_TOOLS.has(item.tool) && { paid: 'imageGeneration' }),
  }
}

// `history.mode` is what was served, never what was asked: `inline` carries
// the item array, `snapshot` / `anchoredSnapshot` carry the folded state
// (items plus name, todo list and goal), `none` carries nothing (paged
// later). The goal is taken as it comes and read on its own (M45).
const historySchema = z.object({
  mode: z.string(),
  items: z.optional(z.nullable(z.array(wireItemSchema))),
  snapshot: z.optional(
    z.nullable(
      z.object({
        state: z.object({
          items: z.array(wireItemSchema),
          name: z.optional(z.nullable(z.string())),
          todoList: z.optional(z.nullable(z.object({ items: z.array(todoItemSchema) }))),
          goal: z.optional(z.unknown()),
        }),
      }),
    ),
  ),
  noneReason: z.optional(z.string()),
})

/** The envelope `session/resume`, `session/read` and `session/fork` share. */
export const sessionEnvelopeSchema = z.object({
  session: sessionRecordSchema,
  history: historySchema,
  viewCursor: z.string(),
  // Late-joiner pointers at unsettled prompts (tdd SS2.5.2); their payloads
  // follow as re-issued server requests and from `approval/listPending`.
  pendingRequests: z.optional(z.array(z.object({ kind: z.string() }))),
})
export type SessionEnvelope = z.infer<typeof sessionEnvelopeSchema>

export const sessionListResultSchema = z.object({
  sessions: z.array(sessionRecordSchema),
  nextCursor: z.nullable(z.string()),
})

export const sessionListChangedSchema = z.object({ session: sessionRecordSchema })
export const sessionClosedSchema = z.object({ sessionId: z.string(), reason: z.string() })

export const sessionRenameResultSchema = z.object({
  status: z.string(),
  name: z.optional(z.string()),
})

export function historyOutcome(envelope: SessionEnvelope): SessionHistoryOutcome {
  const { history, session } = envelope
  const snapshot = history.snapshot?.state
  const items = history.items ?? snapshot?.items ?? []
  // Only a snapshot can say whether there is a goal: its `goal` is `null`
  // when there is none (live 2026-09-25). Inline history says nothing, nor
  // does a snapshot served as its items alone (msp.d.ts SnapshotState, E8).
  const goal = snapshot?.goal === undefined ? undefined : snapshotGoal(snapshot.goal)
  return {
    mode: history.mode,
    items: items.map((item) => toSnapshot(item)),
    name: snapshot?.name ?? session.name,
    todos: snapshot?.todoList?.items ?? [],
    ...(goal !== undefined && { goal }),
  }
}

src/core/backends/musecode/skillsCli.ts:
// The Muse Code CLI's skill commands (M30, PLAN.md D30), which MSP does not
// carry: `muse skills list --json` (every skill with its scope and
// activation), `muse skills enable|disable <name> --scope <scope>`, and
// `muse skills import --from claude|codex [--dry-run] --json`. Shapes were
// read from Muse Code 1.3.0's own output on 2026-09-24. A running
// `muse serve` keeps the activation it started with (verified the same day:
// a disabled skill stays listed, even in a new session on that host), so a
// change takes effect when the host restarts.
//
// Pure: the host runs the commands and hands the output here.

import * as z from 'zod/mini'
import type { SkillImportSource } from '../../../shared/constants'

const JSON_FLAG = '--json'
const WORKSPACE_FLAG = '--workspace'
const TRUST_FLAG = '--trust-workspace'
const SCOPE_FLAG = '--scope'
const OFF_ACTIVATION = 'off'
// `muse skills import` copies into the user's own skills folder.
const IMPORT_SCOPE = 'user'

// `list` reports a skill's scope as `bundled`; `enable`/`disable` spell the
// same scope `built-in`.
const SCOPE_FLAG_VALUES: Readonly<Record<string, string>> = {
  bundled: 'built-in',
  user: 'user',
  project: 'project',
  plugin: 'plugin',
}

const catalogSchema = z.object({
  skills: z.array(
    z.object({
      id: z.string(),
      name: z.string(),
      display_name: z.optional(z.nullable(z.string())),
      description: z.optional(z.nullable(z.string())),
      scope: z.string(),
      activation: z.string(),
    }),
  ),
})

/** One skill as `muse skills list --json` reports it. */
export interface CatalogSkill {
  /** `bundled:grill`, `user:caveman`: unique across scopes. */
  readonly id: string
  /** What `enable`/`disable` take, with the scope. */
  readonly name: string
  readonly displayName: string
  readonly description: string
  readonly scope: string
  /** `on`, `off`, or `user-only` (invocable by the user, never by the model). */
  readonly activation: string
}

/** An activation change the user asked for. */
export interface ActivationChange {
  readonly skill: CatalogSkill
  readonly isOn: boolean
}

function parseJson(stdout: string, what: string): unknown {
  try {
    return JSON.parse(stdout)
  } catch {
    throw new Error(`Muse Code's ${what} output is not JSON`)
  }
}

/** Throws when the output is not the documented shape: never an empty list that reads as "no skills". */
export function parseSkillCatalog(stdout: string): readonly CatalogSkill[] {
  const parsed = catalogSchema.safeParse(parseJson(stdout, 'skills list'))
  if (!parsed.success) {
    throw new Error(
      `Muse Code's skills list has an unexpected shape: ${z.prettifyError(parsed.error)}`,
    )
  }
  return parsed.data.skills.map((skill) => ({
    id: skill.id,
    name: skill.name,
    displayName: skill.display_name ?? skill.name,
    description: skill.description ?? '',
    scope: skill.scope,
    activation: skill.activation,
  }))
}

export function isSkillOn(skill: CatalogSkill): boolean {
  return skill.activation !== OFF_ACTIVATION
}

/** The `--scope` value for a listed scope; undefined for one the CLI cannot toggle. */
export function scopeFlagValue(scope: string): string | undefined {
  return SCOPE_FLAG_VALUES[scope]
}

function workspaceArgs(workspaceRoot: string | undefined, isTrusted: boolean): readonly string[] {
  if (workspaceRoot === undefined) {
    return []
  }
  // Project skills load only in a trusted workspace, as in the panel (D13).
  return [WORKSPACE_FLAG, workspaceRoot, ...(isTrusted ? [TRUST_FLAG] : [])]
}

export function skillsListArgs(
  workspaceRoot: string | undefined,
  isTrusted: boolean,
): readonly string[] {
  return ['skills', 'list', ...workspaceArgs(workspaceRoot, isTrusted), JSON_FLAG]
}

/** The rows whose checkbox changed; a skill with a scope the CLI cannot toggle is left alone. */
export function activationChanges(
  skills: readonly CatalogSkill[],
  pickedIds: ReadonlySet<string>,
): readonly ActivationChange[] {
  return skills
    .filter((skill) => scopeFlagValue(skill.scope) !== undefined)
    .filter((skill) => isSkillOn(skill) !== pickedIds.has(skill.id))
    .map((skill) => ({ skill, isOn: pickedIds.has(skill.id) }))
}

export function activationArgs(
  change: ActivationChange,
  workspaceRoot: string | undefined,
  isTrusted: boolean,
): readonly string[] {
  const scope = scopeFlagValue(change.skill.scope)
  if (scope === undefined) {
    throw new Error(`Muse Code cannot turn ${change.skill.scope} skills on or off`)
  }
  return [
    'skills',
    change.isOn ? 'enable' : 'disable',
    change.skill.name,
    SCOPE_FLAG,
    scope,
    ...workspaceArgs(workspaceRoot, isTrusted),
    JSON_FLAG,
  ]
}

export function skillImportArgs(source: SkillImportSource, isDryRun: boolean): readonly string[] {
  return [
    'skills',
    'import',
    '--from',
    source,
    SCOPE_FLAG,
    IMPORT_SCOPE,
    ...(isDryRun ? ['--dry-run'] : []),
    JSON_FLAG,
  ]
}

// A candidate's `diagnostics` and the other lists' entries carry more than
// this; only what the panel shows is read.
const importEntrySchema = z.object({
  id: z.string(),
  action: z.optional(z.string()),
  valid: z.optional(z.boolean()),
  reason: z.optional(z.nullable(z.string())),
  error: z.optional(z.nullable(z.string())),
})

const importReportSchema = z.object({
  source: z.object({ type: z.string(), path: z.optional(z.nullable(z.string())) }),
  dry_run: z.boolean(),
  candidates: z.array(importEntrySchema),
  installed: z.array(importEntrySchema),
  quarantined: z.array(importEntrySchema),
  skipped: z.array(importEntrySchema),
  failed: z.array(importEntrySchema),
})

export interface ImportEntry {
  readonly id: string
  /** `copy` and so on; the CLI's own word. */
  readonly action: string | undefined
  readonly isValid: boolean
  /** Why it was skipped, quarantined or failed, when the CLI says. */
  readonly reason: string | undefined
}

export interface ImportReport {
  /** Where the CLI looked, when it says. */
  readonly sourcePath: string | undefined
  readonly isDryRun: boolean
  readonly candidates: readonly ImportEntry[]
  readonly installed: readonly ImportEntry[]
  readonly quarantined: readonly ImportEntry[]
  readonly skipped: readonly ImportEntry[]
  readonly failed: readonly ImportEntry[]
}

function entryOf(entry: z.infer<typeof importEntrySchema>): ImportEntry {
  return {
    id: entry.id,
    action: entry.action,
    isValid: entry.valid ?? true,
    reason: entry.reason ?? entry.error ?? undefined,
  }
}

export function parseImportReport(stdout: string): ImportReport {
  const parsed = importReportSchema.safeParse(parseJson(stdout, 'skills import'))
  if (!parsed.success) {
    throw new Error(
      `Muse Code's skills import report has an unexpected shape: ${z.prettifyError(parsed.error)}`,
    )
  }
  const report = parsed.data
  return {
    sourcePath: report.source.path ?? undefined,
    isDryRun: report.dry_run,
    candidates: report.candidates.map((entry) => entryOf(entry)),
    installed: report.installed.map((entry) => entryOf(entry)),
    quarantined: report.quarantined.map((entry) => entryOf(entry)),
    skipped: report.skipped.map((entry) => entryOf(entry)),
    failed: report.failed.map((entry) => entryOf(entry)),
  }
}

src/core/backendSelection.ts:
// Which backend a window uses, and what the sign-in gate offers (PLAN.md D1,
// M7). The two credentials pay from different places, so they are never
// mixed: the Muse Code CLI runs on its own sign-in (the owner's subscription,
// or a key the CLI itself holds), and a Model API key pasted into the panel
// drives only the Model API backend. The extension never hands the pasted
// key to the CLI (it did until M7, and the CLI prefers `META_API_KEY` over
// its browser session, which billed the subscription's work to the key).

import type { BackendMode } from '../shared/constants'
import type { SignInMethod } from '../shared/protocol'
import type { BackendKind } from './agent/agentBackend'

export interface BackendFacts {
  /** `museSpark.backend`. */
  readonly setting: BackendMode
  readonly hasCli: boolean
  /** The CLI's own credential: its file, or `META_API_KEY` in the environment. */
  readonly hasCliSession: boolean
  /** A Model API key in the extension's secret storage. */
  readonly hasStoredKey: boolean
}

export type BackendChoice =
  | {
      readonly kind: BackendKind
      readonly status: 'signedIn' | 'signedOut'
      /** The sign-in paths the gate offers while signed out. */
      readonly methods: readonly SignInMethod[]
    }
  | {
      readonly kind: undefined
      readonly status: 'noCli'
      readonly methods: readonly SignInMethod[]
    }

const BOTH: readonly SignInMethod[] = ['browser', 'apiKey']
const BROWSER_ONLY: readonly SignInMethod[] = ['browser']
const KEY_ONLY: readonly SignInMethod[] = ['apiKey']

/**
 * Whether the choice needs the CLI's own sign-in. With the backend forced to
 * the Model API it does not, so nothing asks the CLI (no probe, no
 * `account/read`): a CLI that is slow to answer about an ambiguous file must
 * not hold up a user whose key is stored (Codex on 328efb52).
 */
export function isCliSignInConsulted(setting: BackendMode): boolean {
  return setting !== 'modelApi'
}

/** The choice, asking for the CLI's sign-in only when the setting needs it. */
export async function readBackendChoice(asked: {
  readonly setting: BackendMode
  readonly hasCli: boolean
  readonly hasCliSession: () => Promise<boolean>
  readonly hasStoredKey: () => Promise<boolean>
}): Promise<BackendChoice> {
  return selectBackend({
    setting: asked.setting,
    hasCli: asked.hasCli,
    hasCliSession: isCliSignInConsulted(asked.setting) && (await asked.hasCliSession()),
    hasStoredKey: await asked.hasStoredKey(),
  })
}

export function selectBackend(facts: BackendFacts): BackendChoice {
  switch (facts.setting) {
    case 'museCode': {
      if (!facts.hasCli) {
        return { kind: undefined, status: 'noCli', methods: [] }
      }
      return {
        kind: 'museCode',
        status: facts.hasCliSession ? 'signedIn' : 'signedOut',
        methods: BROWSER_ONLY,
      }
    }
    case 'modelApi': {
      return {
        kind: 'modelApi',
        status: facts.hasStoredKey ? 'signedIn' : 'signedOut',
        methods: KEY_ONLY,
      }
    }
    case 'auto': {
      if (facts.hasCli && facts.hasCliSession) {
        return { kind: 'museCode', status: 'signedIn', methods: BOTH }
      }
      if (facts.hasStoredKey) {
        return { kind: 'modelApi', status: 'signedIn', methods: BOTH }
      }
      return facts.hasCli
        ? { kind: 'museCode', status: 'signedOut', methods: BOTH }
        : { kind: undefined, status: 'noCli', methods: KEY_ONLY }
    }
  }
}

src/core/bestOfN/bestOfNCoordinator.ts:
// One owner per extension window. Injected into every surface's runner;
// never shared through module state or across accounts/windows.

import type { BestOfNRun } from '../../shared/bestOfN'

export class BestOfNCoordinator {
  private owner: object | undefined
  private readonly runs = new Map<object, BestOfNRun>()
  private readonly openers = new Map<object, (attemptId: string, runId: string) => Promise<void>>()

  public acquire(owner: object): boolean {
    if (this.owner === owner) {
      return true
    }
    if (this.owner !== undefined) {
      return false
    }
    this.owner = owner
    return true
  }

  public release(owner: object): void {
    if (this.owner === owner) {
      this.owner = undefined
    }
  }

  public update(
    owner: object,
    run: BestOfNRun,
    open?: (attemptId: string, runId: string) => Promise<void>,
  ): void {
    this.runs.set(owner, run)
    if (open !== undefined) this.openers.set(owner, open)
  }

  public forget(owner: object): void {
    this.runs.delete(owner)
    this.openers.delete(owner)
  }

  public snapshots(): readonly BestOfNRun[] {
    const snapshots: BestOfNRun[] = []
    this.runs.forEach((run) => {
      snapshots.push(run)
    })
    return snapshots
  }

  /** Board activation opens an ephemeral attempt's owned worktree. */
  public async openSession(sessionId: string): Promise<boolean> {
    for (const [owner, run] of this.runs) {
      const attempt = run.runAttempts.find((entry) => entry.sessionId === sessionId)
      const open = this.openers.get(owner)
      if (attempt !== undefined && open !== undefined) {
        await open(attempt.attemptId, run.runId)
        return true
      }
    }
    return false
  }
}

src/core/bestOfN/bestOfNError.ts:
/** Why a run command was refused; the host says it in the user's language. */
const REFUSALS = [
  'noWorkspace',
  'untrusted',
  'wrongBackend',
  'paidOff',
  'invalid',
  'unknownModel',
  'consentDeclined',
  'worktreeFailed',
  'alreadyRunning',
  'noRun',
  'unknownAttempt',
  'attemptNotDone',
  'alreadyTaken',
  'contextChanged',
  'targetChanged',
  'budgetUnavailable',
] as const
export type BestOfNRefusal = (typeof REFUSALS)[number]
const REFUSAL_NAMES: readonly string[] = REFUSALS

export class BestOfNError extends Error {
  public constructor(
    public readonly refusal: BestOfNRefusal,
    public readonly detail?: string,
  ) {
    super(detail === undefined ? refusal : `${refusal}: ${detail}`)
    this.name = 'BestOfNError'
  }
}

/** Same-build error fields, including a known refusal, cross bundle copies (PLAN.md §8). */
export function isBestOfNError(value: unknown): value is BestOfNError {
  return (
    value instanceof Error &&
    value.name === 'BestOfNError' &&
    'refusal' in value &&
    typeof value.refusal === 'string' &&
    REFUSAL_NAMES.includes(value.refusal) &&
    (!('detail' in value) || value.detail === undefined || typeof value.detail === 'string')
  )
}

src/core/chatReference.ts:
// The context part that rides with a message replying to, asking about or
// commenting on something in the chat (M17). Pure: a tagged block the model
// reads alongside the typed text, naming who wrote the referenced passage
// and what the user is doing with it. The transcript shows the typed text
// only (M5's displayText).

import {
  CHAT_REFERENCE_AUTHORS,
  CHAT_REFERENCE_MAX_CHARS,
  CHAT_REFERENCE_TAG,
  MODEL_TEXT,
} from '../shared/constants'
import type { ChatReference } from '../shared/protocol'

const LEADS: Readonly<Record<ChatReference['intent'], string>> = {
  reply: MODEL_TEXT.replyContextLead,
  question: MODEL_TEXT.questionContextLead,
  comment: MODEL_TEXT.commentContextLead,
}

function authorOf(role: string): string {
  return CHAT_REFERENCE_AUTHORS[role] ?? role
}

function clipped(text: string): string {
  return text.length <= CHAT_REFERENCE_MAX_CHARS
    ? text
    : `${text.slice(0, CHAT_REFERENCE_MAX_CHARS)}\n${MODEL_TEXT.referenceTruncated} ${String(CHAT_REFERENCE_MAX_CHARS)} ${MODEL_TEXT.referenceCharacters}`
}

export function chatReferenceText(reference: ChatReference): string {
  const lead = `${LEADS[reference.intent]} ${authorOf(reference.role)}.`
  return `<${CHAT_REFERENCE_TAG} intent="${reference.intent}" from="${reference.role}">${lead}\n"""\n${clipped(reference.text)}\n"""</${CHAT_REFERENCE_TAG}>`
}

