src/core/codeIntel/definitions.ts:
// The code intelligence tools as the model sees them (M67, PLAN.md D49):
// one description and one argument schema per tool, shared by the Model
// API's native tools (`find_definition`, …) and the `ide` server's
// (`mcp__ide__findDefinition`, …). Only `rename_symbol` differs: on the
// Model API it writes the files through the edit path; on `ide` it returns
// the edits for Muse Code's own edit tool.

import * as z from 'zod/mini'
import { CODE_INTEL_TOOLS, type CodeIntelTool } from '../../shared/constants'

export const CALL_DIRECTIONS = ['incoming', 'outgoing'] as const

export const locateArgs = z.object({
  path: z.optional(z.string()),
  line: z.optional(z.number()),
  column: z.optional(z.number()),
  symbol: z.optional(z.string()),
})
export type LocateArgs = z.infer<typeof locateArgs>
export const workspaceSymbolsArgs = z.object({ query: z.string() })
export const documentSymbolsArgs = z.object({ path: z.string() })
export const callHierarchyArgs = z.extend(locateArgs, {
  direction: z.optional(z.enum(CALL_DIRECTIONS)),
})
export const repoMapArgs = z.object({ max_tokens: z.optional(z.number()) })
export const renameArgs = z.extend(locateArgs, { new_name: z.string() })

const HOW_TO_NAME =
  'Name the symbol by path, line and column (1-based); by path and line plus its name in symbol; by path and symbol (its first use in that file); or by symbol alone (looked up among the workspace symbols).'

const LOCATE_PROPERTIES = {
  path: { type: 'string', description: 'Workspace-relative path of the file' },
  line: { type: 'integer', description: '1-based line' },
  column: { type: 'integer', description: '1-based column: the character in the line' },
  symbol: {
    type: 'string',
    description:
      "The symbol's name: found on line in path, its first use in path, or a workspace symbol when no path is given",
  },
} as const

export interface CodeIntelDefinition {
  readonly tool: CodeIntelTool
  readonly description: string
  readonly properties: Readonly<Record<string, unknown>>
  readonly required: readonly string[]
}

const RENAME_PROPERTIES = {
  ...LOCATE_PROPERTIES,
  new_name: { type: 'string', description: 'The new name' },
} as const

const READ_DEFINITIONS: readonly CodeIntelDefinition[] = [
  {
    tool: 'findDefinition',
    description: `Find where a symbol is defined, from VS Code's language service (Go to Definition). ${HOW_TO_NAME} Answers workspace-relative path:line:column with the line's text.`,
    properties: LOCATE_PROPERTIES,
    required: [],
  },
  {
    tool: 'findReferences',
    description: `Find every use of a symbol, its declaration included, from VS Code's language service (Find All References). ${HOW_TO_NAME} Answers workspace-relative path:line:column with each line's text.`,
    properties: LOCATE_PROPERTIES,
    required: [],
  },
  {
    tool: 'workspaceSymbols',
    description:
      "Search the workspace's symbols (classes, functions, methods, variables…) by name, from VS Code's language services (Go to Symbol in Workspace).",
    properties: { query: { type: 'string', description: 'The name or part of it' } },
    required: ['query'],
  },
  {
    tool: 'documentSymbols',
    description:
      "A file's symbols as an outline (classes, their members, functions…) with line:column, from VS Code's language service.",
    properties: { path: LOCATE_PROPERTIES.path },
    required: ['path'],
  },
  {
    tool: 'hover',
    description: `A symbol's type and documentation, as VS Code's hover shows them. ${HOW_TO_NAME}`,
    properties: LOCATE_PROPERTIES,
    required: [],
  },
  {
    tool: 'callHierarchy',
    description: `Who calls a function or method (incoming, the default) or what it calls (outgoing), from VS Code's language service where the language supports it. ${HOW_TO_NAME}`,
    properties: {
      ...LOCATE_PROPERTIES,
      direction: { type: 'string', enum: [...CALL_DIRECTIONS] },
    },
    required: [],
  },
  {
    tool: 'repoMap',
    description:
      'A compact map of the workspace: the files other files use most, ranked by how often the names they define are used elsewhere, each with its most used definitions, within a token budget. Use it to get your bearings in an unfamiliar codebase.',
    properties: {
      max_tokens: {
        type: 'integer',
        description:
          'The budget in tokens for the whole answer, notes included (default 1024, at most 8192)',
      },
    },
    required: [],
  },
]

/** The Model API's tools: `rename_symbol` writes through the edit path and asks like an edit. */
export const MODEL_API_CODE_INTEL_DEFINITIONS: readonly CodeIntelDefinition[] = [
  ...READ_DEFINITIONS,
  {
    tool: 'renameSymbol',
    description: `Rename a symbol everywhere it is used, through VS Code's language service (Rename Symbol), and write the changed files; it asks like an edit. ${HOW_TO_NAME}`,
    properties: RENAME_PROPERTIES,
    required: ['new_name'],
  },
]

/** The `ide` server's tools: `renameSymbol` changes nothing and returns the edits. */
export const IDE_CODE_INTEL_DEFINITIONS: readonly CodeIntelDefinition[] = [
  ...READ_DEFINITIONS,
  {
    tool: 'renameSymbol',
    description: `Compute the edits that rename a symbol everywhere it is used, through VS Code's language service (Rename Symbol). It changes nothing: it returns a unified diff per file for you to apply with your own edit tool. ${HOW_TO_NAME}`,
    properties: RENAME_PROPERTIES,
    required: ['new_name'],
  },
]

const TOOL_BY_NAME: ReadonlyMap<string, CodeIntelTool> = new Map(
  MODEL_API_CODE_INTEL_DEFINITIONS.map((definition) => [
    CODE_INTEL_TOOLS[definition.tool],
    definition.tool,
  ]),
)

/** Which code intelligence tool a Model API function name is; undefined for any other. */
export function codeIntelToolOf(name: string): CodeIntelTool | undefined {
  return TOOL_BY_NAME.get(name)
}

src/core/context/catalogFiles.ts:
// One loader for the workspace's Markdown catalogs (M76): Muse Code's
// skills (`.agents/skills/<id>/SKILL.md`) and this extension's custom agents
// (`.agents/agents/<id>/AGENT.md`). Both list `<id>` directories under a
// project root confined to the workspace and a personal root, ids sorted,
// the project shadowing the personal one, each file size-capped and parsed;
// every skip is a warning naming what is wrong, never a failed turn.
//
// Each root stands alone (M76 review, RV70x): a root that cannot be listed
// is a warning naming it, and the other roots still load. What a root holds
// but did not yield (a root unlisted, a file unreadable, over its cap or
// refused) is reported with it, so a caller whose precedence narrows (the
// agents) can refuse a name instead of letting a lower root stand in.

import path from 'node:path'
import { type ContextIo, type ContextText, readContextText } from './contextFiles'

export interface CatalogLoaderDeps {
  readonly io: ContextIo
  readonly platform: NodeJS.Platform
}

export interface CatalogRoot<Source extends string = string> {
  /** Absolute directory holding `<id>/<file>` entries. */
  readonly directory: string
  readonly source: Source
  /**
   * The workspace root for project catalogs: a file whose canonical path
   * leaves it is skipped. Undefined for the personal root.
   */
  readonly confineTo: string | undefined
}

export interface CatalogKind {
  /** `skill` or `agent`, as the skip warnings name the entries. */
  readonly kind: string
  readonly fileName: string
  readonly maxBytes: number
  readonly idPattern: RegExp
  /** Entries kept across every root; the rest are skipped with one warning each. Undefined: no limit. */
  readonly maxEntries?: number
}

export type CatalogParse<Entry> =
  | { readonly ok: true; readonly name: string; readonly entry: Entry }
  | { readonly ok: false; readonly reason: string }

export interface CatalogEntry<Entry, Source> {
  readonly id: string
  readonly source: Source
  readonly entry: Entry
}

/** A file a listed root holds but did not yield: unreadable, over its cap, refused, or past the limit. */
export interface CatalogRefusal {
  readonly id: string
  readonly file: string
}

/** What one root yielded beyond its entries (M76 review, RV70x). */
export interface CatalogRootLoad<Source extends string> {
  readonly root: CatalogRoot<Source>
  /** Why the root could not be listed; undefined when it was (a missing root lists as empty). */
  readonly listingFailure: string | undefined
  readonly refused: readonly CatalogRefusal[]
}

export interface CatalogLoad<Entry, Source extends string> {
  readonly entries: readonly CatalogEntry<Entry, Source>[]
  /** One per root, in root order. */
  readonly roots: readonly CatalogRootLoad<Source>[]
  readonly warnings: readonly string[]
}

export type FrontMatterSplit =
  | {
      readonly ok: true
      readonly fields: ReadonlyMap<string, string>
      readonly body: string
      /**
       * What the line reader could not take as `key: value` (a list item, an
       * indented continuation) and what it saw a second time: a format that
       * narrows something must refuse such a file, not guess its meaning.
       */
      readonly ignoredLines: readonly string[]
      readonly duplicateKeys: readonly string[]
    }
  | { readonly ok: false; readonly reason: string }

const FRONT_MATTER_FENCE = '---'
const COMMENT_PREFIX = '#'
const LINE_BREAK = /\r?\n/
const KEY_VALUE = /^([A-Za-z][A-Za-z0-9_-]*):\s*(.*)$/
const QUOTE_PAIRS = [
  ['"', '"'],
  ["'", "'"],
] as const

function unquote(value: string): string {
  const trimmed = value.trim()
  for (const [open, close] of QUOTE_PAIRS) {
    if (trimmed.length >= 2 && trimmed.startsWith(open) && trimmed.endsWith(close)) {
      return trimmed.slice(1, -1)
    }
  }
  return trimmed
}

/** Splits a catalog file into its front matter fields and body. */
export function splitFrontMatter(text: string): FrontMatterSplit {
  const lines = text.split(LINE_BREAK)
  if (lines[0]?.trim() !== FRONT_MATTER_FENCE) {
    return { ok: false, reason: 'front matter is missing' }
  }
  const end = lines.findIndex((line, index) => index > 0 && line.trim() === FRONT_MATTER_FENCE)
  if (end === -1) {
    return { ok: false, reason: 'front matter is not closed' }
  }
  const fields = new Map<string, string>()
  const ignoredLines: string[] = []
  const duplicateKeys: string[] = []
  for (const line of lines.slice(1, end)) {
    const match = KEY_VALUE.exec(line)
    if (match?.[1] !== undefined && match[2] !== undefined) {
      if (fields.has(match[1])) {
        duplicateKeys.push(match[1])
      }
      fields.set(match[1], unquote(match[2]))
    } else if (line.trim() !== '' && !line.trimStart().startsWith(COMMENT_PREFIX)) {
      ignoredLines.push(line)
    }
  }
  return {
    ok: true,
    fields,
    ignoredLines,
    duplicateKeys,
    body: lines
      .slice(end + 1)
      .join('\n')
      .trim(),
  }
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/** One catalog file; a read that throws (a link loop, permissions) refuses that entry only. */
async function readCatalogFile(
  deps: CatalogLoaderDeps,
  file: string,
  confineTo: string | undefined,
  maxBytes: number,
): Promise<ContextText | undefined> {
  try {
    return await readContextText(deps, file, confineTo, maxBytes)
  } catch (error: unknown) {
    return { ok: false, reason: `could not be read: ${describe(error)}` }
  }
}

/** A root's ids, or why it could not be listed. */
async function listRoot(
  deps: CatalogLoaderDeps,
  directory: string,
): Promise<{ readonly ids: readonly string[] } | { readonly failure: string }> {
  try {
    const listed = await deps.io.listDirectory(directory)
    return { ids: listed.toSorted((a, b) => a.localeCompare(b, 'en')) }
  } catch (error: unknown) {
    return { failure: describe(error) }
  }
}

/** Every valid entry under the roots, in root order; ids sorted within a root. */
export async function loadCatalogFiles<Entry, Source extends string>(
  deps: CatalogLoaderDeps,
  roots: readonly CatalogRoot<Source>[],
  kind: CatalogKind,
  parse: (text: string) => CatalogParse<Entry>,
): Promise<CatalogLoad<Entry, Source>> {
  const pathModule = deps.platform === 'win32' ? path.win32 : path.posix
  const seen = new Map<string, Source>()
  const entries: CatalogEntry<Entry, Source>[] = []
  const rootLoads: CatalogRootLoad<Source>[] = []
  const warnings: string[] = []
  for (const root of roots) {
    const listed = await listRoot(deps, root.directory)
    if ('failure' in listed) {
      // This root alone is unknown; the others still load.
      warnings.push(`loading the ${root.source} ${kind.kind}s failed: ${listed.failure}`)
      rootLoads.push({ root, listingFailure: listed.failure, refused: [] })
      continue
    }
    const refused: CatalogRefusal[] = []
    rootLoads.push({ root, listingFailure: undefined, refused })
    for (const id of listed.ids) {
      const label = `${root.source} ${kind.kind} ${id}`
      if (!kind.idPattern.test(id)) {
        warnings.push(`${label} skipped: the directory name is not a valid ${kind.kind} id`)
        continue
      }
      const shadowedBy = seen.get(id)
      if (shadowedBy !== undefined) {
        warnings.push(
          `${label} skipped: the ${shadowedBy} ${kind.kind} with the same id takes precedence`,
        )
        continue
      }
      const file = pathModule.join(root.directory, id, kind.fileName)
      // What exists here but is not taken is reported with the root.
      const refuse = (warning: string): void => {
        warnings.push(`${label} skipped: ${warning}`)
        refused.push({ id, file })
      }
      if (kind.maxEntries !== undefined && entries.length >= kind.maxEntries) {
        refuse(`only the first ${String(kind.maxEntries)} ${kind.kind}s are loaded`)
        continue
      }
      const read = await readCatalogFile(deps, file, root.confineTo, kind.maxBytes)
      if (read === undefined) {
        warnings.push(`${label} skipped: ${kind.fileName} is missing`)
        continue
      }
      if (!read.ok) {
        refuse(`${kind.fileName} ${read.reason}`)
        continue
      }
      const { text } = read
      const bytes = Buffer.byteLength(text)
      if (bytes > kind.maxBytes) {
        refuse(
          `${kind.fileName} is ${String(bytes)} bytes, over the ${String(kind.maxBytes)} byte limit`,
        )
        continue
      }
      const parsed = parse(text)
      if (!parsed.ok) {
        refuse(parsed.reason)
        continue
      }
      if (parsed.name !== id) {
        warnings.push(
          `${label}: front matter name ${parsed.name} differs from the directory; the directory name is the selector`,
        )
      }
      seen.set(id, root.source)
      entries.push({ id, source: root.source, entry: parsed.entry })
    }
  }
  return { entries, roots: rootLoads, warnings }
}

src/core/context/contextFiles.ts:
// How the workspace context loaders read their files (PLAN.md D13, D27):
// the rules files, the skills and the memory index. A file is read as bytes
// and decoded by its byte-order mark, so a UTF-16 `AGENTS.md` (what Windows
// PowerShell 5.1's `>` writes) reads as the text it is instead of NUL
// garbage; a UTF-8 mark is dropped; text that is not valid in its encoding,
// or that still holds NUL characters, is refused with the reason rather than
// given to the model. A file the repository ships is confined to the
// workspace by canonical path (D24): a link or junction that leads outside it
// is refused. Pure: the host supplies the file system.

import { confineWorkspacePath } from '../workspacePath'

export interface ContextIo {
  /**
   * The file's bytes; undefined when it does not exist. With `maxBytes` (the
   * catalogs' caps) it reads at most one byte more than that, so a file over
   * the cap is seen to be over it without being read whole, and it reads only
   * a regular file: a pipe or a device would block or never end.
   */
  readFile(absolutePath: string, maxBytes?: number): Promise<Uint8Array | undefined>
  /**
   * The names of the entries of an absolute directory that are directories
   * or links (symbolic links, junctions), whatever a link leads to, so a
   * broken one is reported by the reader rather than dropped; empty when the
   * directory is missing.
   */
  listDirectory(absolutePath: string): Promise<readonly string[]>
  /** The canonical form of an absolute path (links resolved, PLAN.md D24). */
  realPath(absolutePath: string): Promise<string>
}

export interface ContextReadDeps {
  readonly io: ContextIo
  readonly platform: NodeJS.Platform
}

export type ContextText =
  | { readonly ok: true; readonly text: string }
  /** `reason` reads after the file's name ("is not valid UTF-8 text"). */
  | { readonly ok: false; readonly reason: string }

type Encoding = 'utf8' | 'utf16le' | 'utf16be'

// The UTF-16 byte-order marks, one character per byte (as `imageDimensions`
// spells its signatures).
const UTF16LE_BOM = '\u{FF}\u{FE}'
const UTF16BE_BOM = '\u{FE}\u{FF}'
const INVALID_REASONS: Readonly<Record<Encoding, string>> = {
  utf8: 'is not valid UTF-8 text',
  utf16le: 'is not valid UTF-16LE text',
  utf16be: 'is not valid UTF-16BE text',
}
const NUL = '\0'
const NUL_REASON =
  'contains NUL characters (a binary file, or UTF-16 text without a byte-order mark)'

// `fatal`: a malformed sequence throws instead of becoming U+FFFD. Both
// decoders drop their own byte-order mark (`ignoreBOM` is false): EF BB BF
// for UTF-8, FF FE for UTF-16LE (a big-endian file's FE FF once swapped).
const utf8Decoder = new TextDecoder('utf-8', { fatal: true })
const utf16Decoder = new TextDecoder('utf-16le', { fatal: true })

function hasMark(bytes: Uint8Array, mark: string): boolean {
  return String.fromCodePoint(...bytes.subarray(0, mark.length)) === mark
}

function encodingOf(bytes: Uint8Array): Encoding {
  if (hasMark(bytes, UTF16LE_BOM)) {
    return 'utf16le'
  }
  return hasMark(bytes, UTF16BE_BOM) ? 'utf16be' : 'utf8'
}

function decodeAs(encoding: Encoding, bytes: Uint8Array): string {
  switch (encoding) {
    case 'utf16le': {
      return utf16Decoder.decode(bytes)
    }
    case 'utf16be': {
      // Each code unit's bytes swapped (a copy); an odd length throws.
      return utf16Decoder.decode(Buffer.from(bytes).swap16())
    }
    case 'utf8': {
      return utf8Decoder.decode(bytes)
    }
  }
}

/**
 * A context file's text: UTF-16 (either byte order) by its mark, UTF-8
 * otherwise (its mark dropped); refused when the bytes are not valid in that
 * encoding or the text still holds NUL characters.
 */
export function decodeContextText(bytes: Uint8Array): ContextText {
  const encoding = encodingOf(bytes)
  let text: string
  try {
    text = decodeAs(encoding, bytes)
  } catch {
    return { ok: false, reason: INVALID_REASONS[encoding] }
  }
  return text.includes(NUL) ? { ok: false, reason: NUL_REASON } : { ok: true, text }
}

/**
 * One context file as text; undefined when it does not exist. With
 * `confineTo` (the workspace root, for the files a repository ships) a path
 * whose canonical form leaves that root is refused before it is read. With
 * `maxBytes` a file over that size is refused with its reason, after at most
 * `maxBytes + 1` bytes were read.
 */
export async function readContextText(
  deps: ContextReadDeps,
  absolutePath: string,
  confineTo: string | undefined,
  maxBytes?: number,
): Promise<ContextText | undefined> {
  let readPath = absolutePath
  if (confineTo !== undefined) {
    const resolution = await confineWorkspacePath(confineTo, absolutePath, deps.platform, deps.io)
    if (!resolution.ok) {
      return { ok: false, reason: `is refused: ${resolution.reason}` }
    }
    // Read the path that was checked: a project alias may be replaced with
    // an outside link or junction while canonical resolution awaits.
    readPath = resolution.checkedAbsolute
  }
  const bytes = await deps.io.readFile(readPath, maxBytes)
  if (bytes === undefined) {
    return undefined
  }
  return maxBytes !== undefined && bytes.length > maxBytes
    ? { ok: false, reason: `is over the ${String(maxBytes)} byte limit` }
    : decodeContextText(bytes)
}

src/core/context/customAgents.ts:
// Custom agents for the Model API backend (M76, PLAN.md D49): specialised
// agents with their own prompt, tools, model or effort, and permissions. An
// agent is `<root>/<id>/AGENT.md` with YAML-style front matter (`name`,
// `description`; optional `tools` as a comma-separated allowlist, `model`,
// `effort`, `permission-mode`) above a Markdown body holding the agent's own
// prompt. Project agents live in the workspace's `.agents/agents`, personal
// ones in the managed `muse/agents` root under the config home; a file agent
// shadows a built-in or personal one with the same id. The model runs one
// through `subagent_spawn` with `agent` set to its id, so a run beyond the
// user's own turn is a paid subagent use like any child (D45, D48).
//
// The folder is the extension's own: the CLI names no agent folder
// (`muse --help`, `muse skills --help` and `muse serve --help` list none, and
// its binary's strings hold `.agents/skills`, `.agents/memory` and
// `.agents/plans` but no agent folder, re-checked 2026-09-30 on 1.4.0),
// recorded in PLAN.md D13. A repository's agent files load only in a trusted
// workspace and can only narrow the tools and permissions the session
// already has; a model one names passes the same checks as the user's own
// choice. Muse Code reads its own agents, which the Agent map already shows;
// this backend never sends it one.
//
// An agent file is untrusted input (PLAN.md D49): it is read within a size
// cap, parsed with zod, every field is bounded and free of characters that
// hide, and a file whose front matter the line reader cannot take whole (a
// YAML list, an indented value, a repeated key) is refused rather than
// guessed at, because what it cannot read could have been a narrowing.

import path from 'node:path'
import * as z from 'zod/mini'
import {
  AGENT_DESCRIPTION_MAX_CHARS,
  AGENT_FILE_MAX_BYTES,
  AGENT_FILE_NAME,
  AGENT_ID_PATTERN,
  AGENT_MAX_FILES,
  AGENT_MODEL_MAX_CHARS,
  AGENT_NAME_MAX_CHARS,
  AGENT_TOOL_NAME_PATTERN,
  AGENT_TOOLS_MAX,
  type AgentSource,
  BUILTIN_AGENT_EXPLORE_ID,
  BUILTIN_AGENT_SECOND_OPINION_ID,
  DEFAULT_EFFORT,
  EFFORT_LEVELS,
  type EffortLevel,
  EXPLORE_AGENT_TOOLS,
  MODEL_TEXT,
  PERMISSION_MODES,
  type PermissionMode,
  PERSONAL_AGENTS_DIR_SEGMENTS,
  PROJECT_AGENTS_DIR_SEGMENTS,
  SECOND_OPINION_AGENT_EFFORT,
} from '../../shared/constants'
import { effortLevelsFor } from '../../shared/effort'
import { type ApprovalMode, mspApprovalMode } from '../../shared/permissionModes'
import type { ContextIo } from './contextFiles'
import {
  type CatalogKind,
  type CatalogParse,
  type CatalogRoot,
  type CatalogRootLoad,
  loadCatalogFiles,
  splitFrontMatter,
} from './catalogFiles'
import type { PersonalSkillsRootInput } from './skills'

export interface AgentDefinition {
  /** The directory name (or built-in id): the selector `subagent_spawn` takes as `agent`. */
  readonly id: string
  readonly name: string
  readonly description: string
  /** The agent's own prompt, run as the child's instructions. */
  readonly body: string
  readonly source: AgentSource
  /** The tools the agent may use; undefined runs with the session's own set. */
  readonly tools: readonly string[] | undefined
  /** The model the agent runs on; undefined keeps the session's model. */
  readonly model: string | undefined
  /** The effort the agent runs at; undefined keeps the session's effort. */
  readonly effort: EffortLevel | undefined
  /** The most the agent may do; undefined keeps the session's approval mode. */
  readonly approvalMode: ApprovalMode | undefined
  /** The UI policy, which distinguishes Manual from Edit automatically. */
  readonly permissionMode?: PermissionMode | undefined
}

export type AgentFileSource = 'project' | 'user'
export type AgentRoot = CatalogRoot<AgentFileSource>

/**
 * A definition a root may hold that did not load (M76 review, RV70x): the
 * whole root when it could not be listed (`id` undefined), else one file
 * that was unreadable, over its cap, refused or past the limit. `path` is
 * workspace-relative for the project root, as the user would look for it.
 */
export interface AgentHole {
  readonly source: AgentFileSource
  readonly id: string | undefined
  readonly path: string
}

/** The agents a session may run, and the holes their precedence must respect. */
export interface AgentCatalogue {
  /** Built-ins first, then the files in root order; each id once (its highest loaded source). */
  readonly agents: readonly AgentDefinition[]
  readonly holes: readonly AgentHole[]
}

export interface AgentsLoad extends AgentCatalogue {
  readonly warnings: readonly string[]
}

/** What a name resolves to: an agent, nothing, or a hole of higher precedence than any match. */
export type AgentResolution =
  | { readonly kind: 'found'; readonly agent: AgentDefinition }
  | { readonly kind: 'unknown' }
  | { readonly kind: 'unloaded'; readonly hole: AgentHole }

export const NO_AGENTS: AgentCatalogue = { agents: [], holes: [] }

// Highest first: a project file shadows a personal one, which shadows a built-in.
const AGENT_PRECEDENCE: readonly AgentSource[] = ['project', 'user', 'builtin']

export interface ParsedAgentFile {
  readonly name: string
  readonly description: string
  readonly body: string
  readonly tools: readonly string[] | undefined
  readonly model: string | undefined
  readonly effort: EffortLevel | undefined
  readonly approvalMode: ApprovalMode | undefined
  readonly permissionMode?: PermissionMode | undefined
}

export type AgentFileParse =
  | { readonly ok: true; readonly agent: ParsedAgentFile }
  | { readonly ok: false; readonly reason: string }

/**
 * A custom agent's narrowed run (M76): the resolved agent id and where its
 * file came from, its prompt, the offered tools the child keeps (undefined
 * keeps the session's own set), the effort it runs at, and the most it may
 * do (undefined keeps the session's approval mode). Plain data, so a stored
 * or forked child keeps the narrowing it was spawned with.
 */
export interface AgentRuntime {
  readonly id: string
  readonly source: AgentSource
  readonly prompt: string
  readonly toolAllowlist?: readonly string[] | undefined
  readonly effort: EffortLevel
  readonly approvalMode?: ApprovalMode | undefined
  readonly permissionMode?: PermissionMode | undefined
}

const PERMISSION_MODE_KEY = 'permission-mode'
const LIST_SEPARATOR = ','
// Control characters (other than a tab) and format characters (a direction
// override, a zero-width character): text the model would read that no one
// reviewing the file sees.
const HIDDEN_CHARACTER = /[\p{Cc}\p{Cf}]/u

const AGENT_CATALOG: CatalogKind = {
  kind: 'agent',
  fileName: AGENT_FILE_NAME,
  maxBytes: AGENT_FILE_MAX_BYTES,
  idPattern: AGENT_ID_PATTERN,
  maxEntries: AGENT_MAX_FILES,
}

/** One visible line of bounded length: a name, a description, a model id. */
function boundedLine(maxChars: number) {
  return z.string().check(
    z.trim(),
    z.minLength(1),
    z.maxLength(maxChars),
    z.refine((value) => !HIDDEN_CHARACTER.test(value.replaceAll('\t', ' '))),
  )
}

const agentFrontMatter = z.object({
  name: boundedLine(AGENT_NAME_MAX_CHARS),
  description: boundedLine(AGENT_DESCRIPTION_MAX_CHARS),
  tools: z.optional(z.string().check(z.trim(), z.minLength(1))),
  model: z.optional(boundedLine(AGENT_MODEL_MAX_CHARS)),
  effort: z.optional(z.enum(EFFORT_LEVELS)),
  [PERMISSION_MODE_KEY]: z.optional(z.enum(PERMISSION_MODES)),
})

/**
 * The allowlist a `tools` line names: each entry a function name, at most
 * AGENT_TOOLS_MAX, none empty. A list that is not a list of names (YAML
 * brackets, a sentence) is refused, never read as "all tools".
 */
function toolsOf(value: string | undefined): readonly string[] | 'invalid' | undefined {
  if (value === undefined) {
    return undefined
  }
  const tools = value.split(LIST_SEPARATOR).map((tool) => tool.trim())
  const isValid =
    tools.length <= AGENT_TOOLS_MAX && tools.every((tool) => AGENT_TOOL_NAME_PATTERN.test(tool))
  return isValid ? [...new Set(tools)] : 'invalid'
}

function sortedUnique(keys: readonly string[]): string {
  return [...new Set(keys)].toSorted((a, b) => a.localeCompare(b, 'en')).join(', ')
}

/** Splits an AGENT.md into its front matter (validated with zod) and body. */
export function parseAgentFile(text: string): AgentFileParse {
  const split = splitFrontMatter(text)
  if (!split.ok) {
    return split
  }
  if (split.ignoredLines.length > 0) {
    return {
      ok: false,
      reason:
        'front matter has a line that is not "key: value" (lists and indented values are not supported)',
    }
  }
  if (split.duplicateKeys.length > 0) {
    return { ok: false, reason: `front matter repeats ${sortedUnique(split.duplicateKeys)}` }
  }
  const parsed = agentFrontMatter.safeParse(Object.fromEntries(split.fields))
  if (!parsed.success) {
    const keys = parsed.error.issues.map((issue) => issue.path.map(String).join('.'))
    return {
      ok: false,
      reason: `front matter has an invalid ${sortedUnique(keys) || 'shape'}`,
    }
  }
  const { data } = parsed
  const tools = toolsOf(data.tools)
  if (tools === 'invalid') {
    return { ok: false, reason: 'front matter has an invalid tools' }
  }
  const permissionMode = data[PERMISSION_MODE_KEY]
  return {
    ok: true,
    agent: {
      name: data.name,
      description: data.description,
      body: split.body,
      tools,
      model: data.model,
      effort: data.effort,
      approvalMode: permissionMode === undefined ? undefined : mspApprovalMode(permissionMode),
      ...(permissionMode !== undefined && { permissionMode }),
    },
  }
}

function pathModule(platform: NodeJS.Platform): path.PlatformPath {
  return platform === 'win32' ? path.win32 : path.posix
}

/** The workspace's project agent root. */
export function projectAgentsRoot(workspaceRoot: string, platform: NodeJS.Platform): string {
  return pathModule(platform).join(workspaceRoot, ...PROJECT_AGENTS_DIR_SEGMENTS)
}

/** The managed personal agent root (`$XDG_CONFIG_HOME/muse/agents`, else `~/.config/muse/agents`). */
export function personalAgentsRoot(input: PersonalSkillsRootInput): string {
  const p = pathModule(input.platform)
  const configHome = input.xdgConfigHome ?? p.join(input.homeDir, '.config')
  return p.join(configHome, ...PERSONAL_AGENTS_DIR_SEGMENTS)
}

/** The agents the extension ships: Explore reads without writing, Second opinion consults at high effort. */
export function builtinAgents(): readonly AgentDefinition[] {
  return [
    {
      id: BUILTIN_AGENT_EXPLORE_ID,
      name: 'Explore',
      description: MODEL_TEXT.exploreAgentDescription,
      body: MODEL_TEXT.exploreAgentPrompt,
      source: 'builtin',
      tools: EXPLORE_AGENT_TOOLS,
      model: undefined,
      effort: undefined,
      approvalMode: undefined,
    },
    {
      id: BUILTIN_AGENT_SECOND_OPINION_ID,
      name: 'Second opinion',
      description: MODEL_TEXT.secondOpinionAgentDescription,
      body: MODEL_TEXT.secondOpinionAgentPrompt,
      source: 'builtin',
      tools: undefined,
      model: undefined,
      effort: SECOND_OPINION_AGENT_EFFORT,
      approvalMode: undefined,
    },
  ]
}

export interface AgentsLoaderDeps {
  readonly io: ContextIo
  readonly platform: NodeJS.Platform
}

function parseCatalogFile(text: string): CatalogParse<Omit<AgentDefinition, 'id' | 'source'>> {
  const parsed = parseAgentFile(text)
  return parsed.ok
    ? { ok: true, name: parsed.agent.name, entry: parsed.agent }
    : { ok: false, reason: parsed.reason }
}

/** How a hole names its folder or file: workspace-relative under the project root. */
function holePath(platform: NodeJS.Platform, root: AgentRoot, absolute: string): string {
  return root.confineTo === undefined
    ? absolute
    : pathModule(platform).relative(root.confineTo, absolute)
}

/** Every root's holes: an unlisted root whole, else each file it did not yield. */
export function agentHoles(
  platform: NodeJS.Platform,
  roots: readonly CatalogRootLoad<AgentFileSource>[],
): readonly AgentHole[] {
  return roots.flatMap(({ root, listingFailure, refused }): AgentHole[] =>
    listingFailure === undefined
      ? refused.map((file) => ({
          source: root.source,
          id: file.id,
          path: holePath(platform, root, file.file),
        }))
      : [{ source: root.source, id: undefined, path: holePath(platform, root, root.directory) }],
  )
}

/**
 * Every valid agent: the built-ins first, then the files in root order with
 * ids sorted within a root. A file agent shadows a built-in or personal one
 * with the same id. A root that cannot be listed leaves the others loaded
 * and is a hole, as is each file a root holds but did not yield (RV70x).
 */
export async function loadAgents(
  deps: AgentsLoaderDeps,
  roots: readonly AgentRoot[],
): Promise<AgentsLoad> {
  const load = await loadCatalogFiles(deps, roots, AGENT_CATALOG, parseCatalogFile)
  const warnings = [...load.warnings]
  const files: AgentDefinition[] = load.entries.map((entry) => ({
    id: entry.id,
    source: entry.source,
    ...entry.entry,
  }))
  const keptBuiltins = builtinAgents().filter((builtin) => {
    const file = files.find((agent) => agent.id === builtin.id)
    if (file === undefined) {
      return true
    }
    warnings.push(
      `builtin agent ${builtin.id} skipped: the ${file.source} agent with the same id takes precedence`,
    )
    return false
  })
  return {
    agents: [...keptBuiltins, ...files],
    holes: agentHoles(deps.platform, load.roots),
    warnings,
  }
}

/**
 * The agent a name runs (M76 review, RV70x): walking the sources from the
 * highest, a hole that may hold the name refuses it before any lower
 * definition can stand in, so a project file that did not load never turns
 * into a broader personal or built-in agent.
 */
export function resolveAgent(catalogue: AgentCatalogue, id: string): AgentResolution {
  for (const source of AGENT_PRECEDENCE) {
    const hole = catalogue.holes.find(
      (candidate) =>
        candidate.source === source && (candidate.id === undefined || candidate.id === id),
    )
    if (hole !== undefined) {
      return { kind: 'unloaded', hole }
    }
    const agent = catalogue.agents.find(
      (candidate) => candidate.source === source && candidate.id === id,
    )
    if (agent !== undefined) {
      return { kind: 'found', agent }
    }
  }
  return { kind: 'unknown' }
}

/** The agents the model is offered: those whose name resolves to them. */
export function offeredAgents(catalogue: AgentCatalogue): readonly AgentDefinition[] {
  return catalogue.agents.filter((agent) => {
    const resolved = resolveAgent(catalogue, agent.id)
    return resolved.kind === 'found' && resolved.agent === agent
  })
}

/** The model a spawn with this agent runs on: the agent's, else the session's. */
export function resolveAgentModel(sessionModel: string, agentModel: string | undefined): string {
  return agentModel ?? sessionModel
}

/**
 * The approval mode a spawn with this agent runs under: the agent's when it
 * narrows the session's, else the session's. A repository's file can never
 * widen what the session already has. Least to most permissive: reads only,
 * reads with edits and commands asking, edits running with commands asking,
 * everything running.
 */
const APPROVAL_NARROWING: readonly ApprovalMode[] = [
  'denyUnmatched',
  'promptUnmatched',
  'onRequest',
  'allowAll',
]

export function narrowApprovalMode(
  sessionMode: ApprovalMode,
  agentMode: ApprovalMode | undefined,
): ApprovalMode {
  if (agentMode === undefined) {
    return sessionMode
  }
  return APPROVAL_NARROWING.indexOf(agentMode) <= APPROVAL_NARROWING.indexOf(sessionMode)
    ? agentMode
    : sessionMode
}

/**
 * The tools a spawn with this agent is offered: the agent's allowlist met
 * with what the session offers. Undefined runs with the session's own set.
 */
export function narrowTools(
  sessionTools: readonly string[],
  agentTools: readonly string[] | undefined,
): readonly string[] | undefined {
  if (agentTools === undefined) {
    return undefined
  }
  const allowed = new Set(agentTools)
  return sessionTools.filter((tool) => allowed.has(tool))
}

/**
 * The effort a spawn with this agent runs at: the agent's when the model
 * serves it, else the highest tier it serves; without one the session
 * default, dropped the same way when the model does not serve it (D10).
 */
export function resolveAgentEffort(
  modelId: string,
  agentEffort: EffortLevel | undefined,
): EffortLevel {
  const served = effortLevelsFor(modelId)
  const wanted = agentEffort ?? DEFAULT_EFFORT
  return served.includes(wanted) ? wanted : (served.at(-1) ?? DEFAULT_EFFORT)
}

src/core/context/skills.ts:
// Skills for the Model API backend (PLAN.md D13), by Muse Code's layout:
// `<root>/<id>/SKILL.md` with YAML-style front matter (`name`,
// `description`; optional `user-invocable`, `argument-hint`) above a
// Markdown body. Project skills live in the workspace's `.agents/skills`,
// personal ones in Muse Code's managed root under the config home; a
// project skill shadows a personal one with the same id. The catalogue
// (id and description) goes into the instructions; the body is loaded on
// demand by `read_skill` or a typed `/id arguments` invocation.
//
// A skill directory may be a symbolic link or a junction (D27): a personal
// one is followed wherever it leads, since the user made it in their own
// config root (a dotfiles checkout is the usual target), while a project one
// is a file the repository ships and is confined to the workspace like every
// other workspace read (D24): a link that leads outside it is skipped with a
// warning, as the file tools refuse it, and the other skills still load.
//
// The bundled skills (M89, PLAN.md D68) are a third source, the lowest: the
// `skills/` folder of the package vendored inside the installed extension,
// confined to that package, shadowed by a project or personal skill with the
// same id. Their bodies name `${SKILL_ROOT}` paths, so each reaches the model
// after one line saying which folder that is.

import path from 'node:path'
import {
  BUNDLED_SKILLS_DIR,
  BUNDLED_SKILLS_SOURCES_DIR,
  BUNDLED_SKILLS_VENDOR_SEGMENTS,
  MODEL_TEXT,
  PERSONAL_SKILLS_DIR_SEGMENTS,
  PROJECT_SKILLS_DIR_SEGMENTS,
  SKILL_FILE_MAX_BYTES,
  SKILL_FILE_NAME,
  SKILL_ID_PATTERN,
  type SKILL_SOURCES,
} from '../../shared/constants'
import type { ContextIo } from './contextFiles'
import {
  type CatalogKind,
  type CatalogParse,
  type CatalogRoot,
  loadCatalogFiles,
  splitFrontMatter,
} from './catalogFiles'

export type SkillSource = (typeof SKILL_SOURCES)[number]

export interface SkillDefinition {
  /** The directory name: the selector a `/id` invocation and `read_skill` use. */
  readonly id: string
  readonly name: string
  readonly description: string
  readonly body: string
  readonly source: SkillSource
  /** Shown in the palette unless the front matter says `user-invocable: false`. */
  readonly isUserInvocable: boolean
  readonly argumentHint: string | undefined
  /** A bundled skill's package folder, its `SKILL_ROOT` (M89); undefined for the others. */
  readonly packageRoot?: string
}

export interface SkillRoot extends CatalogRoot<SkillSource> {
  /** The package folder the root's skills name as `SKILL_ROOT` (the bundled root, M89). */
  readonly packageRoot?: string
}

/**
 * The bundled source as the host hands it in (M89, PLAN.md D68): the
 * vendored package inside the installed extension, and its setting, read at
 * each load so turning it off empties the source at the next refresh.
 */
export interface BundledSkillsSource {
  readonly packageRoot: string
  readonly isEnabled: () => boolean
}

export interface SkillsLoad {
  readonly skills: readonly SkillDefinition[]
  readonly warnings: readonly string[]
}

export interface ParsedSkillFile {
  readonly name: string
  readonly description: string
  readonly isUserInvocable: boolean
  readonly argumentHint: string | undefined
  readonly body: string
}

export type SkillFileParse =
  | { readonly ok: true; readonly skill: ParsedSkillFile }
  | { readonly ok: false; readonly reason: string }

const FALSE = 'false'
const NAME_KEY = 'name'
const DESCRIPTION_KEY = 'description'
const USER_INVOCABLE_KEY = 'user-invocable'
const ARGUMENT_HINT_KEY = 'argument-hint'

const SKILL_CATALOG: CatalogKind = {
  kind: 'skill',
  fileName: SKILL_FILE_NAME,
  maxBytes: SKILL_FILE_MAX_BYTES,
  idPattern: SKILL_ID_PATTERN,
}

/** Splits a SKILL.md into its front matter fields and body. */
export function parseSkillFile(text: string): SkillFileParse {
  const split = splitFrontMatter(text)
  if (!split.ok) {
    return split
  }
  const { fields } = split
  const name = fields.get(NAME_KEY)
  if (name === undefined || name === '') {
    return { ok: false, reason: 'front matter has no name' }
  }
  const description = fields.get(DESCRIPTION_KEY)
  if (description === undefined || description === '') {
    return { ok: false, reason: 'front matter has no description' }
  }
  const argumentHint = fields.get(ARGUMENT_HINT_KEY)
  return {
    ok: true,
    skill: {
      name,
      description,
      isUserInvocable: fields.get(USER_INVOCABLE_KEY)?.toLowerCase() !== FALSE,
      argumentHint: argumentHint === '' ? undefined : argumentHint,
      body: split.body,
    },
  }
}

function pathModule(platform: NodeJS.Platform): path.PlatformPath {
  return platform === 'win32' ? path.win32 : path.posix
}

/** The workspace's project skill root. */
export function projectSkillsRoot(workspaceRoot: string, platform: NodeJS.Platform): string {
  return pathModule(platform).join(workspaceRoot, ...PROJECT_SKILLS_DIR_SEGMENTS)
}

export interface PersonalSkillsRootInput {
  readonly platform: NodeJS.Platform
  readonly homeDir: string
  readonly xdgConfigHome: string | undefined
}

/** Muse Code's managed personal skill root (`$XDG_CONFIG_HOME/muse/skills`, else `~/.config/muse/skills`). */
export function personalSkillsRoot(input: PersonalSkillsRootInput): string {
  const p = pathModule(input.platform)
  const configHome = input.xdgConfigHome ?? p.join(input.homeDir, '.config')
  return p.join(configHome, ...PERSONAL_SKILLS_DIR_SEGMENTS)
}

/** The package vendored inside the installed extension (M89): `<extension>/vendor/high-quality-projects-skill`. */
export function bundledSkillsPackageRoot(extensionRoot: string, platform: NodeJS.Platform): string {
  return pathModule(platform).join(extensionRoot, ...BUNDLED_SKILLS_VENDOR_SEGMENTS)
}

/** The bundled package's skill root: its `skills/` folder (M89). */
export function bundledSkillsRoot(packageRoot: string, platform: NodeJS.Platform): string {
  return pathModule(platform).join(packageRoot, BUNDLED_SKILLS_DIR)
}

/**
 * Where the Muse Code install keeps its copy of the package (M89):
 * `skill-sources`, beside the managed personal skill root, in the config home
 * that root resolves to.
 */
export function bundledSkillSourcesRoot(input: PersonalSkillsRootInput): string {
  const p = pathModule(input.platform)
  return p.join(p.dirname(personalSkillsRoot(input)), BUNDLED_SKILLS_SOURCES_DIR)
}

/**
 * A skill's body as the model reads it (`read_skill`, a typed `/id`): a
 * bundled one after the line naming its package root (M89, PLAN.md D68).
 */
export function skillBodyForModel(skill: SkillDefinition): string {
  return skill.packageRoot === undefined
    ? skill.body
    : `${MODEL_TEXT.bundledSkillRoot} ${skill.packageRoot}\n\n${skill.body}`
}

export interface SkillsLoaderDeps {
  readonly io: ContextIo
  readonly platform: NodeJS.Platform
}

function parseCatalogFile(text: string): CatalogParse<ParsedSkillFile> {
  const parsed = parseSkillFile(text)
  return parsed.ok
    ? { ok: true, name: parsed.skill.name, entry: parsed.skill }
    : { ok: false, reason: parsed.reason }
}

/** Every valid skill under the roots, in root order; ids sorted within a root. */
export async function loadSkills(
  deps: SkillsLoaderDeps,
  roots: readonly SkillRoot[],
): Promise<SkillsLoad> {
  const load = await loadCatalogFiles(deps, roots, SKILL_CATALOG, parseCatalogFile)
  // Each source has one root, so an entry's source names its package.
  const packageRoots = new Map(
    roots.flatMap((root) =>
      root.packageRoot === undefined ? [] : [[root.source, root.packageRoot]],
    ),
  )
  return {
    skills: load.entries.map((entry) => {
      const packageRoot = packageRoots.get(entry.source)
      return {
        id: entry.id,
        source: entry.source,
        ...entry.entry,
        ...(packageRoot !== undefined && { packageRoot }),
      }
    }),
    warnings: load.warnings,
  }
}

src/core/diagnostics.ts:
// The `getDiagnostics` IDE tool: the errors and warnings in VS Code's Problems
// panel as text for the model, optionally scoped to one file (the Claude Code
// `mcp__ide__getDiagnostics` contract). Only files under the workspace root
// (the first folder) are reported, by their relative path, so no absolute
// path of another folder or of the user's other files reaches the model; a
// message is clipped at `DIAGNOSTIC_MESSAGE_MAX_CHARS`; a requested file is
// matched by its exact workspace-relative path, and a request that names no
// file in the workspace is an error result, never a crash (PLAN.md D27).
// Pure; the host supplies the entries.

import { fileURLToPath } from 'node:url'
import {
  DIAGNOSTIC_MESSAGE_MAX_CHARS,
  DIAGNOSTICS_MAX_ENTRIES,
  IDE_MCP_TOOL_DIAGNOSTICS,
  MODEL_TEXT,
  MCP_ANNOTATIONS_READ_ONLY,
} from '../shared/constants'
import { fill } from '../shared/l10n/text'
import type { McpTool } from './mcp'
import { resolveAgainstRoot } from './workspaceRoot'

export type DiagnosticSeverity = 'error' | 'warning' | 'information' | 'hint'

/** VS Code's `DiagnosticSeverity` values, in order: `Error` is 0, `Hint` is 3. */
export const DIAGNOSTIC_SEVERITIES: readonly DiagnosticSeverity[] = [
  'error',
  'warning',
  'information',
  'hint',
]

export interface DiagnosticEntry {
  /**
   * Relative to the root with forward slashes (`rootRelativePath`);
   * undefined for a resource outside it, which is never reported.
   */
  readonly path: string | undefined
  readonly severity: DiagnosticSeverity
  /** 1-based. */
  readonly line: number
  readonly column: number
  readonly message: string
  readonly source: string | undefined
}

/** An entry for a file in the workspace. */
export interface WorkspaceDiagnostic extends DiagnosticEntry {
  readonly path: string
}

const SEVERITY_ORDER: Readonly<Record<DiagnosticSeverity, number>> = {
  error: 0,
  warning: 1,
  information: 2,
  hint: 3,
}

const NO_DIAGNOSTICS = 'No diagnostics.'
const URI_ARGUMENT = 'uri'
const FILE_URI = /^file:/i
const HIGH_SURROGATE = /[\uD800-\uDBFF]$/

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

function isInWorkspace(entry: DiagnosticEntry): entry is WorkspaceDiagnostic {
  return entry.path !== undefined
}

/** At most `DIAGNOSTIC_MESSAGE_MAX_CHARS`, never splitting a surrogate pair, with the rest counted. */
function clipMessage(message: string): string {
  if (message.length <= DIAGNOSTIC_MESSAGE_MAX_CHARS) {
    return message
  }
  let kept = message.slice(0, DIAGNOSTIC_MESSAGE_MAX_CHARS)
  if (HIGH_SURROGATE.test(kept)) {
    kept = kept.slice(0, -1)
  }
  return `${kept}… [${String(message.length - kept.length)} characters clipped]`
}

type PathRequest =
  | { readonly ok: true; readonly path: string; readonly fsPath: string }
  | { readonly ok: false; readonly reason: string }

/**
 * The workspace-relative path a request names: a `file:` URI (as VS Code
 * writes one, `file:///c%3A/…`), an absolute path, or a path relative to the
 * root. A malformed URI (bad percent-encoding throws in the decoder) or a
 * path that names no file in the workspace comes back with the reason.
 */
function requestedPath(given: string, deps: DiagnosticsToolDeps): PathRequest {
  let fsPath: string
  try {
    fsPath = FILE_URI.test(given)
      ? fileURLToPath(given, { windows: deps.platform === 'win32' })
      : resolveAgainstRoot(given, deps.workspaceRoot, deps.platform)
  } catch (error: unknown) {
    return {
      ok: false,
      reason: `${given} cannot be read as a file URI or path: ${describe(error)}`,
    }
  }
  const relative = deps.relativeInRoot(fsPath)
  return relative === undefined
    ? { ok: false, reason: `${given} does not name a file in the workspace` }
    : { ok: true, path: relative, fsPath }
}

function formatEntry(entry: WorkspaceDiagnostic): string {
  const source = entry.source === undefined ? '' : ` [${entry.source}]`
  return `${entry.path}:${String(entry.line)}:${String(entry.column)}: ${entry.severity}: ${clipMessage(entry.message)}${source}`
}

/**
 * The tool's text for `entries`, worst first, capped at `max` with a count
 * (the verify loop sends fewer than the tool, M68).
 */
export function formatDiagnostics(
  entries: readonly WorkspaceDiagnostic[],
  max: number = DIAGNOSTICS_MAX_ENTRIES,
): string {
  if (entries.length === 0) {
    return NO_DIAGNOSTICS
  }
  const sorted = entries.toSorted(
    (a, b) =>
      SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity] ||
      a.path.localeCompare(b.path) ||
      a.line - b.line,
  )
  const shown = sorted.slice(0, max).map((entry) => formatEntry(entry))
  if (sorted.length > max) {
    shown.push(`… ${String(sorted.length - max)} more not shown`)
  }
  return shown.join('\n')
}

export interface DiagnosticsToolDeps {
  readonly getDiagnostics: () => readonly DiagnosticEntry[]
  /** The first folder's path, which a relative request is resolved against. */
  readonly workspaceRoot: string | undefined
  readonly platform: NodeJS.Platform
  /** An absolute path relative to the root, undefined outside it (`rootRelativePath`). */
  readonly relativeInRoot: (absolutePath: string) => string | undefined
  /**
   * Shows a file the request names, waits for its language server and reads
   * its diagnostics while it shows (M68): the servers report only on files
   * an editor shows, and may clear them when its tab closes. Undefined when
   * none were read; absent, the tool reads what VS Code holds now.
   */
  readonly settleFile?: (
    absolutePath: string,
    signal: AbortSignal | undefined,
  ) => Promise<readonly DiagnosticEntry[] | undefined>
}

/** Paths compare as the platform's file system does: case-insensitively on Windows. */
function pathKey(relativePath: string, platform: NodeJS.Platform): string {
  return platform === 'win32' ? relativePath.toLowerCase() : relativePath
}

export function diagnosticsTool(deps: DiagnosticsToolDeps): McpTool {
  return {
    name: IDE_MCP_TOOL_DIAGNOSTICS,
    description:
      "Language-server diagnostics: the errors and warnings in VS Code's Problems panel for the files in the workspace, worst first. Optionally scoped to one file, which is then shown in an editor so its language server reports on it.",
    inputSchema: {
      type: 'object',
      properties: {
        [URI_ARGUMENT]: {
          type: 'string',
          description: 'A file:// URI or workspace-relative path; omit for the whole workspace.',
        },
      },
    },
    // It only reads the Problems panel (D49's rule for tools on `ide`, M67).
    annotations: MCP_ANNOTATIONS_READ_ONLY,
    // A request that names no workspace file rejects, so the server answers
    // with an error result the model can read.
    call: async (args, signal) => {
      const uri = args[URI_ARGUMENT]
      const { platform } = deps
      const inWorkspace = () => deps.getDiagnostics().filter((entry) => isInWorkspace(entry))
      if (typeof uri !== 'string' || uri === '') {
        return formatDiagnostics(inWorkspace())
      }
      const request = requestedPath(uri, deps)
      if (!request.ok) {
        throw new Error(request.reason)
      }
      const read = await deps.settleFile?.(request.fsPath, signal)
      if (read !== undefined) {
        return formatDiagnostics(read.map((entry) => ({ ...entry, path: request.path })))
      }
      const wanted = pathKey(request.path, platform)
      const found = inWorkspace().filter((entry) => pathKey(entry.path, platform) === wanted)
      // A file its server never reported on is not checked, never clean (M68).
      return deps.settleFile !== undefined && found.length === 0
        ? fill(MODEL_TEXT.diagnosticsNotSettled, { path: request.path })
        : formatDiagnostics(found)
    },
  }
}

src/core/editorContext.ts:
// The active editor as context for a message (Claude Code's "active file
// chip"): the text the model receives, in the wording Claude Code's own IDE
// reminders use (`<ide_selection>` with the selected lines,
// `<ide_opened_file>` for a bare open file). The chip label lives in
// src/shared/editorContext.ts so the webview can build it too. Pure.

import { IDE_CONTEXT_TAGS, MODEL_TEXT, SELECTION_TEXT_MAX_CHARS } from '../shared/constants'
import type { EditorContextSummary } from '../shared/protocol'

export interface EditorContext extends EditorContextSummary {
  /**
   * The highlighted text, or undefined when the file's content must not be
   * shared (excluded from the workspace index, as Claude Code treats
   * `files.exclude` / gitignored files: path only).
   */
  readonly selectedText: string | undefined
}

export function editorContextSummary(context: EditorContext): EditorContextSummary {
  const { relativePath, startLine, endLine, isEmpty } = context
  return { relativePath, startLine, endLine, isEmpty }
}

function clipped(text: string): string {
  return text.length > SELECTION_TEXT_MAX_CHARS
    ? `${text.slice(0, SELECTION_TEXT_MAX_CHARS)}\n${MODEL_TEXT.selectionClipped}`
    : text
}

/** The context part appended to the turn's prompt (never shown as typed text). */
export function editorContextText(context: EditorContext): string {
  const { relativePath, startLine, endLine, isEmpty, selectedText } = context
  if (isEmpty) {
    return `<${IDE_CONTEXT_TAGS.openedFile}>The user opened the file ${relativePath} in the IDE. This may or may not be related to the current task.</${IDE_CONTEXT_TAGS.openedFile}>`
  }
  const lines = `the lines ${String(startLine)} to ${String(endLine)} from ${relativePath}`
  const body =
    selectedText === undefined
      ? `${lines}. ${MODEL_TEXT.selectionNotShared}`
      : `${lines}:\n${clipped(selectedText)}\n`
  return `<${IDE_CONTEXT_TAGS.selection}>The user selected ${body}</${IDE_CONTEXT_TAGS.selection}>`
}

src/core/executables.ts:
// Finding a program on PATH without the working directory (PLAN.md D24).
// A bare name handed to `spawn` / `execFile` is looked up by the platform:
// libuv on Windows tries the current directory before PATH, and an empty or
// relative PATH entry means "here" on every platform. With the workspace as
// the working directory, a `git.exe` or `bash` committed to a repository
// would run instead of the real one. This resolver takes only absolute PATH
// entries, and on Windows only the extensions `execFile` can start without a
// shell (a `.cmd` needs one, and a shell string is banned, D4). Pure: the
// file probe is injected.

import path from 'node:path'

export interface ExecutableProbe {
  readonly platform: NodeJS.Platform
  /** The PATH value, unsplit. */
  readonly pathVariable: string | undefined
  readonly fileExists: (filePath: string) => boolean
}

// `execFile` starts these directly; batch files need a shell.
const WINDOWS_EXECUTABLE_EXTENSIONS = ['.exe', '.com'] as const

/** The absolute, non-empty entries of a PATH value, in order. */
export function absolutePathEntries(
  platform: NodeJS.Platform,
  pathVariable: string | undefined,
): readonly string[] {
  const p = platform === 'win32' ? path.win32 : path.posix
  const separator = platform === 'win32' ? ';' : ':'
  return (pathVariable ?? '')
    .split(separator)
    .map((entry) => entry.trim())
    .filter((entry) => entry !== '' && p.isAbsolute(entry))
}

/** The absolute path of `name` on PATH, or undefined when it is not there. */
export function resolveExecutable(name: string, probe: ExecutableProbe): string | undefined {
  const p = probe.platform === 'win32' ? path.win32 : path.posix
  const candidates =
    probe.platform === 'win32'
      ? WINDOWS_EXECUTABLE_EXTENSIONS.map((extension) => `${name}${extension}`)
      : [name]
  for (const directory of absolutePathEntries(probe.platform, probe.pathVariable)) {
    for (const candidate of candidates) {
      const full = p.join(directory, candidate)
      if (probe.fileExists(full)) {
        return full
      }
    }
  }
  return undefined
}

src/core/export/sessionTransfer.ts:
// Session export, import and share files (M84, PLAN.md D49): one portable
// JSON document for all three, validated with zod on both ends.
//
// - What it holds: the conversation's transcript items, as the history the
//   Markdown export reads (M30), with only the fields a reader needs. Live
//   state (stored outputs and patches, child sessions, background handles,
//   workflow handles) never enters it, nor does the Model API replay: an
//   import rebuilds what the model reads from the transcript.
// - Known credential shapes (the log redactor's list, `redactSecrets`) and
//   the key digest are scrubbed from every string, always; a secret in a
//   shape the list does not know stays, which is why the preview shows the
//   file before anything is written. Account ids (e-mail addresses) and
//   paths are redacted by default.
// - Every imported byte is parsed: the format and its version first, then
//   the schema with its caps, then any field the schema does not know,
//   anywhere in the file, fails the whole file.
// - An import mints fresh session, turn and item ids (schedules are keyed by
//   session id, so none can follow), keeps the forced asking mode the caller
//   gives, drops goals, todos, outputs and patches, takes the user's own
//   model, and hands the model each imported turn as untrusted data in a
//   user-role message, never as its own replies or tool calls.
//
// Pure: the host reads the session and writes the file. No hosted sharing:
// the file moves on the user's own disk.

import * as z from 'zod/mini'
import { type ItemSnapshot, itemSnapshotFields } from '../../shared/agentEvents'
import {
  DEFAULT_EFFORT,
  MODEL_API_IMPORT_MAX_REPLAY_BYTES,
  MODEL_TEXT,
  REDACTED_MARK,
  SESSION_EXPORT_FIELD_PATH_MAX,
  SESSION_EXPORT_FORMAT,
  SESSION_EXPORT_MAX_ITEMS,
  SESSION_EXPORT_SCRUB_SLICE_CHARS,
  SESSION_EXPORT_VERSION,
  STORED_SESSION_VERSION,
  UI_TEXT,
} from '../../shared/constants'
import { fill, formatBytes } from '../../shared/l10n/text'
import type { ApprovalMode } from '../../shared/permissionModes'
import { BACKEND_KINDS, type BackendKind } from '../../shared/protocol'
import { redactableSlices, redactSecrets } from '../redact'
import type {
  StoredReplayItem,
  StoredSession,
  StoredTranscriptItem,
} from '../backends/modelapi/sessionStore'

/**
 * The transcript fields a portable file keeps: what the panel, the share
 * view and the model need to read the conversation. Ids of live state
 * (`outputRef`, `patchRef`, `subagentId`, `childSessionId`, the workflow
 * handles, `background`) and opaque lists (`children`,
 * `modelVisibleContent`) stay behind; a file that holds one is refused.
 */
const portableItemFields = {
  itemId: itemSnapshotFields.itemId,
  kind: itemSnapshotFields.kind,
  status: itemSnapshotFields.status,
  text: itemSnapshotFields.text,
  summary: itemSnapshotFields.summary,
  tool: itemSnapshotFields.tool,
  args: itemSnapshotFields.args,
  visibleOutput: itemSnapshotFields.visibleOutput,
  failureReason: itemSnapshotFields.failureReason,
  patchSummary: itemSnapshotFields.patchSummary,
  fallbackText: itemSnapshotFields.fallbackText,
  attachments: itemSnapshotFields.attachments,
  role: itemSnapshotFields.role,
  objective: itemSnapshotFields.objective,
  durationMs: itemSnapshotFields.durationMs,
  result: itemSnapshotFields.result,
  commandText: itemSnapshotFields.commandText,
  exitCode: itemSnapshotFields.exitCode,
  exitSignal: itemSnapshotFields.exitSignal,
  paid: itemSnapshotFields.paid,
  citations: itemSnapshotFields.citations,
  message: itemSnapshotFields.message,
} as const
const PORTABLE_ITEM_KEYS: ReadonlySet<string> = new Set(Object.keys(portableItemFields))

export const sessionExportSchema = z.object({
  format: z.literal(SESSION_EXPORT_FORMAT),
  version: z.literal(SESSION_EXPORT_VERSION),
  exportedAt: z.iso.datetime(),
  sourceBackend: z.enum(BACKEND_KINDS),
  /**
   * Whether paths and account ids were redacted when the file was written:
   * the writer's claim, which a reader cannot check.
   */
  redacted: z.boolean(),
  name: z.optional(z.string()),
  /** The model the conversation ran on; informational, an import never takes it. */
  modelId: z.string(),
  transcript: z.array(z.object(portableItemFields)).check(z.maxLength(SESSION_EXPORT_MAX_ITEMS)),
})

export type SessionExport = z.infer<typeof sessionExportSchema>

export type SessionExportParse =
  | { readonly ok: true; readonly doc: SessionExport }
  | { readonly ok: false; readonly reason: string }

// Read before the schema, so a file of another format or a newer version is
// named as such instead of as a list of schema errors.
const headerSchema = z.object({ format: z.string(), version: z.number() })

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/** One step of a path into the file: a key, or an index. */
function pathStep(path: string, step: PropertyKey): string {
  if (typeof step === 'number') {
    return `${path}[${String(step)}]`
  }
  return path === '' ? String(step) : `${path}.${String(step)}`
}

// Control characters (a newline, an escape) in a key a file chose.
const CONTROL_CHARACTERS = /\p{Cc}/gu
const ELLIPSIS = '…'

/**
 * A path into a refused file as a notice and the log may carry it: its keys
 * are the file's own text, so control characters are replaced and the whole
 * is cut short.
 */
function safePath(path: string): string {
  const scrubbed = scrubText(path, { redact: true, localRoots: [] }, [], {
    secrets: 0,
    accounts: 0,
    paths: 0,
  })
  const printable = scrubbed.replaceAll(CONTROL_CHARACTERS, () => '?')
  return printable.length > SESSION_EXPORT_FIELD_PATH_MAX
    ? `${printable.slice(0, SESSION_EXPORT_FIELD_PATH_MAX)}${ELLIPSIS}`
    : printable
}

/**
 * The first field of `raw` the schema did not keep, as a path
 * (`transcript[2].outputRef`). zod drops unknown keys while parsing, so the
 * parse is compared against what was read.
 */
function firstUnknownField(raw: unknown, parsed: unknown, path: string): string | undefined {
  if (Array.isArray(raw) && Array.isArray(parsed)) {
    for (const [index, entry] of raw.entries()) {
      const found = firstUnknownField(entry, parsed[index], pathStep(path, index))
      if (found !== undefined) {
        return found
      }
    }
    return undefined
  }
  if (!isRecord(raw) || !isRecord(parsed)) {
    return undefined
  }
  for (const [key, value] of Object.entries(raw)) {
    const at = pathStep(path, key)
    if (!Object.hasOwn(parsed, key)) {
      return at
    }
    const found = firstUnknownField(value, parsed[key], at)
    if (found !== undefined) {
      return found
    }
  }
  return undefined
}

/**
 * Validates one parsed JSON document: format, version, schema and caps, then
 * unknown fields. A refusal names one problem in a bounded line: the file's
 * own text never reaches a notice or the log as it was written.
 */
export function parseSessionExport(raw: unknown): SessionExportParse {
  const header = headerSchema.safeParse(raw)
  if (!header.success || header.data.format !== SESSION_EXPORT_FORMAT) {
    return { ok: false, reason: UI_TEXT.transferNotAnExport }
  }
  if (header.data.version !== SESSION_EXPORT_VERSION) {
    return {
      ok: false,
      reason: fill(UI_TEXT.transferVersionUnsupported, { version: String(header.data.version) }),
    }
  }
  const result = sessionExportSchema.safeParse(raw)
  if (!result.success) {
    const [issue] = result.error.issues
    const steps = issue?.path ?? []
    let at = ''
    for (const step of steps) {
      at = pathStep(at, step)
    }
    return {
      ok: false,
      reason: fill(UI_TEXT.transferInvalidField, { field: safePath(at === '' ? '.' : at) }),
    }
  }
  const unknown = firstUnknownField(raw, result.data, '')
  return unknown === undefined
    ? { ok: true, doc: result.data }
    : { ok: false, reason: fill(UI_TEXT.transferUnknownField, { field: safePath(unknown) }) }
}

// --- Redaction ---

// A SHA-256 digest such as the stored session's `accountId`, and any longer
// hex run around one: cutting a run into 64-character pieces would leave
// part of a digest behind. It starts only where no hex digit precedes, so a
// run is tried once, not once per digit in it (common in ordinary text). The
// credential shapes are the log redactor's (`redactSecrets`), the one list
// the extension keeps.
const KEY_DIGEST = /(?<![A-Fa-f0-9])[A-Fa-f0-9]{64,}/g
// Bounded as RFC 5321 bounds an address's parts, so a long run of word
// characters (a base64 blob in a tool output) is scanned in linear time.
const EMAIL_ADDRESS = /[\w.%+-]{1,64}@[A-Za-z0-9.-]{1,253}\.[A-Za-z]{2,63}/g
// `file://` URIs, whose path the POSIX rule's guard would skip. One whose
// path a local root has already replaced is left as it reads.
const FILE_URI = /\bfile:\/\/(?!\/*\[)[^\s"'<>()[\]]+/gi
// Absolute POSIX paths of two or more segments. The lookbehind keeps
// relative paths (`a/b`, `./a/b`), URLs (`https://…`) and bare commands
// (`/export`) intact; over-redaction stays the safe direction. A segment
// holds the ASCII characters a name commonly does, or any character outside
// ASCII that is not white space, so `/srv/私密`, `/Users/José` and an emoji
// folder go whole (RV84c C2); CJK punctuation glued after a path goes with
// it. Each segment ends at a `/`, so the scan stays linear.
const POSIX_PATH =
  /(?<![\w.:/\\])\/(?:(?:[\w.~+%-]|[^\p{ASCII}\s])+\/)+(?:[\w.~+%-]|[^\p{ASCII}\s])+/gu
// Drive-letter paths with either separator, and UNC paths.
const WINDOWS_PATH = /(?<!\w)[A-Za-z]:[\\/][^\s"'<>|?*]+|\\\\[^\s"'<>|?*]+/g
const PATH_PATTERNS: readonly RegExp[] = [FILE_URI, POSIX_PATH, WINDOWS_PATH]
const PATH_SEPARATORS = /[\\/]+/
const TRAILING_SEPARATORS = /[\\/]+$/
const LINE_BREAK = '\n'
// Where a path that starts at a local root ends.
const PATH_END = /[\s"'<>|]/
// A local root shorter than this many segments (`/`, `C:\`, `/root`) is left
// to the patterns above: replacing it verbatim would eat ordinary text.
const LOCAL_ROOT_MIN_SEGMENTS = 2

export interface ScrubCounts {
  /** Credentials and key digests scrubbed, always. */
  secrets: number
  /** Account ids (e-mail addresses) redacted, by default. */
  accounts: number
  /** Paths redacted, by default. */
  paths: number
}

export interface ExportRedaction {
  /** Redact account ids and paths; false only after the preview asked for the full file. */
  readonly redact: boolean
  /**
   * This machine's own folders (the workspace folders, the home folder),
   * replaced wherever they appear, spaces and all: the patterns stop at a
   * space, and a user name in a home path is what matters most.
   */
  readonly localRoots: readonly string[]
}

/** The text with every known credential shape and key digest replaced by the mark. */
function withoutCredentials(text: string): string {
  return redactSecrets(text).replaceAll(KEY_DIGEST, () => REDACTED_MARK)
}

/**
 * Text as local roots are looked up in it: lower case, and every run of
 * separators one `/`, so `C:\Users`, `c:/users` and the JSON-escaped
 * `C:\\Users` all read `c:/users`. `offsets[i]` is where the folded
 * character `i` starts in the original, and `offsets[folded.length]` is the
 * original's length.
 */
interface FoldedText {
  readonly text: string
  readonly offsets: readonly number[]
}

// One pass with no allocation per character: a spread of a fresh array per
// character made this half of a whole export's time (RV84 #9).
function foldText(text: string): FoldedText {
  const parts: string[] = []
  const offsets: number[] = []
  let at = 0
  let isAfterSeparator = false
  for (const char of text) {
    if (char === '/' || char === '\\') {
      if (!isAfterSeparator) {
        parts.push('/')
        offsets.push(at)
        isAfterSeparator = true
      }
    } else {
      const lower = char.toLowerCase()
      parts.push(lower)
      // One offset per UTF-16 unit, not per code point (`İ` lower-cases to two).
      offsets.push(at)
      for (let extra = 1; extra < lower.length; extra += 1) {
        offsets.push(at)
      }
      isAfterSeparator = false
    }
    at += char.length
  }
  offsets.push(text.length)
  return { text: parts.join(''), offsets }
}

/**
 * The local roots worth looking for, folded, longest first. A root of fewer
 * than two segments is left out.
 */
function foldedRoots(localRoots: readonly string[]): readonly string[] {
  return localRoots
    .map((root) => foldText(root.replace(TRAILING_SEPARATORS, '')).text)
    .filter(
      (root) =>
        root.split(PATH_SEPARATORS).filter((segment) => segment !== '').length >=
        LOCAL_ROOT_MIN_SEGMENTS,
    )
    .toSorted((a, b) => b.length - a.length)
}

/**
 * Every path that starts at a local root, in either separator, doubled or
 * not, and any letter case, replaced to its end. A text that does not name
 * the root's last folder is not folded at all.
 */
function redactLocalRoots(text: string, roots: readonly string[], counts: ScrubCounts): string {
  let result = text
  for (const root of roots) {
    const lastFolder = root.slice(root.lastIndexOf('/') + 1)
    if (!result.toLowerCase().includes(lastFolder)) {
      continue
    }
    const haystack = foldText(result)
    let rebuilt = ''
    let from = 0
    let search = 0
    for (
      let at = haystack.text.indexOf(root, search);
      at !== -1;
      at = haystack.text.indexOf(root, search)
    ) {
      const start = haystack.offsets[at] ?? result.length
      let end = haystack.offsets[at + root.length] ?? result.length
      while (end < result.length && !PATH_END.test(result.charAt(end))) {
        end += 1
      }
      rebuilt += `${result.slice(from, start)}${MODEL_TEXT.exportRedactedPath}`
      from = end
      search = at + root.length
      while (search < haystack.text.length && (haystack.offsets[search] ?? end) < end) {
        search += 1
      }
      counts.paths += 1
    }
    result = `${rebuilt}${result.slice(from)}`
  }
  return result
}

function scrubText(
  text: string,
  redaction: ExportRedaction,
  roots: readonly string[],
  counts: ScrubCounts,
): string {
  const clean = withoutCredentials(text)
  if (clean !== text) {
    counts.secrets += Math.max(
      0,
      clean.split(REDACTED_MARK).length - text.split(REDACTED_MARK).length,
    )
  }
  if (!redaction.redact) {
    return clean
  }
  // Each pattern runs once, counting as it replaces; an address needs an `@`.
  const withoutAccounts = clean.includes('@')
    ? clean.replaceAll(EMAIL_ADDRESS, () => {
        counts.accounts += 1
        return MODEL_TEXT.exportRedactedAccount
      })
    : clean
  let redacted = redactLocalRoots(withoutAccounts, roots, counts)
  for (const pattern of PATH_PATTERNS) {
    redacted = redacted.replaceAll(pattern, () => {
      counts.paths += 1
      return MODEL_TEXT.exportRedactedPath
    })
  }
  return redacted
}

/** How much text has been scrubbed since the event loop last ran. */
interface ScrubPace {
  sinceYield: number
  /** How long a piece of one string may be (`redactableSlices`). */
  readonly sliceChars: number
}

/**
 * Lets the event loop run once a slice of text has been scrubbed: the scrub
 * runs on the extension host, and a long conversation scrubbed in one go held
 * every extension in the window for seconds (RV84 #9). A long string is cut
 * only just after a line break that nothing redacted goes on past, so each
 * pattern sees whole what it would see in the whole string; a single line
 * longer than a slice is still scrubbed in one go. `setImmediate`, not a
 * timer: on Windows a zero timer waits for the next ~15 ms clock tick, which
 * made a 4 MiB export spend a second waiting.
 */
async function pace(scrubbed: ScrubPace, length: number): Promise<void> {
  scrubbed.sinceYield += length
  if (scrubbed.sinceYield < SESSION_EXPORT_SCRUB_SLICE_CHARS) {
    return
  }
  scrubbed.sinceYield = 0
  await new Promise((resolve) => {
    setImmediate(resolve)
  })
}

/** Every string scrubbed; ordinary protocol words and UUIDs do not match secret shapes. */
async function scrubValue(
  value: unknown,
  scrub: (text: string) => string,
  scrubbed: ScrubPace,
): Promise<unknown> {
  if (typeof value === 'string') {
    let clean = ''
    for (const slice of redactableSlices(value, scrubbed.sliceChars)) {
      clean += scrub(slice)
      await pace(scrubbed, slice.length)
    }
    return clean
  }
  if (Array.isArray(value)) {
    const entries: unknown[] = []
    for (const entry of value) {
      entries.push(await scrubValue(entry, scrub, scrubbed))
    }
    return entries
  }
  if (!isRecord(value)) {
    return value
  }
  const fields: [string, unknown][] = []
  for (const [name, entry] of Object.entries(value)) {
    fields.push([name, await scrubValue(entry, scrub, scrubbed)])
  }
  return Object.fromEntries(fields)
}

// --- Export ---

const USER_MESSAGE = 'userMessage'
const AGENT_MESSAGE = 'agentMessage'

/** The messages in a transcript, the user's and the agent's, as the previews count them. */
export function messageCount(items: readonly Pick<ItemSnapshot, 'kind'>[]): number {
  return items.filter((item) => item.kind === USER_MESSAGE || item.kind === AGENT_MESSAGE).length
}

export interface SessionExportSource {
  readonly backend: BackendKind
  readonly name?: string | undefined
  readonly modelId: string
  /** ISO 8601. */
  readonly exportedAt: string
  /** The session's history, as the Markdown export reads it. */
  readonly items: readonly ItemSnapshot[]
}

export interface BuiltSessionExport extends ScrubCounts {
  readonly doc: SessionExport
}

function portableItem(item: ItemSnapshot): Record<string, unknown> {
  return Object.fromEntries(Object.entries(item).filter(([key]) => PORTABLE_ITEM_KEYS.has(key)))
}

/**
 * The portable document for a conversation: credentials and the key digest
 * scrubbed from every string, account ids and paths too unless `redact` is
 * false. The result is parsed with the import's own schema, so a file this
 * writes is one an import reads. The event loop runs between slices of the
 * scrub (`pace`).
 */
export async function buildSessionExport(
  source: SessionExportSource,
  redaction: ExportRedaction,
): Promise<BuiltSessionExport> {
  const counts: ScrubCounts = { secrets: 0, accounts: 0, paths: 0 }
  const roots = foldedRoots(redaction.localRoots)
  const document = {
    format: SESSION_EXPORT_FORMAT,
    version: SESSION_EXPORT_VERSION,
    exportedAt: source.exportedAt,
    sourceBackend: source.backend,
    redacted: redaction.redact,
    ...(source.name !== undefined && { name: source.name }),
    modelId: source.modelId,
    transcript: source.items.map((item) => portableItem(item)),
  }
  const scrubbed = await scrubValue(document, (text) => scrubText(text, redaction, roots, counts), {
    sinceYield: 0,
    // Cut at a line break, a folder whose name holds one could be split:
    // such a string is scrubbed whole.
    sliceChars: roots.some((root) => root.includes(LINE_BREAK))
      ? Infinity
      : SESSION_EXPORT_SCRUB_SLICE_CHARS,
  })
  return { ...counts, doc: sessionExportSchema.parse(scrubbed) }
}

// --- Import ---

const JSON_INDENT = 2
// Kinds the model is not handed: its old thinking, and host-internal children.
const NOT_FOR_THE_MODEL: ReadonlySet<string> = new Set(['reasoning', 'reminderChild'])
// Fields that mean nothing to the model reading an old turn.
const NOT_FOR_THE_MODEL_FIELDS: ReadonlySet<string> = new Set([
  'itemId',
  'turnId',
  'durationMs',
  'paid',
])
const IMPORTED_TURN_PREFIX = 'imported-turn-'
const IMPORTED_ITEM_PREFIX = 'imported-item-'

export interface SanitizeImportOptions {
  /** A fresh session id: schedules are keyed by session id, so none can follow. */
  readonly sessionId: string
  readonly workspaceRoot: string
  /** Forced by the caller (Manual, or Plan): nothing in the file sets it. */
  readonly approvalMode: ApprovalMode
  /** The user's own model: nothing in the file picks one. */
  readonly modelId: string
  /** ISO 8601. */
  readonly now: string
}

interface ImportedTurn {
  readonly turnId: string
  readonly items: ItemSnapshot[]
}

function hasUserMessage(turn: ImportedTurn): boolean {
  return turn.items.some((item) => item.kind === USER_MESSAGE)
}

/** The file's items in turns: each user message starts one, and everything before the first joins it. */
function importedTurns(transcript: readonly ItemSnapshot[]): readonly ImportedTurn[] {
  const turns: ImportedTurn[] = []
  let itemCount = 0
  for (const item of transcript) {
    let turn = turns.at(-1)
    if (turn === undefined || (item.kind === USER_MESSAGE && hasUserMessage(turn))) {
      turn = { turnId: `${IMPORTED_TURN_PREFIX}${String(turns.length)}`, items: [] }
      turns.push(turn)
    }
    turn.items.push({
      ...item,
      itemId: `${IMPORTED_ITEM_PREFIX}${String(itemCount)}`,
      turnId: turn.turnId,
    })
    itemCount += 1
  }
  return turns
}

/** One imported turn as the model reads it: a lead that marks it untrusted, then its items as JSON. */
function turnForTheModel(turn: ImportedTurn, isFirst: boolean): StoredReplayItem {
  const items = turn.items
    .filter((item) => !NOT_FOR_THE_MODEL.has(item.kind))
    .map((item) =>
      Object.fromEntries(
        Object.entries(item).filter(([key]) => !NOT_FOR_THE_MODEL_FIELDS.has(key)),
      ),
    )
  const lead = isFirst
    ? `${MODEL_TEXT.importedHistoryNote}\n\n${MODEL_TEXT.importedTurnLead}`
    : MODEL_TEXT.importedTurnLead
  return {
    turnId: turn.turnId,
    item: {
      type: 'message',
      role: 'user',
      content: [
        { type: 'input_text', text: `${lead}\n${JSON.stringify(items, undefined, JSON_INDENT)}` },
      ],
    },
  }
}

function importedReplay(turns: readonly ImportedTurn[]): StoredReplayItem[] {
  return turns.map((turn, index) => turnForTheModel(turn, index === 0))
}

/** The UTF-8 bytes of the text `replay` hands the model. */
function replayBytes(replay: readonly StoredReplayItem[]): number {
  let bytes = 0
  for (const { item } of replay) {
    if (item.type !== 'message') {
      continue
    }
    for (const part of item.content) {
      if (part.type === 'input_text') {
        bytes += Buffer.byteLength(part.text)
      }
    }
  }
  return bytes
}

/** The refusal for a replay of `bytes`, naming both sizes; undefined when it fits. */
function oversizeReason(bytes: number): string | undefined {
  return bytes > MODEL_API_IMPORT_MAX_REPLAY_BYTES
    ? fill(UI_TEXT.importReplayTooLarge, {
        size: formatBytes(bytes),
        limit: formatBytes(MODEL_API_IMPORT_MAX_REPLAY_BYTES),
      })
    : undefined
}

/**
 * Why `doc` cannot be resumed on the Model API, or undefined (RV84 #10): the
 * text it hands the model, counted high as one token per UTF-8 byte, must
 * fit `MODEL_API_IMPORT_MAX_REPLAY_BYTES`. Accepted, a larger one would
 * fail every later message past the model's window; it can still be read as
 * a share file.
 */
export function importRefusal(doc: SessionExport): string | undefined {
  return oversizeReason(replayBytes(importedReplay(importedTurns(doc.transcript))))
}

/**
 * A parsed export as a stored session that resumes safely. The transcript
 * keeps what the panel shows, under fresh ids. The model is handed each turn
 * as untrusted data in a user-role message, so nothing in the file speaks as
 * the model, a tool or the developer. The permission mode and model are the
 * caller's; goals, todos, outputs, patches, children and usage start empty;
 * session rules live in a fresh session's own engine, so none carry over.
 * `imported` stays with the session, its forks and its restarts, so it
 * starts asking every time it is opened (PLAN.md D49). Throws, naming the
 * sizes, when its turns do not fit the model (`importRefusal`).
 */
export function sanitizeImportedSession(
  doc: SessionExport,
  options: SanitizeImportOptions,
): StoredSession {
  const turns = importedTurns(doc.transcript)
  const replay = importedReplay(turns)
  const refusal = oversizeReason(replayBytes(replay))
  if (refusal !== undefined) {
    throw new Error(refusal)
  }
  const transcript: StoredTranscriptItem[] = turns.flatMap((turn) =>
    turn.items.map((item) => ({ turnId: turn.turnId, item })),
  )
  const firstPrompt = doc.transcript.find((item) => item.kind === USER_MESSAGE)?.text
  return {
    version: STORED_SESSION_VERSION,
    sessionId: options.sessionId,
    imported: true,
    workspaceRoot: options.workspaceRoot,
    modelId: options.modelId,
    approvalMode: options.approvalMode,
    effort: DEFAULT_EFFORT,
    ...(doc.name !== undefined && { name: doc.name }),
    createdAt: options.now,
    lastActivityAt: options.now,
    turnIds: turns.map((turn) => turn.turnId),
    ...(firstPrompt !== undefined && { firstPrompt }),
    todos: [],
    replay,
    transcript,
    outputs: {},
    usage: { inputTokens: 0, outputTokens: 0, cachedTokens: 0, reasoningTokens: 0 },
  }
}

src/core/export/transcriptMarkdown.ts:
// A conversation as Markdown (M30, PLAN.md D30): Claude Code's `/export`
// writes the conversation as text; Muse Code's own `muse export` writes a
// JSON trajectory for tools, not people. This renders a session's history
// (the same items the transcript is rebuilt from, user messages in their
// presentation form) on either backend. Items the panel hides are left out.
// The file's own words (headings, labels, counts) are in the display
// language (PLAN.md D33); what was said and run is written as it was.
//
// Pure: the host reads the history and writes the file.

import type { CitationSummary, ItemSnapshot } from '../../shared/agentEvents'
import {
  HIDDEN_ITEM_KINDS,
  UI_TEXT,
  USER_SHELL_ITEM_KIND,
  USER_SHELL_PREFIX,
} from '../../shared/constants'
import { fill, plural } from '../../shared/l10n/text'
import { thenRunOutcomeText, verifySummaryText } from '../../shared/verifyText'

export interface TranscriptExport {
  readonly title: string
  readonly sessionId: string
  readonly backendLabel: string
  readonly modelId: string
  /** ISO 8601. */
  readonly exportedAt: string
  readonly items: readonly ItemSnapshot[]
}

const USER_MESSAGE = 'userMessage'
const AGENT_MESSAGE = 'agentMessage'
const REASONING = 'reasoning'
const TOOL_CALL = 'toolCall'
const SUBAGENT = 'subagent'
const MIN_FENCE = 3
const BACKTICK_RUN = /`+/g
const FILE_NAME_UNSAFE = /[^a-z0-9]+/g
const EDGE_DASHES = /^-+|-+$/g
// What a Markdown link's text must escape to stay one link.
const LINK_TEXT_SPECIAL = /[\\[\]]/g
const FILE_NAME_WORDS_MAX = 60
const JSON_INDENT = 2
const COMPLETED = 'completed'

/** A code fence longer than any backtick run inside `text`, so the block cannot end early. */
export function fenced(text: string, language = ''): string {
  // A loop, not `Math.max(...runs)`: a shared file's tool output can hold
  // hundreds of thousands of runs, past the engine's argument limit (a
  // RangeError that took the whole panel down, RV84c C3).
  let longest = 0
  for (const match of text.matchAll(BACKTICK_RUN)) {
    longest = Math.max(longest, match[0].length)
  }
  const fence = '`'.repeat(Math.max(MIN_FENCE, longest + 1))
  return `${fence}${language}\n${text}\n${fence}`
}

function prettyArgs(args: string): { readonly text: string; readonly language: string } {
  try {
    return { text: JSON.stringify(JSON.parse(args), undefined, JSON_INDENT), language: 'json' }
  } catch {
    return { text: args, language: '' }
  }
}

function quoted(text: string): string {
  return text
    .split('\n')
    .map((line) => (line === '' ? '>' : `> ${line}`))
    .join('\n')
}

function statusSuffix(item: ItemSnapshot): string {
  return item.status === COMPLETED ? '' : ` (${item.status})`
}

/** A line of the file's own words, set in italics. */
function note(text: string): string {
  return `_${text}_`
}

function outputBlock(item: ItemSnapshot): readonly string[] {
  if (item.visibleOutput !== undefined && item.visibleOutput !== '') {
    return [UI_TEXT.exportOutputLabel, '', fenced(item.visibleOutput)]
  }
  return item.outputRef === undefined
    ? []
    : [note(plural(UI_TEXT.exportOutputStored, item.outputRef.byteLen))]
}

function toolSection(item: ItemSnapshot, heading: string): string {
  const lines = [`### ${heading}${statusSuffix(item)}`, '']
  if (item.args !== undefined && item.args !== '') {
    const args = prettyArgs(item.args)
    lines.push(UI_TEXT.exportArgumentsLabel, '', fenced(args.text, args.language), '')
  }
  const output = outputBlock(item)
  if (output.length > 0) {
    lines.push(...output, '')
  }
  if (item.patchSummary !== undefined) {
    const { files, added, removed } = item.patchSummary
    lines.push(note(plural(UI_TEXT.exportFilesChanged, files, { added, removed })), '')
  }
  // An edit's then_run (M68): what it printed and how it ended, or why it
  // did not run; a verify row's summary line (the M68 review).
  const { thenRun } = item
  if (thenRun?.outcome === 'notRun') {
    lines.push(
      note(
        fill(UI_TEXT.exportThenRunSkipped, {
          command: thenRun.command,
          outcome: thenRunOutcomeText(thenRun),
        }),
      ),
      '',
    )
  } else if (thenRun !== undefined) {
    const ran = [`$ ${thenRun.command}`, ...(thenRun.output === '' ? [] : [thenRun.output])].join(
      '\n',
    )
    lines.push(
      UI_TEXT.exportThenRunLabel,
      '',
      fenced(ran),
      '',
      note(thenRunOutcomeText(thenRun)),
      '',
    )
  }
  const verified = verifySummaryText(item.verifySummary)
  if (verified !== undefined) {
    lines.push(note(verified), '')
  }
  if (item.failureReason !== undefined) {
    lines.push(note(fill(UI_TEXT.exportFailure, { reason: item.failureReason })), '')
  }
  return lines.join('\n').trimEnd()
}

/** The user's own `!` command (M46): what they ran, what it printed, how it ended. */
function userShellSection(item: ItemSnapshot): string {
  const lines = [`### ${UI_TEXT.exportShellHeading}${statusSuffix(item)}`, '']
  if (item.commandText !== undefined && item.commandText !== '') {
    lines.push(fenced(`${USER_SHELL_PREFIX}${item.commandText}`), '')
  }
  const output = outputBlock(item)
  if (output.length > 0) {
    lines.push(...output, '')
  }
  if (item.exitCode !== undefined) {
    lines.push(note(fill(UI_TEXT.userShellExitCode, { code: String(item.exitCode) })), '')
  }
  if (item.exitSignal !== undefined) {
    lines.push(note(fill(UI_TEXT.userShellExitSignal, { signal: String(item.exitSignal) })), '')
  }
  return lines.join('\n').trimEnd()
}

function userSection(item: ItemSnapshot): string {
  const lines = [`## ${UI_TEXT.exportUserHeading}`, '', item.text ?? '']
  const images = item.attachments?.length ?? 0
  if (images > 0) {
    lines.push('', note(plural(UI_TEXT.exportImagesAttached, images)))
  }
  return lines.join('\n')
}

function subagentSection(item: ItemSnapshot): string {
  const role = item.role ?? UI_TEXT.exportSubagentNoRole
  const lines = [`### ${fill(UI_TEXT.exportSubagentHeading, { role })}${statusSuffix(item)}`, '']
  if (item.objective !== undefined) {
    lines.push(item.objective, '')
  }
  if (item.result !== undefined) {
    lines.push(quoted(item.result.text ?? item.result.summary), '')
  }
  return lines.join('\n').trimEnd()
}

/** A cited page as a Markdown link (M33): the title escaped, the URL in angle brackets. */
function citationLine(citation: CitationSummary): string {
  const title = (citation.title ?? citation.url).replaceAll(LINK_TEXT_SPECIAL, String.raw`\$&`)
  const url = citation.url.replaceAll('<', '%3C').replaceAll('>', '%3E')
  return `- [${title}](<${url}>)`
}

/** A reply, and the web pages it cites (M33). */
function agentSection(item: ItemSnapshot): string | undefined {
  if (item.text === undefined || item.text === '') {
    return undefined
  }
  const lines = [`## ${UI_TEXT.exportAgentHeading}`, '', item.text]
  const citations = item.citations ?? []
  if (citations.length > 0) {
    lines.push(
      '',
      `${UI_TEXT.citationsHeading}:`,
      '',
      ...citations.map((citation) => citationLine(citation)),
    )
  }
  return lines.join('\n')
}

/**
 * One item as its section of the Markdown export; undefined for items the
 * panel hides. The share view (M84) renders a shared file with it too.
 */
export function transcriptItemMarkdown(item: ItemSnapshot): string | undefined {
  switch (item.kind) {
    case USER_MESSAGE: {
      return userSection(item)
    }
    case AGENT_MESSAGE: {
      return agentSection(item)
    }
    case REASONING: {
      const text = item.summary?.join('\n\n') ?? item.text ?? ''
      return text === '' ? undefined : `### ${UI_TEXT.exportThinkingHeading}\n\n${quoted(text)}`
    }
    case TOOL_CALL: {
      // The tool's own name, as the model called it.
      const tool = item.tool ?? UI_TEXT.exportToolNoName
      return toolSection(item, fill(UI_TEXT.exportToolHeading, { tool }))
    }
    case USER_SHELL_ITEM_KIND: {
      return userShellSection(item)
    }
    case SUBAGENT: {
      return subagentSection(item)
    }
    default: {
      return HIDDEN_ITEM_KINDS.has(item.kind) ? undefined : `_${item.fallbackText ?? item.kind}_`
    }
  }
}

export function renderTranscriptMarkdown(input: TranscriptExport): string {
  const header = [
    `# ${input.title}`,
    '',
    `- ${fill(UI_TEXT.exportSessionLine, { id: input.sessionId })}`,
    `- ${fill(UI_TEXT.exportBackendLine, { backend: input.backendLabel })}`,
    `- ${fill(UI_TEXT.exportModelLine, { model: input.modelId })}`,
    `- ${fill(UI_TEXT.exportTimeLine, { time: input.exportedAt })}`,
  ].join('\n')
  const sections = input.items.flatMap((item) => {
    const section = transcriptItemMarkdown(item)
    return section === undefined ? [] : [section]
  })
  return `${[header, '---', ...sections].join('\n\n')}\n`
}

/** `muse-<words-of-the-title>-<date>.<extension>`, safe on every file system. */
export function exportFileName(title: string, date: Date, extension: string): string {
  const words = title
    .toLowerCase()
    .replaceAll(FILE_NAME_UNSAFE, '-')
    .replaceAll(EDGE_DASHES, '')
    .slice(0, FILE_NAME_WORDS_MAX)
    .replaceAll(EDGE_DASHES, '')
  const day = date.toISOString().slice(0, 'yyyy-mm-dd'.length)
  return `muse-${words === '' ? 'conversation' : words}-${day}.${extension}`
}

src/core/fifoLimiter.ts:
// At most a fixed number of tasks at once, the others in arrival order (CLI
// recovery, 2026-10-03): after a resume every open edit row of the owner's
// conversation read its stored diff at the same instant, 26 `item/readOutput`
// calls on a Muse Code already minutes behind, and each one timed out.

export class FifoLimiter {
  private running = 0
  /** The tasks waiting for a slot, oldest first: each is handed one as it frees. */
  private readonly waiting: (() => void)[] = []

  public constructor(private readonly limit: number) {}

  /** A slot freed: the oldest waiting task takes it, or it is counted free. */
  private release(): void {
    const next = this.waiting.shift()
    if (next === undefined) {
      this.running -= 1
      return
    }
    next()
  }

  /**
   * Runs `task` once a slot is free, in the order `run` was called. When its
   * turn comes, a task no longer wanted (`isWanted` says so) is not run at
   * all: `run` rejects with `dropped()` and the slot goes to the next.
   */
  public async run<T>(
    task: () => Promise<T>,
    isWanted: () => boolean,
    dropped: () => Error,
  ): Promise<T> {
    if (this.running < this.limit) {
      this.running += 1
    } else {
      // The slot is handed over by `release`, already counted.
      await new Promise<void>((resolve) => {
        this.waiting.push(resolve)
      })
    }
    try {
      if (!isWanted()) {
        throw dropped()
      }
      return await task()
    } finally {
      this.release()
    }
  }
}

src/core/fs/fileIdentity.ts:
// Native file IDs are 64-bit on Windows. This is the sole sampler and
// comparator: callers retain the exact IDs even when Number would alias them.
import { statSync, type BigIntStats } from 'node:fs'
import { lstat, stat, type FileHandle } from 'node:fs/promises'
import { WORKSPACE_IDENTITY_ZERO } from '../../shared/constants'

export type FileIdentity = Pick<BigIntStats, 'dev' | 'ino'>

/** A held stage's size/mtime change during writing; only its native ID binds cleanup. */
export function identityOf(sample: FileIdentity): FileIdentity {
  return { dev: sample.dev, ino: sample.ino }
}

export async function statIdentity(file: string): Promise<BigIntStats> {
  return await stat(file, { bigint: true })
}

export async function lstatIdentity(file: string): Promise<BigIntStats> {
  return await lstat(file, { bigint: true })
}

export async function handleIdentity(handle: FileHandle): Promise<BigIntStats> {
  return await handle.stat({ bigint: true })
}

/** The ACP's last admission check is synchronous, immediately before mutation. */
export function statIdentitySync(file: string): BigIntStats {
  return statSync(file, { bigint: true })
}

function isSameFile(left: FileIdentity, right: FileIdentity): boolean {
  return left.dev === right.dev && left.ino === right.ino
}

export { isSameFile as sameFile }

/** An absent/invalid native ID cannot bind a workspace or an import preview. */
export function fileIdentityKey(identity: FileIdentity): string | undefined {
  return identity.ino <= WORKSPACE_IDENTITY_ZERO || identity.dev < WORKSPACE_IDENTITY_ZERO
    ? undefined
    : `${identity.dev.toString()}:${identity.ino.toString()}`
}

src/core/fuzzy.ts:
// Fuzzy path matching for @-mentions: case-insensitive subsequence match with
// a score that rewards consecutive characters, matches at path-segment starts
// and matches inside the file name. Deterministic and dependency-free so the
// ranking can be unit-tested exactly.

const SEGMENT_SEPARATORS = new Set(['/', '.', '-', '_', ' '])
const CONSECUTIVE_BONUS = 8
const SEGMENT_START_BONUS = 6
const BASENAME_BONUS = 4
const GAP_PENALTY = 1

function isSegmentStart(candidate: string, index: number): boolean {
  if (index === 0) {
    return true
  }
  const previous = candidate.charAt(index - 1)
  return SEGMENT_SEPARATORS.has(previous)
}

/**
 * Greedy left-to-right subsequence score of `needle` in `haystack`, both
 * already lower-cased; undefined when it is not a subsequence. Characters at
 * or past `basenameStart` earn the file-name bonus.
 */
function greedyScore(needle: string, haystack: string, basenameStart: number): number | undefined {
  let score = 0
  let position = 0
  let previousMatch = -1
  for (const character of needle) {
    const found = haystack.indexOf(character, position)
    if (found === -1) {
      return undefined
    }
    if (found === previousMatch + 1) {
      score += CONSECUTIVE_BONUS
    } else if (previousMatch !== -1) {
      score -= Math.min(found - previousMatch - 1, CONSECUTIVE_BONUS) * GAP_PENALTY
    }
    if (isSegmentStart(haystack, found)) {
      score += SEGMENT_START_BONUS
    }
    if (found >= basenameStart) {
      score += BASENAME_BONUS
    }
    previousMatch = found
    position = found + 1
  }
  return score
}

/**
 * Score of `query` against `candidate`, or undefined when the query is not a
 * subsequence of the candidate. An empty query matches everything with 0.
 *
 * Greedy matching over the whole path can latch onto an early folder letter
 * ("c" of `src/` for `cfg` against `src/config.ts`), so a match confined to
 * the file name is scored separately and the better of the two wins.
 */
export function fuzzyScore(query: string, candidate: string): number | undefined {
  const needle = query.toLowerCase()
  if (needle === '') {
    return 0
  }
  const haystack = candidate.toLowerCase()
  const basenameStart = haystack.lastIndexOf('/') + 1
  const whole = greedyScore(needle, haystack, basenameStart)
  if (whole === undefined) {
    return undefined
  }
  const basenameOnly = greedyScore(needle, haystack.slice(basenameStart), 0)
  return basenameOnly === undefined ? whole : Math.max(whole, basenameOnly)
}

interface Ranked<T> {
  readonly item: T
  readonly score: number
}

/**
 * The best `limit` items for `query`, highest score first; ties go to the
 * shorter key, then to the original order. An empty query keeps the
 * original order.
 */
export function rankMatches<T>(
  query: string,
  items: readonly T[],
  keyOf: (item: T) => string,
  limit: number,
): readonly T[] {
  if (query === '') {
    return items.slice(0, limit)
  }
  const ranked: Ranked<T>[] = []
  for (const item of items) {
    const score = fuzzyScore(query, keyOf(item))
    if (score !== undefined) {
      ranked.push({ item, score })
    }
  }
  return ranked
    .toSorted((a, b) => b.score - a.score || keyOf(a.item).length - keyOf(b.item).length)
    .slice(0, limit)
    .map((entry) => entry.item)
}

src/core/imageDimensions.ts:
// Reads the pixel size and media type of an image from its leading bytes, for
// the `name W×H` attachment chip and the MSP image part. Supports exactly the
// formats the Model API accepts (PNG, JPEG, GIF, WebP); anything else returns
// undefined so the caller can refuse it with a reason.

import type { ImageMediaType } from '../shared/constants'

export interface ImageInfo {
  readonly mediaType: ImageMediaType
  readonly width: number
  readonly height: number
}

const BITS_PER_BYTE = 8
const BYTES_PER_U16 = 2
const BYTES_PER_U24 = 3
const BYTES_PER_U32 = 4
const FOURCC_LENGTH = 4

// PNG: 8-byte signature, then the IHDR chunk whose data starts at byte 16
// with big-endian width and height.
const PNG_SIGNATURE = '\u{89}PNG\r\n\u{1A}\n'
const PNG_WIDTH_OFFSET = 16
const PNG_HEIGHT_OFFSET = 20

// GIF: "GIF87a"/"GIF89a", then little-endian logical screen width/height.
const GIF_SIGNATURE = 'GIF8'
const GIF_WIDTH_OFFSET = 6
const GIF_HEIGHT_OFFSET = 8

// JPEG: SOI (FF D8) then marker segments; a start-of-frame segment carries
// the dimensions after the marker (2), the length (2) and the precision (1).
const JPEG_SOI = '\u{FF}\u{D8}'
const JPEG_MARKER_PREFIX = 0xff
const JPEG_SOF_LOW = 0xc0
const JPEG_SOF_HIGH = 0xcf
// DHT, the JPG extension and DAC sit in the SOF range but are not frames.
const JPEG_DHT = 0xc4
const JPEG_JPG_EXTENSION = 0xc8
const JPEG_DAC = 0xcc
const JPEG_NON_SOF = new Set([JPEG_DHT, JPEG_JPG_EXTENSION, JPEG_DAC])
// RSTn (D0–D7), TEM (01) and fill FF bytes have no length field.
const JPEG_STANDALONE_LOW = 0xd0
const JPEG_STANDALONE_HIGH = 0xd7
const JPEG_TEM = 0x01
const JPEG_MARKER_LENGTH = 2
const JPEG_SOF_HEIGHT_OFFSET = 5
const JPEG_SOF_WIDTH_OFFSET = 7

// WebP: RIFF container, "WEBP" at 8, first chunk FourCC at 12.
const RIFF = 'RIFF'
const WEBP = 'WEBP'
const WEBP_FORMAT_OFFSET = 8
const WEBP_CHUNK_OFFSET = 12
// VP8 (lossy): 14-bit little-endian width/height at 26 and 28.
const WEBP_VP8_WIDTH_OFFSET = 26
const WEBP_VP8_HEIGHT_OFFSET = 28
const WEBP_VP8_DIMENSION_MASK = 0x3f_ff
// VP8L (lossless): 14-bit width-1 and height-1 packed into bytes 21–24.
const WEBP_VP8L_BITS_OFFSET = 21
const VP8L_WIDTH_HIGH_MASK = 0x3f
const VP8L_HEIGHT_LOW_SHIFT = 6
const VP8L_HEIGHT_MID_SHIFT = 2
const VP8L_HEIGHT_HIGH_SHIFT = 10
const VP8L_HEIGHT_HIGH_MASK = 0x0f
// VP8X (extended): 24-bit little-endian width-1 at 24 and height-1 at 27.
const WEBP_VP8X_WIDTH_OFFSET = 24
const WEBP_VP8X_HEIGHT_OFFSET = 27

function ascii(bytes: Uint8Array, start: number, length: number): string {
  return String.fromCodePoint(...bytes.subarray(start, start + length))
}

function hasSignature(bytes: Uint8Array, signature: string, offset = 0): boolean {
  return (
    bytes.length >= offset + signature.length &&
    ascii(bytes, offset, signature.length) === signature
  )
}

function u16be(bytes: Uint8Array, offset: number): number {
  return ((bytes[offset] ?? 0) << BITS_PER_BYTE) | (bytes[offset + 1] ?? 0)
}

function u16le(bytes: Uint8Array, offset: number): number {
  return (bytes[offset] ?? 0) | ((bytes[offset + 1] ?? 0) << BITS_PER_BYTE)
}

function u24le(bytes: Uint8Array, offset: number): number {
  return (
    u16le(bytes, offset) | ((bytes[offset + BYTES_PER_U16] ?? 0) << (BITS_PER_BYTE * BYTES_PER_U16))
  )
}

function u32be(bytes: Uint8Array, offset: number): number {
  return (
    u16be(bytes, offset) * 2 ** (BITS_PER_BYTE * BYTES_PER_U16) +
    u16be(bytes, offset + BYTES_PER_U16)
  )
}

function readPng(bytes: Uint8Array): ImageInfo | undefined {
  if (!hasSignature(bytes, PNG_SIGNATURE) || bytes.length < PNG_HEIGHT_OFFSET + BYTES_PER_U32) {
    return undefined
  }
  return {
    mediaType: 'image/png',
    width: u32be(bytes, PNG_WIDTH_OFFSET),
    height: u32be(bytes, PNG_HEIGHT_OFFSET),
  }
}

function readGif(bytes: Uint8Array): ImageInfo | undefined {
  if (!hasSignature(bytes, GIF_SIGNATURE) || bytes.length < GIF_HEIGHT_OFFSET + BYTES_PER_U16) {
    return undefined
  }
  return {
    mediaType: 'image/gif',
    width: u16le(bytes, GIF_WIDTH_OFFSET),
    height: u16le(bytes, GIF_HEIGHT_OFFSET),
  }
}

function isJpegSof(marker: number): boolean {
  return marker >= JPEG_SOF_LOW && marker <= JPEG_SOF_HIGH && !JPEG_NON_SOF.has(marker)
}

function isJpegStandalone(marker: number): boolean {
  return (
    (marker >= JPEG_STANDALONE_LOW && marker <= JPEG_STANDALONE_HIGH) ||
    marker === JPEG_TEM ||
    marker === JPEG_MARKER_PREFIX
  )
}

function readJpeg(bytes: Uint8Array): ImageInfo | undefined {
  if (!hasSignature(bytes, JPEG_SOI)) {
    return undefined
  }
  let offset = JPEG_SOI.length
  while (offset + JPEG_MARKER_LENGTH <= bytes.length) {
    if (bytes[offset] !== JPEG_MARKER_PREFIX) {
      return undefined
    }
    const marker = bytes[offset + 1] ?? 0
    if (isJpegStandalone(marker)) {
      offset += marker === JPEG_MARKER_PREFIX ? 1 : JPEG_MARKER_LENGTH
      continue
    }
    if (isJpegSof(marker)) {
      if (offset + JPEG_SOF_WIDTH_OFFSET + BYTES_PER_U16 > bytes.length) {
        return undefined
      }
      return {
        mediaType: 'image/jpeg',
        height: u16be(bytes, offset + JPEG_SOF_HEIGHT_OFFSET),
        width: u16be(bytes, offset + JPEG_SOF_WIDTH_OFFSET),
      }
    }
    const length = u16be(bytes, offset + JPEG_MARKER_LENGTH)
    if (length < JPEG_MARKER_LENGTH) {
      return undefined
    }
    offset += JPEG_MARKER_LENGTH + length
  }
  return undefined
}

function readWebpChunk(bytes: Uint8Array, chunk: string): ImageInfo | undefined {
  switch (chunk) {
    case 'VP8 ': {
      if (bytes.length < WEBP_VP8_HEIGHT_OFFSET + BYTES_PER_U16) {
        return undefined
      }
      return {
        mediaType: 'image/webp',
        width: u16le(bytes, WEBP_VP8_WIDTH_OFFSET) & WEBP_VP8_DIMENSION_MASK,
        height: u16le(bytes, WEBP_VP8_HEIGHT_OFFSET) & WEBP_VP8_DIMENSION_MASK,
      }
    }
    case 'VP8L': {
      if (bytes.length < WEBP_VP8L_BITS_OFFSET + BYTES_PER_U32) {
        return undefined
      }
      const [b0, b1, b2, b3] = bytes.subarray(
        WEBP_VP8L_BITS_OFFSET,
        WEBP_VP8L_BITS_OFFSET + BYTES_PER_U32,
      )
      const width = 1 + ((b0 ?? 0) | (((b1 ?? 0) & VP8L_WIDTH_HIGH_MASK) << BITS_PER_BYTE))
      const height =
        1 +
        (((b1 ?? 0) >> VP8L_HEIGHT_LOW_SHIFT) |
          ((b2 ?? 0) << VP8L_HEIGHT_MID_SHIFT) |
          (((b3 ?? 0) & VP8L_HEIGHT_HIGH_MASK) << VP8L_HEIGHT_HIGH_SHIFT))
      return { mediaType: 'image/webp', width, height }
    }
    case 'VP8X': {
      if (bytes.length < WEBP_VP8X_HEIGHT_OFFSET + BYTES_PER_U24) {
        return undefined
      }
      return {
        mediaType: 'image/webp',
        width: 1 + u24le(bytes, WEBP_VP8X_WIDTH_OFFSET),
        height: 1 + u24le(bytes, WEBP_VP8X_HEIGHT_OFFSET),
      }
    }
    default: {
      return undefined
    }
  }
}

function readWebp(bytes: Uint8Array): ImageInfo | undefined {
  const isWebp =
    hasSignature(bytes, RIFF) &&
    hasSignature(bytes, WEBP, WEBP_FORMAT_OFFSET) &&
    bytes.length >= WEBP_CHUNK_OFFSET + FOURCC_LENGTH
  return isWebp ? readWebpChunk(bytes, ascii(bytes, WEBP_CHUNK_OFFSET, FOURCC_LENGTH)) : undefined
}

export function readImageInfo(bytes: Uint8Array): ImageInfo | undefined {
  return readPng(bytes) ?? readGif(bytes) ?? readJpeg(bytes) ?? readWebp(bytes)
}

src/core/logging.ts:
// The logging surface core modules accept. src/host/logger.ts satisfies it
// structurally (with secret redaction); tests pass a recording fake.

import { CLI_STDERR_LOG_MAX_CHARS } from '../shared/constants'

/** A process's output as the log keeps it: the first part, and how much was left out. */
export function clipForLog(text: string, maxChars: number = CLI_STDERR_LOG_MAX_CHARS): string {
  return text.length > maxChars
    ? `${text.slice(0, maxChars)}… [${String(text.length - maxChars)} more characters]`
    : text
}

// A word from the wire (an MSP state, error kind or outcome) in the shape of
// one: a letter, then up to 63 letters, digits, `_` or `-`. Free text of any
// other shape (a message, a path, an e-mail address) is never logged, since
// the redactor catches only key-shaped strings (the review of PR #49).
const WIRE_WORD = /^[A-Za-z][\w-]{0,63}$/u

/** A protocol word as the log names it; any other text becomes a fixed phrase. */
export function wireWordForLog(value: string): string {
  return WIRE_WORD.test(value) ? value : 'an unrecognized value'
}

export interface CoreLogger {
  /** The finest detail (M39): shown when the Muse Spark channel's level is Trace. */
  trace(message: string): void
  info(message: string): void
  warn(message: string): void
  error(message: string): void
}

src/core/mcp.ts:
// The Model Context Protocol server side, reduced to what an IDE tool server
// needs: JSON-RPC 2.0 messages over the streamable-HTTP transport
// (`initialize`, `notifications/initialized`, `ping`, `tools/list`,
// `tools/call`). Verified against `muse serve` 1.3.0 on 2026-09-22: it
// speaks protocol 2025-06-18, sends `initialize`, the initialized
// notification and `tools/list` at session start. Pure: the host owns the
// socket and the tool implementations.

import * as z from 'zod/mini'
import {
  JSON_RPC_ERRORS,
  MCP_CANCELLED_NOTIFICATION,
  MCP_PROTOCOL_VERSION,
} from '../shared/constants'

export interface McpTool {
  readonly name: string
  readonly description: string
  /** JSON Schema for the arguments. */
  readonly inputSchema: Readonly<Record<string, unknown>>
  /** MCP's behaviour hints (`readOnlyHint`, `openWorldHint`, …), listed when present (M69). */
  readonly annotations?: Readonly<Record<string, unknown>>
  /**
   * The tool's text result; throw to report a tool error. `signal` aborts
   * when the caller stops waiting for it (M69: its request closed, or
   * `notifications/cancelled` named it).
   */
  readonly call: (args: Readonly<Record<string, unknown>>, signal: AbortSignal) => Promise<string>
}

export interface McpServerInfo {
  readonly name: string
  readonly version: string
}

/** What the transport does with a message: answer it, or just accept it. */
export type McpOutcome =
  | { readonly kind: 'response'; readonly body: Readonly<Record<string, unknown>> }
  | { readonly kind: 'accepted' }

const messageSchema = z.object({
  jsonrpc: z.literal('2.0'),
  id: z.optional(z.union([z.string(), z.number(), z.null()])),
  method: z.optional(z.string()),
  params: z.optional(z.record(z.string(), z.unknown())),
})

const JSON_RPC_VERSION = '2.0'

function errorResponse(id: unknown, code: number, message: string): McpOutcome {
  return {
    kind: 'response',
    body: { jsonrpc: JSON_RPC_VERSION, id: id ?? null, error: { code, message } },
  }
}

function resultResponse(id: unknown, result: unknown): McpOutcome {
  return { kind: 'response', body: { jsonrpc: JSON_RPC_VERSION, id, result } }
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

async function callTool(
  tools: readonly McpTool[],
  params: Readonly<Record<string, unknown>> | undefined,
  signal: AbortSignal,
): Promise<unknown> {
  const name = params?.['name']
  const tool = tools.find((candidate) => candidate.name === name)
  if (tool === undefined) {
    return { content: [{ type: 'text', text: `Unknown tool: ${String(name)}` }], isError: true }
  }
  const rawArgs = params?.['arguments']
  const args =
    typeof rawArgs === 'object' && rawArgs !== null ? (rawArgs as Record<string, unknown>) : {}
  try {
    return { content: [{ type: 'text', text: await tool.call(args, signal) }] }
  } catch (error: unknown) {
    return { content: [{ type: 'text', text: describe(error) }], isError: true }
  }
}

/** A request id as a key: JSON-RPC allows a string or a number. */
export type McpRequestKey = string

const requestIdSchema = z.union([z.string(), z.number()])
const cancelledSchema = z.object({
  method: z.literal(MCP_CANCELLED_NOTIFICATION),
  params: z.object({ requestId: requestIdSchema }),
})

function keyOf(id: string | number): McpRequestKey {
  return typeof id === 'number' ? `n:${String(id)}` : `s:${id}`
}

/**
 * What a body means for requests in flight (M69): the key of the request it
 * makes, if any, and the key of a request `notifications/cancelled` names
 * (the shape Muse Code 1.4.0 sent when a turn was stopped mid-call:
 * `{"method":"notifications/cancelled","params":{"requestId":3,"reason":…}}`).
 */
export function mcpRequestKeys(raw: string): {
  readonly request: McpRequestKey | undefined
  readonly cancelled: McpRequestKey | undefined
} {
  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    return { request: undefined, cancelled: undefined }
  }
  const message = messageSchema.safeParse(parsed)
  const cancelled = cancelledSchema.safeParse(parsed)
  const id = message.success ? message.data.id : undefined
  return {
    request: id === undefined || id === null ? undefined : keyOf(id),
    cancelled: cancelled.success ? keyOf(cancelled.data.params.requestId) : undefined,
  }
}

/** A signal that never aborts: for a caller with nothing to stop. */
const NEVER_ABORTED = new AbortController().signal

/**
 * Handles one raw request body. A notification (no `id`) is accepted without
 * a body; anything else gets a JSON-RPC response, including parse errors.
 * `signal` reaches a tool the body calls, aborting when its caller stops
 * waiting.
 */
export async function handleMcpMessage(
  raw: string,
  tools: readonly McpTool[],
  serverInfo: McpServerInfo,
  signal: AbortSignal = NEVER_ABORTED,
): Promise<McpOutcome> {
  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    return errorResponse(null, JSON_RPC_ERRORS.parseError, 'Parse error')
  }
  const result = messageSchema.safeParse(parsed)
  if (!result.success) {
    return errorResponse(null, JSON_RPC_ERRORS.invalidRequest, 'Invalid request')
  }
  const message = result.data
  if (message.id === undefined || message.id === null) {
    return { kind: 'accepted' }
  }
  switch (message.method) {
    case 'initialize': {
      const requested = message.params?.['protocolVersion']
      return resultResponse(message.id, {
        protocolVersion: typeof requested === 'string' ? requested : MCP_PROTOCOL_VERSION,
        capabilities: { tools: {} },
        serverInfo,
      })
    }
    case 'ping': {
      return resultResponse(message.id, {})
    }
    case 'tools/list': {
      return resultResponse(message.id, {
        tools: tools.map(({ name, description, inputSchema, annotations }) => ({
          name,
          description,
          inputSchema,
          ...(annotations !== undefined && { annotations }),
        })),
      })
    }
    case 'tools/call': {
      return resultResponse(message.id, await callTool(tools, message.params, signal))
    }
    default: {
      return errorResponse(
        message.id,
        JSON_RPC_ERRORS.methodNotFound,
        `Method not found: ${message.method ?? ''}`,
      )
    }
  }
}

src/core/memory/memoryIndex.ts:
// A memory scope's `MEMORY.md` (PLAN.md D13, D41): one line per note,
// `- [Title](file.md) | hook`, read into the model's context at the start
// of a session. The index is cut at Muse Code's limits with its own marker;
// the extension adds a line for a note it creates and removes the lines of
// a note it deletes, so the index stays true to the folder. Pure.

import {
  MEMORY_HOOK_MAX_CHARS,
  MEMORY_INDEX_FILE,
  MEMORY_MARKDOWN_ESCAPE,
  MEMORY_INDEX_MAX_BYTES,
  MEMORY_INDEX_MAX_LINES,
  MEMORY_NOTE_EXTENSION,
  MEMORY_TRUNCATED_MARKER,
} from '../../shared/constants'

export interface LimitedIndex {
  readonly text: string
  /** Why the index was cut, for the log; undefined when it fits. */
  readonly warning: string | undefined
}

const LINE_BREAK = /\r?\n/
const TRAILING_BREAKS = /(?:\r?\n)+$/
const CURRENT_DIRECTORY = './'
const HEADING_MARKS = /^#+\s*/
const WHITESPACE_RUN = /\s+/g
const FRONT_MATTER_FENCE = '---'
const DESCRIPTION_KEY = 'description:'
const ELLIPSIS = '…'

/** The index within Muse Code's line and byte limits, `label` naming it in the warning. */
export function limitMemoryIndex(text: string, label: string): LimitedIndex {
  const lines = text.split(LINE_BREAK)
  const bytes = Buffer.byteLength(text)
  if (lines.length <= MEMORY_INDEX_MAX_LINES && bytes <= MEMORY_INDEX_MAX_BYTES) {
    return { text: text.trim(), warning: undefined }
  }
  let kept = lines.slice(0, MEMORY_INDEX_MAX_LINES).join('\n')
  if (Buffer.byteLength(kept) > MEMORY_INDEX_MAX_BYTES) {
    kept = Buffer.from(kept).subarray(0, MEMORY_INDEX_MAX_BYTES).toString()
  }
  const limit =
    lines.length > MEMORY_INDEX_MAX_LINES
      ? `${String(lines.length)} lines exceeds the ${String(MEMORY_INDEX_MAX_LINES)} line index limit`
      : `${String(bytes)} bytes exceeds the ${String(MEMORY_INDEX_MAX_BYTES)} byte index limit`
  return {
    text: `${kept.trim()}\n${MEMORY_TRUNCATED_MARKER}`,
    warning: `${label}: ${limit}; it is truncated for this session`,
  }
}

function linkTarget(line: string): string | undefined {
  // Titles may contain an escaped `](`, and a hand-written destination may
  // contain nested parentheses. Find the first unescaped closing bracket,
  // then the destination's balanced end.
  for (let index = 0; index < line.length - 1; index += 1) {
    if (line[index] === MEMORY_MARKDOWN_ESCAPE) {
      index += 1
      continue
    }
    if (line[index] !== ']' || line[index + 1] !== '(') {
      continue
    }
    const start = index + 2
    let depth = 1
    for (let end = start; end < line.length; end += 1) {
      if (line[end] === MEMORY_MARKDOWN_ESCAPE) {
        end += 1
        continue
      }
      if (line[end] === '(') {
        depth += 1
        continue
      }
      if (line[end] !== ')') {
        continue
      }
      depth -= 1
      if (depth !== 0) {
        continue
      }
      const raw = line.slice(start, end).trim()
      const relative = raw.startsWith(CURRENT_DIRECTORY) ? raw.slice(CURRENT_DIRECTORY.length) : raw
      try {
        return decodeURIComponent(relative)
      } catch {
        return relative
      }
    }
    return undefined
  }
  return undefined
}

/** Whether a line of the index links to the note at `notePath` (forward slashes). */
export function hasIndexLine(indexText: string, notePath: string): boolean {
  return indexText.split(LINE_BREAK).some((line) => linkTarget(line) === notePath)
}

/** The index with every line that links to `notePath` removed; undefined when none did. */
export function withoutIndexLines(indexText: string, notePath: string): string | undefined {
  const lines = indexText.split(LINE_BREAK)
  const kept = lines.filter((line) => linkTarget(line) !== notePath)
  return kept.length === lines.length ? undefined : kept.join('\n')
}

/** `text` with one more line at its end (a missing or empty index is the line alone). */
export function withIndexLine(indexText: string | undefined, line: string): string {
  const body = (indexText ?? '').replace(TRAILING_BREAKS, '')
  return body === '' ? `${line}\n` : `${body}\n${line}\n`
}

function oneLine(text: string): string {
  const flat = text.replace(HEADING_MARKS, '').replaceAll(WHITESPACE_RUN, ' ').trim()
  return flat.length > MEMORY_HOOK_MAX_CHARS
    ? `${flat.slice(0, MEMORY_HOOK_MAX_CHARS - ELLIPSIS.length)}${ELLIPSIS}`
    : flat
}

/**
 * What a note is about, in one line: its front matter's `description`, else
 * its first line of text (a heading's marks dropped). Empty for an empty note.
 */
export function noteSummary(text: string): string {
  const lines = text.split(LINE_BREAK)
  let index = 0
  if (lines[0]?.trim() === FRONT_MATTER_FENCE) {
    const end = lines.findIndex((line, at) => at > 0 && line.trim() === FRONT_MATTER_FENCE)
    const description = lines
      .slice(1, end === -1 ? 1 : end)
      .find((line) => line.startsWith(DESCRIPTION_KEY))
    if (description !== undefined) {
      return oneLine(description.slice(DESCRIPTION_KEY.length))
    }
    index = end === -1 ? 0 : end + 1
  }
  const first = lines.slice(index).find((line) => line.trim() !== '')
  return first === undefined ? '' : oneLine(first)
}

/** The index line of a note: its file name as the title, `hook` after the bar when there is one. */
export function indexLineFor(notePath: string, hook: string): string {
  const name = notePath.split('/').at(-1) ?? notePath
  const title = name.endsWith(MEMORY_NOTE_EXTENSION)
    ? name.slice(0, -MEMORY_NOTE_EXTENSION.length)
    : name
  const safeTitle = title
    .replaceAll(MEMORY_MARKDOWN_ESCAPE, () => MEMORY_MARKDOWN_ESCAPE.repeat(2))
    .replaceAll('[', () => `${MEMORY_MARKDOWN_ESCAPE}[`)
    .replaceAll(']', () => `${MEMORY_MARKDOWN_ESCAPE}]`)
  const destination = notePath
    .split('/')
    .map((segment) => encodeURIComponent(segment).replaceAll('(', '%28').replaceAll(')', '%29'))
    .join('/')
  const summary = oneLine(hook)
  return summary === ''
    ? `- [${safeTitle}](${destination})`
    : `- [${safeTitle}](${destination}) | ${summary}`
}

/** Whether a note path is the scope's index itself. */
export function isIndexPath(notePath: string): boolean {
  return notePath === MEMORY_INDEX_FILE
}

src/core/memory/memoryLocation.ts:
// Where Muse Code keeps its memory (M49, PLAN.md D41). Found on disk on
// 2026-09-25 and confirmed by a live capture with the data home moved:
//
//   personal          $XDG_DATA_HOME/muse/memory/personal
//   personal_project  $XDG_DATA_HOME/muse/memory/projects/<slug>-<key>
//   project           <workspace>/.agents/memory
//
// with `~/.local/share` when XDG_DATA_HOME is unset (Windows included). The
// project folder's `<key>` is the FNV-1a 64-bit hash of the workspace's
// canonical path as Rust spells it (`\\?\C:\…` on Windows), in 16 hex digits,
// and `<slug>` its readable half: ASCII letters, digits and hyphens kept,
// anything else a hyphen, the ends trimmed (`C:\muse-live-m49\My Proj.v2_x+é`
// is `C--muse-live-m49-My-Proj-v2-x-0175e6b82ee81b32`). Both were checked
// against the two folders Muse Code made. Pure.

import path from 'node:path'
import {
  MEMORY_DATA_HOME_SEGMENTS,
  MEMORY_DATA_SEGMENTS,
  MEMORY_PERSONAL_DIR,
  MEMORY_PROJECTS_DIR,
} from '../../shared/constants'

export interface MemoryHomeInput {
  readonly platform: NodeJS.Platform
  /** Undefined when the host has no home folder. */
  readonly homeDir: string | undefined
  /** `XDG_DATA_HOME` as `muse serve` sees it (PLAN.md D41). */
  readonly xdgDataHome: string | undefined
}

// FNV-1a, 64 bits: the offset basis and the prime.
const FNV_OFFSET_BASIS = 0xcb_f2_9c_e4_84_22_23_25n
const FNV_PRIME = 0x1_00_00_00_01_b3n
const UINT64_MASK = 0xff_ff_ff_ff_ff_ff_ff_ffn
const HEX_RADIX = 16
const KEY_DIGITS = 16
// Rust's canonical Windows paths are verbatim: `\\?\C:\…`, `\\?\UNC\server\…`.
const VERBATIM_PREFIX = '\\\\?\\'
const VERBATIM_UNC_PREFIX = '\\\\?\\UNC\\'
const UNC_PREFIX = String.raw`\\`
const SLUG_REPLACED = /[^A-Za-z0-9-]/g
const SLUG_ENDS = /^-+|-+$/g
const HYPHEN = '-'

function pathModule(platform: NodeJS.Platform): path.PlatformPath {
  return platform === 'win32' ? path.win32 : path.posix
}

/** Muse Code's memory data root, `…/muse/memory`; undefined without a home or a data home. */
export function memoryDataRoot(input: MemoryHomeInput): string | undefined {
  const p = pathModule(input.platform)
  if (input.xdgDataHome !== undefined && input.xdgDataHome !== '') {
    return p.join(input.xdgDataHome, ...MEMORY_DATA_SEGMENTS)
  }
  return input.homeDir === undefined
    ? undefined
    : p.join(input.homeDir, ...MEMORY_DATA_HOME_SEGMENTS, ...MEMORY_DATA_SEGMENTS)
}

export function personalMemoryRoot(dataRoot: string, platform: NodeJS.Platform): string {
  return pathModule(platform).join(dataRoot, MEMORY_PERSONAL_DIR)
}

export function projectsMemoryRoot(dataRoot: string, platform: NodeJS.Platform): string {
  return pathModule(platform).join(dataRoot, MEMORY_PROJECTS_DIR)
}

/** The path as Rust's `canonicalize` gives it on this platform. */
function rustCanonical(canonicalRoot: string, platform: NodeJS.Platform): string {
  if (platform !== 'win32' || canonicalRoot.startsWith(VERBATIM_PREFIX)) {
    return canonicalRoot
  }
  return canonicalRoot.startsWith(UNC_PREFIX)
    ? `${VERBATIM_UNC_PREFIX}${canonicalRoot.slice(UNC_PREFIX.length)}`
    : `${VERBATIM_PREFIX}${canonicalRoot}`
}

function fnv1a64(bytes: Uint8Array): string {
  let hash = FNV_OFFSET_BASIS
  for (const byte of bytes) {
    hash = ((hash ^ BigInt(byte)) * FNV_PRIME) & UINT64_MASK
  }
  return hash.toString(HEX_RADIX).padStart(KEY_DIGITS, '0')
}

/** The hash half of the project folder's name, from the workspace's canonical path. */
export function projectMemoryKey(canonicalRoot: string, platform: NodeJS.Platform): string {
  return fnv1a64(new TextEncoder().encode(rustCanonical(canonicalRoot, platform)))
}

/** The readable half of the project folder's name. */
export function projectMemorySlug(canonicalRoot: string): string {
  return canonicalRoot.replaceAll(SLUG_REPLACED, '-').replaceAll(SLUG_ENDS, '')
}

/**
 * The workspace's folder under `projects`: one that already ends in its key
 * (whatever Muse Code named it), else the name Muse Code would give it.
 */
export function projectMemoryFolder(
  existing: readonly string[],
  canonicalRoot: string,
  platform: NodeJS.Platform,
): string {
  const key = projectMemoryKey(canonicalRoot, platform)
  const suffix = `${HYPHEN}${key}`
  const found = existing
    .filter((name) => name.endsWith(suffix))
    .toSorted((a, b) => a.localeCompare(b))[0]
  return found ?? `${projectMemorySlug(canonicalRoot)}${suffix}`
}

src/core/memory/memoryStore.ts:
// Muse Code's memory, read and written by the extension (M49, PLAN.md D41):
// the Model API backend's `read_memory`, `add_memory` and `edit_memory`,
// which take Muse Code's arguments and answer with its results so both
// backends' rows read alike and both share one memory, and the Memory view.
//
// What a note may be follows Muse Code 1.3.0 (its binary's messages, and a
// live capture on 2026-09-25): a relative `.md` path under the scope's root,
// no `..`, no hidden component, no link anywhere below the root. `add`
// creates a note (with `type` and `description` as front matter) or appends
// to one after a blank line; `edit` replaces one exact string. Muse Code's
// tools leave `MEMORY.md` to the model; the extension adds a new note's line
// to its scope's index itself and removes a deleted note's lines (D41).
// Existing-note writes replace the file whole (a temporary file renamed over
// it). New notes publish complete bytes with a no-clobber hard link. Muse
// Code's own lock (`.muse-memory.lock`, an operating-system lock) is not
// taken: two writers updating one existing note may lose one write.

import path from 'node:path'
import {
  MEMORY_DIR,
  MEMORY_DIR_SEGMENTS,
  MEMORY_INDEX_FILE,
  MEMORY_LIST_MAX_DEPTH,
  MEMORY_LIST_MAX_NOTES,
  MEMORY_NOTE_EXTENSION,
  MEMORY_READ_DEFAULT_LIMIT,
  MEMORY_SCOPES,
  MEMORY_SNAPSHOT_MAX_NOTES,
  type MemoryScope,
  MODEL_TEXT,
  TOOL_OUTPUT_MAX_CHARS,
} from '../../shared/constants'
import { resolveWorkspacePath } from '../workspacePath'
import {
  indexLineFor,
  hasIndexLine,
  isIndexPath,
  limitMemoryIndex,
  noteSummary,
  withIndexLine,
  withoutIndexLines,
} from './memoryIndex'
import { personalMemoryRoot, projectMemoryFolder, projectsMemoryRoot } from './memoryLocation'

export interface MemoryDirectoryEntry {
  readonly name: string
  /** A link or junction is `other`: it is never followed. */
  readonly kind: 'file' | 'directory' | 'other'
}

/** What the store reads and writes through; the host lends the file system. */
export interface MemoryIo {
  /** The file's text, a BOM kept; undefined when absent; rejects when it is not UTF-8 text. */
  readFile(absolutePath: string): Promise<string | undefined>
  /** Whether the path is open with unsaved changes, which a replacement must not clobber. */
  hasUnsavedChanges(absolutePath: string): boolean
  /**
   * Replaces the file whole (a temporary file renamed into place), folders
   * created. With `checkedPath` (its canonical path as `locate` checked it),
   * a path that leads elsewhere by the time it is written is refused.
   */
  writeFile(
    absolutePath: string,
    content: string,
    checkedPath?: string,
    assertCanWrite?: () => void,
  ): Promise<void>
  /**
   * Atomically publishes a complete new note only if absent; never replaces
   * another writer. With `checkedPath` (the note's canonical path as `locate`
   * checked it), a folder that leads elsewhere by the time the note is
   * written is refused.
   */
  createFile(
    absolutePath: string,
    content: string,
    checkedPath?: string,
    assertCanWrite?: () => void,
  ): Promise<void>
  /** The canonical form (links resolved) of a path that may not exist yet. */
  realPath(absolutePath: string): Promise<string>
  /** A directory's entries; empty when it is missing. */
  listEntries(absolutePath: string): Promise<readonly MemoryDirectoryEntry[]>
}

/**
 * The writes of one memory call. The store is the window's, so a turn's
 * model hands in its own, which record each write for a restore (M86); the
 * store's own io records nothing.
 */
export type MemoryWrites = Pick<MemoryIo, 'writeFile' | 'createFile'>

export interface MemoryStoreDeps {
  readonly io: MemoryIo
  readonly platform: NodeJS.Platform
  /** Muse Code's memory data root (`…/muse/memory`); undefined without a home. */
  readonly dataRoot: () => string | undefined
  /** Undefined without a workspace folder. */
  readonly workspaceRoot: string | undefined
  /**
   * A path as the operating system spells it, links resolved and each name
   * in its own letter case: the workspace root Muse Code hashes.
   */
  readonly systemPath: (absolutePath: string) => Promise<string>
  /** Something that went wrong beside the call itself (an index line, an unreadable scope). */
  readonly warn: (message: string) => void
}

/** A note, validated and placed. */
export interface MemoryNotePlace {
  readonly scope: MemoryScope
  /** As the tools name it: relative to the scope's root, forward slashes. */
  readonly path: string
  readonly absolute: string
  /** What an approval card shows: `.agents/memory/…` for the project, else the absolute path. */
  readonly display: string
  /** The canonical path `locate` checked; a new note is written only there. */
  readonly checked?: string
}

export type Located<T> =
  { readonly ok: true; readonly value: T } | { readonly ok: false; readonly reason: string }

/** A tool call's outcome: Muse Code's JSON result, or why it failed. */
export type MemoryOutcome = Located<string>

export interface MemoryNote extends MemoryNotePlace {
  /** Its front matter's description, else its first line of text. */
  readonly summary: string
}

/** One scope as the session-start snapshot gives it to the model. */
export interface MemoryScopeSnapshot {
  readonly scope: MemoryScope
  /** The scope's `MEMORY.md` within the limits; undefined when it has none. */
  readonly index: string | undefined
  /** The other notes' paths, at most MEMORY_SNAPSHOT_MAX_NOTES. */
  readonly notes: readonly string[]
  readonly hasMoreNotes: boolean
}

/** `read_memory`'s window: 1-based first line, and how many lines. */
export interface ReadWindow {
  readonly offset?: number | undefined
  readonly limit?: number | undefined
}

/** `add_memory`'s note: its text and, for a new note, its front matter. */
export interface NoteAddition {
  readonly content: string
  readonly type?: string | undefined
  readonly description?: string | undefined
}

/** `edit_memory`'s exact replacement. */
export interface NoteEdit {
  readonly old_str: string
  readonly new_str: string
}

const HIDDEN_PREFIX = '.'
const PARENT_SEGMENT = '..'
const SEPARATORS = /[/\\]/
const WINDOWS_DRIVE = /^[A-Za-z]:/
const TRAILING_BREAKS = /(?:\r?\n)+$/
// One line with its own line break (the last may have none).
const LINES_WITH_BREAKS = /[^\n]*\n|[^\n]+$/g
const PARAGRAPH_BREAK = '\n\n'
const FRONT_MATTER_FENCE = '---'
const OPERATION_ADD = 'add'
const OPERATION_EDIT = 'edit'

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

function isTaken(error: unknown): boolean {
  return typeof error === 'object' && error !== null && 'code' in error && error.code === 'EEXIST'
}

function failed(reason: string): { readonly ok: false; readonly reason: string } {
  return { ok: false, reason }
}

/**
 * What `add` throws when its owner's assertion stopped a new note's index
 * line (M78, the RV78g review): the note is published already, `written` is
 * the tool's answer for it, and `stopped` is what the owner threw, for the
 * owner to tell its Stop from a refusal of the line alone.
 */
export class IndexLineStoppedError extends Error {
  public readonly stopped: Error

  public constructor(
    public readonly written: string,
    stopped: unknown,
  ) {
    super(`the ${MEMORY_INDEX_FILE} line was stopped`)
    this.name = 'IndexLineStoppedError'
    this.stopped = stopped instanceof Error ? stopped : new Error(describe(stopped))
  }
}

/**
 * After a write failed: the caller's assertion asked once more (M78, the
 * RV78f and RV78g reviews). It keeps throwing once it has thrown (a Stop, a
 * refusal, a revoked guard), so a failure it caused is thrown on as the
 * caller's, never reported as a file error; the I/O is handed the very
 * assertion it was given.
 */
function rethrowOwner(assertCurrent: (() => void) | undefined): void {
  assertCurrent?.()
}

function isUnavailable(reason: string): boolean {
  return reason === MODEL_TEXT.memoryNoWorkspace || reason === MODEL_TEXT.memoryNoHome
}

function pathModule(platform: NodeJS.Platform): path.PlatformPath {
  return platform === 'win32' ? path.win32 : path.posix
}

/** Why Muse Code would refuse this note path, or undefined (its own checks, in its order). */
export function memoryPathProblem(given: string): string | undefined {
  if (given.trim() === '') {
    return MODEL_TEXT.memoryPathEmpty
  }
  if (path.posix.isAbsolute(given) || path.win32.isAbsolute(given) || WINDOWS_DRIVE.test(given)) {
    return MODEL_TEXT.memoryPathAbsolute
  }
  const segments = given.split(SEPARATORS)
  if (segments.includes(PARENT_SEGMENT)) {
    return MODEL_TEXT.memoryPathTraversal
  }
  const name = segments.at(-1) ?? ''
  if (name === '') {
    return MODEL_TEXT.memoryPathNoFileName
  }
  if (segments.some((segment) => segment.startsWith(HIDDEN_PREFIX))) {
    return MODEL_TEXT.memoryPathHidden
  }
  return name.endsWith(MEMORY_NOTE_EXTENSION) ? undefined : MODEL_TEXT.memoryPathNotMarkdown
}

/** Muse Code's `{:?}` of a string, near enough: quoted, with its escapes. */
function quoted(text: string): string {
  return JSON.stringify(text)
}

function occurrences(text: string, part: string): number {
  return text.split(part).length - 1
}

/** A new note's text: `type` and `description` as front matter, as Muse Code writes them. */
function newNoteText(note: NoteAddition): string {
  const fields = [
    ...(note.type === undefined ? [] : [`type: ${note.type}`]),
    ...(note.description === undefined ? [] : [`description: ${note.description}`]),
  ]
  return fields.length === 0
    ? note.content
    : [FRONT_MATTER_FENCE, ...fields, FRONT_MATTER_FENCE, '', note.content].join('\n')
}

/** A note's text after `content` is appended: after a blank line, its front matter as it was. */
function appendedText(existing: string, content: string): string {
  const kept = existing.replace(TRAILING_BREAKS, '')
  return kept === '' ? content : `${kept}${PARAGRAPH_BREAK}${content}`
}

function isSamePath(a: string, b: string, platform: NodeJS.Platform): boolean {
  // Windows and macOS file systems fold case.
  return platform === 'linux' ? a === b : a.toLowerCase() === b.toLowerCase()
}

/** Muse Code's answer to a write (captured live 2026-09-25). */
function written(place: MemoryNotePlace, operation: string, message: string): string {
  return JSON.stringify({ success: true, scope: place.scope, path: place.path, operation, message })
}

function placeOf(
  scope: MemoryScope,
  notePath: string,
  absolute: string,
  checked?: string,
): MemoryNotePlace {
  return {
    scope,
    path: notePath,
    absolute,
    display: scope === 'project' ? `${MEMORY_DIR}/${notePath}` : absolute,
    ...(checked !== undefined && { checked }),
  }
}

/** The index first, then the notes by name. */
function byIndexThenName(a: string, b: string): number {
  if (isIndexPath(a) !== isIndexPath(b)) {
    return isIndexPath(a) ? -1 : 1
  }
  return a.localeCompare(b)
}

export class MemoryStore {
  public constructor(private readonly deps: MemoryStoreDeps) {}

  private get p(): path.PlatformPath {
    return pathModule(this.deps.platform)
  }

  private async personalProjectRoot(dataRoot: string): Promise<Located<string>> {
    const { workspaceRoot } = this.deps
    if (workspaceRoot === undefined) {
      return failed(MODEL_TEXT.memoryNoWorkspace)
    }
    const projects = projectsMemoryRoot(dataRoot, this.deps.platform)
    const checkedProjects = await this.checkedRoot(projects, dataRoot)
    if (!checkedProjects.ok) {
      return checkedProjects
    }
    let canonical: string
    let entries: readonly MemoryDirectoryEntry[]
    try {
      ;[canonical, entries] = await Promise.all([
        this.deps.systemPath(workspaceRoot),
        this.deps.io.listEntries(projects),
      ])
    } catch (error: unknown) {
      return failed(describe(error))
    }
    const folders = entries.filter((entry) => entry.kind === 'directory').map((entry) => entry.name)
    return {
      ok: true,
      value: this.p.join(projects, projectMemoryFolder(folders, canonical, this.deps.platform)),
    }
  }

  /**
   * The note's text (undefined when there is none), or why it cannot be read.
   * The caller's assertion throws on: a Stop is never a file error (the
   * RV78f review).
   */
  private async readNote(
    place: MemoryNotePlace,
    assertCurrent?: () => void,
  ): Promise<Located<string | undefined>> {
    assertCurrent?.()
    let value: string | undefined
    try {
      value = await this.deps.io.readFile(place.absolute)
    } catch (error: unknown) {
      return failed(describe(error))
    }
    assertCurrent?.()
    return { ok: true, value }
  }

  /** The scope's index place; throws with the reason when the scope has none. */
  private async indexPlace(scope: MemoryScope): Promise<MemoryNotePlace> {
    const place = await this.locate(scope, MEMORY_INDEX_FILE)
    if (!place.ok) {
      throw new Error(place.reason)
    }
    return place.value
  }

  /** A replacement refused under the editor's unsaved changes, or undefined. */
  private unsavedRefusal(
    absolutePath: string,
  ): { readonly ok: false; readonly reason: string } | undefined {
    return this.deps.io.hasUnsavedChanges(absolutePath)
      ? failed(`${absolutePath} ${MODEL_TEXT.fileHasUnsavedChanges}`)
      : undefined
  }

  /**
   * A new note's line in its scope's `MEMORY.md`, unless one already links to
   * it (D41). A line that cannot be written is logged and the note stays; what
   * the owner's assertion threw (its Stop, its refusal) is thrown on after the
   * log, as the note's own writes throw it (M78, the RV78g review).
   */
  private async addIndexLine(
    place: MemoryNotePlace,
    hook: string,
    assertCurrent: (() => void) | undefined,
    writes: MemoryWrites,
  ): Promise<void> {
    if (isIndexPath(place.path)) {
      return
    }
    try {
      assertCurrent?.()
      const index = await this.indexPlace(place.scope)
      assertCurrent?.()
      if (this.unsavedRefusal(index.absolute) !== undefined) {
        this.deps.warn(
          `${place.display}'s ${MEMORY_INDEX_FILE} line waits: the index has unsaved changes`,
        )
        return
      }
      const text = await this.deps.io.readFile(index.absolute)
      assertCurrent?.()
      if (text !== undefined && hasIndexLine(text, place.path)) {
        return
      }
      await writes.writeFile(
        index.absolute,
        withIndexLine(text, indexLineFor(place.path, hook)),
        index.checked,
        assertCurrent,
      )
    } catch (error: unknown) {
      this.deps.warn(
        `${place.display} was written, but its ${MEMORY_INDEX_FILE} line was not: ${describe(error)}`,
      )
      rethrowOwner(assertCurrent)
    }
  }

  private async walk(root: string, relative: readonly string[], found: string[]): Promise<void> {
    if (relative.length > MEMORY_LIST_MAX_DEPTH || found.length >= MEMORY_LIST_MAX_NOTES) {
      return
    }
    const entries = await this.deps.io.listEntries(this.p.join(root, ...relative))
    const visible = entries
      .filter((entry) => !entry.name.startsWith(HIDDEN_PREFIX))
      .toSorted((a, b) => a.name.localeCompare(b.name))
    for (const entry of visible) {
      if (found.length >= MEMORY_LIST_MAX_NOTES) {
        return
      }
      const segments = [...relative, entry.name]
      if (entry.kind === 'directory') {
        await this.walk(root, segments, found)
      } else if (entry.kind === 'file' && entry.name.endsWith(MEMORY_NOTE_EXTENSION)) {
        found.push(segments.join('/'))
      }
    }
  }

  /**
   * The notes of a scope as places, the index first; none when the scope is
   * unavailable. The walk never enters a link, so no place is behind one.
   */
  private async notePlaces(scope: MemoryScope): Promise<readonly MemoryNotePlace[]> {
    const root = await this.root(scope)
    if (!root.ok) {
      if (isUnavailable(root.reason)) {
        return []
      }
      throw new Error(root.reason)
    }
    const found: string[] = []
    await this.walk(root.value, [], found)
    return found
      .toSorted(byIndexThenName)
      .map((notePath) => placeOf(scope, notePath, this.p.join(root.value, ...notePath.split('/'))))
  }

  private async indexText(scope: MemoryScope): Promise<string | undefined> {
    const index = await this.indexPlace(scope)
    const text = await this.deps.io.readFile(index.absolute)
    if (text === undefined) {
      return undefined
    }
    const limited = limitMemoryIndex(text, `${scope} ${MEMORY_INDEX_FILE}`)
    if (limited.warning !== undefined) {
      this.deps.warn(limited.warning)
    }
    return limited.text
  }

  /** A scope must stay below its trusted anchor, even when its root is a link. */
  private async checkedRoot(root: string, anchor: string): Promise<Located<string>> {
    try {
      const [realAnchor, realRoot] = await Promise.all([
        this.deps.io.realPath(anchor),
        this.deps.io.realPath(root),
      ])
      return isSamePath(
        realRoot,
        this.p.join(realAnchor, this.p.relative(anchor, root)),
        this.deps.platform,
      )
        ? { ok: true, value: root }
        : failed(MODEL_TEXT.memoryPathLink)
    } catch (error: unknown) {
      return failed(describe(error))
    }
  }

  /** The scopes this window has: `personal` with a home, the other two with a folder. */
  public async availableScopes(): Promise<readonly MemoryScope[]> {
    const roots = await Promise.all(MEMORY_SCOPES.map((scope) => this.root(scope)))
    for (const [index, scope] of MEMORY_SCOPES.entries()) {
      const result = roots[index]
      if (result !== undefined && !result.ok && !isUnavailable(result.reason)) {
        this.deps.warn(`the ${scope} memory could not be read: ${result.reason}`)
      }
    }
    return MEMORY_SCOPES.filter((_scope, index) => roots[index]?.ok === true)
  }

  /** A scope's root folder (it may not exist yet), or why the scope is unavailable. */
  public async root(scope: MemoryScope): Promise<Located<string>> {
    if (scope === 'project') {
      const workspaceRoot = this.deps.workspaceRoot
      return workspaceRoot === undefined
        ? failed(MODEL_TEXT.memoryNoWorkspace)
        : await this.checkedRoot(this.p.join(workspaceRoot, ...MEMORY_DIR_SEGMENTS), workspaceRoot)
    }
    const dataRoot = this.deps.dataRoot()
    if (dataRoot === undefined) {
      return failed(MODEL_TEXT.memoryNoHome)
    }
    const root: Located<string> =
      scope === 'personal'
        ? { ok: true, value: personalMemoryRoot(dataRoot, this.deps.platform) }
        : await this.personalProjectRoot(dataRoot)
    return root.ok ? await this.checkedRoot(root.value, dataRoot) : root
  }

  /**
   * A note path checked as Muse Code checks it and placed under its scope,
   * or the refusal: a path that climbs out, a hidden part, not Markdown, or a
   * link anywhere between the scope's root and the note.
   */
  public async locate(scope: MemoryScope, given: string): Promise<Located<MemoryNotePlace>> {
    const problem = memoryPathProblem(given)
    if (problem !== undefined) {
      return failed(problem)
    }
    const root = await this.root(scope)
    if (!root.ok) {
      return root
    }
    const relative = given.split(SEPARATORS).join('/')
    // The Windows checks (device names, streams, trailing dots) of the file tools.
    const resolved = resolveWorkspacePath(root.value, relative, this.deps.platform)
    if (!resolved.ok) {
      return resolved
    }
    let checked: string
    try {
      const [realRoot, realTarget] = await Promise.all([
        this.deps.io.realPath(root.value),
        this.deps.io.realPath(resolved.absolute),
      ])
      if (
        !isSamePath(realTarget, this.p.join(realRoot, ...relative.split('/')), this.deps.platform)
      ) {
        return failed(MODEL_TEXT.memoryPathLink)
      }
      checked = realTarget
    } catch (error: unknown) {
      return failed(describe(error))
    }
    return { ok: true, value: placeOf(scope, relative, resolved.absolute, checked) }
  }

  /** `read_memory`: a window of lines, each with its own line break. */
  public async read(
    place: MemoryNotePlace,
    window: ReadWindow,
    assertCurrent?: () => void,
  ): Promise<MemoryOutcome> {
    const offset = window.offset ?? 1
    if (offset < 1) {
      return failed(MODEL_TEXT.memoryOffsetTooSmall)
    }
    const limit = window.limit ?? MEMORY_READ_DEFAULT_LIMIT
    if (limit < 1) {
      return failed(MODEL_TEXT.memoryLimitTooSmall)
    }
    const read = await this.readNote(place, assertCurrent)
    if (!read.ok) {
      return read
    }
    if (read.value === undefined) {
      return failed(MODEL_TEXT.memoryFileNotFound)
    }
    const lines = read.value.match(LINES_WITH_BREAKS) ?? []
    const shown = lines.slice(offset - 1, offset - 1 + limit).join('')
    const isClipped = shown.length > TOOL_OUTPUT_MAX_CHARS
    return {
      ok: true,
      value: JSON.stringify({
        success: true,
        scope: place.scope,
        path: place.path,
        start_line_number: offset,
        content: isClipped ? shown.slice(0, TOOL_OUTPUT_MAX_CHARS) : shown,
        truncated: isClipped || offset - 1 + limit < lines.length,
      }),
    }
  }

  /** `add_memory`: a new note, or the content appended after a blank line. */
  public async add(
    place: MemoryNotePlace,
    note: NoteAddition,
    assertCurrent?: () => void,
    writes: MemoryWrites = this.deps.io,
  ): Promise<MemoryOutcome> {
    const read = await this.readNote(place, assertCurrent)
    if (!read.ok) {
      return read
    }
    const existing = read.value
    if (existing !== undefined) {
      const refused = this.unsavedRefusal(place.absolute)
      if (refused !== undefined) {
        return refused
      }
    }
    assertCurrent?.()
    try {
      if (existing === undefined) {
        await writes.createFile(place.absolute, newNoteText(note), place.checked, assertCurrent)
      } else {
        await writes.writeFile(
          place.absolute,
          appendedText(existing, note.content),
          place.checked,
          assertCurrent,
        )
      }
    } catch (error: unknown) {
      rethrowOwner(assertCurrent)
      return failed(isTaken(error) ? MODEL_TEXT.memoryNoteExists : describe(error))
    }
    const result = written(place, OPERATION_ADD, MODEL_TEXT.memoryNoteWritten)
    if (existing === undefined) {
      try {
        await this.addIndexLine(
          place,
          note.description ?? noteSummary(note.content),
          assertCurrent,
          writes,
        )
      } catch (error: unknown) {
        // Only the owner's throw reaches here: the note is published already.
        throw new IndexLineStoppedError(result, error)
      }
    }
    return { ok: true, value: result }
  }

  /** `edit_memory`: one exact string replaced, refused unless it occurs exactly once. */
  public async edit(
    place: MemoryNotePlace,
    change: NoteEdit,
    assertCurrent?: () => void,
    writes: MemoryWrites = this.deps.io,
  ): Promise<MemoryOutcome> {
    if (change.old_str === '') {
      return failed(MODEL_TEXT.memoryOldStrEmpty)
    }
    const read = await this.readNote(place, assertCurrent)
    if (!read.ok) {
      return read
    }
    const text = read.value
    if (text === undefined) {
      return failed(MODEL_TEXT.memoryFileNotFound)
    }
    const refused = this.unsavedRefusal(place.absolute)
    if (refused !== undefined) {
      return refused
    }
    const count = occurrences(text, change.old_str)
    if (count === 0) {
      return failed(`${MODEL_TEXT.memoryOldStrNotFound} ${quoted(change.old_str)}`)
    }
    if (count > 1) {
      return failed(`${MODEL_TEXT.memoryOldStrAmbiguous} ${quoted(change.old_str)}`)
    }
    assertCurrent?.()
    try {
      await writes.writeFile(
        place.absolute,
        text.replace(change.old_str, () => change.new_str),
        place.checked,
        assertCurrent,
      )
    } catch (error: unknown) {
      rethrowOwner(assertCurrent)
      return failed(describe(error))
    }
    return { ok: true, value: written(place, OPERATION_EDIT, MODEL_TEXT.memoryNoteEdited) }
  }

  /** A scope's notes with what each is about, the index first (the Memory view). */
  public async notes(scope: MemoryScope): Promise<readonly MemoryNote[]> {
    const places = await this.notePlaces(scope)
    return await Promise.all(
      places.map(async (place) => {
        const read = await this.readNote(place)
        const summary = read.ok && read.value !== undefined ? noteSummary(read.value) : ''
        return { ...place, summary }
      }),
    )
  }

  /** Whether anything is already at the note's place. */
  public async hasNote(place: MemoryNotePlace): Promise<boolean> {
    const read = await this.readNote(place)
    return !read.ok || read.value !== undefined
  }

  /**
   * A new, empty note from the Memory view (its description as front
   * matter when given), with its line in the scope's index. Throws with the
   * reason when the path is refused or taken.
   */
  public async create(
    scope: MemoryScope,
    notePath: string,
    description: string,
    assertCurrent?: () => void,
  ): Promise<MemoryNotePlace> {
    assertCurrent?.()
    const place = await this.locate(scope, notePath)
    assertCurrent?.()
    if (!place.ok) {
      throw new Error(place.reason)
    }
    const isPresent = await this.hasNote(place.value)
    assertCurrent?.()
    if (isPresent) {
      throw new Error(MODEL_TEXT.memoryNoteExists)
    }
    const hook = description.trim()
    try {
      await this.deps.io.createFile(
        place.value.absolute,
        hook === '' ? '' : newNoteText({ content: '', description: hook }),
        place.value.checked,
        assertCurrent,
      )
    } catch (error: unknown) {
      throw new Error(isTaken(error) ? MODEL_TEXT.memoryNoteExists : describe(error), {
        cause: error,
      })
    }
    try {
      await this.addIndexLine(place.value, hook, assertCurrent, this.deps.io)
    } catch {
      // The view keeps a note its guard left published; its line was logged as not written.
    }
    return place.value
  }

  /** After the view deleted a note: its lines leave the scope's index. */
  public async forget(place: MemoryNotePlace, assertCurrent?: () => void): Promise<void> {
    if (isIndexPath(place.path)) {
      return
    }
    assertCurrent?.()
    const index = await this.indexPlace(place.scope)
    assertCurrent?.()
    const text = await this.deps.io.readFile(index.absolute)
    assertCurrent?.()
    const updated = text === undefined ? undefined : withoutIndexLines(text, place.path)
    if (updated === undefined) {
      return
    }
    if (this.unsavedRefusal(index.absolute) !== undefined) {
      this.deps.warn(
        `the ${MEMORY_INDEX_FILE} line for ${place.display} waits: the index has unsaved changes`,
      )
      return
    }
    await this.deps.io.writeFile(index.absolute, updated, index.checked, assertCurrent)
  }

  /**
   * What the model is given at the start of a session, as Muse Code gives
   * it: each scope's `MEMORY.md` and the paths of its other notes. A scope
   * that cannot be read is a warning, never a failed turn.
   */
  public async snapshot(): Promise<readonly MemoryScopeSnapshot[]> {
    const snapshots: MemoryScopeSnapshot[] = []
    for (const scope of MEMORY_SCOPES) {
      try {
        const places = await this.notePlaces(scope)
        const others = places.filter((place) => !isIndexPath(place.path)).map((place) => place.path)
        const index = others.length === places.length ? undefined : await this.indexText(scope)
        if (index !== undefined || others.length > 0) {
          snapshots.push({
            scope,
            index,
            notes: others.slice(0, MEMORY_SNAPSHOT_MAX_NOTES),
            hasMoreNotes: others.length > MEMORY_SNAPSHOT_MAX_NOTES,
          })
        }
      } catch (error: unknown) {
        this.deps.warn(`the ${scope} memory could not be read: ${describe(error)}`)
      }
    }
    return snapshots
  }
}

src/core/mention.ts:
// Builds the `@path#start-end` reference the Alt+K keybinding inserts into the
// composer, mirroring the Claude Code extension's mention syntax
// (`@app.ts#5-10`; a single line is `@app.ts#5`; no selection is `@app.ts`),
// with a path that holds a space, `#` or `"` quoted (`@"my app.ts"#5-10`,
// PLAN.md D27; `src/shared/mentions.ts` has the syntax). Pure; no `vscode`
// import.

import { formatMention } from '../shared/mentions'

export interface MentionSource {
  /** Workspace-relative with forward slashes, or absolute for a file outside the root. */
  readonly relativePath: string
  /** 1-based, inclusive. */
  readonly startLine: number
  /** 1-based, inclusive. */
  readonly endLine: number
  /** True when the selection is a bare cursor (nothing highlighted). */
  readonly isEmpty: boolean
}

export function formatMentionReference(source: MentionSource): string {
  const path = source.relativePath.replaceAll('\\', '/')
  return formatMention(
    path,
    source.isEmpty ? undefined : { startLine: source.startLine, endLine: source.endLine },
  )
}

src/core/mentionIndex.ts:
// The searchable list of workspace paths behind the `@` mention menu. The
// file list comes from an injected lister (git or VS Code's file search, see
// src/host/mention/workspaceFiles.ts), is cached for a short TTL because the
// menu queries on every keystroke, and is ranked with the fuzzy scorer.

import type { MentionItem } from '../shared/protocol'
import { rankMatches } from './fuzzy'
import type { CoreLogger } from './logging'

export interface MentionIndexDeps {
  readonly listFiles: () => Promise<readonly string[]>
  readonly now: () => number
  readonly ttlMs: number
  /** Paths beyond this many are dropped (with a warning) to bound search time. */
  readonly limit: number
  readonly log: CoreLogger
}

interface CachedIndex {
  readonly items: readonly MentionItem[]
  readonly builtAt: number
}

/** Files plus every ancestor folder (`dir/`), folders first within ties. */
export function buildMentionItems(files: readonly string[]): readonly MentionItem[] {
  const folders = new Set<string>()
  for (const file of files) {
    let slash = file.indexOf('/')
    while (slash !== -1) {
      folders.add(file.slice(0, slash + 1))
      slash = file.indexOf('/', slash + 1)
    }
  }
  return [
    ...[...folders].map((path) => ({ path, isFolder: true })),
    ...files.map((path) => ({ path, isFolder: false })),
  ]
}

export class MentionIndex {
  private cache: CachedIndex | undefined
  private inflight: Promise<readonly MentionItem[]> | undefined

  public constructor(private readonly deps: MentionIndexDeps) {}

  private async load(): Promise<readonly MentionItem[]> {
    const now = this.deps.now()
    if (this.cache !== undefined && now - this.cache.builtAt < this.deps.ttlMs) {
      return this.cache.items
    }
    this.inflight ??= this.rebuild()
    try {
      return await this.inflight
    } finally {
      this.inflight = undefined
    }
  }

  private async rebuild(): Promise<readonly MentionItem[]> {
    const files = await this.deps.listFiles()
    const kept = files.length > this.deps.limit ? files.slice(0, this.deps.limit) : files
    if (kept.length < files.length) {
      this.deps.log.warn(
        `Mention index truncated to ${String(this.deps.limit)} of ${String(files.length)} paths`,
      )
    }
    const items = buildMentionItems(kept)
    this.cache = { items, builtAt: this.deps.now() }
    return items
  }

  public async search(query: string, limit: number): Promise<readonly MentionItem[]> {
    const items = await this.load()
    return rankMatches(query, items, (item) => item.path, limit)
  }

  /**
   * Whether the index lists this file: false for gitignored / excluded files
   * (and, since the index is capped, for files beyond the cap), which is when
   * Claude Code shares a path but not its content.
   */
  public async contains(relativePath: string): Promise<boolean> {
    const items = await this.load()
    return items.some((item) => !item.isFolder && item.path === relativePath)
  }

  /** Forget the cached list (a workspace file changed). */
  public invalidate(): void {
    this.cache = undefined
  }
}

src/core/networkFailure.ts:
// What went wrong when a request never reached the server (M56, PLAN.md
// D43). Node's `fetch` throws "fetch failed" and keeps the reason in the
// error's causes: a TLS verification code for a certificate it does not
// trust, a socket code for a connection it could not make, or undici's
// "Proxy response (407) !== 200 when HTTP Tunneling" from a proxy. Those are
// the facts a user behind a corporate network needs, so the message names
// the likely fix (which VS Code setting, which store) and keeps the
// technical detail beside it. Pure; no `vscode` import. The shapes are the
// ones Node 24 throws (captured 2026-09-25, docs/certification/m56.md).
//
// The ACP agent (PLAN.md D62, Q66) runs outside VS Code, where its
// settings do not reach: there the same failure names the variables the
// agent's own environment takes instead. The host says which it is.

import {
  CONNECTION_ERROR_CODES,
  ERROR_CAUSE_MAX_DEPTH,
  HTTP_PROXY_AUTHENTICATION_REQUIRED,
  PROXY_TUNNEL_STATUS,
  TLS_TRUST_ERROR_CODES,
  UI_TEXT,
} from '../shared/constants'
import { fill } from '../shared/l10n/text'
import { redactSecrets } from './redact'

export type NetworkFailureKind =
  'certificate' | 'proxyCredentials' | 'proxyRefused' | 'unreachable' | 'other'

/**
 * Whose settings the advice names: VS Code's `http.*` settings in the
 * extension, the agent's environment variables in the ACP agent.
 */
export type NetworkAdvice = 'vscode' | 'agent'

export interface NetworkFailure {
  readonly kind: NetworkFailureKind
  /** The error and its causes, "fetch failed: connect ECONNREFUSED … (ECONNREFUSED)". */
  readonly detail: string
  /** The status a proxy answered the tunnel with, for the proxy kinds. */
  readonly proxyStatus: number | undefined
}

interface Link {
  readonly message: string
  /** A string code (`ECONNREFUSED`); a DOMException's numeric code is not one. */
  readonly code: string | undefined
}

/** A cause that is not an Error: its text when it is one, else only its type. */
function plainLink(cause: unknown): Link {
  const message =
    typeof cause === 'string' || typeof cause === 'number' ? String(cause) : typeof cause
  return { message, code: undefined }
}

/** The error, then each `cause` under it, as far as ERROR_CAUSE_MAX_DEPTH. */
function chainOf(error: unknown): readonly Link[] {
  const links: Link[] = []
  let current: unknown = error
  while (current !== undefined && current !== null) {
    if (links.length >= ERROR_CAUSE_MAX_DEPTH) {
      break
    }
    if (!(current instanceof Error)) {
      links.push(plainLink(current))
      break
    }
    const code = 'code' in current && typeof current.code === 'string' ? current.code : undefined
    links.push({ message: current.message, code })
    current = current.cause
  }
  return links
}

function describeLink(link: Link): string {
  return link.code === undefined || link.message.includes(link.code)
    ? link.message
    : `${link.message} (${link.code})`
}

function proxyStatusIn(links: readonly Link[]): number | undefined {
  for (const link of links) {
    const status = PROXY_TUNNEL_STATUS.exec(link.message)?.[1]
    if (status !== undefined) {
      return Number(status)
    }
  }
  return undefined
}

function kindOf(links: readonly Link[], proxyStatus: number | undefined): NetworkFailureKind {
  if (proxyStatus !== undefined) {
    return proxyStatus === HTTP_PROXY_AUTHENTICATION_REQUIRED ? 'proxyCredentials' : 'proxyRefused'
  }
  const codes = links.flatMap((link) => (link.code === undefined ? [] : [link.code]))
  if (codes.some((code) => TLS_TRUST_ERROR_CODES.has(code))) {
    return 'certificate'
  }
  return codes.some((code) => CONNECTION_ERROR_CODES.has(code)) ? 'unreachable' : 'other'
}

export function describeNetworkFailure(error: unknown): NetworkFailure {
  const links = chainOf(error)
  const proxyStatus = proxyStatusIn(links)
  return {
    kind: kindOf(links, proxyStatus),
    detail: redactSecrets(links.map((link) => describeLink(link)).join(': ')),
    proxyStatus,
  }
}

/**
 * The error and its causes by their codes (`ERR_TLS_CERT_ALTNAME_INVALID`),
 * a cause's message only where it has no code (M69). A code is Node's own
 * word; a message can carry what a server sent, such as the names on its
 * certificate.
 */
export function networkFailureCodes(error: unknown): string {
  return redactSecrets(
    chainOf(error)
      .map((link) => link.code ?? link.message)
      .join(': '),
  )
}

/** The advice for a kind, read when shown (PLAN.md D33); none for an unrecognised failure. */
function adviceFor(failure: NetworkFailure, advice: NetworkAdvice): string | undefined {
  const isAgent = advice === 'agent'
  switch (failure.kind) {
    case 'certificate': {
      return isAgent ? UI_TEXT.acpNetworkUntrustedCertificate : UI_TEXT.networkUntrustedCertificate
    }
    case 'proxyCredentials': {
      return isAgent ? UI_TEXT.acpNetworkProxyCredentials : UI_TEXT.networkProxyCredentials
    }
    case 'proxyRefused': {
      // A status code, not a quantity: never grouped or localised.
      return fill(UI_TEXT.networkProxyRefused, { status: String(failure.proxyStatus) })
    }
    case 'unreachable': {
      return isAgent ? UI_TEXT.acpNetworkUnreachable : UI_TEXT.networkUnreachable
    }
    case 'other': {
      return undefined
    }
  }
}

/**
 * The advice, with the technical detail in parentheses; the detail alone
 * when there is none. A proxy's refusal names no setting, so both hosts
 * share it.
 */
export function networkFailureMessage(error: unknown, advice: NetworkAdvice = 'vscode'): string {
  const failure = describeNetworkFailure(error)
  const text = adviceFor(failure, advice)
  return text === undefined ? failure.detail : `${text} (${failure.detail})`
}

