// What the extension reads of a PDF (M54, PLAN.md D47): that it is one, by
// its header rather than its name, and how many pages it has when that is
// cheap to learn. The count names the chip and weighs the PDF against
// Meta's 50 images per request (its first 50 pages each become one); an
// unknown count reserves all 50 slots in the attachment store.
//
// The count comes from a directly visible `/Type /Pages` dictionary's
// `/Count`, the largest of them. Compressed or encrypted page trees have no
// count here and reserve the full request budget. This inspection never
// decompresses untrusted file content on the extension host thread.

import { Buffer } from 'node:buffer'
import {
  PDF_DICTIONARY_SCAN_CHARS,
  PDF_PAGE_COUNT_MAX,
  PDF_PAGE_TREE_SCAN_LIMIT,
} from '../shared/constants'
import { hasPdfHeader } from '../shared/pdfHeader'

const PDF_NAME_ESCAPE_RADIX = 16
const PDF_NAME_ESCAPE_SOURCE_CHARS = 3
const PDF_CRITICAL_NAME_MAX_LENGTH = 'Encrypt'.length
const PDF_CRITICAL_NAME_SOURCE_MAX_LENGTH =
  PDF_CRITICAL_NAME_MAX_LENGTH * PDF_NAME_ESCAPE_SOURCE_CHARS
const PDF_CRITICAL_NAMES = new Set(['type', 'objstm', 'encrypt', 'pages', 'count'])
const PDF_NAME_HEX_PAIR = /^[0-9A-Fa-f]{2}$/
const PDF_NAME_LETTER = /^[A-Za-z]$/
const PDF_NAME_CONTINUATION = /^[A-Za-z0-9#]$/
const OBJECT_STREAM_MARKER = '/ObjStm'
const ENCRYPTION_MARKER = '/Encrypt'
const DICTIONARY_OPEN = '<<'
const DICTIONARY_CLOSE = '>>'
// A name ends only at white space or a delimiter (ISO 32000-1 §7.2.2):
// every other character, `-`, `_` and `.` included, continues it, so
// `/Pages-Template` is another name, not the page tree (the review of PR #42).
const PAGES_TYPE = /\/Type\s*\/Pages(?=[\0\t\n\f\r ()<>[\]{}/%]|$)/g
// A signed object number may name the real Pages tree while a visible direct
// tree is an unlinked decoy. Fail closed rather than trusting the decoy.
const INDIRECT_TYPE_CANDIDATE = /\/Type\s+[+-]?\d+(?![A-Za-z0-9])/
const COUNT_VALUE = /^\s+(\d+)(?![A-Za-z0-9])/
const PDF_COMMENT_CANDIDATE = /\/(?:Type|Count)/g
const PDF_WHITESPACE = ' \t\r\n\f\0'

/** A bounded parse of a PDF name that may encode one or more bytes as `#HH`. */
function escapedNameAt(text: string, slash: number): string | undefined {
  let cursor = slash + 1
  let name = ''
  let hasEscape = false
  while (name.length <= PDF_CRITICAL_NAME_MAX_LENGTH) {
    const character = text[cursor]
    if (character === '#') {
      const hex = text.slice(cursor + 1, cursor + PDF_NAME_ESCAPE_SOURCE_CHARS)
      if (!PDF_NAME_HEX_PAIR.test(hex)) {
        return undefined
      }
      name += String.fromCodePoint(Number.parseInt(hex, PDF_NAME_ESCAPE_RADIX))
      cursor += PDF_NAME_ESCAPE_SOURCE_CHARS
      hasEscape = true
    } else if (character !== undefined && PDF_NAME_LETTER.test(character)) {
      name += character
      cursor += 1
    } else {
      break
    }
  }
  return hasEscape &&
    !PDF_NAME_CONTINUATION.test(text[cursor] ?? '') &&
    PDF_CRITICAL_NAMES.has(name.toLowerCase())
    ? name
    : undefined
}

/** Too many `#` bytes are ambiguous too; inspection work stays bounded. */
function hasEscapedCriticalName(text: string): boolean {
  let inspected = 0
  for (let hash = text.indexOf('#'); hash !== -1; hash = text.indexOf('#', hash + 1)) {
    inspected += 1
    if (inspected > PDF_PAGE_TREE_SCAN_LIMIT) {
      return true
    }
    const floor = Math.max(0, hash - PDF_CRITICAL_NAME_SOURCE_MAX_LENGTH)
    const before = text.slice(floor, hash)
    const relativeSlash = before.lastIndexOf('/')
    if (relativeSlash !== -1 && escapedNameAt(text, floor + relativeSlash) !== undefined) {
      return true
    }
  }
  return false
}

/** A comment or excessive whitespace after a critical name may hide the real tree. */
function hasAmbiguousCommentGap(text: string): boolean {
  let inspected = 0
  for (const match of text.matchAll(PDF_COMMENT_CANDIDATE)) {
    inspected += 1
    if (inspected > PDF_PAGE_TREE_SCAN_LIMIT) {
      return true
    }
    let cursor = match.index + match[0].length
    let character = text[cursor]
    while (
      character !== undefined &&
      PDF_WHITESPACE.includes(character) &&
      cursor - match.index < PDF_DICTIONARY_SCAN_CHARS
    ) {
      cursor += 1
      character = text[cursor]
    }
    if (character === '%' || cursor - match.index >= PDF_DICTIONARY_SCAN_CHARS) {
      return true
    }
  }
  return false
}

function latin1(bytes: Uint8Array): string {
  return Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength).toString('latin1')
}

/** Whether the bytes are a PDF: its header within the first 1024 bytes. */
export function isPdf(bytes: Uint8Array): boolean {
  return hasPdfHeader(bytes)
}

/** Where the dictionary around `index` opens, looking back at most the scan window. */
function dictionaryStart(text: string, index: number): number | undefined {
  const floor = Math.max(index - PDF_DICTIONARY_SCAN_CHARS, 0)
  let depth = 0
  let at = index - DICTIONARY_OPEN.length
  while (at >= floor) {
    if (text.startsWith(DICTIONARY_CLOSE, at)) {
      depth += 1
      // A delimiter pair is two characters: the next one ends before it.
      at -= DICTIONARY_CLOSE.length
    } else if (text.startsWith(DICTIONARY_OPEN, at)) {
      if (depth === 0) {
        return at
      }
      depth -= 1
      at -= DICTIONARY_OPEN.length
    } else {
      at -= 1
    }
  }
  return undefined
}

/** Where the dictionary opening at `start` closes (just past its `>>`), within the scan window. */
function dictionaryEnd(text: string, start: number): number | undefined {
  const ceiling = Math.min(start + PDF_DICTIONARY_SCAN_CHARS, text.length)
  let depth = 0
  let at = start
  while (at < ceiling) {
    if (text.startsWith(DICTIONARY_OPEN, at)) {
      depth += 1
      at += DICTIONARY_OPEN.length
    } else if (text.startsWith(DICTIONARY_CLOSE, at)) {
      depth -= 1
      at += DICTIONARY_CLOSE.length
      if (depth === 0) {
        return at
      }
    } else {
      at += 1
    }
  }
  return undefined
}

/** The dictionary that holds `index`, with where it ends; undefined when none is found. */
function enclosingDictionary(
  text: string,
  index: number,
): { readonly body: string; readonly end: number } | undefined {
  const start = dictionaryStart(text, index)
  const end = start === undefined ? undefined : dictionaryEnd(text, start)
  return start === undefined || end === undefined
    ? undefined
    : { body: text.slice(start, end), end }
}

/** Just past a literal string, including nested parentheses and escapes. */
function afterString(body: string, start: number): number {
  let depth = 1
  let at = start + 1
  while (at < body.length && depth > 0) {
    if (body[at] === '\\') {
      at += 2
      continue
    }
    if (body[at] === '(') {
      depth += 1
      at += 1
      continue
    }
    if (body[at] === ')') {
      depth -= 1
      at += 1
      continue
    }
    at += 1
  }
  return at
}

/** A `/Count` at this dictionary's own depth, not one in a nested value. */
function directCount(body: string): number | undefined {
  let dictionaryDepth = 0
  let arrayDepth = 0
  let at = 0
  while (at < body.length) {
    if (body.startsWith(DICTIONARY_OPEN, at)) {
      dictionaryDepth += 1
      at += DICTIONARY_OPEN.length
      continue
    }
    if (body.startsWith(DICTIONARY_CLOSE, at)) {
      dictionaryDepth -= 1
      at += DICTIONARY_CLOSE.length
      continue
    }
    if (body[at] === '%') {
      while (at < body.length && body[at] !== '\n' && body[at] !== '\r') {
        at += 1
      }
      continue
    }
    if (body[at] === '(') {
      at = afterString(body, at)
      continue
    }
    if (body[at] === '[') {
      arrayDepth += 1
      at += 1
      continue
    }
    if (body[at] === ']') {
      arrayDepth -= 1
      at += 1
      continue
    }
    if (dictionaryDepth === 1 && arrayDepth === 0 && body.startsWith('/Count', at)) {
      const value = COUNT_VALUE.exec(body.slice(at + '/Count'.length))
      if (value !== null) {
        // A direct integer ends at the next key or dictionary close. A later
        // number can be the generation of an indirect reference (`5 0 R`),
        // not a page count; comments here are ambiguous too.
        const following = body.slice(at + '/Count'.length + value[0].length).trimStart()[0]
        return following === '/' || following === '>' ? Number(value[1]) : undefined
      }
    }
    at += 1
  }
  return undefined
}

/** The largest page-tree `/Count` in the text; undefined when there is none. */
function pageTreeCount(text: string): number | undefined {
  let best: number | undefined
  let inspected = 0
  for (const match of text.matchAll(PAGES_TYPE)) {
    inspected += 1
    if (inspected > PDF_PAGE_TREE_SCAN_LIMIT) {
      return undefined
    }
    const dictionary = enclosingDictionary(text, match.index)
    const count = directCount(dictionary?.body ?? '')
    if (
      count === undefined ||
      !Number.isSafeInteger(count) ||
      count <= 0 ||
      count > PDF_PAGE_COUNT_MAX
    ) {
      return undefined
    }
    best = Math.max(best ?? 0, count)
  }
  return best
}

/** The PDF's page count, when its page tree can be read cheaply; undefined otherwise. */
export function pdfPageCount(bytes: Uint8Array): number | undefined {
  const text = latin1(bytes)
  // An object stream or encryption can hide the real Pages dictionary.
  // An unrelated visible one must not lower its budget reservation.
  const hasHiddenObjects =
    text.includes(OBJECT_STREAM_MARKER) ||
    text.includes(ENCRYPTION_MARKER) ||
    INDIRECT_TYPE_CANDIDATE.test(text) ||
    hasEscapedCriticalName(text) ||
    hasAmbiguousCommentGap(text)
  return hasHiddenObjects ? undefined : pageTreeCount(text)
}

src/core/plans/planDocument.ts:
// A saved plan as a Markdown file (M79, PLAN.md D49), after Muse Code's own
// convention: its bundled `plan` skill (Muse Code 1.4.0) saves a plan to
// `.agents/plans/YYYY-MM-DD-<slug>.md`, a short numeric suffix when that
// name is taken, and the file's content is exactly the plan's body. The
// name it gets, the body a reply holds, how a file is read back, and the
// steps that seed a new conversation's todo list. No file system, no
// `vscode`.
//
// A plan's heading and steps, and what the panel leaves out of it, need the
// panel's own Markdown parser, which loads on first use (planMarkdown.ts,
// dist/planMarkdown.js): they arrive here as a `PlanMarkdown`.

import { createHash } from 'node:crypto'
import {
  MUSE_PLAN_HANDOFF_LEAD,
  MUSE_PLAN_HANDOFF_TAIL,
  PLAN_FILE_EXTENSION,
  PLAN_LOG_HASH_CHARS,
  PLAN_SLUG_FALLBACK,
  PLAN_SLUG_MAX_CHARS,
  PLAN_STEP_MAX_CHARS,
  PLAN_STEPS_MAX,
  PLAN_TITLE_MAX_CHARS,
} from '../../shared/constants'

/** A plan read back from its file. */
export interface PlanDocument {
  /** Its first top-level heading, else its file name. */
  readonly title: string
  /** The file whole: the plan as the model wrote it. */
  readonly body: string
}

/**
 * What the panel's Markdown parser says of a plan (planMarkdown.ts), loaded
 * with dist/planMarkdown.js on the first plan action.
 */
export interface PlanMarkdown {
  /** The text of its first top-level heading as the panel shows it, if any. */
  readonly topHeading: (text: string) => string | undefined
  /** The items of its top-level numbered lists, else of its bulleted ones, each on one line. */
  readonly listItems: (body: string) => readonly string[]
  /** Whether it holds raw HTML, which the panel never renders. */
  readonly hasRawHtml: (text: string) => boolean
  /** The plan as the model gets it: what the panel showed of it, written as Markdown. */
  readonly briefText: (text: string) => string
}

/** What a plan file is written from. */
export interface PlanContent {
  /** What the file is named after. */
  readonly title: string
  readonly savedAt: Date
  /** The plan, written byte for byte. */
  readonly text: string
}

const LINE_BREAK = /\r?\n/
// "Plan", "Plan:", "Plan how to", "Implementation plan —" say nothing about the task.
const GENERIC_PLAN_LEAD = /^(?:implementation\s+)?plan\b(?:\s+how\s+to\b)?[\s:.\-–—]*/i
const WHITESPACE = /\s+/g
// Letters, their marks (Devanagari's vowel signs, Thai's tones) and digits.
const NOT_SLUG = /[^\p{L}\p{M}\p{N}]+/gu
// The accents of Latin, Greek and Cyrillic letters once decomposed; kana's
// voicing marks and Hangul's jamo are left to recompose.
const COMBINING_ACCENTS = /[\u{300}-\u{36F}]+/gu
const EDGE_HYPHENS = /^-+|-+$/g
const LEADING_BREAKS = /^(?:\r?\n)+/
const TRAILING_BREAKS = /(?:\r?\n)+$/
// A separator, a drive or stream colon, a control character (a line break
// would reach the brief unquoted) or a format character (a right-to-left
// override would disguise the name in Plans…): never part of a plan's name.
const UNSAFE_NAME_CHARACTER = /[\\/:\p{Cc}\p{Cf}]/u
// In a plan's text: a control character other than a tab or a line break
// (DEL and the C1 controls included), or a format character (a direction
// override, a zero-width character). The panel paints them, reordering or
// hiding text, while the model reads the string as it is.
const UNSHOWN_CHARACTER = /[^\P{Cc}\t\n\r]|\p{Cf}/u
// A plan file's name as the extension makes it starts with its day.
const DATED_NAME = /^(\d{4})-(\d{2})-(\d{2})(?=[-.])/
const DATE_PAD = 2
const ELLIPSIS = '…'

// Characters as the user sees them: a cut never splits a pair or a cluster.
const GRAPHEMES = new Intl.Segmenter(undefined, { granularity: 'grapheme' })

function graphemes(text: string): readonly string[] {
  return Array.from(GRAPHEMES.segment(text), (part) => part.segment)
}

function oneLine(text: string): string {
  return text.replaceAll(WHITESPACE, ' ').trim()
}

/** At most `maxChars` characters, never split, an ellipsis when cut. */
function cut(text: string, maxChars: number): string {
  const characters = graphemes(text)
  return characters.length <= maxChars
    ? text
    : `${characters
        .slice(0, maxChars - 1)
        .join('')
        .trimEnd()}${ELLIPSIS}`
}

/**
 * The plan a reply holds. A Muse Code plan reply opens and closes with its
 * `plan` skill's handoff (captured live 2026-09-27, docs/certification/m79.md):
 * the plan is what lies between, the blank lines around it dropped, and
 * nothing else changed. Any other reply is the plan whole.
 */
export function planBody(reply: string): string {
  if (!reply.startsWith(MUSE_PLAN_HANDOFF_LEAD)) {
    return reply
  }
  const inner = reply.slice(MUSE_PLAN_HANDOFF_LEAD.length).replace(LEADING_BREAKS, '')
  const withoutTail = inner.trimEnd().endsWith(MUSE_PLAN_HANDOFF_TAIL)
    ? inner.trimEnd().slice(0, -MUSE_PLAN_HANDOFF_TAIL.length)
    : inner
  const body = withoutTail.replace(TRAILING_BREAKS, '')
  return body.trim() === '' ? reply : body
}

/**
 * What a plan is named after: its top-level heading, unless that only says
 * "Plan"; else the first line of the prompt that asked for it, its "Plan how
 * to" dropped; else `fallback`.
 */
export function planTitle(
  markdown: PlanMarkdown,
  text: string,
  prompt: string | undefined,
  fallback: string,
): string {
  const heading = markdown.topHeading(text)?.replace(GENERIC_PLAN_LEAD, '').trim()
  const request = (prompt ?? '')
    .split(LINE_BREAK)
    .map((line) => oneLine(line).replace(GENERIC_PLAN_LEAD, ''))
    .find((line) => line !== '')
  const title = heading === undefined || heading === '' ? (request ?? fallback) : heading
  return cut(title, PLAN_TITLE_MAX_CHARS)
}

/**
 * The file-name form of a title: letters and digits of any script, lower
 * case, accents dropped, everything else one hyphen, cut to a length.
 */
export function planSlug(title: string): string {
  const slug = title
    .normalize('NFKD')
    .replaceAll(COMBINING_ACCENTS, '')
    .normalize('NFC')
    .toLowerCase()
    .replaceAll(NOT_SLUG, '-')
    .replaceAll(EDGE_HYPHENS, '')
  // Cut by characters: a pair cut in half would reach the disk as U+FFFD.
  const kept = graphemes(slug).slice(0, PLAN_SLUG_MAX_CHARS).join('').replaceAll(EDGE_HYPHENS, '')
  return kept === '' ? PLAN_SLUG_FALLBACK : kept
}

/** A name's leading `YYYY-MM-DD` when it is a real day, as the extension names plans. */
function datePrefix(fileName: string): string | undefined {
  const match = DATED_NAME.exec(fileName)
  const [, year = 0, month = 0, date = 0] = (match ?? []).map(Number)
  const day = new Date(Date.UTC(year, month - 1, date))
  const isRealDay = day.getUTCMonth() === month - 1 && day.getUTCDate() === date
  return match !== null && isRealDay ? match[0] : undefined
}

/**
 * How the log names a plan file: a short hash of its name, after its day
 * when the name verifiably starts with one, and nothing else of it: the rest
 * of a name is drawn from what the user or the model wrote (M39), and a file
 * someone else put in the folder may be named anything.
 */
export function planLogName(fileName: string): string {
  const hash = createHash('sha256').update(fileName).digest('hex').slice(0, PLAN_LOG_HASH_CHARS)
  const day = datePrefix(fileName)
  return `${day === undefined ? '' : `${day}-`}#${hash}${PLAN_FILE_EXTENSION}`
}

/** `2026-09-27`: the local calendar day. */
function localDay(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(DATE_PAD, '0')
  const day = String(date.getDate()).padStart(DATE_PAD, '0')
  return `${String(date.getFullYear())}-${month}-${day}`
}

/** `<date>-<slug>.md`, or `<date>-<slug>-<n>.md` from the second attempt on. */
export function planFileName(savedAt: Date, slug: string, attempt: number): string {
  const suffix = attempt <= 1 ? '' : `-${String(attempt)}`
  return `${localDay(savedAt)}-${slug}${suffix}${PLAN_FILE_EXTENSION}`
}

/** Reads a plan file back; `fileName` names it when no top-level heading does. */
export function parsePlanFile(
  markdown: PlanMarkdown,
  content: string,
  fileName: string,
): PlanDocument {
  const bareName = fileName.endsWith(PLAN_FILE_EXTENSION)
    ? fileName.slice(0, -PLAN_FILE_EXTENSION.length)
    : fileName
  return {
    title: cut(markdown.topHeading(content) ?? bareName, PLAN_TITLE_MAX_CHARS),
    body: content,
  }
}

/**
 * The plan's steps: its top-level numbered items, or, when it numbers none,
 * its top-level bullets, as the panel parses them; at most PLAN_STEPS_MAX,
 * each cut to PLAN_STEP_MAX_CHARS.
 */
export function planSteps(markdown: PlanMarkdown, body: string): readonly string[] {
  return markdown
    .listItems(body)
    .slice(0, PLAN_STEPS_MAX)
    .map((item) => cut(item, PLAN_STEP_MAX_CHARS))
}

/** The steps as numbered lines, as the model is told its todo list was set. */
export function numberedSteps(steps: readonly string[]): string {
  return steps.map((step, index) => `${String(index + 1)}. ${step}`).join('\n')
}

/**
 * Whether a plan's text holds a character the panel does not show as the
 * model reads it (see UNSHOWN_CHARACTER): such a plan is neither saved nor
 * started, as the rendered view is no longer what the model gets.
 */
export function hasUnshownCharacters(text: string): boolean {
  return UNSHOWN_CHARACTER.test(text)
}

/** Whether a name is a plan file's own: one path segment ending in `.md`. */
export function isPlanFileName(name: string): boolean {
  return (
    name.endsWith(PLAN_FILE_EXTENSION) &&
    name.length > PLAN_FILE_EXTENSION.length &&
    !name.startsWith('.') &&
    !UNSAFE_NAME_CHARACTER.test(name)
  )
}

src/core/plans/planStore.ts:
// The workspace's saved plans (M79, PLAN.md D49): `.agents/plans/*.md`.
// A save never replaces a file: it makes a new one, or finds the same plan
// already saved under one of its names. Every path is confined to the
// workspace, links and junctions resolved (PLAN.md D24), and the plans
// folder must be the workspace's own `.agents/plans`, not a link to
// somewhere else inside it. Reads are bounded. The file system is a port.

import {
  PLAN_FILE_MAX_BYTES,
  PLAN_FILE_MAX_KB,
  PLAN_LIST_MAX,
  PLAN_NAME_ATTEMPTS,
  PLANS_DIR_SEGMENTS,
  UI_TEXT,
} from '../../shared/constants'
import { fill } from '../../shared/l10n/text'
import { hasBinaryControlCharacters } from '../attachments'
import { confineWorkspacePath, type RealPathIo } from '../workspacePath'
import type { EditedFile } from '../verify/diagnosticsReport'
import type { WorkspaceEditRecorder } from '../verify/workspaceEdits'
import {
  isPlanFileName,
  type PlanContent,
  type PlanDocument,
  type PlanMarkdown,
  parsePlanFile,
  planFileName,
  planSlug,
} from './planDocument'

export interface PlanDirectoryEntry {
  readonly name: string
  /** A link or junction is `other`: never followed. */
  readonly kind: 'file' | 'directory' | 'other'
}

export interface PlanIo extends RealPathIo {
  /**
   * Publishes a new file with `content` at `absolutePath`, the checked
   * canonical target, its folder created and checked again before the file
   * appears; false when a file of that name exists already, which is left
   * as it was. Any other failure rejects.
   */
  createFile(absolutePath: string, content: string): Promise<boolean>
  /**
   * The file's bytes, read only from `expectedCanonicalPath`'s target, never
   * more than `maxBytes` whatever the file is; `bytes` is undefined when it
   * is missing or larger.
   */
  readFile(
    absolutePath: string,
    maxBytes: number,
    expectedCanonicalPath: string,
  ): Promise<{ readonly bytes: Uint8Array | undefined; readonly isPdf: boolean }>
  /** A folder's entries; none when it does not exist, a rejection when it is not a folder. */
  listEntries(absolutePath: string): Promise<readonly PlanDirectoryEntry[]>
  /** Removes the hidden stages a failed or interrupted save left in the folder, once stale. */
  removeStaleStages(absolutePath: string): Promise<void>
}

export interface PlanStoreDeps {
  readonly workspaceRoot: string
  readonly platform: NodeJS.Platform
  readonly io: PlanIo
  /**
   * The panel's Markdown parser for a plan's title (dist/planMarkdown.js,
   * loaded on first use); throws, with the reason, when it cannot load.
   */
  readonly markdown: () => PlanMarkdown
  /** Host-owned notices; only a true new-file result counts as the captured owner's edit. */
  readonly beginEdit?: (
    file: EditedFile,
    ownerRecorder: WorkspaceEditRecorder | undefined,
  ) => (wasWritten: boolean) => void
}

/** Where a saved plan landed. */
export interface SavedPlan {
  readonly fileName: string
  /** Workspace-relative, forward slashes: `.agents/plans/<file>`. */
  readonly relativePath: string
}

/** What a save did: a new file, or the same plan found saved already. */
export interface SaveOutcome extends SavedPlan {
  readonly isNew: boolean
}

/** A plan read back whole. */
export interface PlanFile extends SavedPlan {
  readonly bytes: Uint8Array
  readonly document: PlanDocument
}

/** One row of Plans…. */
export interface PlanSummary extends SavedPlan {
  readonly title: string
}

const PLANS_DIR = PLANS_DIR_SEGMENTS.join('/')

interface PlanPlace {
  readonly relativePath: string
  /** The target as the file system resolves it: what is written and read. */
  readonly checkedAbsolute: string
}

/** Case folds where the usual file systems fold it (Windows, macOS). */
function isSameRelative(left: string, right: string, platform: NodeJS.Platform): boolean {
  return platform === 'win32' || platform === 'darwin'
    ? left.toLowerCase() === right.toLowerCase()
    : left === right
}

function isSameBytes(left: Uint8Array, right: Uint8Array): boolean {
  return left.byteLength === right.byteLength && left.every((byte, index) => byte === right[index])
}

/** The refusal for a plan over the size limit, in the user's language. */
export function planTooLargeText(): string {
  return fill(UI_TEXT.planTooLarge, { size: PLAN_FILE_MAX_KB })
}

export class PlanStore {
  public constructor(private readonly deps: PlanStoreDeps) {}

  /** A path under the plans folder, confined; throws with the reason otherwise. */
  private async place(relativePath: string): Promise<PlanPlace> {
    const resolution = await confineWorkspacePath(
      this.deps.workspaceRoot,
      relativePath,
      this.deps.platform,
      this.deps.io,
    )
    if (!resolution.ok) {
      throw new Error(resolution.reason)
    }
    // `.agents` or `plans` as a link to another folder of the workspace
    // would put the plans where nobody looks for them.
    if (!isSameRelative(resolution.canonical, relativePath, this.deps.platform)) {
      throw new Error(`${PLANS_DIR} leads to ${resolution.canonical} through a link`)
    }
    return { relativePath, checkedAbsolute: resolution.checkedAbsolute }
  }

  private async planPlace(fileName: string): Promise<PlanPlace> {
    if (!isPlanFileName(fileName)) {
      throw new Error(`${fileName} is not a plan file name`)
    }
    return await this.place(`${PLANS_DIR}/${fileName}`)
  }

  /** Whether the taken name already holds exactly these bytes (the same plan saved before). */
  private async holds(fileName: string, bytes: Uint8Array): Promise<boolean> {
    try {
      const saved = await this.read(fileName)
      return isSameBytes(saved.bytes, bytes)
    } catch {
      // Unreadable (a folder of that name, too large, gone again): not this plan.
      return false
    }
  }

  /**
   * Where this plan is saved already under one of the names a save would
   * give it (the same bytes), so a second press asks nothing and writes
   * nothing; undefined when it is not.
   */
  public async find(content: PlanContent): Promise<SavedPlan | undefined> {
    const bytes = new TextEncoder().encode(content.text)
    const folder = await this.place(PLANS_DIR)
    const entries = await this.deps.io.listEntries(folder.checkedAbsolute)
    const taken = new Set(entries.map((entry) => entry.name))
    const slug = planSlug(content.title)
    for (let attempt = 1; attempt <= PLAN_NAME_ATTEMPTS; attempt += 1) {
      const fileName = planFileName(content.savedAt, slug, attempt)
      if (!taken.has(fileName)) {
        return undefined
      }
      if (await this.holds(fileName, bytes)) {
        return { fileName, relativePath: `${PLANS_DIR}/${fileName}` }
      }
    }
    return undefined
  }

  /**
   * Saves the plan byte for byte as `<date>-<slug>.md`, or the first free
   * `-<n>` after it. A name that already holds exactly this plan is the
   * plan's (saved before, from this or another panel): no second copy.
   */
  public async save(
    content: PlanContent,
    ownerRecorder?: WorkspaceEditRecorder,
  ): Promise<SaveOutcome> {
    const bytes = new TextEncoder().encode(content.text)
    if (bytes.byteLength > PLAN_FILE_MAX_BYTES) {
      throw new Error(planTooLargeText())
    }
    const folder = await this.place(PLANS_DIR)
    await this.deps.io.removeStaleStages(folder.checkedAbsolute)
    const slug = planSlug(content.title)
    for (let attempt = 1; attempt <= PLAN_NAME_ATTEMPTS; attempt += 1) {
      const fileName = planFileName(content.savedAt, slug, attempt)
      const place = await this.planPlace(fileName)
      const complete = this.deps.beginEdit?.(
        { relative: place.relativePath, absolute: place.checkedAbsolute },
        ownerRecorder,
      )
      let wasWritten = false
      try {
        wasWritten = await this.deps.io.createFile(place.checkedAbsolute, content.text)
      } finally {
        complete?.(wasWritten)
      }
      if (wasWritten) {
        return { fileName, relativePath: place.relativePath, isNew: true }
      }
      if (await this.holds(fileName, bytes)) {
        return { fileName, relativePath: place.relativePath, isNew: false }
      }
    }
    throw new Error(UI_TEXT.planNamesTaken)
  }

  /** Whether the plans folder holds this file (a regular file, not a link). */
  public async has(fileName: string): Promise<boolean> {
    const folder = await this.place(PLANS_DIR)
    const entries = await this.deps.io.listEntries(folder.checkedAbsolute)
    return entries.some((entry) => entry.kind === 'file' && entry.name === fileName)
  }

  /** A plan whole, bounded; throws with the reason when it cannot be read as one. */
  public async read(fileName: string): Promise<PlanFile> {
    const markdown = this.deps.markdown()
    const place = await this.planPlace(fileName)
    const read = await this.deps.io.readFile(
      place.checkedAbsolute,
      PLAN_FILE_MAX_BYTES,
      place.checkedAbsolute,
    )
    if (read.isPdf) {
      throw new Error(UI_TEXT.textFileInvalid)
    }
    if (read.bytes === undefined) {
      throw new Error((await this.has(fileName)) ? planTooLargeText() : UI_TEXT.planFileMissing)
    }
    // Text, as a picked text file must be (M54): the brief is written from
    // the parsed plan, which would turn a NUL into U+FFFD and pass it on.
    let text: string
    try {
      text = new TextDecoder('utf-8', { fatal: true }).decode(read.bytes)
    } catch {
      throw new Error(UI_TEXT.textFileInvalid)
    }
    if (hasBinaryControlCharacters(text)) {
      throw new Error(UI_TEXT.textFileInvalid)
    }
    return {
      fileName,
      relativePath: place.relativePath,
      bytes: read.bytes,
      document: parsePlanFile(markdown, text, fileName),
    }
  }

  /**
   * The saved plans, newest date first (a plan's name starts with the day it
   * was saved; one day's plans follow in reverse name order). One that
   * cannot be read is listed by its name.
   */
  public async list(): Promise<readonly PlanSummary[]> {
    // The parser first: a listing it cannot title is refused, not half made.
    this.deps.markdown()
    const folder = await this.place(PLANS_DIR)
    await this.deps.io.removeStaleStages(folder.checkedAbsolute)
    const entries = await this.deps.io.listEntries(folder.checkedAbsolute)
    const names = entries
      .filter((entry) => entry.kind === 'file' && isPlanFileName(entry.name))
      .map((entry) => entry.name)
      .toSorted((left, right) => right.localeCompare(left))
      .slice(0, PLAN_LIST_MAX)
    const summaries: PlanSummary[] = []
    for (const fileName of names) {
      const relativePath = `${PLANS_DIR}/${fileName}`
      let title = fileName
      try {
        const plan = await this.read(fileName)
        title = plan.document.title
      } catch {
        // Listed by its name: opening or implementing it says why it cannot be read.
      }
      summaries.push({ fileName, relativePath, title })
    }
    return summaries
  }
}

src/core/protectedPaths.ts:
// Protected writes (PLAN.md D24): a file that configures or runs code
// outside the edit itself (git's hooks and config, the editor's tasks, CI
// workflows, the agent's own rules and skills). The Model API's permission
// engine asks before writing one; the conversation controller refuses one
// as a picked text file (M54). Apart from the engine so the activation
// bundle carries only this (M57, PLAN.md D6).

import { PROTECTED_FILE_NAMES, PROTECTED_PATH_SEGMENTS } from '../shared/constants'

/**
 * Whether a workspace-relative path (forward slashes, links resolved) is a
 * protected write. Case is ignored: Windows and macOS file systems fold it.
 */
export function isProtectedPath(canonicalRelative: string): boolean {
  const segments = canonicalRelative.toLowerCase().split('/')
  const name = segments.at(-1) ?? ''
  if (PROTECTED_FILE_NAMES.has(name)) {
    return true
  }
  // The run may sit anywhere (a nested repository's `.git`) and may be the
  // file itself (a `.git` file points git at another directory).
  return segments.some((_segment, index) =>
    PROTECTED_PATH_SEGMENTS.some(
      (protectedSegments) =>
        protectedSegments.length <= segments.length - index &&
        protectedSegments.every((part, offset) => segments[index + offset] === part),
    ),
  )
}

src/core/redact.ts:
// Secret redaction for anything that reaches a log, and for a session export
// (M84), which adds only the key digest. Pure; no `vscode` import. This is
// the one list of credential shapes the extension knows: a secret in any
// other shape is not recognised.
//
// Patterns cover the credential shapes this extension can encounter:
//   - Meta Model API keys: `LLM_` and at least 16 of `[A-Za-z0-9_-]` (the
//     current shape), or the older `LLM|<numeric id>|<secret>`; the same
//     shapes `MODEL_API_KEY_PATTERN` accepts
//   - HTTP bearer and basic credentials: `Bearer <token>`, `Basic <base64>`
//   - JSON Web Tokens (the CLI's OAuth access tokens are JWT-shaped):
//     three base64url parts, the first two starting `eyJ`, redacted from
//     the first `eyJ` on whatever is glued before it (`x-`, `x_`, `abc`)
//   - Environment assignments of the known key variables: `META_API_KEY=...`,
//     `MODEL_API_KEY=...`
//   - Token and secret fields in JSON, query strings or `key=value` text:
//     `access_token`, `refresh_token`, `id_token`, `client_secret`,
//     `api_key` / `apikey`, `password`
//   - Credentials in a URL's user-info part: `https://user:secret@host`
//   - Common services' keys and tokens, wherever they appear (a tool's
//     output, `cat .env`, a config file): a PEM private key; GitHub, GitLab,
//     npm and Google API tokens; AWS access key ids; Slack tokens; `sk-` and
//     `sk_live_` style API keys
//   - Secrets named by their key, the value replaced and the name kept: an
//     upper-case environment name that says so (`GITHUB_TOKEN=`), an
//     `api-key` header, `Authorization: token …`, a quoted JSON field, a URL
//     parameter, `~/.aws/credentials` lines in any case, an Azure connection
//     string's `AccountKey=`, and `.npmrc`'s `_authToken=`
//
// Every pattern scans in linear time (no nested quantifiers; each run is
// bounded or anchored on a literal): the session export runs them over
// whole conversations, and a crafted import file's text reaches the log.
// Replacements are functions, not strings, so no `$` sequence in the mark is
// interpreted (unicorn/no-unsafe-string-replacement).

import { REDACTED_MARK } from '../shared/constants'

/** The mark alone, in place of the whole match. */
function mark(): string {
  return REDACTED_MARK
}

/** The mark after the match's first group (the field name or scheme it follows). */
function markAfter(_match: string, lead: string): string {
  return `${lead}${REDACTED_MARK}`
}

/** A quoted value: its name and both quotes stay. */
function markQuoted(_match: string, lead: string, quote: string): string {
  return `${lead}${quote}${REDACTED_MARK}${quote}`
}

/** URL user-info: the scheme and the `@` stay. */
function markUserInfo(_match: string, lead: string): string {
  return `${lead}${REDACTED_MARK}@`
}

// A token's first two parts are base64url JSON, which starts `{"`.
const TOKEN_HEAD = 'eyJ'

function isTokenPayload(part: string | undefined): boolean {
  return part !== undefined && part.startsWith(TOKEN_HEAD) && part.length > TOKEN_HEAD.length
}

/**
 * `words` (three or more dotted words) with every token in it redacted: a
 * word holding `eyJ` and more, then a word starting `eyJ` and more, then any
 * word. A token is redacted from its first `eyJ` through its third word;
 * tokens that share a word are one redaction. Words without `eyJ` come back
 * as they were.
 */
function redactTokens(words: string): string {
  if (!words.includes(TOKEN_HEAD)) {
    return words
  }
  const parts = words.split('.')
  const kept: string[] = []
  // The index of the last part inside a token found so far.
  let redactedThrough = -1
  for (const [index, part] of parts.entries()) {
    const head = part.indexOf(TOKEN_HEAD)
    const isTokenStart =
      head !== -1 &&
      head + TOKEN_HEAD.length < part.length &&
      index + 2 < parts.length &&
      isTokenPayload(parts[index + 1])
    if (index > redactedThrough) {
      kept.push(isTokenStart ? `${part.slice(0, head)}${REDACTED_MARK}` : part)
    }
    if (isTokenStart) {
      redactedThrough = index + 2
    }
  }
  return kept.join('.')
}

/** One credential shape, applied in list order. */
export interface SecretRule {
  readonly pattern: RegExp
  /**
   * Lower case; every match of `pattern` that `replace` changes holds at
   * least one of these, case ignored. `MAY_HOLD_SECRET` must find each, or
   * the pattern never runs: redact.test.ts checks both against real-shaped
   * matches.
   */
  readonly literals: readonly string[]
  readonly replace: (match: string, lead: string, quote: string) => string
}

// The fields `QUOTED_SECRET_FIELD` and `SECRET_FIELD` name.
const SECRET_FIELD_LITERALS = ['token', 'secret', 'apikey', 'api_key', 'password']
// A PEM private key, its body to the END line. The one rule whose match runs
// on over line breaks other than in the white space after a name, `=` or `:`
// (`redactableSlices` relies on that).
const PEM_PRIVATE_KEY =
  /-----BEGIN [A-Z0-9 ]{0,40}PRIVATE KEY-----[A-Za-z0-9+/=\s]*(?:-----END [A-Z0-9 ]{0,40}PRIVATE KEY-----)?/g

export const SECRET_RULES: readonly SecretRule[] = [
  // Meta Model API keys.
  { pattern: /LLM_[\w-]{16,}|LLM\|\d+\|[\w+./=-]+/g, literals: ['llm'], replace: mark },
  { pattern: /(\bBearer\s+)[\w+./=~-]+/gi, literals: ['bearer'], replace: markAfter },
  { pattern: /(\bBasic\s+)[\w+/=]{8,}/gi, literals: ['basic'], replace: markAfter },
  // JSON Web Tokens, inside three or more words joined by dots, matched
  // whole. The lookbehind lets a match start only where a word starts, so a
  // long word is not read again from each of its characters; the tokens are
  // then found inside the match (`redactTokens`), so one glued after a dash,
  // an underscore or a letter is still found. Matched from each `eyJ`
  // instead (`\beyJ[\w-]+\.eyJ[\w-]+\.[\w-]+`), the rest of the word was read
  // again from every `eyJ` in it: quadratic, seconds for a 64,000-character
  // line of `eyJa-eyJa-…`.
  {
    pattern: /(?<![\w-])[\w-]+(?:\.[\w-]+){2,}/g,
    literals: ['eyj'],
    replace: (words) => redactTokens(words),
  },
  // The known key variables.
  { pattern: /((?:META|MODEL)_API_KEY\s*=\s*)\S+/g, literals: ['api_key'], replace: markAfter },
  {
    pattern:
      /((?:access_token|refresh_token|id_token|client_secret|api_?key|password)["']?\s*[:=]\s*)(["'])(?:\\.|[^\r\n\\])*?\2/gi,
    literals: SECRET_FIELD_LITERALS,
    replace: markQuoted,
  },
  {
    pattern:
      /((?:access_token|refresh_token|id_token|client_secret|api_?key|password)["']?\s*[:=]\s*["']?)[^\s"'&,;}]+/gi,
    literals: SECRET_FIELD_LITERALS,
    replace: markAfter,
  },
  // Credentials in a URL. The scheme is bounded (real ones are a few
  // letters): unbounded, a long run such as `a.b.c.…` took quadratic time.
  {
    pattern: /(\b[a-z][\w+.-]{0,31}:\/\/)[^\s/@:]+:[^\s/@]+@/gi,
    literals: ['://'],
    replace: markUserInfo,
  },
  // Whole tokens, recognised by their shape and replaced entirely. A PEM
  // private key, its body to the END line:
  { pattern: PEM_PRIVATE_KEY, literals: ['private key'], replace: mark },
  // GitHub tokens, GitLab personal access tokens, npm tokens.
  {
    pattern: /\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_\w{20,})/g,
    literals: ['ghp_', 'gho_', 'ghu_', 'ghs_', 'ghr_', 'github_pat_'],
    replace: mark,
  },
  { pattern: /\bglpat-[\w-]{20,255}/g, literals: ['glpat-'], replace: mark },
  { pattern: /\bnpm_[A-Za-z0-9]{36,255}/g, literals: ['npm_'], replace: mark },
  // Google API keys: `AIza` and 35 more.
  { pattern: /\bAIza[\w-]{35}/g, literals: ['aiza'], replace: mark },
  // AWS access key ids, Slack tokens, and `sk-` / `sk_live_` style API keys.
  { pattern: /\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/g, literals: ['akia', 'asia'], replace: mark },
  { pattern: /\bxox[abposr]-[A-Za-z0-9-]{10,}/g, literals: ['xox'], replace: mark },
  {
    pattern: /\b(?:sk|rk|pk)_(?:live|test)_[A-Za-z0-9]{16,255}|\bsk-[\w-]{20,255}/g,
    literals: ['_live_', '_test_', 'sk-'],
    replace: mark,
  },
  // Secrets named by their key: the value after the name is replaced, the
  // name stays. This one is upper case only, so ordinary words
  // (`inputTokens: 12`) keep their values; the AWS file's lower-case names
  // have their own pattern.
  {
    pattern:
      /(\b[A-Z][A-Z0-9_]{0,60}(?:SECRET|TOKEN|PASSWORD|PASSWD|API_KEY|APIKEY|ACCESS_KEY|PRIVATE_KEY|CREDENTIALS?)[A-Z0-9_]{0,60}\s{0,5}[=:]\s{0,5}["']?)[^\s"'&,;}]{1,4096}/g,
    literals: [
      'secret',
      'token',
      'passw',
      'api_key',
      'apikey',
      'access_key',
      'private_key',
      'credential',
    ],
    replace: markAfter,
  },
  {
    pattern:
      /(\baws_(?:secret_access_key|session_token)\s{0,5}[=:]\s{0,5}["']?)[^\s"'&,;}]{1,4096}/gi,
    literals: ['aws_secret_access_key', 'aws_session_token'],
    replace: markAfter,
  },
  {
    pattern: /(\b(?:Account|SharedAccess)Key\s{0,5}=\s{0,5})[^\s"';]{1,4096}/gi,
    literals: ['accountkey', 'sharedaccesskey'],
    replace: markAfter,
  },
  // Not after a dot or a word character, so code's `self._auth = …` stays.
  {
    pattern: /(?<![\w.])(_auth(?:Token)?\s{0,5}=\s{0,5}["']?)[^\s"'&,;}]{1,4096}/gi,
    literals: ['_auth'],
    replace: markAfter,
  },
  {
    pattern: /(\b(?:x-)?api-key\s{0,5}[:=]\s{0,5}["']?)[^\s"'&,;}]{1,4096}/gi,
    literals: ['api-key'],
    replace: markAfter,
  },
  {
    pattern: /(\bAuthorization\s{0,5}:\s{0,5}token\s{1,5})[^\s"'&,;}]{1,4096}/gi,
    literals: ['token'],
    replace: markAfter,
  },
  {
    pattern:
      /(["'][\w-]{0,40}(?:token|secret|passw(?:or)?d|api[_-]?key|private[_-]?key)["']\s{0,5}:\s{0,5}["'])[^"'\r\n]{1,4096}/gi,
    literals: [
      'token',
      'secret',
      'passw',
      'apikey',
      'api_key',
      'api-key',
      'privatekey',
      'private_key',
      'private-key',
    ],
    replace: markAfter,
  },
  {
    pattern: /([?&](?:token|key|secret|sig|signature|auth)=)[^&#\s"']{1,4096}/gi,
    literals: [
      'token',
      'secret',
      '?key=',
      '&key=',
      '?sig=',
      '&sig=',
      '?signature=',
      '&signature=',
      '?auth=',
      '&auth=',
    ],
    replace: markAfter,
  },
]

// Every rule's literals, case ignored: text with none of them, which is most
// of a conversation and most log lines, skips all the patterns in one linear
// scan instead of one scan each (RV84 #9). Kept as a literal pattern; a rule
// whose literal this misses would never run, so redact.test.ts proves it
// finds every rule's literals and every rule's real-shaped matches.
export const MAY_HOLD_SECRET =
  /LLM|bearer|basic|eyJ|token|secret|passw|api_?key|api-key|private|credential|access_?key|accountkey|_auth|aws_|:\/\/|gh[pousr]_|github_pat_|glpat-|npm_|AIza|AKIA|ASIA|xox|_live_|_test_|sk-|[?&](?:key|sig|signature|auth)=/i

function redactPatterns(text: string, matched?: () => void): string {
  if (!MAY_HOLD_SECRET.test(text)) {
    return text
  }
  let result = text
  for (const rule of SECRET_RULES) {
    // A function, so no `$` sequence in the mark is interpreted.
    result = result.replaceAll(rule.pattern, (match: string, lead: string, quote: string) => {
      const replacement = rule.replace(match, lead, quote)
      if (replacement !== match) {
        matched?.()
      }
      return replacement
    })
  }
  return result
}

/**
 * The forms of one exact literal that literal-first redaction replaces (M80,
 * SPEC §4.2): the literal, its percent-encoded form, and what a pattern-only
 * pass leaves of it. Text that an earlier step already redacted by pattern
 * alone (a network error's description) still carries that residue, such as a
 * legacy key's tail after the `%` its pattern stops at.
 */
function literalForms(literal: string): string[] {
  const forms = [literal]
  try {
    forms.push(encodeURIComponent(literal))
  } catch {
    // A lone surrogate has no encoded form; the literal itself still applies.
  }
  const residue = redactPatterns(literal)
  if (residue !== literal && residue !== REDACTED_MARK) {
    forms.push(residue)
  }
  return forms
}

function redactWith(text: string, literals: readonly string[], matched?: () => void): string {
  let result = text
  const ordered = [
    ...new Set(literals.filter((value) => value !== '').flatMap((value) => literalForms(value))),
  ].toSorted((a, b) => b.length - a.length)
  for (const literal of ordered) {
    result = result.replaceAll(literal, () => {
      matched?.()
      return REDACTED_MARK
    })
  }
  return redactPatterns(result, matched)
}

/** Exact run keys precede patterns, including legacy keys containing percent signs. */
export function redactSecrets(text: string, literals: readonly string[] = []): string {
  return redactWith(text, literals)
}

/** Counts only changed, nonoverlapping matches in the same order as redaction. */
export function countSecretMatches(text: string, literals: readonly string[]): number {
  let count = 0
  redactWith(text, literals, () => {
    count += 1
  })
  return count
}

// --- Long text in slices (RV84 #9) ---
//
// A rule's match holds a line break only in the white space after a name, an
// `=` or a `:` (`Bearer\n  token`, `"password":\n  "…"`), or in a PEM key's
// body. So text cut just after a line break redacts piece by piece as it
// does whole, unless the last word before the break could start such a
// match: one holding a rule's literal (`MAY_HOLD_SECRET`), ending in `=` or
// `:`, or `Authorization` (whose rule has no literal of its own before its
// colon); or unless the break is inside a PEM key. Every lookbehind and `\b`
// reads a line break as it reads the start of the text, so a piece's edges
// change no match. redact.test.ts checks this against every rule.

const LINE_BREAK = '\n'
const WHITESPACE = /\s/
const OPEN_WORD_END = /(?:[=:]|authorization)$/i
// A rule's name before the white space runs at most this long (an
// upper-case variable: 1 + 60 + 11 + 60 characters), so a word's end is all
// that is read.
const OPEN_WORD_MAX_CHARS = 256
const PEM_START = '-----BEGIN '
const PEM_AT = new RegExp(PEM_PRIVATE_KEY.source, 'y')

/** Where the white space starting at `at` ends. */
function afterWhitespace(text: string, at: number): number {
  let end = at
  while (end < text.length && WHITESPACE.test(text.charAt(end))) {
    end += 1
  }
  return end
}

/**
 * Whether the last word before `cut`, after `from`, could start a match that
 * goes on past `cut`. Only white space since `from` (a cut already found
 * safe, or the text's start) leaves nothing open.
 */
function isWordOpen(text: string, from: number, cut: number): boolean {
  let end = cut
  while (end > from && WHITESPACE.test(text.charAt(end - 1))) {
    end -= 1
  }
  let start = end
  while (
    start > from &&
    end - start < OPEN_WORD_MAX_CHARS &&
    !WHITESPACE.test(text.charAt(start - 1))
  ) {
    start -= 1
  }
  const word = text.slice(start, end)
  return word !== '' && (MAY_HOLD_SECRET.test(word) || OPEN_WORD_END.test(word))
}

/** Where the PEM key that `cut` falls inside ends, if it falls inside one begun after `from`. */
function pemEndAround(text: string, from: number, cut: number): number | undefined {
  const start = text.lastIndexOf(PEM_START, cut - 1)
  if (start < from) {
    return undefined
  }
  PEM_AT.lastIndex = start
  const key = PEM_AT.exec(text)
  const end = key === null ? start : start + key[0].length
  return end > cut ? end : undefined
}

/**
 * The first cut at or after `target`, just after a line break, that no match
 * goes on past; undefined when there is none before the text's end.
 */
function safeCut(text: string, from: number, target: number): number | undefined {
  let at = target
  for (;;) {
    const lineBreak = text.indexOf(LINE_BREAK, at - 1)
    const cut = lineBreak + 1
    if (lineBreak === -1 || cut >= text.length) {
      return undefined
    }
    if (isWordOpen(text, from, cut)) {
      // The match may run through this white space: the next try is the
      // line after the next word.
      at = afterWhitespace(text, cut) + 1
      continue
    }
    const pemEnd = pemEndAround(text, from, cut)
    if (pemEnd === undefined) {
      return cut
    }
    at = pemEnd + 1
  }
}

/**
 * `text` in pieces of `sliceChars` or a little more, each ending just after
 * a line break that no credential goes on past, so `redactSecrets` of each
 * piece, joined, is `redactSecrets` of the whole: a long text can be redacted
 * a piece at a time, letting the event loop run between. A line longer than
 * `sliceChars` stays in one piece.
 */
export function redactableSlices(text: string, sliceChars: number): string[] {
  const slices: string[] = []
  let from = 0
  while (text.length - from > sliceChars) {
    const cut = safeCut(text, from, from + sliceChars)
    if (cut === undefined) {
      break
    }
    slices.push(text.slice(from, cut))
    from = cut
  }
  slices.push(text.slice(from))
  return slices
}

src/core/sessionBoard.ts:
// The session board's rows (M77, PLAN.md D49): every conversation in the
// window joined with its worktree, on either backend. Pure: the host
// collects sessions, worktrees, pending approvals and change counts.
//
// A conversation with no worktree still gets a row: the board shows every
// conversation, not only ones in a worktree.

import { sessionTitle } from '../shared/sessions'
import type { BoardRow } from '../shared/sessionBoard'
import { isSameFolder, type WorktreeEntry } from './worktrees'

/** One conversation the window knows, on either backend. */
export interface BoardSession {
  readonly sessionId: string
  readonly name?: string | undefined
  readonly title?: string | undefined
  readonly firstUserPrompt?: string | undefined
  readonly backend: BoardRow['backend']
  readonly status: BoardRow['status']
  /** The git branch the backend names for the conversation, when it does. */
  readonly branch?: string | undefined
  /**
   * Where the conversation runs: an attempt's worktree, or the window's own
   * checkout. Matches a worktree entry by folder first, then by branch.
   */
  readonly workspaceRoot?: string | undefined
}

/** One worktree with its change count, when git could say it. */
export interface BoardWorktree {
  readonly entry: WorktreeEntry
  readonly changedFiles?: number | undefined
}

export interface SessionBoardInput {
  readonly sessions: readonly BoardSession[]
  readonly worktrees: readonly BoardWorktree[]
  /** Conversations with an approval card or question waiting on the user. */
  readonly approvalsPending: ReadonlySet<string>
  readonly platform: NodeJS.Platform
}

function worktreeOf(
  session: BoardSession,
  worktrees: readonly BoardWorktree[],
  platform: NodeJS.Platform,
): BoardWorktree | undefined {
  const root = session.workspaceRoot
  if (root !== undefined) {
    const byFolder = worktrees.find((candidate) =>
      isSameFolder(candidate.entry.path, root, platform),
    )
    if (byFolder !== undefined) {
      return byFolder
    }
  }
  return session.branch === undefined
    ? undefined
    : worktrees.find(
        (candidate) => candidate.entry.branch === session.branch && !candidate.entry.isDetached,
      )
}

/**
 * Approvals and questions waiting on the user, window-wide (M77): every
 * surface's controller tracks its own session's prompts here, so the board
 * marks a conversation awaiting approval whatever surface raised its card.
 * Entries are prompt ids, so a replayed card never counts twice; a closed
 * session drops its entry, and a dropped host clears them all.
 */
export class PendingPrompts {
  private readonly pending = new Map<string, Set<string>>()

  /** An approval card or question now waits in this conversation. */
  public track(sessionId: string, promptId: string): void {
    let ids = this.pending.get(sessionId)
    if (ids === undefined) {
      ids = new Set()
      this.pending.set(sessionId, ids)
    }
    ids.add(promptId)
  }

  /** The prompt settled or its card went away. */
  public resolve(sessionId: string, promptId: string): void {
    const ids = this.pending.get(sessionId)
    if (ids === undefined) {
      return
    }
    ids.delete(promptId)
    if (ids.size === 0) {
      this.pending.delete(sessionId)
    }
  }

  /** The session closed: nothing in it can pend any more. */
  public drop(sessionId: string): void {
    this.pending.delete(sessionId)
  }

  /** The host went away: no tracked card can still wait on it. */
  public clear(): void {
    this.pending.clear()
  }

  /** Every conversation with a prompt waiting, for the board. */
  public pendingSessionIds(): ReadonlySet<string> {
    return new Set(this.pending.keys())
  }
}

function rankOf(status: BoardRow['status'], isAwaitingApproval: boolean): number {
  if (status === 'running') {
    return 0
  }
  return isAwaitingApproval ? 1 : 2
}

/** Every conversation as one board row: running first, then waiting, then the rest. */
export function buildSessionBoard(input: SessionBoardInput): readonly BoardRow[] {
  const rows = input.sessions.map((session): BoardRow => {
    const worktree = worktreeOf(session, input.worktrees, input.platform)
    return {
      sessionId: session.sessionId,
      title: sessionTitle(session),
      backend: session.backend,
      status: session.status,
      ...(session.branch !== undefined && { branch: session.branch }),
      ...(worktree !== undefined && { worktreePath: worktree.entry.path }),
      ...(worktree?.changedFiles !== undefined && { changedFiles: worktree.changedFiles }),
      awaitingApproval: input.approvalsPending.has(session.sessionId),
    }
  })
  return rows.toSorted((a, b) => {
    const rank = rankOf(a.status, a.awaitingApproval) - rankOf(b.status, b.awaitingApproval)
    if (rank !== 0) {
      return rank
    }
    if (a.title !== b.title) {
      return a.title < b.title ? -1 : 1
    }
    if (a.sessionId === b.sessionId) {
      return 0
    }
    return a.sessionId < b.sessionId ? -1 : 1
  })
}

src/core/shellQuote.ts:
// Quoting one value as one argument for the two shells the extension types
// into (M31): Windows PowerShell (the job helper's scripts, M27, and the
// Windows terminals) and `/bin/sh` (the terminals elsewhere).
//
// PowerShell treats the typographic single quotes U+2018 to U+201B as quote
// characters too, so inside a single-quoted string each of them, like `'`,
// is doubled; a value such as `C:\Users\O’Brien` otherwise ends the string
// early (about_Quoting_Rules). `/bin/sh` has no escape inside single quotes,
// so a `'` closes the string, is written escaped, and reopens it.

const POWERSHELL_SINGLE_QUOTES = /['\u{2018}-\u{201B}]/gu
const POSIX_SINGLE_QUOTE = "'"
const POSIX_ESCAPED_QUOTE = String.raw`'\''`

/** A PowerShell single-quoted string holding exactly `text`. */
export function powerShellQuoted(text: string): string {
  return `'${text.replaceAll(POWERSHELL_SINGLE_QUOTES, (quote) => `${quote}${quote}`)}'`
}

/** A `/bin/sh` single-quoted word holding exactly `text`. */
export function posixQuoted(text: string): string {
  // A function, so nothing in the replacement is read as a `$` pattern.
  return `'${text.replaceAll(POSIX_SINGLE_QUOTE, () => POSIX_ESCAPED_QUOTE)}'`
}

/** One argument for the terminal shell the extension pins on this platform. */
export function terminalArgument(text: string, platform: NodeJS.Platform): string {
  return platform === 'win32' ? powerShellQuoted(text) : posixQuoted(text)
}

src/core/shellResult.ts:
// Shared process result only: eager host adapters must not load the Model API tools bundle.

export interface ShellResult {
  /** Local caller admission refused before native entry; never inferred from output or cancellation. */
  readonly isEntryRefused?: true
  /**
   * Locally owned process provenance only: no workspace-capable process exists
   * that could outlive the result. Only a command that could not start
   * (`unstartedShell`) or was refused before entry carries it; a launched
   * command never does, and exit code/pipe close/drain never qualify. Never
   * read this from model/MSP data.
   */
  readonly isWorkspaceShutdownProven?: true
  readonly stdout: string
  readonly stderr: string
  readonly exitCode: number | null
  readonly isTimedOut: boolean
  /** Stopped because the turn was (the Stop button, PLAN.md D25). */
  readonly isCancelled: boolean
  /** The command exceeded its per-stream byte budget (M51 hooks). */
  readonly isOutputTooLarge?: boolean
}

/**
 * A command that could not start at all (no interpreter, no program): the
 * failure stays the caller's to report, and only this local fact, never a
 * normal exit, proves no process exists to outlive it.
 */
export function unstartedShell(stderr: string): ShellResult {
  return {
    stdout: '',
    stderr,
    exitCode: null,
    isTimedOut: false,
    isCancelled: false,
    isWorkspaceShutdownProven: true,
  }
}

/**
 * A failure before the command could enter (the checkpoint could not be
 * marked): no process exists and nothing ran, so a caller that would tell the
 * model what the user ran stays silent. Only a failure AFTER the command ran
 * is a plain Error.
 */
export class ShellEntryError extends Error {}

/** Proven no-entry outcome from a local caller guard, separate from a stopped running process. */
export function refusedShellEntry(): ShellResult {
  return {
    stdout: '',
    stderr: '',
    exitCode: null,
    isTimedOut: false,
    isCancelled: true,
    isWorkspaceShutdownProven: true,
    isEntryRefused: true,
  }
}

src/core/support/report.ts:
// The "Muse Spark: Diagnostics" report (PLAN.md D14): the facts a bug
// report needs, as text for the log channel. Pure: the host gathers the
// facts. Nothing secret is ever in it: credentials appear as booleans or,
// for the CLI's credential file, as one word for its structure (D26),
// environment variables as a count, the home directory as `~` (PLAN.md
// D24: the report is meant to be pasted into a public issue), and the
// logger redacts on top. The network posture (M56, PLAN.md D43) is stated
// the same way: whether a proxy is set, never its address, which can hold
// a password; and `muse config status` contributes only known-safe fields.

import {
  MUSE_CONFIG_STATUS_MAX_CHARS,
  MUSE_KEYCHAIN_SERVICE,
  PRODUCT_NAME,
  VSCODE_WEBSOCKET_ROUTED_SINCE,
} from '../../shared/constants'
import type {
  CliSignIn,
  CredentialFileVerdict,
  KeychainItemPresence,
} from '../backends/musecode/credentialFile'

/**
 * Whether the editor's extension host installed its proxy-aware version of a
 * global (M62): `absent` when the host has no such global at all, as Node 20
 * (VS Code 1.99 and 1.100) has no WebSocket.
 */
export type HostRouting = 'routed' | 'notRouted' | 'absent'

/**
 * The network the extension's own requests and Muse Code's run under (M56).
 * The extension's `fetch` and WebSocket go through VS Code's proxy support
 * and system certificates where the editor routes them and VS Code's
 * settings allow it.
 */
export interface NetworkFacts {
  /** `http.proxy` is set; its value is not shown. */
  readonly isProxySet: boolean
  /** `http.proxySupport`: `off`, `on`, `fallback` or `override`. */
  readonly proxySupport: string
  readonly isProxyStrictSsl: boolean
  readonly isProxyAuthorizationSet: boolean
  readonly noProxyCount: number
  readonly isSystemCertificatesOn: boolean
  /** `http.fetchAdditionalSupport` and `http.webSocketAdditionalSupport`. */
  readonly isFetchSupportOn: boolean
  readonly isWebSocketSupportOn: boolean
  /** Whether this editor routes each global at all; the settings above matter only then (M62). */
  readonly fetchRouting: HostRouting
  readonly webSocketRouting: HostRouting
  /** HTTPS_PROXY / HTTP_PROXY in the extension host's environment, in either case. */
  readonly hasEnvironmentProxy: boolean
  /** NODE_EXTRA_CA_CERTS names extra roots for the extension host. */
  readonly hasExtraCaCertificates: boolean
  /** Where `muse serve` gets its proxy. */
  readonly museProxySource: 'environment' | 'vscode' | 'none'
  /** SSL_CERT_FILE or SSL_CERT_DIR replaces the system store for `muse serve`. */
  readonly hasMuseCertificateOverride: boolean
}

export interface SupportFacts {
  readonly extensionVersion: string
  readonly vscodeVersion: string
  readonly nodeVersion: string
  readonly platform: string
  readonly arch: string
  /** `vscode.env.remoteName`; undefined on a local window. */
  readonly remoteName: string | undefined
  readonly hasWorkspace: boolean
  readonly isWorkspaceTrusted: boolean
  readonly backendSetting: string
  readonly shellSandboxSetting: string
  readonly shellSandboxPosture: string
  /** `museSpark.sandboxNetwork`, and whether the next host gets it (M56). */
  readonly sandboxNetworkSetting: string
  readonly isSandboxNetworkApplied: boolean
  readonly isBinaryPathConfigured: boolean
  readonly environmentVariableCount: number
  /** The CLI's install directory and version, or why it was not found. */
  readonly cli:
    | { readonly ok: true; readonly installDir: string; readonly version: string | undefined }
    | { readonly ok: false; readonly reason: string }
  /**
   * What the CLI's credential file's structure says, never a value from it:
   * `absent`, `empty` (no sign-in), `inline` (holds one), `keychain` (a macOS
   * pointer), `unsupportedHere` (a macOS file where `muse serve` cannot
   * start with it) or `unrecognized`.
   */
  readonly cliCredentialFile: CredentialFileVerdict | 'absent'
  /** The CLI's sign-in as the gate counts it (`unknown` counts as signed in). */
  readonly cliSignIn: CliSignIn
  /** macOS only: whether the login Keychain holds the CLI's item, by attribute lookup. */
  readonly keychainItem: KeychainItemPresence | undefined
  /** Muse Code's `run.subagent_delegation_mode` as read from its settings file (M14). */
  readonly delegationMode: string
  /** Muse Code's `run.workflow_trigger_mode`, read the same way (M47). */
  readonly workflowTriggerMode: string
  readonly hasStoredApiKey: boolean
  readonly hasEnvironmentApiKey: boolean
  readonly dictation:
    { readonly isAvailable: true } | { readonly isAvailable: false; readonly reason: string }
  readonly network: NetworkFacts
  /** `muse config status` as printed, or why it could not run (M56). */
  readonly managedConfiguration:
    { readonly ok: true; readonly text: string } | { readonly ok: false; readonly reason: string }
  /** The user's home directory, shown as `~` wherever a path contains it. */
  readonly homeDir: string
}

const YES = 'yes'
const NO = 'no'
const NONE = 'none'
const UNKNOWN = 'unknown'
const HOME_ABBREVIATION = '~'
const INDENT = '  '
const TRUNCATED = '…'
const LINE_BREAK = /\r?\n/
// Diagnostics is pasted into public issues. Only captured status fields with
// fixed vocabularies are safe to copy from CLI output: a future CLI version
// may print a credential under a new key that a redaction pattern misses.
const CONFIG_GENERATION = /^Generation: sha256:[\da-f]{4,64}$/i
const CONFIG_SOURCE =
  /^plane=(defaults|policy) source_class=(system_file|windows_machine_policy) state=(absent|present|loaded|active|invalid|error)$/
const CONFIG_LINE_OMITTED = '[unrecognized status line omitted]'
const CONFIG_FAILURE = 'could not read status'
const CONFIG_EXIT_CODE = /^exit code -?\d+$/

function safeConfigLine(line: string): string {
  const trimmed = line.trim()
  if (trimmed === 'Enterprise configuration status' || trimmed === 'Sources:') {
    return `${INDENT}${trimmed}`
  }
  if (CONFIG_GENERATION.test(trimmed)) {
    return `${INDENT}${trimmed}`
  }
  return CONFIG_SOURCE.test(trimmed)
    ? `${INDENT}${INDENT}${trimmed}`
    : `${INDENT}${CONFIG_LINE_OMITTED}`
}
const MUSE_PROXY_SOURCES: Readonly<Record<NetworkFacts['museProxySource'], string>> = {
  environment: 'its environment',
  vscode: 'VS Code’s http.proxy',
  none: NONE,
}

function yesNo(isTrue: boolean): string {
  return isTrue ? YES : NO
}

/**
 * A global's route: its setting where the editor routes it, and otherwise
 * why not, so the report never claims a proxy the request does not use (M62).
 */
function routeState(isSettingOn: boolean, routing: HostRouting, notRouted: string): string {
  switch (routing) {
    case 'routed': {
      return yesNo(isSettingOn)
    }
    case 'notRouted': {
      return notRouted
    }
    case 'absent': {
      return 'none in this extension host'
    }
  }
}

function networkLines(network: NetworkFacts): readonly string[] {
  const fetchRoute = routeState(
    network.isFetchSupportOn,
    network.fetchRouting,
    'no (this editor does not route it)',
  )
  const webSocketRoute = routeState(
    network.isWebSocketSupportOn,
    network.webSocketRouting,
    `no (this editor does not route it; VS Code does from ${VSCODE_WEBSOCKET_ROUTED_SINCE})`,
  )
  return [
    `network: http.proxy set: ${yesNo(network.isProxySet)}; proxySupport: ${network.proxySupport}; proxyStrictSSL: ${yesNo(network.isProxyStrictSsl)}; proxyAuthorization set: ${yesNo(network.isProxyAuthorizationSet)}; noProxy entries: ${String(network.noProxyCount)}; proxy in environment: ${yesNo(network.hasEnvironmentProxy)}`,
    `certificates: system certificates: ${yesNo(network.isSystemCertificatesOn)}; NODE_EXTRA_CA_CERTS: ${yesNo(network.hasExtraCaCertificates)}`,
    `extension requests through VS Code's network support: fetch ${fetchRoute}, WebSocket ${webSocketRoute}`,
    `muse serve: proxy from ${MUSE_PROXY_SOURCES[network.museProxySource]}; SSL_CERT_FILE or SSL_CERT_DIR: ${yesNo(network.hasMuseCertificateOverride)}`,
  ]
}

/** `muse config status` under its heading, only known-safe fields, capped. */
function managedConfigurationLines(facts: SupportFacts['managedConfiguration']): readonly string[] {
  if (!facts.ok) {
    const reason =
      facts.reason === 'not run: the Muse Code CLI was not found' ||
      CONFIG_EXIT_CODE.test(facts.reason)
        ? facts.reason
        : CONFIG_FAILURE
    return [`muse config status: ${reason}`]
  }
  const text = facts.text
    .trim()
    .split(LINE_BREAK)
    .map((line) => safeConfigLine(line))
    .join('\n')
  const capped =
    text.length > MUSE_CONFIG_STATUS_MAX_CHARS
      ? `${text.slice(0, MUSE_CONFIG_STATUS_MAX_CHARS)}${TRUNCATED}`
      : text
  return ['muse config status:', capped]
}

export function renderSupportReport(facts: SupportFacts): string {
  const cli = facts.cli.ok
    ? `found in ${facts.cli.installDir} (version ${facts.cli.version ?? UNKNOWN})`
    : `not found: ${facts.cli.reason}`
  const dictation = facts.dictation.isAvailable
    ? 'available'
    : `unavailable: ${facts.dictation.reason}`
  const sandboxNetwork = facts.isSandboxNetworkApplied
    ? 'passed to muse serve'
    : 'not passed (Muse Code’s own default, or the shell sandbox is off)'
  const text = [
    `${PRODUCT_NAME} diagnostics`,
    `extension: ${facts.extensionVersion}`,
    `vscode: ${facts.vscodeVersion} (remote: ${facts.remoteName ?? NONE})`,
    `node: ${facts.nodeVersion} on ${facts.platform} ${facts.arch}`,
    `workspace: ${facts.hasWorkspace ? 'open' : NONE}, trusted: ${yesNo(facts.isWorkspaceTrusted)}`,
    `backend setting: ${facts.backendSetting}`,
    `shell sandbox: setting ${facts.shellSandboxSetting}, posture ${facts.shellSandboxPosture}`,
    `sandbox network: setting ${facts.sandboxNetworkSetting}, ${sandboxNetwork}`,
    `muse binary path configured: ${yesNo(facts.isBinaryPathConfigured)}; environment variables: ${String(facts.environmentVariableCount)}`,
    `muse cli: ${cli}`,
    `muse subagent delegation: ${facts.delegationMode}; workflow trigger mode: ${facts.workflowTriggerMode}`,
    `cli credential file: ${facts.cliCredentialFile}; cli sign-in: ${facts.cliSignIn}; stored model api key: ${yesNo(facts.hasStoredApiKey)}; META_API_KEY in environment: ${yesNo(facts.hasEnvironmentApiKey)}`,
    ...(facts.keychainItem === undefined
      ? []
      : [`macOS Keychain item ${MUSE_KEYCHAIN_SERVICE}: ${facts.keychainItem}`]),
    `voice dictation: ${dictation}`,
    ...networkLines(facts.network),
    ...managedConfigurationLines(facts.managedConfiguration),
  ].join('\n')
  return facts.homeDir === '' ? text : text.split(facts.homeDir).join(HOME_ABBREVIATION)
}

