        process.platform,
        workspaceRoot,
      ),
    searchWorkerPath: vscode.Uri.joinPath(context.extensionUri, 'dist', SEARCH_WORKER_FILE).fsPath,
    log: (message) => {
      log.warn(message)
    },
    // Each Windows command in a job object of its own, so a Stop ends
