            },
          }),
        log,
      })(),
    contextIo: fileContextIo,
    // VS Code's proxy-aware fetch, as it stands at each request (M56, D43).
    fetch: liveFetch,
    newId: () => crypto.randomUUID(),
    now: () => Date.now(),
    sleep: (ms) =>
      new Promise((resolve) => {
        setTimeout(resolve, ms)
      }),
    random: () => Math.random(),
    personalSkillsRoot: skillsHome,
    bundledSkills: {
      packageRoot: bundledPackageRoot,
      isEnabled: () => currentSettings().bundledSkills,
    },
    personalAgentsRoot: agentsHome,
    isWorkspaceTrusted: () => vscode.workspace.isTrusted,
    isConfidentialWorkspace: () => currentSettings().confidentialWorkspace,
    confirmContributorModel: isContributorModelAllowed,
    hookSettingsPath: museSettingsPath(museConfig()),
    isHooksEnabled: () => currentSettings().modelApiHooks,
    // Sessions survive the window (PLAN.md D14) in the workspace storage
    // directory; no folder open, no storage, no persistence.
    store:
      context.storageUri === undefined
        ? undefined
        : createFileSessionStore({
            directory: path.join(context.storageUri.fsPath, MODEL_API_SESSIONS_DIR),
            log,
            retentionDays: () => currentSettings().cleanupPeriodDays,
            now: () => Date.now(),
            sleep: (ms) =>
              new Promise((resolve) => {
                setTimeout(resolve, ms)
              }),
          }),
    scheduleStore:
      context.storageUri === undefined
        ? undefined
        : createFileScheduleStore({
            directory: path.join(context.storageUri.fsPath, MODEL_API_SCHEDULES_DIR),
            now: () => Date.now(),
            log,
          }),
    describeEnvironment: () => {
      const check = backend.workspaceActionGuard(nativeStarts.signal, workspaceRoot)
      return describeEnvironment({
        runGit: async (args, cwd) => {
          const owned = () => {
            check()
            if (
              workspaceRoot === undefined ||
              !vscode.workspace.isTrusted ||
              !isSamePath(cwd, workspaceRoot, process.platform)
            ) {
              throw new Error(UI_TEXT.checkpointFailed)
            }
          }
          return await withCheckpointEdit(
            checkpoints,
            log,
            owned,
            async () => await runGit(args, cwd, undefined, undefined, owned),
          )
        },
        workspaceRoot,
        isWorkspaceTrusted: () => vscode.workspace.isTrusted,
        log,
        now: Date.now,
      })
    },
    // An attempt's own branch and change counts, read in its worktree (M77).
    describeAttemptEnvironment: (attemptRoot) =>
      describeEnvironment({
        runGit: runBestOfNGit,
        workspaceRoot: attemptRoot,
        isWorkspaceTrusted: () => vscode.workspace.isTrusted,
        log,
        now: Date.now,
      }),
    isPaidFeatureOn: (feature) => paid.gate.isOn(feature),
    notePaidUse: (feature, units) => {
      paid.usage.add(feature, units)
    },
    promptCacheRetention: () => currentSettings().modelApiPromptCacheRetention,
    // The session budget cap and the per-reply usage line (M82), read per
    // request and per reply so a changed setting applies at once.
    sessionBudgetUsd: () => currentSettings().modelApiSessionBudgetUsd,
    showReplyUsage: () => currentSettings().modelApiReplyUsage,
    // Muse Code's MCP servers, run by this window for the Model API backend
    // (M50, PLAN.md D42): started in a trusted workspace only, stopped with
    // the host.
    createMcpServers: async (root, newPool) =>
      newPool(
        modelApiMcpPoolDeps({
          beforeWorkspaceProcessStart: () => checkpoints.markNativeBackend(),
          workspaceRoot: root,
          settingsPath: () => museSettingsPath(museConfig()),
          isWorkspaceTrusted: () => vscode.workspace.isTrusted,
          clientVersion: version,
          platform: process.platform,
          jobExecutablePath: await windowsMcpJob?.(),
          env: () => process.env,
          fetch: globalThis.fetch.bind(globalThis),
          log,
        }),
      ),
    ideTools,
    webFetch,
    codeIntel: languageServices,
    isRepoMapInPrompt: () => currentSettings().modelApiRepoMap,
    isObservationPackingOn: () => currentSettings().modelApiObservationPacking,
    allowsPaidUse: async (request, requiresAsking) =>
      await paid.consent.allows(request, requiresAsking),
    isPaidUseRemembered: (feature) => paid.consent.isRemembered(feature),
    noteSubagentUsage: (modelId, usage) => {
      paid.usage.addSubagentUsage(modelId, usage)
    },
    noteReviewerUsage: (modelId, usage) => {
      paid.usage.addReviewerUsage(modelId, usage)
    },
    // The command rules and permission profiles (M78), read at each call.
    permissionSettings: () => permissionSettingsOf(currentSettings()),
    memory: memory.store,
    // The settings are read at each use; a repository cannot set them (D15).
    verify: {
      isDiagnosticsOn: () => currentSettings().diagnosticsAfterEdits,
      checkCommands: () => currentSettings().checkCommands,
      isFormatOnEdit: () => currentSettings().formatOnEdit,
      diagnosticsAfterEdit: (files, signal, canReadFile) =>
        verifyEditor.diagnosticsAfterEdit(files, signal, canReadFile),
      formatAfterEdit: (absolutePath, text) => verifyEditor.formatAfterEdit(absolutePath, text),
    },
    createAttemptVerify: (attemptRoot) => {
      const editor = createVerifyEditor({
        platform: process.platform,
        log,
        workspaceRoot: attemptRoot,
        realPath: canonicalPath,
      })
      return {
        isDiagnosticsOn: () => currentSettings().diagnosticsAfterEdits,
        checkCommands: () => currentSettings().checkCommands,
        isFormatOnEdit: () => currentSettings().formatOnEdit,
        diagnosticsAfterEdit: (files, signal, canReadFile) =>
          editor.diagnosticsAfterEdit(files, signal, canReadFile),
        formatAfterEdit: (absolutePath, text) => editor.formatAfterEdit(absolutePath, text),
        dispose: () => {
          editor.dispose()
        },
      }
    },
    // Its own bundle, loaded when this backend first starts (M57, PLAN.md D6).
    bundlePath: vscode.Uri.joinPath(context.extensionUri, 'dist', MODEL_API_BUNDLE_FILE).fsPath,
  })
  const watchedHosts = new WeakSet<AgentHost>()
  let chosenBackend: BackendKind | undefined
  /** The host for the next conversation, by the same selection the sign-in gate uses. */
  const ensureSelectedHost = async () => {
    const host = await chooseAuthorizedHost(
      () => auth.backend,
      // Forced Model API asks the CLI nothing (Codex on 328efb52).
      async () =>
        await readBackendChoice({
          setting: currentSettings().backend,
          hasCli: backend.resolveLaunch().ok,
          hasCliSession,
          hasStoredKey: async () => (await credentials.getApiKey()) !== undefined,
        }),
      async (kind): Promise<AgentHost> =>
        kind === 'modelApi' ? await modelApi.ensureHost() : await backend.ensureHost(),
      () => auth.admissionGeneration,
    )
    if (host.info.kind !== chosenBackend) {
      // Said when it changes, not on every message (M39).
      chosenBackend = host.info.kind
      log.info(`Conversations run on the ${host.info.kind} backend`)
    }
    // One exit listener per host, however many messages ask for it (D25).
    if (host.info.kind === 'museCode' && !watchedHosts.has(host)) {
      watchedHosts.add(host)
      host.onExit((exit) => {
        for (const active of controllers.values()) {
          active.hostExited(exit)
        }
      })
    }
    return host
  }

  // Session history memory (M6): archived ids and the last session, per
  // workspace, in the extension's own `workspaceState`.
  const sessions: SessionMemory = {
    // A value an earlier version (or a hand edit) stored that does not
    // validate reads as "none archived" instead of throwing (PLAN.md D25).
    archivedIds: () => {
      const parsed = archivedIdsSchema.safeParse(
        context.workspaceState.get<unknown>(WORKSPACE_STATE_KEYS.archivedSessions) ?? [],
      )
      return parsed.success ? parsed.data : []
    },
    setArchivedIds: async (ids) => {
      await context.workspaceState.update(WORKSPACE_STATE_KEYS.archivedSessions, [...ids])
    },
    // Sessions whose Muse Code event log failed (CLI recovery); a value
    // that does not validate reads as none, as above.
    damagedIds: () => {
      const parsed = damagedIdsSchema.safeParse(
        context.workspaceState.get<unknown>(WORKSPACE_STATE_KEYS.damagedSessions) ?? [],
      )
      return parsed.success ? parsed.data : []
    },
    setDamagedIds: async (ids) => {
      await context.workspaceState.update(WORKSPACE_STATE_KEYS.damagedSessions, [...ids])
    },
    lastSession: () => {
      const stored = context.workspaceState.get<unknown>(WORKSPACE_STATE_KEYS.lastSession)
      const parsed = lastSessionSchema.safeParse(stored)
      return parsed.success ? parsed.data : undefined
    },
    setLastSession: async (last) => {
      await context.workspaceState.update(WORKSPACE_STATE_KEYS.lastSession, last)
    },
  }

  const files: FileAccess = {
    showOpenDialog: async () => {
      const uris = await vscode.window.showOpenDialog({
        canSelectMany: true,
        openLabel: UI_TEXT.attachTitle,
      })
      return (uris ?? []).map((uri): PickedFile => ({
        name: path.basename(uri.fsPath),
        fsPath: uri.fsPath,
        relativePath: relativePathInWorkspace(uri),
      }))
    },
    readFile: readPickedFile,
    canonicalRelativePath: async (fsPath) => {
      if (workspaceRoot === undefined) {
        return
      }
      const resolved = await confineWorkspacePath(workspaceRoot, fsPath, process.platform, toolIo)
      return resolved.ok
        ? { canonical: resolved.canonical, checkedAbsolute: resolved.checkedAbsolute }
        : undefined
    },
    pickMentionFile: () =>
      pickMentionFile({
        createQuickPick: () => vscode.window.createQuickPick(),
        mentions,
        limit: QUICK_PICK_LIMIT,
        placeholder: UI_TEXT.mentionFile,
      }),
    // A dropped URI is the UI side's name for the file; in a remote window it
    // is mapped to this (remote) side's as VS Code maps URIs itself (D27).
    toRelativePath: (uri) =>
      relativePathInWorkspace(
        vscode.Uri.from(hostSideUri(vscode.Uri.parse(uri), vscode.env.remoteName)),
      ),
  }

  const runHostAction = async (action: HostAction): Promise<void> => {
    switch (action) {
      case 'openSettings': {
        await vscode.commands.executeCommand(VSCODE_COMMANDS.openSettings, SETTINGS_SECTION)
        break
      }
      case 'openKeybindings': {
        await vscode.commands.executeCommand(VSCODE_COMMANDS.openKeybindings, SETTINGS_SECTION)
        break
      }
      case 'openLog': {
        channel.show(true)
        break
      }
      case 'toggleFocusView': {
        await toggleFocusView({
          isFocusViewEnabled: () => currentSettings().focusView,
          setFocusViewEnabled: (isEnabled) => updateSetting('focusView', isEnabled),
        })
        break
      }
      case 'toggleCtrlEnterToSend': {
        await updateSetting('useCtrlEnterToSend', !currentSettings().useCtrlEnterToSend)
        break
      }
      case 'hideOnboarding': {
        await updateSetting('hideOnboarding', true)
        break
      }
      case 'openMuseSettings': {
        const settingsPath = museSettingsPath(museConfig())
        if (await isExistingPath(settingsPath)) {
          await vscode.window.showTextDocument(vscode.Uri.file(settingsPath))
        } else {
          void vscode.window.showInformationMessage(
            fill(UI_TEXT.museSettingsMissing, { path: settingsPath }),
          )
        }
        break
      }
      case 'manageSkills': {
        await cliFeatures.manageSkills()
        break
      }
      case 'importSkills': {
        await cliFeatures.importSkills()
        break
      }
      case 'importFromAgents': {
        await cliFeatures.importFromAgents()
        break
      }
      case 'showMcpServers': {
        await cliFeatures.showMcpServers()
        break
      }
      case 'showHooks': {
        await cliFeatures.showHooks()
        break
      }
      case 'showMemory': {
        await memoryView.showMemory()
        break
      }
      case 'newWorktree': {
        await worktrees.newWorktree()
        break
      }
      case 'removeWorktree': {
        await worktrees.removeWorktree()
        break
      }
      case 'restartMuseCode': {
        // A notice's Restart (a D26 fault, or Muse Code not answering): the
        // next message continues the conversation (D25).
        await restartMuseCode('asked for from a notice in the panel')
        break
      }
      // The bundled skills' offer (M89): Install and Update are the same steps.
      case 'installBundledSkills':
      case 'updateBundledSkills': {
        await runBundledSkillsInstall(bundledSkillsCommand())
        break
      }
      case 'declineBundledSkills': {
        await bundledSkillsOffer.decline()
        break
      }
    }
  }

  // One per window (M82): a notice two surfaces on one session receive is
  // raised once, and only while the window is unfocused.
  const backgroundNotifier = new BackgroundNotifier({
    isEnabled: () => currentSettings().notifyOnBackgroundTurn,
    isWindowFocused: () => vscode.window.state.focused,
    show: async (message) =>
      (await vscode.window.showInformationMessage(message, UI_TEXT.notifyShowConversation)) ===
      UI_TEXT.notifyShowConversation,
    log,
  })

  const controllerFor = (surface: ChatSurface): ConversationController => {
    let controller = controllers.get(surface.id)
    if (controller === undefined) {
      controller = new ConversationController({
        surface,
        auth,
        ensureHost: ensureSelectedHost,
        workspaceRoot,
        modelId: DEFAULT_MODEL_ID,
        initialPermissionMode: currentSettings().initialPermissionMode,
        hasApprovalUi: HAS_APPROVAL_UI,
        openExternal: (url) => {
          void vscode.env.openExternal(vscode.Uri.parse(url))
        },
        openSideChat: (sessionId) => {
          openChatPanel(hostContext, registry, {
            sessionId,
            isSideChat: true,
            onDisposed: () => {
              if (registry.has(surface)) {
                surface.reveal()
              }
            },
          })
        },
        mentions: {
          search: (query, limit) => mentions.search(query, limit),
          contains: (relativePath) => mentions.contains(relativePath),
        },
        files,
        isBypassAllowed: () => currentSettings().allowDangerouslySkipPermissions,
        isRemoteWindow: vscode.env.remoteName !== undefined,
        confirmRemoteBypass: async () =>
          (await vscode.window.showWarningMessage(
            UI_TEXT.bypassRemoteTitle,
            { modal: true, detail: UI_TEXT.bypassRemoteDetail },
            UI_TEXT.bypassRemoteConfirm,
          )) === UI_TEXT.bypassRemoteConfirm,
        isConfidentialWorkspace: () => currentSettings().confidentialWorkspace,
        // One explicit yes per conversation before the model switches; the
        // Model API backend asks the same question for a custom agent's model.
        confirmContributor: isContributorModelAllowed,
        runHostAction,
        // A turn needs the user while the VS Code window is unfocused
        // (M82); the notice's button brings this surface into view, while
        // it is still open.
        notifyAttention: (notice) => {
          backgroundNotifier.notify(notice, () => {
            if (registry.has(surface)) {
              surface.reveal()
            }
          })
        },
        museCodeReviewer,
        copyText: async (text) => {
          await vscode.env.clipboard.writeText(text)
        },
        insertCode: async (text) => {
          const editor = vscode.window.activeTextEditor
          if (editor === undefined) {
            return false
          }
          return await editor.edit((builder) => {
            builder.insert(editor.selection.active, text)
          })
        },
        onSandboxUnavailable: () => {
          void sandbox.offerIfNeeded('failure').catch(logRejection(log, 'sandbox offer'))
        },
        platform: process.platform,
        userProfileDir: process.env['USERPROFILE'],
        shellSandbox: () => backend.shellSandboxPosture(),
        editorContext: () => editorContext.active,
        isAutosaveEnabled: () => currentSettings().autosave,
        saveAll: async () => {
          await vscode.workspace.saveAll(false)
        },
        // Workspace files open with unsaved changes (PLAN.md D27).
        unsavedFiles: () =>
          vscode.workspace.textDocuments
            .filter((document) => document.isDirty && document.uri.scheme === FILE_SCHEME)
            .map((document) => vscode.workspace.asRelativePath(document.uri, false)),
        // Code block "Apply": the block replaces the selection (or lands at
        // the caret); false when no text editor is active.
        applyCode: async (text) => {
          const editor = vscode.window.activeTextEditor
          if (editor === undefined) {
            return false
          }
          const isApplied = await editor.edit((builder) => {
            builder.replace(editor.selection, text)
          })
          if (isApplied) {
            editor.revealRange(editor.selection)
          }
          return isApplied
        },
        editReview: review.editReview,
        review,
        openDocument,
        openFile,
        readToolImage: async (imagePath) =>
          await loadToolImage(
            imagePath,
            workspaceRoot,
            process.platform,
            toolImagePreviewIo(toolIo, async (fsPath) => {
              const stat = await vscode.workspace.fs.stat(vscode.Uri.file(fsPath))
              return stat.size
            }),
          ),
        // A server that failed to start is started again, and the session
        // that asked waits for it, so it gets the tool too (D25).
        ideMcpEndpoint: async () => {
          if (ideServer.current === undefined) {
            await startIdeServer()
          }
          return ideServer.current
        },
        newAttachmentId: () => crypto.randomUUID(),
        sessions,
        // The usage modal's Account section and insights (M14).
        accountFacts: async (kind) => {
          const resolution = backend.resolveLaunch()
          const isCliSession = await hasCliSession()
          const hasKey = (await credentials.getApiKey()) !== undefined
          const signInMethod = signInMethodFor(kind, isCliSession, hasKey)
          const cliVersion = resolution.ok
            ? backend.installedVersion(resolution.launch.installDir)
            : undefined
          return {
            signInMethod,
            ...(cliVersion !== undefined && { cliVersion }),
            ...(kind === 'museCode' && {
              delegationMode: delegationMode(),
              workflowTriggerMode: workflowTriggerMode(),
            }),
          }
        },
        usageInsights: () => insights.read(),
        // Only the sidebar reopens on its last session; a tab is a new
        // conversation by construction (M6).
        isRestorable: surface.id === SIDEBAR_SURFACE_ID,
        dictation,
        // Muse Voice on the Model API backend, and on Muse Code with a stored key (M44).
        museVoice: () =>
          paid.gate.isOn('voice') &&
          usablePaidFeatures(auth.current.backend, isKeyStored).includes('voice')
            ? museVoiceSetup
            : undefined,
        modelApiSessionBudgetUsd: () => currentSettings().modelApiSessionBudgetUsd,
        voiceAccountId: () => modelApi.accountId(),
        ownedVoiceBudgetScope: async (sessionId) => {
          if (auth.current.backend !== 'modelApi') {
            throw new Error(UI_TEXT.sessionBudgetStoreUnavailable)
          }
          const host = await modelApi.ensureHost()
          return await host.getOwnedBudgetScope(sessionId)
        },
        exports: cliFeatures.exports,
        transferFiles: createSessionTransferFiles(),
        plans,
        // The palette's paid-feature toggles (M33): on goes through the price confirmation.
        setPaidFeature: async (feature, isOn) => {
          if (isOn) {
            await paid.gate.turnOn(feature)
          } else {
            await paid.gate.turnOff(feature)
          }
        },
        isWorkspaceTrusted: () => vscode.workspace.isTrusted,
        onForegroundTasksChanged: refreshTaskContext,
        isScheduledPaidOn: () => paid.gate.isOn('scheduledPrompts'),
        confirmScheduledRun: async (job, modelId) =>
          await paid.consent.allows({ feature: 'scheduledPrompts', prompt: job.prompt, modelId }),
        allowsPaidUse: async (request) => await paid.consent.allows(request),
        forgetPaidUse: async () => {
          await paid.consent.forget()
        },
        checkpoints,
        // Text files and notebooks open with unsaved changes, by absolute path (M72).
        unsavedPaths: () =>
          [...vscode.workspace.textDocuments, ...vscode.workspace.notebookDocuments]
            .filter((document) => document.isDirty && document.uri.scheme === FILE_SCHEME)
            .map((document) => document.uri.fsPath),
        confirmFileAction: async (title, detail, action) =>
          (await vscode.window.showWarningMessage(title, { modal: true, detail }, action)) ===
          action,
        // Muse Code checks its own edits (M68): its checks run through its own
        // shell, so none are named while Restricted Mode runs no shell (D13).
        // The diagnostics sentence only for a session that has the ide server.
        verifyGuidance: (hasIdeServer) => {
          const settings = currentSettings()
          return verifyGuidance(
            settings.diagnosticsAfterEdits && hasIdeServer,
            vscode.workspace.isTrusted ? settings.checkCommands : [],
          )
        },
        bundledSkillsOffer: () => bundledSkillsOffer.next(),
        // The session board's pending prompts, shared by every surface (M77).
        pendingPrompts: boardPrompts,
        boardSessions: () => {
          const sessions: BoardSession[] = []
          for (const active of controllers.values()) {
            const session = active.boardSession()
            if (session !== undefined) sessions.push(session)
          }
          return sessions
        },
        focusBoardSession: (sessionId, backendKind) => {
          for (const active of controllers.values()) {
            if (active.revealBoardSession(sessionId, backendKind)) return true
          }
          return false
        },
        bestOfNCoordinator,
        bestOfNWorkspaceEdits: (session) => {
          const owner =
            session === undefined ? undefined : modelApi.captureExternalEditOwner(session)
          return async (root, paths) => {
            const files: EditedFile[] = []
            for (const file of paths) {
              const checked = await confineWorkspacePath(root, file, process.platform, {
                realPath: canonicalPath,
              })
              if (
                !checked.ok ||
                isProtectedPath(checked.relative) ||
                isProtectedPath(checked.canonical) ||
                checked.relative !== checked.canonical
              ) {
                throw new Error(UI_TEXT.bestOfNTargetChanged)
              }
              files.push({ relative: checked.canonical, absolute: checked.checkedAbsolute })
            }
            return modelApi.beginExternalEdit(owner, files)
          }
        },
        modelApiAccountId: () => modelApi.accountId(),
        noteBestOfNRequest: () => {
          paid.usage.addBestOfNRequest()
        },
        noteBestOfNUsage: (modelId, usage) => {
          paid.usage.addBestOfNUsage(modelId, usage)
        },
        bestOfNBudgetScope: (sessionId) => modelApi.bestOfNBudgetScope(sessionId),
        openBestOfNWorktree: async (absolutePath) => {
          await vscode.commands.executeCommand(
            VSCODE_COMMANDS.openFolder,
            vscode.Uri.file(absolutePath),
            { forceNewWindow: true },
          )
        },
        runGit,
        runBestOfNGit,
        isPaidFeatureOn: (feature) => paid.gate.isOn(feature),
        notePaidUse: (feature, units) => {
          paid.usage.add(feature, units)
        },
        buildAttemptHost: (worktreeRoot, admitRequest, noteUsage, budgetScope) =>
          modelApi.buildAttemptHost(worktreeRoot, admitRequest, noteUsage, budgetScope),
        realPath: canonicalPath,
        now: () => Date.now(),
        log,
      })
      controllers.set(surface.id, controller)
    }
    return controller
  }

  const hostContext: WebviewHostContext = {
    extensionUri: context.extensionUri,
    l10n,
    log,
    getSettings: () => toSettingsSnapshot(currentSettings()),
    onInputFocusChanged: (surface, isFocused) => {
      isInputFocused = isFocused
      if (isFocused) {
        registry.setActive(surface)
      }
      void vscode.commands.executeCommand(
        VSCODE_COMMANDS.setContext,
        CONTEXT_KEYS.inputFocused,
        isFocused,
      )
    },
    onSurfaceReady: (surface, attachmentEpoch) => {
      const controller = controllerFor(surface)
      controller.surfaceReady(attachmentEpoch)
      surface.post({ type: 'editorContext', context: editorContext.summary })
      surface.post({ type: 'paidState', state: paid.state() })
      // A rebuilt panel resumes the session it held (D15); the sidebar
      // follows the ten-minute rule (M6).
      const restoredSessionId = surface.takeRestoredSessionId()
      const restore = () =>
        restoredSessionId === undefined
          ? controller.restoreRecentSession()
          : controller.restoreSession(restoredSessionId)
      if (auth.current.status === 'checking') {
        void auth.refresh().then(restore).catch(logRejection(log, 'session restore'))
      } else {
        void restore().catch(logRejection(log, 'session restore'))
      }
      // No setup offer where this window will not use the sandbox anyway.
      if (!backend.shellSandboxPosture().isSandboxed) {
        return
      }
      void sandbox.offerIfNeeded('startup').catch(logRejection(log, 'sandbox offer'))
    },
    onConversationMessage: (surface, message) => {
      void controllerFor(surface).handle(message)
    },
  }

  registry.onRemoved((surface) => {
    controllers.get(surface.id)?.dispose()
    controllers.delete(surface.id)
  })
  registry.onActiveChanged(refreshTaskContext)
  /** A command for the conversation in view, when there is one. */
  const forActiveConversation =
    (run: (controller: ConversationController) => Promise<void>) => async () => {
      const surface = registry.active
      if (surface !== undefined) {
        await run(controllerFor(surface))
      }
    }

  const openSidebar = () => vscode.commands.executeCommand(`${CHAT_VIEW_ID}.focus`)
  /** A conversation where the setting says new ones open. */
  const openConversation = async (): Promise<void> => {
    if (currentSettings().preferredLocation === 'sidebar') {
      await openSidebar()
      return
    }
    openChatPanel(hostContext, registry)
  }
  const resolveCli = () => {
    const resolution = backend.resolveLaunch()
    return resolution.ok
      ? { ok: true as const, cliPath: resolution.launch.cliPath }
      : { ok: false as const, reason: resolution.reason }
  }
  const fileWatcher = vscode.workspace.createFileSystemWatcher(FIND_FILES_GLOB, false, true, false)
  const onSkillFilesChanged = () => {
    void modelApi.refreshSkills().catch(logRejection(log, 'skill refresh'))
  }
  const projectSkillsWatcher = vscode.workspace.createFileSystemWatcher(PROJECT_SKILLS_GLOB)
  const personalSkillsWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(vscode.Uri.file(skillsHome), PERSONAL_SKILLS_GLOB),
  )

  editorContext.update(editorSnapshot)
  // A setting turned on while VS Code was closed, or in another window, is
  // confirmed here: at activation, and when this window gains focus (D30).
  void paid.gate.review().catch(logRejection(log, 'paid feature review'))
  context.subscriptions.push(
    { dispose: paid.gate.onDidChange(broadcastPaidState) },
    { dispose: paid.consent.onDidChange(broadcastPaidState) },
    { dispose: paid.usage.onDidChange(broadcastPaidState) },
    vscode.window.onDidChangeWindowState((state) => {
      if (state.focused) {
        void paid.gate.review().catch(logRejection(log, 'paid feature review'))
      }
    }),
    channel,
    fileWatcher,
    projectSkillsWatcher,
    personalSkillsWatcher,
    projectSkillsWatcher.onDidChange(onSkillFilesChanged),
    projectSkillsWatcher.onDidCreate(onSkillFilesChanged),
    projectSkillsWatcher.onDidDelete(onSkillFilesChanged),
    personalSkillsWatcher.onDidChange(onSkillFilesChanged),
    personalSkillsWatcher.onDidCreate(onSkillFilesChanged),
    personalSkillsWatcher.onDidDelete(onSkillFilesChanged),
    editorContext,
    {
      dispose: () => {
        ideServer.close()
      },
    },
    vscode.window.onDidChangeActiveTextEditor(() => {
      editorContext.update(editorSnapshot)
    }),
    vscode.window.onDidChangeTextEditorSelection(() => {
      editorContext.update(editorSnapshot)
    }),
    vscode.workspace.registerTextDocumentContentProvider(MUSE_EDIT_SCHEME, {
      provideTextDocumentContent: (uri) => review.editReview.provide(uri.path),
    }),
    fileWatcher.onDidCreate(() => {
      mentions.invalidate()
    }),
    fileWatcher.onDidDelete(() => {
      mentions.invalidate()
    }),
    vscode.window.registerWebviewViewProvider(
      CHAT_VIEW_ID,
      new ChatViewProvider(hostContext, registry),
      { webviewOptions: { retainContextWhenHidden: true } },
    ),
    vscode.workspace.onDidChangeConfiguration((event) => {
      if (event.affectsConfiguration(SETTINGS_SECTION)) {
        registry.broadcast({ type: 'settingsChanged', settings: hostContext.getSettings() })
        for (const controller of controllers.values()) {
          controller.refreshDictation()
        }
      }
      // Checkpoints on or off: every panel's menus follow (M72).
      if (event.affectsConfiguration(TURN_CHECKPOINTS_SETTING)) {
        for (const controller of controllers.values()) {
          controller.checkpointsChanged()
        }
      }
      // A paid feature turned on anywhere asks for its price once (D30).
      if (paid.affects(event)) {
        void paid.gate.review().catch(logRejection(log, 'paid feature review'))
      }
      // The bundled skills on or off: the Model API catalogue follows (M89).
      if (event.affectsConfiguration(BUNDLED_SKILLS_SETTING)) {
        onSkillFilesChanged()
      }
      // Turning the Bypass setting off ends Bypass everywhere now (D24).
      if (
        event.affectsConfiguration(BYPASS_SETTING) &&
        !currentSettings().allowDangerouslySkipPermissions
      ) {
        for (const controller of controllers.values()) {
          void controller.revokeBypass().catch(logRejection(log, 'Bypass revocation'))
        }
      }
      // A host keeps its sandbox posture, its environment and its binary for
      // life, and the backend choice is made per host: drop them so the next
      // message spawns afresh (and resumes the conversation, D25).
      const isBackendSetting = event.affectsConfiguration(BACKEND_SETTING)
      if (isBackendSetting) {
        void restartBackend('the backend setting changed')
          .then(() => auth.refresh())
          .catch(logRejection(log, 'backend restart'))
        return
      }
      const isCliSetting = CLI_PROCESS_SETTINGS.some((key) => event.affectsConfiguration(key))
      if (isCliSetting) {
        backend.invalidateLaunch()
      }
      const isHostSetting =
        isCliSetting ||
        event.affectsConfiguration(SHELL_SANDBOX_SETTING) ||
        event.affectsConfiguration(SANDBOX_NETWORK_SETTING)
      if (!isHostSetting || !backend.isRunning) {
        return
      }
      void restartBackend('a CLI, environment, proxy or sandbox setting changed').catch(
        logRejection(log, 'backend restart'),
      )
      registry.broadcast({ type: 'notice', level: 'info', text: UI_TEXT.sandboxRestartNotice })
    }),
    // Trust is a host-lifetime posture like the sandbox (PLAN.md D13): the
    // hosts restart so the next message loads the rules and skills.
    vscode.workspace.onDidGrantWorkspaceTrust(() => {
      // The index was built without git in Restricted Mode (D24).
      mentions.invalidate()
      void restartBackend('the workspace was trusted').catch(logRejection(log, 'backend restart'))
      registry.broadcast({ type: 'notice', level: 'info', text: UI_TEXT.trustGrantedNotice })
      // "Allow always in this workspace" counts only in a trusted one (M58).
      broadcastPaidState()
      // Checkpoints run from now on, and what was queued while untrusted is cleaned up (M72).
      void checkpoints.maintain().catch(logRejection(log, 'checkpoint cleanup'))
      for (const controller of controllers.values()) {
        controller.checkpointsChanged()
      }
    }),
    // Editor-tab conversations come back after a window reload (D15).
    vscode.window.registerWebviewPanelSerializer(CHAT_PANEL_VIEW_TYPE, {
      deserializeWebviewPanel: (panel, state: unknown) => {
        restoreChatPanel(panel, state, hostContext, registry)
        return Promise.resolve()
      },
    }),
    registerLoggedCommand(log, COMMAND_IDS.openInNewTab, () => {
      openChatPanel(hostContext, registry)
    }),
    registerLoggedCommand(log, COMMAND_IDS.newConversation, async () => {
      const surface = registry.active
      if (surface === undefined) {
        await openConversation()
        return
      }
      surface.reveal()
      await controllerFor(surface).handle({ type: 'clearConversation' })
    }),
    registerLoggedCommand(log, COMMAND_IDS.signOut, async () => {
      await auth.signOut()
      void vscode.window.showInformationMessage(UI_TEXT.signedOutNotice)
    }),
    registerLoggedCommand(log, COMMAND_IDS.openInTerminal, async () => {
      await openMuseTerminal({
        resolveCli,
        runInTerminal: runCliInTerminal,
        workspaceRoot,
        showWarning: (message) => {
          void vscode.window.showWarningMessage(message)
        },
      })
    }),
    registerLoggedCommand(log, COMMAND_IDS.createRulesFile, async () => {
      const check = backend.workspaceActionGuard(nativeStarts.signal)
      await createRulesFile({
        workspaceRoot,
        isWorkspaceTrusted: () => vscode.workspace.isTrusted,
        fileExists: isExistingPath,
        writeFile: (fsPath, content) => writeUserFile(check, fsPath, content),
        openFile: async (fsPath) => {
          await vscode.window.showTextDocument(vscode.Uri.file(fsPath))
        },
        runInit: () => {
          check()
          const resolution = backend.resolveLaunch()
          return workspaceRoot !== undefined && resolution.ok
            ? backend.startWorkspaceCommand(() => {
                check()
                return runProcess(
                  { command: resolution.launch.command, args: MUSE_INIT_ARGS },
                  MUSE_INIT_TIMEOUT_MS,
                  workspaceRoot,
                )
              }, nativeStarts.signal)
            : undefined
        },
        showInformation: (message) => {
          void vscode.window.showInformationMessage(message)
        },
        showWarning: (message) => {
          void vscode.window.showWarningMessage(message)
        },
        log,
      })
    }),
    registerLoggedCommand(log, COMMAND_IDS.openWalkthrough, async () => {
      await vscode.commands.executeCommand(
        VSCODE_COMMANDS.openWalkthrough,
        WALKTHROUGH_QUALIFIED_ID,
        false,
      )
    }),
    registerLoggedCommand(log, COMMAND_IDS.openInSidebar, openSidebar),
    registerLoggedCommand(log, COMMAND_IDS.showLogs, () => {
      channel.show(true)
    }),
    // The support report (PLAN.md D14): facts only, credentials as booleans.
    registerLoggedCommand(log, COMMAND_IDS.diagnostics, async () => {
      const settings = currentSettings()
      const resolution = backend.resolveLaunch()
      const posture = backend.shellSandboxPosture()
      // The managed configuration as the CLI reads it (M56, PLAN.md D43): a
      // local read, no model call, in the environment `muse serve` gets.
      const managed = await managedConfiguration(
        resolution.ok
          ? () =>
              runProcess(
                { command: resolution.launch.command, args: MUSE_CONFIG_STATUS_ARGS },
                MUSE_CONFIG_STATUS_TIMEOUT_MS,
                workspaceRoot,
                backend.childEnvironment(),
              )
          : undefined,
      )
      // Where a macOS sign-in's token lives, looked up by attribute only (no
      // `-g`/`-w`: no secret, no prompt); never the sign-in signal (D26).
      const keychainLookup =
        process.platform === 'darwin'
          ? await runProcess(
              { command: MACOS_SECURITY_TOOL, args: MACOS_KEYCHAIN_LOOKUP_ARGS },
              MACOS_KEYCHAIN_LOOKUP_TIMEOUT_MS,
            )
          : undefined
      log.info(
        renderSupportReport({
          extensionVersion: version,
          vscodeVersion: vscode.version,
          nodeVersion: process.versions.node,
          platform: process.platform,
          arch: process.arch,
          remoteName: vscode.env.remoteName,
          hasWorkspace: workspaceRoot !== undefined,
          isWorkspaceTrusted: vscode.workspace.isTrusted,
          backendSetting: settings.backend,
          shellSandboxSetting: settings.shellSandbox,
          shellSandboxPosture: `${posture.isSandboxed ? 'sandboxed' : 'disabled'} (${posture.reason})`,
          sandboxNetworkSetting: settings.sandboxNetwork,
          isSandboxNetworkApplied: isSandboxNetworkApplied(settings.sandboxNetwork, posture),
          isBinaryPathConfigured: settings.museBinaryPath !== '',
          environmentVariableCount: settings.environmentVariables.length,
          cli: resolution.ok
            ? {
                ok: true,
                installDir: resolution.launch.installDir,
                version: backend.installedVersion(resolution.launch.installDir),
              }
            : { ok: false, reason: resolution.reason },
          cliCredentialFile: backend.credentialFileVerdict(),
          cliSignIn: await cliAccount.signIn(true),
          keychainItem:
            keychainLookup === undefined
              ? undefined
              : keychainItemPresence(keychainLookup.exitCode),
          delegationMode: delegationMode(),
          workflowTriggerMode: workflowTriggerMode(),
          hasStoredApiKey: (await credentials.getApiKey()) !== undefined,
          hasEnvironmentApiKey: backend.hasEnvironmentKey(),
          dictation: dictation.isAvailable
            ? { isAvailable: true }
            : { isAvailable: false, reason: dictation.reason },
          network: readNetworkFacts(
            vscode.workspace.getConfiguration(HTTP_SETTINGS_SECTION),
            process.env,
            process.platform,
            backend,
            globalThis,
          ),
          managedConfiguration: managed,
          homeDir: homedir(),
        }),
      )
      channel.show(true)
    }),
    registerLoggedCommand(log, COMMAND_IDS.focusInput, async () => {
      await toggleInputFocus({
        isInputFocused: () => isInputFocused,
        activeSurface: () => registry.active,
        focusEditor: () => vscode.commands.executeCommand(VSCODE_COMMANDS.focusActiveEditorGroup),
        openSidebar,
      })
    }),
    registerLoggedCommand(log, COMMAND_IDS.insertMentionReference, async () => {
      await insertMentionReference({
        activeSelection,
        activeSurface: () => registry.active,
        openSidebar,
        showInformation: (message) => {
          void vscode.window.showInformationMessage(message)
        },
      })
    }),
    registerLoggedCommand(log, COMMAND_IDS.toggleFocusView, async () => {
      await runHostAction('toggleFocusView')
    }),
    registerLoggedCommand(
      log,
      COMMAND_IDS.toggleThinking,
      forActiveConversation((controller) => controller.toggleThinking()),
    ),
    // Ctrl+B and "Stop Background Tasks" (M46, PLAN.md D39).
    registerLoggedCommand(
      log,
      COMMAND_IDS.moveToBackground,
      forActiveConversation((controller) => controller.moveRunningToBackground()),
    ),
    registerLoggedCommand(
      log,
      COMMAND_IDS.stopBackgroundTasks,
      forActiveConversation((controller) => controller.stopBackgroundTasks()),
    ),
    registerLoggedCommand(log, COMMAND_IDS.setUpSandbox, async () => {
      await sandbox.runCommand()
    }),
    // A fresh `muse serve` without a window reload (CLI recovery): a running
    // turn is stopped, and each conversation resumes with its next message.
    registerLoggedCommand(log, COMMAND_IDS.restartMuseCode, async () => {
      await restartMuseCode('asked for from the command palette')
      // Said in VS Code: the palette may run it with no panel open.
      void vscode.window.showInformationMessage(UI_TEXT.museCodeRestarted)
    }),
    // M89 (PLAN.md D68): the bundled skills into Muse Code's folders, and out.
    registerLoggedCommand(log, COMMAND_IDS.installBundledSkills, () =>
      runBundledSkillsInstall(bundledSkillsCommand()),
    ),
    registerLoggedCommand(log, COMMAND_IDS.removeBundledSkills, () =>
      runBundledSkillsRemove(bundledSkillsCommand()),
    ),
    registerLoggedCommand(log, COMMAND_IDS.manageSkills, () => cliFeatures.manageSkills()),
    registerLoggedCommand(log, COMMAND_IDS.importSkills, () => cliFeatures.importSkills()),
    registerLoggedCommand(log, COMMAND_IDS.importFromAgents, () => cliFeatures.importFromAgents()),
    registerLoggedCommand(log, COMMAND_IDS.mcpServers, () => cliFeatures.showMcpServers()),
    registerLoggedCommand(log, COMMAND_IDS.hooks, () => cliFeatures.showHooks()),
    registerLoggedCommand(log, COMMAND_IDS.memory, () => memoryView.showMemory()),
    registerLoggedCommand(log, COMMAND_IDS.newWorktree, () => worktrees.newWorktree()),
    registerLoggedCommand(log, COMMAND_IDS.removeWorktree, () => worktrees.removeWorktree()),
    registerLoggedCommand(log, COMMAND_IDS.exportConversation, async () => {
      const surface = registry.active
      if (surface === undefined) {
        void vscode.window.showInformationMessage(UI_TEXT.exportNothing)
        return
      }
      await controllerFor(surface).handle({ type: 'exportConversation', format: 'markdown' })
    }),
    // Import and share (M84): listed only while a Muse panel is in view.
    registerLoggedCommand(
      log,
      COMMAND_IDS.importSession,
      forActiveConversation((controller) => controller.handle({ type: 'importSession' })),
    ),
    registerLoggedCommand(
      log,
      COMMAND_IDS.openShareFile,
      forActiveConversation((controller) => controller.handle({ type: 'openShareFile' })),
    ),
    // M95 (PLAN.md D74) lane 0: the ids so the manifest stays whole. Lane K
    // registers the real handlers; until then each refuses with an explicit
    // error, never an empty success.
    registerLoggedCommand(log, COMMAND_IDS.startWithOwnModel, () => {
      throw new Error(UI_TEXT.modelsPanelUnavailable)
    }),
    registerLoggedCommand(log, COMMAND_IDS.modelsAndAgents, () => {
      throw new Error(UI_TEXT.modelsPanelUnavailable)
    }),
    registerLoggedCommand(log, COMMAND_IDS.addModelProvider, () => {
      throw new Error(UI_TEXT.modelsPanelUnavailable)
    }),
  )
  log.info(`Activated in ${String(Math.round(performance.now() - activationStartedAt))} ms`)
}

src/host/agentImportBundle.ts:
// The import as the activation bundle sees it (M83, PLAN.md D6):
// dist/agentImport.js, built from agentImportEntry.ts and required on the
// first import. Only types come from the import's side here: a value
// imported from there would carry the scan, the converters and `smol-toml`
// back into dist/extension.js, which the bundle-split gate refuses.
//
// There is no fallback without it: an import that cannot load is refused
// with the reason (`agentImportUnavailable`; the log has the cause), and the
// next one tries again.

import { UI_TEXT } from '../shared/constants'
import type { UiText } from '../shared/l10n/en'
import type { AgentImportHost } from './commands/agentImportCommands'
import { lazyBundleLoader } from './lazyBundle'
import type { Logger } from './logger'
import type { AgentImportHostDeps } from './agentImportHost'

/** The injected flow and the VS Code UI entry, shipped and loaded together. */
export interface AgentImportBundle {
  readonly importFromAgents: (host: AgentImportHost, table: UiText, locale: string) => Promise<void>
  readonly runAgentImport: (
    host: AgentImportHostDeps,
    table: UiText,
    locale: string,
  ) => Promise<void>
}

/** Whether a required module exports both import entries. */
export function isAgentImportBundle(value: unknown): value is AgentImportBundle {
  return (
    typeof value === 'object' &&
    value !== null &&
    'importFromAgents' in value &&
    typeof value.importFromAgents === 'function' &&
    'runAgentImport' in value &&
    typeof value.runAgentImport === 'function'
  )
}

export interface AgentImportLoaderDeps {
  /** dist/agentImport.js beside the running bundle. */
  readonly bundlePath: string
  readonly log: Logger
  /** How the bundle is loaded: Node's `require` unless a test hands in the module. */
  readonly loadBundle?: ((file: string) => unknown) | undefined
}

/** The bundle, required the first time it is asked for and kept from then on. */
export function agentImportLoader(deps: AgentImportLoaderDeps): () => AgentImportBundle {
  return lazyBundleLoader({
    ...deps,
    log: {
      trace: (message) => {
        deps.log.trace(message)
      },
      info: (message) => {
        deps.log.info(message)
      },
      warn: (message) => {
        deps.log.warn(message)
      },
      error: (message) => {
        deps.log.error(
          message.includes('does not export')
            ? 'The import bundle does not export the import'
            : 'The import bundle could not be loaded',
        )
      },
    },
    isBundle: isAgentImportBundle,
    label: 'import bundle',
    unavailable: () => UI_TEXT.agentImportUnavailable,
  })
}

src/host/agentImportHost.ts:
// The VS Code side of "Import from other agents" (M83, PLAN.md D49): the
// pickers, the read-only preview, the modals, unsaved target edits.
// Activation retains only `runAgentImport`, the loader shim. The UI entry
// and the scan, plan and writes load together through `agentImportEntry.ts`
// in the existing import bundle on the first import.

import { homedir } from 'node:os'
import * as vscode from 'vscode'
import type { AgentImportBundle } from './agentImportBundle'
import type { AgentImportHost, AgentImportSourceChoice } from './commands/agentImportCommands'
import type { EditedFile } from '../core/verify/diagnosticsReport'
import type { WorkspaceEditRecorder } from '../core/verify/workspaceEdits'
import { UI_TEXT } from '../shared/constants'
import { uiLocale } from '../shared/l10n/text'
import type { Logger } from './logger'
import * as z from 'zod/mini'

export interface AgentImportHostDeps {
  readonly workspaceRoot: string | undefined
  readonly isActive: () => boolean
  /** The window's first folder as VS Code names it now. */
  readonly currentRoot: () => string | undefined
  readonly captureOwner?: () => WorkspaceEditRecorder | undefined
  readonly beginEdit?: (
    file: EditedFile,
    owner: WorkspaceEditRecorder | undefined,
  ) => (wasWritten: boolean) => void
  /** The checkpoint lease and storage guard for project writes (M86); never recorded. */
  readonly editProject: AgentImportHost['editProject']
  readonly beforeProjectWrite: AgentImportHost['beforeProjectWrite']
  /** Muse Code's settings file where `muse serve` reads it. */
  readonly museSettingsPath: () => string
  /** Opens text as a read-only document titled by its path's last segment. */
  readonly openDocument: (title: string, content: string) => Promise<void>
  /** The import's bundle, loaded on the first import. */
  readonly bundle: () => AgentImportBundle
  readonly log: Logger
}

interface SourceChoice extends vscode.QuickPickItem {
  readonly choice: AgentImportSourceChoice
}

const UNTITLED_SCHEME = 'untitled'

/** Built when asked, so the labels come from the table installed at activation. */
function sourceChoices(): readonly SourceChoice[] {
  return [
    { label: UI_TEXT.agentImportSourceAll, choice: 'all' },
    { label: UI_TEXT.importSourceClaude, choice: 'claudeCode' },
    { label: UI_TEXT.importSourceCodex, choice: 'codex' },
    { label: UI_TEXT.agentImportSourceCursor, choice: 'cursor' },
  ]
}

const configSchema = z.looseObject({
  mcpServers: z.optional(z.record(z.string(), z.unknown())),
  hooks: z.optional(z.record(z.string(), z.array(z.unknown()))),
})

/** Merge only imported members into the live document; preserve existing servers and unrelated settings. */
function mergedConfig(
  current: string,
  additions: string,
): { readonly text: string } | { readonly reason: 'exists' | 'unreadable' } {
  try {
    const prior = configSchema.parse(current.trim() === '' ? {} : JSON.parse(current))
    const added = configSchema.parse(JSON.parse(additions))
    if (
      Object.keys(added.mcpServers ?? {}).some((name) =>
        Object.hasOwn(prior.mcpServers ?? {}, name),
      )
    )
      return { reason: 'exists' }
    const events = new Set([...Object.keys(prior.hooks ?? {}), ...Object.keys(added.hooks ?? {})])
    return {
      text: JSON.stringify(
        {
          ...added,
          ...prior,
          ...(added.mcpServers !== undefined && {
            mcpServers: { ...added.mcpServers, ...prior.mcpServers },
          }),
          ...(added.hooks !== undefined && {
            hooks: Object.fromEntries(
              [...events].map((event) => [
                event,
                [...(prior.hooks?.[event] ?? []), ...(added.hooks?.[event] ?? [])],
              ]),
            ),
          }),
        },
        undefined,
        2,
      ),
    }
  } catch {
    return { reason: 'unreadable' }
  }
}

export async function runAgentImport(deps: AgentImportHostDeps): Promise<void> {
  // Only this shim is retained by activation; the existing UI implementation
  // is exported to the import bundle and is tree-shaken from the shim's caller.
  await deps.bundle().runAgentImport(deps, UI_TEXT, uiLocale())
}

export async function runAgentImportUi(deps: AgentImportHostDeps): Promise<void> {
  // Load the bundle first: a window without it says so before any picker opens.
  const { importFromAgents } = deps.bundle()
  // Capture this exact live session before any queue, picker or filesystem await.
  const owner = deps.captureOwner?.()
  const beginEdit = deps.beginEdit
  await importFromAgents(
    {
      platform: process.platform,
      homeDir: homedir(),
      environment: process.env,
      workspaceRoot: deps.workspaceRoot,
      workspaceRoots: () =>
        vscode.workspace.workspaceFolders
          ?.filter((folder) => folder.uri.scheme === 'file')
          .map((folder) => folder.uri.fsPath) ??
        (deps.workspaceRoot === undefined ? [] : [deps.workspaceRoot]),
      currentRoot: deps.currentRoot,
      isWorkspaceTrusted: () => vscode.workspace.isTrusted,
      isActive: deps.isActive,
      museSettingsFile: deps.museSettingsPath(),
      editProject: deps.editProject,
      beforeProjectWrite: deps.beforeProjectWrite,
      ...(beginEdit !== undefined && { beginProjectEdit: (file) => beginEdit(file, owner) }),
      pickSource: async () => {
        const picked = await vscode.window.showQuickPick(sourceChoices(), {
          title: UI_TEXT.agentImportSourceTitle,
          ignoreFocusOut: true,
        })
        return picked?.choice
      },
      pickCandidates: async (items) => {
        const picked = await vscode.window.showQuickPick(
          items.map((item) => ({ ...item })),
          {
            canPickMany: true,
            title: UI_TEXT.agentImportPickTitle,
            placeHolder: UI_TEXT.agentImportPickPlaceholder,
            matchOnDescription: true,
            matchOnDetail: true,
            ignoreFocusOut: true,
          },
        )
        return picked?.map((item) => item.id)
      },
      openPreview: deps.openDocument,
      // Not modal: the preview beside it stays readable and scrollable while it asks.
      confirmImport: async (message) =>
        (await vscode.window.showInformationMessage(message, UI_TEXT.agentImportConfirmAction)) ===
        UI_TEXT.agentImportConfirmAction,
      offerEdit: async (message) => {
        const picked = await vscode.window.showInformationMessage(
          message,
          UI_TEXT.agentImportEditAction,
          UI_TEXT.agentImportOpenFile,
        )
        if (picked === UI_TEXT.agentImportEditAction) {
          return 'edit'
        }
        return picked === UI_TEXT.agentImportOpenFile ? 'open' : undefined
      },
      openTarget: async (absolutePath, isExisting, isStillSafe, canApply, text) => {
        if (!(await isStillSafe()) || !canApply()) return false
        const file = vscode.Uri.file(absolutePath)
        const document = await vscode.workspace.openTextDocument(
          isExisting ? file : file.with({ scheme: UNTITLED_SCHEME }),
        )
        if (!(await isStillSafe()) || !canApply()) return false
        await vscode.window.showTextDocument(document, { preview: false })
        if (text === undefined) return true
        const content = mergedConfig(document.getText(), text)
        if ('reason' in content) {
          void vscode.window.showWarningMessage(
            content.reason === 'exists'
              ? UI_TEXT.agentImportSkippedExists
              : UI_TEXT.agentImportSkippedUnreadable,
          )
          return false
        }
        const version = document.version
        if (!(await isStillSafe()) || !canApply() || document.version !== version) return false
        const edit = new vscode.WorkspaceEdit()
        edit.replace(
          document.uri,
          new vscode.Range(document.positionAt(0), document.positionAt(document.getText().length)),
          content.text,
        )
        // The edit stays dirty: the user reviews and saves it at this exact target.
        return await vscode.workspace.applyEdit(edit)
      },
      showInformation: (message) => {
        void vscode.window.showInformationMessage(message)
      },
      showWarning: (message) => {
        void vscode.window.showWarningMessage(message)
      },
      log: deps.log,
    },
    UI_TEXT,
    uiLocale(),
  )
}

src/host/auth/accountHost.ts:
// Muse Code's experimental account methods on a short-lived `muse serve`
// that owns no conversation (M55; PLAN.md D26, 2026-09-27): the device
// sign-in, `account/read` (which credential the CLI would use) and
// `account/logout`. The chat host is not started with `experimentalApi`, so
// these always get a process of their own, closed when they finish. The
// extension never sends its Model API key to it, and never keeps, logs or
// shows the account's `label` (an e-mail address) or `avatarUrl`.

import { spawnMspConnection, type Connection } from '@muse-code/sdk'
import * as z from 'zod/mini'
import { wireWordForLog } from '../../core/logging'
import { unlessAborted, withDeadline } from '../../core/timeouts'
import {
  MSP_CLIENT_NAME,
  MSP_HANDSHAKE_TIMEOUT_MS,
  MUSE_ACCOUNT_LOGOUT,
  MUSE_ACCOUNT_READ,
  MUSE_ACCOUNT_STATES,
} from '../../shared/constants'
import type { MuseCodeBackendManager } from '../backend/museCodeBackendManager'
import type { Logger } from '../logger'

// `AccountState` as captured (1.3.0 and 1.4.0): `label` and `avatarUrl` are
// not in the schema, so parsing drops them.
const accountStateSchema = z.object({
  state: z.string(),
  credentialRequired: z.boolean(),
})

export type AccountState = z.infer<typeof accountStateSchema>

export interface AccountSession {
  /** `closed` settles when the host's output ends: it exited or died. */
  readonly connection: Pick<Connection, 'request' | 'onNotification' | 'closed'>
  readonly close: () => Promise<unknown>
}

/** Starts one short-lived host; `signal` cancels the start. */
export type ConnectAccountHost = (signal: AbortSignal) => Promise<AccountSession>

/** The error's name only: a CLI message can carry a path or an account. */
function errorName(error: unknown): string {
  return error instanceof Error ? error.name : 'unknown error'
}

/** Whether a stored credential (a sign-in or a key the CLI saved) is the one in use. */
export function isStoredSignIn(account: AccountState): boolean {
  return (
    account.state === MUSE_ACCOUNT_STATES.accountLogin ||
    account.state === MUSE_ACCOUNT_STATES.apiKey
  )
}

/**
 * The answer every captured `account/read` after a sign-out gave
 * (docs/certification/sign-in-detection.md). Nothing else counts as signed
 * out: `envKey` masks the stored lane, and other answers were never
 * captured (AGENTS.md rule 13, the review of PR #49).
 */
export function isCapturedSignedOut(account: AccountState): boolean {
  return account.state === MUSE_ACCOUNT_STATES.loggedOut && account.credentialRequired
}

type AccountConnection = AccountSession['connection']

/** An account method's `AccountState` answer; undefined when it failed or came in another shape. */
async function requestAccount(
  connection: AccountConnection,
  method: string,
): Promise<AccountState | undefined> {
  try {
    const result = accountStateSchema.safeParse(
      await withDeadline(
        connection.request(method, {}),
        MSP_HANDSHAKE_TIMEOUT_MS,
        `Muse Code did not answer ${method} in time`,
      ),
    )
    return result.success ? result.data : undefined
  } catch {
    return undefined
  }
}

/** `account/read` on an open host; undefined when the host cannot say. */
export async function readAccountState(
  connection: AccountConnection,
): Promise<AccountState | undefined> {
  return await requestAccount(connection, MUSE_ACCOUNT_READ)
}

/**
 * `use` on one short-lived host, closed afterwards; `fallback` when it
 * cannot start, or once `ended` aborts (the window closing), which closes
 * the host at once instead of waiting for its answer.
 */
async function onAccountHost<T>(
  connect: ConnectAccountHost,
  log: Logger,
  ended: AbortSignal,
  fallback: T,
  use: (connection: AccountConnection) => Promise<T>,
): Promise<T> {
  let session: AccountSession
  try {
    session = await connect(ended)
  } catch (error: unknown) {
    log.warn(`The Muse Code account host could not start: ${errorName(error)}`)
    return fallback
  }
  try {
    return (await unlessAborted(use(session.connection), ended)) ?? fallback
  } finally {
    try {
      await session.close()
    } catch (error: unknown) {
      log.warn(`The Muse Code account host did not close cleanly: ${errorName(error)}`)
    }
  }
}

/** One short-lived host asked `account/read`; undefined when it could not start or say. */
export async function probeAccount(
  connect: ConnectAccountHost,
  log: Logger,
  ended: AbortSignal,
): Promise<AccountState | undefined> {
  return await onAccountHost(connect, log, ended, undefined, readAccountState)
}

/**
 * MSP `account/logout` on a short-lived host, confirmed by `account/read`:
 * `confirmed` only on the captured signed-out answer; `unconfirmed` when the
 * host could not start or refused, or answered anything else: a stored
 * credential, `envKey` (`META_API_KEY`, which no logout can unset, masks
 * the stored lane), or a state never captured.
 */
export async function logOutAccount(
  connect: ConnectAccountHost,
  log: Logger,
  ended: AbortSignal,
): Promise<'confirmed' | 'unconfirmed'> {
  return await onAccountHost<'confirmed' | 'unconfirmed'>(
    connect,
    log,
    ended,
    'unconfirmed',
    async (connection) => {
      const answer = await requestAccount(connection, MUSE_ACCOUNT_LOGOUT)
      const after = answer === undefined ? undefined : await readAccountState(connection)
      // The state word only, and only in the shape of one: its vocabulary
      // is open (the review of PR #49).
      if (after === undefined || !isCapturedSignedOut(after)) {
        log.warn(
          after?.state === MUSE_ACCOUNT_STATES.envKey
            ? 'Muse Code runs on META_API_KEY, which hides whether account/logout cleared the stored sign-in'
            : `Muse Code did not confirm account/logout (${after === undefined ? 'no answer' : wireWordForLog(after.state)})`,
        )
        return 'unconfirmed'
      }
      log.info(`Muse Code signed out through account/logout (now ${after.state})`)
      return 'confirmed'
    },
  )
}

/**
 * The window's short-lived `account/read` and `account/logout` hosts, which
 * end together when it closes (the review of PR #49): a probe still waiting,
 * or one Cancel left behind, is closed rather than left running, and none
 * starts afterwards.
 */
export class AccountHosts {
  private readonly windowClosing = new AbortController()

  public constructor(
    private readonly connect: ConnectAccountHost,
    private readonly log: Logger,
  ) {}

  public async probe(): Promise<AccountState | undefined> {
    return await probeAccount(this.connect, this.log, this.windowClosing.signal)
  }

  public async logOut(): Promise<'confirmed' | 'unconfirmed'> {
    return await logOutAccount(this.connect, this.log, this.windowClosing.signal)
  }

  public close(): void {
    this.windowClosing.abort()
  }
}

/** Start a dedicated experimental MSP process. Keep it separate from chat. */
export async function connectAccountSession(
  backend: MuseCodeBackendManager,
  extensionVersion: string,
  log: Logger,
  workspaceRoot: string | undefined,
  signal: AbortSignal,
): Promise<AccountSession> {
  const isAborted = () => signal.aborted
  if (isAborted()) {
    throw new Error('The Muse Code account host was cancelled')
  }
  backend.invalidateLaunch()
  const resolution = backend.resolveLaunch()
  if (!resolution.ok) {
    throw new Error(resolution.reason)
  }
  await backend.admitWorkspaceHost()
  if (isAborted()) {
    throw new Error('The Muse Code account host was cancelled')
  }
  let isStderrReported = false
  const handshake = spawnMspConnection({
    command: resolution.launch.command,
    args: resolution.launch.args,
    ...(workspaceRoot !== undefined && { cwd: workspaceRoot }),
    env: backend.childEnvironment(),
    onStderr: () => {
      if (isStderrReported) {
        return
      }

      log.warn('The Muse Code account host wrote to stderr')
      isStderrReported = true
    },
  })
  try {
    // Not `Promise.withResolvers`, which Node 20 lacks (PLAN.md M62).
    const spawned = await unlessAborted(
      withDeadline(
        handshake.initialize({
          clientInfo: { name: MSP_CLIENT_NAME, version: extensionVersion },
          capabilities: { experimentalApi: true, userInputDialogs: false },
        }),
        MSP_HANDSHAKE_TIMEOUT_MS,
        'The Muse Code account host did not start in time',
      ),
      signal,
    )
    if (spawned === undefined || isAborted()) {
      throw new Error('The Muse Code account host was cancelled')
    }
    if (!spawned.initializeResult.experimentalApi) {
      throw new Error('This Muse Code version does not offer its account methods')
    }
    return { connection: spawned.connection, close: () => spawned.close() }
  } catch (error: unknown) {
    await handshake.close()
    throw error
  }
}

src/host/auth/authService.ts:
// Credential state for both backends, shared by every surface (PLAN.md D1,
// M7). The backend selection decides which credential counts: the Muse
// Code CLI's own sign-in (subscription) for the CLI backend, the pasted
// Model API key for the Model API backend; they are never mixed. `status`
// is the estimate from the credential facts (the CLI's from its credential
// file's structure, confirmed by the CLI when that is ambiguous, PLAN.md
// D26); a backend's own `authRequired` turn error overrides it through
// `markAuthRequired`. All VS Code interactions (terminals, input boxes) are
// injected so the flow is unit-tested end to end.

import { isCliSignInConsulted, selectBackend } from '../../core/backendSelection'
import type { BackendKind } from '../../core/agent/agentBackend'
import type { CliSignIn } from '../../core/backends/musecode/credentialFile'
import { wireWordForLog } from '../../core/logging'
import { unlessAborted } from '../../core/timeouts'
import {
  type BackendMode,
  MUSE_INSTALL_POLL_INTERVAL_MS,
  MUSE_INSTALL_TIMEOUT_MS,
  MUSE_LOGOUT_ARGS,
  UI_TEXT,
} from '../../shared/constants'
import { fill } from '../../shared/l10n/text'
import type { AuthStatus, HostToWebviewMessage, SignInMethod } from '../../shared/protocol'
import type { Logger } from '../logger'
import { isCliSignedIn } from './cliAccount'
import type { CapturedSignInEnding, DeviceSignInEnded, DeviceSignInOutcome } from './deviceSignIn'
import type { CredentialStore } from './credentialStore'

export interface AuthBackendFacts {
  /** The CLI path to run for `login` / `logout`, or the reason it is absent. */
  readonly resolveCli: () =>
    | { readonly ok: true; readonly cliPath: string }
    | { readonly ok: false; readonly reason: string }
  /**
   * The CLI's own sign-in: its credential file's structure, and the CLI's
   * `account/read` when that cannot say. With `isUserAction` macOS may ask
   * too (its host reads the Keychain); otherwise it does not.
   */
  readonly cliSignIn: (isUserAction: boolean) => Promise<CliSignIn>
  /**
   * Leaves an unanswered probe behind (Cancel): the next question asks
   * afresh, and a remembered answer stands.
   */
  readonly abandonCliProbe: () => void
  /**
   * Drops everything the CLI said, the remembered answer too (a sign-out, a
   * new sign-in, Check again): the next question asks afresh.
   */
  readonly forgetCliAnswers: () => void
  /** Where the CLI keeps its sign-in, named when the file stops it starting. */
  readonly credentialFilePath: () => string
  /** The credential file's modification time; undefined when there is none. */
  readonly credentialFileModifiedAt: () => number | undefined
  readonly hasEnvironmentKey: () => boolean
  /** `museSpark.backend`. */
  readonly getBackendMode: () => BackendMode
  /**
   * Stop the running hosts so the next turn spawns the right one afresh;
   * with `isConversationEnding` (sign-out) the conversations are not resumed.
   */
  readonly restartBackend: (isConversationEnding: boolean) => Promise<void>
  /**
   * The CLI's own sign-out, MSP `account/logout` on a short-lived host: true
   * only when `account/read` then gives the captured signed-out answer. A
   * host that could not start or refused, `envKey` (META_API_KEY hides the
   * stored lane), a stored credential or a state never captured is false.
   * Never rejects.
   */
  readonly logOutCli: () => Promise<boolean>
}

export interface AuthServiceDeps {
  readonly backend: AuthBackendFacts
  readonly credentials: CredentialStore
  /** Extension-private, credential-free state retained across activation. */
  readonly logoutHold: {
    readonly get: () => boolean
    readonly set: (isHeld: boolean) => PromiseLike<void>
  }
  readonly runInTerminal: (cliPath: string, args: readonly string[]) => void | Promise<void>
  readonly installCommand: string
  readonly runInstallerInTerminal: () => void | Promise<void>
  readonly runDeviceSignIn: (
    signal: AbortSignal,
    onCode: (url: string, code: string) => void,
  ) => Promise<DeviceSignInOutcome>
  /** Returns the pasted key, or undefined when the user dismissed the box. */
  readonly promptForApiKey: () => Promise<string | undefined>
  readonly broadcast: (message: HostToWebviewMessage) => void
  readonly sleep: (ms: number) => Promise<void>
  readonly now: () => number
  readonly log: Logger
}

export interface AuthSnapshot {
  readonly status: AuthStatus
  readonly detail: string | undefined
  /** The backend the window uses (known once the facts are in). */
  readonly backend?: BackendKind | undefined
  /** The sign-in paths the gate offers. */
  readonly methods?: readonly SignInMethod[] | undefined
  readonly verificationUrl?: string | undefined
  readonly userCode?: string | undefined
  readonly hasCli?: boolean | undefined
  readonly hasCliSession?: boolean | undefined
  readonly installState?: 'running' | 'failed' | undefined
}

/**
 * What a conversation needs from the service: the controller's dependency
 * type, so a test hands it a plain object with exactly these members.
 */
export type AuthPort = Pick<
  AuthService,
  | 'current'
  | 'backend'
  | 'admissionGeneration'
  | 'toMessage'
  | 'signIn'
  | 'installMuseCode'
  | 'cancelSignIn'
  | 'signOut'
  | 'refresh'
  | 'checkAgain'
  | 'markAuthRequired'
  | 'markBackendError'
>

/**
 * The sign-in story for the log (M39): the state, the backend it chose and,
 * for an error, why (`loggedDetail`, which may stand in for a detail that
 * names a path). Written when the state or the backend changes.
 */
function signInLine(snapshot: AuthSnapshot, loggedDetail: string | undefined): string {
  const backend = snapshot.backend === undefined ? '' : ` on the ${snapshot.backend} backend`
  const why = loggedDetail !== undefined && snapshot.status === 'error' ? `: ${loggedDetail}` : ''
  return `Sign-in state: ${snapshot.status}${backend}${why}`
}

// What the log says in place of the unsupported-file message, which names
// the credential file's full path under the user's profile (the review of
// PR #49); the panel still shows the path.
const UNSUPPORTED_FILE_LOGGED =
  'the Muse Code credential file is in a format Muse Code cannot start with on this system'

/** The browser sign-in's pre-check found a file the sign-in host could not start with. */
const UNSUPPORTED_FILE = Symbol('unsupported credential file')

/**
 * Why a device sign-in the host ended did not sign in (read when shown, D33):
 * each captured ending in its own words, any other as Muse Code named it
 * (AGENTS.md rule 13).
 */
function endedSignInText(
  ending: Exclude<CapturedSignInEnding, 'cancelled'> | DeviceSignInEnded,
): string {
  switch (ending) {
    case 'expired': {
      return UI_TEXT.signInExpired
    }
    case 'denied': {
      return UI_TEXT.signInDenied
    }
    case 'failed': {
      return UI_TEXT.signInSaveFailed
    }
    default: {
      return fill(UI_TEXT.signInEnded, { outcome: ending.endedAs })
    }
  }
}

/** One browser sign-in, as its steps see it. */
interface CliSignInFlow {
  /** What the panel showed when the flow began. */
  readonly initial: AuthSnapshot
  readonly epoch: number
  readonly wasLogoutHeld: boolean
  /** Aborted by Cancel and by a sign-out. */
  readonly abort: AbortController
  /** Aborted when a sign-out starts; Cancel leaves it. */
  readonly signOut: AbortSignal
  /** The credential file's modification time when the flow began. */
  readonly fileBefore: number | undefined
  /** The device code was shown: the browser may have approved it. */
  isCodeShown: boolean
}

export class AuthService {
  private snapshot: AuthSnapshot = { status: 'checking', detail: undefined }
  /** The browser sign-in in flight: a second click joins it (PLAN.md D25). */
  private deviceSignIn: Promise<AuthSnapshot> | undefined
  private installPromise: Promise<AuthSnapshot> | undefined
  /** Every panel joins one sign-out; the hold cannot be released by an earlier caller. */
  private signOutPromise: Promise<AuthSnapshot> | undefined
  private deviceAbort: AbortController | undefined
  /**
   * A sign-out invalidates key prompts already open in any surface, and
   * refreshes begun before it ended (it moves on as it starts and ends).
   */
  private signOutEpoch = 0
  /** Aborted as a sign-out starts: a finishing sign-in stops waiting on the CLI. */
  private signOutStarts = new AbortController()
  /** Invalidates selectors across a same-kind sign-out/sign-in or key replacement. */
  private admissionGenerationValue = 0
  /** Sign-out waits for accepted key writes and backend restarts before ending sessions. */
  private readonly keyActivations = new Set<Promise<AuthSnapshot>>()
  /** Every Check again pressed while one runs joins it: one question to the CLI. */
  private checkingAgain: Promise<AuthSnapshot> | undefined
  private isLogoutHeld: boolean
  private isSigningOut = false
  private isLogoutPersistenceFailed = false
  /** The window is closing: no browser sign-in starts any more. */
  private isStopped = false
  /**
   * Every publication's place in time (the review of PR #49): a refresh
   * takes a ticket as it starts and publishes only if nothing that started
   * or was published after it has published first.
   */
  private tickets = 0
  private publishedTicket = 0
  /** The browser sign-in's code is on screen: a refresh leaves the panel to that flow. */
  private isDeviceFlowWaiting = false
  /**
   * The backend conversations were last admitted on: the backend of the
   * last signed-in state published, until a restart ends its conversations.
   * The panel may show another state meanwhile (a sign-in's code) while a
   * conversation still runs there.
   */
  private liveBackend: BackendKind | undefined
  /** Moves each time `liveBackend` is recorded: a restart clears only what it ended. */
  private liveVersion = 0
  /** Counts logout-hold writes: only the latest one's outcome is kept. */
  private holdWrites = 0

  public constructor(private readonly deps: AuthServiceDeps) {
    this.isLogoutHeld = deps.logoutHold.get()
  }

  private async setLogoutHold(isHeld: boolean): Promise<boolean> {
    this.isLogoutHeld = isHeld
    // Only the latest write says whether the hold is saved: an older one
    // that settles late speaks for a value that no longer holds (the review
    // of PR #49).
    this.holdWrites += 1
    const write = this.holdWrites
    try {
      await this.deps.logoutHold.set(isHeld)
      if (write === this.holdWrites) {
        this.isLogoutPersistenceFailed = false
      }
      return true
    } catch {
      if (write === this.holdWrites) {
        this.isLogoutPersistenceFailed = true
      }
      this.deps.log.warn('Muse Code sign-out state could not be saved')
      return false
    }
  }

  private logoutDetail(): string {
    return this.isLogoutPersistenceFailed ? UI_TEXT.signOutHoldFailed : UI_TEXT.signOutPending
  }

  /**
   * Whether a sign-out runs now: read afresh after an await, which the
   * compiler's narrowing of `isSigningOut` does not see.
   */
  private isSignOutRunning(): boolean {
    return this.isSigningOut
  }

  /**
   * Stops the running hosts; with `isConversationEnding` their conversations
   * end too, so none runs on any backend any more. Rejects as the restart
   * does.
   */
  private async restartHosts(isConversationEnding: boolean): Promise<void> {
    // Cleared after the restart, so a failed one leaves the record of the
    // conversations still running; and only if no signed-in state was
    // published meanwhile, whose conversations did not end (the review of
    // PR #49).
    const live = this.liveVersion
    await this.deps.backend.restartBackend(isConversationEnding)
    if (isConversationEnding && live === this.liveVersion) {
      this.liveBackend = undefined
    }
  }

  private async stopBackendForSignOut(): Promise<boolean> {
    try {
      await this.restartHosts(true)
      return true
    } catch {
      this.deps.log.warn('Muse Code backend could not stop during sign-out')
      return false
    }
  }

  /** Whether publishing `next` moves signed-in conversations to another backend. */
  private isBackendSwitch(next: AuthSnapshot): boolean {
    return (
      next.status === 'signedIn' &&
      this.liveBackend !== undefined &&
      next.backend !== this.liveBackend
    )
  }

  /**
   * The one way a state is published that may sign in on another backend
   * than conversations run on (the review of PR #49): new hosts are gated
   * and that backend's conversations end first, as a device sign-in's
   * success does, then `next` is published if it still may be (`isCurrent`,
   * and no newer publication meanwhile).
   */
  private async publishSelection(
    next: AuthSnapshot,
    ticket: number = this.nextTicket(),
    isCurrent: () => boolean = () => true,
  ): Promise<AuthSnapshot> {
    if (!this.isBackendSwitch(next)) {
      return this.set(next, ticket)
    }
    this.deps.log.info(
      `Conversations move from the ${String(this.liveBackend)} backend to the ${String(next.backend)} backend: ending them first`,
    )
    this.admissionGenerationValue += 1
    this.set(
      {
        ...this.snapshot,
        status: 'checking',
        detail: undefined,
        verificationUrl: undefined,
        userCode: undefined,
      },
      ticket,
    )
    try {
      await this.restartHosts(true)
    } catch {
      this.deps.log.warn('The running backend could not stop before switching backends')
      // The failure is published under the same guards as the success: a
      // newer state, or a sign-out, published meanwhile stands (Codex on
      // 86d63652).
      return ticket < this.publishedTicket || !isCurrent()
        ? this.snapshot
        : this.set(
            {
              ...this.snapshot,
              status: 'error',
              detail: UI_TEXT.signOutStopFailed,
              installState:
                this.snapshot.installState === 'running' ? 'failed' : this.snapshot.installState,
            },
            ticket,
          )
    }
    return ticket < this.publishedTicket || !isCurrent() ? this.snapshot : this.set(next, ticket)
  }

  private nextTicket(): number {
    this.tickets += 1
    return this.tickets
  }

  /**
   * A refresh's answer, unless something newer was published while it was
   * asked, or a browser sign-in's code is on screen: its facts may be older
   * than what the panel shows (the review of PR #49).
   */
  private async publishRefresh(
    ticket: number,
    epoch: number,
    snapshot: AuthSnapshot,
  ): Promise<AuthSnapshot> {
    return ticket < this.publishedTicket || this.isDeviceFlowWaiting
      ? this.snapshot
      : await this.publishSelection(snapshot, ticket, () => epoch === this.signOutEpoch)
  }

  private set(snapshot: AuthSnapshot, ticket = this.nextTicket()): AuthSnapshot {
    const previous = this.snapshot
    this.snapshot = snapshot
    this.publishedTicket = ticket
    if (snapshot.status === 'signedIn') {
      this.liveBackend = snapshot.backend
      this.liveVersion += 1
    }
    if (previous.status !== snapshot.status || previous.backend !== snapshot.backend) {
      const isUnsupportedFile =
        snapshot.detail !== undefined && snapshot.detail === this.unsupportedFileText()
      this.deps.log.info(
        signInLine(snapshot, isUnsupportedFile ? UNSUPPORTED_FILE_LOGGED : snapshot.detail),
      )
    }
    this.deps.broadcast(this.toMessage())
    return this.snapshot
  }

  /**
   * The CLI's own credential as the gate counts it: `META_API_KEY` in its
   * environment, or its sign-in, including one only the CLI could confirm.
   * With the key set no file is looked at: `muse serve` then starts even
   * with a version-2 file it refuses otherwise, and uses the key (captured
   * 2026-09-27, docs/certification/sign-in-detection.md).
   */
  private async cliCredential(
    isUserAction: boolean,
  ): Promise<{ readonly hasCliSession: boolean; readonly isUnsupportedFile: boolean }> {
    if (this.deps.backend.hasEnvironmentKey()) {
      return { hasCliSession: true, isUnsupportedFile: false }
    }
    const signIn = await this.deps.backend.cliSignIn(isUserAction)
    return {
      hasCliSession: isCliSignedIn(signIn),
      isUnsupportedFile: signIn === 'unsupportedHere',
    }
  }

  private async hasCliCredential(isUserAction: boolean): Promise<boolean> {
    const { hasCliSession } = await this.cliCredential(isUserAction)
    return hasCliSession
  }

  /**
   * The backend selection from the current facts. With the backend forced
   * to the Model API the CLI is not asked at all (Codex on 328efb52).
   */
  private async choose(isUserAction: boolean) {
    const cli = this.deps.backend.resolveCli()
    const setting = this.deps.backend.getBackendMode()
    const { hasCliSession, isUnsupportedFile } = isCliSignInConsulted(setting)
      ? await this.cliCredential(isUserAction)
      : { hasCliSession: false, isUnsupportedFile: false }
    return {
      cli,
      hasCliSession,
      isUnsupportedFile,
      choice: selectBackend({
        setting,
        hasCli: cli.ok,
        hasCliSession,
        hasStoredKey: (await this.deps.credentials.getApiKey()) !== undefined,
      }),
    }
  }

  /** A macOS credential file on Windows or Linux: `muse serve` exits at startup. */
  private unsupportedFileText(): string {
    return fill(UI_TEXT.cliCredentialUnsupported, {
      path: this.deps.backend.credentialFilePath(),
    })
  }

  /** One device-code sign-in process, however often the button is pressed (D25). */
  private async joinDeviceSignIn(): Promise<AuthSnapshot> {
    if (this.deviceSignIn !== undefined) {
      return await this.deviceSignIn
    }
    // A click whose pre-flight questions outlived the window starts no host
    // after the backends stopped (the review of PR #49).
    if (this.isStopped) {
      return this.snapshot
    }
    this.deviceSignIn = this.signInWithCli()
    try {
      return await this.deviceSignIn
    } finally {
      this.deviceSignIn = undefined
    }
  }

  /**
   * The flow's pre-check and the device runner, while the flow owns the
   * panel: a refresh meanwhile does not publish over its code (the review of
   * PR #49).
   */
  private async awaitDeviceRunner(
    flow: CliSignInFlow,
  ): Promise<DeviceSignInOutcome | typeof UNSUPPORTED_FILE> {
    const { abort } = flow
    this.isDeviceFlowWaiting = true
    try {
      // The sign-in host could not start with that file either. A probe the
      // CLI never answers must not hold Cancel or sign-out (the review of
      // PR #49): the look ends with the flow's own signal.
      const credential = await unlessAborted(this.cliCredential(false), abort.signal)
      if (credential?.isUnsupportedFile === true) {
        return UNSUPPORTED_FILE
      }
      // A cancel or sign-out during that look ends the flow before it starts.
      return abort.signal.aborted
        ? 'cancelled'
        : await this.deps.runDeviceSignIn(abort.signal, (url, code) => {
            if (abort.signal.aborted) {
              return
            }
            flow.isCodeShown = true
            this.set({ ...this.snapshot, verificationUrl: url, userCode: code })
          })
    } finally {
      this.isDeviceFlowWaiting = false
    }
  }

  private async signInWithCli(): Promise<AuthSnapshot> {
    const flow: CliSignInFlow = {
      initial: this.snapshot,
      epoch: this.signOutEpoch,
      wasLogoutHeld: this.isLogoutHeld,
      abort: new AbortController(),
      signOut: this.signOutStarts.signal,
      fileBefore: this.deps.backend.credentialFileModifiedAt(),
      isCodeShown: false,
    }
    const { abort } = flow
    const cli = this.deps.backend.resolveCli()
    if (!cli.ok) {
      return await this.finishFailedCliSignIn(flow, 'noCli', cli.reason, 'warning')
    }
    // Cancel and sign-out reach this flow from here on, before any await.
    this.deviceAbort = abort
    this.set({ ...this.snapshot, status: 'signingIn', detail: UI_TEXT.signInWaiting })
    try {
      const outcome = await this.awaitDeviceRunner(flow)
      if (outcome === UNSUPPORTED_FILE) {
        return await this.finishFailedCliSignIn(
          flow,
          'error',
          this.unsupportedFileText(),
          'warning',
        )
      }
      if (outcome === 'cancelled') {
        return await this.finishCancelledCliSignIn(flow)
      }
      if (outcome === 'timedOut') {
        return await this.finishFailedCliSignIn(
          flow,
          'signedOut',
          UI_TEXT.signInTimedOut,
          'warning',
        )
      }
      if (outcome !== 'signedIn') {
        return await this.finishFailedCliSignIn(
          flow,
          'signedOut',
          endedSignInText(outcome),
          'warning',
        )
      }
      if (this.isSigningOut) {
        return this.snapshot
      }
      // What the CLI said before this sign-in no longer holds, even where
      // the file did not change (a Keychain sign-in; the review of PR #49).
      this.deps.backend.forgetCliAnswers()
      return await this.confirmCliSignIn(flow)
    } catch (error: unknown) {
      this.deps.log.warn(
        `In-panel sign-in failed: ${error instanceof Error ? error.name : 'unknown error'}`,
      )
      return await this.finishFailedCliSignIn(flow, 'error', UI_TEXT.signInFailed, 'warning')
    } finally {
      this.deviceAbort = undefined
    }
  }

  /**
   * The device runner saw the sign-in land. Every question to the CLI here
   * yields to the flow's signal, so a sign-out (or Cancel) never waits on
   * one (the review of PR #49).
   */
  private async confirmCliSignIn(flow: CliSignInFlow): Promise<AuthSnapshot> {
    const { abort } = flow
    // After a sign-out, only the CLI's own confirmation of the new sign-in
    // (the device runner's, then the file or `account/read` here) lifts the
    // hold, and never while a key would bill instead.
    if (flow.wasLogoutHeld) {
      const hasBillingKey =
        this.deps.backend.hasEnvironmentKey() ||
        (await this.deps.credentials.getApiKey()) !== undefined
      const confirmed = hasBillingKey
        ? undefined
        : await unlessAborted(this.deps.backend.cliSignIn(true), abort.signal)
      if (abort.signal.aborted) {
        return await this.finishCancelledCliSignIn(flow)
      }
      if (confirmed !== 'signedIn') {
        return await this.refreshUnlessCancelled(flow)
      }
    }
    this.admissionGenerationValue += 1
    // A restart that fails after a newer state was published (a refresh
    // meanwhile) leaves that state standing, rather than the flow's failure
    // (Codex on 86d63652).
    const published = this.publishedTicket
    try {
      await this.restartHosts(flow.initial.status === 'signedIn')
    } catch (error: unknown) {
      if (this.publishedTicket !== published) {
        this.deps.log.warn('The backend did not restart after sign-in; a newer state stands')
        return this.snapshot
      }
      throw error
    }
    if (abort.signal.aborted) {
      return await this.finishCancelledCliSignIn(flow)
    }
    if (flow.wasLogoutHeld) {
      if (this.signOutEpoch !== flow.epoch || this.deps.backend.hasEnvironmentKey()) {
        return await this.refreshUnlessCancelled(flow)
      }
      const isHoldSaved = await this.setLogoutHold(false)
      if (!isHoldSaved) {
        return this.set({ ...this.snapshot, status: 'error', detail: UI_TEXT.signOutHoldFailed })
      }
    }
    return await this.refreshUnlessCancelled(flow)
  }

  /** A user-action refresh that ends with the flow's signal. */
  private async refreshUnlessCancelled(flow: CliSignInFlow): Promise<AuthSnapshot> {
    const refreshed = await unlessAborted(this.refresh(true), flow.abort.signal)
    return refreshed ?? (await this.finishCancelledCliSignIn(flow))
  }

  /**
   * Cancel decides the flow, but not against what the CLI saved (the review
   * of PR #49). When the credential file changed since the flow began (the
   * browser approved as Cancel was pressed), the CLI's sign-in is read
   * afresh, a Cancel being a click that may ask it. When the code was shown
   * and the file did not change, the CLI is asked afresh too: on macOS an
   * approval may land in the Keychain alone, the pointer file as it was
   * (Codex on 55b9e24c).
   */
  private async finishCancelledCliSignIn(flow: CliSignInFlow): Promise<AuthSnapshot> {
    if (this.isSigningOut) {
      return this.snapshot
    }
    const isFileChanged = this.deps.backend.credentialFileModifiedAt() !== flow.fileBefore
    if (isFileChanged) {
      return (await unlessAborted(this.refresh(true), flow.signOut)) ?? this.snapshot
    }
    if (flow.isCodeShown) {
      this.deps.backend.forgetCliAnswers()
    }
    return await this.finishFailedCliSignIn(
      flow,
      'signedOut',
      UI_TEXT.signInCancelled,
      'info',
      flow.isCodeShown,
    )
  }

  /**
   * A flow that did not sign in: its state is published at once, then, with
   * the hold on, a Model API session, or `isAskingAfresh` (a Cancel after
   * the code was shown), a refresh reads the CLI's sign-in and publishes
   * what it finds through `publishSelection`'s guards, with the ending as a
   * notice.
   */
  private async finishFailedCliSignIn(
    flow: CliSignInFlow,
    status: 'noCli' | 'signedOut' | 'error',
    detail: string,
    noticeLevel: 'info' | 'warning',
    isAskingAfresh = false,
  ): Promise<AuthSnapshot> {
    // A sign-out that cancelled this sign-in publishes its own state.
    if (this.isSigningOut) {
      return this.snapshot
    }
    const { initial } = flow
    // The code leaves the panel at once, not after the refresh below, which
    // may wait on the CLI (the review of PR #49).
    const ended = this.set({
      ...this.snapshot,
      status,
      detail,
      verificationUrl: undefined,
      userCode: undefined,
    })
    if (
      isAskingAfresh ||
      this.isLogoutHeld ||
      (initial.status === 'signedIn' && initial.backend === 'modelApi')
    ) {
      // A sign-out that starts meanwhile publishes its own state, and does
      // not wait on the question this refresh may ask (the review of PR #49).
      const refreshed = await unlessAborted(this.refresh(true), flow.signOut)
      if (refreshed === undefined) {
        return this.snapshot
      }
      this.deps.broadcast({ type: 'notice', level: noticeLevel, text: detail })
      return refreshed
    }
    return ended
  }

  private async refreshAfterCliDiscovery(epoch: number): Promise<AuthSnapshot> {
    // Auto selection may cross backends: the refresh publishes through
    // `publishSelection`, which retires the Model API conversation first.
    return epoch === this.signOutEpoch ? await this.refresh(true) : this.snapshot
  }

  private async installWithCli(): Promise<AuthSnapshot> {
    const epoch = this.signOutEpoch
    if (this.deps.backend.resolveCli().ok) {
      return await this.refreshAfterCliDiscovery(epoch)
    }
    const shouldKeepModelApi =
      this.snapshot.status === 'signedIn' && this.snapshot.backend === 'modelApi'
    let status: AuthStatus = 'installing'
    let detail: string | undefined = UI_TEXT.installWaiting
    if (this.isLogoutHeld) {
      status = this.snapshot.status
      detail = this.snapshot.detail
    } else if (shouldKeepModelApi) {
      status = 'signedIn'
      detail = undefined
    }
    this.set({
      ...this.snapshot,
      status,
      detail,
      installState: 'running',
      hasCli: false,
    })
    try {
      await this.deps.runInstallerInTerminal()
      const deadline = this.deps.now() + MUSE_INSTALL_TIMEOUT_MS
      while (this.deps.now() < deadline) {
        if (epoch !== this.signOutEpoch || this.isSigningOut) {
          return this.snapshot
        }
        if (this.deps.backend.resolveCli().ok) {
          return await this.refreshAfterCliDiscovery(epoch)
        }
        await this.deps.sleep(MUSE_INSTALL_POLL_INTERVAL_MS)
      }
      return await this.installFailed(UI_TEXT.installTimedOut, epoch)
    } catch (error: unknown) {
      this.deps.log.warn(
        `Muse Code installer terminal failed: ${error instanceof Error ? error.name : 'unknown error'}`,
      )
      return await this.installFailed(UI_TEXT.installStartFailed, epoch)
    }
  }

  private async installFailed(detail: string, epoch: number): Promise<AuthSnapshot> {
    // The install's error path publishes what it asks here only if nothing
    // newer was published while it asked (Codex on 86d63652).
    const ticket = this.nextTicket()
    const selected = await this.selectedSnapshot(true)
    if (epoch !== this.signOutEpoch || this.isSigningOut || ticket < this.publishedTicket) {
      return this.snapshot
    }
    if (this.isLogoutHeld) {
      this.deps.broadcast({ type: 'notice', level: 'warning', text: detail })
      return this.set({
        ...this.snapshot,
        status: 'error',
        detail: this.logoutDetail(),
        installState: 'failed',
      })
    }
    // Either may sign in on another backend than conversations run on.
    if (selected.hasCli === true) {
      return await this.publishSelection(selected)
    }
    const failed = await this.publishSelection({
      ...selected,
      detail,
      installState: 'failed',
    })
    if (failed.status === 'signedIn' && failed.backend === 'modelApi') {
      this.deps.broadcast({ type: 'notice', level: 'warning', text: detail })
    }
    return failed
  }

  /** Derive from current CLI, setting and SecretStorage facts. */
  private async selectedSnapshot(isUserAction: boolean): Promise<AuthSnapshot> {
    const { cli, hasCliSession, isUnsupportedFile, choice } = await this.choose(isUserAction)
    if (choice.kind === undefined) {
      return {
        status: 'noCli',
        detail: cli.ok ? undefined : cli.reason,
        backend: undefined,
        methods: choice.methods,
        hasCli: cli.ok,
        hasCliSession,
      }
    }
    // Muse Code would be used but cannot start with its credential file:
    // said by name, not left to a host that exits at every message.
    const isBlocked = choice.kind === 'museCode' && cli.ok && isUnsupportedFile
    return {
      status: isBlocked ? 'error' : choice.status,
      detail: isBlocked ? this.unsupportedFileText() : undefined,
      backend: choice.kind,
      methods: choice.methods,
      hasCli: cli.ok,
      hasCliSession,
    }
  }

  private async activateApiKey(key: string, epoch: number): Promise<AuthSnapshot> {
    this.admissionGenerationValue += 1
    const previousKey = await this.deps.credentials.getApiKey()
    if (epoch !== this.signOutEpoch || this.isSigningOut) {
      return this.snapshot
    }
    const isReplacingActiveAccount =
      this.snapshot.status === 'signedIn' &&
      this.snapshot.backend === 'modelApi' &&
      previousKey !== key.trim()
    // Stop old turns while they still read the old key. A tool round must not
    // resume after SecretStorage begins returning the replacement key.
    if (isReplacingActiveAccount) {
      await this.restartHosts(true)
    }
    if (epoch !== this.signOutEpoch) {
      return this.snapshot
    }
    await this.deps.credentials.setApiKey(key)
    if (epoch !== this.signOutEpoch) {
      return this.snapshot
    }
    if (
      !isReplacingActiveAccount &&
      (this.snapshot.status !== 'signedIn' || this.snapshot.backend !== 'museCode')
    ) {
      await this.restartHosts(false)
    }
    const selected = await this.selectedSnapshot(true)
    // A key can move conversations off Muse Code (a CLI no longer signed in).
    return epoch === this.signOutEpoch
      ? await this.publishSelection(selected, undefined, () => epoch === this.signOutEpoch)
      : this.snapshot
  }

  /**
   * The CLI's own sign-out: `account/logout` on a short-lived host, else
   * `muse logout` in a terminal (confirmed later, by the file or the CLI).
   * Returns false when that terminal could not open.
   */
  private async logOutCli(cliPath: string): Promise<boolean> {
    const isConfirmed = await this.deps.backend.logOutCli()
    // What the CLI said before the logout no longer holds, even when the
    // file did not change (the review of PR #49).
    this.deps.backend.forgetCliAnswers()
    if (isConfirmed) {
      return true
    }
    // `account/logout` may have worked while META_API_KEY hid it from
    // `account/read` (`envKey`): the sign-in itself, read afresh, says
    // whether a terminal is still needed (the review of PR #49).
    if ((await this.deps.backend.cliSignIn(true)) === 'signedOut') {
      this.deps.log.info(
        'Muse Code did not confirm account/logout, but its sign-in now reads signed out; no terminal needed',
      )
      return true
    }
    this.deps.log.warn(
      'Muse Code still reads signed in after account/logout; running muse logout in a terminal',
    )
    try {
      await this.deps.runInTerminal(cliPath, MUSE_LOGOUT_ARGS)
      return true
    } catch {
      this.deps.log.warn('Muse Code logout terminal could not open')
      return false
    }
  }

  private async performSignOut(): Promise<AuthSnapshot> {
    this.signOutEpoch += 1
    this.admissionGenerationValue += 1
    this.isSigningOut = true
    this.signOutStarts.abort()
    this.signOutStarts = new AbortController()
    this.set({
      ...this.snapshot,
      status: 'error',
      detail: UI_TEXT.signOutPending,
      verificationUrl: undefined,
      userCode: undefined,
    })
    this.cancelSignIn()
    // Cancel keeps a remembered answer; a sign-out must not decide on it: a
    // Keychain sign-in made since leaves the file as it was, and a stale
    // `signedOut` would skip `account/logout` (the review of PR #49).
    this.deps.backend.forgetCliAnswers()
    const hasPendingSignIn = this.deviceSignIn !== undefined || this.keyActivations.size > 0
    const stopping = this.stopBackendForSignOut()
    try {
      const isHoldSaved = await this.setLogoutHold(true)
      if (this.deviceSignIn !== undefined) {
        await this.deviceSignIn
      }
      await Promise.allSettled(this.keyActivations)
      let isHostStopped = await stopping
      if (hasPendingSignIn || !isHostStopped) {
        isHostStopped = await this.stopBackendForSignOut()
      }
      let isKeyClearFailed = false
      try {
        await this.deps.credentials.clearApiKey()
      } catch {
        isKeyClearFailed = true
        this.deps.log.warn('Stored Model API key could not be cleared during sign-out')
      }
      const cli = this.deps.backend.resolveCli()
      const isTerminalUnavailable =
        cli.ok &&
        isCliSignedIn(await this.deps.backend.cliSignIn(true)) &&
        !(await this.logOutCli(cli.cliPath))
      // `muse logout` rewrites the file rather than deleting it: what is in
      // it, or the CLI's own answer, says whether a sign-in remains.
      const hasCliCredential = await this.hasCliCredential(true)
      const hasStoredKey =
        isKeyClearFailed || (await this.deps.credentials.getApiKey()) !== undefined
      const shouldKeepHold = hasCliCredential || hasStoredKey || !isHostStopped
      const isReleaseSaved = shouldKeepHold || (await this.setLogoutHold(false))
      let detail: string | undefined
      if (!isHostStopped) {
        detail = UI_TEXT.signOutStopFailed
      } else if (isKeyClearFailed) {
        detail = UI_TEXT.signOutKeyClearFailed
      } else if (!isHoldSaved || !isReleaseSaved) {
        detail = UI_TEXT.signOutHoldFailed
      } else if (isTerminalUnavailable) {
        detail = UI_TEXT.signOutTerminalFailed
      } else if (shouldKeepHold) {
        detail = UI_TEXT.signOutPending
      }
      // Every detail asks for a step and a Check again, which the panel
      // offers on `error` only; `refresh` says `error` for the same state
      // (the review of PR #49).
      return this.set({
        ...this.snapshot,
        status: detail === undefined ? 'signedOut' : 'error',
        detail,
        verificationUrl: undefined,
        userCode: undefined,
        installState: undefined,
        hasCliSession: hasCliCredential,
      })
    } finally {
      this.isSigningOut = false
      // A refresh begun during the sign-out answers too late to publish (the
      // review of PR #49).
      this.signOutEpoch += 1
    }
  }

  public cancelSignIn(): void {
    this.deviceAbort?.abort()
    // Sign-out and the next sign-in ask afresh rather than wait on a probe
    // the CLI left unanswered; an answer already given stands, so what
    // Cancel shows needs no new question (the review of PR #49).
    this.deps.backend.abandonCliProbe()
  }

  /**
   * The window is closing: the browser sign-in is cancelled and waited
   * for, so its host is closed before the backends stop, and none starts
   * afterwards, not even from a click still in its pre-flight questions (the
   * review of PR #49). A flag rather than the window's signal joined to the
   * flow's connect: a stopped click then never publishes `signingIn`, asks
   * its pre-check or opens a key prompt, where a signal would reach it only
   * at the connect.
   */
  public async stopSignIn(): Promise<void> {
    this.isStopped = true
    this.cancelSignIn()
    const signingIn = this.deviceSignIn
    if (signingIn !== undefined) {
      await Promise.allSettled([signingIn])
    }
  }

  /**
   * Check again: the CLI is asked afresh, even about a sign-in it confirmed
   * before (a Keychain sign-in or sign-out leaves the file as it was; the
   * review of PR #49). Presses while one runs join it, so a second press does
   * not forget the probe the first started and start another host.
   */
  public async checkAgain(): Promise<AuthSnapshot> {
    if (this.checkingAgain !== undefined) {
      return await this.checkingAgain
    }
    this.deps.backend.forgetCliAnswers()
    const checking = this.refresh(true)
    this.checkingAgain = checking
    try {
      return await checking
    } finally {
      this.checkingAgain = undefined
    }
  }

  /** One visible installer terminal and one location watch per window. */
  public async installMuseCode(): Promise<AuthSnapshot> {
    if (this.isSigningOut) {
      return this.snapshot
    }
    if (this.installPromise !== undefined) {
      return await this.installPromise
    }
    this.installPromise = this.installWithCli()
    try {
      return await this.installPromise
    } finally {
      this.installPromise = undefined
    }
  }

  public get current(): AuthSnapshot {
    return this.snapshot
  }

  /** The backend the next conversation runs on; undefined without any credential. */
  public get backend(): BackendKind | undefined {
    return this.snapshot.status === 'signedIn' &&
      !this.isLogoutHeld &&
      !this.isSigningOut &&
      this.keyActivations.size === 0 &&
      !this.isLogoutPersistenceFailed
      ? this.snapshot.backend
      : undefined
  }

  public get admissionGeneration(): number {
    return this.admissionGenerationValue
  }

  public toMessage(): HostToWebviewMessage {
    return {
      type: 'authState',
      status: this.snapshot.status,
      ...(this.snapshot.detail !== undefined && { detail: this.snapshot.detail }),
      ...(this.snapshot.backend !== undefined && { backend: this.snapshot.backend }),
      ...(this.snapshot.methods !== undefined && { methods: [...this.snapshot.methods] }),
      ...(this.snapshot.verificationUrl !== undefined && {
        verificationUrl: this.snapshot.verificationUrl,
      }),
      ...(this.snapshot.userCode !== undefined && { userCode: this.snapshot.userCode }),
      installCommand: this.deps.installCommand,
      ...(this.snapshot.hasCli !== undefined && { hasCli: this.snapshot.hasCli }),
      ...(this.snapshot.hasCliSession !== undefined && {
        hasCliSession: this.snapshot.hasCliSession,
      }),
      ...(this.snapshot.installState !== undefined && { installState: this.snapshot.installState }),
    }
  }

  /**
   * Re-derive the status from the CLI, credential and setting facts, then
   * broadcast. `isUserAction` (Check again, a sign-in or sign-out) lets
   * macOS ask the CLI about a Keychain sign-in; opening a panel does not.
   */
  public async refresh(isUserAction = false): Promise<AuthSnapshot> {
    const epoch = this.signOutEpoch
    // Publications are ordered by when their questions began: a slower,
    // older refresh never overwrites a newer state (the review of PR #49).
    const ticket = this.nextTicket()
    const selected = await this.selectedSnapshot(isUserAction)
    // A refresh begun before a sign-out (its probe may answer long after)
    // never overwrites what the sign-out, or a later sign-in, published (the
    // review of PR #49).
    if (this.signOutEpoch !== epoch) {
      return this.snapshot
    }
    if (this.isSigningOut) {
      return await this.publishRefresh(ticket, epoch, {
        ...selected,
        status: 'error',
        detail: this.logoutDetail(),
      })
    }
    if (!this.isLogoutHeld) {
      return await this.publishRefresh(ticket, epoch, selected)
    }
    const hasCliCredential = await this.hasCliCredential(isUserAction)
    const hasStoredKey = (await this.deps.credentials.getApiKey()) !== undefined
    if (this.signOutEpoch !== epoch) {
      return this.snapshot
    }
    if (hasCliCredential || hasStoredKey) {
      return await this.publishRefresh(ticket, epoch, {
        ...selected,
        status: 'error',
        detail: this.logoutDetail(),
      })
    }
    const isHoldSaved = await this.setLogoutHold(false)
    if (!isHoldSaved) {
      return await this.publishRefresh(ticket, epoch, {
        ...selected,
        status: 'error',
        detail: UI_TEXT.signOutHoldFailed,
      })
    }
    const current = await this.selectedSnapshot(isUserAction)
    const hasCurrentCredential =
      (await this.hasCliCredential(isUserAction)) ||
      (await this.deps.credentials.getApiKey()) !== undefined
    if (this.signOutEpoch !== epoch) {
      // A sign-out raced this release: its state is its own, and so is the
      // hold. One still running holds it again; one that has ended decided
      // it, and a late answer must not put back a hold it released (the
      // review of PR #49).
      if (this.isSignOutRunning()) {
        await this.setLogoutHold(true)
      }
      return this.snapshot
    }
    if (hasCurrentCredential || current.status === 'signedIn') {
      await this.setLogoutHold(true)
      return await this.publishRefresh(ticket, epoch, {
        ...current,
        status: 'error',
        detail: this.logoutDetail(),
      })
    }
    return await this.publishRefresh(ticket, epoch, current)
  }

  public async signIn(method: SignInMethod): Promise<AuthSnapshot> {
    if (this.isSigningOut || this.isStopped) {
      return this.snapshot
    }
    const epoch = this.signOutEpoch
    if (this.isLogoutHeld) {
      // A sign-in the CLI still holds after sign-out can be replaced only by
      // an explicit new browser approval, with no key that would bill instead.
      const canRecoverCliSignIn =
        method === 'browser' &&
        !this.deps.backend.hasEnvironmentKey() &&
        isCliSignedIn(await this.deps.backend.cliSignIn(true)) &&
        (await this.deps.credentials.getApiKey()) === undefined
      if (epoch !== this.signOutEpoch) {
        return this.snapshot
      }
      if (!canRecoverCliSignIn) {
        const refreshed = await this.refresh(true)
        if (epoch !== this.signOutEpoch) {
          return this.snapshot
        }
        if (refreshed.status === 'error') {
          return refreshed
        }
      }
    }
    this.deps.log.info(`Sign-in started: ${method}`)
    if (method === 'apiKey') {
      const key = await this.deps.promptForApiKey()
      if (key === undefined) {
        this.deps.log.info('Sign-in with an API key cancelled')
        return this.snapshot
      }
      if (epoch !== this.signOutEpoch) {
        return this.snapshot
      }
      const activation = this.activateApiKey(key, epoch)
      this.keyActivations.add(activation)
      try {
        return await activation
      } finally {
        this.keyActivations.delete(activation)
      }
    }
    return await this.joinDeviceSignIn()
  }

  public async signOut(): Promise<AuthSnapshot> {
    const running = this.signOutPromise ?? this.performSignOut()
    this.signOutPromise = running
    try {
      return await running
    } finally {
      if (this.signOutPromise === running) {
        this.signOutPromise = undefined
      }
    }
  }

  /** The backend answered a turn with `authRequired`: the estimate was wrong. */
  public markAuthRequired(reason: string): AuthSnapshot {
    // The reason is the backend's own text: the panel shows it, and the log
    // names it only in the shape of a protocol word (the review of PR #49).
    this.deps.log.warn(`The backend reported authRequired: ${wireWordForLog(reason)}`)
    return this.set({ ...this.snapshot, status: 'signedOut', detail: reason })
  }

  public markBackendError(detail: string): AuthSnapshot {
    return this.set({ ...this.snapshot, status: 'error', detail })
  }
}

