// The Model API key lives only in VS Code secret storage (OS keychain). The
// dependency is the three-method subset of `vscode.SecretStorage`, which the
// real object satisfies structurally, the ACP agent's OS credential store
// implements (PLAN.md D61), and tests replace with a Map.

import { MODEL_API_KEY_PATTERN, SECRET_KEYS } from '../../shared/constants'

export interface SecretStore {
  get(key: string): PromiseLike<string | undefined>
  store(key: string, value: string): PromiseLike<void>
  delete(key: string): PromiseLike<void>
}

export function isValidModelApiKey(candidate: string): boolean {
  return MODEL_API_KEY_PATTERN.test(candidate.trim())
}

export class CredentialStore {
  private hasReportedFailure = false

  public constructor(
    private readonly secrets: SecretStore,
    /** Where an unreadable secret store is reported, once. */
    private readonly warn: (message: string) => void,
    /** The store's name in that report: the ACP agent's is the OS store (D61). */
    private readonly storeName = "VS Code's secret storage",
  ) {}

  /**
   * The stored key; undefined when there is none or the store cannot be
   * read (PLAN.md D25): on Linux without a keyring VS Code's secret storage
   * throws, and that must not block the Muse Code backend, which needs no key.
   */
  public async getApiKey(): Promise<string | undefined> {
    let stored: string | undefined
    try {
      stored = await this.secrets.get(SECRET_KEYS.modelApiKey)
    } catch (error: unknown) {
      if (!this.hasReportedFailure) {
        this.hasReportedFailure = true
        this.warn(
          `${this.storeName} could not be read, so no Model API key is available: ${String(error)}`,
        )
      }
      return undefined
    }
    return stored === undefined || stored === '' ? undefined : stored
  }

  /** Stores a validated key; throws on an invalid shape so a typo never lands. */
  public async setApiKey(candidate: string): Promise<void> {
    const key = candidate.trim()
    if (!isValidModelApiKey(key)) {
      throw new Error('Refusing to store a value that is not a Meta Model API key')
    }
    await this.secrets.store(SECRET_KEYS.modelApiKey, key)
  }

  public async clearApiKey(): Promise<void> {
    await this.secrets.delete(SECRET_KEYS.modelApiKey)
  }
}

src/host/auth/deviceSignIn.ts:
// Muse Code's captured experimental account/device-code flow (M55). This
// process owns no chat session and is always closed after success, cancel,
// timeout or error. The extension never sends its Model API key to this host.
//
// A sign-in has succeeded (PLAN.md D26, 2026-09-27) when polling
// `account/read` on the same host sees the account sign in, or when the
// credential file is written and `account/read` does not contradict it; a
// CLI that cannot answer `account/read` falls back to the file alone.
//
// `account/loginCompleted` ends the flow on any outcome but `granted`. Every
// outcome was captured live (docs/certification/sign-in-detection.md, "Live
// capture"): `cancelled`, `expired`, `denied` and `failed` each have a
// meaning of their own, and any other word is shown as the CLI named it
// (AGENTS.md rule 13). `granted` came 205 ms after the file was written and
// `account/read` said `accountLogin`, so those usually decide first. It is
// remembered for when they cannot: `granted` with `account/read` saying
// `accountLogin` is the sign-in, with no first `account/read` to compare,
// or when the account was already `accountLogin` (a same-account re-sign-in
// on macOS may change only the Keychain). `granted` alone never signs in. `account/changed` is not relied on: it fired neither
// for a change made outside the host nor for an expired, denied or failed
// code.
//
// Cancel, the host's ending and the host's exit are noticed at once, even
// while an `account/read` is unanswered, and the `account/loginCancel` sent
// on the way out is bounded: the host is closed either way, which ends its
// flow. A host that exits after the credential file changed has signed in,
// unless an answered `account/read` said signed out about that same write:
// that evidence stands for the exit and for a question left unanswered.

import * as z from 'zod/mini'
import { wireWordForLog } from '../../core/logging'
import { withDeadline } from '../../core/timeouts'
import {
  CREDENTIAL_POLL_INTERVAL_MS,
  CREDENTIAL_POLL_TIMEOUT_MS,
  MSP_HANDSHAKE_TIMEOUT_MS,
  MUSE_ACCOUNT_DEVICE_CODE_TYPE,
  MUSE_ACCOUNT_LOGIN_CANCEL,
  MUSE_ACCOUNT_LOGIN_COMPLETED,
  MUSE_ACCOUNT_LOGIN_START,
  MUSE_ACCOUNT_STATES,
  MUSE_DEVICE_SIGN_IN_URL_ORIGIN,
  MUSE_LOGIN_CANCEL_TIMEOUT_MS,
  MUSE_LOGIN_OUTCOME_SHOWN_MAX_CHARS,
  MUSE_LOGIN_OUTCOMES,
} from '../../shared/constants'
import type { Logger } from '../logger'
import { type AccountSession, type AccountState, readAccountState } from './accountHost'

const loginStartSchema = z.object({
  verificationUrl: z.url(),
  userCode: z.string().check(z.minLength(1)),
})
// As captured: `expired` and `denied` carry a message ("login failed: the
// request expired" / "… was denied"), `failed` one that names the credential
// file's path, `cancelled` and `granted` none. The message is free text the
// CLI chose, so neither the log nor the panel shows it: the log names each
// captured ending in fixed words (`loggedEnding`).
const loginCompletedSchema = z.object({
  outcome: z.string().check(z.minLength(1)),
})
const loginCancelSchema = z.object({ cancelled: z.boolean() })

export interface DeviceSignInDeps {
  readonly connect: (signal: AbortSignal) => Promise<AccountSession>
  readonly credentialFileModifiedAt: () => number | undefined
  readonly sleep: (ms: number) => Promise<void>
  readonly now: () => number
  readonly signal: AbortSignal
  readonly onCode: (url: string, code: string) => void
  readonly log: Logger
}

/** An ending Muse Code named that no capture covers: shown as it came (AGENTS.md rule 13). */
export interface DeviceSignInEnded {
  readonly endedAs: string
}
/** The endings captured live, each with a meaning of its own. */
export type CapturedSignInEnding = 'cancelled' | 'expired' | 'denied' | 'failed'
/** How the host ended a flow that did not sign in. */
type HostEnding = CapturedSignInEnding | DeviceSignInEnded
export type DeviceSignInOutcome = 'signedIn' | 'timedOut' | HostEnding

const STOPPED = Symbol('device sign-in stopped')

/**
 * A host that exits mid-flow fails the sign-in at once, instead of being
 * polled until the backstop (the review of PR #49).
 */
function hostGone(): Error {
  return new Error('The Muse Code sign-in host exited during sign-in')
}

// The endings captured live: `cancelled` (1.3.0, M55; 1.4.0-R4302.1),
// `expired` (600 s after `account/loginStart`), `denied` (Deny clicked) and
// `failed` (approved, but the file could not be written), all 1.4.0-R4302.1.
const CAPTURED_ENDINGS: ReadonlyMap<string, CapturedSignInEnding> = new Map([
  [MUSE_LOGIN_OUTCOMES.cancelled, 'cancelled'],
  [MUSE_LOGIN_OUTCOMES.expired, 'expired'],
  [MUSE_LOGIN_OUTCOMES.denied, 'denied'],
  [MUSE_LOGIN_OUTCOMES.failed, 'failed'],
])

// How the log names each captured ending: fixed words, never the CLI's
// message (the review of PR #49). `clipForLog` only shortens, and the
// redactor catches keys, not a path or an e-mail address a message may hold.
const LOGGED_ENDINGS: ReadonlyMap<string, string> = new Map([
  [MUSE_LOGIN_OUTCOMES.granted, 'granted'],
  [MUSE_LOGIN_OUTCOMES.cancelled, 'cancelled'],
  [MUSE_LOGIN_OUTCOMES.expired, 'expired: the code expired before it was approved'],
  [MUSE_LOGIN_OUTCOMES.denied, 'denied: the sign-in was denied in the browser'],
  [MUSE_LOGIN_OUTCOMES.failed, 'failed: saving the credential failed'],
])

/** How the log names an ending: fixed words, or an uncovered word in the shape of one. */
function loggedEnding(outcome: string): string {
  return (
    LOGGED_ENDINGS.get(outcome) ??
    `${wireWordForLog(outcome)} (an ending no capture covers; its message is not logged)`
  )
}

/** How `outcome` ends the flow; undefined for `granted`, which `account/read` bears out. */
function endingOf(outcome: string): HostEnding | undefined {
  if (outcome === MUSE_LOGIN_OUTCOMES.granted) {
    return undefined
  }
  const captured = CAPTURED_ENDINGS.get(outcome)
  if (captured !== undefined) {
    return captured
  }
  const shown =
    outcome.length > MUSE_LOGIN_OUTCOME_SHOWN_MAX_CHARS
      ? `${outcome.slice(0, MUSE_LOGIN_OUTCOME_SHOWN_MAX_CHARS)}…`
      : outcome
  return { endedAs: shown }
}

/**
 * Settles with `value` once `signal` aborts (at once if it already has);
 * `remove` stops listening. Not `Promise.withResolvers`: VS Code 1.99 and
 * 1.100 run Node 20 (PLAN.md M62).
 */
function settleOnAbort<T>(
  signal: AbortSignal,
  value: T,
): { readonly promise: Promise<T>; readonly remove: () => void } {
  const listening = new AbortController()
  const promise = new Promise<T>((resolve) => {
    signal.addEventListener(
      'abort',
      () => {
        resolve(value)
      },
      { once: true, signal: listening.signal },
    )
    if (signal.aborted) {
      resolve(value)
    }
  })
  return {
    promise,
    remove: () => {
      listening.abort()
    },
  }
}

/** The returned URL is data from a CLI process: do not open arbitrary origins. */
export function parseDeviceCode(raw: unknown): { readonly url: string; readonly code: string } {
  const parsed = loginStartSchema.parse(raw)
  const url = new URL(parsed.verificationUrl)
  if (url.origin !== MUSE_DEVICE_SIGN_IN_URL_ORIGIN) {
    throw new Error('Muse Code returned an unexpected sign-in URL')
  }
  return { url: url.href, code: parsed.userCode }
}

/** The signals that a new sign-in landed, as one poll sees them. */
interface SignInSignals {
  /** Undefined when the host did not answer the first question. */
  readonly initial: AccountState | undefined
  /** Undefined when the host did not answer, or the poll was cut short. */
  readonly current: AccountState | undefined
  readonly isFileWritten: boolean
  /** The host sent `account/loginCompleted {outcome: "granted"}`. */
  readonly isGranted: boolean
}

function isSignedIn(signals: SignInSignals): boolean {
  const { initial, current, isFileWritten, isGranted } = signals
  if (current === undefined) {
    return isFileWritten
  }
  // A file written by a sign-out. Signed out is signed out, whatever the
  // uncaptured `credentialRequired: false` might mean (the review of PR #49).
  if (current.state === MUSE_ACCOUNT_STATES.loggedOut) {
    return false
  }
  // `envKey` or a stored key may mask the new login, so a new file counts
  // while the account is anything but signed out.
  if (isFileWritten) {
    return true
  }
  const isAccountLogin = current.state === MUSE_ACCOUNT_STATES.accountLogin
  // The host's own `granted`, borne out by `account/read` saying
  // `accountLogin` (the captured success), is a sign-in whatever came
  // before. That matters where no change of state or file can show it: with
  // no first answer, and for a same-account re-sign-in on macOS that
  // replaces only the Keychain item while the logout hold keeps the old
  // sign-in (Codex on 328efb52). Otherwise a sign-in shows as a change from
  // an account read before the flow. `granted` alone never counts.
  const hasChangedToLogin =
    initial !== undefined && initial.state !== MUSE_ACCOUNT_STATES.accountLogin
  return isAccountLogin && (isGranted || hasChangedToLogin)
}

export async function runDeviceSignIn(deps: DeviceSignInDeps): Promise<DeviceSignInOutcome> {
  const isAborted = () => deps.signal.aborted
  if (isAborted()) {
    return 'cancelled'
  }
  const before = deps.credentialFileModifiedAt()
  let session: AccountSession
  try {
    session = await deps.connect(deps.signal)
  } catch (error: unknown) {
    if (isAborted()) {
      return 'cancelled'
    }
    throw error
  }
  // Cancel, the host's own ending, or its exit: whatever the flow is
  // waiting on stops. A controller of the flow's own, not
  // `Promise.withResolvers`, which Node 20 lacks (PLAN.md M62).
  const stopper = new AbortController()
  const stopped = settleOnAbort(stopper.signal, STOPPED)
  const stop = () => {
    stopper.abort()
  }
  let hostEnding: HostEnding | undefined
  let isEnded = false
  let isGranted = false
  let isHostGone = false
  // The file's modification time when an answered `account/read` said
  // signed out: that write (another Muse process's sign-out) is no sign-in,
  // whatever follows it, a host exit or a question left unanswered (the
  // review of PR #49).
  let refutedWrite: number | undefined
  /** A write since the flow began that no answer contradicted. */
  const isFreshWrite = (modified: number | undefined) =>
    modified !== undefined && modified !== before && modified !== refutedWrite
  const isFileWritten = () => isFreshWrite(deps.credentialFileModifiedAt())
  try {
    session.connection.onNotification((notification) => {
      if (isEnded || notification.method !== MUSE_ACCOUNT_LOGIN_COMPLETED) {
        return
      }
      const result = loginCompletedSchema.safeParse(notification.params)
      if (!result.success) {
        return
      }
      // The first ending counts; the host runs one flow.
      isEnded = true
      isGranted = result.data.outcome === MUSE_LOGIN_OUTCOMES.granted
      hostEnding = endingOf(result.data.outcome)
      deps.log.info(`Muse Code sign-in ended: ${loggedEnding(result.data.outcome)}`)
      if (hostEnding !== undefined) {
        stop()
      }
    })
    void session.connection.closed.then(() => {
      isHostGone = true
      stop()
    })
    deps.signal.addEventListener('abort', stop, { once: true })
    if (isAborted()) {
      return 'cancelled'
    }
    /** `work`, or STOPPED as soon as Cancel, the host's ending or its exit arrives. */
    const untilStopped = <T>(work: Promise<T>) => Promise.race([work, stopped.promise])
    /** Why a wait before the polling was cut short; no loginCancel is owed. */
    const stoppedEarly = (): HostEnding => {
      if (hostEnding !== undefined) {
        return hostEnding
      }
      if (isHostGone && !isAborted()) {
        throw hostGone()
      }
      return 'cancelled'
    }
    // The account before the flow, so a sign-in shows as a change.
    const initial = await untilStopped(readAccountState(session.connection))
    if (initial === STOPPED) {
      return stoppedEarly()
    }
    const start = await untilStopped(
      withDeadline(
        session.connection.request(MUSE_ACCOUNT_LOGIN_START, {
          type: MUSE_ACCOUNT_DEVICE_CODE_TYPE,
        }),
        MSP_HANDSHAKE_TIMEOUT_MS,
        'Muse Code did not start sign-in in time',
      ),
    )
    if (start === STOPPED) {
      return stoppedEarly()
    }
    const { url, code } = parseDeviceCode(start)
    deps.onCode(url, code)
    const deadline = deps.now() + CREDENTIAL_POLL_TIMEOUT_MS
    // Captured: the ending arrives before this answer, in milliseconds. A
    // host that does not answer is closed all the same.
    const cancelLogin = async () => {
      try {
        loginCancelSchema.parse(
          await withDeadline(
            session.connection.request(MUSE_ACCOUNT_LOGIN_CANCEL, {}),
            MUSE_LOGIN_CANCEL_TIMEOUT_MS,
            'Muse Code did not cancel sign-in in time',
          ),
        )
      } catch {
        deps.log.warn('Muse Code did not confirm the sign-in cancel; closing its host')
      }
    }
    const hasLanded = async () => {
      // Read before the question, so an answer refutes only a write it saw.
      const modified = deps.credentialFileModifiedAt()
      const current = await untilStopped(readAccountState(session.connection))
      // A stop (Cancel, an ending) decides the flow: a file change alone
      // must not turn it into a sign-in (the review of PR #49).
      if (current === STOPPED) {
        return false
      }
      if (current?.state === MUSE_ACCOUNT_STATES.loggedOut) {
        refutedWrite = modified
      }
      return isSignedIn({ initial, current, isFileWritten: isFreshWrite(modified), isGranted })
    }
    /** How a flow that has not landed ends now; undefined while it goes on. */
    const endedAs = async (): Promise<DeviceSignInOutcome | undefined> => {
      if (hostEnding !== undefined) {
        return hostEnding
      }
      if (isAborted()) {
        await cancelLogin()
        return 'cancelled'
      }
      if (isHostGone) {
        // An exit is no decision: a host that wrote the credential file
        // before it went has signed in, unless an answer already said that
        // write left it signed out (the review of PR #49).
        if (isFileWritten()) {
          deps.log.warn('The Muse Code sign-in host exited after writing the credential file')
          return 'signedIn'
        }
        throw hostGone()
      }
      return undefined
    }
    while (deps.now() < deadline) {
      if (await hasLanded()) {
        return 'signedIn'
      }
      const ending = await endedAs()
      if (ending !== undefined) {
        return ending
      }
      await untilStopped(deps.sleep(CREDENTIAL_POLL_INTERVAL_MS))
    }
    if (await hasLanded()) {
      return 'signedIn'
    }
    const ending = await endedAs()
    if (ending !== undefined) {
      return ending
    }
    await cancelLogin()
    return isAborted() ? 'cancelled' : 'timedOut'
  } finally {
    deps.signal.removeEventListener('abort', stop)
    stopped.remove()
    await session.close()
  }
}

src/host/backend/checkpointedMemory.ts:
// Muse Code's memory under turn checkpoints (M72, M86; PLAN.md D51, D63).
// This is the one composition activation builds, and the one its regression
// tests build:
// - the model's memory tools use one store for the window, and each call
//   writes through its turn's own recording writes (`turnWrites`): a
//   replacement through the turn's io, a new note's no-clobber publication
//   through the io's intent seam, both recorded for a restore. Without them
//   (nothing recorded) the store writes through the window's tool io. Either
//   way a write into the checkpoint storage is refused, an exclusive creation
//   (which has no ToolIo call) before its publication;
// - the Memory view has its own store over the raw io, which records
//   nothing: what the user does there is theirs, and a restore that finds a
//   note changed since the model's write leaves it alone;
// - the view's creation and trash hold the pure checkpoint lease until their
//   native promises settle, so another window's restore cannot overlap them.
//   A scope outside the workspace (Muse Code's personal data folders) takes
//   no project lease and keeps only the lifetime guard.

import type { ToolIo } from '../../core/backends/modelapi/tools'
import { MemoryStore, type MemoryStoreDeps, type MemoryWrites } from '../../core/memory/memoryStore'
import {
  type CheckpointPort,
  withCheckpointStorageGuard,
  withCheckpointEditAt,
} from '../checkpoints/checkpointHost'
import type { OwnerIo } from '../checkpoints/writeRecorder'
import type { MemoryEdit } from '../commands/memoryCommands'
import { createMemoryIo } from './memoryIo'

export interface CheckpointedMemoryDeps extends Omit<MemoryStoreDeps, 'io'> {
  /**
   * A guard for one mutation, captured when it starts: it throws once the
   * window or the backend it was taken for is gone.
   */
  readonly captureGuard: () => () => void
}

export interface CheckpointedMemory {
  /** The model's memory tools' store: each call hands in its turn's writes. */
  readonly store: MemoryStore
  /** The Memory view's store, over the raw io: nothing it writes is recorded. */
  readonly viewStore: MemoryStore
  /** The Memory view's mutations: the pure lease for notes under the workspace, held until the work settles. */
  readonly edit: MemoryEdit
  /** A turn's memory writes through its own recording io (M86). */
  readonly turnWrites: (io: OwnerIo) => MemoryWrites
}

export function createCheckpointedMemory(
  files: ToolIo,
  checkpoints: CheckpointPort,
  deps: CheckpointedMemoryDeps,
): CheckpointedMemory {
  const { captureGuard, ...storeDeps } = deps
  const store = new MemoryStore({
    ...storeDeps,
    io: createMemoryIo(withCheckpointStorageGuard(files, checkpoints), {
      warn: storeDeps.warn,
      aroundCreate: async (absolutePath, _content, _checkedPath, publish) => {
        checkpoints.refuseStorageWrite(absolutePath)
        await publish()
      },
    }),
  })
  return {
    store,
    viewStore: new MemoryStore({
      ...storeDeps,
      io: createMemoryIo(files, { warn: storeDeps.warn }),
    }),
    edit: async (scope, work) => {
      const check = captureGuard()
      check()
      const root = await store.root(scope)
      return await withCheckpointEditAt(
        checkpoints,
        { warn: storeDeps.warn },
        check,
        { root: storeDeps.workspaceRoot, platform: storeDeps.platform },
        root.ok ? root.value : undefined,
        async () => await work(check),
      )
    },
    turnWrites: (io) =>
      createMemoryIo(io, {
        warn: storeDeps.warn,
        aroundCreate: async (...args) => {
          checkpoints.refuseStorageWrite(args[0])
          await io.recordNew(...args)
        },
      }),
  }
}

src/host/backend/contextIo.ts:
// The file access behind the workspace context loaders (PLAN.md D13, D27):
// a file's raw bytes, so the loaders can tell UTF-8 from UTF-16 by its
// byte-order mark, and a skill root's entries with symbolic links and
// junctions included (a `Dirent` reports a link, and on Windows a junction,
// as neither a directory nor a file). Confinement and decoding are the
// loaders' (`src/core/context/contextFiles.ts`).

import { open, readdir, readFile, stat } from 'node:fs/promises'
import type { ContextIo } from '../../core/context/contextFiles'
import { canonicalPath, isMissingPath } from '../canonicalPath'

/**
 * At most `maxBytes + 1` bytes of a regular file (M76): the catalogs cap a
 * file the repository ships, and a cap checked after a whole read would not
 * stop a huge file, a pipe that never ends or a device that blocks.
 */
async function readCapped(absolutePath: string, maxBytes: number): Promise<Uint8Array> {
  const info = await stat(absolutePath)
  if (!info.isFile()) {
    throw new Error(`${absolutePath} is not a regular file`)
  }
  const wanted = Math.min(info.size, maxBytes + 1)
  const handle = await open(absolutePath, 'r')
  try {
    const buffer = Buffer.alloc(wanted)
    let filled = 0
    while (filled < wanted) {
      const { bytesRead } = await handle.read(buffer, filled, wanted - filled, filled)
      if (bytesRead === 0) {
        break
      }
      filled += bytesRead
    }
    return buffer.subarray(0, filled)
  } finally {
    await handle.close()
  }
}

export const fileContextIo: ContextIo = {
  async readFile(absolutePath, maxBytes) {
    try {
      return maxBytes === undefined
        ? await readFile(absolutePath)
        : await readCapped(absolutePath, maxBytes)
    } catch (error: unknown) {
      if (isMissingPath(error)) {
        return
      }
      throw error
    }
  },
  async listDirectory(absolutePath) {
    try {
      const entries = await readdir(absolutePath, { withFileTypes: true })
      return entries
        .filter((entry) => entry.isDirectory() || entry.isSymbolicLink())
        .map((entry) => entry.name)
    } catch (error: unknown) {
      if (isMissingPath(error)) {
        return []
      }
      throw error
    }
  },
  realPath: canonicalPath,
}

src/host/backend/environment.ts:
// The git facts for the Model API prompt's environment section (PLAN.md
// D15): branch, how many entries `git status` lists and the latest commit
// subjects, gathered once per session. Metadata only, never file contents.
// Never rejects: outside a repository, without git, or in a repository with
// no commit yet the section says so instead. Not in Restricted Mode (D24):
// git reads the repository's own `.git/config`, and `core.fsmonitor` or
// `core.hooksPath` there would run a program the workspace chose.

import type { EnvironmentFacts } from '../../core/backends/modelapi/instructions'
import { ENVIRONMENT_RECENT_COMMITS, UI_TEXT } from '../../shared/constants'
import { failureForLog } from '../../core/backends/musecode/logText'
import { metadataGit } from '../git'
import type { Logger } from '../logger'

export interface EnvironmentDeps {
  readonly runGit: (args: readonly string[], cwd: string) => Promise<string>
  readonly workspaceRoot: string | undefined
  readonly isWorkspaceTrusted: () => boolean
  readonly log: Logger
  readonly now: () => number
}

const LINE_BREAK = /\r?\n/

function nonEmptyLines(text: string): readonly string[] {
  return text.split(LINE_BREAK).filter((line) => line.trim() !== '')
}

async function recentCommits(
  run: (args: readonly string[]) => Promise<string>,
): Promise<readonly string[]> {
  try {
    return nonEmptyLines(await run(['log', '--oneline', `-${String(ENVIRONMENT_RECENT_COMMITS)}`]))
  } catch {
    // A repository before its first commit has a branch but no log.
    return []
  }
}

export async function describeEnvironment(deps: EnvironmentDeps): Promise<EnvironmentFacts> {
  const root = deps.workspaceRoot
  if (root === undefined || !deps.isWorkspaceTrusted()) {
    return { git: undefined }
  }
  const startedAt = deps.now()
  try {
    const git = await metadataGit(deps.runGit, root)
    const run = async (args: readonly string[]) => {
      if (!deps.isWorkspaceTrusted()) {
        throw new Error(UI_TEXT.checkpointFailed)
      }
      return await git(args)
    }
    // Together, not one after another (M39): each may take up to git's own
    // timeout, and the first Model API turn waits for them.
    const [branchText, status, commits] = await Promise.all([
      run(['rev-parse', '--abbrev-ref', 'HEAD']),
      run(['status', '--porcelain']),
      recentCommits(run),
    ])
    deps.log.trace(`Git facts for the prompt in ${String(deps.now() - startedAt)} ms`)
    return {
      git: {
        branch: branchText.trim(),
        changedFiles: nonEmptyLines(status).length,
        recentCommits: commits,
      },
    }
  } catch (error: unknown) {
    // Outside a repository, without git, or git timing out: the log says
    // which (M39); the prompt only says there are no git facts.
    const reason = failureForLog(error)
    deps.log.info(`No git facts for the prompt: ${reason}`)
    return { git: undefined }
  }
}

src/host/backend/fileScheduleStore.ts:
// Durable, workspace-local Model API schedules (PLAN.md M52). Each job is a
// file in VS Code's workspace storage. An occurrence is admitted by creating
// its receipt with `wx`: two windows cannot admit the same fire. A receipt is
// never rolled back after admission, so a crash cannot silently replay a
// possibly billed request.

import { mkdir, readFile, readdir, rm, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'
import * as z from 'zod/mini'
import { nextScheduleFire } from '../../core/backends/modelapi/schedules'
import { SCHEDULE_CLAIM_RETENTION_MS } from '../../shared/constants'
import {
  scheduledPromptSchema,
  type ScheduledPrompt,
  type ScheduleStore,
} from '../../shared/schedule'
import type { Logger } from '../logger'
import { describeStoreError, storeErrorCode } from './storeErrors'

export interface FileScheduleStoreDeps {
  readonly directory: string
  readonly now: () => number
  readonly log: Logger
}

const JOB_FILE = '.json'
const CLAIM_FILE = '.claim'
const ID = /^[A-Za-z0-9_-]+$/
const ENOENT = 'ENOENT'
const EEXIST = 'EEXIST'
const receiptSchema = z.object({ admittedAtMs: z.number() })

function assertId(id: string): void {
  if (!ID.test(id)) {
    throw new Error('A schedule identifier cannot name a file')
  }
}

function claimName(id: string, occurrenceMs: number): string {
  assertId(id)
  if (!Number.isSafeInteger(occurrenceMs) || occurrenceMs < 0) {
    throw new Error('A schedule occurrence must be a positive epoch millisecond')
  }
  return `${id}.${String(occurrenceMs)}${CLAIM_FILE}`
}

export function createFileScheduleStore(deps: FileScheduleStoreDeps): ScheduleStore {
  const jobPath = (id: string) => {
    assertId(id)
    return path.join(deps.directory, `${id}${JOB_FILE}`)
  }
  const receiptPath = (id: string, occurrenceMs: number) =>
    path.join(deps.directory, claimName(id, occurrenceMs))

  const readJob = async (id: string): Promise<ScheduledPrompt | undefined> => {
    let raw: unknown
    try {
      raw = JSON.parse(await readFile(jobPath(id), 'utf8'))
    } catch (error: unknown) {
      if (storeErrorCode(error) !== ENOENT) {
        deps.log.warn(`Schedule ${id} skipped: ${describeStoreError(error)}`)
      }
      return undefined
    }
    const parsed = scheduledPromptSchema.safeParse(raw)
    if (!parsed.success || parsed.data.id !== id) {
      deps.log.warn(`Schedule ${id} skipped: invalid stored shape`)
      return undefined
    }
    return parsed.data
  }

  const receiptsFor = async (
    job: ScheduledPrompt,
    names: readonly string[],
  ): Promise<readonly { readonly occurrenceMs: number; readonly admittedAtMs: number }[]> => {
    const result: { occurrenceMs: number; admittedAtMs: number }[] = []
    for (const name of names) {
      if (!name.startsWith(`${job.id}.`) || !name.endsWith(CLAIM_FILE)) {
        continue
      }
      const occurrenceMs = Number(name.slice(job.id.length + 1, -CLAIM_FILE.length))
      if (!Number.isSafeInteger(occurrenceMs) || occurrenceMs < job.nextFireAtMs) {
        continue
      }
      const file = path.join(deps.directory, name)
      let admittedAtMs: number
      try {
        const raw: unknown = JSON.parse(await readFile(file, 'utf8'))
        const parsed = receiptSchema.safeParse(raw)
        if (parsed.success) {
          admittedAtMs = parsed.data.admittedAtMs
        } else {
          const fileStat = await stat(file)
          admittedAtMs = fileStat.mtimeMs
        }
      } catch {
        // A receipt created before a crash still means admitted, never retry.
        const fileStat = await stat(file)
        admittedAtMs = fileStat.mtimeMs
      }
      result.push({ occurrenceMs, admittedAtMs: Math.max(occurrenceMs, admittedAtMs) })
    }
    return result
  }

  const currentJob = async (
    job: ScheduledPrompt,
    names: readonly string[],
  ): Promise<ScheduledPrompt | undefined> => {
    const receipts = await receiptsFor(job, names)
    const last = receipts.toSorted((a, b) => b.admittedAtMs - a.admittedAtMs)[0]
    const nextFireAtMs =
      last === undefined
        ? job.nextFireAtMs
        : nextScheduleFire(
            job.cadence,
            Math.max(last.occurrenceMs, last.admittedAtMs),
            job.expiresAtMs,
          )
    if (nextFireAtMs === undefined) {
      return undefined
    }
    return {
      ...job,
      nextFireAtMs,
      fireCount: receipts.length,
      ...(last !== undefined && { lastFireAtMs: last.occurrenceMs }),
    }
  }

  const readNames = async (): Promise<readonly string[]> => {
    try {
      return await readdir(deps.directory)
    } catch (error: unknown) {
      if (storeErrorCode(error) === ENOENT) {
        return []
      }
      throw error
    }
  }

  const listJobs: ScheduleStore['list'] = async (sessionId) => {
    const names = await readNames()
    const now = deps.now()
    const jobs: ScheduledPrompt[] = []
    for (const name of names) {
      if (name.endsWith(CLAIM_FILE)) {
        const file = path.join(deps.directory, name)
        try {
          const fileStat = await stat(file)
          if (now - fileStat.mtimeMs > SCHEDULE_CLAIM_RETENTION_MS) {
            await rm(file, { force: true })
          }
        } catch (error: unknown) {
          if (storeErrorCode(error) !== ENOENT) {
            deps.log.warn(`Schedule receipt ${name} cleanup failed: ${describeStoreError(error)}`)
          }
        }
        continue
      }
      if (!name.endsWith(JOB_FILE)) {
        continue
      }
      const id = name.slice(0, -JOB_FILE.length)
      if (!ID.test(id)) {
        continue
      }
      const stored = await readJob(id)
      if (stored === undefined) {
        continue
      }
      if (stored.expiresAtMs <= now || stored.nextFireAtMs >= stored.expiresAtMs) {
        await rm(jobPath(id), { force: true })
        continue
      }
      if (stored.sessionId !== sessionId) {
        continue
      }
      const job = await currentJob(stored, names)
      if (job !== undefined) {
        jobs.push(job)
      }
    }
    return jobs.toSorted((a, b) => a.nextFireAtMs - b.nextFireAtMs)
  }

  return {
    async create(job) {
      const parsed = scheduledPromptSchema.safeParse(job)
      if (!parsed.success || job.id !== parsed.data.id) {
        throw new Error('Invalid scheduled prompt')
      }
      await mkdir(deps.directory, { recursive: true })
      // UUID ids are unique; `wx` also refuses a collision across windows.
      await writeFile(jobPath(job.id), JSON.stringify(job), { flag: 'wx' })
    },
    list: listJobs,
    async remove(sessionId, jobId) {
      const job = await readJob(jobId)
      if (job?.sessionId !== sessionId) {
        return false
      }
      await rm(jobPath(jobId), { force: true })
      return true
    },
    async claim(job, occurrenceMs) {
      const jobs = await listJobs(job.sessionId)
      const current = jobs.find((entry) => entry.id === job.id)
      if (
        current?.workspaceRoot !== job.workspaceRoot ||
        current.accountId !== job.accountId ||
        current.prompt !== job.prompt ||
        current.nextFireAtMs !== occurrenceMs ||
        occurrenceMs > deps.now()
      ) {
        return false
      }
      const receipt = receiptPath(job.id, occurrenceMs)
      try {
        await writeFile(receipt, JSON.stringify({ admittedAtMs: deps.now() }), { flag: 'wx' })
      } catch (error: unknown) {
        if (storeErrorCode(error) === EEXIST) {
          return false
        }
        throw error
      }
      // If cancellation won before admission finished, refuse this run.
      const stillStored = await readJob(job.id)
      return (
        stillStored?.sessionId === job.sessionId &&
        stillStored.workspaceRoot === job.workspaceRoot &&
        stillStored.accountId === job.accountId &&
        stillStored.prompt === job.prompt &&
        deps.now() < stillStored.expiresAtMs
      )
    },
  }
}

src/host/backend/fileSessionStore.ts:
// The Model API session store on disk (PLAN.md D14): one JSON file per
// session under the workspace storage directory VS Code gives the
// extension (`context.storageUri`: per user, per workspace, outside the
// repository). Writes go to a temporary file and are renamed into place,
// so a crash mid-write leaves the previous version. A file that does not
// parse or validate is skipped with a log line and never stops the host.
//
// PLAN.md D26: listing keeps only each session's header, a session is read
// whole when it is opened, a session idle past the retention period
// (`museSpark.cleanupPeriodDays`, Claude Code's `cleanupPeriodDays`) is
// deleted when the list is read, and a temporary file a crash left behind
// is removed. The write itself is `writeFileAtomically` (host/fsAtomic.ts).

import { readdir, readFile, rm, stat } from 'node:fs/promises'
import path from 'node:path'
import {
  headerOf,
  parseStoredSession,
  type SessionStore,
  type StoredSession,
  type StoredSessionHeader,
} from '../../core/backends/modelapi/sessionStore'
import {
  ATOMIC_TEMPORARY_SUFFIX,
  MILLISECONDS_PER_DAY,
  SESSION_FILE_STALE_TEMPORARY_MS,
  UI_TEXT,
} from '../../shared/constants'
import { writeFileAtomically } from '../fsAtomic'
import type { Logger } from '../logger'
import { describeStoreError, storeErrorCode } from './storeErrors'
import { createSessionBudgetJournal, type SessionBudgetJournalDeps } from './sessionBudgetJournal'

export interface FileSessionStoreDeps {
  readonly directory: string
  readonly log: Logger
  /** Days a session may sit idle before it is deleted; 0 keeps it for ever. */
  readonly retentionDays: () => number
  /** Epoch milliseconds. */
  readonly now: () => number
  /** Waits between rename attempts; injectable so tests do not sleep. */
  readonly sleep: (ms: number) => Promise<void>
  /** `fs.rename`; tests stand in a scanner holding the file. */
  readonly rename?: (from: string, to: string) => Promise<void>
}

const FILE_EXTENSION = '.json'
const ENOENT = 'ENOENT'
// A session id names a file; only the UUID alphabet is allowed into a path.
const SESSION_ID_PATTERN = /^[A-Za-z0-9_-]+$/

function assertSessionId(sessionId: string): void {
  if (!SESSION_ID_PATTERN.test(sessionId)) {
    throw new Error(`session id ${sessionId} cannot name a file`)
  }
}

async function hasSessionFile(file: string): Promise<boolean> {
  try {
    await stat(file)
    return true
  } catch (error: unknown) {
    if (storeErrorCode(error) === ENOENT) {
      return false
    }
    throw new Error(UI_TEXT.sessionBudgetStoreUnavailable, { cause: error })
  }
}

export function createFileSessionStore(deps: FileSessionStoreDeps): SessionStore {
  const fileFor = (sessionId: string) => path.join(deps.directory, `${sessionId}${FILE_EXTENSION}`)

  const readOne = async (name: string): Promise<StoredSession | undefined> => {
    const file = path.join(deps.directory, name)
    let raw: unknown
    try {
      raw = JSON.parse(await readFile(file, 'utf8'))
    } catch (error: unknown) {
      if (storeErrorCode(error) !== ENOENT) {
        deps.log.warn(`Session file ${name} skipped: ${describeStoreError(error)}`)
      }
      return undefined
    }
    const parsed = parseStoredSession(raw)
    if (!parsed.ok) {
      deps.log.warn(`Session file ${name} skipped: ${parsed.reason}`)
      return undefined
    }
    return parsed.session
  }

  const journalDeps: SessionBudgetJournalDeps = {
    directory: deps.directory,
    loadSession: async (sessionId) => {
      assertSessionId(sessionId)
      return await readOne(`${sessionId}${FILE_EXTENSION}`)
    },
    sleep: deps.sleep,
    ...(deps.rename !== undefined && { rename: deps.rename }),
  }
  const budget = createSessionBudgetJournal(journalDeps)

  /** A temporary file older than any save in flight is a crash's leftover. */
  const removeIfStale = async (name: string): Promise<void> => {
    const file = path.join(deps.directory, name)
    try {
      const { mtimeMs } = await stat(file)
      if (deps.now() - mtimeMs >= SESSION_FILE_STALE_TEMPORARY_MS) {
        await rm(file, { force: true })
      }
    } catch (error: unknown) {
      deps.log.warn(`Leftover ${name} could not be removed: ${describeStoreError(error)}`)
    }
  }

  /** True when the session has sat idle past the retention period (and was deleted). */
  const isExpired = async (session: StoredSession): Promise<boolean> => {
    const days = deps.retentionDays()
    const idleMs = deps.now() - Date.parse(session.lastActivityAt)
    // An unreadable date is kept: only a known age deletes anything.
    if (days <= 0 || Number.isNaN(idleMs) || idleMs <= days * MILLISECONDS_PER_DAY) {
      return false
    }
    try {
      await rm(fileFor(session.sessionId), { force: true })
      deps.log.info(`Session ${session.sessionId} idle for more than ${String(days)} days deleted`)
    } catch (error: unknown) {
      deps.log.warn(
        `Expired session ${session.sessionId} not deleted: ${describeStoreError(error)}`,
      )
    }
    return true
  }

  return {
    budget,
    async list() {
      let names: string[]
      try {
        names = await readdir(deps.directory)
      } catch (error: unknown) {
        if (storeErrorCode(error) === ENOENT) {
          return []
        }
        throw error
      }
      const headers: StoredSessionHeader[] = []
      const sorted = names.toSorted((a, b) => a.localeCompare(b, 'en'))
      for (const name of sorted) {
        if (name.endsWith(ATOMIC_TEMPORARY_SUFFIX)) {
          await removeIfStale(name)
          continue
        }
        if (!name.endsWith(FILE_EXTENSION)) {
          continue
        }
        const session = await readOne(name)
        if (session !== undefined && !(await isExpired(session))) {
          headers.push(headerOf(session))
        }
      }
      return headers
    },
    async load(sessionId) {
      assertSessionId(sessionId)
      const session = await readOne(`${sessionId}${FILE_EXTENSION}`)
      if (session === undefined) {
        return
      }
      // Freeze existing account-owned legacy evidence before another
      // window's whole-session save can replace its transcript or spend.
      if (session.accountId !== undefined) {
        await budget.read(sessionId, session.accountId)
      }
      return await budget.project(session)
    },
    async save(session) {
      assertSessionId(session.sessionId)
      const hasFile = await hasSessionFile(fileFor(session.sessionId))
      const previous = await readOne(`${session.sessionId}${FILE_EXTENSION}`)
      if (
        (hasFile && previous === undefined) ||
        (previous !== undefined && previous.accountId !== session.accountId)
      ) {
        throw new Error(UI_TEXT.sessionBudgetStoreUnavailable)
      }
      // Seed from the fresh file before a stale DTO can discard historical
      // paid rows or nested children. The raw loader avoids projection recursion.
      if (previous?.accountId !== undefined) {
        await budget.read(previous.sessionId, previous.accountId)
      }
      // Before journal activation, keep fresh legacy spend when an older
      // snapshot arrives. Once active, only the journal supplies this field.
      const previousSpend = previous?.budgetSpentUsd
      const incomingSpend = session.budgetSpentUsd
      const withLegacySpend =
        previousSpend === undefined && incomingSpend === undefined
          ? session
          : { ...session, budgetSpentUsd: Math.max(previousSpend ?? 0, incomingSpend ?? 0) }
      const projected = await budget.project(withLegacySpend)
      if (
        projected.budgetSpentUsd !== undefined &&
        (!Number.isFinite(projected.budgetSpentUsd) || projected.budgetSpentUsd < 0)
      ) {
        throw new Error(UI_TEXT.sessionBudgetStoreUnavailable)
      }
      await writeFileAtomically(fileFor(session.sessionId), JSON.stringify(projected), {
        sleep: deps.sleep,
        ...(deps.rename !== undefined && { rename: deps.rename }),
      })
      if (previous === undefined && projected.accountId !== undefined) {
        await budget.read(projected.sessionId, projected.accountId)
      }
    },
    async remove(sessionId) {
      assertSessionId(sessionId)
      await rm(fileFor(sessionId), { force: true })
    },
  }
}

src/host/backend/jobBuild.ts:
// How a Windows job helper's C# (`jobSource.ts`) becomes a file in the
// extension's storage: named by the source's digest, compiled once by
// Windows PowerShell 5.1's `Add-Type`, moved into place, and the builds of
// earlier sources removed. M27's shell job assembly and M50's MCP launcher
// take the same steps with their own names and `Add-Type` options.

import { createHash, randomUUID } from 'node:crypto'
import { mkdir, readdir, rename, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { powerShellQuoted } from '../../core/shellQuote'
import { WINDOWS_POWERSHELL_COMMAND_ARGS } from '../../shared/constants'
import { type RunProgram, windowsPowerShell } from '../processTree'

const SOURCE_EXTENSION = '.cs'
const DIGEST_LENGTH = 16

/** One helper's build. */
export interface JobBuild {
  /** The file name before the source's digest. */
  readonly stem: string
  /** The file name's extension, which `Add-Type`'s output has too. */
  readonly extension: string
  /** `Add-Type`'s options for this helper's output. */
  readonly addTypeOptions: string
  /** What the log calls the built file. */
  readonly label: string
  /** Whether a built file is already at a path. */
  readonly isPresent: (file: string) => Promise<boolean>
}

/** The built file's name for this source (the whole C#, the shared half included). */
export function jobFileName(build: JobBuild, csharp: string): string {
  const digest = createHash('sha256').update(csharp).digest('hex').slice(0, DIGEST_LENGTH)
  return `${build.stem}${digest}${build.extension}`
}

/** Compiles `csharp` to `target`. */
export async function compileJob(
  build: JobBuild,
  target: string,
  csharp: string,
  systemRoot: string,
  run: RunProgram,
): Promise<void> {
  const directory = path.dirname(target)
  await mkdir(directory, { recursive: true })
  // Unique names, so two windows compiling at once never share a file.
  const stem = path.join(directory, randomUUID())
  const source = `${stem}${SOURCE_EXTENSION}`
  const output = `${stem}${build.extension}`
  const powershell = windowsPowerShell(systemRoot)
  try {
    await writeFile(source, csharp, 'utf8')
    await run(
      powershell.file,
      [
        ...WINDOWS_POWERSHELL_COMMAND_ARGS,
        `Add-Type -Path ${powerShellQuoted(source)} -OutputAssembly ${powerShellQuoted(output)} ${build.addTypeOptions}`,
      ],
      powershell.env,
    )
    try {
      await rename(output, target)
    } catch (error: unknown) {
      // Another window put the same file in place first.
      if (!(await build.isPresent(target))) {
        throw error
      }
    }
  } finally {
    await rm(source, { force: true })
    await rm(output, { force: true })
  }
}

/**
 * Removes the builds of earlier sources beside `current`. One that another
 * window still has loaded cannot go and stays until a later start; that is
 * logged.
 */
export async function removeStaleJobs(
  build: JobBuild,
  current: string,
  log: (message: string) => void,
): Promise<void> {
  const directory = path.dirname(current)
  const currentName = path.basename(current)
  try {
    const names = await readdir(directory)
    for (const name of names) {
      if (name !== currentName && name.startsWith(build.stem) && name.endsWith(build.extension)) {
        await rm(path.join(directory, name), { force: true })
      }
    }
  } catch (error: unknown) {
    log(`an earlier ${build.label} could not be removed yet (${String(error)})`)
  }
}

src/host/backend/jobSource.ts:
// The C# of the Windows job helpers (M27's shell job assembly, M50's MCP
// stdio launcher), shipped under native/windows/ and read when a helper is
// first built, instead of riding in the host bundle as strings (PLAN.md D6,
// the M55 and M56 size receipts). Each helper is its own file (its `using`
// directives first, then its types) followed by the Win32 half both share,
// MuseSparkMcpJob.cs. A missing or unreadable file fails that helper's
// preparation, which each helper already reports and falls back from.

import { readFile } from 'node:fs/promises'
import path from 'node:path'

const NATIVE_WINDOWS = path.join('native', 'windows')

/** The shipped files, relative to the extension's folder. */
export const JOB_SOURCE_FILES = {
  /** The Win32 half both helpers compile in. */
  shared: path.join(NATIVE_WINDOWS, 'MuseSparkMcpJob.cs'),
  /** The job type shell commands join (`shellJob.ts`), a library. */
  shellJob: path.join(NATIVE_WINDOWS, 'MuseSparkJob.cs'),
  /** The MCP launcher's entry and configuration (`mcpJobExecutable.ts`), a console application. */
  mcpLauncher: path.join(NATIVE_WINDOWS, 'MuseSparkMcpLauncher.cs'),
} as const

/** A helper whose whole C# `jobSourceReader` gives. */
export type JobHelper = Exclude<keyof typeof JOB_SOURCE_FILES, 'shared'>

/** Reads a helper's C# (its own file, then the shared half), each file at most once per window. */
export function jobSourceReader(extensionPath: string): (helper: JobHelper) => Promise<string> {
  const files = new Map<keyof typeof JOB_SOURCE_FILES, Promise<string>>()
  const read = (file: keyof typeof JOB_SOURCE_FILES): Promise<string> => {
    let text = files.get(file)
    if (text === undefined) {
      text = readFile(path.join(extensionPath, JOB_SOURCE_FILES[file]), 'utf8')
      files.set(file, text)
    }
    return text
  }
  return async (helper) => {
    const [own, shared] = await Promise.all([read(helper), read('shared')])
    return `${own}\n${shared}`
  }
}

src/host/backend/mcpJobExecutable.ts:
// Compile the Windows MCP job launcher once per source version. Each server
// starts this executable directly; PowerShell is used only while preparing it.
// M27's shell-job DLL remains separate for shell commands.

import { stat } from 'node:fs/promises'
import path from 'node:path'
import {
  MCP_JOB_SELF_TEST_ARGUMENT,
  MCP_JOB_SELF_TEST_TOKEN,
  SHELL_JOB_FOLDER,
} from '../../shared/constants'
import { runProgram } from '../processTree'
import { compileJob, type JobBuild, jobFileName, removeStaleJobs } from './jobBuild'
import type { ShellJobDeps } from './shellJob'

// The C# is the shipped native/windows/MuseSparkMcpLauncher.cs with the
// shared Win32 half (`jobSource.ts`).

/** Same compile inputs as M27, with an independent source and executable. */
export type McpJobExecutableDeps = ShellJobDeps

async function isPresent(file: string): Promise<boolean> {
  try {
    const fileInfo = await stat(file)
    return fileInfo.isFile()
  } catch {
    return false
  }
}

const EXECUTABLE: JobBuild = {
  stem: 'MuseSparkMcpJob-',
  extension: '.exe',
  addTypeOptions:
    "-OutputType ConsoleApplication -ReferencedAssemblies 'System.Runtime.Serialization','System.Xml'",
  label: 'MCP job executable',
  isPresent,
}

/** The executable's file name for this source (the whole C#, the shared half included). */
export function mcpJobExecutableName(csharp: string): string {
  return jobFileName(EXECUTABLE, csharp)
}

async function verify(executable: string, deps: McpJobExecutableDeps): Promise<void> {
  let answer: string
  try {
    answer = await (deps.run ?? runProgram)(executable, [MCP_JOB_SELF_TEST_ARGUMENT], {
      SystemRoot: deps.systemRoot,
    })
  } catch (error: unknown) {
    throw new Error(`the MCP job executable self-test failed (${String(error)})`, { cause: error })
  }
  if (answer.trim() !== MCP_JOB_SELF_TEST_TOKEN) {
    throw new Error(`the MCP job executable self-test answered ${JSON.stringify(answer.trim())}`)
  }
}

/** Undefined means stdio MCP must fail closed on this Windows machine. */
export function mcpJobExecutable(deps: McpJobExecutableDeps): () => Promise<string | undefined> {
  let ready: Promise<string | undefined> | undefined
  return () =>
    (ready ??= (async () => {
      try {
        const csharp = await deps.readJobSource('mcpLauncher')
        const executable = path.join(
          deps.storageDir,
          SHELL_JOB_FOLDER,
          mcpJobExecutableName(csharp),
        )
        let didCompile = false
        if (!(await isPresent(executable))) {
          await compileJob(EXECUTABLE, executable, csharp, deps.systemRoot, deps.run ?? runProgram)
          didCompile = true
        }
        await verify(executable, deps)
        if (didCompile) await removeStaleJobs(EXECUTABLE, executable, deps.log)
        return executable
      } catch (error: unknown) {
        deps.log(`Windows MCP job executable is unavailable (${String(error)})`)
        return
      }
    })())
}

src/host/backend/mcpJobLaunch.ts:
// Windows MCP stdio launcher (M50): the configured server inherits Node's
// binary pipe handles directly. The compiled C# executable creates the server
// suspended, assigns its no-breakaway kill-on-close job, and only then resumes
// it. It holds an actual handle to
// this extension process; when either it or the server exits, the job closes.

import { type ChildProcessWithoutNullStreams, spawn } from 'node:child_process'
import { Buffer } from 'node:buffer'
import { randomBytes, randomUUID } from 'node:crypto'
import { createServer } from 'node:net'
import { setEnvironmentVariable } from '../../core/backends/musecode/launch'
import {
  MCP_JOB_CONFIG_VARIABLE,
  MCP_JOB_HANDSHAKE_MAX_CHARS,
  MCP_JOB_NONCE_BYTES,
} from '../../shared/constants'

export interface McpJobLaunch {
  readonly executablePath: string
  readonly file: string
  readonly args: readonly string[]
  readonly isVerbatim: boolean
  readonly cwd: string
  /** Only the allowlisted and explicitly configured variables reach the server. */
  readonly env: NodeJS.ProcessEnv
  readonly log: (message: string) => void
}

/** The raw pipes belong to this ChildProcess; no text relay touches MCP frames. */
export function spawnMcpJob(launch: McpJobLaunch): ChildProcessWithoutNullStreams {
  const controlPipe = `muse-spark-mcp-${randomUUID()}`
  const controlNonce = randomBytes(MCP_JOB_NONCE_BYTES).toString('hex')
  let isClosed = false
  let child: ChildProcessWithoutNullStreams | undefined
  const control = createServer((socket) => {
    let request = ''
    let isAuthorized = false
    socket.on('error', (error) => {
      launch.log(`the MCP job control pipe closed: ${error.message}`)
    })
    socket.on('data', (bytes: Buffer) => {
      if (isAuthorized) return
      request += bytes.toString('utf8')
      if (request.length > MCP_JOB_HANDSHAKE_MAX_CHARS) {
        socket.destroy()
        return
      }
      const end = request.indexOf('\n')
      if (end === -1) {
        return
      }
      if (request.slice(0, end) !== `READY ${controlNonce}`) {
        socket.destroy()
        return
      }
      isAuthorized = true
      socket.end(`GO ${controlNonce}\n`)
      closeControl()
    })
  })
  const closeControl = () => {
    isClosed = true
    if (control.listening) control.close()
  }
  control.maxConnections = 1
  control.on('listening', () => {
    if (isClosed) control.close()
  })
  control.on('error', (error) => {
    launch.log(`the MCP job control pipe could not listen: ${error.message}`)
    child?.kill()
  })
  control.listen(`\\\\.\\pipe\\${controlPipe}`)
  control.unref()
  const payload = Buffer.from(
    JSON.stringify({
      file: launch.file,
      args: [...launch.args],
      cwd: launch.cwd,
      env: launch.env,
      parentPid: process.pid,
      isVerbatim: launch.isVerbatim,
      controlPipe,
      controlNonce,
    }),
    'utf8',
  ).toString('base64')
  const helperEnv = { ...launch.env }
  setEnvironmentVariable(helperEnv, 'win32', MCP_JOB_CONFIG_VARIABLE, payload)
  try {
    child = spawn(
      // nosemgrep: javascript.lang.security.detect-child-process.detect-child-process -- this executable is compiled from the packaged native/windows/MuseSparkMcpLauncher.cs and MuseSparkMcpJob.cs into a digest-named file in extension storage; configured MCP input stays in a private environment value (PLAN.md §8).
      launch.executablePath,
      [],
      {
        cwd: launch.cwd,
        env: helperEnv,
        stdio: ['pipe', 'pipe', 'pipe'],
        windowsHide: true,
      },
    )
    child.once('exit', closeControl)
    child.once('error', closeControl)
    return child
  } catch (error: unknown) {
    closeControl()
    throw error
  }
}

src/host/backend/mcpProcess.ts:
// Starting a stdio MCP server for the Model API backend (M50, PLAN.md D42).
//
// - **Environment.** The server gets what Muse Code gives its own: a small
//   allowlist of the extension host's variables (MCP_STDIO_ENV_ALLOWLIST),
//   then its entry's `env`. Nothing else of the host's environment, where a
//   key or token may sit, reaches it.
// - **Command.** An absolute path is taken as it is, a relative one against
//   the server's working directory, and a bare name is looked for on the
//   absolute entries of PATH only (D24: never the working directory), with
//   the extensions Windows starts (`.com`, `.exe`, `.bat`, `.cmd`).
// - **Batch files.** Windows starts a `.cmd` or `.bat` (`npx.cmd`, the usual
//   launcher) only through `cmd.exe`, as `CreateProcess` itself does. Every
//   part of the line is quoted, and a part that holds `"`, `%` or a line
//   break is refused, since cmd.exe would read it as syntax: arguments come
//   from the user's settings, never the model, and are never re-read.
// - **Stopping.** A POSIX process group or a Windows kill-on-close job owns
//   the entire process tree; the Windows helper exits on Stop or owner death.

import { type ChildProcessWithoutNullStreams, spawn } from 'node:child_process'
import { statSync } from 'node:fs'
import path from 'node:path'
import type { Readable, Writable } from 'node:stream'
import { environmentValue, setEnvironmentVariable } from '../../core/backends/musecode/launch'
import type { McpStdioLaunch } from '../../core/backends/modelapi/mcp/servers'
import type { McpChildProcess } from '../../core/backends/modelapi/mcp/stdio'
import { absolutePathEntries } from '../../core/executables'
import { MCP_STDIO_ENV_ALLOWLIST, TREE_EXIT_WAIT_MS } from '../../shared/constants'
import { killTree, sweepExitedTree, type TreeRoot, treeSpawnOptions } from '../processTree'
import { spawnMcpJob } from './mcpJobLaunch'

export interface McpSpawnDeps {
  readonly platform: NodeJS.Platform
  readonly systemRoot: string | undefined
  /** Windows: M50's compiled executable, which jobs the server before it runs. */
  readonly jobExecutablePath?: string | undefined
  /** The extension host's environment, read per server. */
  readonly env: () => NodeJS.ProcessEnv
  readonly isExistingFile: (filePath: string) => boolean
  readonly isExistingDirectory: (directory: string) => boolean
  readonly log: (message: string) => void
}

const PATH_VARIABLE = 'PATH'
const PATHEXT_VARIABLE = 'PATHEXT'
// The extensions `CreateProcess` starts, in Windows' default PATHEXT order.
const WINDOWS_LAUNCHABLE = ['.com', '.exe', '.bat', '.cmd'] as const
const WINDOWS_BATCH: ReadonlySet<string> = new Set(['.bat', '.cmd'])
const CMD_RELATIVE_PATH = String.raw`System32\cmd.exe`
// `/d` skips AutoRun; `/v:off` prevents inherited delayed expansion of `!`;
// `/s` keeps the quoted line as it is; `/c` runs it and ends.
const CMD_ARGUMENTS = ['/d', '/v:off', '/s', '/c'] as const
const CMD_UNQUOTABLE = /["%\r\n]/
const NUL = String.fromCodePoint(0)
const TRAILING_BACKSLASHES = /(\\+)$/
// A window can hold many MCP servers. Their exit sweeps must not launch a
// burst of PowerShell process-table helpers at shutdown.
const exitedSweepQueue: { current: Promise<void> } = { current: Promise.resolve() }

function queueExitedSweep(
  pid: number | undefined,
  startedAt: number,
  diedAt: number,
  deps: McpSpawnDeps,
): Promise<void> {
  if (deps.platform !== 'win32') {
    return (async () => {
      try {
        await sweepExitedTree(pid, startedAt, diedAt, deps)
      } catch (error: unknown) {
        deps.log(`the children of an exited MCP server could not be ended: ${String(error)}`)
      }
    })()
  }
  const previous = exitedSweepQueue.current
  const cleanup = (async () => {
    await previous
    try {
      await sweepExitedTree(pid, startedAt, diedAt, deps)
    } catch (error: unknown) {
      deps.log(`the children of an exited MCP server could not be swept: ${String(error)}`)
    }
  })()
  exitedSweepQueue.current = cleanup
  return cleanup
}

/** The allowlisted variables of the host's environment, then the entry's own. */
export function mcpServerEnvironment(
  hostEnv: NodeJS.ProcessEnv,
  entryEnv: Readonly<Record<string, string>>,
  platform: NodeJS.Platform,
): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {}
  for (const name of MCP_STDIO_ENV_ALLOWLIST) {
    const value = environmentValue(hostEnv, platform, name)
    if (value !== undefined) {
      setEnvironmentVariable(env, platform, name, value)
    }
  }
  for (const [name, value] of Object.entries(entryEnv)) {
    setEnvironmentVariable(env, platform, name, value)
  }
  return env
}

/** The extensions to try for a bare Windows name: PATHEXT's launchable ones, in its order. */
function windowsExtensions(env: NodeJS.ProcessEnv): readonly string[] {
  const listed = (environmentValue(env, 'win32', PATHEXT_VARIABLE) ?? '')
    .split(';')
    .map((extension) => extension.trim().toLowerCase())
  const known: readonly string[] = WINDOWS_LAUNCHABLE
  const ordered = listed.filter((extension) => known.includes(extension))
  return ordered.length === 0 ? WINDOWS_LAUNCHABLE : ordered
}

function candidatesFor(
  name: string,
  platform: NodeJS.Platform,
  env: NodeJS.ProcessEnv,
): readonly string[] {
  if (platform !== 'win32') {
    return [name]
  }
  const extension = path.win32.extname(name).toLowerCase()
  const known: readonly string[] = WINDOWS_LAUNCHABLE
  return known.includes(extension)
    ? [name]
    : windowsExtensions(env).map((candidate) => `${name}${candidate}`)
}

/** The file the command names, absolute; throws with the reason when there is none. */
export function resolveServerCommand(
  command: string,
  cwd: string,
  env: NodeJS.ProcessEnv,
  deps: Pick<McpSpawnDeps, 'platform' | 'isExistingFile'>,
): string {
  const p = deps.platform === 'win32' ? path.win32 : path.posix
  const name = p.basename(command)
  const hasDirectory =
    command.includes('/') || (deps.platform === 'win32' && command.includes('\\'))
  const directories = hasDirectory
    ? [p.dirname(p.resolve(cwd, command))]
    : absolutePathEntries(deps.platform, environmentValue(env, deps.platform, PATH_VARIABLE))
  for (const directory of directories) {
    for (const candidate of candidatesFor(name, deps.platform, env)) {
      const full = p.join(directory, candidate)
      if (deps.isExistingFile(full)) {
        return full
      }
    }
  }
  throw new Error(
    hasDirectory
      ? `its command ${name} does not exist`
      : `its command ${name} was not found on the absolute entries of PATH`,
  )
}

/** One part of a cmd.exe line: quoted, with the backslashes before the closing quote doubled. */
export function cmdQuoted(part: string): string {
  if (CMD_UNQUOTABLE.test(part) || part.includes(NUL)) {
    throw new Error(
      'a batch-file server cannot be given a double quote, a percent sign or a line break; start its program directly',
    )
  }
  return `"${part.replace(TRAILING_BACKSLASHES, '$1$1')}"`
}

/** What `spawn` is given: the file itself, or cmd.exe running a batch file. */
export function spawnLine(
  file: string,
  args: readonly string[],
  deps: Pick<McpSpawnDeps, 'platform' | 'systemRoot'>,
): { readonly file: string; readonly args: readonly string[]; readonly isVerbatim: boolean } {
  const isBatch =
    deps.platform === 'win32' && WINDOWS_BATCH.has(path.win32.extname(file).toLowerCase())
  if (!isBatch) {
    return { file, args, isVerbatim: false }
  }
  if (deps.systemRoot === undefined) {
    throw new Error('a batch-file server needs cmd.exe, and SystemRoot is not set')
  }
  const line = [file, ...args].map((part) => cmdQuoted(part)).join(' ')
  return {
    file: path.win32.join(deps.systemRoot, CMD_RELATIVE_PATH),
    args: [...CMD_ARGUMENTS, `"${line}"`],
    isVerbatim: true,
  }
}

function exitDescription(code: number | null, signal: NodeJS.Signals | null): string {
  return code === null
    ? `it was ended by ${signal ?? 'a signal'}`
    : `it exited with code ${String(code)}`
}

/** The Node process events are separate: `exit` can precede its last stdout bytes. */
export interface McpProcessHandle extends TreeRoot {
  readonly stdin: Writable
  readonly stdout: Readable
  readonly stderr: Readable
  onProcessExit(listener: (code: number | null, signal: NodeJS.Signals | null) => void): void
  onStreamsClose(listener: (code: number | null, signal: NodeJS.Signals | null) => void): void
  onStartError(listener: (error: Error) => void): void
}

function nodeProcessHandle(child: ChildProcessWithoutNullStreams): McpProcessHandle {
  return {
    get pid() {
      return child.pid
    },
    get exitCode() {
      return child.exitCode
    },
    get signalCode() {
      return child.signalCode
    },
    stdin: child.stdin,
    stdout: child.stdout,
    stderr: child.stderr,
    onProcessExit(listener) {
      child.once('exit', listener)
    },
    onStreamsClose(listener) {
      child.once('close', listener)
    },
    onStartError(listener) {
      child.once('error', listener)
    },
    once(event, listener) {
      child.once(event, listener)
    },
    kill(signal) {
      return child.kill(signal)
    },
  }
}

/** Deliver final bytes before ending MCP, while starting job cleanup at process exit. */
export function observeMcpProcess(
  child: McpProcessHandle,
  deps: McpSpawnDeps,
  startedAt: number,
  isJobLauncher = false,
): McpChildProcess {
  const exitListeners = new Set<(how: string) => void>()
  let exit: string | undefined
  let startError: string | undefined
  let processCode: number | null = null
  let processSignal: NodeJS.Signals | null = null
  let treeCleanup: Promise<void> | undefined
  const treeDeps = { platform: deps.platform, systemRoot: deps.systemRoot, log: deps.log }
  const exited = (how: string) => {
    if (exit !== undefined) {
      return
    }
    exit = how
    for (const listener of exitListeners) {
      listener(how)
    }
  }
  child.onProcessExit((code, signal) => {
    processCode = code
    processSignal = signal
    // A server that exits by itself can still leave a child. Start the
    // identity-checked sweep now; stdout may still have a final MCP frame.
    if (!isJobLauncher) {
      treeCleanup ??= queueExitedSweep(child.pid, startedAt, Date.now(), deps)
    }
  })
  child.onStreamsClose((code, signal) => {
    exited(startError ?? exitDescription(code ?? processCode, signal ?? processSignal))
  })
  child.onStartError((error) => {
    startError = `it could not be started: ${error.message}`
  })
  // A write to a server that has gone is reported by its exit, not thrown.
  child.stdin.on('error', (error) => {
    deps.log(`an MCP server's input could not be written: ${error.message}`)
  })
  return {
    write: (bytes) => {
      if (exit === undefined && child.stdin.writable) {
        child.stdin.write(bytes)
      }
    },
    endInput: () => {
      child.stdin.end()
    },
    onStdout: (listener) => {
      child.stdout.on('data', listener)
    },
    onStderr: (listener) => {
      child.stderr.on('data', listener)
    },
    onExit: (listener) => {
      if (exit === undefined) {
        exitListeners.add(listener)
      } else {
        listener(exit)
      }
    },
    kill: () => {
      if (isJobLauncher) {
        if (exit !== undefined) {
          return Promise.resolve()
        }
        treeCleanup ??= new Promise<void>((resolve, reject) => {
          const timer = setTimeout(() => {
            reject(new Error('the MCP job launcher did not exit after Stop'))
          }, TREE_EXIT_WAIT_MS)
          child.onStreamsClose(() => {
            clearTimeout(timer)
            resolve()
          })
          const didSignal = child.kill()
          if (didSignal || child.exitCode !== null || child.signalCode !== null) {
            return
          }
          clearTimeout(timer)
          reject(new Error('the MCP job launcher could not be stopped'))
        })
        return treeCleanup
      }
      if (treeCleanup !== undefined) {
        return treeCleanup
      }
      // Node can set exitCode just before it emits `exit`. Let that event
      // capture the real death time and start the sweep; do not cache
      // killTree's early no-op over the pending exit cleanup.
      if (child.exitCode !== null || child.signalCode !== null) {
        return new Promise<void>((resolve) => {
          child.onProcessExit(() => {
            void (treeCleanup ?? Promise.resolve()).then(resolve)
          })
        })
      }
      treeCleanup ??= killTree(child, treeDeps, startedAt)
      return treeCleanup
    },
  }
}

/** The pool's spawner (McpPoolDeps.spawn); throws with the reason a server cannot start. */
export function mcpServerSpawner(
  deps: McpSpawnDeps,
): (launch: McpStdioLaunch, cwd: string) => McpChildProcess {
  return (launch, cwd) => {
    if (!deps.isExistingDirectory(cwd)) {
      throw new Error(`its working directory ${cwd} does not exist`)
    }
    const env = mcpServerEnvironment(deps.env(), launch.env, deps.platform)
    const file = resolveServerCommand(launch.command, cwd, env, deps)
    const line = spawnLine(file, launch.args, deps)
    const startedAt = Date.now()
    if (deps.platform === 'win32') {
      if (deps.jobExecutablePath === undefined || deps.systemRoot === undefined) {
        throw new Error('Windows job containment is unavailable; the MCP server was not started')
      }
      const child = spawnMcpJob({
        executablePath: deps.jobExecutablePath,
        file: line.file,
        args: line.args,
        isVerbatim: line.isVerbatim,
        cwd,
        env,
        log: deps.log,
      })
      return observeMcpProcess(nodeProcessHandle(child), deps, startedAt, true)
    }
    // nosemgrep: javascript.lang.security.detect-child-process.detect-child-process -- the server the user configured in Muse Code's settings, started only in a trusted workspace, with an absolute resolved command and a fixed argument array (PLAN.md §8).
    const child = spawn(line.file, [...line.args], {
      cwd,
      env,
      stdio: ['pipe', 'pipe', 'pipe'],
      windowsHide: true,
      ...treeSpawnOptions(deps.platform),
    })
    return observeMcpProcess(nodeProcessHandle(child), deps, startedAt)
  }
}

/** Whether a directory is there: the real spawner's probe. */
export function isExistingDirectory(directory: string): boolean {
  try {
    return statSync(directory).isDirectory()
  } catch {
    return false
  }
}

/** Whether a file (not a directory) is there: the real spawner's probe. */
export function isExistingFile(filePath: string): boolean {
  try {
    return statSync(filePath).isFile()
  } catch {
    return false
  }
}

src/host/backend/mcpServers.ts:
// The Model API backend's MCP servers as this window runs them (M50, PLAN.md
// D42): Muse Code's settings file read by M31's reader each time they start,
// stdio servers started by the real spawner (mcpProcess.ts), remote ones
// reached with the extension host's `fetch`, and `${VAR}` read from the
// extension host's environment. The pool itself is the Model API bundle's
// (M57, PLAN.md D6); this module gives it this window's parts.

import type { McpPoolDeps } from '../../core/backends/modelapi/mcp/pool'
import { environmentValue } from '../../core/backends/musecode/launch'
import { readMcpServerEntries } from '../../core/backends/musecode/museConfigView'
import { UI_TEXT } from '../../shared/constants'
import { readTextIfPresent } from '../cliFeatures'
import type { Logger } from '../logger'
import { isExistingDirectory, isExistingFile, mcpServerSpawner } from './mcpProcess'

export interface ModelApiMcpDeps {
  /** Awaited before a workspace-capable local stdio process can start. */
  readonly beforeWorkspaceProcessStart: () => Promise<void>
  readonly workspaceRoot: string
  /** Muse Code's settings file where `muse serve` would read it. */
  readonly settingsPath: () => string
  readonly isWorkspaceTrusted: () => boolean
  /** The extension's version, sent as the client's in `initialize`. */
  readonly clientVersion: string
  readonly platform: NodeJS.Platform
  /** Windows: the compiled M50 job executable; absent means stdio fails closed. */
  readonly jobExecutablePath?: string | undefined
  readonly env: () => NodeJS.ProcessEnv
  readonly fetch: typeof fetch
  readonly log: Logger
}

export function modelApiMcpPoolDeps(deps: ModelApiMcpDeps): McpPoolDeps {
  const spawn = mcpServerSpawner({
    platform: deps.platform,
    systemRoot: environmentValue(deps.env(), deps.platform, 'SystemRoot'),
    jobExecutablePath: deps.jobExecutablePath,
    env: deps.env,
    isExistingFile,
    isExistingDirectory,
    log: (message) => {
      deps.log.warn(message)
    },
  })
  return {
    readSettings: () => readMcpServerEntries(readTextIfPresent(deps.settingsPath())),
    lookupEnv: (name) => environmentValue(deps.env(), deps.platform, name),
    isWorkspaceTrusted: deps.isWorkspaceTrusted,
    workspaceRoot: deps.workspaceRoot,
    platform: deps.platform,
    spawn: async (launch, cwd, isCancelled) => {
      await deps.beforeWorkspaceProcessStart()
      if (isCancelled?.() === true || !deps.isWorkspaceTrusted()) {
        throw new Error(UI_TEXT.questionCancelled)
      }
      return spawn(launch, cwd)
    },
    fetch: deps.fetch,
    clientVersion: deps.clientVersion,
    log: deps.log,
  }
}

src/host/backend/memoryIo.ts:
// The file access behind Muse Code's memory (M49, PLAN.md D41): the Model
// API tools' own reads and existing-file replacements (UTF-8 text, a size
// cap), no-clobber publication of complete new notes, and a folder's entries
// by kind, with a link or junction
// reported as neither a file nor a folder so the store never follows one.
// The workspace's name for the project folder is taken from the path as the
// operating system spells it, which is what Muse Code hashes.

import { realpath } from 'node:fs'
import { readdir } from 'node:fs/promises'
import path from 'node:path'
import { promisify } from 'node:util'
import { MEMORY_STAGE_FILE_MODE } from '../../shared/constants'
import type { StagedFile, ToolIo } from '../../core/backends/modelapi/tools'
import type { MemoryDirectoryEntry, MemoryIo } from '../../core/memory/memoryStore'
import { isMissingPath } from '../canonicalPath'
import { createFileExclusively } from '../fsAtomic'

/**
 * A folder's entries by kind, a link or junction reported as neither file
 * nor folder; rejects as `readdir` does (plans, M79, tell a missing folder
 * from one that is a file).
 */
export async function entriesByKind(
  absolutePath: string,
): Promise<readonly MemoryDirectoryEntry[]> {
  const entries = await readdir(absolutePath, { withFileTypes: true })
  return entries.map((entry) => {
    let kind: MemoryDirectoryEntry['kind'] = 'other'
    if (entry.isFile()) {
      kind = 'file'
    } else if (entry.isDirectory()) {
      kind = 'directory'
    }
    return { name: entry.name, kind }
  })
}

/** A folder's entries; none when it does not exist. */
export async function listMemoryEntries(
  absolutePath: string,
): Promise<readonly MemoryDirectoryEntry[]> {
  try {
    return await entriesByKind(absolutePath)
  } catch (error: unknown) {
    if (isMissingPath(error)) {
      return []
    }
    throw error
  }
}

export function createMemoryIo(
  files: Pick<ToolIo, 'readFile' | 'writeFile' | 'realPath' | 'hasUnsavedChanges'>,
  options: {
    /** A warning when cleanup fails after the target has already been published. */
    readonly warn: (message: string) => void
    /** Replace the hard-link call in a deterministic publication test. */
    readonly publish?: (stage: string, target: string) => Promise<void>
    /** Existing atomic staging seam for a deterministic publication test. */
    readonly staged?: (file: StagedFile) => Promise<void>
    /** Runtime owners fence publication after asynchronous staging. */
    readonly assertCanWrite?: () => void
    /**
     * Exclusive creation has no ToolIo write call: what the tool io does
     * around a write runs here instead, the checkpoint storage refused and,
     * through a turn's recording io (M86), its intent journaled before
     * `publish` runs.
     */
    readonly aroundCreate?: (
      absolutePath: string,
      content: string,
      checkedPath: string | undefined,
      publish: (staged?: (file: StagedFile) => Promise<void>) => Promise<void>,
    ) => Promise<void>
  },
): MemoryIo {
  const admission = (assertCanWrite?: () => void) => () => {
    options.assertCanWrite?.()
    assertCanWrite?.()
  }
  const createNote = (
    absolutePath: string,
    content: string,
    checkedPath: string | undefined,
    assertCanWrite: (() => void) | undefined,
    staged?: (file: StagedFile) => Promise<void>,
  ) =>
    createFileExclusively(absolutePath, content, {
      mode: MEMORY_STAGE_FILE_MODE,
      assertCanWrite: admission(assertCanWrite),
      // The folder `locate` checked (C2-4): one swapped for a link since is refused.
      ...(checkedPath !== undefined && { expectedDirectory: path.dirname(checkedPath) }),
      // The stage is named after the note, which the model named: not logged (M39).
      warn: (_stage, isPublished, error) => {
        const when = isPublished ? 'after the note was published' : 'after the write failed'
        const code =
          typeof error === 'object' && error !== null && 'code' in error ? error.code : undefined
        options.warn(`a memory note's hidden stage could not be removed ${when} (${String(code)})`)
      },
      ...(options.publish !== undefined && { publish: options.publish }),
      staged: async (file) => {
        await options.staged?.(file)
        await staged?.(file)
      },
    })
  return {
    readFile: (absolutePath) => files.readFile(absolutePath),
    hasUnsavedChanges: (absolutePath) => files.hasUnsavedChanges(absolutePath),
    // The checked path holds a replacement to where `locate` found the note (C2-4, M86).
    writeFile: (absolutePath, content, checkedPath, assertCanWrite) =>
      files.writeFile(absolutePath, content, checkedPath, admission(assertCanWrite)),
    createFile: async (absolutePath, content, checkedPath, assertCanWrite) => {
      const publish = (staged?: (file: StagedFile) => Promise<void>) =>
        createNote(absolutePath, content, checkedPath, assertCanWrite, staged)
      await (options.aroundCreate === undefined
        ? publish()
        : options.aroundCreate(absolutePath, content, checkedPath, publish))
    },
    realPath: (absolutePath) => files.realPath(absolutePath),
    listEntries: listMemoryEntries,
  }
}

/**
 * The folder as the operating system names it: links resolved and each
 * name in its own letter case (VS Code lowers a Windows drive letter; Muse
 * Code's `canonicalize` does not).
 */
export const systemPath: (absolutePath: string) => Promise<string> = promisify(realpath.native)

// Owns the Model API host for this extension host (M7): one in-process
// `ModelApiHost` over the real `fetch`, the stored key and the workspace's
// files, with the MCP servers of Muse Code's settings (M50), which it starts
// with the first conversation. Disposing it forgets the window's sessions
// and stops those servers.
//
// The host itself lives in a bundle of its own, dist/modelApi.js (M57,
// PLAN.md D6), required here the first time it is built, so activation does
// not load it. A missing or unreadable bundle fails that build like any
// other failure: the caller hears a sentence, the log gets the cause, and the
// next call tries again.

