// The Muse Code CLI's own settings file, read for two facts. Whether native
// subagent delegation is on (PLAN.md D17): Muse Code 1.3.0 hides its
// subagent tools unless `run.subagent_delegation_mode` is `"auto"` in
// `$XDG_CONFIG_HOME/muse/settings.json` (else `~/.config/muse/settings.json`),
// and the panel can only spawn agents when the CLI lets the model do so. And
// when the model may start a workflow (M47, PLAN.md D40):
// `run.workflow_trigger_mode`, `auto`, `explicit` or `off`.
// Read only; the extension never writes this file. The user opens it from
// the Agent map when they want to change it.

import * as z from 'zod/mini'
import {
  MUSE_DELEGATION_DEFAULT,
  MUSE_SETTINGS_FILE_SEGMENTS,
  MUSE_WORKFLOW_TRIGGER_DEFAULT,
} from '../../shared/constants'
import type { CredentialPathInput } from '../../core/backends/musecode/launch'
import path from 'node:path'

export interface MuseSettingsDeps extends CredentialPathInput {
  /** Returns undefined when the file cannot be read. */
  readonly readTextFile: (filePath: string) => string | undefined
}

/**
 * Only the `run` block; each member the extension reads is checked on its
 * own, so one of another type costs that fact alone, never the other.
 */
const settingsSchema = z.object({ run: z.optional(z.record(z.string(), z.unknown())) })

export function museSettingsPath(input: CredentialPathInput): string {
  const p = input.platform === 'win32' ? path.win32 : path.posix
  const configHome = input.xdgConfigHome ?? p.join(input.homeDir, '.config')
  return p.join(configHome, ...MUSE_SETTINGS_FILE_SEGMENTS)
}

/** One string member of the file's `run` block; undefined when missing, unreadable or not a string. */
function readRunSetting(deps: MuseSettingsDeps, key: string): string | undefined {
  const text = deps.readTextFile(museSettingsPath(deps))
  if (text === undefined) {
    return undefined
  }
  try {
    const value = settingsSchema.safeParse(JSON.parse(text)).data?.run?.[key]
    return typeof value === 'string' ? value : undefined
  } catch {
    return undefined
  }
}

/** `run.subagent_delegation_mode`, or the CLI's default when unset or unreadable. */
export function readDelegationMode(deps: MuseSettingsDeps): string {
  return readRunSetting(deps, 'subagent_delegation_mode') ?? MUSE_DELEGATION_DEFAULT
}

/** `run.workflow_trigger_mode` (M47), or the CLI's default when unset or unreadable. */
export function readWorkflowTriggerMode(deps: MuseSettingsDeps): string {
  return readRunSetting(deps, 'workflow_trigger_mode') ?? MUSE_WORKFLOW_TRIGGER_DEFAULT
}

src/host/backend/sandboxSetup.ts:
// Gets Muse Code's Windows sandbox set up without sending the user to an
// elevated terminal: checks `muse sandbox windows check` when a chat surface
// opens (and again when a shell tool reports the sandbox missing), offers the
// one-time setup in a notification, relaunches the CLI through UAC on
// "Set up now", and re-checks. Every VS Code and process call is injected so
// the flow is unit-tested on every platform.

import type { LaunchResolution } from '../../core/backends/musecode/launch'
import { failureForLog } from '../../core/backends/musecode/logText'
import {
  type CliInvocation,
  elevatedInvocation,
  parseSandboxCheck,
  type SandboxCheck,
  sandboxCheckInvocation,
  sandboxSetupInvocation,
} from '../../core/backends/musecode/sandbox'
import {
  SANDBOX_CHECK_TIMEOUT_MS,
  SANDBOX_SETUP_TIMEOUT_MS,
  SANDBOX_STATUS_READY,
  SANDBOX_STATUS_SETUP_REQUIRED,
  UI_TEXT,
} from '../../shared/constants'
import { fill } from '../../shared/l10n/text'
import type { Logger } from '../logger'

export interface ProcessResult {
  /** The exit code, or a negative number when the process could not run or was killed. */
  readonly exitCode: number
  readonly stdout: string
  readonly stderr: string
}

export interface SandboxSetupDeps {
  readonly platform: NodeJS.Platform
  /** `%SystemRoot%`; undefined off Windows. */
  readonly systemRoot: string | undefined
  readonly resolveLaunch: () => LaunchResolution
  /** Runs a process to completion; startup admission may reject before launch. */
  readonly run: (invocation: CliInvocation, timeoutMs: number) => Promise<ProcessResult>
  /** A warning notification with buttons; resolves to the chosen label. */
  readonly showWarning: (
    message: string,
    ...choices: readonly string[]
  ) => Promise<string | undefined>
  readonly showInformation: (message: string) => void
  /** The "Don't ask again" flag in the extension's own global state. */
  readonly isPromptSuppressed: () => boolean
  readonly suppressPrompt: () => Promise<void>
  readonly log: Logger
}

const WINDOWS = 'win32'
const FAILED_EXIT_CODE = -1

/** A one-line description of what a process said, for notifications and logs. */
function firstLine(text: string): string {
  return text.trim().split(/\r?\n/, 1)[0] ?? ''
}

export type SandboxOfferTrigger = 'startup' | 'failure'

export class SandboxSetup {
  private hasOffered = false
  private inFlight: Promise<void> | undefined

  public constructor(private readonly deps: SandboxSetupDeps) {}

  private get isWindows(): boolean {
    return this.deps.platform === WINDOWS
  }

  private async setUp(): Promise<void> {
    const resolution = this.deps.resolveLaunch()
    if (!resolution.ok || this.deps.systemRoot === undefined) {
      await this.deps.showWarning(UI_TEXT.sandboxCliMissing)
      return
    }
    const invocation = elevatedInvocation(
      this.deps.systemRoot,
      sandboxSetupInvocation(resolution.launch),
    )
    this.deps.log.info(`Sandbox setup: ${invocation.command} ${invocation.args.join(' ')}`)
    const result = await this.deps.run(invocation, SANDBOX_SETUP_TIMEOUT_MS)
    if (result.exitCode !== 0) {
      const detail = firstLine(result.stderr) || firstLine(result.stdout)
      const outcome =
        result.exitCode === FAILED_EXIT_CODE ? 'did not run' : `exited ${String(result.exitCode)}`
      this.deps.log.warn(`Sandbox setup ${outcome}: ${detail}`)
      // The code as the process gave it: no digit grouping for a status.
      const exit = fill(UI_TEXT.sandboxExitCode, { code: String(result.exitCode) })
      await this.deps.showWarning(
        `${UI_TEXT.sandboxCancelled} (${exit}${detail === '' ? '' : `: ${detail}`}).`,
      )
      return
    }
    const report = await this.check()
    if (report?.status === SANDBOX_STATUS_READY) {
      this.deps.showInformation(UI_TEXT.sandboxReady)
      return
    }
    await this.deps.showWarning(
      `${UI_TEXT.sandboxStillRequired}${report?.reason === undefined ? '.' : `: ${report.reason}.`}`,
    )
  }

  private async offer(): Promise<void> {
    const report = await this.check()
    if (report?.status !== SANDBOX_STATUS_SETUP_REQUIRED) {
      return
    }
    const choice = await this.deps.showWarning(
      UI_TEXT.sandboxOffer,
      UI_TEXT.sandboxSetUpNow,
      UI_TEXT.sandboxNotNow,
      UI_TEXT.sandboxDontAskAgain,
    )
    if (choice === UI_TEXT.sandboxSetUpNow) {
      await this.setUp()
    } else if (choice === UI_TEXT.sandboxDontAskAgain) {
      await this.deps.suppressPrompt()
    }
  }

  private async offerTracked(): Promise<void> {
    try {
      await this.offer()
    } finally {
      this.inFlight = undefined
    }
  }

  /**
   * The sandbox report, or undefined off Windows or without the CLI. Never
   * throws: a check that cannot run is logged and reported as `unknown`.
   */
  public async check(): Promise<SandboxCheck | undefined> {
    if (!this.isWindows) {
      return undefined
    }
    const resolution = this.deps.resolveLaunch()
    if (!resolution.ok) {
      this.deps.log.warn(`Sandbox check skipped: ${resolution.reason}`)
      return undefined
    }
    let result: ProcessResult
    try {
      result = await this.deps.run(
        sandboxCheckInvocation(resolution.launch),
        SANDBOX_CHECK_TIMEOUT_MS,
      )
    } catch (error: unknown) {
      this.deps.log.warn(`Sandbox check could not start: ${failureForLog(error)}`)
      return parseSandboxCheck('')
    }
    const report = parseSandboxCheck(`${result.stdout}\n${result.stderr}`)
    this.deps.log.info(
      `Sandbox check: status=${report.status} exit=${String(result.exitCode)}${report.reason === undefined ? '' : ` reason=${report.reason}`}`,
    )
    for (const diagnostic of report.diagnostics) {
      this.deps.log.info(`Sandbox diagnostic: ${diagnostic}`)
    }
    return report
  }

  /**
   * Offers the setup when it is needed. `startup` asks at most once per
   * extension host and honours "Don't ask again"; `failure` (a shell tool just
   * reported the sandbox missing) asks again even after "Not now".
   */
  public offerIfNeeded(trigger: SandboxOfferTrigger): Promise<void> {
    if (!this.isWindows) {
      return Promise.resolve()
    }
    if (this.inFlight !== undefined) {
      return this.inFlight
    }
    if (trigger === 'startup' && (this.hasOffered || this.deps.isPromptSuppressed())) {
      return Promise.resolve()
    }
    this.hasOffered = true
    this.inFlight = this.offerTracked()
    return this.inFlight
  }

  /** The "Set Up Shell Sandbox" command: always reports, sets up when needed. */
  public async runCommand(): Promise<void> {
    if (!this.isWindows) {
      this.deps.showInformation(UI_TEXT.sandboxNotNeeded)
      return
    }
    const report = await this.check()
    if (report === undefined) {
      await this.deps.showWarning(UI_TEXT.sandboxCliMissing)
      return
    }
    if (report.status === SANDBOX_STATUS_READY) {
      this.deps.showInformation(UI_TEXT.sandboxAlreadyReady)
      return
    }
    await this.setUp()
  }
}

src/host/backend/selectedHost.ts:
// Admission for the extension's host selector. Raw credential presence may
// choose a backend, but never grants a host after sign-out or an auth change.

import type { BackendKind } from '../../core/agent/agentBackend'
import type { BackendChoice } from '../../core/backendSelection'
import { UI_TEXT } from '../../shared/constants'

export async function chooseAuthorizedHost<T>(
  admittedBackend: () => BackendKind | undefined,
  readRawChoice: () => Promise<BackendChoice>,
  openHost: (kind: BackendKind) => Promise<T>,
  admissionGeneration: () => number,
): Promise<T> {
  const before = admittedBackend()
  if (before === undefined) {
    throw new Error(UI_TEXT.sendDisabledReason)
  }
  const generation = admissionGeneration()
  const choice = await readRawChoice()
  if (
    admissionGeneration() !== generation ||
    admittedBackend() !== before ||
    choice.kind !== before ||
    choice.status !== 'signedIn'
  ) {
    throw new Error(UI_TEXT.sendDisabledReason)
  }
  const host = await openHost(before)
  if (admissionGeneration() !== generation || admittedBackend() !== before) {
    // ensureHost returns a manager-owned cache entry. The manager stops it on
    // a real backend shutdown; a secondary key change must leave CLI chat up.
    throw new Error(UI_TEXT.sendDisabledReason)
  }
  return host
}

src/host/backend/sessionBudgetJournal.ts:
// Shared session spend (M82): each request owns one durable row before its
// synchronous final admission. Rows are never elected over, stolen, or
// removed; an unclosed request keeps its full liability after a crash.
// One-time seed creation has a durable intent outside the journal scope,
// so an incomplete or missing scope can never be silently seeded again.

import { randomUUID } from 'node:crypto'
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { mkdir, stat } from 'node:fs/promises'
import path from 'node:path'
import * as z from 'zod/mini'
import type {
  SessionBudgetClaim,
  SessionBudgetJournal,
  SessionBudgetTotal,
} from '../../core/backends/modelapi/sessionBudget'
import type { StoredSession } from '../../core/backends/modelapi/sessionStore'
import { formatUsd } from '../../core/usage/insights'
import { UI_TEXT } from '../../shared/constants'
import { fill } from '../../shared/l10n/text'
import { writeFileAtomically } from '../fsAtomic'
import { storeErrorCode } from './storeErrors'

const JOURNAL_DIRECTORY = 'budget-journal'
const INTENT_DIRECTORY = 'budget-intents'
const CLAIMS_DIRECTORY = 'claims'
const SEED_FILE = 'seed.json'
const CLAIM_FILE = 'claim.json'
const MISSING = 'ENOENT'
const EXISTS = 'EEXIST'
const SESSION_ID = /^[A-Za-z0-9_-]+$/
const ACCOUNT_ID = /^[a-f0-9]{64}$/
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/

const seedSchema = z.object({
  version: z.literal(1),
  scopeId: z.string().check(z.regex(UUID)),
  sessionId: z.string().check(z.regex(SESSION_ID)),
  accountId: z.string().check(z.regex(ACCOUNT_ID)),
  spentUsd: z.number().check(z.nonnegative()),
  hasUnknownHistoricalFees: z.boolean(),
})
type Seed = z.infer<typeof seedSchema>

const claimSchema = z.object({
  version: z.literal(1),
  scopeId: z.string().check(z.regex(UUID)),
  claimId: z.string().check(z.regex(UUID)),
  ownerId: z.string().check(z.regex(UUID)),
  sessionId: z.string().check(z.regex(SESSION_ID)),
  accountId: z.string().check(z.regex(ACCOUNT_ID)),
  reservedUsd: z.number().check(z.nonnegative()),
  settledUsd: z.optional(z.number().check(z.nonnegative())),
  hasUnknownCost: z.optional(z.boolean()),
  isUnbounded: z.optional(z.boolean()),
})
type Claim = z.infer<typeof claimSchema>

const claimFlagsSchema = z.object({
  isUnbounded: z.optional(z.boolean()),
  hasUnknownCost: z.optional(z.boolean()),
})
type ClaimFlags = z.infer<typeof claimFlagsSchema>

export interface SessionBudgetJournalDeps {
  readonly directory: string
  /** Reads the authoritative session file without its journal projection. */
  readonly loadSession: (sessionId: string) => Promise<StoredSession | undefined>
  readonly sleep: (ms: number) => Promise<void>
  readonly rename?: (from: string, to: string) => Promise<void>
}

interface ProjectedSessionBudgetJournal extends SessionBudgetJournal {
  /** Existing journal data owns this field; an unopened journal leaves a snapshot alone. */
  project(session: StoredSession): Promise<StoredSession>
}

interface Scope {
  readonly sessionId: string
  readonly accountId: string
  readonly directory: string
  readonly intent: string
}

function unavailable(cause?: unknown): Error {
  return new Error(UI_TEXT.sessionBudgetStoreUnavailable, { cause })
}

function assertCost(costUsd: number): void {
  if (!Number.isFinite(costUsd) || costUsd < 0) {
    throw unavailable()
  }
}

async function isPresent(file: string): Promise<boolean> {
  try {
    await stat(file)
    return true
  } catch (error: unknown) {
    if (storeErrorCode(error) === MISSING) {
      return false
    }
    throw unavailable(error)
  }
}

function hasHistoricalTokens(session: StoredSession): boolean {
  return (
    session.usage.inputTokens > 0 ||
    session.usage.outputTokens > 0 ||
    (session.children ?? []).some((child) => hasHistoricalTokens(child.session))
  )
}

function hasHistoricalFlatFees(session: StoredSession): boolean {
  return (
    session.transcript.some(
      ({ item }) => item.paid === 'webSearch' || item.paid === 'imageGeneration',
    ) || (session.children ?? []).some((child) => hasHistoricalFlatFees(child.session))
  )
}

/** The parent's recorded spend includes children; flat fee rows remain independently unknown. */
function hasUnknownHistory(session: StoredSession): boolean {
  if (session.budgetIsFreshFork === true) {
    if (
      session.budgetSpentUsd !== 0 ||
      session.forkedFrom === undefined ||
      !SESSION_ID.test(session.forkedFrom)
    ) {
      throw unavailable()
    }
    // Only the controlled first fork snapshot proves these copied rows
    // belong to the parent. Legacy zero/forkedFrom without the marker does not.
    return false
  }
  return (
    (session.budgetSpentUsd === undefined && hasHistoricalTokens(session)) ||
    hasHistoricalFlatFees(session)
  )
}

function readSeed(scope: Scope): Seed {
  try {
    if (!statSync(scope.intent).isDirectory() || !statSync(scope.directory).isDirectory()) {
      throw unavailable()
    }
    const seed = seedSchema.parse(
      JSON.parse(readFileSync(path.join(scope.directory, SEED_FILE), 'utf8')),
    )
    if (seed.sessionId !== scope.sessionId || seed.accountId !== scope.accountId) {
      throw unavailable()
    }
    return seed
  } catch (error: unknown) {
    throw unavailable(error)
  }
}

function readClaim(scope: Scope, seed: Seed, claimId: string): Claim {
  try {
    if (!UUID.test(claimId)) {
      throw unavailable()
    }
    const claim = claimSchema.parse(
      JSON.parse(
        readFileSync(path.join(scope.directory, CLAIMS_DIRECTORY, claimId, CLAIM_FILE), 'utf8'),
      ),
    )
    if (
      claim.scopeId !== seed.scopeId ||
      claim.claimId !== claimId ||
      claim.sessionId !== scope.sessionId ||
      claim.accountId !== scope.accountId
    ) {
      throw unavailable()
    }
    return claim
  } catch (error: unknown) {
    throw unavailable(error)
  }
}

function totalFor(scope: Scope): SessionBudgetTotal {
  try {
    const seed = readSeed(scope)
    let spentUsd = seed.spentUsd
    let hasUnknownHistoricalFees = seed.hasUnknownHistoricalFees
    const claimIds = readdirSync(path.join(scope.directory, CLAIMS_DIRECTORY))
    for (const claimId of claimIds) {
      const claim = readClaim(scope, seed, claimId)
      spentUsd += claim.settledUsd ?? claim.reservedUsd
      hasUnknownHistoricalFees ||=
        claim.hasUnknownCost === true ||
        (claim.isUnbounded === true && claim.settledUsd === undefined)
    }
    assertCost(spentUsd)
    return { spentUsd, hasUnknownHistoricalFees }
  } catch (error: unknown) {
    throw unavailable(error)
  }
}

export function createSessionBudgetJournal(
  deps: SessionBudgetJournalDeps,
): ProjectedSessionBudgetJournal {
  const ownerId = randomUUID()
  const options = {
    sleep: deps.sleep,
    ...(deps.rename !== undefined && { rename: deps.rename }),
  }

  const scopeFor = (sessionId: string, accountId: string): Scope => {
    if (!SESSION_ID.test(sessionId) || !ACCOUNT_ID.test(accountId)) {
      throw unavailable()
    }
    return {
      sessionId,
      accountId,
      directory: path.join(deps.directory, JOURNAL_DIRECTORY, accountId, sessionId),
      intent: path.join(deps.directory, INTENT_DIRECTORY, accountId, sessionId),
    }
  }

  const ensure = async (scope: Scope): Promise<Seed> => {
    const [hasIntent, hasScope] = await Promise.all([
      isPresent(scope.intent),
      isPresent(scope.directory),
    ])
    if (hasIntent || hasScope) {
      // An existing intent never grants another writer the right to seed.
      return readSeed(scope)
    }
    const session = await deps.loadSession(scope.sessionId)
    if (session?.sessionId !== scope.sessionId || session.accountId !== scope.accountId) {
      throw unavailable()
    }
    try {
      await mkdir(path.dirname(scope.intent), { recursive: true })
      await mkdir(scope.intent)
    } catch (error: unknown) {
      if (storeErrorCode(error) === EXISTS) {
        return readSeed(scope)
      }
      throw unavailable(error)
    }
    try {
      // Only the intent creator reaches this path. A crash leaves the
      // intent behind and future readers refuse, rather than resetting spend.
      const fresh = await deps.loadSession(scope.sessionId)
      if (fresh?.sessionId !== scope.sessionId || fresh.accountId !== scope.accountId) {
        throw unavailable()
      }
      await mkdir(path.dirname(scope.directory), { recursive: true })
      await mkdir(scope.directory)
      await mkdir(path.join(scope.directory, CLAIMS_DIRECTORY))
      const spentUsd = fresh.budgetSpentUsd ?? 0
      assertCost(spentUsd)
      const seed: Seed = {
        version: 1,
        scopeId: randomUUID(),
        sessionId: scope.sessionId,
        accountId: scope.accountId,
        spentUsd,
        hasUnknownHistoricalFees: hasUnknownHistory(fresh),
      }
      await writeFileAtomically(
        path.join(scope.directory, SEED_FILE),
        JSON.stringify(seed),
        options,
      )
      return readSeed(scope)
    } catch (error: unknown) {
      throw unavailable(error)
    }
  }

  const writeClaim = async (
    scope: Scope,
    seed: Seed,
    costUsd: number,
    isNonsentReservation: boolean,
    flags: ClaimFlags = {},
  ): Promise<Claim> => {
    assertCost(costUsd)
    const claim: Claim = {
      version: 1,
      scopeId: seed.scopeId,
      claimId: randomUUID(),
      ownerId,
      sessionId: scope.sessionId,
      accountId: scope.accountId,
      reservedUsd: costUsd,
      ...(flags.hasUnknownCost === true && { hasUnknownCost: true }),
      ...(flags.isUnbounded === true && { isUnbounded: true }),
    }
    const directory = path.join(scope.directory, CLAIMS_DIRECTORY, claim.claimId)
    let hasCreatedIntent = false
    try {
      // The owned directory is a permanent intent. An absent or partial
      // payload blocks all admission until its original writer publishes it.
      await mkdir(directory)
      hasCreatedIntent = true
      await writeFileAtomically(path.join(directory, CLAIM_FILE), JSON.stringify(claim), options)
      return claim
    } catch (error: unknown) {
      if (hasCreatedIntent && isNonsentReservation) {
        try {
          // No claim reached a caller, so no request could have been sent.
          // Only this creator can close its known nonsent row. A second
          // IO failure leaves the original intent/liability blocking admission.
          const currentSeed = readSeed(scope)
          if (currentSeed.scopeId !== seed.scopeId) {
            throw unavailable()
          }
          if (await isPresent(path.join(directory, CLAIM_FILE))) {
            const current = readClaim(scope, currentSeed, claim.claimId)
            if (
              current.ownerId !== ownerId ||
              current.reservedUsd !== costUsd ||
              (current.settledUsd !== undefined && current.settledUsd !== 0)
            ) {
              throw unavailable()
            }
          }
          await writeFileAtomically(
            path.join(directory, CLAIM_FILE),
            JSON.stringify({ ...claim, settledUsd: 0, hasUnknownCost: false }),
            options,
          )
        } catch {
          // Preserve the original failure; nobody treats this as a successful reservation.
        }
      }
      throw unavailable(error)
    }
  }

  const claimFor = (scope: Scope, seed: Seed, created: Claim): SessionBudgetClaim => {
    let settling: Promise<SessionBudgetTotal> | undefined
    let settlingCost: number | undefined
    let isSettlingCostUnknown: boolean | undefined
    const owned = (): Claim => {
      const currentSeed = readSeed(scope)
      const claim = readClaim(scope, currentSeed, created.claimId)
      if (
        currentSeed.scopeId !== seed.scopeId ||
        claim.ownerId !== ownerId ||
        claim.reservedUsd !== created.reservedUsd
      ) {
        throw unavailable()
      }
      return claim
    }
    const settleEntry = async (
      actualCostUsd: number,
      hasUnknownCost: boolean,
    ): Promise<SessionBudgetTotal> => {
      const claim = owned()
      if (claim.settledUsd !== undefined) {
        if (
          claim.settledUsd !== actualCostUsd ||
          (claim.hasUnknownCost === true) !== hasUnknownCost
        ) {
          throw unavailable()
        }
        return totalFor(scope)
      }
      try {
        await writeFileAtomically(
          path.join(scope.directory, CLAIMS_DIRECTORY, created.claimId, CLAIM_FILE),
          JSON.stringify({ ...claim, settledUsd: actualCostUsd, hasUnknownCost }),
          options,
        )
        return totalFor(scope)
      } catch (error: unknown) {
        throw unavailable(error)
      }
    }
    return {
      claimId: created.claimId,
      reservedUsd: created.reservedUsd,
      check(capUsd) {
        assertCost(capUsd)
        if (settling !== undefined) {
          throw unavailable()
        }
        const claim = owned()
        if (claim.settledUsd !== undefined) {
          throw unavailable()
        }
        const total = totalFor(scope)
        if (capUsd > 0 && total.hasUnknownHistoricalFees) {
          throw new Error(UI_TEXT.sessionBudgetLegacyFeesUnknown)
        }
        if (capUsd > 0 && total.spentUsd > capUsd) {
          throw new Error(
            fill(UI_TEXT.sessionBudgetStopped, {
              estimate: formatUsd(created.reservedUsd),
              cap: formatUsd(capUsd),
              spent: formatUsd(Math.max(0, total.spentUsd - created.reservedUsd)),
            }),
          )
        }
        return total
      },
      async settle(actualCostUsd, hasUnknownCost) {
        assertCost(actualCostUsd)
        const validated = claimFlagsSchema.parse({ hasUnknownCost })
        const isUnknown =
          validated.hasUnknownCost ?? isSettlingCostUnknown ?? owned().hasUnknownCost === true
        if (
          settlingCost !== undefined &&
          (settlingCost !== actualCostUsd || isSettlingCostUnknown !== isUnknown)
        ) {
          throw unavailable()
        }
        settlingCost = actualCostUsd
        isSettlingCostUnknown = isUnknown
        settling ??= settleEntry(actualCostUsd, isUnknown)
        const current = settling
        try {
          return await current
        } finally {
          if (settling === current) {
            settling = undefined
            settlingCost = undefined
            isSettlingCostUnknown = undefined
          }
        }
      },
    }
  }

  return {
    async read(sessionId, accountId) {
      const scope = scopeFor(sessionId, accountId)
      await ensure(scope)
      return totalFor(scope)
    },
    async reserve(sessionId, accountId, costUsd, flags = {}) {
      const scope = scopeFor(sessionId, accountId)
      const seed = await ensure(scope)
      return claimFor(
        scope,
        seed,
        await writeClaim(scope, seed, costUsd, true, claimFlagsSchema.parse(flags)),
      )
    },
    async record(sessionId, accountId, actualCostUsd, hasUnknownCost = false) {
      const scope = scopeFor(sessionId, accountId)
      const seed = await ensure(scope)
      return await claimFor(
        scope,
        seed,
        await writeClaim(
          scope,
          seed,
          actualCostUsd,
          false,
          claimFlagsSchema.parse({ hasUnknownCost }),
        ),
      ).settle(actualCostUsd)
    },
    async project(session) {
      if (session.accountId === undefined) {
        return session
      }
      const scope = scopeFor(session.sessionId, session.accountId)
      if (!(await isPresent(scope.intent)) && !(await isPresent(scope.directory))) {
        return session
      }
      const total = totalFor(scope)
      const { budgetIsFreshFork: _initialFork, ...projected } = session
      return { ...projected, budgetSpentUsd: total.spentUsd }
    },
  }
}

src/host/backend/shellJob.ts:
// The job objects Windows commands run in (PLAN.md D25, M27). A process
// belongs to its creator's job from the moment it exists, so a job holds
// everything a command starts, however it starts it (a launcher that exits
// included), and `TerminateJobObject` ends them all at once: nothing can be
// started between a look at the tree and the kill, which is what `taskkill
// /T` misses. The job has no limits and no kill-on-close, so a command that
// ends normally leaves its background processes running, as on POSIX.
//
// PowerShell reaches the Win32 job calls through a small C# type, compiled
// once per machine into the extension's storage (named by the source's
// digest) and loaded by each command. Where that is impossible (Constrained
// Language Mode forbids `Add-Type` and loading an assembly), the self-test
// fails, the log says so, and commands run as before, their kill falling
// back to taskkill and the orphan sweep (`processTree.ts`).

import { randomUUID } from 'node:crypto'
import { access } from 'node:fs/promises'
import path from 'node:path'
import {
  SHELL_JOB_FOLDER,
  SHELL_JOB_NAME_PREFIX,
  SHELL_JOB_TYPE_NAME,
  WINDOWS_POWERSHELL_COMMAND_ARGS,
} from '../../shared/constants'
import { powerShellQuoted } from '../../core/shellQuote'
import {
  loadJobAssembly,
  type RunProgram,
  runProgram,
  type ShellJob,
  windowsPowerShell,
} from '../processTree'
import { compileJob, type JobBuild, jobFileName, removeStaleJobs } from './jobBuild'
import type { JobHelper } from './jobSource'

// The C# (C# 5, which Windows PowerShell 5.1's `Add-Type` compiles) is the
// shipped native/windows/MuseSparkJob.cs with the shared Win32 half
// (`jobSource.ts`).

const JOINED = 'joined'

export interface ShellJobDeps {
  /** The extension's global storage folder. */
  readonly storageDir: string
  readonly systemRoot: string
  readonly log: (message: string) => void
  /** A helper's whole C# (`jobSource.ts`), read when the helper is first built. */
  readonly readJobSource: (helper: JobHelper) => Promise<string>
  /** `execFile` for Windows PowerShell; tests stand in the compiler. */
  readonly run?: RunProgram
}

async function isPresent(file: string): Promise<boolean> {
  try {
    await access(file)
    return true
  } catch {
    return false
  }
}

const ASSEMBLY: JobBuild = {
  stem: `${SHELL_JOB_TYPE_NAME}-`,
  extension: '.dll',
  addTypeOptions: '-OutputType Library',
  label: 'shell job assembly',
  isPresent,
}

/** The assembly's file name for this source (the whole C#, the shared half included). */
export function shellJobAssemblyName(csharp: string): string {
  return jobFileName(ASSEMBLY, csharp)
}

async function prepare(deps: ShellJobDeps): Promise<string | undefined> {
  const run = deps.run ?? runProgram
  try {
    const csharp = await deps.readJobSource('shellJob')
    const assembly = path.join(deps.storageDir, SHELL_JOB_FOLDER, shellJobAssemblyName(csharp))
    if (!(await isPresent(assembly))) {
      await compileJob(ASSEMBLY, assembly, csharp, deps.systemRoot, run)
      await removeStaleJobs(ASSEMBLY, assembly, deps.log)
    }
    // Loading the type and joining a job, as a command does, proves both
    // work and the system lets a process start a job of its own here. A
    // failing .NET call ends only its own statement in PowerShell, so the
    // answer is inside `try`: a load or join that fails never says joined.
    const powershell = windowsPowerShell(deps.systemRoot)
    const answer = await run(
      powershell.file,
      [
        ...WINDOWS_POWERSHELL_COMMAND_ARGS,
        `try { ${loadJobAssembly(assembly)}; [${SHELL_JOB_TYPE_NAME}]::Join(${powerShellQuoted(`${SHELL_JOB_NAME_PREFIX}${randomUUID()}`)}); '${JOINED}' } catch { exit 1 }`,
      ],
      powershell.env,
    )
    if (answer.trim() !== JOINED) {
      throw new Error(`the self-test answered ${JSON.stringify(answer.trim())}`)
    }
    return assembly
  } catch (error: unknown) {
    deps.log(
      `Windows job objects are unavailable (${String(error)}); a stopped command is ended with taskkill and a sweep for its orphans`,
    )
    return undefined
  }
}

/** The helper's assembly; a failed preparation can be tried again by the next caller. */
export function shellJobAssembly(deps: ShellJobDeps): () => Promise<string | undefined> {
  let ready: Promise<string | undefined> | undefined
  const attempt = async (): Promise<string | undefined> => {
    // Share an in-flight attempt and keep success, but not a transient
    // failure, whether it resolved empty or threw (a throwing logger, say):
    // a caller always gets an assembly or undefined, never a rejection.
    try {
      const assembly = await prepare(deps)
      if (assembly === undefined) {
        ready = undefined
      }
      return assembly
    } catch {
      ready = undefined
      return undefined
    }
  }
  return () => (ready ??= attempt())
}

/** A fresh job for one command. */
export function newShellJob(assemblyPath: string): ShellJob {
  return { name: `${SHELL_JOB_NAME_PREFIX}${randomUUID()}`, assemblyPath }
}

/**
 * The statement a command starts with to join its job. A failure (the
 * assembly gone, a policy) is swallowed: the command runs as it would
 * without one, and its kill finds no job and falls back.
 *
 * It names no cmdlet (`loadJobAssembly`): a hook runs in a narrow
 * environment without `PSModuleAnalysisCachePath`, and on GitHub's Windows
 * runner the module analysis an `Add-Type` here set off took 20 s or more
 * and, on a fresh runner, ran past the hook test's 60 s budget before the
 * hook began.
 */
export function joinStatement(job: ShellJob): string {
  return `try { ${loadJobAssembly(job.assemblyPath)}; [${SHELL_JOB_TYPE_NAME}]::Join(${powerShellQuoted(job.name)}) } catch { }; `
}

