// A manual bundle split: loading is synchronous at the existing store
// construction point. Startup maintenance and admission are not deferred.
import type { UiText } from '../../shared/l10n/en'
import { UI_TEXT } from '../../shared/constants'
import { forgetFile, requireFile } from '../lazyBundle'
import type { Logger } from '../logger'
import type { CheckpointStore, CheckpointStoreDeps } from './checkpointStore'
import type { LegacyCheckpointDeps } from './legacyCheckpoints'
import type { createTurnRecording } from './writeRecorder'

interface CheckpointStoreBundle {
  readonly createCheckpointStore: (
    deps: CheckpointStoreDeps,
    table: UiText,
    locale: string,
  ) => CheckpointStore
  readonly legacyCheckpointTurns: (
    deps: LegacyCheckpointDeps,
    sessionId: string,
    table: UiText,
    locale: string,
  ) => Promise<readonly string[]>
  readonly createTurnRecording: typeof createTurnRecording
}

/** Function signatures are trusted only for our same-build packaged module (PLAN.md §8). */
export function isCheckpointStoreBundle(value: unknown): value is CheckpointStoreBundle {
  return (
    typeof value === 'object' &&
    value !== null &&
    'createCheckpointStore' in value &&
    typeof value.createCheckpointStore === 'function' &&
    'legacyCheckpointTurns' in value &&
    typeof value.legacyCheckpointTurns === 'function' &&
    'createTurnRecording' in value &&
    typeof value.createTurnRecording === 'function'
  )
}

export interface CheckpointStoreLoaderDeps {
  readonly bundlePath: string
  readonly log: Logger
  readonly loadBundle?: ((file: string) => unknown) | undefined
}

/** Missing/malformed modules refuse construction; a later call can retry a repaired file. */
export function checkpointStoreLoader(
  deps: CheckpointStoreLoaderDeps,
): () => CheckpointStoreBundle {
  let bundle: CheckpointStoreBundle | undefined
  return () => {
    if (bundle !== undefined) {
      return bundle
    }
    const { bundlePath, loadBundle = requireFile } = deps
    let loaded: unknown
    try {
      loaded = loadBundle(bundlePath)
    } catch (error: unknown) {
      deps.log.error(`The checkpoint store ${bundlePath} could not be loaded`)
      throw new Error(UI_TEXT.checkpointFailed, { cause: error })
    }
    if (!isCheckpointStoreBundle(loaded)) {
      deps.log.error(`${bundlePath} does not export the checkpoint store factory and legacy reader`)
      if (deps.loadBundle === undefined) {
        forgetFile(bundlePath)
      }
      throw new Error(UI_TEXT.checkpointFailed)
    }
    bundle = loaded
    return bundle
  }
}

src/host/checkpoints/windowPresence.ts:
// Which windows are open on a checkpoint store, and which turns run in each
// (M72, M86; PLAN.md D51, D63). Two VS Code windows on the same folder
// ("Duplicate Workspace", or a reload racing the old extension host) share
// `<global storage>/checkpoints/<namespace>`. Nothing there is locked: each
// window keeps a presence file of its own (its process id, its store's
// instance id and its running turns), replaced whole on every change and on
// every heartbeat, so another window reads one version or the next. A window
// is gone on process exit only when its current attestation contains no
// native or unresolved process activity. Native/unknown state remains closed
// until explicitly confirmed recovery; age and owner PID death never prove
// that workspace-capable descendants stopped.
//
// Mixed versions (M86, spec section 7): this version publishes
// `fenced-window-v2`. A 0.10.0 window knows only v1, so it reads this one as
// unfenced and refuses its own restores while this one is live; this version
// reads a v1 window as a legacy window, whose restores it cannot see, and
// refuses its own. A window that has seen a v1 window since it opened leaves
// its presence file behind when it closes, so the 0.10.0 window stays fenced
// until it reloads (0.10.0 never removes a v2 file); this version removes a
// gone window's file only while no v1 window is live.

import { randomUUID } from 'node:crypto'
import { constants as fsConstants, rmSync } from 'node:fs'
import { copyFile, mkdir, readdir, readFile, rename, rm } from 'node:fs/promises'
import path from 'node:path'
import * as z from 'zod/mini'
import {
  CHECKPOINT_ACTIVITY_PREFIX,
  CHECKPOINT_FENCED_WINDOW,
  CHECKPOINT_LEGACY_FENCED_WINDOW,
  CHECKPOINT_NATIVE_WINDOW,
  CHECKPOINT_STORAGE_MODE,
} from '../../shared/constants'
import { isMissingPath } from '../canonicalPath'
import { writeFileAtomically } from '../fsAtomic'

const PRESENCE_DIR = 'windows'
const PRESENCE_SUFFIX = '.json'
const ASIDE_SUFFIX = '.aside'
const ALREADY_THERE = 'EEXIST'
const NO_SUCH_PROCESS = 'ESRCH'
const UNREADABLE_TURN = 'unreadable-presence'

const presenceSchema = z.object({
  pid: z.number(),
  instance: z.string(),
  running: z.optional(z.array(z.string())),
})
type Presence = z.infer<typeof presenceSchema>

function errorCode(error: unknown): string | undefined {
  return typeof error === 'object' && error !== null && 'code' in error
    ? String(error.code)
    : undefined
}

/** The text as JSON; undefined when it is not JSON. */
function parsedJson(text: string): unknown {
  try {
    return JSON.parse(text)
  } catch {
    return undefined
  }
}

/** Runs `task` once `previous` settled, whichever way: that write failed for its own caller. */
async function afterSettled(previous: Promise<unknown>, task: () => Promise<void>): Promise<void> {
  try {
    await previous
  } catch {
    // This write carries the latest state regardless.
  }
  await task()
}

/** Whether a process with this id exists (one we may not signal still exists). */
export function isProcessAlive(pid: number): boolean {
  try {
    process.kill(pid, 0)
    return true
  } catch (error: unknown) {
    return errorCode(error) !== NO_SUCH_PROCESS
  }
}

/** Whether a window's running list is fenced by this version or by 0.10.0. */
function isFenced(running: readonly string[]): boolean {
  return (
    running.includes(CHECKPOINT_FENCED_WINDOW) || running.includes(CHECKPOINT_LEGACY_FENCED_WINDOW)
  )
}

/** A 0.10.0 window: fenced with v1 only. Its restores and records are its own. */
export function isLegacyWindow(running: readonly string[]): boolean {
  return (
    running.includes(CHECKPOINT_LEGACY_FENCED_WINDOW) && !running.includes(CHECKPOINT_FENCED_WINDOW)
  )
}

export interface WindowPresenceDeps {
  readonly storageDir: string
  /** This store's id: one per window, so two stores in one process differ too. */
  readonly instance: string
  readonly pid: number
  readonly isProcessAlive: (pid: number) => boolean
  readonly sleep: (ms: number) => Promise<void>
  readonly signal: AbortSignal
}

interface Seen {
  readonly presence: Presence | undefined
}

export class WindowPresence {
  private readonly presenceDir: string
  /** Whether this window keeps a presence file (from its first use until it closes). */
  private isPresent = false
  /** The turns this window last published as running. */
  private running: readonly string[] = []
  /** Presence writes, one after another: the last one carries the latest turns. */
  private writing: Promise<unknown> = Promise.resolve()
  /** A 0.10.0 window was live at some read since this one opened: its file stays at close. */
  private hasSeenLegacy = false

  public constructor(private readonly deps: WindowPresenceDeps) {
    this.presenceDir = path.join(deps.storageDir, PRESENCE_DIR)
  }

  private get presencePath(): string {
    return path.join(this.presenceDir, `${this.deps.instance}${PRESENCE_SUFFIX}`)
  }

  /** A presence file's window; undefined when gone. */
  private async read(filePath: string): Promise<Seen | undefined> {
    try {
      const text = await readFile(filePath, 'utf8')
      const presence = presenceSchema.safeParse(parsedJson(text))
      return {
        presence: presence.success ? presence.data : undefined,
      }
    } catch (error: unknown) {
      if (isMissingPath(error)) {
        return undefined
      }
      throw error
    }
  }

  /** Owner exit cannot prove native descendants or an unknown window stopped. */
  private isGone(seen: Seen): boolean {
    const running = seen.presence?.running ?? []
    return (
      seen.presence !== undefined &&
      isFenced(running) &&
      !running.includes(CHECKPOINT_NATIVE_WINDOW) &&
      running.every((key) => !key.startsWith(CHECKPOINT_ACTIVITY_PREFIX)) &&
      !this.deps.isProcessAlive(seen.presence.pid)
    )
  }

  private turnsOf(presence: Presence | undefined): readonly string[] {
    if (presence === undefined) {
      return [UNREADABLE_TURN]
    }
    const running = presence.running ?? []
    const isUnprovedActivity =
      running.some((key) => key.startsWith(CHECKPOINT_ACTIVITY_PREFIX)) &&
      !this.deps.isProcessAlive(presence.pid)
    return isUnprovedActivity ? [CHECKPOINT_NATIVE_WINDOW, ...running] : running
  }

  /** Whether the window has left (read afresh after an await). */
  private hasLeft(): boolean {
    return !this.isPresent
  }

  private async write(): Promise<void> {
    if (this.deps.signal.aborted || !this.isPresent) {
      return
    }
    await mkdir(this.presenceDir, { recursive: true, mode: CHECKPOINT_STORAGE_MODE })
    await writeFileAtomically(
      this.presencePath,
      JSON.stringify({
        pid: this.deps.pid,
        instance: this.deps.instance,
        running: this.running,
      }),
      { sleep: this.deps.sleep },
    )
    // The window left while the file was being written: it goes again,
    // unless it must stay for a 0.10.0 window.
    if (this.hasLeft() && !this.hasSeenLegacy) {
      await rm(this.presencePath, { force: true })
    }
  }

  /** Writes the presence file from memory, after any write before it. */
  private async writeInTurn(): Promise<void> {
    const current = afterSettled(this.writing, () => this.write())
    this.writing = current
    await current
  }

  /**
   * Removes a gone window's presence file, unless it was written again after
   * it was read: it is moved aside under a name no other move uses, read
   * again, and put back when that window beat meanwhile. True when removed.
   */
  private async removeIfGone(filePath: string): Promise<boolean> {
    const aside = `${filePath}.${randomUUID()}${ASIDE_SUFFIX}`
    try {
      await rename(filePath, aside)
    } catch (error: unknown) {
      if (isMissingPath(error)) {
        return true
      }
      throw error
    }
    const moved = await this.read(aside)
    const isStillGone = moved === undefined || this.isGone(moved)
    if (!isStillGone) {
      try {
        await copyFile(aside, filePath, fsConstants.COPYFILE_EXCL)
      } catch (error: unknown) {
        if (errorCode(error) !== ALREADY_THERE) {
          throw error
        }
      }
    }
    await rm(aside, { force: true })
    return isStillGone
  }

  /**
   * Publishes this window as present with these turns running (no lock:
   * only this window writes its file). Resolves once the file says so.
   */
  public async publish(running: readonly string[]): Promise<void> {
    this.isPresent = true
    this.running = [...running]
    await this.writeInTurn()
  }

  /**
   * The heartbeat: the presence file is written again from memory, so a
   * file another window removed (thinking this one gone) or a failed write
   * heals within one beat.
   */
  public async beat(): Promise<void> {
    if (this.isPresent) {
      await this.writeInTurn()
    }
  }

  /**
   * The windows open on this store and the turns running in each, this one
   * included. The presence files of windows that are gone are removed, but
   * only while no 0.10.0 window is live: a file a window of this version
   * left behind for it keeps it fenced.
   */
  public async liveWindows(): Promise<ReadonlyMap<string, readonly string[]>> {
    const live = new Map<string, readonly string[]>([[this.deps.instance, this.running]])
    let names: string[]
    try {
      names = await readdir(this.presenceDir)
    } catch (error: unknown) {
      if (isMissingPath(error)) {
        return live
      }
      throw error
    }
    const gone: string[] = []
    const presenceFiles = names.filter((entry) => entry.endsWith(PRESENCE_SUFFIX))
    for (const name of presenceFiles) {
      // A window's file is named by its instance.
      const instance = name.slice(0, -PRESENCE_SUFFIX.length)
      const filePath = path.join(this.presenceDir, name)
      const seen = await this.read(filePath)
      if (seen === undefined || instance === this.deps.instance) {
        continue
      }
      if (this.isGone(seen)) {
        gone.push(name)
        continue
      }
      live.set(instance, this.turnsOf(seen.presence))
    }
    for (const running of live.values()) {
      if (isLegacyWindow(running)) {
        this.hasSeenLegacy = true
        return live
      }
    }
    for (const name of gone) {
      const filePath = path.join(this.presenceDir, name)
      await this.removeIfGone(filePath)
      // A heartbeat may have replaced the original while its old file
      // was aside. Read the current file, including its current turns.
      const current = await this.read(filePath)
      if (current !== undefined && !this.isGone(current)) {
        live.set(name.slice(0, -PRESENCE_SUFFIX.length), this.turnsOf(current.presence))
      }
    }
    return live
  }

  /**
   * The window is closing: its presence goes at once, and no write brings it
   * back. It stays when this window may still have work under way, and when
   * a 0.10.0 window was seen since this one opened (that window stays fenced
   * until it reloads; a later window of this version removes the file once
   * no 0.10.0 window is live).
   */
  public leave(): void {
    if (
      !this.isPresent ||
      !this.running.includes(CHECKPOINT_FENCED_WINDOW) ||
      this.running.includes(CHECKPOINT_NATIVE_WINDOW) ||
      this.running.some((key) => key.startsWith(CHECKPOINT_ACTIVITY_PREFIX))
    ) {
      return
    }
    this.isPresent = false
    if (this.hasSeenLegacy) {
      return
    }
    try {
      rmSync(this.presencePath, { force: true })
    } catch {
      // An uncertain leftover remains closed to destructive operations.
    }
  }
}

src/host/cliFeatures.ts:
// The VS Code side of the CLI-backed features (M30, M31, PLAN.md D30): the
// pickers, dialogs, terminals and file writes behind "Manage skills…",
// "Import skills…", "Export conversation…", "MCP servers…" and "Hooks…".
// The flows themselves live in commands/skillsCommands.ts,
// commands/museConfigCommands.ts and conversation/exportConversation.ts.

import { existsSync, readFileSync } from 'node:fs'
import { homedir } from 'node:os'
import path from 'node:path'
import * as vscode from 'vscode'
import type { McpPoolSnapshot } from '../core/backends/modelapi/mcp/pool'
import {
  EXPORT_FILE_EXTENSIONS,
  MUSE_EXPORT_TIMEOUT_MS,
  MUSE_EXTENDING_DOCS_URL,
  MODEL_API_HOOKS_SETTING,
  MUSE_SKILLS_TIMEOUT_MS,
  PROJECT_HOOKS_SEGMENTS,
  type SkillImportSource,
  UI_TEXT,
} from '../shared/constants'
import { fill } from '../shared/l10n/text'
import type { ProcessResult } from './backend/sandboxSetup'
import { type AgentImportHostDeps, runAgentImport } from './agentImportHost'
import { type MuseConfigDeps, showHooks, showMcpServers } from './commands/museConfigCommands'
import { importSkills, manageSkills, type SkillsCliDeps } from './commands/skillsCommands'
import type { ConversationExports } from './conversation/exportConversation'
import type { Logger } from './logger'
import { loggedPopups } from './popups'
import { showPickOne } from './quickPick'

export interface CliFeatureDeps {
  /** The CLI with these arguments, run to completion in `muse serve`'s environment; undefined when absent. */
  readonly runCli: (
    args: readonly string[],
    timeoutMs: number,
  ) => Promise<ProcessResult> | undefined
  /** The CLI in a VS Code terminal the user watches; false when it is not installed. */
  readonly runCliInTerminal: (
    args: readonly string[],
    terminalName: string,
  ) => boolean | Promise<boolean>
  /** Muse Code's settings file where `muse serve` reads it (`XDG_CONFIG_HOME` honoured). */
  readonly museSettingsPath: () => string
  readonly workspaceRoot: string | undefined
  /**
   * Runs a write of `fsPath` (an export the user placed): inside the
   * workspace folder under the checkpoint lease (M72), elsewhere as it is.
   */
  readonly editFile: <T>(fsPath: string, work: () => Promise<T>) => Promise<T>
  /** What the import from other agents needs of the window (M83). */
  readonly agentImport: Omit<
    AgentImportHostDeps,
    'workspaceRoot' | 'museSettingsPath' | 'openDocument' | 'log'
  >
  /** A read-only document that is never written to disk: an export's preview (M84). */
  readonly openPreview: (title: string, content: string) => Promise<void>
  /** Stops the hosts; the next message starts them with the new settings (D25). */
  readonly restartBackend: () => Promise<void>
  /**
   * The Model API backend's MCP servers, read for the view when this window
   * runs on that backend (M50); undefined on Muse Code.
   */
  readonly modelApiMcp: () => (() => McpPoolSnapshot | undefined) | undefined
  /** Undefined on Muse Code; current machine hook setting on Model API. */
  readonly modelApiHooks: () => boolean | undefined
  /** Shows the extension's log, where an MCP server's stderr goes. */
  readonly openLog: () => void
  /** Opens text as a read-only document (M15's tool outputs; M83's import preview). */
  readonly openDocument: (title: string, content: string) => Promise<void>
  readonly log: Logger
}

export interface CliFeatures {
  manageSkills(): Promise<void>
  importSkills(): Promise<void>
  /** Import from Claude Code, Codex and Cursor (M83). */
  importFromAgents(): Promise<void>
  showMcpServers(): Promise<void>
  showHooks(): Promise<void>
  readonly exports: ConversationExports
}

const NOT_FOUND = 'ENOENT'

/** The file's text; undefined when there is none; throws on any other failure. */
export function readTextIfPresent(fsPath: string): string | undefined {
  try {
    return readFileSync(fsPath, 'utf8')
  } catch (error: unknown) {
    if (error instanceof Error && 'code' in error && error.code === NOT_FOUND) {
      return undefined
    }
    throw error
  }
}

interface SourceChoice extends vscode.QuickPickItem {
  readonly source: SkillImportSource
}

/** Built when asked, so the labels come from the table installed at activation. */
function sourceChoices(): readonly SourceChoice[] {
  return [
    { label: UI_TEXT.importSourceClaude, source: 'claude' },
    { label: UI_TEXT.importSourceCodex, source: 'codex' },
  ]
}
const FILE_SCHEME = 'file'
const MARKDOWN_FILTER = 'Markdown'
const JSON_FILTER = 'JSON'
const LINE_BREAK = /\r?\n/

function firstLine(text: string): string {
  return text.trim().split(LINE_BREAK, 1)[0] ?? ''
}

/** `muse export` writes the session's JSON log to a path it is given. */
function sessionExportArgs(sessionId: string, outPath: string): readonly string[] {
  return ['export', '--session', sessionId, '--out', outPath]
}

/** A saved export: where it went, and Open. */
async function offerToOpen(target: vscode.Uri): Promise<void> {
  const choice = await vscode.window.showInformationMessage(
    fill(UI_TEXT.exportSaved, { path: target.fsPath }),
    UI_TEXT.exportOpen,
  )
  if (choice === UI_TEXT.exportOpen) {
    await vscode.window.showTextDocument(target, { preview: false })
  }
}

export function createCliFeatures(deps: CliFeatureDeps): CliFeatures {
  const skillsDeps = (): SkillsCliDeps => ({
    runCli: (args) => deps.runCli(args, MUSE_SKILLS_TIMEOUT_MS),
    workspaceRoot: deps.workspaceRoot,
    isWorkspaceTrusted: () => vscode.workspace.isTrusted,
    showInformation: (message) => {
      void vscode.window.showInformationMessage(message)
    },
    showError: loggedPopups(deps.log).showError,
    confirmRestart: async () =>
      (await vscode.window.showInformationMessage(
        UI_TEXT.skillsRestartPrompt,
        UI_TEXT.restartNow,
        UI_TEXT.restartLater,
      )) === UI_TEXT.restartNow,
    restart: deps.restartBackend,
    log: deps.log,
  })
  const configDeps = (): MuseConfigDeps => {
    const settingsPath = deps.museSettingsPath()
    return {
      settingsPath,
      readSettings: () => readTextIfPresent(settingsPath),
      projectHooksPath:
        deps.workspaceRoot === undefined
          ? undefined
          : path.join(deps.workspaceRoot, ...PROJECT_HOOKS_SEGMENTS),
      fileExists: existsSync,
      isWorkspaceTrusted: () => vscode.workspace.isTrusted,
      pick: showPickOne,
      openFile: async (fsPath) => {
        await vscode.window.showTextDocument(vscode.Uri.file(fsPath), { preview: false })
      },
      openDocs: () => {
        void vscode.env.openExternal(vscode.Uri.parse(MUSE_EXTENDING_DOCS_URL))
      },
      runMcpCommand: (action, server) =>
        deps.runCliInTerminal(['mcp', action, server], UI_TEXT.mcpTerminalName),
      restart: deps.restartBackend,
      showInformation: (message) => {
        void vscode.window.showInformationMessage(message)
      },
      showWarning: loggedPopups(deps.log).showWarning,
      modelApiServers: deps.modelApiMcp(),
      modelApiHooks: deps.modelApiHooks() === undefined ? undefined : () => deps.modelApiHooks(),
      openModelApiHooksSetting: async () => {
        await vscode.commands.executeCommand(
          'workbench.action.openSettings',
          MODEL_API_HOOKS_SETTING,
        )
      },
      openLog: deps.openLog,
    }
  }
  const saveTarget = (fileName: string, filterName: string, extension: string) =>
    vscode.window.showSaveDialog({
      defaultUri: vscode.Uri.file(path.join(deps.workspaceRoot ?? homedir(), fileName)),
      filters: { [filterName]: [extension] },
    })
  /**
   * Asks where to save an export and writes it there under the edit lease
   * and action guard (M72), Markdown and portable JSON alike; undefined,
   * with nothing written, when the dialog is dismissed.
   */
  const saveExport = async (
    fileName: string,
    filterName: string,
    extension: string,
    content: string,
  ): Promise<vscode.Uri | undefined> => {
    const target = await saveTarget(fileName, filterName, extension)
    if (target === undefined) {
      return undefined
    }
    await deps.editFile(target.fsPath, async () => {
      await vscode.workspace.fs.writeFile(target, new TextEncoder().encode(content))
    })
    return target
  }
  return {
    showMcpServers: () => showMcpServers(configDeps()),
    showHooks: () => showHooks(configDeps()),
    manageSkills: () =>
      manageSkills({
        ...skillsDeps(),
        pickSkills: async (items) => {
          const picked = await vscode.window.showQuickPick(
            items.map((item) => ({ ...item })),
            {
              canPickMany: true,
              title: UI_TEXT.skillsPickTitle,
              placeHolder: UI_TEXT.skillsPickPlaceholder,
              matchOnDescription: true,
              matchOnDetail: true,
              ignoreFocusOut: true,
            },
          )
          return picked === undefined ? undefined : new Set(picked.map((item) => item.id))
        },
      }),
    importSkills: () =>
      importSkills({
        ...skillsDeps(),
        pickSource: async () => {
          const choice = await vscode.window.showQuickPick(sourceChoices(), {
            title: UI_TEXT.importSourceTitle,
          })
          return choice?.source
        },
        confirmImport: async (message, detail) =>
          (await vscode.window.showInformationMessage(
            message,
            { modal: true, detail },
            UI_TEXT.importConfirmAction,
          )) === UI_TEXT.importConfirmAction,
      }),
    importFromAgents: () =>
      runAgentImport({
        ...deps.agentImport,
        workspaceRoot: deps.workspaceRoot,
        museSettingsPath: deps.museSettingsPath,
        openDocument: deps.openDocument,
        log: deps.log,
      }),
    exports: {
      saveMarkdown: async (fileName, content) => {
        const target = await saveExport(
          fileName,
          MARKDOWN_FILTER,
          EXPORT_FILE_EXTENSIONS.markdown,
          content,
        )
        if (target === undefined) {
          return
        }
        deps.log.info(`Exported the conversation to ${target.toString()}`)
        await vscode.window.showTextDocument(target, { preview: false })
      },
      saveJson: async (fileName, content) => {
        const target = await saveExport(fileName, JSON_FILTER, EXPORT_FILE_EXTENSIONS.json, content)
        if (target === undefined) {
          return
        }
        deps.log.info(`Exported the session as JSON to ${target.toString()}`)
        await offerToOpen(target)
      },
      // The redacted file opens first, read-only and in memory; the modal
      // then asks. Closing it writes nothing.
      previewExport: async ({ fileName, content, detail }) => {
        await deps.openPreview(fileName, content)
        const choice = await vscode.window.showInformationMessage(
          UI_TEXT.exportPreviewTitle,
          { modal: true, detail },
          UI_TEXT.exportPreviewRedacted,
          UI_TEXT.exportPreviewFull,
        )
        if (choice === UI_TEXT.exportPreviewFull) {
          return 'full'
        }
        return choice === UI_TEXT.exportPreviewRedacted ? 'redacted' : 'dismissed'
      },
      localRoots: () => [
        ...(vscode.workspace.workspaceFolders ?? []).map((folder) => folder.uri.fsPath),
        homedir(),
      ],
      saveSessionLog: async (sessionId, fileName) => {
        const target = await saveTarget(fileName, JSON_FILTER, EXPORT_FILE_EXTENSIONS.sessionLog)
        if (target === undefined) {
          return
        }
        // The CLI writes the file itself, so it needs a path on this side.
        if (target.scheme !== FILE_SCHEME) {
          throw new Error(UI_TEXT.exportLogLocalOnly)
        }
        const running = deps.runCli(
          sessionExportArgs(sessionId, target.fsPath),
          MUSE_EXPORT_TIMEOUT_MS,
        )
        if (running === undefined) {
          throw new Error(UI_TEXT.exportCliMissing)
        }
        const result = await running
        if (result.exitCode !== 0) {
          throw new Error(
            firstLine(result.stderr) ||
              `muse export: ${fill(UI_TEXT.processExitCode, { code: String(result.exitCode) })}`,
          )
        }
        deps.log.info(`muse export wrote session ${sessionId} to ${target.fsPath}`)
        await offerToOpen(target)
      },
    },
  }
}

src/host/codeIntel/languageServices.ts:
// VS Code's language services for the code intelligence tools (M67,
// PLAN.md D49): the `vscode.execute…` commands the editor's own Go to
// Definition, Find All References, outline, hover, call hierarchy and
// Rename Symbol use, their results converted to the plain data
// src/core/codeIntel works with. A document is loaded without being shown;
// a result that is no file on disk (a virtual document) has no path.

import * as vscode from 'vscode'
import * as z from 'zod/mini'
import { VSCODE_COMMANDS } from '../../shared/constants'
import type {
  CallDirection,
  CallHierarchyAnswer,
  CallSite,
  CodeLocation,
  CodePosition,
  CodeRange,
  CodeSymbol,
  FileOperations,
  LanguageServiceHost,
  RenameEdits,
} from '../../core/codeIntel/languageService'

const FILE_SCHEME = 'file'
const FENCE = '```'

function pathOf(uri: vscode.Uri): string | undefined {
  return uri.scheme === FILE_SCHEME ? uri.fsPath : undefined
}

function toPosition(at: CodePosition): vscode.Position {
  return new vscode.Position(at.line, at.character)
}

function fromRange(range: vscode.Range): CodeRange {
  return {
    start: { line: range.start.line, character: range.start.character },
    end: { line: range.end.line, character: range.end.character },
  }
}

/** A `Location` or a `LocationLink` (definition providers return either). */
function fromLocation(location: vscode.Location | vscode.LocationLink): CodeLocation {
  return 'targetUri' in location
    ? {
        path: pathOf(location.targetUri),
        range: fromRange(location.targetSelectionRange ?? location.targetRange),
      }
    : { path: pathOf(location.uri), range: fromRange(location.range) }
}

function fromDocumentSymbol(symbol: vscode.DocumentSymbol, path: string): CodeSymbol {
  return {
    name: symbol.name,
    kind: symbol.kind,
    detail: symbol.detail,
    container: undefined,
    location: { path, range: fromRange(symbol.range) },
    selection: fromRange(symbol.selectionRange),
    children: symbol.children.map((child) => fromDocumentSymbol(child, path)),
  }
}

function fromSymbolInformation(symbol: vscode.SymbolInformation): CodeSymbol {
  const location = fromLocation(symbol.location)
  return {
    name: symbol.name,
    kind: symbol.kind,
    detail: undefined,
    container: symbol.containerName,
    location,
    selection: location.range,
    children: [],
  }
}

function fromCallItem(item: vscode.CallHierarchyItem): CodeSymbol {
  return {
    name: item.name,
    kind: item.kind,
    detail: item.detail,
    container: undefined,
    location: { path: pathOf(item.uri), range: fromRange(item.range) },
    selection: fromRange(item.selectionRange),
    children: [],
  }
}

// A hover part: Markdown text, or code in a language (the older marked-string form).
const markedCodeSchema = z.object({ language: z.string(), value: z.string() })
const markdownSchema = z.object({ value: z.string() })

/**
 * A hover part as Markdown, code fenced. A shape VS Code does not document
 * is shown as it came, never dropped (AGENTS rule 13).
 */
function hoverText(part: unknown): string {
  if (typeof part === 'string') {
    return part
  }
  const code = markedCodeSchema.safeParse(part)
  if (code.success) {
    return `${FENCE}${code.data.language}\n${code.data.value}\n${FENCE}`
  }
  const markdown = markdownSchema.safeParse(part)
  return markdown.success ? markdown.data.value : JSON.stringify(part)
}

async function run<T>(command: string, ...args: unknown[]): Promise<T | undefined> {
  return await vscode.commands.executeCommand<T | undefined>(command, ...args)
}

/** Whether the range holds the position, its ends included. */
function isWithin(range: CodeRange, at: CodePosition): boolean {
  const { start, end } = range
  return (
    (at.line > start.line || (at.line === start.line && at.character >= start.character)) &&
    (at.line < end.line || (at.line === end.line && at.character <= end.character))
  )
}

async function callHierarchy(
  uri: vscode.Uri,
  at: CodePosition,
  direction: CallDirection,
): Promise<CallHierarchyAnswer | undefined> {
  const items =
    (await run<vscode.CallHierarchyItem[]>(
      VSCODE_COMMANDS.prepareCallHierarchy,
      uri,
      toPosition(at),
    )) ?? []
  // Several items (overloads, merged declarations): the one declared at the
  // position is asked, else the first; the answer counts the others.
  const item =
    items.find(
      (candidate) =>
        pathOf(candidate.uri) === pathOf(uri) && isWithin(fromRange(candidate.selectionRange), at),
    ) ?? items[0]
  if (item === undefined) {
    return undefined
  }
  let calls: readonly CallSite[]
  if (direction === 'incoming') {
    const incoming = await run<vscode.CallHierarchyIncomingCall[]>(
      VSCODE_COMMANDS.provideIncomingCalls,
      item,
    )
    calls = (incoming ?? []).map((call) => ({
      symbol: fromCallItem(call.from),
      ranges: call.fromRanges.map((range) => fromRange(range)),
    }))
  } else {
    const outgoing = await run<vscode.CallHierarchyOutgoingCall[]>(
      VSCODE_COMMANDS.provideOutgoingCalls,
      item,
    )
    calls = (outgoing ?? []).map((call) => ({
      symbol: fromCallItem(call.to),
      ranges: call.fromRanges.map((range) => fromRange(range)),
    }))
  }
  return { item: fromCallItem(item), calls, otherItems: items.length - 1 }
}

async function rename(uri: vscode.Uri, at: CodePosition, newName: string): Promise<RenameEdits> {
  const position = toPosition(at)
  // Rejects with the provider's reason ("You cannot rename this element.").
  await run(VSCODE_COMMANDS.prepareRename, uri, position)
  const edit = await run<vscode.WorkspaceEdit>(
    VSCODE_COMMANDS.executeDocumentRenameProvider,
    uri,
    position,
    newName,
  )
  if (edit === undefined) {
    return { files: [], fileOperations: 'none' }
  }
  return {
    files: edit.entries().map(([target, edits]) => ({
      path: pathOf(target),
      edits: edits.map((textEdit) => ({
        range: fromRange(textEdit.range),
        newText: textEdit.newText,
      })),
    })),
    fileOperations: fileOperationsOf(edit),
  }
}

// What `WorkspaceEdit` holds beyond its text edits. Its API shows only
// those: `entries()` lists text edits and `size` counts them (read from
// VS Code 1.125.0's and 1.139.0's extensionHostProcess.js), so a rename that
// also creates, moves or deletes files looks like a plain one. Only the
// internal `_allEntries()` lists everything, each entry with a `_type` (1 a
// file operation, 2 a text edit, others cells and snippets). It is read as
// untyped data: when it is missing or its shape changes, the answer is
// `unknown`, and the rename is refused rather than half applied.
const ALL_ENTRIES = '_allEntries'
const TEXT_EDIT_TYPE = 2
const allEntriesSchema = z.array(z.object({ _type: z.number() }))

function fileOperationsOf(edit: vscode.WorkspaceEdit): FileOperations {
  const allEntries: unknown = Reflect.get(edit, ALL_ENTRIES)
  if (typeof allEntries !== 'function') {
    return 'unknown'
  }
  const parsed = allEntriesSchema.safeParse(Reflect.apply(allEntries, edit, []))
  if (!parsed.success) {
    return 'unknown'
  }
  return parsed.data.every((entry) => entry._type === TEXT_EDIT_TYPE) ? 'none' : 'present'
}

/** The language services behind the code intelligence tools. */
export function vscodeLanguageServices(): LanguageServiceHost {
  return {
    open: async (path) => {
      const document = await vscode.workspace.openTextDocument(vscode.Uri.file(path))
      return {
        languageId: document.languageId,
        text: document.getText(),
        isDirty: document.isDirty,
      }
    },
    definitions: async (path, at) => {
      const found = await run<(vscode.Location | vscode.LocationLink)[]>(
        VSCODE_COMMANDS.executeDefinitionProvider,
        vscode.Uri.file(path),
        toPosition(at),
      )
      return (found ?? []).map((location) => fromLocation(location))
    },
    references: async (path, at) => {
      const found = await run<vscode.Location[]>(
        VSCODE_COMMANDS.executeReferenceProvider,
        vscode.Uri.file(path),
        toPosition(at),
      )
      return (found ?? []).map((location) => fromLocation(location))
    },
    hover: async (path, at) => {
      const hovers = await run<vscode.Hover[]>(
        VSCODE_COMMANDS.executeHoverProvider,
        vscode.Uri.file(path),
        toPosition(at),
      )
      return (hovers ?? []).flatMap((hover) => hover.contents.map((part) => hoverText(part)))
    },
    documentSymbols: async (path) => {
      const found = await run<(vscode.DocumentSymbol | vscode.SymbolInformation)[]>(
        VSCODE_COMMANDS.executeDocumentSymbolProvider,
        vscode.Uri.file(path),
      )
      return (found ?? []).map((symbol) =>
        'selectionRange' in symbol
          ? fromDocumentSymbol(symbol, path)
          : fromSymbolInformation(symbol),
      )
    },
    workspaceSymbols: async (query) => {
      const found = await run<vscode.SymbolInformation[]>(
        VSCODE_COMMANDS.executeWorkspaceSymbolProvider,
        query,
      )
      return (found ?? []).map((symbol) => fromSymbolInformation(symbol))
    },
    callHierarchy: async (path, at, direction) =>
      await callHierarchy(vscode.Uri.file(path), at, direction),
    rename: async (path, at, newName) => await rename(vscode.Uri.file(path), at, newName),
    // VS Code's installation holds the built-in languages' libraries (the
    // TypeScript extension's `lib.*.d.ts`); an installed extension holds
    // its own (Python's typeshed). Read at each call: extensions come and go.
    libraryRoots: () => [
      vscode.env.appRoot,
      ...vscode.extensions.all.map((extension) => extension.extensionPath),
    ],
  }
}

src/host/commands/createRulesFile.ts:
// `Muse Spark: Create AGENTS.md` (PLAN.md D15). The file that both backends
// read as project rules (D13) gets created the way Muse Code itself would:
// `muse init` when the CLI is present and the workspace is trusted (the CLI
// detects commands and directories, with no model call), else the same
// layout from `rulesFileTemplate`. An existing file is opened, never
// overwritten. Every VS Code and process interaction is injected.

import path from 'node:path'
import { rulesFileTemplate } from '../../core/context/rulesTemplate'
import { RULES_FILE_NAMES, UI_TEXT } from '../../shared/constants'
import type { ProcessResult } from '../backend/sandboxSetup'
import type { Logger } from '../logger'

export interface CreateRulesFileDeps {
  readonly workspaceRoot: string | undefined
  readonly isWorkspaceTrusted: () => boolean
  readonly fileExists: (fsPath: string) => Promise<boolean>
  readonly writeFile: (fsPath: string, content: string) => Promise<void>
  readonly openFile: (fsPath: string) => Promise<void>
  /** `muse init` in the workspace root, or undefined when the CLI is absent. */
  readonly runInit: () => Promise<ProcessResult> | undefined
  readonly showInformation: (message: string) => void
  readonly showWarning: (message: string) => void
  readonly log: Logger
}

const [RULES_FILE_NAME] = RULES_FILE_NAMES

function firstLine(text: string): string {
  return text.trim().split(/\r?\n/, 1)[0] ?? ''
}

/** Absent/exited CLI may select the template; refused startup propagates. */
async function didCliWriteFile(deps: CreateRulesFileDeps, target: string): Promise<boolean> {
  const running = deps.isWorkspaceTrusted() ? deps.runInit() : undefined
  if (running === undefined) {
    return false
  }
  const result = await running
  if (result.exitCode === 0 && (await deps.fileExists(target))) {
    deps.log.info(`muse init wrote ${target}`)
    return true
  }
  const detail = firstLine(result.stderr) || firstLine(result.stdout)
  deps.log.warn(
    `muse init exited ${String(result.exitCode)} without writing ${RULES_FILE_NAME}${detail === '' ? '' : `: ${detail}`}; writing the template instead`,
  )
  return false
}

export async function createRulesFile(deps: CreateRulesFileDeps): Promise<void> {
  if (deps.workspaceRoot === undefined) {
    deps.showWarning(UI_TEXT.rulesFileNoWorkspace)
    return
  }
  const target = path.join(deps.workspaceRoot, RULES_FILE_NAME)
  if (await deps.fileExists(target)) {
    deps.showInformation(UI_TEXT.rulesFileExists)
    await deps.openFile(target)
    return
  }
  if (!(await didCliWriteFile(deps, target))) {
    await deps.writeFile(target, rulesFileTemplate(path.basename(deps.workspaceRoot)))
    deps.log.info(`Wrote the ${RULES_FILE_NAME} template to ${target}`)
  }
  deps.showInformation(UI_TEXT.rulesFileCreated)
  await deps.openFile(target)
}

src/host/commands/focusInput.ts:
// Ctrl+Esc: toggle keyboard focus between the editor and the chat composer.
// Pure orchestration over injected dependencies so it is unit-tested without
// VS Code.

import type { ChatSurface } from '../views/chatSurface'

export interface FocusInputDeps {
  /** Current value of the `museSpark.inputFocused` context key. */
  readonly isInputFocused: () => boolean
  readonly activeSurface: () => ChatSurface | undefined
  readonly focusEditor: () => Thenable<unknown>
  /** Opens (and focuses) the sidebar view when no surface exists yet. */
  readonly openSidebar: () => Thenable<unknown>
}

export async function toggleInputFocus(deps: FocusInputDeps): Promise<void> {
  if (deps.isInputFocused()) {
    await deps.focusEditor()
    return
  }
  const surface = deps.activeSurface()
  if (surface === undefined) {
    // The view resolves asynchronously; the composer focuses itself on init.
    await deps.openSidebar()
    return
  }
  surface.reveal()
  surface.post({ type: 'focusInput' })
}

