// Alt+K: insert an `@path#lines` reference for the active editor selection
// into the composer. Pure orchestration over injected dependencies.

import { formatMentionReference, type MentionSource } from '../../core/mention'
import { UI_TEXT } from '../../shared/constants'
import type { ChatSurface } from '../views/chatSurface'

export interface InsertMentionDeps {
  /** The active text editor's file and selection, or undefined when none. */
  readonly activeSelection: () => MentionSource | undefined
  readonly activeSurface: () => ChatSurface | undefined
  readonly openSidebar: () => Thenable<unknown>
  readonly showInformation: (message: string) => void
}

export async function insertMentionReference(deps: InsertMentionDeps): Promise<void> {
  const source = deps.activeSelection()
  if (source === undefined) {
    deps.showInformation(UI_TEXT.insertReferenceNoEditor)
    return
  }
  const surface = deps.activeSurface()
  if (surface === undefined) {
    await deps.openSidebar()
    deps.showInformation(UI_TEXT.insertReferencePanelOpened)
    return
  }
  surface.reveal()
  surface.post({ type: 'insertText', text: `${formatMentionReference(source)} ` })
}

src/host/commands/memoryCommands.ts:
// `Muse Spark: Memory` (M49, PLAN.md D41): the notes Muse Code keeps for
// this workspace in its three scopes, on both backends (they share one
// memory). A note opens in an editor to read or change; a new one is created
// empty (its description as front matter) and opened; a deleted one goes to
// the trash after a modal. The view keeps each scope's MEMORY.md true: a note
// it creates gets its line, a note it deletes loses its lines. Every VS Code
// interaction is injected.

import type { MemoryNote, MemoryStore } from '../../core/memory/memoryStore'
import {
  MEMORY_INDEX_FILE,
  MEMORY_NOTE_EXTENSION,
  type MemoryScope,
  UI_TEXT,
} from '../../shared/constants'
import { fill, plural } from '../../shared/l10n/text'
import type { PickItem, PickOne } from './pickItem'

/**
 * One mutation of the notes. A scope whose notes lie under the workspace
 * folder holds the pure checkpoint lease until `work` settles; `work` gets
 * the guard to honour right before each native write.
 */
export type MemoryEdit = <T>(
  scope: MemoryScope,
  work: (assertCanWrite: () => void) => Promise<T>,
) => Promise<T>

export interface MemoryViewDeps {
  readonly store: Pick<
    MemoryStore,
    'availableScopes' | 'notes' | 'root' | 'locate' | 'hasNote' | 'create' | 'forget'
  >
  readonly pick: PickOne
  /** An input box for the note's name; `validate` answers undefined for a good value, else why not. */
  readonly askName: (
    validate: (value: string) => Promise<string | undefined>,
  ) => Promise<string | undefined>
  /** The note's one-line description, possibly empty; undefined when the box was dismissed. */
  readonly askDescription: () => Promise<string | undefined>
  /** A modal; true when the user chose `action`. */
  readonly confirm: (message: string, detail: string, action: string) => Promise<boolean>
  readonly openFile: (fsPath: string) => Promise<void>
  /** Moves a file to the trash, after a checkpoint copy and the guard's last word. */
  readonly trash: (fsPath: string, assertCanWrite: () => void) => Promise<void>
  readonly edit: MemoryEdit
  readonly openDocs: () => void
  readonly showInformation: (message: string) => void
  readonly showError: (message: string) => void
}

const NOTE_PREFIX = 'note:'
const NEW_NOTE = 'action:new'
const DOCS = 'action:docs'
const OPEN = 'open'
const DELETE = 'delete'
const EXTENSION = /\.[^./\\]+$/

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

function noteItem(note: MemoryNote, index: number): PickItem {
  const detail = note.path === MEMORY_INDEX_FILE ? UI_TEXT.memoryIndexDetail : note.summary
  return {
    id: `${NOTE_PREFIX}${String(index)}`,
    label: note.path,
    description: UI_TEXT.memoryScopes[note.scope],
    ...(detail !== '' && { detail }),
  }
}

/** The name as typed, `.md` added when it has no extension. */
function noteName(value: string): string {
  const name = value.trim()
  return name === '' || EXTENSION.test(name) ? name : `${name}${MEMORY_NOTE_EXTENSION}`
}

async function deleteNote(deps: MemoryViewDeps, note: MemoryNote): Promise<void> {
  const isConfirmed = await deps.confirm(
    fill(UI_TEXT.memoryDeleteConfirm, { path: note.path }),
    UI_TEXT.memoryDeleteConfirmDetail,
    UI_TEXT.memoryDeleteAction,
  )
  if (!isConfirmed) {
    return
  }
  await deps.edit(note.scope, async (assertCanWrite) => {
    await deps.trash(note.absolute, assertCanWrite)
    await deps.store.forget(note, assertCanWrite)
  })
  deps.showInformation(fill(UI_TEXT.memoryDeleted, { path: note.path }))
}

async function noteActions(deps: MemoryViewDeps, note: MemoryNote): Promise<void> {
  const choice = await deps.pick(
    [
      { id: OPEN, label: UI_TEXT.memoryOpen, detail: note.absolute },
      {
        id: DELETE,
        label: UI_TEXT.memoryDelete,
        detail:
          note.path === MEMORY_INDEX_FILE
            ? UI_TEXT.memoryDeleteIndexDetail
            : UI_TEXT.memoryDeleteDetail,
      },
    ],
    note.path,
    UI_TEXT.memoryScopes[note.scope],
  )
  if (choice === OPEN) {
    await deps.openFile(note.absolute)
  } else if (choice === DELETE) {
    await deleteNote(deps, note)
  }
}

async function pickScope(
  deps: MemoryViewDeps,
  scopes: readonly MemoryScope[],
): Promise<MemoryScope | undefined> {
  const items = await Promise.all(
    scopes.map(async (scope): Promise<PickItem> => {
      const root = await deps.store.root(scope)
      return {
        id: scope,
        label: UI_TEXT.memoryScopes[scope],
        description: scope,
        ...(root.ok && { detail: root.value }),
      }
    }),
  )
  const choice = await deps.pick(items, UI_TEXT.memoryNewTitle, UI_TEXT.memoryScopePlaceholder)
  return scopes.find((scope) => scope === choice)
}

/** Why the typed name cannot be a new note in `scope`, or undefined. */
async function nameProblem(
  deps: MemoryViewDeps,
  scope: MemoryScope,
  value: string,
): Promise<string | undefined> {
  const place = await deps.store.locate(scope, noteName(value))
  if (!place.ok) {
    return `${UI_TEXT.memoryNameInvalid} (${place.reason})`
  }
  return (await deps.store.hasNote(place.value)) ? UI_TEXT.memoryNameTaken : undefined
}

async function newNote(deps: MemoryViewDeps, scopes: readonly MemoryScope[]): Promise<void> {
  const scope = await pickScope(deps, scopes)
  if (scope === undefined) {
    return
  }
  const name = await deps.askName((value) => nameProblem(deps, scope, value))
  if (name === undefined) {
    return
  }
  const description = await deps.askDescription()
  if (description === undefined) {
    return
  }
  const place = await deps.edit(
    scope,
    async (assertCanWrite) =>
      await deps.store.create(scope, noteName(name), description, assertCanWrite),
  )
  await deps.openFile(place.absolute)
}

async function showMemoryView(deps: MemoryViewDeps): Promise<void> {
  const scopes = await deps.store.availableScopes()
  const byScope = await Promise.all(scopes.map((scope) => deps.store.notes(scope)))
  const notes = byScope.flat()
  const choice = await deps.pick(
    [
      ...notes.map((note, index) => noteItem(note, index)),
      { id: NEW_NOTE, label: UI_TEXT.memoryNewNote, detail: UI_TEXT.memoryNewNoteDetail },
      { id: DOCS, label: UI_TEXT.memoryDocs },
    ],
    UI_TEXT.memoryTitle,
    notes.length === 0 ? UI_TEXT.memoryNone : plural(UI_TEXT.memoryCount, notes.length),
  )
  if (choice === undefined) {
    return
  }
  if (choice.startsWith(NOTE_PREFIX)) {
    const note = notes[Number(choice.slice(NOTE_PREFIX.length))]
    if (note !== undefined) {
      await noteActions(deps, note)
    }
    return
  }
  if (choice === NEW_NOTE) {
    await newNote(deps, scopes)
    return
  }
  deps.openDocs()
}

/** The view; a failure on the way (a folder that cannot be read or written) is said, not thrown. */
export async function showMemory(deps: MemoryViewDeps): Promise<void> {
  try {
    await showMemoryView(deps)
  } catch (error: unknown) {
    deps.showError(`${UI_TEXT.memoryFailed}: ${describe(error)}`)
  }
}

src/host/commands/museConfigCommands.ts:
// `Muse Spark: MCP Servers` and `Muse Spark: Hooks` (M31, PLAN.md D30):
// what Muse Code will load from its settings and the workspace, shown
// read-only (D17: the extension never writes the CLI's settings). A server
// can be signed in to or out of through `muse mcp login|logout` in a
// terminal, and every file is one click away. Every VS Code and process
// interaction is injected.
//
// On the Model API backend the window runs the same servers itself (M50,
// PLAN.md D42): each row says whether it is connected and with how many
// tools, or why it is not running; the extension's own diagnostics server
// has a row too; a server opens the log (its stderr) instead of a sign-in,
// since `muse mcp login` signs in Muse Code only.

import type { McpPoolSnapshot } from '../../core/backends/modelapi/mcp/pool'
import {
  type McpServerView,
  type McpSettingsView,
  readHookSources,
  readMcpServers,
} from '../../core/backends/musecode/museConfigView'
import { IDE_MCP_SERVER_NAME, MODEL_API_HOOKS_SETTING, UI_TEXT } from '../../shared/constants'
import { fill, plural } from '../../shared/l10n/text'
import type { PickItem, PickOne } from './pickItem'

export type McpAction = 'login' | 'logout'

export interface MuseConfigDeps {
  readonly settingsPath: string
  /** The settings file's text; undefined when there is no file; throws when it cannot be read. */
  readonly readSettings: () => string | undefined
  /** The workspace's `.muse/hooks.json`; undefined without a workspace. */
  readonly projectHooksPath: string | undefined
  readonly fileExists: (fsPath: string) => boolean
  readonly isWorkspaceTrusted: () => boolean
  readonly pick: PickOne
  readonly openFile: (fsPath: string) => Promise<void>
  readonly openDocs: () => void
  /** `muse mcp <action> <server>` in a terminal; false when the CLI is not installed. */
  readonly runMcpCommand: (action: McpAction, server: string) => boolean | Promise<boolean>
  /** Stops the hosts so the next message starts Muse Code with the new settings. */
  readonly restart: () => Promise<void>
  readonly showInformation: (message: string) => void
  readonly showWarning: (message: string) => void
  /**
   * The Model API backend's servers as this window runs them (M50):
   * undefined while the window runs Muse Code, which starts its own; the
   * function answers undefined until they have been started.
   */
  readonly modelApiServers?: (() => McpPoolSnapshot | undefined) | undefined
  /** The extension's log, where a server's stderr goes. */
  readonly openLog?: (() => void) | undefined
  /** Present only on the Model API backend; false means no hook can run. */
  readonly modelApiHooks?: (() => boolean | undefined) | undefined
  readonly openModelApiHooksSetting?: (() => Promise<void>) | undefined
}

const OPEN_SETTINGS = 'action:openSettings'
const RESTART = 'action:restart'
const DOCS = 'action:docs'
const SHOW_LOG = 'action:log'
const SERVER_PREFIX = 'server:'
const BUILT_IN_PREFIX = 'builtin:'
const PROJECT_HOOKS = 'hooks:project'
const USER_HOOKS = 'hooks:user'
const MANAGED_HOOKS = 'hooks:managed'
const MODEL_API_HOOKS_PICK = 'hooks:modelApiSetting'
const STREAMABLE_HTTP = 'streamable-http'
const LIST_SEPARATOR = ', '
const DETAIL_SEPARATOR = ' · '

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/** The file's text, or why it could not be read (a permission, a directory). */
function settingsText(deps: MuseConfigDeps): { readonly text?: string; readonly error?: string } {
  try {
    const text = deps.readSettings()
    return text === undefined ? {} : { text }
  } catch (error: unknown) {
    return { error: describe(error) }
  }
}

/** A server's state as the Model API backend runs it, in words (M50). */
function liveState(server: McpServerView, snapshot: McpPoolSnapshot | undefined): string {
  if (!server.isEnabled) {
    return UI_TEXT.mcpDisabled
  }
  if (snapshot?.isStarted !== true) {
    return UI_TEXT.mcpStateNotStarted
  }
  if (snapshot.fault !== undefined) {
    return UI_TEXT.mcpStateNotLoaded
  }
  const state = snapshot.servers.find((candidate) => candidate.name === server.name)?.state
  switch (state?.status) {
    case undefined: {
      return UI_TEXT.mcpStateNotStarted
    }
    case 'starting': {
      return UI_TEXT.mcpStateStarting
    }
    case 'connected': {
      const connected = plural(UI_TEXT.mcpStateConnected, state.toolCount)
      return state.unofferedCount > 0
        ? `${connected}${DETAIL_SEPARATOR}${plural(UI_TEXT.mcpStateUnoffered, state.unofferedCount)}`
        : connected
    }
    case 'failed': {
      return fill(UI_TEXT.mcpStateFailed, { reason: state.reason })
    }
    case 'disabled': {
      return UI_TEXT.mcpDisabled
    }
    case 'restricted': {
      return UI_TEXT.mcpStateRestricted
    }
  }
}

/** The detail line; `live` is the Model API backend's state of the server, first when given. */
function serverDetail(server: McpServerView, live: string | undefined): string {
  let mode: string = UI_TEXT.mcpOptional
  if (server.mode !== 'optional') {
    mode = live === undefined ? UI_TEXT.mcpRequired : UI_TEXT.mcpRequiredModelApi
  }
  const parts: string[] = live === undefined ? [mode] : [live, mode]
  if (live === undefined && !server.isEnabled) {
    parts.push(UI_TEXT.mcpDisabled)
  }
  if (server.envNames.length > 0) {
    parts.push(`${UI_TEXT.mcpEnv} ${server.envNames.join(LIST_SEPARATOR)}`)
  }
  if (server.headerNames.length > 0) {
    parts.push(`${UI_TEXT.mcpHeaders} ${server.headerNames.join(LIST_SEPARATOR)}`)
  }
  if (server.hasModeConflict) {
    parts.push(UI_TEXT.mcpModeConflict)
  }
  return parts.join(DETAIL_SEPARATOR)
}

function serverItem(server: McpServerView, live: string | undefined): PickItem {
  return {
    id: `${SERVER_PREFIX}${server.name}`,
    label: server.name,
    description: `${server.transport}${DETAIL_SEPARATOR}${server.target}`,
    detail: serverDetail(server, live),
  }
}

/** The extension's own diagnostics server, which the Model API backend runs in process. */
function builtInItem(): PickItem {
  return {
    id: `${BUILT_IN_PREFIX}${IDE_MCP_SERVER_NAME}`,
    label: IDE_MCP_SERVER_NAME,
    description: UI_TEXT.mcpBuiltIn,
    detail: UI_TEXT.mcpBuiltInDetail,
  }
}

/** The pick's placeholder: what the file holds, or why nothing can be shown. */
function mcpSummary(view: McpSettingsView, settingsPath: string): string {
  switch (view.status) {
    case 'missing': {
      return fill(UI_TEXT.mcpNoSettings, { path: settingsPath })
    }
    case 'unreadable': {
      return `${UI_TEXT.mcpUnreadable} ${view.reason}`
    }
    case 'read': {
      return view.servers.length === 0
        ? fill(UI_TEXT.mcpNone, { path: settingsPath })
        : plural(UI_TEXT.mcpCount, view.servers.length, { path: settingsPath })
    }
  }
}

/** The faults that make Muse Code load no user server at all, said out loud. */
function warnAboutFaults(deps: MuseConfigDeps, view: McpSettingsView): void {
  if (view.status !== 'read') {
    return
  }
  if (view.hasKeyConflict) {
    deps.showWarning(UI_TEXT.mcpKeyConflict)
  }
  const conflicted = view.servers.filter((server) => server.hasModeConflict)
  if (conflicted.length > 0) {
    deps.showWarning(
      `${UI_TEXT.mcpModeConflictWarning} ${conflicted.map((server) => server.name).join(LIST_SEPARATOR)}`,
    )
  }
}

async function openSettings(deps: MuseConfigDeps): Promise<void> {
  if (deps.fileExists(deps.settingsPath)) {
    await deps.openFile(deps.settingsPath)
    return
  }
  deps.showInformation(fill(UI_TEXT.museSettingsMissing, { path: deps.settingsPath }))
}

/** A server the Model API backend runs: its log, or its entry (M50). */
async function modelApiServerActions(deps: MuseConfigDeps, server: McpServerView): Promise<void> {
  const choice = await deps.pick(
    [
      ...(deps.openLog === undefined
        ? []
        : [{ id: SHOW_LOG, label: UI_TEXT.mcpShowLog, detail: UI_TEXT.mcpShowLogDetail }]),
      { id: OPEN_SETTINGS, label: UI_TEXT.mcpOpenSettings },
    ],
    server.name,
    UI_TEXT.mcpModelApiPlaceholder,
  )
  if (choice === SHOW_LOG) {
    deps.openLog?.()
  } else if (choice === OPEN_SETTINGS) {
    await openSettings(deps)
  }
}

async function serverActions(deps: MuseConfigDeps, server: McpServerView): Promise<void> {
  if (deps.modelApiServers !== undefined) {
    await modelApiServerActions(deps, server)
    return
  }
  const isRemote = server.transport === STREAMABLE_HTTP
  const items: PickItem[] = [
    ...(isRemote
      ? [
          { id: 'login', label: UI_TEXT.mcpSignIn, detail: UI_TEXT.mcpSignInDetail },
          { id: 'logout', label: UI_TEXT.mcpSignOut },
        ]
      : []),
    { id: OPEN_SETTINGS, label: UI_TEXT.mcpOpenSettings },
  ]
  const choice = await deps.pick(
    items,
    server.name,
    isRemote ? UI_TEXT.mcpRemotePlaceholder : UI_TEXT.mcpStdioPlaceholder,
  )
  if (choice === 'login' || choice === 'logout') {
    if (!(await deps.runMcpCommand(choice, server.name))) {
      deps.showWarning(UI_TEXT.mcpCliMissing)
    }
    return
  }
  if (choice === OPEN_SETTINGS) {
    await openSettings(deps)
  }
}

export async function showMcpServers(deps: MuseConfigDeps): Promise<void> {
  const read = settingsText(deps)
  const view: McpSettingsView =
    read.error === undefined
      ? readMcpServers(read.text)
      : { status: 'unreadable', reason: read.error }
  warnAboutFaults(deps, view)
  const servers = view.status === 'read' ? view.servers : []
  const isModelApi = deps.modelApiServers !== undefined
  const snapshot = deps.modelApiServers?.()
  const choice = await deps.pick(
    [
      ...servers.map((server) =>
        serverItem(server, isModelApi ? liveState(server, snapshot) : undefined),
      ),
      ...(isModelApi ? [builtInItem()] : []),
      { id: OPEN_SETTINGS, label: UI_TEXT.mcpOpenSettings, detail: deps.settingsPath },
      isModelApi
        ? {
            id: RESTART,
            label: UI_TEXT.mcpRestartModelApi,
            detail: UI_TEXT.mcpRestartModelApiDetail,
          }
        : { id: RESTART, label: UI_TEXT.mcpRestart, detail: UI_TEXT.mcpRestartDetail },
      { id: DOCS, label: UI_TEXT.mcpDocs },
    ],
    isModelApi ? UI_TEXT.mcpTitleModelApi : UI_TEXT.mcpTitle,
    mcpSummary(view, deps.settingsPath),
  )
  // Nothing to do for the built-in server: it has no entry and no process.
  if (choice === undefined || choice.startsWith(BUILT_IN_PREFIX)) {
    return
  }
  if (choice.startsWith(SERVER_PREFIX)) {
    const name = choice.slice(SERVER_PREFIX.length)
    const server = servers.find((candidate) => candidate.name === name)
    if (server !== undefined) {
      await serverActions(deps, server)
    }
    return
  }
  switch (choice) {
    case OPEN_SETTINGS: {
      await openSettings(deps)
      break
    }
    case RESTART: {
      await deps.restart()
      deps.showInformation(isModelApi ? UI_TEXT.mcpRestartedModelApi : UI_TEXT.mcpRestarted)
      break
    }
    default: {
      deps.openDocs()
    }
  }
}

function projectHooksItem(deps: MuseConfigDeps): PickItem {
  const { projectHooksPath } = deps
  let detail: string
  if (projectHooksPath === undefined || !deps.fileExists(projectHooksPath)) {
    detail = UI_TEXT.hooksProjectNone
  } else if (!deps.isWorkspaceTrusted()) {
    detail = UI_TEXT.hooksProjectUntrusted
  } else if (deps.modelApiHooks?.() === false) {
    detail = UI_TEXT.usagePaidOff
  } else {
    detail = UI_TEXT.hooksProjectTrusted
  }
  return {
    id: PROJECT_HOOKS,
    label: UI_TEXT.hooksProject,
    description: UI_TEXT.hooksProjectFile,
    detail,
  }
}

/**
 * On the Model API backend no hook source loads in an untrusted workspace, so
 * a configured user or managed source says it waits for trust, as the project
 * source does. Muse Code applies its own rules, so its view is unchanged.
 */
function withTrustNote(deps: MuseConfigDeps, detail: string): string {
  return deps.modelApiHooks !== undefined && !deps.isWorkspaceTrusted()
    ? `${detail} · ${UI_TEXT.hooksProjectUntrusted}`
    : detail
}

export async function showHooks(deps: MuseConfigDeps): Promise<void> {
  const read = settingsText(deps)
  if (read.error !== undefined) {
    deps.showWarning(`${UI_TEXT.mcpUnreadable} ${read.error}`)
  }
  const sources = readHookSources(read.text)
  const managed = sources.managedHooksPath
  let managedDetail: string = UI_TEXT.hooksManagedNotSet
  if (managed !== undefined) {
    managedDetail = deps.fileExists(managed)
      ? withTrustNote(deps, UI_TEXT.hooksManagedSet)
      : UI_TEXT.hooksManagedMissing
  }
  const choice = await deps.pick(
    [
      ...(deps.modelApiHooks === undefined
        ? []
        : [
            {
              id: MODEL_API_HOOKS_PICK,
              label: MODEL_API_HOOKS_SETTING,
              description: UI_TEXT.backendModelApi,
              detail: deps.modelApiHooks() === true ? UI_TEXT.usagePaidOn : UI_TEXT.usagePaidOff,
            },
          ]),
      projectHooksItem(deps),
      {
        id: USER_HOOKS,
        label: UI_TEXT.hooksUser,
        description: UI_TEXT.hooksUserBlock,
        detail:
          sources.userHookCount === undefined
            ? UI_TEXT.hooksUserNone
            : withTrustNote(deps, plural(UI_TEXT.hooksUserCount, sources.userHookCount)),
      },
      {
        id: MANAGED_HOOKS,
        label: UI_TEXT.hooksManaged,
        description: managed ?? UI_TEXT.hooksManagedKey,
        detail: managedDetail,
      },
      { id: DOCS, label: UI_TEXT.hooksDocs },
    ],
    deps.modelApiHooks === undefined ? UI_TEXT.hooksTitle : UI_TEXT.hooksTitleModelApi,
    deps.modelApiHooks === undefined ? UI_TEXT.hooksWarning : UI_TEXT.hooksModelApiWarning,
  )
  switch (choice) {
    case MODEL_API_HOOKS_PICK: {
      await deps.openModelApiHooksSetting?.()
      break
    }
    case PROJECT_HOOKS: {
      const target = deps.projectHooksPath
      if (target !== undefined && deps.fileExists(target)) {
        await deps.openFile(target)
      } else {
        deps.showInformation(UI_TEXT.hooksProjectNone)
      }
      break
    }
    case USER_HOOKS: {
      await openSettings(deps)
      break
    }
    case MANAGED_HOOKS: {
      if (managed !== undefined && deps.fileExists(managed)) {
        await deps.openFile(managed)
      } else {
        deps.showInformation(managedDetail)
      }
      break
    }
    case DOCS: {
      deps.openDocs()
      break
    }
    default: {
      break
    }
  }
}

src/host/commands/openInTerminal.ts:
// `Muse Spark: Open in Terminal` (PLAN.md D15): the Muse Code CLI's own
// interactive TUI in a VS Code terminal at the workspace root, for the user
// who wants the terminal experience beside the panel (Claude Code's "Open in
// Terminal"). The CLI is the user's signed-in one, so the work is billed to
// the subscription exactly as the panel's is; the pasted Model API key never
// reaches it.

import { MUSE_TERMINAL_NAME, UI_TEXT } from '../../shared/constants'

/** What a user-facing terminal needs beside the command line. */
export interface TerminalLaunchOptions {
  readonly name: string
  /** The terminal's working directory; VS Code's default when undefined. */
  readonly cwd: string | undefined
}

export interface OpenInTerminalDeps {
  readonly resolveCli: () =>
    | { readonly ok: true; readonly cliPath: string }
    | { readonly ok: false; readonly reason: string }
  readonly runInTerminal: (
    cliPath: string,
    args: readonly string[],
    options: TerminalLaunchOptions,
  ) => void | Promise<void>
  readonly workspaceRoot: string | undefined
  readonly showWarning: (message: string) => void
}

export async function openMuseTerminal(deps: OpenInTerminalDeps): Promise<void> {
  const cli = deps.resolveCli()
  if (!cli.ok) {
    deps.showWarning(`${UI_TEXT.terminalCliMissing} ${cli.reason}`)
    return
  }
  await deps.runInTerminal(cli.cliPath, [], { name: MUSE_TERMINAL_NAME, cwd: deps.workspaceRoot })
}

src/host/commands/planCommands.ts:
// The palette's Plans… (M79, PLAN.md D49): the saved plans, newest first,
// then what to do with the one picked, open it or implement it in a fresh
// conversation. The conversation controller acts on the answer; the picks
// are injected.

import type { PlanSummary } from '../../core/plans/planStore'
import { UI_TEXT } from '../../shared/constants'
import { plural } from '../../shared/l10n/text'
import type { PlanChoice } from '../conversation/conversationController'
import type { PickItem, PickOne } from './pickItem'

const PLAN_PREFIX = 'plan:'
const OPEN = 'open'
const IMPLEMENT = 'implement'

function planItem(plan: PlanSummary, index: number): PickItem {
  return { id: `${PLAN_PREFIX}${String(index)}`, label: plan.title, description: plan.fileName }
}

/** The plan picked and the action chosen for it; undefined when either pick is dismissed. */
export async function choosePlan(
  plans: readonly PlanSummary[],
  pick: PickOne,
): Promise<PlanChoice | undefined> {
  const picked = await pick(
    plans.map((plan, index) => planItem(plan, index)),
    UI_TEXT.plansTitle,
    plural(UI_TEXT.plansCount, plans.length),
  )
  const plan = picked?.startsWith(PLAN_PREFIX)
    ? plans[Number(picked.slice(PLAN_PREFIX.length))]
    : undefined
  if (plan === undefined) {
    return undefined
  }
  const action = await pick(
    [
      { id: OPEN, label: UI_TEXT.planOpen, detail: plan.relativePath },
      { id: IMPLEMENT, label: UI_TEXT.implementPlan, detail: UI_TEXT.planImplementDetail },
    ],
    plan.title,
    plan.fileName,
  )
  if (action === OPEN) {
    return { plan, action: 'open' }
  }
  return action === IMPLEMENT ? { plan, action: 'implement' } : undefined
}

src/host/commands/skillsCommands.ts:
// `Muse Spark: Manage Skills` and `Muse Spark: Import Skills from Claude Code
// or Codex` (M30, PLAN.md D30), on the Muse Code CLI's own skill commands
// (MSP has none). A running `muse serve` keeps the skills it started with,
// so a change ends with the offer to restart it. Every VS Code and process
// interaction is injected.

import {
  type ActivationChange,
  activationArgs,
  activationChanges,
  type CatalogSkill,
  type ImportEntry,
  type ImportReport,
  isSkillOn,
  parseImportReport,
  parseSkillCatalog,
  scopeFlagValue,
  skillImportArgs,
  skillsListArgs,
} from '../../core/backends/musecode/skillsCli'
import { stderrForLog } from '../../core/backends/musecode/logText'
import { clipForLog } from '../../core/logging'
import { type SkillImportSource, UI_TEXT } from '../../shared/constants'
import type { PluralForms } from '../../shared/l10n/forms'
import { fill, plural } from '../../shared/l10n/text'
import type { ProcessResult } from '../backend/sandboxSetup'
import type { Logger } from '../logger'

export interface SkillsCliDeps {
  /** The CLI with these arguments, run to completion; undefined when it is not installed. */
  readonly runCli: (args: readonly string[]) => Promise<ProcessResult> | undefined
  readonly workspaceRoot: string | undefined
  readonly isWorkspaceTrusted: () => boolean
  readonly showInformation: (message: string) => void
  readonly showError: (message: string) => void
  /** Offers to restart Muse Code; true when the user chose to. */
  readonly confirmRestart: () => Promise<boolean>
  readonly restart: () => Promise<void>
  readonly log: Logger
}

/** One row of the skills pick: checked when the skill is on. */
export interface SkillPickItem {
  readonly id: string
  readonly label: string
  readonly description: string
  readonly detail: string
  readonly picked: boolean
}

export interface ManageSkillsDeps extends SkillsCliDeps {
  /** A multi-select pick; the ids left checked, or undefined when dismissed. */
  readonly pickSkills: (items: readonly SkillPickItem[]) => Promise<ReadonlySet<string> | undefined>
}

export interface ImportSkillsDeps extends SkillsCliDeps {
  /** Where to import from, or undefined when dismissed. */
  readonly pickSource: () => Promise<SkillImportSource | undefined>
  /** A modal listing what would be imported; true to go ahead. */
  readonly confirmImport: (message: string, detail: string) => Promise<boolean>
}

const LINE_BREAK = /\r?\n/
const LIST_SEPARATOR = ', '
const NO_SKILLS = '—'

/** Where a skill comes from, in the display language; an unknown scope shows its id. */
function scopeLabel(scope: string): string {
  const labels: Readonly<Record<string, string>> = UI_TEXT.skillScopes
  return labels[scope] ?? scope
}

function firstLine(text: string): string {
  return text.trim().split(LINE_BREAK, 1)[0] ?? ''
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/** Why a finished CLI run failed, in one line. */
function failureOf(result: ProcessResult): string {
  return (
    firstLine(result.stderr) ||
    firstLine(result.stdout) ||
    fill(UI_TEXT.processExitCode, { code: String(result.exitCode) })
  )
}

/** The CLI's stdout, or undefined after telling the user why there is none. */
async function runForOutput(
  deps: SkillsCliDeps,
  args: readonly string[],
  failure: string,
): Promise<string | undefined> {
  const running = deps.runCli(args)
  if (running === undefined) {
    deps.showError(UI_TEXT.skillsCliMissing)
    return undefined
  }
  const result = await running
  if (result.exitCode !== 0) {
    deps.log.warn(
      `muse ${args.join(' ')} failed with exit code ${String(result.exitCode)}: ${clipForLog(stderrForLog(result.stderr))}`,
    )
    deps.showError(`${failure}: ${failureOf(result)}`)
    return undefined
  }
  return result.stdout
}

async function offerRestart(deps: SkillsCliDeps): Promise<void> {
  if (!(await deps.confirmRestart())) {
    return
  }
  await deps.restart()
  deps.showInformation(UI_TEXT.restartedNotice)
}

function pickItemOf(skill: CatalogSkill): SkillPickItem {
  return {
    id: skill.id,
    label: skill.displayName,
    description: scopeLabel(skill.scope),
    detail: skill.description,
    picked: isSkillOn(skill),
  }
}

async function applyChange(
  deps: SkillsCliDeps,
  change: ActivationChange,
): Promise<string | undefined> {
  const running = deps.runCli(activationArgs(change, deps.workspaceRoot, deps.isWorkspaceTrusted()))
  if (running === undefined) {
    return `${change.skill.name}: ${UI_TEXT.skillsCliMissing}`
  }
  const result = await running
  return result.exitCode === 0 ? undefined : `${change.skill.name}: ${failureOf(result)}`
}

export async function manageSkills(deps: ManageSkillsDeps): Promise<void> {
  const stdout = await runForOutput(
    deps,
    skillsListArgs(deps.workspaceRoot, deps.isWorkspaceTrusted()),
    UI_TEXT.skillsListFailed,
  )
  if (stdout === undefined) {
    return
  }
  let skills: readonly CatalogSkill[]
  try {
    skills = parseSkillCatalog(stdout).filter((skill) => scopeFlagValue(skill.scope) !== undefined)
  } catch (error: unknown) {
    deps.showError(`${UI_TEXT.skillsListFailed}: ${describe(error)}`)
    return
  }
  const picked = await deps.pickSkills(skills.map((skill) => pickItemOf(skill)))
  if (picked === undefined) {
    return
  }
  const changes = activationChanges(skills, picked)
  if (changes.length === 0) {
    deps.showInformation(UI_TEXT.skillsUnchanged)
    return
  }
  // One at a time: each command rewrites the same settings file.
  const failures: string[] = []
  for (const change of changes) {
    const failure = await applyChange(deps, change)
    if (failure !== undefined) {
      failures.push(failure)
    }
  }
  const changed = changes.length - failures.length
  if (failures.length > 0) {
    deps.log.warn(`Skill changes that failed: ${failures.join('; ')}`)
    deps.showError(fill(UI_TEXT.skillsChangeFailed, { skills: failures.join('; ') }))
  }
  if (changed === 0) {
    return
  }
  deps.log.info(`Skills changed: ${String(changed)} of ${String(changes.length)}`)
  await offerRestart(deps)
}

function entryLine(entry: ImportEntry): string {
  return entry.isValid ? entry.id : `${entry.id} (${UI_TEXT.importInvalid})`
}

function importSummary(report: ImportReport): string {
  const installed = report.installed.map((entry) => entry.id).join(LIST_SEPARATOR)
  const parts = [
    plural(UI_TEXT.importInstalledSummary, report.installed.length, {
      skills: installed === '' ? NO_SKILLS : installed,
    }),
  ]
  const counts: readonly (readonly [readonly ImportEntry[], PluralForms])[] = [
    [report.skipped, UI_TEXT.importSkippedSummary],
    [report.quarantined, UI_TEXT.importQuarantinedSummary],
    [report.failed, UI_TEXT.importFailedSummary],
  ]
  for (const [entries, summary] of counts) {
    if (entries.length === 0) {
      continue
    }
    const reasons = entries.map((entry) =>
      entry.reason === undefined ? entry.id : `${entry.id} (${entry.reason})`,
    )
    parts.push(plural(summary, entries.length, { skills: reasons.join(LIST_SEPARATOR) }))
  }
  return parts.join('. ')
}

function parsedReport(deps: SkillsCliDeps, stdout: string): ImportReport | undefined {
  try {
    return parseImportReport(stdout)
  } catch (error: unknown) {
    deps.showError(`${UI_TEXT.importFailed}: ${describe(error)}`)
    return undefined
  }
}

export async function importSkills(deps: ImportSkillsDeps): Promise<void> {
  const source = await deps.pickSource()
  if (source === undefined) {
    return
  }
  const preview = await runForOutput(deps, skillImportArgs(source, true), UI_TEXT.importFailed)
  const planned = preview === undefined ? undefined : parsedReport(deps, preview)
  if (planned === undefined) {
    return
  }
  if (planned.candidates.length === 0) {
    deps.showInformation(fill(UI_TEXT.importNothingFrom, { source: planned.sourcePath ?? source }))
    return
  }
  const isConfirmed = await deps.confirmImport(
    UI_TEXT.importConfirm,
    planned.candidates.map((entry) => entryLine(entry)).join('\n'),
  )
  if (!isConfirmed) {
    return
  }
  const output = await runForOutput(deps, skillImportArgs(source, false), UI_TEXT.importFailed)
  const report = output === undefined ? undefined : parsedReport(deps, output)
  if (report === undefined) {
    return
  }
  const summary = importSummary(report)
  deps.log.info(`muse skills import --from ${source}: ${summary}`)
  deps.showInformation(summary)
  if (report.installed.length > 0) {
    await offerRestart(deps)
  }
}

