// How the extension runs git (the mention index, the Model API prompt's
// environment facts): by absolute path, found on the absolute PATH entries
// only, so a `git.exe` committed to the workspace is never the one that runs
// (PLAN.md D24); with a timeout, no console window, no credential prompt,
// and `GIT_OPTIONAL_LOCKS=0` so a background `git status` never takes the
// index lock out from under the user's own git.

import { type ExecFileOptions, execFile, spawn } from 'node:child_process'
import { existsSync } from 'node:fs'
import { Buffer } from 'node:buffer'
import * as z from 'zod/mini'
import { resolveExecutable } from '../core/executables'
import type { BestOfNGitGuard } from '../core/bestOfN/bestOfNRunner'
import { environmentValue } from '../core/backends/musecode/launch'
import {
  BEST_OF_N_MIN_GIT_MINOR,
  GIT_FILTER_NAMES_ARGS,
  GIT_FILTER_NAMES_MAX,
  GIT_FILTER_NAME_MAX_CHARS,
  GIT_METADATA_OPTIONS,
  GIT_OUTPUT_MAX_BYTES,
  GIT_STDERR_MAX_CHARS,
  GIT_TIMEOUT_MS,
  UI_TEXT,
} from '../shared/constants'

const GIT = 'git'
const PATH_VARIABLE = 'PATH'
const GIT_MISSING = 'git was not found on the absolute entries of PATH'
const CONFIG_OPTION = '-c'
const OPTION_MARK = '-'
const FILTER_SEPARATOR = '\u{0}'
const FILTER_KEY = /^filter\.([^=\p{Cc}]+)\.(?:clean|process|required)$/u
// Best-of-N's automatic snapshots run with no hook, no fsmonitor, no replace
// refs and no maintenance, and refuse a repository that configures a program.
const AUTOMATIC_ARGS = [
  '--no-replace-objects',
  '-c',
  'core.hooksPath=/dev/null',
  '-c',
  'core.fsmonitor=false',
  '-c',
  'maintenance.auto=false',
  '-c',
  'gc.auto=0',
]
const PROGRAM_CONFIG = /^(?:filter\..+\.(?:clean|smudge|process)|hook\..+\.command)$/iu
const filterKeys = z
  .array(z.string().check(z.maxLength(GIT_FILTER_NAME_MAX_CHARS), z.regex(FILTER_KEY)))
  .check(z.maxLength(GIT_FILTER_NAMES_MAX))

/** Names only become scoped overrides; configured command values are never read. */
export function gitFilterOptions(output: string): readonly string[] {
  const names = output === '' ? [] : output.split(FILTER_SEPARATOR)
  if (names.at(-1) === '') {
    names.pop()
  }
  const parsed = filterKeys.safeParse(names)
  if (!parsed.success) {
    throw new Error(UI_TEXT.checkpointFailed)
  }
  const drivers = new Set(parsed.data.map((key) => key.slice(0, key.lastIndexOf('.'))))
  return [...drivers].flatMap((driver) => [
    '-c',
    `${driver}.clean=`,
    '-c',
    `${driver}.process=`,
    '-c',
    `${driver}.required=false`,
  ])
}

/**
 * git for an automatic metadata read in `cwd` (the prompt's facts, D15; the
 * session board, M77): no fsmonitor, maintenance, replacement refs or
 * signature program (GIT_METADATA_OPTIONS), and each configured filter
 * driver's clean and process emptied by name, its command never read. The
 * runner's `GIT_OPTIONAL_LOCKS=0` takes no index lock, so status writes no
 * index and no index hook runs. Rejects when the names cannot be read.
 */
export async function metadataGit(
  runGit: (args: readonly string[], cwd: string, timeoutMs?: number) => Promise<string>,
  cwd: string,
): Promise<(args: readonly string[], timeoutMs?: number) => Promise<string>> {
  let names: string
  try {
    names = await runGit([...GIT_METADATA_OPTIONS, ...GIT_FILTER_NAMES_ARGS], cwd)
  } catch (error: unknown) {
    // `config --get-regexp` exits 1 when no filter is configured.
    if (typeof error !== 'object' || error === null || !('code' in error) || error.code !== 1) {
      throw error
    }
    names = ''
  }
  const filters = gitFilterOptions(names)
  return async (args, timeoutMs) =>
    await runGit([...GIT_METADATA_OPTIONS, ...filters, ...args], cwd, timeoutMs)
}

/** git is not on the absolute entries of PATH (D24): nothing ran. */
export class GitMissingError extends Error {
  public constructor() {
    super(GIT_MISSING)
    this.name = 'GitMissingError'
  }
}

/** The subcommand of an argument list, past `-c name=value` pairs and other options. */
function subcommandOf(args: readonly string[]): string {
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index] ?? ''
    if (arg === CONFIG_OPTION) {
      index += 1
    } else if (!arg.startsWith(OPTION_MARK)) {
      return arg
    }
  }
  return GIT
}

/**
 * git's absolute path, found once per PATH value; a miss is not cached, so
 * git installed while the window is open is found on the next call.
 */
function gitLocator(
  deps: Pick<GitRunnerDeps, 'platform' | 'env' | 'fileExists'>,
): () => string | undefined {
  let cache: { readonly pathValue: string | undefined; readonly git: string } | undefined
  return () => {
    const pathValue = environmentValue(deps.env, deps.platform, PATH_VARIABLE)
    if (cache === undefined || cache.pathValue !== pathValue) {
      const git = resolveExecutable(GIT, {
        platform: deps.platform,
        pathVariable: pathValue,
        fileExists: deps.fileExists,
      })
      cache = git === undefined ? undefined : { pathValue, git }
    }
    return cache?.git
  }
}

export interface GitRunnerDeps {
  readonly platform: NodeJS.Platform
  readonly env: NodeJS.ProcessEnv
  readonly fileExists: (filePath: string) => boolean
  /** Best-of-N's automatic local snapshots, never ordinary user Git commands. */
  readonly isAutomatic?: boolean
  /** `execFile` as a promise of stdout; rejects on a failure, a timeout or a non-zero exit. */
  readonly execFile: (
    file: string,
    args: readonly string[],
    options: ExecFileOptions,
    input?: string,
  ) => Promise<string>
}

/**
 * A git runner; rejects when git is not on the absolute PATH. A call that
 * does real work (a worktree's checkout, M32) passes its own timeout.
 */
export function createGitRunner(
  deps: GitRunnerDeps,
): (
  args: readonly string[],
  cwd: string,
  timeoutMs?: number,
  input?: string,
  beforeRun?: BestOfNGitGuard,
) => Promise<string> {
  const env: NodeJS.ProcessEnv = {
    ...deps.env,
    GIT_OPTIONAL_LOCKS: '0',
    GIT_TERMINAL_PROMPT: '0',
  }
  const gitPath = gitLocator(deps)
  let supportedVersion: { readonly git: string; readonly checked: Promise<void> } | undefined
  return async (args, cwd, timeoutMs = GIT_TIMEOUT_MS, input, beforeRun) => {
    const git = gitPath()
    if (git === undefined) {
      throw new GitMissingError()
    }
    const options: ExecFileOptions = {
      cwd,
      env,
      maxBuffer: GIT_OUTPUT_MAX_BYTES,
      timeout: timeoutMs,
      windowsHide: true,
    }
    beforeRun?.()
    if (deps.isAutomatic === true) {
      if (supportedVersion?.git !== git) {
        supportedVersion = {
          git,
          checked: (async () => {
            const version = /^git version (\d+)\.(\d+)/u.exec(
              await deps.execFile(git, ['--version'], options),
            )
            const major = Number(version?.[1])
            const minor = Number(version?.[2])
            if (
              !Number.isSafeInteger(major) ||
              !Number.isSafeInteger(minor) ||
              major < 2 ||
              (major === 2 && minor < BEST_OF_N_MIN_GIT_MINOR)
            ) {
              throw new Error(UI_TEXT.bestOfNGitProgramsUnavailable)
            }
          })(),
        }
      }
      await supportedVersion.checked
      beforeRun?.()
      const location = args.filter(
        (arg) => arg.startsWith('--git-dir=') || arg.startsWith('--work-tree='),
      )
      const names = await deps.execFile(
        git,
        [...AUTOMATIC_ARGS, ...location, 'config', '--null', '--name-only', '--list'],
        options,
      )
      if (names.split('\0').some((name) => PROGRAM_CONFIG.test(name))) {
        throw new Error(UI_TEXT.bestOfNGitProgramsUnavailable)
      }
    }
    const invocation = deps.isAutomatic === true ? [...AUTOMATIC_ARGS, ...args] : args
    await beforeRun?.prepare?.()
    // Configuration/version reads can await. The owned caller rechecks
    // synchronously here, with no await before the actual process entry.
    beforeRun?.()
    return input === undefined
      ? await deps.execFile(git, invocation, options)
      : await deps.execFile(git, invocation, options, input)
  }
}

/**
 * The runner over this process's own environment and Node's `execFile`: the
 * one the extension uses, and the one tests use to drive real git (M32).
 */
export function processGitRunner(
  options: { readonly isAutomatic?: boolean; readonly env?: NodeJS.ProcessEnv } = {},
): (
  args: readonly string[],
  cwd: string,
  timeoutMs?: number,
  input?: string,
  beforeRun?: BestOfNGitGuard,
) => Promise<string> {
  return createGitRunner({
    platform: process.platform,
    env: options.env ?? process.env,
    fileExists: existsSync,
    isAutomatic: options.isAutomatic === true,
    execFile: (file, args, options, input) =>
      new Promise((resolve, reject) => {
        const child = execFile(
          file,
          [...args],
          { ...options, encoding: 'utf8' },
          (error, stdout) => {
            if (error === null) {
              resolve(stdout)
            } else {
              reject(error instanceof Error ? error : new Error('Git process failed'))
            }
          },
        )
        child.stdin?.on('error', reject)
        child.stdin?.end(input)
      }),
  })
}

/** git ended with a non-zero exit code: the code and what it said (capped). */
export class GitExitError extends Error {
  public constructor(
    public readonly exitCode: number,
    public readonly stderr: string,
    command: string,
  ) {
    super(`git ${command} exited with code ${String(exitCode)}: ${stderr.trim()}`)
    this.name = 'GitExitError'
  }
}

/** All extra fields are checked; the original error/message are retained. */
export function isGitExitError(value: unknown): value is GitExitError {
  return (
    value instanceof Error &&
    value.name === 'GitExitError' &&
    'exitCode' in value &&
    typeof value.exitCode === 'number' &&
    Number.isSafeInteger(value.exitCode) &&
    'stderr' in value &&
    typeof value.stderr === 'string'
  )
}

export interface GitProcessOptions {
  readonly cwd: string
  /** The child's whole environment: nothing else is inherited. */
  readonly env: NodeJS.ProcessEnv
  /** Written to stdin, which is then closed; stdin is empty without it. */
  readonly input?: string | Uint8Array
  readonly timeoutMs: number
  /** Aborting ends the command (the window closing). */
  readonly signal?: AbortSignal
}

/** One git command's stdout as bytes; rejects on a failure, a timeout or a non-zero exit. */
export type GitProcess = (args: readonly string[], options: GitProcessOptions) => Promise<Buffer>

export interface GitProcessDeps {
  readonly platform: NodeJS.Platform
  /** Where git is looked for: this environment's PATH, absolute entries only (D24). */
  readonly env: NodeJS.ProcessEnv
  readonly fileExists: (filePath: string) => boolean
  readonly spawn: typeof spawn
}

/**
 * git with stdin and binary stdout (M72's checkpoints): found as the other
 * runner finds it, no console window, stdout capped at GIT_OUTPUT_MAX_BYTES
 * and stderr at GIT_STDERR_MAX_CHARS, killed at its timeout. The caller
 * passes the complete environment, so nothing of the extension host's own
 * (a `GIT_DIR`, a `GIT_INDEX_FILE`) reaches it unless the caller says so.
 */
export function createGitProcess(deps: GitProcessDeps): GitProcess {
  const gitPath = gitLocator(deps)
  return (args, options) =>
    new Promise<Buffer>((resolve, reject) => {
      const git = gitPath()
      if (git === undefined) {
        reject(new GitMissingError())
        return
      }
      const command = subcommandOf(args)
      if (options.signal?.aborted === true) {
        reject(new Error(`git ${command} was not started: the window is closing`))
        return
      }
      const child = deps.spawn(git, [...args], {
        cwd: options.cwd,
        env: options.env,
        stdio: ['pipe', 'pipe', 'pipe'],
        windowsHide: true,
      })
      const chunks: Buffer[] = []
      let size = 0
      let stderr = ''
      let failure: Error | undefined
      const fail = (error: Error) => {
        failure ??= error
        child.kill()
      }
      const timer = setTimeout(() => {
        fail(new Error(`git ${command} timed out after ${String(options.timeoutMs)} ms`))
      }, options.timeoutMs)
      const onAbort = () => {
        fail(new Error(`git ${command} was stopped: the window is closing`))
      }
      options.signal?.addEventListener('abort', onAbort, { once: true })
      child.stdout.on('data', (chunk: Buffer) => {
        size += chunk.length
        if (size > GIT_OUTPUT_MAX_BYTES) {
          fail(new Error(`git ${command} wrote more than ${String(GIT_OUTPUT_MAX_BYTES)} bytes`))
          return
        }
        chunks.push(chunk)
      })
      child.stderr.setEncoding('utf8')
      child.stderr.on('data', (chunk: string) => {
        if (stderr.length < GIT_STDERR_MAX_CHARS) {
          stderr = `${stderr}${chunk}`.slice(0, GIT_STDERR_MAX_CHARS)
        }
      })
      // A command that exits before reading all of stdin closes the pipe
      // under the write; its exit code says what went wrong.
      child.stdin.on('error', () => {
        // Nothing to add: the exit code reports it.
      })
      child.on('error', (error) => {
        fail(error)
      })
      child.on('close', (code) => {
        clearTimeout(timer)
        options.signal?.removeEventListener('abort', onAbort)
        if (failure !== undefined) {
          reject(failure)
        } else if (code === 0) {
          resolve(Buffer.concat(chunks))
        } else {
          reject(new GitExitError(code ?? -1, stderr, command))
        }
      })
      child.stdin.end(options.input ?? '')
    })
}

/** Whether git is on the absolute entries of this process's PATH (M72's availability). */
export function processGitLocator(): () => boolean {
  const locate = gitLocator({
    platform: process.platform,
    env: process.env,
    fileExists: existsSync,
  })
  return () => locate() !== undefined
}

/** The process runner over this process's PATH and Node's `spawn` (M72). */
export function processGitProcess(): GitProcess {
  return createGitProcess({
    platform: process.platform,
    env: process.env,
    fileExists: existsSync,
    spawn,
  })
}

src/host/html.ts:
// Builds the webview document. Pure: no `vscode` import, so it is unit-tested
// directly. Security properties (PLAN.md section 2, D4):
//   - default-src 'none'; scripts only with the per-load nonce; no remote
//     origins; no 'unsafe-inline' / 'unsafe-eval' anywhere.
//   - Inline `style=` attributes are blocked by this policy on purpose, so the
//     React tree must style through classes in main.css.
//   - The display language's table rides in a `type="application/json"`
//     script (D33): a data block the browser never runs, so the policy needs
//     no change for it. The webview reads it before its first render.

import {
  NONCE_BYTES,
  PRODUCT_NAME,
  WEBVIEW_L10N_ELEMENT_ID,
  WEBVIEW_ROOT_ELEMENT_ID,
} from '../shared/constants'
import type { UiTable } from './l10n'

export interface WebviewHtmlOptions {
  readonly scriptUri: string
  readonly styleUri: string
  /** `webview.cspSource`: the origin VS Code serves local resources from. */
  readonly cspSource: string
  readonly nonce: string
  /** The installed table and its language (`<html lang>` for screen readers). */
  readonly l10n: UiTable
}

// What must not appear raw inside a script element: `<` could close it
// (`</script>`) or open a comment, and the two line separators end a line
// in older JavaScript parsers. Each becomes its JSON escape, which parses
// back to the same text.
const SCRIPT_UNSAFE = /[<\u{2028}\u{2029}]/gu
const SCRIPT_ESCAPES: Readonly<Record<string, string>> = {
  '<': String.raw`\u003c`,
  '\u{2028}': String.raw`\u2028`,
  '\u{2029}': String.raw`\u2029`,
}

export function createNonce(): string {
  const bytes = globalThis.crypto.getRandomValues(new Uint8Array(NONCE_BYTES))
  return Buffer.from(bytes).toString('base64url')
}

/** JSON that is safe as the text of a `<script>` element. */
function scriptSafeJson(value: unknown): string {
  return JSON.stringify(value).replaceAll(
    SCRIPT_UNSAFE,
    (character) => SCRIPT_ESCAPES[character] ?? character,
  )
}

export function buildWebviewHtml(options: WebviewHtmlOptions): string {
  const csp = [
    `default-src 'none'`,
    `img-src ${options.cspSource} data:`,
    `style-src ${options.cspSource} 'nonce-${options.nonce}'`,
    `font-src ${options.cspSource}`,
    `script-src 'nonce-${options.nonce}'`,
  ].join('; ')
  const { locale, table } = options.l10n

  return `<!DOCTYPE html>
<html lang="${locale}">
<head>
<meta charset="UTF-8">
<meta http-equiv="Content-Security-Policy" content="${csp}">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link rel="stylesheet" href="${options.styleUri}" nonce="${options.nonce}">
<title>${PRODUCT_NAME}</title>
</head>
<body>
<div id="${WEBVIEW_ROOT_ELEMENT_ID}"></div>
<script type="application/json" id="${WEBVIEW_L10N_ELEMENT_ID}">${scriptSafeJson({ locale, table })}</script>
<script nonce="${options.nonce}" src="${options.scriptUri}"></script>
</body>
</html>
`
}

src/host/ide/codeIntelBundle.ts:
// Code intelligence's answers as the activation bundle sees them (M67,
// PLAN.md D6): dist/codeIntel.js, built from codeIntelEntry.ts and required
// on the first `ide` code intelligence call. Only types come from the
// queries' side here: a value imported from there would carry them back
// into dist/extension.js, which the bundle-split gate refuses.
//
// There is no fallback without it: a call that cannot load it is answered
// with `MODEL_TEXT.codeIntelUnavailable` as an error result (the log has the
// cause), and the next call tries again.

import { MODEL_TEXT } from '../../shared/constants'
import { lazyBundleLoader } from '../lazyBundle'
import type { Logger } from '../logger'
import type * as CodeIntelEntry from './codeIntelEntry'

/** The bundle's one export. */
export interface CodeIntelBundle {
  readonly callCodeIntel: typeof CodeIntelEntry.callCodeIntel
}

/** Whether a required module exports the call. */
export function isCodeIntelBundle(value: unknown): value is CodeIntelBundle {
  return (
    typeof value === 'object' &&
    value !== null &&
    'callCodeIntel' in value &&
    typeof value.callCodeIntel === 'function'
  )
}

export interface CodeIntelLoaderDeps {
  /** dist/codeIntel.js beside the running bundle. */
  readonly bundlePath: string
  readonly log: Logger
  /** How the bundle is loaded: Node's `require` unless a test hands in the module. */
  readonly loadBundle?: ((file: string) => unknown) | undefined
}

/** The bundle, required on the first call and kept from then on. */
export function codeIntelLoader(deps: CodeIntelLoaderDeps): () => CodeIntelBundle {
  return lazyBundleLoader({
    ...deps,
    isBundle: isCodeIntelBundle,
    label: 'code intelligence bundle',
    unavailable: () => MODEL_TEXT.codeIntelUnavailable,
  })
}

src/host/ide/codeIntelTools.ts:
// The code intelligence tools the `ide` server offers Muse Code (M67,
// PLAN.md D49): the same answers as the Model API's native tools, as
// `mcp__ide__findDefinition` and the rest. Every one changes nothing, so
// each declares `readOnlyHint` (D49's rule for tools on `ide`) and all are
// listed in Restricted Mode too. `renameSymbol` never writes: it returns the
// edits as a diff, and Muse Code's own edit tool applies them under its
// approvals and rewind. Listed only with a folder open. The answers are
// dist/codeIntel.js (D6), loaded on the first call.

import { IDE_CODE_INTEL_TOOLS, MCP_ANNOTATIONS_READ_ONLY, UI_TEXT } from '../../shared/constants'
import type { CodeIntelDeps } from '../../core/codeIntel/codeIntelQuery'
import {
  type CodeIntelDefinition,
  IDE_CODE_INTEL_DEFINITIONS,
} from '../../core/codeIntel/definitions'
import type { McpTool } from '../../core/mcp'
import { uiLocale } from '../../shared/l10n/text'
import type { CodeIntelBundle } from './codeIntelBundle'

function toolFor(
  definition: CodeIntelDefinition,
  intel: CodeIntelDeps,
  bundle: () => CodeIntelBundle,
): McpTool {
  const { tool } = definition
  return {
    name: IDE_CODE_INTEL_TOOLS[tool],
    description: definition.description,
    inputSchema: {
      type: 'object',
      properties: definition.properties,
      required: [...definition.required],
      additionalProperties: false,
    },
    annotations: MCP_ANNOTATIONS_READ_ONLY,
    // A refusal, or a bundle that cannot load, rejects, so the server
    // answers with an error result the model reads.
    call: async (args) => await bundle().callCodeIntel(tool, args, intel, UI_TEXT, uiLocale()),
  }
}

/** The tools as they stand: none with no folder open. */
export function ideCodeIntelTools(
  intel: CodeIntelDeps | undefined,
  bundle: () => CodeIntelBundle,
): readonly McpTool[] {
  return intel === undefined
    ? []
    : IDE_CODE_INTEL_DEFINITIONS.map((definition) => toolFor(definition, intel, bundle))
}

src/host/ide/ideMcpServer.ts:
// The IDE tool server `muse serve` reaches from each session: MCP over
// streamable HTTP on a loopback port, guarded by a bearer token minted per
// extension host (never logged, never written to disk). Its tools are
// `getDiagnostics`, web fetch in a trusted workspace (M69) and, while paid
// image generation is on and a key is stored, the image tools (M44); the
// list is read on every request, so a session started after a change sees
// it. A call whose caller stops waiting (its request closed, or
// `notifications/cancelled` naming it) is told through its signal. The
// JSON-RPC handling itself is pure (src/core/mcp.ts).

import { randomBytes, timingSafeEqual } from 'node:crypto'
import { Buffer } from 'node:buffer'
import { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http'
import {
  handleMcpMessage,
  type McpOutcome,
  type McpRequestKey,
  mcpRequestKeys,
  type McpTool,
} from '../../core/mcp'
import {
  CLI_OUTPUT_MAX_BYTES,
  HTTP_STATUS,
  IDE_MCP_LOOPBACK_HOST,
  IDE_MCP_PATH,
  IDE_MCP_SERVER_INFO,
  IDE_MCP_TOKEN_BYTES,
} from '../../shared/constants'
import type { Logger } from '../logger'

/** What `session/start` is told: where the server is and how to authenticate. */
export interface IdeMcpEndpoint {
  readonly url: string
  readonly headers: Readonly<Record<string, string>>
}

const AUTHORIZATION_HEADER = 'authorization'
const BEARER_PREFIX = 'Bearer '
const JSON_CONTENT_TYPE = 'application/json'
const POST = 'POST'

function readBody(request: IncomingMessage, maxBytes: number): Promise<string | undefined> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = []
    let size = 0
    request.on('data', (chunk: Buffer) => {
      size += chunk.length
      if (size <= maxBytes) {
        chunks.push(chunk)
      }
    })
    request.on('end', () => {
      resolve(size > maxBytes ? undefined : Buffer.concat(chunks).toString('utf8'))
    })
    request.on('error', () => {
      resolve(undefined)
    })
  })
}

function isSameSecret(presented: string, expected: string): boolean {
  const left = Buffer.from(presented)
  const right = Buffer.from(expected)
  return left.length === right.length && timingSafeEqual(left, right)
}

export class IdeMcpServer {
  private readonly token = randomBytes(IDE_MCP_TOKEN_BYTES).toString('hex')
  private server: Server | undefined
  private endpoint: IdeMcpEndpoint | undefined
  /** A start in flight: concurrent callers share it instead of opening two ports. */
  private starting: Promise<IdeMcpEndpoint> | undefined
  /** The calls being answered, by request id, so a cancellation can stop them (M69). */
  private readonly inFlight = new Map<McpRequestKey, Set<AbortController>>()

  public constructor(
    /** The tools offered now, asked on every request. */
    private readonly tools: () => readonly McpTool[],
    private readonly log: Logger,
  ) {}

  /**
   * Stops every call in flight under the key (M69). Muse Code 1.4.0 sends
   * `notifications/cancelled` for a stopped turn's call and closes its
   * request; either one stops the tool. The server has no session identity,
   * so two sessions' calls with the same id are both stopped: a stopped call
   * fails, which no call takes as success.
   */
  private cancel(key: McpRequestKey): void {
    const calls = this.inFlight.get(key) ?? []
    for (const controller of calls) {
      controller.abort()
    }
  }

  /** The body handled with a signal that aborts when its caller stops waiting. */
  private async handleInFlight(
    body: string,
    key: McpRequestKey | undefined,
    response: ServerResponse,
  ): Promise<McpOutcome> {
    const controller = new AbortController()
    const onClose = () => {
      if (!response.writableFinished) {
        controller.abort()
      }
    }
    response.once('close', onClose)
    const calls = key === undefined ? undefined : (this.inFlight.get(key) ?? new Set())
    if (key !== undefined && calls !== undefined) {
      calls.add(controller)
      this.inFlight.set(key, calls)
    }
    try {
      return await handleMcpMessage(body, this.tools(), IDE_MCP_SERVER_INFO, controller.signal)
    } finally {
      response.off('close', onClose)
      if (key !== undefined && calls !== undefined) {
        calls.delete(controller)
        if (calls.size === 0) {
          this.inFlight.delete(key)
        }
      }
    }
  }

  private isAuthorised(request: IncomingMessage): boolean {
    const header = request.headers[AUTHORIZATION_HEADER]
    return (
      typeof header === 'string' &&
      header.startsWith(BEARER_PREFIX) &&
      isSameSecret(header.slice(BEARER_PREFIX.length), this.token)
    )
  }

  private async handle(request: IncomingMessage, response: ServerResponse): Promise<void> {
    if (request.method !== POST) {
      response.writeHead(HTTP_STATUS.methodNotAllowed).end()
      return
    }
    if (request.url !== IDE_MCP_PATH) {
      response.writeHead(HTTP_STATUS.notFound).end()
      return
    }
    if (!this.isAuthorised(request)) {
      this.log.warn('IDE tool server refused a request without the session token')
      response.writeHead(HTTP_STATUS.unauthorized).end()
      return
    }
    const body = await readBody(request, CLI_OUTPUT_MAX_BYTES)
    if (body === undefined) {
      response.writeHead(HTTP_STATUS.badRequest).end()
      return
    }
    const keys = mcpRequestKeys(body)
    if (keys.cancelled !== undefined) {
      this.cancel(keys.cancelled)
    }
    const outcome = await this.handleInFlight(body, keys.request, response)
    if (response.destroyed) {
      return
    }
    if (outcome.kind === 'accepted') {
      response.writeHead(HTTP_STATUS.accepted).end()
      return
    }
    response.writeHead(HTTP_STATUS.ok, { 'content-type': JSON_CONTENT_TYPE })
    response.end(JSON.stringify(outcome.body))
  }

  /** The endpoint once `start` has resolved; undefined before or after `close`. */
  /** `handle`, with a failure answered 500 instead of left as an unhandled rejection (D25). */
  private async respond(request: IncomingMessage, response: ServerResponse): Promise<void> {
    try {
      await this.handle(request, response)
    } catch (error: unknown) {
      this.log.error(`IDE tool server request failed: ${String(error)}`)
      if (response.headersSent) {
        response.end()
      } else {
        response.writeHead(HTTP_STATUS.internalServerError).end()
      }
    }
  }

  /** `listen`, forgetting the shared start once it settles. */
  private async listenOnce(): Promise<IdeMcpEndpoint> {
    try {
      return await this.listen()
    } finally {
      this.starting = undefined
    }
  }

  private async listen(): Promise<IdeMcpEndpoint> {
    const server = createServer((request, response) => {
      void this.respond(request, response)
    })
    this.server = server
    await new Promise<void>((resolve, reject) => {
      server.once('error', reject)
      server.listen(0, IDE_MCP_LOOPBACK_HOST, () => {
        server.off('error', reject)
        resolve()
      })
    })
    // Errors after the listen (a socket fault) are logged, never thrown at the host.
    server.on('error', (error) => {
      this.log.error(`IDE tool server error: ${error.message}`)
    })
    const address = server.address()
    if (address === null || typeof address === 'string') {
      throw new Error('IDE tool server has no TCP address')
    }
    this.endpoint = {
      url: `http://${IDE_MCP_LOOPBACK_HOST}:${String(address.port)}${IDE_MCP_PATH}`,
      headers: { Authorization: `${BEARER_PREFIX}${this.token}` },
    }
    this.log.info(`IDE tool server listening on ${this.endpoint.url}`)
    return this.endpoint
  }

  public get current(): IdeMcpEndpoint | undefined {
    return this.endpoint
  }

  /**
   * Listens on an ephemeral loopback port; idempotent, and callable again
   * after a failed start (PLAN.md D25: a first failure no longer leaves the
   * diagnostics tool off for the window's life).
   */
  public start(): Promise<IdeMcpEndpoint> {
    if (this.endpoint !== undefined) {
      return Promise.resolve(this.endpoint)
    }
    this.starting ??= this.listenOnce()
    return this.starting
  }

  public close(): void {
    this.server?.close()
    this.server = undefined
    this.endpoint = undefined
  }
}

src/host/ide/imageTools.ts:
// The image tools the `ide` session server offers Muse Code (M44, PLAN.md
// D37): Muse Code's own image tool is switched off in `muse serve`, so on
// the Muse Code backend the extension makes images itself, with Meta's image
// model and the stored Model API key. The key stays in this process and is
// never handed to `muse serve` (D1); the subscription never pays for an
// image. They are offered only while paid image generation is on (D30) and
// a key is stored, and every call is confirmed in a modal naming the price,
// whatever permission mode Muse Code runs in: its own approval covers using
// the tool, this one covers buying the image.

import { IMAGE_REQUEST_TIMEOUT_MS, IDE_IMAGE_TOOLS, MODEL_TEXT } from '../../shared/constants'
import type { McpTool } from '../../core/mcp'
import type { ModelApiClient } from '../../core/backends/modelapi/client'
import {
  type ImagePlan,
  type ImageWorkspace,
  prepareImageCall,
  runImageCall,
} from '../../core/backends/modelapi/imageGeneration'
import {
  EDIT_IMAGE_DESCRIPTION,
  EDIT_IMAGE_PARAMETERS,
  GENERATE_IMAGE_DESCRIPTION,
  GENERATE_IMAGE_PARAMETERS,
} from '../../core/backends/modelapi/imageToolDefinitions'
import type { Logger } from '../logger'

export interface IdeImageToolsDeps {
  /** Whether the tools are offered now: image generation on and a key stored. */
  readonly isOffered: () => boolean
  /** Changes before SecretStorage replaces a secondary key. */
  readonly keyGeneration: () => number
  /** The workspace the images go into; undefined with no folder open. */
  readonly workspace: ImageWorkspace | undefined
  /** A Model API client that reads the stored key (never the subscription). */
  readonly client: ModelApiClient
  /** The modal before every purchase; true only when the user chose to buy. */
  readonly confirm: (plan: ImagePlan) => Promise<boolean>
  /** Called once an image was returned: the window's tally. */
  readonly onBilled: () => void
  readonly log: Logger
}

interface ImageToolShape {
  readonly kind: ImagePlan['kind']
  readonly name: string
  readonly description: string
  readonly parameters: Readonly<Record<string, unknown>>
  readonly required: readonly string[]
}

const SHAPES: readonly ImageToolShape[] = [
  {
    kind: 'generate',
    name: IDE_IMAGE_TOOLS.generateImage,
    description: GENERATE_IMAGE_DESCRIPTION,
    parameters: GENERATE_IMAGE_PARAMETERS,
    required: ['prompt', 'path'],
  },
  {
    kind: 'edit',
    name: IDE_IMAGE_TOOLS.editImage,
    description: EDIT_IMAGE_DESCRIPTION,
    parameters: EDIT_IMAGE_PARAMETERS,
    required: ['prompt', 'images', 'path'],
  },
]

/** One call: checked, confirmed, bought and written, or refused with the reason. */
async function callImageTool(
  shape: ImageToolShape,
  args: Readonly<Record<string, unknown>>,
  workspace: ImageWorkspace,
  deps: IdeImageToolsDeps,
): Promise<string> {
  const keyGeneration = deps.keyGeneration()
  const prepared = await prepareImageCall(shape.kind, args, workspace)
  if (!prepared.ok) {
    throw new Error(prepared.reason)
  }
  const keyDigest = await deps.client.currentKeyDigest()
  if (deps.keyGeneration() !== keyGeneration) {
    throw new Error(MODEL_TEXT.imageAccountChanged)
  }
  if (!(await deps.confirm(prepared.plan))) {
    deps.log.info(`Image ${prepared.plan.target.relative} declined in the price confirmation`)
    throw new Error(MODEL_TEXT.imageDeclined)
  }
  if (deps.keyGeneration() !== keyGeneration) {
    throw new Error(MODEL_TEXT.imageAccountChanged)
  }
  const outcome = await runImageCall(prepared.plan, {
    client: deps.client,
    io: workspace.io,
    // No turn to stop it from here: the request's own deadline ends the wait.
    signal: AbortSignal.timeout(IMAGE_REQUEST_TIMEOUT_MS),
    isStillOn: deps.isOffered,
    admitAttempt: (currentDigest) => {
      if (currentDigest !== keyDigest || deps.keyGeneration() !== keyGeneration) {
        throw new Error(MODEL_TEXT.imageAccountChanged)
      }
      if (!deps.isOffered()) {
        throw new Error(MODEL_TEXT.imageGenerationOff)
      }
    },
    onBilled: deps.onBilled,
  })
  if (outcome.failureReason !== undefined) {
    throw new Error(outcome.failureReason)
  }
  deps.log.info(`Image ${prepared.plan.target.relative} made for Muse Code (billed to the key)`)
  return outcome.output
}

/** The tools as they stand now: none while image generation is off or no key is stored. */
export function ideImageTools(deps: IdeImageToolsDeps): readonly McpTool[] {
  const { workspace } = deps
  if (workspace === undefined || !deps.isOffered()) {
    return []
  }
  return SHAPES.map((shape) => ({
    name: shape.name,
    description: shape.description,
    inputSchema: {
      type: 'object',
      properties: shape.parameters,
      required: shape.required,
      additionalProperties: false,
    },
    call: async (args) => await callImageTool(shape, args, workspace, deps),
  }))
}

src/host/ide/webFetchTool.ts:
// Web fetch for Muse Code through the `ide` session server (M69, PLAN.md
// D49): Muse Code's own `web_fetch` is switched off in `muse serve`, so the
// extension fetches the page itself (webFetcher.ts) and hands its text back.
// The server is one loopback endpoint for the whole window, with no session
// identity, and it is attached even in Restricted Mode, so the tool:
//
// - is listed only while the workspace is trusted and
//   `museSpark.sandboxNetwork` does not deny the agent the network (the list
//   is read on every request, so a call made after either changes finds no
//   such tool);
// - declares itself open-world and not read-only (MCP annotations), so Muse
//   Code's own approval treats it as more than a read;
// - asks in the extension's own modal before every call, naming the host
//   and the URL, whatever mode Muse Code runs in, as the image tools do, and
//   checks that it is still offered after the answer, before each request
//   the fetch sends, and once the page is in;
// - stops when Muse Code stops waiting (a stopped turn closes the request
//   and sends `notifications/cancelled`, captured from Muse Code 1.4.0): an
//   answer given after that fetches nothing, and a fetch under way ends.
//
// Nothing is billed: the fetch is the extension's, not Meta's paid search.

import * as z from 'zod/mini'
import type { McpTool } from '../../core/mcp'
import { WEB_FETCH_DESCRIPTION, WEB_FETCH_PARAMETERS } from '../../core/web/webFetchDefinition'
import type { WebFetcher } from '../../core/web/webFetch'
import { approvalHost, checkPageUrl } from '../../core/web/pageUrl'
import {
  IDE_WEB_FETCH_TOOL,
  MCP_ANNOTATIONS_OPEN_WORLD,
  MODEL_TEXT,
  SANDBOX_NETWORK_DENIED,
  type SandboxNetworkMode,
} from '../../shared/constants'
import type { Logger } from '../logger'

export interface IdeWebFetchDeps {
  /** A trusted workspace whose sandbox network setting allows the network. */
  readonly isOffered: () => boolean
  readonly fetchPage: WebFetcher
  /** The modal before every fetch: true only when the user allowed this one. */
  readonly confirm: (url: string, host: string) => Promise<boolean>
  readonly log: Logger
}

const argsSchema = z.object({ url: z.string() })

/** A listener with nothing to do until it is replaced. */
function noop(): void {
  // Replaced before it can run; see unlessCancelled.
}

/**
 * Whether Muse Code is offered the fetch: a trusted workspace, and
 * `museSpark.sandboxNetwork` not set to deny its commands the network.
 */
export function isIdeWebFetchOffered(
  isTrusted: boolean,
  sandboxNetwork: SandboxNetworkMode,
): boolean {
  return isTrusted && sandboxNetwork !== SANDBOX_NETWORK_DENIED
}

/**
 * The modal, asked once per URL at a time: VS Code cannot close a modal a
 * caller stopped waiting for, so a retry of the same URL while it is still
 * open waits for that same answer instead of queueing a second modal.
 */
export function oneQuestionPerUrl(
  isAllowedByUser: (url: string, host: string) => Promise<boolean>,
): (url: string, host: string) => Promise<boolean> {
  const open = new Map<string, Promise<boolean>>()
  const isAllowedOnce = async (url: string, host: string): Promise<boolean> => {
    try {
      return await isAllowedByUser(url, host)
    } finally {
      open.delete(url)
    }
  }
  return async (url, host) => {
    const pending = open.get(url)
    if (pending !== undefined) {
      return await pending
    }
    const asked = isAllowedOnce(url, host)
    open.set(url, asked)
    return await asked
  }
}

/**
 * `start()`'s answer, or a refusal as soon as the caller stops waiting; a
 * caller that already stopped starts nothing (no modal for nobody).
 */
async function unlessCancelled<T>(start: () => Promise<T>, signal: AbortSignal): Promise<T> {
  if (signal.aborted) {
    throw new Error(MODEL_TEXT.webFetchCancelled)
  }
  let onAbort: () => void = noop
  const cancelled = new Promise<never>((_resolve, reject) => {
    onAbort = () => {
      reject(new Error(MODEL_TEXT.webFetchCancelled))
    }
    signal.addEventListener('abort', onAbort, { once: true })
  })
  try {
    return await Promise.race([start(), cancelled])
  } finally {
    signal.removeEventListener('abort', onAbort)
  }
}

async function callWebFetch(
  args: Readonly<Record<string, unknown>>,
  signal: AbortSignal,
  deps: IdeWebFetchDeps,
): Promise<string> {
  const parsed = argsSchema.safeParse(args)
  if (!parsed.success) {
    throw new Error(`invalid arguments: ${z.prettifyError(parsed.error)}`)
  }
  // A URL that would be refused anyway is refused before the modal.
  const checked = checkPageUrl(parsed.data.url)
  if (!checked.ok) {
    throw new Error(checked.failure.reason)
  }
  const host = approvalHost(checked.url)
  // Muse Code may stop waiting while the modal is open (Stop, its own time
  // limit, a restart): its answer then fetches nothing.
  const isAllowed = await unlessCancelled(
    async () => await deps.confirm(checked.url.href, host),
    signal,
  )
  if (!isAllowed) {
    deps.log.info(`Web fetch from ${host} declined in the extension's confirmation`)
    throw new Error(MODEL_TEXT.webFetchDeclined)
  }
  // Trust or the sandbox network may have changed while the modal was open.
  if (!deps.isOffered()) {
    throw new Error(MODEL_TEXT.webFetchNotOffered)
  }
  // Muse Code's stop reaches the fetch too; the fetch's own deadline bounds
  // it. The offer is asked again before each request goes out, and once the
  // page is in: it reaches the model only while web fetch is still offered.
  const result = await deps.fetchPage(checked.url.href, signal, deps.isOffered)
  if (signal.aborted) {
    throw new Error(MODEL_TEXT.webFetchCancelled)
  }
  if (!deps.isOffered()) {
    throw new Error(MODEL_TEXT.webFetchNotOffered)
  }
  if (result.kind === 'failed') {
    throw new Error(result.failure.reason)
  }
  return result.text
}

/** The tool as it stands now: none while the workspace is untrusted or the network is denied. */
export function ideWebFetchTools(deps: IdeWebFetchDeps): readonly McpTool[] {
  if (!deps.isOffered()) {
    return []
  }
  return [
    {
      name: IDE_WEB_FETCH_TOOL,
      description: WEB_FETCH_DESCRIPTION,
      inputSchema: {
        type: 'object',
        properties: WEB_FETCH_PARAMETERS,
        required: ['url'],
        additionalProperties: false,
      },
      annotations: MCP_ANNOTATIONS_OPEN_WORLD,
      call: async (args, signal) => await callWebFetch(args, signal, deps),
    },
  ]
}

src/host/l10n.ts:
// The table for VS Code's display language (PLAN.md D33), installed once at
// activation before anything shows text. English is built in; any other
// language with a table reads `l10n/ui.<locale>.json` from the package and
// checks its shape against English. A language without a table, or a file
// that cannot be read or does not match, leaves the extension in English,
// and the log says why. The same table goes to each webview in its HTML.
// Pure: the file read and the language are injected.

import { tableProblems } from '../shared/l10n/check'
import { EN, type UiText } from '../shared/l10n/en'
import { TABLE_DIRECTORY, tableFileName, tableLocaleFor } from '../shared/l10n/locales'
import { BASE_LOCALE, setUiText } from '../shared/l10n/text'
import type { Logger } from './logger'

/** The installed table and its language, as the webviews receive them. */
export interface UiTable {
  readonly locale: string
  readonly table: UiText
}

export interface UiTableDeps {
  /** `vscode.env.language`: VS Code's display language (`en`, `de`, `zh-cn`, …). */
  readonly language: string
  /** A packaged file's text, by its path segments under the extension root; rejects when unreadable. */
  readonly readExtensionFile: (segments: readonly string[]) => Promise<string>
  readonly log: Logger
  /** The table a display language reads; the shipped list decides unless a test gives its own. */
  readonly tableLocaleFor?: (language: string) => string | undefined
}

// A damaged table can differ in hundreds of keys; the log names the first few.
const PROBLEMS_LOGGED = 5

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/** Whether the parsed file has English's shape; what differs is added to `problems`. */
function isTableShape(value: unknown, locale: string, problems: string[]): value is UiText {
  problems.push(...tableProblems(EN, value, { locale, isStrict: false }))
  return problems.length === 0
}

function problemSummary(problems: readonly string[]): string {
  const shown = problems.slice(0, PROBLEMS_LOGGED).join('; ')
  const more = problems.length - PROBLEMS_LOGGED
  return more > 0 ? `${shown}; and ${String(more)} more` : shown
}

/**
 * Installs the display language's table (`setUiText`) and returns it for the
 * webviews; English when the language has none or its file is unusable.
 */
export async function loadUiTable(deps: UiTableDeps): Promise<UiTable> {
  const english: UiTable = { locale: BASE_LOCALE, table: EN }
  const locale = (deps.tableLocaleFor ?? tableLocaleFor)(deps.language)
  if (locale === undefined) {
    deps.log.info(`Display language ${deps.language}: the panel is in English`)
    return english
  }
  const fileName = tableFileName(locale)
  const file = `${TABLE_DIRECTORY}/${fileName}`
  let parsed: unknown
  try {
    parsed = JSON.parse(await deps.readExtensionFile([TABLE_DIRECTORY, fileName]))
  } catch (error: unknown) {
    deps.log.warn(`${file} could not be read, so the panel stays in English: ${describe(error)}`)
    return english
  }
  const problems: string[] = []
  if (!isTableShape(parsed, locale, problems)) {
    deps.log.warn(
      `${file} does not match the English table, so the panel stays in English: ${problemSummary(problems)}`,
    )
    return english
  }
  setUiText(parsed, locale)
  deps.log.info(`Display language ${deps.language}: the panel is in ${locale} (${file})`)
  return { locale, table: parsed }
}

src/host/lazyBundle.ts:
// Loading a bundle of our own that ships beside dist/extension.js but is
// not part of activation (PLAN.md D6): the Model API backend (M57) and the
// plan reader (M79). Node's own `require`, from wherever this code was
// bundled.

import { createRequire } from 'node:module'
import type { Logger } from './logger'

/** Node's own `require` of an absolute path. */
export function requireFile(file: string): unknown {
  return createRequire(file)(file)
}

/**
 * Forgets a file Node loaded but that is not the bundle, so the next load
 * reads it again: a module that ran without throwing stays in Node's cache,
 * and a file repaired in place would otherwise never be seen (the review of
 * PR #47). One that threw while loading is never cached.
 */
export function forgetFile(file: string): void {
  const nodeRequire = createRequire(file)
  Reflect.deleteProperty(nodeRequire.cache, nodeRequire.resolve(file))
}

export interface LazyBundleLoaderOptions<T> {
  /** The bundle beside the running one (`dist/<name>.js`). */
  readonly bundlePath: string
  readonly log: Logger
  /** How the bundle is loaded: Node's `require` unless a test hands in the module. */
  readonly loadBundle?: ((file: string) => unknown) | undefined
  /**
   * Whether a required module is the bundle. Signatures are taken on trust
   * (PLAN.md §8): entry, loader and package come from one source tree, one
   * `npm run build` and one package.
   */
  readonly isBundle: (value: unknown) => value is T
  /** What the bundle is, for the log. */
  readonly label: string
  /** The words the user reads when it cannot be loaded, read when it fails (the log has the cause). */
  readonly unavailable: () => string
}

/**
 * The bundle, required the first time it is asked for and kept from then on.
 * A missing or corrupt bundle throws `unavailable` and is tried again on the
 * next call.
 */
export function lazyBundleLoader<T>(options: LazyBundleLoaderOptions<T>): () => T {
  const { bundlePath, log, loadBundle = requireFile, isBundle, label, unavailable } = options
  let bundle: T | undefined
  return () => {
    if (bundle !== undefined) {
      return bundle
    }
    let loaded: unknown
    try {
      loaded = loadBundle(bundlePath)
    } catch (error: unknown) {
      log.error(
        `The ${label} ${bundlePath} could not be loaded: ${error instanceof Error ? error.message : String(error)}`,
      )
      throw new Error(unavailable(), { cause: error })
    }
    if (!isBundle(loaded)) {
      log.error(`${bundlePath} does not export the ${label}`)
      if (options.loadBundle === undefined) {
        forgetFile(bundlePath)
      }
      throw new Error(unavailable())
    }
    bundle = loaded
    return bundle
  }
}

src/host/logger.ts:
// Logging adapter over VS Code's LogOutputChannel that redacts secrets before
// anything is written. Every host module logs through this interface, never
// through the channel or `console` directly. The channel is taken by its
// shape, so the modules that log stay free of `vscode` (M61, PLAN.md D60).

import { redactSecrets } from '../core/redact'

export interface Logger {
  /** Shown only when the channel's level is Trace (M39). */
  trace(message: string): void
  info(message: string): void
  warn(message: string): void
  error(message: string): void
}

/** An error as the log wants it: the stack where there is one, else the message. */
export function errorDetail(error: unknown): string {
  return error instanceof Error ? (error.stack ?? error.message) : String(error)
}

/**
 * For a call nobody awaits (`void promise.catch(…)`): its failure goes to the
 * log as "`what` failed", not only to VS Code's Extension Host log (M39).
 */
export function logRejection(log: Logger, what: string): (error: unknown) => void {
  return (error) => {
    log.error(`${what} failed: ${errorDetail(error)}`)
  }
}

/** `channel` is VS Code's `LogOutputChannel`, taken by the four methods it shares with `Logger`. */
export function createLogger(channel: Logger): Logger {
  return {
    trace(message) {
      channel.trace(redactSecrets(message))
    },
    info(message) {
      channel.info(redactSecrets(message))
    },
    warn(message) {
      channel.warn(redactSecrets(message))
    },
    error(message) {
      channel.error(redactSecrets(message))
    },
  }
}

src/host/memoryFeatures.ts:
// The VS Code side of "Memory…" (M49, PLAN.md D41): the picks, the input
// boxes, the modal, the editor and the trash. The flow lives in
// commands/memoryCommands.ts, the notes in core/memory/memoryStore.ts.

import * as vscode from 'vscode'
import type { MemoryStore } from '../core/memory/memoryStore'
import { MUSE_MEMORY_DOCS_URL, UI_TEXT } from '../shared/constants'
import { type MemoryEdit, showMemory } from './commands/memoryCommands'
import type { Logger } from './logger'
import { loggedPopups } from './popups'
import { showPickOne } from './quickPick'

export interface MemoryFeatureDeps {
  readonly store: MemoryStore
  readonly log: Logger
  readonly edit: MemoryEdit
}

export interface MemoryFeatures {
  showMemory(): Promise<void>
}

export function createMemoryFeatures(deps: MemoryFeatureDeps): MemoryFeatures {
  return {
    showMemory: () =>
      showMemory({
        store: deps.store,
        edit: deps.edit,
        pick: showPickOne,
        askName: (validate) =>
          Promise.resolve(
            vscode.window.showInputBox({
              title: UI_TEXT.memoryNamePrompt,
              placeHolder: UI_TEXT.memoryNamePlaceholder,
              ignoreFocusOut: true,
              validateInput: validate,
            }),
          ),
        askDescription: () =>
          Promise.resolve(
            vscode.window.showInputBox({
              title: UI_TEXT.memoryDescriptionPrompt,
              placeHolder: UI_TEXT.memoryDescriptionPlaceholder,
              ignoreFocusOut: true,
            }),
          ),
        confirm: async (message, detail, action) =>
          (await vscode.window.showWarningMessage(message, { modal: true, detail }, action)) ===
          action,
        openFile: async (fsPath) => {
          await vscode.window.showTextDocument(vscode.Uri.file(fsPath), { preview: false })
        },
        trash: async (fsPath, assertCanWrite) => {
          // VS Code's delete has no publication callback: the guard speaks last, right before it.
          // The user's removal is never recorded (M86): a restore leaves it as it is.
          assertCanWrite()
          await vscode.workspace.fs.delete(vscode.Uri.file(fsPath), { useTrash: true })
          deps.log.info(`Memory note moved to the trash: ${fsPath}`)
        },
        openDocs: () => {
          void vscode.env.openExternal(vscode.Uri.parse(MUSE_MEMORY_DOCS_URL))
        },
        showInformation: (message) => {
          void vscode.window.showInformationMessage(message)
        },
        showError: loggedPopups(deps.log).showError,
      }),
  }
}

src/host/mention/mentionQuickPick.ts:
// "Mention file from this project…": a QuickPick whose items are refreshed
// from the mention index as the user types. The QuickPick factory is injected
// so the flow is unit-tested with a fake; `vscode.window.createQuickPick`
// satisfies it directly.

import type * as vscode from 'vscode'
import type { MentionSearch } from '../conversation/conversationController'

export interface MentionPickItem extends vscode.QuickPickItem {
  readonly path: string
}

export type MentionQuickPick = Pick<
  vscode.QuickPick<MentionPickItem>,
  | 'items'
  | 'placeholder'
  | 'matchOnDescription'
  | 'value'
  | 'selectedItems'
  | 'onDidChangeValue'
  | 'onDidAccept'
  | 'onDidHide'
  | 'show'
  | 'hide'
  | 'dispose'
>

export interface MentionQuickPickDeps {
  readonly createQuickPick: () => MentionQuickPick
  readonly mentions: Pick<MentionSearch, 'search'>
  readonly limit: number
  readonly placeholder: string
}

function toItems(paths: readonly { path: string; isFolder: boolean }[]): MentionPickItem[] {
  return paths.map((entry) => ({ label: entry.path, path: entry.path }))
}

/** Resolves with the chosen relative path, or undefined when dismissed. */
export async function pickMentionFile(deps: MentionQuickPickDeps): Promise<string | undefined> {
  const picker = deps.createQuickPick()
  picker.placeholder = deps.placeholder
  // The index already fuzzy-ranked the rows; VS Code's own filter would hide
  // results whose match is spread across path segments.
  picker.matchOnDescription = false
  let latestQuery = ''
  const refresh = async (query: string) => {
    latestQuery = query
    const results = await deps.mentions.search(query, deps.limit)
    if (query === latestQuery) {
      picker.items = toItems(results)
    }
  }
  // Not `Promise.withResolvers`: VS Code 1.99 and 1.100 run Node 20 (PLAN.md M62).
  const settled = new Promise<string | undefined>((resolve) => {
    picker.onDidAccept(() => {
      resolve(picker.selectedItems[0]?.path)
      picker.hide()
    })
    picker.onDidHide(() => {
      resolve(undefined)
      picker.dispose()
    })
  })
  picker.onDidChangeValue((value) => {
    void refresh(value)
  })
  picker.show()
  await refresh('')
  return await settled
}

src/host/mention/workspaceFiles.ts:
// Lists workspace paths for the mention index. With `respectGitIgnore` on the
// list comes from `git ls-files --cached --others --exclude-standard`, which
// applies every .gitignore exactly the way git does; when git is missing or
// the folder is not a repository it falls back to VS Code's file search
// (which honours `files.exclude` but not .gitignore). With the setting off,
// or in Restricted Mode (git would read the untrusted repository's own
// config, PLAN.md D24), only the file search is used. Both list the first
// workspace folder only, the root every mention is relative to (D27).

import { GIT_LS_FILES_ARGS } from '../../shared/constants'
import type { Logger } from '../logger'

export interface WorkspaceFileListerDeps {
  readonly workspaceRoot: string
  readonly respectGitIgnore: () => boolean
  readonly isWorkspaceTrusted: () => boolean
  /** Runs git with `args` in `cwd` and resolves stdout; rejects on any failure. */
  readonly runGit: (args: readonly string[], cwd: string) => Promise<string>
  /** Workspace-relative paths (forward slashes) from `workspace.findFiles`. */
  readonly findFiles: () => Promise<readonly string[]>
  readonly log: Logger
}

export interface RootFileSearch<U> {
  /**
   * VS Code's file search below the first folder only (a `RelativePattern`
   * on it); undefined with no folder open.
   */
  readonly search: (() => PromiseLike<readonly U[]>) | undefined
  /** The path relative to the root; undefined outside it (`rootRelativePath`). */
  readonly relativePath: (uri: U) => string | undefined
}

/**
 * The file search's list: the root's files, relative to it with forward
 * slashes. A second folder's files are neither searched nor listed, so none
 * can pass for a path under the root.
 */
export async function findRootFiles<U>(files: RootFileSearch<U>): Promise<readonly string[]> {
  if (files.search === undefined) {
    return []
  }
  const found = await files.search()
  return found.flatMap((uri) => {
    const relative = files.relativePath(uri)
    return relative === undefined ? [] : [relative]
  })
}

/** Splits NUL-separated output, dropping the empty trailing entry. */
export function parseNulSeparated(output: string): readonly string[] {
  return output.split('\0').filter((entry) => entry !== '')
}

export function createWorkspaceFileLister(
  deps: WorkspaceFileListerDeps,
): () => Promise<readonly string[]> {
  return async () => {
    if (!deps.respectGitIgnore() || !deps.isWorkspaceTrusted()) {
      return await deps.findFiles()
    }
    try {
      const output = await deps.runGit(GIT_LS_FILES_ARGS, deps.workspaceRoot)
      return parseNulSeparated(output)
    } catch (error: unknown) {
      const reason = error instanceof Error ? error.message : String(error)
      deps.log.warn(`git ls-files unavailable (${reason}); .gitignore is not applied to mentions`)
      return await deps.findFiles()
    }
  }
}

src/host/networkPosture.ts:
// The extension's network posture (M56, PLAN.md D43). VS Code extends an
// extension's global `fetch` and `WebSocket` with its proxy support
// (`http.proxy`, the system proxy or a PAC file, proxy authentication,
// `http.noProxy`) and the operating system's certificates, while
// `http.fetchAdditionalSupport`, `http.webSocketAdditionalSupport`,
// `http.proxySupport` and `http.systemCertificates` allow it (read from VS
// Code 1.125.0's `proxyResolver.ts` and 1.139.0's shipped extension host).
// Not every version the manifest accepts does both (M62): `fetch` is routed
// from the 1.99 floor on, `WebSocket` only from 1.112.0, and an editor that
// does not run VS Code's extension host may route neither. So the Model API
// client and the Muse Voice socket use the globals as they stand at each
// call, and the Diagnostics report states whether this editor routes each
// and the settings that decide it, never a proxy's address (it can hold a
// password).

import * as z from 'zod/mini'
import { environmentValue } from '../core/backends/musecode/launch'
import type { HostRouting, NetworkFacts, SupportFacts } from '../core/support/report'
import {
  HTTP_NO_PROXY_SETTING,
  HTTP_POSTURE_SETTINGS,
  HTTP_PROXY_SETTING,
  HTTP_PROXY_SUPPORT_DEFAULT,
  HTTP_PROXY_SUPPORT_MODES,
  NODE_EXTRA_CA_CERTS_VARIABLE,
  PROXY_VARIABLE_SPELLINGS,
  VSCODE_ROUTED_GLOBALS,
} from '../shared/constants'
import type { ProxySettings } from './backend/museCodeBackendManager'
import type { ProcessResult } from './backend/sandboxSetup'

/**
 * The global `fetch` at each call, not at activation: whatever VS Code has
 * installed then (its proxy-aware fetch, or Electron's with
 * `http.electronFetch`) carries the request.
 */
export const liveFetch: typeof fetch = (input, init) => globalThis.fetch(input, init)

/** The one method of `vscode.WorkspaceConfiguration` (the `http` section) this reads. */
export interface HttpSettingsSource {
  get(section: string): unknown
}

/** Where `muse serve` gets its proxy and certificates (MuseCodeBackendManager). */
export interface MuseNetworkPosture {
  proxySource(): NetworkFacts['museProxySource']
  hasCertificateOverride(): boolean
}

const flagSchema = z.boolean()
const textSchema = z.string()
const listSchema = z.array(z.string())

/** Type-check VS Code's `http.proxy` and `http.noProxy` before passing either to Muse Code. */
export function readProxySettings(source: HttpSettingsSource): ProxySettings {
  const proxy = textSchema.safeParse(source.get(HTTP_PROXY_SETTING))
  const noProxy = listSchema.safeParse(source.get(HTTP_NO_PROXY_SETTING))
  return {
    proxy: proxy.success ? proxy.data : '',
    noProxy: noProxy.success ? noProxy.data : [],
  }
}

function isFlagOn(source: HttpSettingsSource, key: string, isOnByDefault: boolean): boolean {
  const parsed = flagSchema.safeParse(source.get(key))
  return parsed.success ? parsed.data : isOnByDefault
}

function isTextSet(source: HttpSettingsSource, key: string): boolean {
  const parsed = textSchema.safeParse(source.get(key))
  return parsed.success && parsed.data !== ''
}

/**
 * Whether the extension host put its proxy-aware `fetch` or `WebSocket` in
 * place (M62), told by the global VS Code's `proxyResolver.ts` sets beside
 * it. A host without the marker is not claimed to route the global.
 */
export function hostRouting(
  globals: object,
  global: keyof typeof VSCODE_ROUTED_GLOBALS,
): HostRouting {
  const { name, marker } = VSCODE_ROUTED_GLOBALS[global]
  const value: unknown = Reflect.get(globals, name)
  if (typeof value !== 'function') {
    return 'absent'
  }
  return Object.hasOwn(globals, marker) ? 'routed' : 'notRouted'
}

/**
 * VS Code's defaults stand for a value it does not report or that is
 * malformed; `globals` is the extension host's `globalThis`.
 */
export function readNetworkFacts(
  http: HttpSettingsSource,
  env: NodeJS.ProcessEnv,
  platform: NodeJS.Platform,
  muse: MuseNetworkPosture,
  globals: object,
): NetworkFacts {
  const isVariableSet = (name: string) => (environmentValue(env, platform, name) ?? '') !== ''
  const proxySupport = z
    .enum(HTTP_PROXY_SUPPORT_MODES)
    .safeParse(http.get(HTTP_POSTURE_SETTINGS.proxySupport))
  const proxy = readProxySettings(http)
  return {
    isProxySet: proxy.proxy !== '',
    proxySupport: proxySupport.success ? proxySupport.data : HTTP_PROXY_SUPPORT_DEFAULT,
    isProxyStrictSsl: isFlagOn(http, HTTP_POSTURE_SETTINGS.proxyStrictSsl, true),
    isProxyAuthorizationSet: isTextSet(http, HTTP_POSTURE_SETTINGS.proxyAuthorization),
    noProxyCount: proxy.noProxy.length,
    isSystemCertificatesOn: isFlagOn(http, HTTP_POSTURE_SETTINGS.systemCertificates, true),
    isFetchSupportOn: isFlagOn(http, HTTP_POSTURE_SETTINGS.fetchAdditionalSupport, true),
    isWebSocketSupportOn: isFlagOn(http, HTTP_POSTURE_SETTINGS.webSocketAdditionalSupport, true),
    fetchRouting: hostRouting(globals, 'fetch'),
    webSocketRouting: hostRouting(globals, 'webSocket'),
    hasEnvironmentProxy: PROXY_VARIABLE_SPELLINGS.some((name) => isVariableSet(name)),
    hasExtraCaCertificates: isVariableSet(NODE_EXTRA_CA_CERTS_VARIABLE),
    museProxySource: muse.proxySource(),
    hasMuseCertificateOverride: muse.hasCertificateOverride(),
  }
}

const CLI_NOT_FOUND = 'not run: the Muse Code CLI was not found'

/**
 * `muse config status` for the report: its output, or why there is none.
 * `run` is undefined when the CLI is not installed.
 */
export async function managedConfiguration(
  run: (() => Promise<ProcessResult>) | undefined,
): Promise<SupportFacts['managedConfiguration']> {
  if (run === undefined) {
    return { ok: false, reason: CLI_NOT_FOUND }
  }
  let result: ProcessResult
  try {
    result = await run()
  } catch {
    return { ok: false, reason: 'could not read status' }
  }
  if (result.exitCode !== 0) {
    // CLI output is untrusted and may contain managed credentials. The
    // report needs its exit code, never stderr or partial stdout.
    return { ok: false, reason: `exit code ${String(result.exitCode)}` }
  }
  return { ok: true, text: result.stdout }
}

src/host/outputDocuments.ts:
// The tool outputs opened as read-only documents (M15), kept so a tab that is
// reopened still reads. At most OUTPUT_DOCUMENTS_KEPT of them, and at most
// OUTPUT_DOCUMENTS_MAX_CHARS together (M39): each can be up to 16 MiB, and
// they live in the extension host's memory. The newest one always stays.

import { OUTPUT_DOCUMENTS_KEPT, OUTPUT_DOCUMENTS_MAX_CHARS } from '../shared/constants'

export class OutputDocumentStore {
  private readonly documents = new Map<string, string>()
  private count = 0

  public constructor(
    private readonly maxCount: number = OUTPUT_DOCUMENTS_KEPT,
    private readonly maxChars: number = OUTPUT_DOCUMENTS_MAX_CHARS,
  ) {}

  /** Keeps `content`, drops the oldest over the limits, and returns its id. */
  public add(content: string): string {
    this.count += 1
    const id = String(this.count)
    this.documents.set(id, content)
    let total = 0
    for (const text of this.documents.values()) {
      total += text.length
    }
    for (const [key, text] of this.documents) {
      const isWithinLimits = this.documents.size <= this.maxCount && total <= this.maxChars
      if (isWithinLimits || key === id) {
        break
      }
      this.documents.delete(key)
      total -= text.length
    }
    return id
  }

  public get(id: string): string | undefined {
    return this.documents.get(id)
  }
}

src/host/paid/paidHost.ts:
// The host side of the paid Model API features (M33–M35, PLAN.md D30): the
// gate over VS Code's settings, the extension's global state and a modal
// confirmation naming the price, the popup before each paid use (M58,
// PLAN.md D48), the window's tally, and the `paidState` message every panel
// renders its badge, toggles and tally from.

import * as vscode from 'vscode'
import * as z from 'zod/mini'
import { PaidUseConsent, type PaidUseAnswer, paidUseQuestion } from '../../core/paid/paidConsent'
import { PaidFeatureGate, PaidUsage, paidStateOf } from '../../core/paid/paidFeatures'
import {
  GLOBAL_STATE_KEYS,
  PAID_FEATURE_SETTINGS,
  PAID_FEATURES,
  type PaidFeature,
  SETTINGS_SECTION,
  SUBAGENT_PRICE_ACCEPTANCE_VERSION,
  UI_TEXT,
  WORKSPACE_STATE_KEYS,
} from '../../shared/constants'
import { fill } from '../../shared/l10n/text'
import {
  autoReviewPrice,
  modelApiPaidTier,
  paidFeatureName,
  paidFeaturePrice,
  type PaidState,
  type PaidUseRequest,
} from '../../shared/paid'
import type { Logger } from '../logger'

// What an earlier version (or a hand edit) stored is validated, never trusted.
const acceptedSchema = z.array(z.enum(PAID_FEATURES))
// Feature → grant generation; keys that are not a paid feature are ignored.
const generationsSchema = z.record(z.string(), z.int().check(z.nonnegative()))

/** A feature's grant generation: 0 until its price acceptance first changes. */
function generationOf(generations: Readonly<Record<string, number>>, feature: PaidFeature): number {
  return generations[feature] ?? 0
}

interface MementoLike {
  get(key: string): unknown
  update(key: string, value: unknown): Thenable<void>
}

export interface PaidFeaturesDeps {
  readonly globalState: MementoLike
  /** Where "Allow always in this workspace" is kept (M58). */
  readonly workspaceState: MementoLike
  /** Whether the feature's setting is on, as the settings reader validated it. */
  readonly isSettingOn: (feature: PaidFeature) => boolean
  /** Whether a Model API key is stored, as last read (M44). */
  readonly isKeyStored: () => boolean
  /** A trusted workspace with a folder open: "always" is offered and kept only there. */
  readonly canRememberPaidUse: () => boolean
  readonly log: Logger
}

export interface PaidFeatures {
  readonly gate: PaidFeatureGate
  readonly consent: PaidUseConsent
  readonly usage: PaidUsage
  readonly state: () => PaidState
  /** Whether a change to the configuration touched a paid feature's setting. */
  readonly affects: (event: vscode.ConfigurationChangeEvent) => boolean
}

/** What the confirmation says the feature does and costs, in the display language. */
function confirmationDetail(feature: PaidFeature): string {
  const details: Readonly<Record<PaidFeature, string>> = {
    webSearch: UI_TEXT.paidConfirmWebSearch,
    imageGeneration: UI_TEXT.paidConfirmImage,
    voice: UI_TEXT.paidConfirmVoice,
    scheduledPrompts: UI_TEXT.paidConfirmScheduled,
    subagents: UI_TEXT.paidConfirmSubagents,
    autoReviewer: UI_TEXT.paidConfirmAutoReviewer,
    bestOfN: UI_TEXT.paidConfirmBestOfN,
  }
  return fill(details[feature], { price: paidFeaturePrice(feature) })
}

async function isTurnOnConfirmed(feature: PaidFeature): Promise<boolean> {
  const accept = UI_TEXT.paidConfirmAccept
  const answer = await vscode.window.showWarningMessage(
    fill(UI_TEXT.paidConfirmTitle, { feature: paidFeatureName(feature) }),
    { modal: true, detail: confirmationDetail(feature) },
    accept,
  )
  return answer === accept
}

/**
 * The popup before a paid use (M58): Allow once, Allow always in this
 * workspace (only where it can be kept), or Deny, which is also what closing
 * the popup answers.
 */
export async function askPaidUse(
  request: PaidUseRequest,
  canRemember: boolean,
): Promise<PaidUseAnswer> {
  // No verified price, nothing to accept (M48, M78): refused before any popup.
  if (
    (request.feature === 'subagents' && modelApiPaidTier(request.task.modelId) === undefined) ||
    (request.feature === 'autoReviewer' && autoReviewPrice(request.modelId) === undefined)
  ) {
    return 'deny'
  }
  if (request.feature === 'bestOfN' && modelApiPaidTier(request.modelId) === undefined) {
    return 'deny'
  }
  if (request.feature === 'bestOfN' && modelApiPaidTier(request.modelId) === undefined) {
    return 'deny'
  }
  const { title, detail } = paidUseQuestion(request)
  const once: vscode.MessageItem = { title: UI_TEXT.allowOnce }
  const always: vscode.MessageItem = { title: UI_TEXT.paidAllowAlways }
  const deny: vscode.MessageItem = { title: UI_TEXT.paidDeny, isCloseAffordance: true }
  const answer = await vscode.window.showWarningMessage(
    title,
    { modal: true, detail },
    ...(canRemember ? [once, always, deny] : [once, deny]),
  )
  if (answer === once) {
    return 'once'
  }
  return answer === always && canRemember ? 'always' : 'deny'
}

export function createPaidFeatures(deps: PaidFeaturesDeps): PaidFeatures {
  const readAccepted = (): ReadonlySet<PaidFeature> => {
    const parsed = acceptedSchema.safeParse(
      deps.globalState.get(GLOBAL_STATE_KEYS.paidConfirmations) ?? [],
    )
    const accepted = new Set(parsed.success ? parsed.data : [])
    if (
      deps.globalState.get(GLOBAL_STATE_KEYS.subagentPriceAcceptance) !==
      SUBAGENT_PRICE_ACCEPTANCE_VERSION
    ) {
      accepted.delete('subagents')
    }
    return accepted
  }
  const readGenerations = (): Readonly<Record<string, number>> => {
    const parsed = generationsSchema.safeParse(
      deps.globalState.get(GLOBAL_STATE_KEYS.paidGrantGenerations) ?? {},
    )
    return parsed.success ? parsed.data : {}
  }
  const gate = new PaidFeatureGate({
    isSettingOn: deps.isSettingOn,
    setSetting: async (feature, isOn) => {
      await vscode.workspace
        .getConfiguration(SETTINGS_SECTION)
        .update(PAID_FEATURE_SETTINGS[feature], isOn, vscode.ConfigurationTarget.Global)
    },
    readAccepted,
    writeAccepted: async (accepted) => {
      // A price accepted or withdrawn voids every "always" given under the
      // old acceptance, in every workspace (M58).
      const previous = readAccepted()
      const generations = { ...readGenerations() }
      for (const feature of PAID_FEATURES) {
        if (previous.has(feature) !== accepted.has(feature)) {
          generations[feature] = generationOf(generations, feature) + 1
        }
      }
      await deps.globalState.update(GLOBAL_STATE_KEYS.paidGrantGenerations, generations)
      await deps.globalState.update(
        GLOBAL_STATE_KEYS.subagentPriceAcceptance,
        accepted.has('subagents') ? SUBAGENT_PRICE_ACCEPTANCE_VERSION : undefined,
      )
      await deps.globalState.update(GLOBAL_STATE_KEYS.paidConfirmations, [...accepted])
    },
    confirm: isTurnOnConfirmed,
    isWindowFocused: () => vscode.window.state.focused,
    log: deps.log,
  })
  const consent = new PaidUseConsent({
    isOn: (feature) => gate.isOn(feature),
    canRemember: deps.canRememberPaidUse,
    readGrants: () => {
      const parsed = generationsSchema.safeParse(
        deps.workspaceState.get(WORKSPACE_STATE_KEYS.paidWorkspaceGrants) ?? {},
      )
      const grants = parsed.success ? parsed.data : {}
      const generations = readGenerations()
      return new Set(
        PAID_FEATURES.filter(
          (feature) =>
            grants[feature] !== undefined && grants[feature] === generationOf(generations, feature),
        ),
      )
    },
    writeGrants: async (grants) => {
      const generations = readGenerations()
      await deps.workspaceState.update(
        WORKSPACE_STATE_KEYS.paidWorkspaceGrants,
        Object.fromEntries(
          [...grants].map((feature) => [feature, generationOf(generations, feature)]),
        ),
      )
    },
    ask: askPaidUse,
    log: deps.log,
  })
  const usage = new PaidUsage(deps.log)
  return {
    gate,
    consent,
    usage,
    state: () => paidStateOf(gate, usage, deps.isKeyStored(), consent.remembered()),
    affects: (event) =>
      PAID_FEATURES.some((feature) =>
        event.affectsConfiguration(`${SETTINGS_SECTION}.${PAID_FEATURE_SETTINGS[feature]}`),
      ),
  }
}

src/host/planFeatures.ts:
// The VS Code side of plans as files (M79, PLAN.md D49): the plan store over
// the file system, and the Plans… picks. The flow lives in
// commands/planCommands.ts, the files in core/plans/planStore.ts, and what a
// plan does in the conversation in conversation/conversationController.ts.

import { rm } from 'node:fs/promises'
import path from 'node:path'
import { lstatIdentity } from '../core/fs/fileIdentity'
import type { PlanMarkdown } from '../core/plans/planDocument'
import { isSamePath } from '../core/paths'
import {
  type PlanDirectoryEntry,
  type PlanIo,
  PlanStore,
  type PlanStoreDeps,
} from '../core/plans/planStore'
import {
  ATOMIC_TEMPORARY_SUFFIX,
  PLAN_FILE_MODE,
  PLAN_STAGE_STALE_MS,
  UI_TEXT,
} from '../shared/constants'
import { entriesByKind } from './backend/memoryIo'
import { readPickedFile } from './backend/toolIo'
import { canonicalPath } from './canonicalPath'
import { choosePlan } from './commands/planCommands'
import type { PickOne } from './commands/pickItem'
import type { PlanFiles } from './conversation/conversationController'
import { createFileExclusively, isNameTaken, isOwnedFile } from './fsAtomic'
import type { Logger } from './logger'

// A save's hidden stage: `.<name>.<uuid><suffix>` (createFileExclusively).
const STAGE_NAME = new RegExp(
  String.raw`^\..+\.[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}${ATOMIC_TEMPORARY_SUFFIX.replaceAll('.', String.raw`\.`)}$`,
  'u',
)
const MISSING = 'ENOENT'

function errorCode(error: unknown): string | undefined {
  return typeof error === 'object' && error !== null && 'code' in error
    ? String(error.code)
    : undefined
}

/**
 * A folder's entries by kind, a link or junction reported as neither file
 * nor folder; none when the folder does not exist. Anything else (a file
 * where the folder should be) rejects, so it is not taken for "no plans".
 */
async function listPlanEntries(absolutePath: string): Promise<readonly PlanDirectoryEntry[]> {
  try {
    return await entriesByKind(absolutePath)
  } catch (error: unknown) {
    if (errorCode(error) === MISSING) {
      return []
    }
    throw error
  }
}

export interface PlanIoOptions {
  readonly log: Logger
  readonly now: () => number
  /** Replace the hard-link call in a deterministic publication test. */
  readonly publish?: (stage: string, target: string) => Promise<void>
  /** The extension's actual-promise checkpoint lease for workspace mutations. */
  readonly edit?: (work: (assertCanWrite?: () => void) => Promise<void>) => Promise<void>
  /** Existing no-clobber stage boundary, injectable for live-owner regressions. */
  readonly staged?: () => Promise<void>
}

/** The plan store's file access: no-clobber creation, bounded checked reads, entries by kind. */
export function createPlanIo(options: PlanIoOptions): PlanIo {
  const { log } = options
  const edit =
    options.edit ??
    (async (work: (assertCanWrite?: () => void) => Promise<void>) => {
      await work()
    })
  return {
    realPath: canonicalPath,
    async createFile(absolutePath, content) {
      try {
        await edit(async (assertCanWrite) => {
          await createFileExclusively(absolutePath, content, {
            mode: PLAN_FILE_MODE,
            // The path is the checked canonical target: its folder is the checked folder.
            expectedDirectory: path.dirname(absolutePath),
            // The stage's name holds the plan's, which is the user's words: not logged (M39).
            warn: (_stage, isPublished, error) => {
              const when = isPublished ? 'after the plan was published' : 'after the save failed'
              log.warn(
                `A plan's hidden stage could not be removed ${when} (${String(errorCode(error))})`,
              )
            },
            ...(options.publish !== undefined && { publish: options.publish }),
            ...(options.staged !== undefined && { staged: options.staged }),
            ...(assertCanWrite !== undefined && { assertCanWrite }),
          })
        })
        return true
      } catch (error: unknown) {
        if (isNameTaken(error)) {
          return false
        }
        throw error
      }
    },
    // A plan is text: a file that starts like a PDF gets no larger limit.
    readFile: (absolutePath, maxBytes, expectedCanonicalPath) =>
      readPickedFile(absolutePath, maxBytes, expectedCanonicalPath, maxBytes),
    listEntries: listPlanEntries,
    async removeStaleStages(absolutePath) {
      await edit(async (assertCanWrite) => {
        const entries = await listPlanEntries(absolutePath)
        let removed = 0
        for (const entry of entries) {
          if (entry.kind !== 'file' || !STAGE_NAME.test(entry.name)) {
            continue
          }
          const stage = path.join(absolutePath, entry.name)
          try {
            const stats = await lstatIdentity(stage)
            if (stats.isFile() && options.now() - Number(stats.mtimeMs) > PLAN_STAGE_STALE_MS) {
              if (
                !isSamePath(await canonicalPath(stage), stage, process.platform) ||
                !(await isOwnedFile(stage, stats))
              ) {
                continue
              }
              assertCanWrite?.()
              await rm(stage, { force: true })
              removed += 1
            }
          } catch (error: unknown) {
            log.warn(`A stale plan stage could not be removed (${String(errorCode(error))})`)
          }
        }
        if (removed > 0) {
          log.info(`Removed ${String(removed)} stale plan stage(s)`)
        }
      })
    },
  }
}

export interface PlanFeatureDeps {
  readonly workspaceRoot: string
  readonly platform: NodeJS.Platform
  /** `createPlanIo` over the file system. */
  readonly io: PlanIo
  readonly pick: PickOne
  /** A modal; true when the user chose `action`. */
  readonly confirm: (message: string, detail: string, action: string) => Promise<boolean>
  /** The plan reader, dist/planMarkdown.js on first use (`planMarkdownLoader`). */
  readonly markdown: () => PlanMarkdown
  readonly beginEdit?: PlanStoreDeps['beginEdit']
  readonly captureOwner?: PlanFiles['captureOwner']
}

export function createPlanFiles(deps: PlanFeatureDeps): PlanFiles {
  const store = new PlanStore({
    workspaceRoot: deps.workspaceRoot,
    platform: deps.platform,
    io: deps.io,
    markdown: deps.markdown,
    ...(deps.beginEdit !== undefined && { beginEdit: deps.beginEdit }),
  })
  return {
    ...(deps.captureOwner !== undefined && { captureOwner: deps.captureOwner }),
    markdown: deps.markdown,
    find: (content) => store.find(content),
    save: (content, ownerRecorder) => store.save(content, ownerRecorder),
    has: (fileName) => store.has(fileName),
    read: (fileName) => store.read(fileName),
    list: () => store.list(),
    confirmSave: () =>
      deps.confirm(UI_TEXT.planSaveConfirm, UI_TEXT.planSaveConfirmDetail, UI_TEXT.savePlan),
    choose: (plans) => choosePlan(plans, deps.pick),
  }
}

src/host/planMarkdownBundle.ts:
// The plan reader as the activation bundle sees it (M79, PLAN.md D6):
// dist/planMarkdown.js, built from planMarkdownEntry.ts and required on the
// first plan action. Only a type comes from core/plans/planMarkdown's side
// here: a value imported from there would carry the parser back into
// dist/extension.js, which the bundle-split gate refuses.
//
// There is no fallback without it: the reader is what says whether a plan
// holds raw HTML and what the model is sent, so a plan action that cannot load it
// is refused with the reason, and the next action tries again.

import type { PlanMarkdown } from '../core/plans/planDocument'
import { UI_TEXT } from '../shared/constants'
import { forgetFile, requireFile } from './lazyBundle'
import type { Logger } from './logger'

const READER_FUNCTIONS = ['topHeading', 'listItems', 'hasRawHtml', 'briefText'] as const

/** The bundle's one export. */
interface PlanMarkdownBundle {
  readonly planMarkdown: PlanMarkdown
}

/**
 * Whether a required module is the bundle: its reader has the three
 * functions. Their signatures are taken on trust (PLAN.md §8): both bundles
 * come from one source tree, one `npm run build` and one package.
 */
export function isPlanMarkdownBundle(value: unknown): value is PlanMarkdownBundle {
  if (typeof value !== 'object' || value === null || !('planMarkdown' in value)) {
    return false
  }
  const { planMarkdown } = value
  return (
    typeof planMarkdown === 'object' &&
    planMarkdown !== null &&
    READER_FUNCTIONS.every((name) => typeof Reflect.get(planMarkdown, name) === 'function')
  )
}

export interface PlanMarkdownLoaderDeps {
  /** dist/planMarkdown.js beside the running bundle. */
  readonly bundlePath: string
  readonly log: Logger
  /** How the bundle is loaded: Node's `require` unless a test hands in the module. */
  readonly loadBundle?: ((file: string) => unknown) | undefined
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/**
 * The reader, required the first time it is asked for and kept from then
 * on. A missing or corrupt bundle throws `planMarkdownUnavailable` (the log
 * has the cause) and is tried again on the next call.
 */
export function planMarkdownLoader(deps: PlanMarkdownLoaderDeps): () => PlanMarkdown {
  let reader: PlanMarkdown | undefined
  return () => {
    if (reader !== undefined) {
      return reader
    }
    const { bundlePath, loadBundle = requireFile } = deps
    let loaded: unknown
    try {
      loaded = loadBundle(bundlePath)
    } catch (error: unknown) {
      deps.log.error(`The plan reader ${bundlePath} could not be loaded: ${describe(error)}`)
      throw new Error(UI_TEXT.planMarkdownUnavailable, { cause: error })
    }
    if (!isPlanMarkdownBundle(loaded)) {
      deps.log.error(`${bundlePath} does not export the plan reader`)
      if (deps.loadBundle === undefined) {
        forgetFile(bundlePath)
      }
      throw new Error(UI_TEXT.planMarkdownUnavailable)
    }
    reader = loaded.planMarkdown
    return reader
  }
}

