// The single-choice quick pick behind the host's lists (M31's MCP servers and
// hooks, M49's memory): each row filtered by its label, description and
// detail, the pick answered with the chosen row's id.

import * as vscode from 'vscode'
import type { PickOne } from './commands/pickItem'

export const showPickOne: PickOne = async (items, title, placeholder) => {
  const choice = await vscode.window.showQuickPick(
    items.map((item) => ({ ...item })),
    { title, placeHolder: placeholder, matchOnDescription: true, matchOnDetail: true },
  )
  return choice?.id
}

src/host/review/museCodeReviewerBundle.t:
// The Auto reviewer on Muse Code as the window sees it (M90, PLAN.md D6,
// D69): dist/museCodeReviewer.js, built from museCodeReviewerEntry.ts and
// required on the first review. Only types come from the reviewer's side
// here: a value imported from there would carry it, and M78's reviewer core
// (which otherwise loads only with the Model API backend), back into
// dist/extension.js, which the bundle-split gate refuses.

import { failureForLog } from '../../core/backends/musecode/logText'
import { UI_TEXT } from '../../shared/constants'
import { uiLocale } from '../../shared/l10n/text'
import { lazyBundleLoader } from '../lazyBundle'
import type { Logger } from '../logger'
import type { MuseCodeReviewer } from './museCodeReviewer'
import type * as ReviewerEntry from './museCodeReviewerEntry'

/** The bundle's one export. */
export interface MuseCodeReviewerBundle {
  readonly createMuseCodeReviewer: typeof ReviewerEntry.createMuseCodeReviewer
}

/** Whether a required module exports the reviewer's factory. */
export function isMuseCodeReviewerBundle(value: unknown): value is MuseCodeReviewerBundle {
  return (
    typeof value === 'object' &&
    value !== null &&
    'createMuseCodeReviewer' in value &&
    typeof value.createMuseCodeReviewer === 'function'
  )
}

/** What a conversation asks of the window's reviewer. */
export interface MuseCodeReviewerPort {
  /** `museSpark.museCodeAutoReviewer`, read for each approval. */
  readonly isOn: () => boolean
  /**
   * The window's reviewer, its bundle required on the first call; throws
   * when the bundle cannot be loaded (the log has why).
   */
  readonly reviewer: () => MuseCodeReviewer
  /** Whether a session is one of the reviewer's side sessions: no History lists it. */
  readonly isSideSession: (sessionId: string) => boolean
  readonly dispose: () => void
}

export interface MuseCodeReviewerPortDeps {
  /** dist/museCodeReviewer.js beside the running bundle. */
  readonly bundlePath: string
  /** The empty folder the side session runs in (MUSE_CODE_REVIEWER_DIR). */
  readonly root: string
  readonly isOn: () => boolean
  readonly log: Logger
  /** How the bundle is loaded: Node's `require` unless a test hands in the module. */
  readonly loadBundle?: ((file: string) => unknown) | undefined
}

/** The window's reviewer port: the bundle and the reviewer, made on first use. */
export function museCodeReviewerPort(deps: MuseCodeReviewerPortDeps): MuseCodeReviewerPort {
  const load = lazyBundleLoader({
    bundlePath: deps.bundlePath,
    log: deps.log,
    loadBundle: deps.loadBundle,
    isBundle: isMuseCodeReviewerBundle,
    label: 'Auto reviewer bundle',
    unavailable: () => UI_TEXT.autoReviewerFailed,
  })
  const sideSessionIds = new Set<string>()
  let reviewer: MuseCodeReviewer | undefined
  return {
    isOn: deps.isOn,
    reviewer: () => {
      reviewer ??= load().createMuseCodeReviewer(
        {
          root: deps.root,
          log: deps.log,
          onSideSession: (sessionId) => {
            sideSessionIds.add(sessionId)
          },
          describeFailure: failureForLog,
        },
        UI_TEXT,
        uiLocale(),
      )
      return reviewer
    },
    isSideSession: (sessionId) => sideSessionIds.has(sessionId),
    dispose: () => {
      reviewer?.dispose()
    },
  }
}

src/host/review/reviewBundle.ts:
// The review as the activation bundle sees it (M70, PLAN.md D6):
// dist/review.js, built from reviewEntry.ts and required the first time a
// review starts. Only types come from core/review/** and reviewCollector here:
// a value imported from there would carry the review back into
// dist/extension.js, which the bundle-split gate (scripts/check-bundle-split.mjs)
// refuses.
//
// There is no fallback without it: a review that cannot load its bundle is
// refused with the reason, the log has the cause, and the next review tries
// again.

import type { PlanModeHold, PlanModeHoldDeps } from '../../core/review/planModeHold'
import type { ReviewTurnInput } from '../../core/review/reviewPrompt'
import { UI_TEXT } from '../../shared/constants'
import type { UiText } from '../../shared/l10n/en'
import { uiLocale } from '../../shared/l10n/text'
import type { EditReviewActions, EditReviewDeps } from '../editor/editReview'
import { forgetFile, requireFile } from '../lazyBundle'
import type { Logger } from '../logger'
import type { GitReviewRequest, ReviewCollection, ReviewCollectorDeps } from './reviewCollector'

/** What a `/review` uses of the bundle: git's material, the turn's text, the mode hold. */
export interface ReviewFeatures {
  /** The request's material from git; asks for a base or a commit the request leaves out. */
  readonly collect: (
    request: GitReviewRequest,
    isStillAllowed: () => boolean,
  ) => Promise<ReviewCollection>
  /** The review turn's text, the material between markers that call it untrusted. */
  readonly turnText: (input: ReviewTurnInput) => string
  /** Fresh random text for those markers. */
  readonly newMarker: () => string
  /** The hold that keeps a Muse Code review in Plan mode and puts the user's mode back. */
  readonly createHold: (deps: PlanModeHoldDeps) => PlanModeHold
  /**
   * Edit review (M5) and the review pane's hunks (M70): they share one read,
   * rebuild and write lane per file, so one instance serves both.
   */
  readonly editReview: EditReviewActions & {
    /** The original text of a `muse-edit:` document; undefined before any diff was opened. */
    readonly provide: (uriPath: string) => string | undefined
  }
}

/** What the conversation uses of the review turn itself: everything but edit review. */
export type ReviewTurnFeatures = Omit<ReviewFeatures, 'editReview'>

/**
 * What the bundle builds its parts from: values and functions of the
 * activation bundle, nothing compared by identity across the two (M57's audit).
 */
export interface ReviewBundleDeps {
  /** The installed table and its language (PLAN.md D33); installed before the factory builds. */
  readonly uiText: UiText
  readonly uiLocale: string
  readonly collector: ReviewCollectorDeps
  readonly editReview: EditReviewDeps
}

/** The bundle's one export. */
interface ReviewBundle {
  readonly createReviewFeatures: (deps: ReviewBundleDeps) => ReviewFeatures
}

/**
 * Whether a required module is the bundle: its factory is a function. The
 * factory's signature is taken on trust (PLAN.md §8): both bundles come from
 * one source tree, one `npm run build` and one package.
 */
export function isReviewBundle(value: unknown): value is ReviewBundle {
  return (
    typeof value === 'object' &&
    value !== null &&
    'createReviewFeatures' in value &&
    typeof value.createReviewFeatures === 'function'
  )
}

export interface LazyReviewDeps {
  /** dist/review.js beside the running bundle. */
  readonly bundlePath: string
  readonly log: Logger
  /** Undefined without a folder: there is no repository to read. */
  readonly workspaceRoot: string | undefined
  readonly runGit: ReviewCollectorDeps['runGit']
  readonly pickOne: ReviewCollectorDeps['pickOne']
  /** Edit review's ports: the file reads, the checkpointed writes and the diff editor. */
  readonly editReview: EditReviewDeps
  /** How the bundle is loaded: Node's `require` unless a test hands in the module. */
  readonly loadBundle?: ((file: string) => unknown) | undefined
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/**
 * The review's parts, the bundle required the first time any is used and
 * kept from then on. A missing or corrupt bundle throws `reviewUnavailable`
 * and is tried again on the next use.
 */
export function lazyReview(deps: LazyReviewDeps): ReviewFeatures {
  let features: ReviewFeatures | undefined
  const loaded = (): ReviewFeatures => {
    if (features !== undefined) {
      return features
    }
    const { bundlePath, workspaceRoot, loadBundle = requireFile } = deps
    let bundle: unknown
    try {
      bundle = loadBundle(bundlePath)
    } catch (error: unknown) {
      deps.log.error(`The review ${bundlePath} could not be loaded: ${describe(error)}`)
      throw new Error(UI_TEXT.reviewUnavailable, { cause: error })
    }
    if (!isReviewBundle(bundle)) {
      deps.log.error(`${bundlePath} does not export the review`)
      if (deps.loadBundle === undefined) {
        forgetFile(bundlePath)
      }
      throw new Error(UI_TEXT.reviewUnavailable)
    }
    features = bundle.createReviewFeatures({
      uiText: UI_TEXT,
      uiLocale: uiLocale(),
      collector: { workspaceRoot: workspaceRoot ?? '', runGit: deps.runGit, pickOne: deps.pickOne },
      editReview: deps.editReview,
    })
    return features
  }
  return {
    // Without a folder there is no repository; the controller refuses
    // before it asks (no workspace), so this only answers honestly.
    collect: async (request, isStillAllowed) =>
      deps.workspaceRoot === undefined
        ? { kind: 'refused', refusal: 'notRepository' }
        : await loaded().collect(request, isStillAllowed),
    turnText: (input) => loaded().turnText(input),
    newMarker: () => loaded().newMarker(),
    createHold: (holdDeps) => loaded().createHold(holdDeps),
    editReview: {
      openDiff: async (itemId, patchJson) => await loaded().editReview.openDiff(itemId, patchJson),
      revert: async (itemId, patchJson) => await loaded().editReview.revert(itemId, patchJson),
      describe: async (patchJson) => await loaded().editReview.describe(patchJson),
      revertHunk: async (itemId, patchJson, fileIndex, hunkIndex) =>
        await loaded().editReview.revertHunk(itemId, patchJson, fileIndex, hunkIndex),
      // Nothing to serve before the first diff opened the bundle.
      provide: (uriPath) => features?.editReview.provide(uriPath),
    },
  }
}

src/host/settings.ts:
// Reads `museSpark.*` settings with runtime validation. VS Code already
// validates against the manifest schema, but settings.json can hold anything,
// so every value is parsed; an invalid value is logged and replaced by the
// documented default so one bad key cannot take the whole panel down.

import * as z from 'zod/mini'
import { checkCommandsSchema } from '../core/verify/checkCommands'
import {
  BACKEND_MODES,
  type BackendMode,
  type CheckCommandSetting,
  type EnvironmentVariable,
  PROMPT_CACHE_RETENTIONS,
  type PromptCacheRetention,
  SANDBOX_NETWORK_MODES,
  type SandboxNetworkMode,
  SETTING_DEFAULTS,
  SETTINGS_SECTION,
  SHELL_SANDBOX_MODES,
  type ShellSandboxMode,
} from '../shared/constants'
import type { PermissionSettings } from '../core/permissionSettings'
import { type SettingsSnapshot, settingsSnapshotShape } from '../shared/protocol'
import type { Logger } from './logger'

export interface ExtensionSettings extends SettingsSnapshot {
  /** Absolute path to the `muse` executable; empty means "discover". */
  readonly museBinaryPath: string
  readonly environmentVariables: readonly EnvironmentVariable[]
  /** Shell sandbox posture for `muse serve` (PLAN.md D12). */
  readonly shellSandbox: ShellSandboxMode
  /** Which backend hosts conversations (PLAN.md D1, M7). */
  readonly backend: BackendMode
  /** Ctrl+N for a new conversation (read by the keybinding, kept here for the schema). */
  readonly enableNewConversationShortcut: boolean
  /** Days an idle Model API conversation is kept; 0 keeps it (PLAN.md D26). */
  readonly cleanupPeriodDays: number
  /** The paid Model API features (M33–M35, PLAN.md D30): on only with the price accepted too. */
  readonly modelApiWebSearch: boolean
  readonly modelApiImageGeneration: boolean
  readonly modelApiVoice: boolean
  /** The shell sandbox's network for `muse serve` (M56, PLAN.md D43). */
  readonly sandboxNetwork: SandboxNetworkMode
  /** How long Meta is asked to keep the Model API's cached prompt prefix (M56). */
  readonly modelApiPromptCacheRetention: PromptCacheRetention
  readonly modelApiScheduledPrompts: boolean
  readonly modelApiSubagents: boolean
  /** Best-of-N parallel attempts (M77, PLAN.md D49): on only with the price accepted too. */
  readonly modelApiBestOfN: boolean
  /** Explicit machine opt-in for external hook commands (M51). */
  readonly modelApiHooks: boolean
  /**
   * M78 (PLAN.md D49): each kept whole here; the Model API bundle parses
   * every rule and profile and reports what it refuses (permissionPolicy.ts).
   */
  readonly modelApiCommandRules: readonly unknown[]
  readonly modelApiPermissionProfiles: Readonly<Record<string, unknown>>
  readonly modelApiPermissionProfile: unknown
  readonly modelApiRepositoryRules: unknown
  /** The paid Auto reviewer (M78): on only with its price accepted too. */
  readonly modelApiAutoReviewer: boolean
  /** The verify loop (M68, PLAN.md D49): diagnostics after edits, check commands, format on edit. */
  readonly diagnosticsAfterEdits: boolean
  readonly checkCommands: readonly CheckCommandSetting[]
  readonly formatOnEdit: boolean

  /** The repo map in the Model API's system prompt (M67). */
  readonly modelApiRepoMap: boolean
  /** Observation packing on the Model API backend (M73): a conversation reads it when it starts. */
  readonly modelApiObservationPacking: boolean
  /** A checkpoint of the workspace's files at each turn boundary (M72). */
  readonly turnCheckpoints: boolean
  /** The skills that ship with the extension (M89, PLAN.md D68). */
  readonly bundledSkills: boolean
  /** Notify when a turn needs attention while the window is unfocused (M82). */
  readonly notifyOnBackgroundTurn: boolean
  /** Tokens and the dollar estimate under each Model API reply (M82). */
  readonly modelApiReplyUsage: boolean
  /** Session budget cap in USD for Model API requests; 0 is no cap (M82). */
  readonly modelApiSessionBudgetUsd: number
}

/**
 * The one method this module needs from `vscode.WorkspaceConfiguration`,
 * which satisfies it structurally. Keeping the dependency this narrow makes
 * the reader trivially fakeable in unit tests.
 */
export interface SettingsSource {
  get(section: string): unknown
}

const environmentVariableSchema = z.object({ name: z.string(), value: z.string() })

// The webview-visible settings share their schemas with the wire protocol;
// only the host-only keys are declared here.
const settingSchemas = {
  ...settingsSnapshotShape,
  museBinaryPath: z.string(),
  environmentVariables: z.array(environmentVariableSchema),
  shellSandbox: z.enum(SHELL_SANDBOX_MODES),
  backend: z.enum(BACKEND_MODES),
  enableNewConversationShortcut: z.boolean(),
  cleanupPeriodDays: z.int().check(z.nonnegative()),
  modelApiWebSearch: z.boolean(),
  modelApiImageGeneration: z.boolean(),
  modelApiVoice: z.boolean(),
  sandboxNetwork: z.enum(SANDBOX_NETWORK_MODES),
  modelApiPromptCacheRetention: z.enum(PROMPT_CACHE_RETENTIONS),
  modelApiScheduledPrompts: z.boolean(),
  modelApiSubagents: z.boolean(),
  modelApiBestOfN: z.boolean(),
  modelApiHooks: z.boolean(),
  modelApiCommandRules: z.array(z.unknown()),
  modelApiPermissionProfiles: z.record(z.string(), z.unknown()),
  modelApiPermissionProfile: z.unknown(),
  modelApiRepositoryRules: z.unknown(),
  modelApiAutoReviewer: z.boolean(),
  diagnosticsAfterEdits: z.boolean(),
  checkCommands: checkCommandsSchema,
  formatOnEdit: z.boolean(),

  modelApiRepoMap: z.boolean(),
  modelApiObservationPacking: z.boolean(),
  turnCheckpoints: z.boolean(),
  bundledSkills: z.boolean(),
  notifyOnBackgroundTurn: z.boolean(),
  modelApiReplyUsage: z.boolean(),
  modelApiSessionBudgetUsd: z.number().check(z.nonnegative()),
} as const

type SettingKey = keyof typeof settingSchemas

// An invalid value is reported once per logger, not on every read: the
// settings are read about seven times for each message sent (M39).
const reported = new WeakMap<Logger, Set<string>>()

function warnOnce(log: Logger, key: string, text: string): void {
  const seen = reported.get(log) ?? new Set<string>()
  reported.set(log, seen)
  if (seen.has(key)) {
    return
  }
  seen.add(key)
  log.warn(text)
}

function readSetting<K extends SettingKey>(
  config: SettingsSource,
  key: K,
  log: Logger,
): ExtensionSettings[K] {
  const raw = config.get(key)
  const fallback = SETTING_DEFAULTS[key] as ExtensionSettings[K]
  if (raw === undefined) {
    return fallback
  }
  const result = settingSchemas[key].safeParse(raw)
  if (result.success) {
    return result.data as ExtensionSettings[K]
  }
  warnOnce(
    log,
    `${key}=${JSON.stringify(raw)}`,
    `Setting ${SETTINGS_SECTION}.${key} is invalid and its default is in effect: ${z.prettifyError(result.error)}`,
  )
  return fallback
}

export function readSettings(config: SettingsSource, log: Logger): ExtensionSettings {
  return {
    preferredLocation: readSetting(config, 'preferredLocation', log),
    initialPermissionMode: readSetting(config, 'initialPermissionMode', log),
    autosave: readSetting(config, 'autosave', log),
    attachOpenFile: readSetting(config, 'attachOpenFile', log),
    useCtrlEnterToSend: readSetting(config, 'useCtrlEnterToSend', log),
    hideOnboarding: readSetting(config, 'hideOnboarding', log),
    focusView: readSetting(config, 'focusView', log),
    respectGitIgnore: readSetting(config, 'respectGitIgnore', log),
    confidentialWorkspace: readSetting(config, 'confidentialWorkspace', log),
    allowDangerouslySkipPermissions: readSetting(config, 'allowDangerouslySkipPermissions', log),
    archiveInactiveSessions: readSetting(config, 'archiveInactiveSessions', log),
    museBinaryPath: readSetting(config, 'museBinaryPath', log),
    environmentVariables: readSetting(config, 'environmentVariables', log),
    shellSandbox: readSetting(config, 'shellSandbox', log),
    backend: readSetting(config, 'backend', log),
    enableNewConversationShortcut: readSetting(config, 'enableNewConversationShortcut', log),
    cleanupPeriodDays: readSetting(config, 'cleanupPeriodDays', log),
    modelApiWebSearch: readSetting(config, 'modelApiWebSearch', log),
    modelApiImageGeneration: readSetting(config, 'modelApiImageGeneration', log),
    modelApiVoice: readSetting(config, 'modelApiVoice', log),
    sandboxNetwork: readSetting(config, 'sandboxNetwork', log),
    modelApiPromptCacheRetention: readSetting(config, 'modelApiPromptCacheRetention', log),
    modelApiScheduledPrompts: readSetting(config, 'modelApiScheduledPrompts', log),
    modelApiSubagents: readSetting(config, 'modelApiSubagents', log),
    modelApiBestOfN: readSetting(config, 'modelApiBestOfN', log),
    modelApiHooks: readSetting(config, 'modelApiHooks', log),
    diagnosticsAfterEdits: readSetting(config, 'diagnosticsAfterEdits', log),
    checkCommands: readSetting(config, 'checkCommands', log),
    formatOnEdit: readSetting(config, 'formatOnEdit', log),
    modelApiRepoMap: readSetting(config, 'modelApiRepoMap', log),
    modelApiObservationPacking: readSetting(config, 'modelApiObservationPacking', log),
    turnCheckpoints: readSetting(config, 'turnCheckpoints', log),
    bundledSkills: readSetting(config, 'bundledSkills', log),
    notifyOnBackgroundTurn: readSetting(config, 'notifyOnBackgroundTurn', log),
    modelApiReplyUsage: readSetting(config, 'modelApiReplyUsage', log),
    modelApiSessionBudgetUsd: readSetting(config, 'modelApiSessionBudgetUsd', log),
    modelApiCommandRules: readSetting(config, 'modelApiCommandRules', log),
    modelApiPermissionProfiles: readSetting(config, 'modelApiPermissionProfiles', log),
    modelApiPermissionProfile: readSetting(config, 'modelApiPermissionProfile', log),
    modelApiRepositoryRules: readSetting(config, 'modelApiRepositoryRules', log),
    modelApiAutoReviewer: readSetting(config, 'modelApiAutoReviewer', log),
    museCodeAutoReviewer: readSetting(config, 'museCodeAutoReviewer', log),
  }
}

/** The permission settings as the Model API backend reads them at each call (M78). */
export function permissionSettingsOf(settings: ExtensionSettings): PermissionSettings {
  return {
    commandRules: settings.modelApiCommandRules,
    profiles: settings.modelApiPermissionProfiles,
    profile: settings.modelApiPermissionProfile,
    repositoryRules: settings.modelApiRepositoryRules,
  }
}

/** The subset of settings the webview receives. */
export function toSettingsSnapshot(settings: ExtensionSettings): SettingsSnapshot {
  return {
    preferredLocation: settings.preferredLocation,
    initialPermissionMode: settings.initialPermissionMode,
    autosave: settings.autosave,
    attachOpenFile: settings.attachOpenFile,
    useCtrlEnterToSend: settings.useCtrlEnterToSend,
    hideOnboarding: settings.hideOnboarding,
    focusView: settings.focusView,
    respectGitIgnore: settings.respectGitIgnore,
    confidentialWorkspace: settings.confidentialWorkspace,
    allowDangerouslySkipPermissions: settings.allowDangerouslySkipPermissions,
    archiveInactiveSessions: settings.archiveInactiveSessions,
    modelApiReplyUsage: settings.modelApiReplyUsage,
    museCodeAutoReviewer: settings.museCodeAutoReviewer,
  }
}

src/host/skills/bundledSkills.ts:
// The bundled skills for Muse Code as the activation bundle sees them (M89,
// PLAN.md D6, D68): the installer's bundle, dist/bundledSkills.js, required
// the first time it is needed (only types come from its side here); the
// panel's one-time offer; and the two commands, which say what the installer
// did in the user's language and then offer the restart a skill change needs
// (a running `muse serve` keeps the skills it started with, as for Manage
// Skills). Every VS Code interaction is injected.

import { UI_TEXT } from '../../shared/constants'
import { fill, plural } from '../../shared/l10n/text'
import type { NoticeAction } from '../../shared/protocol'
import { lazyBundleLoader } from '../lazyBundle'
import type { Logger } from '../logger'
import type {
  BundledSkillsFailure,
  BundledSkillsInstallDeps,
  BundledSkillsInstallResult,
  BundledSkillsPaths,
  BundledSkillsRemoveResult,
  BundledSkillsStatus,
} from './bundledSkillsInstall'

/** The installer's three entries, shipped and loaded together. */
export interface BundledSkillsBundle {
  readonly bundledSkillsStatus: (paths: BundledSkillsPaths) => Promise<BundledSkillsStatus>
  readonly installBundledSkills: (
    deps: BundledSkillsInstallDeps,
  ) => Promise<BundledSkillsInstallResult>
  readonly removeBundledSkills: (paths: BundledSkillsPaths) => Promise<BundledSkillsRemoveResult>
}

const BUNDLE_FUNCTIONS = ['bundledSkillsStatus', 'installBundledSkills', 'removeBundledSkills']

/** Whether a required module exports the three entries (their signatures taken on trust, PLAN.md §8). */
export function isBundledSkillsBundle(value: unknown): value is BundledSkillsBundle {
  return (
    typeof value === 'object' &&
    value !== null &&
    BUNDLE_FUNCTIONS.every((name) => typeof Reflect.get(value, name) === 'function')
  )
}

export interface BundledSkillsLoaderDeps {
  /** dist/bundledSkills.js beside the running bundle. */
  readonly bundlePath: string
  readonly log: Logger
  /** How the bundle is loaded: Node's `require` unless a test hands in the module. */
  readonly loadBundle?: ((file: string) => unknown) | undefined
}

/** The installer, required the first time it is asked for and kept from then on. */
export function bundledSkillsLoader(deps: BundledSkillsLoaderDeps): () => BundledSkillsBundle {
  return lazyBundleLoader({
    ...deps,
    isBundle: isBundledSkillsBundle,
    label: 'bundled skills installer',
    unavailable: () => UI_TEXT.bundledSkillsUnavailable,
  })
}

/** The keys of the two answers the offer remembers (GLOBAL_STATE_KEYS). */
export interface BundledSkillsOfferKeys {
  readonly installDeclined: string
  readonly updateDeclined: string
}

export interface BundledSkillsOfferDeps {
  /** `museSpark.bundledSkills`: off, nothing is offered. */
  readonly isEnabled: () => boolean
  /** The extension's `globalState`: Not now outlives the window. */
  readonly state: {
    get(key: string): unknown
    update(key: string, value: unknown): PromiseLike<void>
  }
  readonly keys: BundledSkillsOfferKeys
  /** The vendored release against the copy in Muse Code's config home. */
  readonly status: () => Promise<BundledSkillsStatus>
}

/** A panel notice and the ways on it offers (D26's notice actions). */
export interface BundledSkillsNotice {
  readonly text: string
  readonly actions: readonly NoticeAction[]
}

export interface BundledSkillsOffer {
  /**
   * The notice for a Muse Code conversation that just started, at most once
   * per window: the install while there is no copy and Not now was never
   * said, the update while the copy's release is not the vendored one and
   * its Not now named another release.
   */
  next(): Promise<BundledSkillsNotice | undefined>
  /** Not now on the notice shown: remembered for the install, or for this release's update. */
  decline(): Promise<void>
}

const LIST_SEPARATOR = ', '
const NONE = '—'

function listed(ids: readonly string[]): string {
  return ids.length === 0 ? NONE : ids.join(LIST_SEPARATOR)
}

export function createBundledSkillsOffer(deps: BundledSkillsOfferDeps): BundledSkillsOffer {
  let isClaimed = false
  let shown:
    { readonly kind: 'install' } | { readonly kind: 'update'; readonly tag: string } | undefined
  const noticeFor = (status: BundledSkillsStatus): BundledSkillsNotice | undefined => {
    if (status.kind === 'notInstalled' && deps.state.get(deps.keys.installDeclined) !== true) {
      shown = { kind: 'install' }
      return {
        text: fill(UI_TEXT.bundledSkillsOffer, { skills: listed(status.skillIds) }),
        actions: ['installBundledSkills', 'declineBundledSkills'],
      }
    }
    if (
      status.kind === 'installed' &&
      status.installedTag !== status.vendorTag &&
      deps.state.get(deps.keys.updateDeclined) !== status.vendorTag
    ) {
      shown = { kind: 'update', tag: status.vendorTag }
      return {
        text: fill(UI_TEXT.bundledSkillsUpdateOffer, { tag: status.vendorTag }),
        actions: ['updateBundledSkills', 'declineBundledSkills'],
      }
    }
    return undefined
  }
  // Claimed before the read, so two conversations starting together offer
  // once; given back when there was nothing to offer or the read failed.
  const claimAndRead = async (): Promise<BundledSkillsNotice | undefined> => {
    isClaimed = true
    let notice: BundledSkillsNotice | undefined
    try {
      notice = noticeFor(await deps.status())
    } finally {
      if (notice === undefined) {
        isClaimed = false
      }
    }
    return notice
  }
  return {
    next: async () => (isClaimed || !deps.isEnabled() ? undefined : await claimAndRead()),
    decline: async () => {
      if (shown === undefined) {
        return
      }
      await (shown.kind === 'install'
        ? deps.state.update(deps.keys.installDeclined, true)
        : deps.state.update(deps.keys.updateDeclined, shown.tag))
    },
  }
}

export interface BundledSkillsCommandDeps {
  readonly bundle: () => BundledSkillsBundle
  /** Read at each run: the config home follows `museSpark.environmentVariables`. */
  readonly paths: () => BundledSkillsPaths
  readonly platform: NodeJS.Platform
  readonly now: () => number
  readonly newId: () => string
  readonly showInformation: (message: string) => void
  /** Said and logged (`loggedPopups`). */
  readonly showError: (message: string) => void
  /** Whether a `muse serve` runs that started with the old skills. */
  readonly isMuseCodeRunning: () => boolean
  /** The skill commands' restart offer; true when the user chose to. */
  readonly confirmRestart: () => Promise<boolean>
  readonly restart: () => Promise<void>
  readonly log: Logger
}

function reasonText(failure: BundledSkillsFailure): string {
  return failure.reason.kind === 'notOurs' ? UI_TEXT.bundledSkillsNotOurs : failure.reason.message
}

function failureText(template: string, failure: BundledSkillsFailure): string {
  return fill(template, { folder: failure.folder, reason: reasonText(failure) })
}

async function offerRestart(deps: BundledSkillsCommandDeps): Promise<void> {
  if (!deps.isMuseCodeRunning() || !(await deps.confirmRestart())) {
    return
  }
  await deps.restart()
  deps.showInformation(UI_TEXT.restartedNotice)
}

/** Install for Muse Code, or update the extension's copy: the same steps, said once done. */
export async function runBundledSkillsInstall(deps: BundledSkillsCommandDeps): Promise<void> {
  const result = await deps.bundle().installBundledSkills({
    ...deps.paths(),
    platform: deps.platform,
    now: deps.now,
    newId: deps.newId,
  })
  const tag = result.tag ?? NONE
  deps.log.info(
    `Bundled skills ${tag}: installed [${result.installed.join(', ')}], skipped [${result.skipped.join(', ')}], removed [${result.removed.join(', ')}]`,
  )
  const said = [
    ...(result.installed.length === 0
      ? []
      : [
          plural(UI_TEXT.bundledSkillsInstalled, result.installed.length, {
            tag,
            skills: listed(result.installed),
          }),
        ]),
    ...(result.skipped.length === 0
      ? []
      : [
          plural(UI_TEXT.bundledSkillsSkipped, result.skipped.length, {
            skills: listed(result.skipped),
          }),
        ]),
    ...(result.removed.length === 0
      ? []
      : [
          plural(UI_TEXT.bundledSkillsRemoved, result.removed.length, {
            skills: listed(result.removed),
          }),
        ]),
  ]
  if (said.length > 0) {
    deps.showInformation(said.join('. '))
  }
  for (const failure of [result.failure, result.undoFailure]) {
    if (failure !== undefined) {
      deps.showError(failureText(UI_TEXT.bundledSkillsInstallFailed, failure))
    }
  }
  if (result.failure === undefined) {
    await offerRestart(deps)
  }
}

/** Remove what the install made, and only that. */
export async function runBundledSkillsRemove(deps: BundledSkillsCommandDeps): Promise<void> {
  const result = await deps.bundle().removeBundledSkills(deps.paths())
  if (!result.hadCopy) {
    deps.showInformation(UI_TEXT.bundledSkillsNothingToRemove)
    return
  }
  deps.log.info(`Bundled skills removed: [${result.removed.join(', ')}]`)
  // A removal that stopped before its first link says only why.
  if (result.failure === undefined || result.removed.length > 0) {
    deps.showInformation(
      plural(UI_TEXT.bundledSkillsRemoved, result.removed.length, {
        skills: listed(result.removed),
      }),
    )
  }
  if (result.failure !== undefined) {
    deps.showError(failureText(UI_TEXT.bundledSkillsRemoveFailed, result.failure))
    // Nothing removed, nothing for a restart to pick up.
    if (result.removed.length === 0) {
      return
    }
  }
  await offerRestart(deps)
}

src/host/usage/traceLogs.ts:
// Reads the Muse Code CLI's trace logs for the usage insights (PLAN.md D17):
// `~/.local/share/muse/local-tracing/bootstrap/cli-<uuid>.log`, one per
// `muse serve` process, newest first, a bounded number of bounded files. A
// running host holds its log locked; that file is skipped, not waited for.
// The lines are read by the pure parser in src/core/usage/insights.ts.

import { readdir, readFile, stat } from 'node:fs/promises'
import path from 'node:path'
import { parseTraceLog, summarizeInsights, type TraceLogFacts } from '../../core/usage/insights'
import {
  MUSE_TRACE_LOG_SEGMENTS,
  TRACE_LOG_FILE_SUFFIX,
  TRACE_LOG_MAX_BYTES,
  TRACE_LOG_MAX_FILES,
  USAGE_INSIGHTS_TTL_MS,
  USAGE_WINDOW_DAY_MS,
  USAGE_WINDOW_WEEK_MS,
} from '../../shared/constants'
import type { UsageInsightsReport } from '../conversation/conversationController'

export interface TraceLogDeps {
  readonly homeDir: string
}

export interface InsightsReaderDeps extends TraceLogDeps {
  readonly now: () => number
}

export interface InsightsReader {
  /** The day and week windows; undefined when there are no logs at all. */
  read(): Promise<UsageInsightsReport | undefined>
}

export function traceLogDirectory(deps: TraceLogDeps): string {
  return path.join(deps.homeDir, ...MUSE_TRACE_LOG_SEGMENTS)
}

async function readOne(file: string): Promise<TraceLogFacts | undefined> {
  try {
    const info = await stat(file)
    return info.size > TRACE_LOG_MAX_BYTES ? undefined : parseTraceLog(await readFile(file, 'utf8'))
  } catch {
    // Locked by a running host, or gone between the listing and the read.
    return undefined
  }
}

/**
 * Reads and summarises the logs on demand, at most once per TTL: the usage
 * modal asks on every open and on every `usage/changed`.
 */
export function createInsightsReader(deps: InsightsReaderDeps): InsightsReader {
  let cached:
    { readonly atMs: number; readonly report: UsageInsightsReport | undefined } | undefined
  return {
    async read() {
      const nowMs = deps.now()
      if (cached !== undefined && nowMs - cached.atMs < USAGE_INSIGHTS_TTL_MS) {
        return cached.report
      }
      const logs = await readTraceLogs(deps)
      const report =
        logs.length === 0
          ? undefined
          : {
              day: summarizeInsights(logs, nowMs, USAGE_WINDOW_DAY_MS),
              week: summarizeInsights(logs, nowMs, USAGE_WINDOW_WEEK_MS),
            }
      cached = { atMs: nowMs, report }
      return report
    },
  }
}

/** The readable logs, newest first, capped; an absent directory is no logs. */
export async function readTraceLogs(deps: TraceLogDeps): Promise<readonly TraceLogFacts[]> {
  const directory = traceLogDirectory(deps)
  let names: readonly string[]
  try {
    names = await readdir(directory)
  } catch {
    return []
  }
  const candidates = names.filter((name) => name.endsWith(TRACE_LOG_FILE_SUFFIX))
  const stamped = await Promise.all(
    candidates.map(async (name) => {
      const file = path.join(directory, name)
      try {
        const info = await stat(file)
        return { file, mtimeMs: info.mtimeMs }
      } catch {
        return
      }
    }),
  )
  const newestFirst = stamped
    .filter((entry) => entry !== undefined)
    .toSorted((a, b) => b.mtimeMs - a.mtimeMs)
    .slice(0, TRACE_LOG_MAX_FILES)
  const logs = await Promise.all(newestFirst.map((entry) => readOne(entry.file)))
  return logs.filter((log) => log !== undefined)
}

src/host/views/chatPanel.ts:
// Editor-tab surface ("Open in New Tab"). Each panel is an independent
// conversation, mirroring the Claude Code extension's tab model: the tab is
// named after the conversation and carries an unread mark while something
// happened behind it (M6). After a window reload VS Code rebuilds the panel
// through the serializer registered in extension.ts and hands back the
// state the webview stored (its session id), so the tab resumes its
// conversation (PLAN.md D15). A tab becomes the surface the keybindings act
// on when it turns active or its document takes focus (M25).

import * as vscode from 'vscode'
import { CHAT_PANEL_VIEW_TYPE, UI_TEXT } from '../../shared/constants'
import { parsePersistedState } from '../../shared/protocol'
import type { SurfaceRegistry } from './surfaceRegistry'
import { configureWebview, type WebviewHostContext } from './webviewSetup'

function attachChatPanel(
  panel: vscode.WebviewPanel,
  context: WebviewHostContext,
  registry: SurfaceRegistry,
  restoredSessionId: string | undefined,
  isSideChat = false,
  onDisposed?: () => void,
): void {
  // A restored panel keeps the title VS Code saved, unread mark included.
  let title = panel.title.startsWith(UI_TEXT.unreadMark)
    ? panel.title.slice(UI_TEXT.unreadMark.length)
    : panel.title
  let isUnread = false
  const applyTitle = () => {
    panel.title = isUnread ? `${UI_TEXT.unreadMark}${title}` : title
  }
  const surface = configureWebview(panel.webview, context, {
    id: `panel:${globalThis.crypto.randomUUID()}`,
    restoredSessionId,
    isSideChat,
    reveal: () => {
      panel.reveal(undefined, false)
    },
    markUnread: () => {
      if (panel.active) {
        return
      }
      isUnread = true
      applyTitle()
    },
    setTitle: (name) => {
      title = isSideChat ? `${UI_TEXT.sideChatTitle}: ${name}` : name
      applyTitle()
    },
    onFocused: (focused) => {
      registry.setActive(focused)
    },
  })
  const registration = registry.add(surface)
  registry.setActive(surface)
  panel.onDidChangeViewState((event) => {
    if (!event.webviewPanel.active) {
      return
    }
    registry.setActive(surface)
    if (!isUnread) {
      return
    }
    isUnread = false
    applyTitle()
  })
  panel.onDidDispose(() => {
    registration.dispose()
    surface.dispose()
    onDisposed?.()
  })
}

export interface NewChatPanelOptions {
  readonly sessionId?: string
  readonly isSideChat?: boolean
  readonly onDisposed?: () => void
}

export function openChatPanel(
  context: WebviewHostContext,
  registry: SurfaceRegistry,
  options: NewChatPanelOptions = {},
): vscode.WebviewPanel {
  const panel = vscode.window.createWebviewPanel(
    CHAT_PANEL_VIEW_TYPE,
    options.isSideChat === true ? UI_TEXT.sideChatTitle : UI_TEXT.untitledConversation,
    vscode.ViewColumn.Beside,
    { retainContextWhenHidden: true },
  )
  attachChatPanel(
    panel,
    context,
    registry,
    options.sessionId,
    options.isSideChat,
    options.onDisposed,
  )
  return panel
}

/**
 * A panel VS Code rebuilt after a window reload: wired like a new one, and
 * resuming the session the webview had stored, if the state is one of ours.
 */
export function restoreChatPanel(
  panel: vscode.WebviewPanel,
  state: unknown,
  context: WebviewHostContext,
  registry: SurfaceRegistry,
): void {
  const persisted = parsePersistedState(state)
  attachChatPanel(panel, context, registry, persisted.sessionId, persisted.sideChat)
}

src/host/views/ChatViewProvider.ts:
// Sidebar surface: the `museSpark.chatView` WebviewView contributed in
// package.json. The editor-tab surface lives in chatPanel.ts; both share
// configureWebview. The view becomes the surface the keybindings act on when
// it is shown or its document takes focus (M25).

import type * as vscode from 'vscode'
import { UI_TEXT } from '../../shared/constants'
import type { SurfaceRegistry } from './surfaceRegistry'
import { configureWebview, type WebviewHostContext } from './webviewSetup'

export const SIDEBAR_SURFACE_ID = 'sidebar'
const UNREAD_BADGE_VALUE = 1

export class ChatViewProvider implements vscode.WebviewViewProvider {
  public constructor(
    private readonly context: WebviewHostContext,
    private readonly registry: SurfaceRegistry,
  ) {}

  public resolveWebviewView(view: vscode.WebviewView): void {
    const surface = configureWebview(view.webview, this.context, {
      id: SIDEBAR_SURFACE_ID,
      restoredSessionId: undefined,
      reveal: () => {
        view.show(false)
      },
      // The unread dot of Claude Code's sidebar: a badge on the view while it
      // is hidden, cleared as soon as it is shown again (M6).
      markUnread: () => {
        if (!view.visible) {
          view.badge = { tooltip: UI_TEXT.unreadTooltip, value: UNREAD_BADGE_VALUE }
        }
      },
      setTitle: (title) => {
        view.description = title === UI_TEXT.untitledConversation ? '' : title
      },
      onFocused: (focused) => {
        this.registry.setActive(focused)
      },
    })
    const registration = this.registry.add(surface)
    view.onDidChangeVisibility(() => {
      if (!view.visible) {
        return
      }
      view.badge = undefined
      this.registry.setActive(surface)
    })
    view.onDidDispose(() => {
      registration.dispose()
      surface.dispose()
    })
  }
}

src/host/views/surfaceRegistry.ts:
// Tracks every open chat surface and which one last had the user's attention,
// so keybindings and settings broadcasts know where to send messages.

import type * as vscode from 'vscode'
import type { HostToWebviewMessage } from '../../shared/protocol'
import type { ChatSurface } from './chatSurface'

export class SurfaceRegistry {
  private readonly surfaces = new Map<string, ChatSurface>()
  private readonly removedListeners = new Set<(surface: ChatSurface) => void>()
  private readonly activeListeners = new Set<() => void>()
  private activeId: string | undefined

  /** The active surface is now `id`; its watchers hear of a change (M46). */
  private activate(id: string | undefined): void {
    if (this.activeId === id) {
      return
    }
    this.activeId = id
    for (const listener of this.activeListeners) {
      listener()
    }
  }

  /** Registers a surface; the returned disposable unregisters it. */
  public add(surface: ChatSurface): vscode.Disposable {
    this.surfaces.set(surface.id, surface)
    this.activate(this.activeId ?? surface.id)
    return {
      dispose: () => {
        this.surfaces.delete(surface.id)
        if (this.activeId === surface.id) {
          this.activate(this.surfaces.keys().next().value)
        }
        for (const listener of this.removedListeners) {
          listener(surface)
        }
      },
    }
  }

  /** Observe surfaces leaving the registry (view closed, panel disposed). */
  public onRemoved(listener: (surface: ChatSurface) => void): vscode.Disposable {
    this.removedListeners.add(listener)
    return {
      dispose: () => {
        this.removedListeners.delete(listener)
      },
    }
  }

  /**
   * Observe the active surface changing (M46): the keybindings' context keys
   * follow the conversation the user is looking at.
   */
  public onActiveChanged(listener: () => void): vscode.Disposable {
    this.activeListeners.add(listener)
    return {
      dispose: () => {
        this.activeListeners.delete(listener)
      },
    }
  }

  public setActive(surface: ChatSurface): void {
    if (this.surfaces.has(surface.id)) {
      this.activate(surface.id)
    }
  }

  /** True only while this exact surface is still registered. */
  public has(surface: ChatSurface): boolean {
    return this.surfaces.get(surface.id) === surface
  }

  /** The surface that last reported focus, else the earliest registered one. */
  public get active(): ChatSurface | undefined {
    return this.activeId === undefined ? undefined : this.surfaces.get(this.activeId)
  }

  public get size(): number {
    return this.surfaces.size
  }

  public broadcast(message: HostToWebviewMessage): void {
    for (const surface of this.surfaces.values()) {
      surface.post(message)
    }
  }
}

src/host/views/webviewErrors.ts:
// Webview errors in the host's log (M39). The webview reports what threw:
// a render the error boundary caught, an error or a rejected promise nothing
// handled, a host message it could not use. Each panel logs at most
// WEBVIEW_ERROR_LOG_LIMIT a minute, then says once that it stopped, so a
// render loop cannot flood the log.

import { WEBVIEW_ERROR_LOG_LIMIT, WEBVIEW_ERROR_WINDOW_MS } from '../../shared/constants'
import type { WebviewToHostMessage } from '../../shared/protocol'
import type { Logger } from '../logger'

export type WebviewErrorMessage = Extract<WebviewToHostMessage, { type: 'webviewError' }>

/** One panel's error log: call it with each report. */
export function webviewErrorLog(
  log: Logger,
  now: () => number,
): (report: WebviewErrorMessage) => void {
  let recent: readonly number[] = []
  let isMuted = false
  return (report) => {
    const at = now()
    recent = recent.filter((logged) => at - logged < WEBVIEW_ERROR_WINDOW_MS)
    if (recent.length >= WEBVIEW_ERROR_LOG_LIMIT) {
      if (!isMuted) {
        isMuted = true
        log.warn(
          `More webview errors in this minute are not logged (${String(WEBVIEW_ERROR_LOG_LIMIT)} were)`,
        )
      }
      return
    }
    isMuted = false
    recent = [...recent, at]
    const stack = report.stack === undefined ? '' : `\n${report.stack}`
    log.error(`Webview error (${report.source}): ${report.message}${stack}`)
  }
}

src/host/views/webviewSetup.ts:
// Shared wiring for both webview surfaces (sidebar view and editor panel):
// options, HTML with a fresh CSP nonce, the inbound message handler, and the
// `ChatSurface` handle (chatSurface.ts) the rest of the host uses to talk back.

import * as vscode from 'vscode'
import {
  UI_TEXT,
  WEBVIEW_DIST_SEGMENTS,
  WEBVIEW_SCRIPT_FILE,
  WEBVIEW_STYLE_FILE,
} from '../../shared/constants'
import {
  type HostToWebviewMessage,
  parseWebviewToHostMessage,
  type SettingsSnapshot,
} from '../../shared/protocol'
import { buildWebviewHtml, createNonce } from '../html'
import type { UiTable } from '../l10n'
import type { Logger } from '../logger'
import type { ChatSurface, ConversationMessage } from './chatSurface'
import { webviewErrorLog } from './webviewErrors'

export interface WebviewHostContext {
  readonly extensionUri: vscode.Uri
  /** The display language's table, installed at activation, for every webview's HTML (D33). */
  readonly l10n: UiTable
  readonly log: Logger
  readonly getSettings: () => SettingsSnapshot
  readonly onInputFocusChanged: (surface: ChatSurface, isFocused: boolean) => void
  /** The webview mounted and received `init`; push the conversation state. */
  readonly onSurfaceReady: (surface: ChatSurface, attachmentEpoch?: number) => void
  readonly onConversationMessage: (surface: ChatSurface, message: ConversationMessage) => void
}

export interface SurfaceOptions {
  readonly id: string
  readonly isSideChat?: boolean
  /** The session id a deserialized panel stored; undefined for a new surface. */
  readonly restoredSessionId: string | undefined
  readonly reveal: () => void
  readonly markUnread: () => void
  readonly setTitle: (title: string) => void
  /** The document gained focus (M25): the surface the keybindings act on. */
  readonly onFocused: (surface: ChatSurface) => void
}

/**
 * Whether a message ends the restore a panel is owed (M25): a session is
 * live on the surface (its history went out, or a new one started), or the
 * conversation was cleared (from the panel or a keybinding).
 */
function isRestoreEnding(message: HostToWebviewMessage): boolean {
  return (
    message.type === 'historyLoaded' ||
    message.type === 'conversationCleared' ||
    (message.type === 'sessionInfo' && message.sessionId !== undefined)
  )
}

function buildInitMessage(context: WebviewHostContext, isSideChat: boolean): HostToWebviewMessage {
  return {
    type: 'init',
    emptyStateHint: UI_TEXT.emptyStateHint,
    composerPlaceholder: UI_TEXT.composerPlaceholder,
    settings: isSideChat
      ? { ...context.getSettings(), initialPermissionMode: 'plan' }
      : context.getSettings(),
    ...(isSideChat && { sideChat: true }),
  }
}

/**
 * Configures `webview` and starts handling its messages. Disposing the
 * returned surface stops the message handling; callers tie it to the owning
 * view's or panel's `onDidDispose`.
 */
export function configureWebview(
  webview: vscode.Webview,
  context: WebviewHostContext,
  options: SurfaceOptions,
): ChatSurface {
  const bundleRoot = vscode.Uri.joinPath(context.extensionUri, ...WEBVIEW_DIST_SEGMENTS)
  webview.options = { enableScripts: true, localResourceRoots: [bundleRoot] }
  const applyHtml = () => {
    webview.html = buildWebviewHtml({
      scriptUri: webview
        .asWebviewUri(vscode.Uri.joinPath(bundleRoot, WEBVIEW_SCRIPT_FILE))
        .toString(),
      styleUri: webview
        .asWebviewUri(vscode.Uri.joinPath(bundleRoot, WEBVIEW_STYLE_FILE))
        .toString(),
      cspSource: webview.cspSource,
      nonce: createNonce(),
      l10n: context.l10n,
    })
  }
  applyHtml()

  let restoredSessionId = options.restoredSessionId
  const surface: ChatSurface = {
    id: options.id,
    isSideChat: options.isSideChat === true,
    post(message) {
      if (isRestoreEnding(message)) {
        restoredSessionId = undefined
      }
      void webview.postMessage(message)
    },
    reveal: options.reveal,
    markUnread: options.markUnread,
    setTitle: options.setTitle,
    reload: applyHtml,
    takeRestoredSessionId() {
      return restoredSessionId
    },
    dispose() {
      subscription.dispose()
    },
  }

  const logWebviewError = webviewErrorLog(context.log, Date.now)
  const subscription = webview.onDidReceiveMessage((raw: unknown) => {
    const parsed = parseWebviewToHostMessage(raw)
    if (!parsed.ok) {
      context.log.warn(`Dropped malformed webview message: ${parsed.error}`)
      return
    }
    const { message } = parsed
    switch (message.type) {
      case 'ready': {
        surface.post(buildInitMessage(context, surface.isSideChat === true))
        context.onSurfaceReady(surface, message.attachmentEpoch)
        break
      }
      case 'inputFocusChanged': {
        context.onInputFocusChanged(surface, message.focused)
        break
      }
      case 'surfaceFocused': {
        options.onFocused(surface)
        break
      }
      case 'webviewError': {
        logWebviewError(message)
        break
      }
      default: {
        context.onConversationMessage(surface, message)
      }
    }
  })

  return surface
}

src/host/voice/dictationHost.ts:
// The host side of voice dictation (M9): finds the helper for this platform,
// at activation, so the microphone says at once whether it can record. One
// setup per window; each conversation creates its own driver from it on
// first use. Muse Voice (M35) adds its capture helper, the Linux recorders
// and the WebSocket to Meta. The drivers themselves, with the processes and
// the socket, are dist/voice.js (PLAN.md D6), loaded on the first recording.

import { existsSync } from 'node:fs'
import { env, ExtensionKind, extensions } from 'vscode'
import type { CoreLogger } from '../../core/logging'
import type { DictationSetup } from '../../core/voice/dictation'
import {
  type CaptureProbe,
  type HelperProbe,
  locateCaptureHelper,
  locateDictationHelper,
} from '../../core/voice/helperLocation'
import { EXTENSION_QUALIFIED_ID, UI_TEXT } from '../../shared/constants'
import { uiLocale } from '../../shared/l10n/text'
import { deferredDriver, type VoiceBundle } from './voiceBundle'

/**
 * The remote this extension host runs on, or undefined on the user's own
 * machine. `env.remoteName` alone is not enough: it is also set in the local
 * extension host of a remote window ("defined in all extension hosts (local
 * and remote) in case a remote extension host exists", vscode.d.ts), where
 * a user's `remote.extensionKind` override could run this extension; the
 * extension's kind says which side it is on.
 */
function remoteHostName(): string | undefined {
  const kind = extensions.getExtension(EXTENSION_QUALIFIED_ID)?.extensionKind
  return kind === ExtensionKind.UI ? undefined : env.remoteName
}

export function createDictationSetup(
  probe: Omit<HelperProbe, 'fileExists' | 'programFiles' | 'remoteName' | 'appName'>,
  log: CoreLogger,
  voice: () => VoiceBundle,
): DictationSetup {
  const location = locateDictationHelper({
    ...probe,
    fileExists: existsSync,
    programFiles: process.env['ProgramFiles'],
    remoteName: remoteHostName(),
    appName: env.appName,
  })
  if (!location.isAvailable) {
    log.info(`Voice dictation unavailable: ${location.reason}`)
    return location
  }
  return {
    isAvailable: true,
    create: (listener) =>
      deferredDriver(listener, () =>
        voice().createDictation(location.invocation, listener, log, UI_TEXT, uiLocale()),
      ),
  }
}

export interface MuseVoiceSetupDeps {
  /** The Model API key, read per recording. */
  readonly apiKey: () => Promise<string | undefined>
  /** Counts whole seconds of audio sent, for the window's tally. */
  readonly onSeconds: (seconds: number) => void
  readonly log: CoreLogger
  /** dist/voice.js, required on the first recording. */
  readonly voice: () => VoiceBundle
}

/**
 * Muse Voice (M35, PLAN.md D30): the paid engine's recorder for this
 * platform and the stream to Meta, or why it cannot run here. Whether it is
 * the microphone's engine (the setting, the accepted price, the Model API
 * backend) is the caller's to decide.
 */
export function createMuseVoiceSetup(
  probe: Omit<
    CaptureProbe,
    'fileExists' | 'programFiles' | 'remoteName' | 'appName' | 'pathVariable'
  >,
  deps: MuseVoiceSetupDeps,
): DictationSetup {
  if (typeof globalThis.WebSocket !== 'function') {
    return { isAvailable: false, reason: UI_TEXT.museVoiceNoWebSocket }
  }
  const location = locateCaptureHelper({
    ...probe,
    fileExists: existsSync,
    programFiles: process.env['ProgramFiles'],
    remoteName: remoteHostName(),
    appName: env.appName,
    pathVariable: process.env['PATH'],
  })
  if (!location.isAvailable) {
    deps.log.info(`Muse Voice unavailable: ${location.reason}`)
    return location
  }
  const { voice, ...driverDeps } = deps
  return {
    isAvailable: true,
    create: (listener) =>
      deferredDriver(listener, () =>
        voice().createMuseVoice(
          { ...driverDeps, capture: location },
          listener,
          UI_TEXT,
          uiLocale(),
        ),
      ),
  }
}

src/host/voice/voiceBundle.ts:
// Voice's drivers as the activation bundle sees them (M9, M35, PLAN.md D6):
// dist/voice.js, built from voiceEntry.ts and required on the first
// recording. Only types come from the drivers' side here: a value imported
// from there would carry them back into dist/extension.js, which the
// bundle-split gate refuses.
//
// There is no fallback without it: a recording that cannot load it fails as
// any recording fails, through the listener's `onError` ("Voice dictation
// failed: …", the log has the cause), and the next press tries again.

import type { DictationHandle, DictationListener } from '../../core/voice/dictation'
import { UI_TEXT } from '../../shared/constants'
import { lazyBundleLoader } from '../lazyBundle'
import type { Logger } from '../logger'
import type * as VoiceEntry from './voiceEntry'

/** The bundle's two drivers, shipped and loaded together. */
export interface VoiceBundle {
  readonly createDictation: typeof VoiceEntry.createDictation
  readonly createMuseVoice: typeof VoiceEntry.createMuseVoice
}

/** Whether a required module exports both drivers. */
export function isVoiceBundle(value: unknown): value is VoiceBundle {
  return (
    typeof value === 'object' &&
    value !== null &&
    'createDictation' in value &&
    typeof value.createDictation === 'function' &&
    'createMuseVoice' in value &&
    typeof value.createMuseVoice === 'function'
  )
}

export interface VoiceLoaderDeps {
  /** dist/voice.js beside the running bundle. */
  readonly bundlePath: string
  readonly log: Logger
  /** How the bundle is loaded: Node's `require` unless a test hands in the module. */
  readonly loadBundle?: ((file: string) => unknown) | undefined
}

/** The bundle, required on the first recording and kept from then on. */
export function voiceLoader(deps: VoiceLoaderDeps): () => VoiceBundle {
  return lazyBundleLoader({
    ...deps,
    isBundle: isVoiceBundle,
    label: 'voice bundle',
    unavailable: () => UI_TEXT.dictationNotLoaded,
  })
}

/**
 * A driver whose implementation is made on the first `start`, so the bundle
 * loads with the first recording rather than with the panel. A load that
 * fails is the listener's `onError` (the status is still idle), and the next
 * `start` tries again; `stop` and `dispose` reach the driver once there is one.
 */
export function deferredDriver(
  listener: DictationListener,
  make: () => DictationHandle,
): DictationHandle {
  let driver: DictationHandle | undefined
  let isDisposed = false
  return {
    start() {
      if (isDisposed) {
        return
      }
      if (driver === undefined) {
        try {
          driver = make()
        } catch (error: unknown) {
          listener.onError(error instanceof Error ? error.message : String(error))
          return
        }
      }
      driver.start()
    },
    stop() {
      driver?.stop()
    },
    dispose() {
      isDisposed = true
      driver?.dispose()
    },
  }
}

src/host/web/pageConverter.ts:
// Runs web fetch's HTML converter on a worker thread (M69, PLAN.md D49):
// the bundled dist/pageWorker.js, started for each page (never at
// activation). Each worker is stopped when it passes
// WEB_FETCH_CONVERT_TIMEOUT_MS, when its heap passes
// WEB_FETCH_CONVERT_MAX_HEAP_MIB, or when the fetch is stopped, and at most
// WEB_FETCH_CONVERT_MAX_WORKERS run at once in the window, so subagents
// fetching together wait their turn instead of multiplying the heap. The
// extension host itself never parses a page. A failure's detail is a short
// code (it is shown inside a translated sentence); its diagnosis (the
// error's name, code and top stack frames, never its message) goes to the
// log.

import { Worker, type WorkerOptions } from 'node:worker_threads'
import * as z from 'zod/mini'
import type { HtmlConversion, HtmlConverter, HtmlJob } from '../../core/web/htmlConversion'
import {
  WEB_FETCH_CONVERT_MAX_HEAP_MIB,
  WEB_FETCH_CONVERT_MAX_WORKERS,
  WEB_FETCH_CONVERT_TIMEOUT_MS,
} from '../../shared/constants'
import type { Logger } from '../logger'

// Node's code for a worker stopped at its heap limit.
const OUT_OF_MEMORY = 'ERR_WORKER_OUT_OF_MEMORY'
// The failure details, codes rather than words.
const STOPPED = 'STOPPED'
const BAD_ANSWER = 'BAD_ANSWER'
const UNKNOWN_ERROR = 'ERROR'
const EXIT_PREFIX = 'EXIT_'
const STACK_FRAME = /^\s+at /
const LOGGED_FRAMES = 3

// What the worker posts, checked at the thread boundary (AGENTS.md rule 7).
const CONVERSION = z.union([
  z.object({
    ok: z.literal(true),
    page: z.object({
      title: z.optional(z.string()),
      markdown: z.string(),
      isTruncated: z.boolean(),
    }),
  }),
  z.object({
    ok: z.literal(false),
    kind: z.enum(['timeout', 'memory', 'failed', 'undecodable']),
    detail: z.string(),
  }),
])

/** How long, and with how much heap, a page may take to convert. */
export interface ConverterLimits {
  readonly timeoutMs: number
  readonly maxHeapMib: number
}

const LIMITS: ConverterLimits = {
  timeoutMs: WEB_FETCH_CONVERT_TIMEOUT_MS,
  maxHeapMib: WEB_FETCH_CONVERT_MAX_HEAP_MIB,
}

/** Starts a worker: Node's, or a test's that watches it. */
export type StartWorker = (path: string, options: WorkerOptions) => Worker

function startNodeWorker(path: string, options: WorkerOptions): Worker {
  return new Worker(path, options)
}

/** The conversions allowed at once; a wait for a slot ends when the fetch is stopped. */
export class ConversionSlots {
  private running = 0
  private readonly waiting: (() => void)[] = []

  public constructor(private readonly size: number) {}

  /** Takes a slot; false when the signal stopped the wait first. */
  public async take(signal: AbortSignal): Promise<boolean> {
    if (signal.aborted) {
      return false
    }
    if (this.running < this.size) {
      this.running += 1
      return true
    }
    return await new Promise<boolean>((resolve) => {
      const grant = () => {
        signal.removeEventListener('abort', onAbort)
        this.running += 1
        resolve(true)
      }
      const onAbort = () => {
        const at = this.waiting.indexOf(grant)
        if (at !== -1) {
          this.waiting.splice(at, 1)
        }
        resolve(false)
      }
      this.waiting.push(grant)
      signal.addEventListener('abort', onAbort, { once: true })
    })
  }

  public release(): void {
    this.running -= 1
    this.waiting.shift()?.()
  }
}

// The window's conversions, shared by every fetch (and every subagent's).
const WINDOW_SLOTS = new ConversionSlots(WEB_FETCH_CONVERT_MAX_WORKERS)

function codeOf(error: unknown): string {
  return typeof error === 'object' && error !== null && 'code' in error
    ? String(error.code)
    : UNKNOWN_ERROR
}

/** An error as the log may keep it: name, code and top frames; the message can quote the page. */
function diagnosisOf(error: unknown): string {
  if (!(error instanceof Error)) {
    return typeof error
  }
  const frames = (error.stack ?? '')
    .split('\n')
    .filter((line) => STACK_FRAME.test(line))
    .slice(0, LOGGED_FRAMES)
    .map((line) => line.trim())
  return [`${error.name} ${codeOf(error)}`, ...frames].join(' | ')
}

/** The converter on the worker bundle at `workerPath`, with the time and memory limits. */
export function pageConverter(
  workerPath: string,
  log: Logger,
  limits = LIMITS,
  startWorker: StartWorker = startNodeWorker,
  slots = WINDOW_SLOTS,
): HtmlConverter {
  return async (job, signal) => {
    if (!(await slots.take(signal))) {
      return { ok: false, kind: 'failed', detail: STOPPED }
    }
    try {
      return await convertOnWorker({ workerPath, job, limits, signal, log, startWorker })
    } finally {
      slots.release()
    }
  }
}

interface Conversion {
  readonly workerPath: string
  readonly job: HtmlJob
  readonly limits: ConverterLimits
  readonly signal: AbortSignal
  readonly log: Logger
  readonly startWorker: StartWorker
}

function convertOnWorker(conversion: Conversion): Promise<HtmlConversion> {
  const { workerPath, job, limits, signal, log, startWorker } = conversion
  return new Promise<HtmlConversion>((resolve) => {
    let worker: Worker
    try {
      worker = startWorker(workerPath, {
        workerData: job,
        resourceLimits: { maxOldGenerationSizeMb: limits.maxHeapMib },
      })
    } catch (error: unknown) {
      log.warn(`Web fetch: the page converter did not start: ${diagnosisOf(error)}`)
      resolve({ ok: false, kind: 'failed', detail: codeOf(error) })
      return
    }
    let isSettled = false
    const settle = (outcome: HtmlConversion) => {
      if (isSettled) {
        return
      }
      isSettled = true
      clearTimeout(timer)
      signal.removeEventListener('abort', onAbort)
      void worker.terminate()
      resolve(outcome)
    }
    function onAbort(): void {
      settle({ ok: false, kind: 'failed', detail: STOPPED })
    }
    const timer = setTimeout(() => {
      settle({ ok: false, kind: 'timeout', detail: String(limits.timeoutMs) })
    }, limits.timeoutMs)
    if (signal.aborted) {
      onAbort()
      return
    }
    signal.addEventListener('abort', onAbort, { once: true })
    worker.on('message', (message: unknown) => {
      const parsed = CONVERSION.safeParse(message)
      if (!parsed.success) {
        log.warn('Web fetch: the page converter answered in an unknown shape')
        settle({ ok: false, kind: 'failed', detail: BAD_ANSWER })
        return
      }
      const outcome = parsed.data
      settle(
        outcome.ok ? { ok: true, page: { ...outcome.page, title: outcome.page.title } } : outcome,
      )
    })
    worker.on('error', (error: unknown) => {
      const code = codeOf(error)
      if (code !== OUT_OF_MEMORY) {
        log.warn(`Web fetch: the page converter failed: ${diagnosisOf(error)}`)
      }
      settle({ ok: false, kind: code === OUT_OF_MEMORY ? 'memory' : 'failed', detail: code })
    })
    worker.on('exit', (code: number) => {
      if (!isSettled) {
        log.warn(`Web fetch: the page converter exited with code ${String(code)}`)
      }
      settle({ ok: false, kind: 'failed', detail: `${EXIT_PREFIX}${String(code)}` })
    })
  })
}

src/host/web/pinnedRequest.ts:
// Web fetch's transport (M69, PLAN.md D49): one HTTPS GET made to the
// address the fetch checked, never to a name looked up again. Node's `https`
// is asked to connect to that IP address; TLS still sends and verifies the
// page's own name (`servername`), and the `Host` header carries it.
//
// Through VS Code's proxy: VS Code patches Node's `https` module in place
// for every extension (proxyResolver.ts in VS Code 1.125 and later, with
// @vscode/proxy-agent), so this request takes the user's proxy (`http.proxy`,
// the system's or a PAC file's, `http.noProxy`) and their certificates as
// the Model API's `fetch` does (M56). Its proxy agent tunnels with
// `CONNECT <address>:<port>` for the address given here, and upgrades the
// tunnel to TLS with our `servername`, so a proxy never resolves the name
// either: the request stays pinned or fails. VS Code's patched `fetch`
// cannot pin: it replaces a caller's dispatcher with its own agent, which
// keeps only the certificates and HTTP/2 options (@vscode/proxy-agent's
// `createFetchPatch`, read 2026-09-27), so the fetch uses `https`.
//
// Only an answer that came over TLS is read. A proxy that refuses the tunnel
// (a policy against addresses, missing credentials) answers the CONNECT
// itself, and https-proxy-agent hands that answer to the request on a plain
// socket; it is refused as the proxy's (WEB_FETCH_NOT_TLS_CODE), never read
// as the page's.
//
// The proxy decision sees the address too. @vscode/proxy-agent 0.45.0 (VS
// Code 1.139.1's) builds the URL it resolves a proxy for from the request's
// `host` (agent.js: `hostname: opts.host`), and `http.noProxy` and the
// environment's NO_PROXY match that host name's suffix (index.js
// `noProxyFromConfig`). With the pinned address there, a PAC rule or a
// no-proxy entry written for a host name does not match; one written for
// addresses does. Giving the name instead would let the proxy resolve it
// again, which pinning exists to prevent, so the address stays.

import type { ClientRequest, IncomingMessage } from 'node:http'
import { request as httpsRequest, type RequestOptions } from 'node:https'
import type { Socket } from 'node:net'
import { TLSSocket } from 'node:tls'
import type { PinnedResponse, PinnedTarget } from '../../core/web/webFetch'
import { addressFamily } from '../../core/web/publicAddress'
import {
  WEB_FETCH_ACCEPT,
  WEB_FETCH_ACCEPT_ENCODING,
  WEB_FETCH_DEFAULT_PORT,
  WEB_FETCH_NOT_TLS_CODE,
  WEB_FETCH_USER_AGENT,
} from '../../shared/constants'

/** Node's `https.request`, or a test's stand-in with the same shape. */
export type RequestFunction = (
  options: RequestOptions,
  onResponse: (response: IncomingMessage) => void,
) => ClientRequest

/** The request options for a pinned GET: the address to connect to, the name to verify. */
export function pinnedOptions(target: PinnedTarget, signal: AbortSignal): RequestOptions {
  const { url } = target
  return {
    method: 'GET',
    host: target.address,
    family: target.family,
    port: url.port === '' ? WEB_FETCH_DEFAULT_PORT : Number(url.port),
    path: `${url.pathname}${url.search}`,
    // An IP address in the URL is verified as an address; a name is sent
    // and verified as a name (a name, never an address, may go in SNI).
    ...(addressFamily(target.host) === undefined && { servername: target.host }),
    headers: {
      host: url.host,
      'user-agent': WEB_FETCH_USER_AGENT,
      accept: WEB_FETCH_ACCEPT,
      'accept-encoding': WEB_FETCH_ACCEPT_ENCODING,
    },
    signal,
  }
}

/** A response's headers as the fetch reads them: one string each, names in lower case. */
function headersOf(response: IncomingMessage): Readonly<Record<string, string | undefined>> {
  const headers: Record<string, string | undefined> = {}
  for (const [name, value] of Object.entries(response.headers)) {
    headers[name.toLowerCase()] = Array.isArray(value) ? value.join(', ') : value
  }
  return headers
}

/** Whether the answer arrived over TLS, as only the pinned server's can. */
function isOverTls(socket: Socket | null): boolean {
  return socket !== null && 'encrypted' in socket && socket.encrypted === true
}

/**
 * Whether a TLS socket has finished its handshake: its Finished message is
 * there only then (`getProtocol` may name a version before it is done).
 */
function isHandshakeDone(socket: TLSSocket): boolean {
  return socket.getFinished() !== undefined
}

/**
 * Calls `onConnected` once the request's connection is up: its TLS handshake
 * done (to the pinned address, or through the proxy's tunnel to it), or for
 * the tests' plain server its TCP connection. A socket kept alive from an
 * earlier request is up already.
 */
function watchConnection(
  outgoing: ClientRequest,
  isTlsRequired: boolean,
  onConnected: () => void,
): void {
  outgoing.once('socket', (socket: Socket) => {
    if (socket instanceof TLSSocket) {
      if (isHandshakeDone(socket)) {
        onConnected()
      } else {
        socket.once('secureConnect', onConnected)
      }
      return
    }
    if (isTlsRequired) {
      return
    }
    if (socket.connecting) {
      socket.once('connect', onConnected)
    } else {
      onConnected()
    }
  })
}

/** The error for an answer that did not come over TLS: a proxy refused the tunnel. */
function notOverTls(status: number, address: string): Error {
  return Object.assign(
    new Error(
      `Proxy response (${String(status)}) instead of a TLS connection to ${address}; nothing was read`,
    ),
    { code: WEB_FETCH_NOT_TLS_CODE, status },
  )
}

/**
 * One pinned GET; `onConnected` once its connection is up. Rejects when it
 * cannot be made, when a proxy answered instead of the server, or when the
 * signal aborts. `isTlsRequired` is off only for the tests' plain loopback
 * server.
 */
export function pinnedHttpsRequest(
  target: PinnedTarget,
  signal: AbortSignal,
  onConnected: () => void,
  request: RequestFunction = httpsRequest,
  isTlsRequired = true,
): Promise<PinnedResponse> {
  return new Promise((resolve, reject) => {
    const outgoing = request(pinnedOptions(target, signal), (response) => {
      if (isTlsRequired && !isOverTls(response.socket)) {
        response.destroy()
        outgoing.destroy()
        reject(notOverTls(response.statusCode ?? 0, target.address))
        return
      }
      resolve({
        status: response.statusCode ?? 0,
        headers: headersOf(response),
        body: response,
        close: () => {
          response.destroy()
          outgoing.destroy()
        },
      })
    })
    watchConnection(outgoing, isTlsRequired, onConnected)
    outgoing.on('error', reject)
    outgoing.end()
  })
}

src/host/web/webFetchConfirm.ts:
// The extension's own question before Muse Code's web fetch (M69, PLAN.md
// D49): a native modal naming the host and the URL, asked for every call,
// whatever mode Muse Code runs in (its approval covers using the tool; this
// one covers the extension sending the request from the user's machine).
// Closing it is Reject.

import * as vscode from 'vscode'
import { UI_TEXT } from '../../shared/constants'
import { fill } from '../../shared/l10n/text'

export async function isWebFetchAllowed(url: string, host: string): Promise<boolean> {
  const allow: vscode.MessageItem = { title: UI_TEXT.allowOnce }
  const reject: vscode.MessageItem = { title: UI_TEXT.reject, isCloseAffordance: true }
  const answer = await vscode.window.showWarningMessage(
    fill(UI_TEXT.webFetchConfirmTitle, { host }),
    { modal: true, detail: fill(UI_TEXT.webFetchConfirmDetail, { url, host }) },
    allow,
    reject,
  )
  return answer === allow
}

src/host/web/webFetcher.ts:
// The window's web fetch (M69, PLAN.md D49): the core fetch over this
// machine's resolver and the pinned HTTPS transport, shared by the Model API
// backend's `web_fetch` and the `ide` server's `webFetch` for Muse Code. The
// log names the host and the outcome only: a path or a query can carry
// what the conversation put there.

import { randomBytes } from 'node:crypto'
import { ADDRCONFIG } from 'node:dns'
import { lookup, Resolver } from 'node:dns/promises'
import type { HtmlConverter } from '../../core/web/htmlConversion'
import { nat64PrefixesOf } from '../../core/web/publicAddress'
import {
  fetchWebPage,
  type Nat64Discovery,
  type WebFetcher,
  type WebFetchResult,
} from '../../core/web/webFetch'
import {
  ADDRESS_FAMILIES,
  NAT64_ABSENT_CODES,
  NAT64_DISCOVERY_NAME,
  NAT64_DISCOVERY_TIMEOUT_MS,
  NAT64_DISCOVERY_TRIES,
  WEB_FETCH_MARKER_BYTES,
} from '../../shared/constants'
import type { Logger } from '../logger'
import { pinnedHttpsRequest } from './pinnedRequest'

/**
 * Every address the name resolves to, as the operating system's resolver
 * answers a connection's lookup (Node's `net` asks with ADDRCONFIG: no IPv6
 * answers on a machine without an IPv6 address), in its order.
 */
async function resolveAll(host: string): Promise<readonly string[]> {
  const answers = await lookup(host, { all: true, order: 'verbatim', hints: ADDRCONFIG })
  return answers.map((answer) => answer.address)
}

/**
 * The two ways `ipv4only.arpa`'s AAAA answers are asked for (RFC 7050):
 * the operating system's resolver, as the page's name was looked up, which
 * returns what a DNS64 in its path synthesized; and a DNS query of its own
 * (c-ares), whose NXDOMAIN or NODATA is the only proof that no AAAA record
 * exists. getaddrinfo's failure proves nothing: Node documents that its
 * ENOTFOUND may stand for other failures of the lookup.
 */
export interface Nat64Lookups {
  readonly system: () => Promise<readonly string[]>
  readonly dns: () => Promise<readonly string[]>
}

async function lookupSystem(): Promise<readonly string[]> {
  const answers = await lookup(NAT64_DISCOVERY_NAME, { all: true, family: ADDRESS_FAMILIES.ipv6 })
  return answers.map((answer) => answer.address)
}

async function queryDns(): Promise<readonly string[]> {
  const resolver = new Resolver({
    timeout: NAT64_DISCOVERY_TIMEOUT_MS,
    tries: NAT64_DISCOVERY_TRIES,
  })
  return await resolver.resolve6(NAT64_DISCOVERY_NAME)
}

const NAT64_LOOKUPS: Nat64Lookups = { system: lookupSystem, dns: queryDns }

function codeOf(error: unknown): string {
  return typeof error === 'object' && error !== null && 'code' in error
    ? String(error.code)
    : 'error'
}

function answersOf(outcome: PromiseSettledResult<readonly string[]>): readonly string[] {
  return outcome.status === 'fulfilled' ? outcome.value : []
}

function outcomeText(outcome: PromiseSettledResult<readonly string[]>): string {
  return outcome.status === 'fulfilled' ? 'no answer' : codeOf(outcome.reason)
}

/**
 * The network's NAT64 prefixes (RFC 7050), from the answers either lookup
 * returned. With none, only the DNS query's NXDOMAIN or NODATA means no
 * DNS64; any other outcome (a timeout, SERVFAIL, a refusal, no servers
 * found), or answers that carry no RFC 6052 prefix, leave NAT64 unknown,
 * and the fetch then uses no IPv6 answer, since any could carry a private
 * address.
 */
export async function discoverNat64(lookups: Nat64Lookups, log: Logger): Promise<Nat64Discovery> {
  const [system, dns] = await Promise.allSettled([lookups.system(), lookups.dns()])
  const answers = [...answersOf(system), ...answersOf(dns)]
  if (answers.length > 0) {
    const prefixes = nat64PrefixesOf(answers)
    if (prefixes.length > 0) {
      return { isKnown: true, prefixes }
    }
    const shown = answers.join(', ')
    log.info(
      `Web fetch: ${NAT64_DISCOVERY_NAME} answered ${shown}, which carries no NAT64 prefix; IPv6 answers are not used`,
    )
    return { isKnown: false, detail: `${NAT64_DISCOVERY_NAME}: ${shown}` }
  }
  const outcome = `${NAT64_DISCOVERY_NAME}: DNS ${outcomeText(dns)}, system ${outcomeText(system)}`
  if (dns.status === 'rejected' && NAT64_ABSENT_CODES.has(codeOf(dns.reason))) {
    log.trace(`Web fetch: no NAT64 prefix (${outcome})`)
    return { isKnown: true, prefixes: [] }
  }
  log.info(`Web fetch: NAT64 discovery failed (${outcome}); IPv6 answers are not used`)
  return { isKnown: false, detail: outcome }
}

function hostOf(url: string): string {
  try {
    return new URL(url).host
  } catch {
    return '(not a URL)'
  }
}

function outcomeOf(result: WebFetchResult): string {
  switch (result.kind) {
    case 'page': {
      const { page } = result
      return `HTTP ${String(page.status)}, ${page.type}, ${String(page.bytes)} bytes`
    }
    case 'moved': {
      return `redirected to another host (${hostOf(result.location)}); handed back to the model`
    }
    case 'failed': {
      return `refused or failed: ${result.failure.kind}`
    }
  }
}

/**
 * The window's fetch: `convertHtml` turns an HTML page into Markdown apart
 * from the extension host (pageConverter.ts).
 */
export function createWebFetcher(
  log: Logger,
  convertHtml: HtmlConverter,
  nat64Lookups: Nat64Lookups = NAT64_LOOKUPS,
): WebFetcher {
  return async (url, signal, isStillAllowed) => {
    const result = await fetchWebPage(
      url,
      {
        resolve: resolveAll,
        nat64: async () => await discoverNat64(nat64Lookups, log),
        request: pinnedHttpsRequest,
        convertHtml,
        newMarker: () => randomBytes(WEB_FETCH_MARKER_BYTES).toString('hex'),
      },
      signal,
      isStillAllowed,
    )
    log.info(`Web fetch from ${hostOf(url)}: ${outcomeOf(result)}`)
    return result
  }
}

src/host/worktreeFeatures.ts:
// The VS Code side of "New worktree…" and "Remove worktree…" (M32, PLAN.md
// D30): the input box, the picks, the confirmations and the new window.
// The flows live in commands/worktreeCommands.ts.

import { existsSync } from 'node:fs'
import * as vscode from 'vscode'
import { UI_TEXT, VSCODE_COMMANDS } from '../shared/constants'
import { newWorktree, removeWorktree, type WorktreeDeps } from './commands/worktreeCommands'
import type { Logger } from './logger'
import { loggedPopups } from './popups'

export interface WorktreeFeatureDeps {
  readonly workspaceRoot: string | undefined
  /** git by absolute path (git.ts), with an optional per-call timeout. */
  readonly runGit: (args: readonly string[], cwd: string, timeoutMs?: number) => Promise<string>
  /** Exact add/remove forms can run repository hooks; admit them before Git starts. */
  readonly mutationGit: (
    args: readonly string[],
    cwd: string,
    timeoutMs?: number,
  ) => Promise<string>
  readonly log: Logger
}

export interface WorktreeFeatures {
  newWorktree(): Promise<void>
  removeWorktree(): Promise<void>
}

export function createWorktreeFeatures(deps: WorktreeFeatureDeps): WorktreeFeatures {
  const flowDeps = (): WorktreeDeps => ({
    workspaceRoot: deps.workspaceRoot,
    platform: process.platform,
    isWorkspaceTrusted: () => vscode.workspace.isTrusted,
    runGit: (args, cwd, timeoutMs) =>
      args[0] === 'worktree' && (args[1] === 'add' || args[1] === 'remove')
        ? deps.mutationGit(args, cwd, timeoutMs)
        : deps.runGit(args, cwd, timeoutMs),
    pathExists: existsSync,
    askBranchName: (validate) =>
      Promise.resolve(
        vscode.window.showInputBox({
          title: UI_TEXT.worktreeBranchPrompt,
          placeHolder: UI_TEXT.worktreeBranchPlaceholder,
          ignoreFocusOut: true,
          validateInput: validate,
        }),
      ),
    pick: async (items, title, placeholder) => {
      const choice = await vscode.window.showQuickPick(
        items.map((item) => ({ ...item })),
        { title, placeHolder: placeholder, matchOnDescription: true },
      )
      return choice?.id
    },
    confirm: async (message, detail, action) =>
      (await vscode.window.showWarningMessage(message, { modal: true, detail }, action)) === action,
    offerOpen: async (message) =>
      (await vscode.window.showInformationMessage(message, UI_TEXT.worktreeOpen)) ===
      UI_TEXT.worktreeOpen,
    openFolder: async (fsPath) => {
      await vscode.commands.executeCommand(VSCODE_COMMANDS.openFolder, vscode.Uri.file(fsPath), {
        forceNewWindow: true,
      })
    },
    showInformation: (message) => {
      void vscode.window.showInformationMessage(message)
    },
    ...loggedPopups(deps.log),
    log: deps.log,
  })
  return {
    newWorktree: () => newWorktree(flowDeps()),
    removeWorktree: () => removeWorktree(flowDeps()),
  }
}

