src/shared/effort.ts:
// Reasoning-effort helpers shared by the composer (labels, slider steps) and
// the conversation controller (the wire value sent to the host).

import {
  EFFORT_LEVELS,
  type EffortLevel,
  MODEL_EFFORT_LEVELS,
  THINKING_OFF_EFFORT,
  UI_TEXT,
} from './constants'

export function isEffortLevel(value: string): value is EffortLevel {
  return (EFFORT_LEVELS as readonly string[]).includes(value)
}

export function effortLabel(effort: EffortLevel): string {
  return UI_TEXT.effortLevels[effort]
}

/**
 * The MSP `ReasoningEffort` for the session: the chosen tier while Thinking
 * is on, `none` while it is off. The chosen tier is kept so switching
 * Thinking back on restores it.
 */
export function effortForThinking(effort: EffortLevel, isThinkingEnabled: boolean): string {
  return isThinkingEnabled ? effort : THINKING_OFF_EFFORT
}

/**
 * The tiers a model serves (verified live per model family, see
 * MODEL_EFFORT_LEVELS); the full UI range when the model is unknown or not
 * yet reported, so the slider never offers less than the CLI does.
 */
export function effortLevelsFor(modelId: string | undefined): readonly EffortLevel[] {
  if (modelId === undefined) {
    return EFFORT_LEVELS
  }
  const family = Object.keys(MODEL_EFFORT_LEVELS).find((prefix) => modelId.startsWith(prefix))
  return family === undefined ? EFFORT_LEVELS : (MODEL_EFFORT_LEVELS[family] ?? EFFORT_LEVELS)
}

/** Slider position (0-based) for a tier; -1 when the model does not serve it. */
export function effortIndex(levels: readonly EffortLevel[], effort: EffortLevel): number {
  return levels.indexOf(effort)
}

/** The tier at a slider position, clamped to the ends. */
export function effortAt(levels: readonly EffortLevel[], index: number): EffortLevel {
  const clamped = Math.min(Math.max(index, 0), levels.length - 1)
  return levels[clamped] ?? EFFORT_LEVELS[0]
}

src/shared/l10n/check.ts:
// How a translation is checked against English (PLAN.md D33). The host runs
// the shape checks on the table it loads, so a damaged file falls back to
// English instead of showing broken text; the l10n gate
// (`scripts/check-l10n.mjs`) runs them strictly on every table it ships.

import { isPluralForms, type PluralCategory, type PluralForms } from './forms'

const SLOT = /\{(\w+)\}/g
const CODE_SPAN = /`/g
const BOLD = /\*\*/g

export interface CheckOptions {
  /** The table's language: its plural categories come from `Intl.PluralRules`. */
  readonly locale: string
  /**
   * The gate's checks on top of the shape: exactly the language's plural
   * categories, the same code spans and bold markers, and no value left in
   * English unless its key is in `untranslated`.
   */
  readonly isStrict: boolean
  /** Dotted keys whose value may equal the English (names, commands, …). */
  readonly untranslated?: ReadonlySet<string>
}

function byText(left: string, right: string): number {
  return left.localeCompare(right)
}

function slotsOf(text: string): readonly string[] {
  const names = new Set(Array.from(text.matchAll(SLOT), (match) => match[1] ?? ''))
  return [...names].toSorted(byText)
}

function countOf(text: string, pattern: RegExp): number {
  return text.split(pattern).length - 1
}

function isSameList(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((item, index) => item === right[index])
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function stringProblems(
  key: string,
  english: string,
  value: string,
  options: CheckOptions,
): readonly string[] {
  const problems: string[] = []
  const expected = slotsOf(english)
  const found = slotsOf(value)
  if (!isSameList(expected, found)) {
    problems.push(
      `${key}: slots {${expected.join('}, {')}} expected, found {${found.join('}, {')}}`,
    )
  }
  if (!options.isStrict) {
    return problems
  }
  if (countOf(english, CODE_SPAN) !== countOf(value, CODE_SPAN)) {
    problems.push(`${key}: the code spans (\`) differ from the English`)
  }
  if (countOf(english, BOLD) !== countOf(value, BOLD)) {
    problems.push(`${key}: the bold markers (**) differ from the English`)
  }
  if (value === english && english.trim() !== '' && options.untranslated?.has(key) !== true) {
    problems.push(`${key}: left in English`)
  }
  return problems
}

function formsProblems(
  key: string,
  english: PluralForms,
  value: unknown,
  options: CheckOptions,
): readonly string[] {
  if (!isPluralForms(value)) {
    return [`${key}: plural forms expected (an object with "other")`]
  }
  const problems: string[] = []
  // Parsed JSON: the category keys are checked, their values are not yet.
  const forms: Readonly<Record<string, unknown>> = value
  // An allowlisted entry may keep every form in English.
  const formOptions = (formKey: string): CheckOptions =>
    options.untranslated?.has(key) === true
      ? { ...options, untranslated: new Set([formKey]) }
      : options
  for (const [category, text] of Object.entries(forms)) {
    const formKey = `${key}.${category}`
    if (typeof text !== 'string') {
      problems.push(`${formKey}: text expected`)
      continue
    }
    // Each form is checked like a string against its English form, or
    // `other` for a category English lacks: every slot kept (Russian's
    // `one` also covers 21, so it cannot drop `{count}`), and strictly the
    // code spans, the bold markers and no English left behind.
    const englishForm =
      Object.entries(english).find(([name]) => name === category)?.[1] ?? english.other
    problems.push(...stringProblems(formKey, englishForm, text, formOptions(formKey)))
  }
  if (options.isStrict) {
    const categories: readonly PluralCategory[] = new Intl.PluralRules(options.locale)
      .resolvedOptions()
      .pluralCategories.toSorted(byText)
    const found = Object.keys(forms).toSorted(byText)
    if (!isSameList(categories, found)) {
      problems.push(
        `${key}: ${options.locale} uses the forms ${categories.join(', ')}; found ${found.join(', ')}`,
      )
    }
  }
  return problems
}

function groupProblems(
  prefix: string,
  english: Readonly<Record<string, unknown>>,
  table: Readonly<Record<string, unknown>>,
  options: CheckOptions,
): readonly string[] {
  const problems: string[] = []
  for (const name of Object.keys(table)) {
    if (!Object.hasOwn(english, name)) {
      problems.push(`${prefix}${name}: not in the English table`)
    }
  }
  for (const [name, englishValue] of Object.entries(english)) {
    const key = `${prefix}${name}`
    const value = table[name]
    if (value === undefined) {
      problems.push(`${key}: missing`)
    } else if (typeof englishValue === 'string') {
      problems.push(
        ...(typeof value === 'string'
          ? stringProblems(key, englishValue, value, options)
          : [`${key}: text expected`]),
      )
    } else if (isPluralForms(englishValue)) {
      problems.push(...formsProblems(key, englishValue, value, options))
    } else if (isRecord(englishValue)) {
      problems.push(
        ...(isRecord(value)
          ? groupProblems(`${key}.`, englishValue, value, options)
          : [`${key}: a group of labels expected`]),
      )
    }
  }
  return problems
}

/** Every way `table` differs from `english` in shape (and, strictly, in content). */
export function tableProblems(
  english: Readonly<Record<string, unknown>>,
  table: unknown,
  options: CheckOptions,
): readonly string[] {
  return isRecord(table)
    ? groupProblems('', english, table, options)
    : ['the table is not a JSON object']
}

src/shared/l10n/forms.ts:
// Count-dependent strings (PLAN.md D33): one form per plural category the
// language uses, as `Intl.PluralRules` names them. English uses `one` and
// `other`; Russian, Polish and Czech add `few` and `many`.

export type PluralCategory = Intl.LDMLPluralRule

export type PluralForms = Readonly<Partial<Record<PluralCategory, string>>> & {
  readonly other: string
}

const PLURAL_CATEGORIES: ReadonlySet<string> = new Set<PluralCategory>([
  'zero',
  'one',
  'two',
  'few',
  'many',
  'other',
])

/** Marks an entry of the table as plural forms rather than a group of labels. */
export function forms(entry: PluralForms): PluralForms {
  return entry
}

/** Whether a table value is plural forms: only category keys, `other` among them. */
export function isPluralForms(value: unknown): value is PluralForms {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const keys = Object.keys(value)
  return keys.includes('other') && keys.every((key) => PLURAL_CATEGORIES.has(key))
}

src/shared/l10n/locales.ts:
// Which display languages have a translated table, and where it lives
// (PLAN.md D33). The ids are VS Code's own (`vscode.env.language`), lower
// case. English is the base in `en.ts` and needs no file; these are the
// fourteen other languages VS Code ships (M40b), machine-translated.

export const TABLE_LOCALES: readonly string[] = [
  'zh-cn',
  'zh-tw',
  'ja',
  'ko',
  'de',
  'fr',
  'es',
  'pt-br',
  'ru',
  'it',
  'tr',
  'pl',
  'cs',
  'hu',
]

/** The packaged folder that holds the translated tables. */
export const TABLE_DIRECTORY = 'l10n'

/** A table's file name inside `TABLE_DIRECTORY`. */
export function tableFileName(locale: string): string {
  return `ui.${locale}.json`
}

/**
 * The table for VS Code's display language: the exact id (`pt-br`, `zh-tw`),
 * else its primary language when that has a table of its own (`de-ch` reads
 * `de`); undefined means English.
 */
export function tableLocaleFor(
  language: string,
  locales: readonly string[] = TABLE_LOCALES,
): string | undefined {
  const id = language.toLowerCase()
  if (locales.includes(id)) {
    return id
  }
  const primary = id.split('-', 1)[0] ?? id
  return locales.includes(primary) ? primary : undefined
}

src/shared/l10n/text.ts:
// The table the extension shows, and the helpers that fill it in the display
// language (PLAN.md D33). `UI_TEXT` starts as English; the host installs the
// user's table at activation and hands the same table to each webview, which
// installs it before its first render. Everything reads `UI_TEXT.key` when
// it runs, never at module load, so the installed table is the one shown.

import { EN, type UiText } from './en'
import type { PluralForms } from './forms'

export const BASE_LOCALE = 'en'
const PERCENT_DIVISOR = 100
// `{name}`: a slot a template leaves for `fill`.
const SLOT = /\{(\w+)\}/g

interface LocaleState {
  locale: string
  pluralRules: Intl.PluralRules
  relativeTimes: Intl.RelativeTimeFormat
  dates: Intl.DateTimeFormat
  dateTimes: Intl.DateTimeFormat
  readonly formatters: Map<string, Intl.NumberFormat>
}

function stateFor(locale: string, formatters: Map<string, Intl.NumberFormat>): LocaleState {
  return {
    locale,
    pluralRules: new Intl.PluralRules(locale),
    relativeTimes: new Intl.RelativeTimeFormat(locale, { numeric: 'auto', style: 'short' }),
    dates: new Intl.DateTimeFormat(locale, { dateStyle: 'medium' }),
    dateTimes: new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeStyle: 'short' }),
    formatters,
  }
}

// The installed language's rules and formatters, replaced by `setUiText`.
const current: LocaleState = stateFor(BASE_LOCALE, new Map())

/** What the user reads, in the display language once `setUiText` has run. */
export const UI_TEXT: UiText = { ...EN }

/** Installs a checked table and the language whose plural and number rules apply. */
export function setUiText(table: UiText, tableLocale: string): void {
  Object.assign(UI_TEXT, table)
  current.formatters.clear()
  Object.assign(current, stateFor(tableLocale, current.formatters))
}

/** The BCP 47 tag of the installed table (`en`, `de`, `zh-cn`, …). */
export function uiLocale(): string {
  return current.locale
}

export type TemplateValues = Readonly<Record<string, string | number>>

function numberFormat(key: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const cached = current.formatters.get(key)
  if (cached !== undefined) {
    return cached
  }
  const created = new Intl.NumberFormat(current.locale, options)
  current.formatters.set(key, created)
  return created
}

/** A count in the display language's digits and grouping: 1,234 / 1.234 / 1 234. */
export function formatNumber(value: number): string {
  return numberFormat('number', {}).format(value)
}

/** A whole percentage, as the language writes one: 42% / 42 % / %42. */
export function formatPercent(percent: number): string {
  return numberFormat('percent', { style: 'percent', maximumFractionDigits: 0 }).format(
    percent / PERCENT_DIVISOR,
  )
}

/** An amount of US dollars as the language writes money: $1.46 / 1,46 $ / US$1.46. */
export function formatUsd(amount: number, fractionDigits: number): string {
  return numberFormat(`usd:${String(fractionDigits)}`, {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(amount)
}

// Decimal sizes, as Intl's byte units are named (kB, MB).
const BYTES_PER_KILOBYTE = 1000
const BYTES_PER_MEGABYTE = BYTES_PER_KILOBYTE * BYTES_PER_KILOBYTE
const SIZE_FRACTION_DIGITS = 1

/** A size as the language writes one, in the largest unit below it: 512 byte / 48.2 kB / 5.2 MB. */
export function formatBytes(bytes: number): string {
  let unit = 'byte'
  let value = bytes
  if (bytes >= BYTES_PER_MEGABYTE) {
    unit = 'megabyte'
    value = bytes / BYTES_PER_MEGABYTE
  } else if (bytes >= BYTES_PER_KILOBYTE) {
    unit = 'kilobyte'
    value = bytes / BYTES_PER_KILOBYTE
  }
  return numberFormat(`bytes:${unit}`, {
    style: 'unit',
    unit,
    unitDisplay: 'short',
    maximumFractionDigits: SIZE_FRACTION_DIGITS,
  }).format(value)
}

export type DurationUnit = 'second' | 'minute' | 'hour' | 'day'

/** A short amount of time in one unit: 3s / 3 Sek. / 3秒. */
export function formatUnit(value: number, unit: DurationUnit): string {
  return numberFormat(`unit:${unit}`, {
    style: 'unit',
    unit,
    unitDisplay: 'narrow',
  }).format(value)
}

/** "5 min. ago", "yesterday": a signed amount of time relative to now. */
export function formatRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit): string {
  return current.relativeTimes.format(value, unit)
}

/** A calendar date in the display language. */
export function formatDate(epochMs: number): string {
  return current.dates.format(epochMs)
}

/** A local calendar date and time in the installed language. */
export function formatDateTime(epochMs: number): string {
  return current.dateTimes.format(epochMs)
}

/** The template with each `{slot}` replaced; numbers are formatted, unknown slots stay. */
export function fill(template: string, values: TemplateValues): string {
  return template.replaceAll(SLOT, (whole, name: string) => {
    const value = values[name]
    if (value === undefined) {
      return whole
    }
    return typeof value === 'number' ? formatNumber(value) : value
  })
}

/** The form the language uses for `count`, filled with `count` and any other slots. */
export function plural(entry: PluralForms, count: number, values: TemplateValues = {}): string {
  const form = entry[current.pluralRules.select(count)] ?? entry.other
  return fill(form, { count, ...values })
}

export type TemplatePart = string | { readonly slot: string }

/** A template split around its slots, for a view that renders a slot as markup. */
export function templateParts(template: string): readonly TemplatePart[] {
  const parts: TemplatePart[] = []
  let last = 0
  for (const match of template.matchAll(SLOT)) {
    if (match.index > last) {
      parts.push(template.slice(last, match.index))
    }
    parts.push({ slot: match[1] ?? '' })
    last = match.index + match[0].length
  }
  if (last < template.length) {
    parts.push(template.slice(last))
  }
  return parts
}

src/shared/mentions.ts:
// `@` mentions: how the extension writes them and how the composer reads
// them back. Pure and shared so the webview drives the menu and the host
// writes the same syntax.
//
// A mention starts with `@` at the beginning of the text or after
// whitespace. The Claude Code form is `@path` with an optional line range,
// `#start` or `#start-end` (`@src/app.ts#5-10`); its path stops at the first
// space (anthropics/claude-code#4012). A path holding whitespace, `#` or `"`
// is therefore quoted, the range after the closing quote
// (`@"my notes/a#1.md"#5-10`); inside the quotes `\"` is a quote and `\\`
// a backslash, and a line break ends an unclosed quote (PLAN.md D27). The
// composer's menu is open while the caret sits at the end of a mention, and
// searches for the path as written inside the quotes, spaces included.

export interface MentionQuery {
  /** Offset of the `@`. */
  readonly start: number
  /** Offset just past the token (the caret, since the token ends there). */
  readonly end: number
  /** The path the token names (unquoted, without its line range), possibly empty. */
  readonly query: string
}

/** 1-based, inclusive. */
export interface MentionLines {
  readonly startLine: number
  readonly endLine: number
}

interface MentionToken {
  readonly start: number
  readonly end: number
  readonly path: string
}

const MENTION = '@'
const QUOTE = '"'
const ESCAPE = '\\'
const FRAGMENT = '#'
const WHITESPACE = /\s/
const LINE_BREAK = /[\r\n]/
const NEEDS_QUOTES = /[\s#"]/
const ESCAPED_IN_QUOTES = /["\\]/g

function isTokenStart(text: string, index: number): boolean {
  return index === 0 || WHITESPACE.test(text.charAt(index - 1))
}

/** The `@` mention of `path`, quoted when it must be, with the lines when given. */
export function formatMention(path: string, lines?: MentionLines): string {
  const written = NEEDS_QUOTES.test(path)
    ? `${QUOTE}${path.replaceAll(ESCAPED_IN_QUOTES, (char) => `${ESCAPE}${char}`)}${QUOTE}`
    : path
  if (lines === undefined) {
    return `${MENTION}${written}`
  }
  const start = String(lines.startLine)
  const range = lines.startLine === lines.endLine ? start : `${start}-${String(lines.endLine)}`
  return `${MENTION}${written}${FRAGMENT}${range}`
}

/** A quoted path from the opening quote at `open`: the path and where the quotes end. */
function readQuoted(text: string, open: number): { readonly path: string; readonly end: number } {
  let path = ''
  let index = open + 1
  while (index < text.length) {
    const char = text.charAt(index)
    const next = text.charAt(index + 1)
    if (char === QUOTE) {
      return { path, end: index + 1 }
    }
    if (LINE_BREAK.test(char)) {
      break
    }
    if (char === ESCAPE && (next === QUOTE || next === ESCAPE)) {
      path += next
      index += 2
      continue
    }
    path += char
    index += 1
  }
  return { path, end: index }
}

/** Where a run of characters that are neither whitespace nor `stop` ends. */
function runEnd(text: string, from: number, stop = ''): number {
  let index = from
  while (index < text.length) {
    const char = text.charAt(index)
    if (char === stop || WHITESPACE.test(char)) {
      break
    }
    index += 1
  }
  return index
}

/** The mention whose `@` is at `at`: its path, then its line range if any. */
function readMention(text: string, at: number): MentionToken {
  const open = at + 1
  const quoted = text.charAt(open) === QUOTE ? readQuoted(text, open) : undefined
  const pathEnd = quoted?.end ?? runEnd(text, open, FRAGMENT)
  const path = quoted?.path ?? text.slice(open, pathEnd)
  const end = text.charAt(pathEnd) === FRAGMENT ? runEnd(text, pathEnd + 1) : pathEnd
  return { start: at, end, path }
}

/** The last mention in `text`, read from the start so a quoted one's spaces stay inside it. */
function lastMention(text: string): MentionToken | undefined {
  let last: MentionToken | undefined
  let index = 0
  while (index < text.length) {
    if (text.charAt(index) === MENTION && isTokenStart(text, index)) {
      last = readMention(text, index)
      index = last.end
    } else {
      index += 1
    }
  }
  return last
}

/** The mention token the caret is at the end of, or undefined when there is none. */
export function mentionQueryAt(text: string, caret: number): MentionQuery | undefined {
  const token = lastMention(text.slice(0, caret))
  if (token?.end !== caret) {
    return undefined
  }
  // The caret must be at the end of the token, not inside a longer word.
  const next = text.charAt(caret)
  const isTokenEnd = next === '' || WHITESPACE.test(next)
  return isTokenEnd ? { start: token.start, end: caret, query: token.path } : undefined
}

/** Replace the token with the path's mention and a space, and report where the caret lands. */
export function applyMention(
  text: string,
  query: MentionQuery,
  path: string,
): { readonly text: string; readonly caret: number } {
  const replacement = `${formatMention(path)} `
  const updated = text.slice(0, query.start) + replacement + text.slice(query.end)
  return { text: updated, caret: query.start + replacement.length }
}

/**
 * The slash command a draft is typing, when the whole draft is one `/token`:
 * `''` for a bare `/` (the composer shows the palette), else the name so far
 * (the composer's "/" list, M38). `/compact args` is a command with
 * arguments, not a filter, so it returns undefined.
 */
export function slashFilterOf(text: string): string | undefined {
  const match = /^\/(\S*)$/.exec(text)
  return match?.[1]
}

export interface SkillInvocation {
  readonly selector: string
  readonly arguments: string | undefined
}

/**
 * Splits `/selector rest of text` into a skill invocation when `selector` is
 * one the host listed; any other leading slash is ordinary prompt text.
 */
export function parseSkillInvocation(
  text: string,
  knownSelectors: ReadonlySet<string>,
): SkillInvocation | undefined {
  const match = /^\/(\S+)(?:\s+([\s\S]*))?$/.exec(text.trim())
  const selector = match?.[1]
  if (selector === undefined || !knownSelectors.has(selector)) {
    return undefined
  }
  const rest = match?.[2]?.trim()
  return { selector, arguments: rest === undefined || rest === '' ? undefined : rest }
}

src/shared/paid.ts:
// The paid Model API features (M33–M35, PLAN.md D30) as the host, the wire
// protocol and the webview share them: which are on, what this window has
// used, and what that is estimated to cost at Meta's published prices.
//
// Shared by host and webview: no `vscode`, Node, or DOM imports.

import * as z from 'zod/mini'
import {
  BEST_OF_N_DEFAULT_ATTEMPTS,
  BEST_OF_N_DEFAULT_REQUESTS_PER_ATTEMPT,
  MUSE_CODE_PAID_FEATURES,
  DEFAULT_MODEL_ID,
  CONTRIBUTOR_MODEL_SUFFIX,
  MODEL_API_PRICED_MODELS,
  MODEL_API_PRICES_PER_MILLION,
  MODEL_API_PRICE_DECIMALS,
  PAID_FEATURES,
  PAID_PRICES_USD,
  type PaidFeature,
  SEARCHES_PER_PRICE_UNIT,
  SECONDS_PER_HOUR,
  SUBAGENT_TASK_MAX_REQUESTS,
  UI_TEXT,
} from './constants'
import { fill, formatNumber, formatUsd } from './l10n/text'
import type { BackendKind } from './protocol'

/** What this window used of each paid feature since it opened. */
export const paidTallySchema = z.object({
  webSearches: z.number(),
  images: z.number(),
  voiceSeconds: z.number(),
  scheduledRuns: z.number(),
  // Optional for panels saved before M48; absent means no child use recorded.
  subagentRequests: z.optional(z.int().check(z.nonnegative())),
  subagentUnknownRequests: z.optional(z.int().check(z.nonnegative())),
  subagentTokens: z.optional(z.int().check(z.nonnegative())),
  subagentCostUsd: z.optional(z.number().check(z.nonnegative())),
  // Optional for panels saved before M78; absent means no review made.
  autoReviews: z.optional(z.int().check(z.nonnegative())),
  autoReviewUnknownRequests: z.optional(z.int().check(z.nonnegative())),
  autoReviewTokens: z.optional(z.int().check(z.nonnegative())),
  autoReviewCostUsd: z.optional(z.number().check(z.nonnegative())),
  // Best-of-N runs started this window (M77); absent means none.
  bestOfNAttempts: z.optional(z.int().check(z.nonnegative())),
  bestOfNRequests: z.optional(z.int().check(z.nonnegative())),
  bestOfNUnknownRequests: z.optional(z.int().check(z.nonnegative())),
  bestOfNTokens: z.optional(z.int().check(z.nonnegative())),
  bestOfNCostUsd: z.optional(z.number().check(z.nonnegative())),
})
export type PaidTally = z.infer<typeof paidTallySchema>

export const EMPTY_PAID_TALLY: PaidTally = {
  webSearches: 0,
  images: 0,
  voiceSeconds: 0,
  scheduledRuns: 0,
}

export interface SubagentTaskConfirmation {
  readonly role: string
  readonly objective: string
  readonly modelId: string
  readonly attemptLimit: number
}

export interface SubagentUsage {
  readonly inputTokens: number
  readonly outputTokens: number
  readonly cachedTokens: number
}

/** Unknown model tariffs cannot authorize a paid child task. */
export function modelApiPaidTier(
  modelId: string,
): keyof typeof MODEL_API_PRICES_PER_MILLION | undefined {
  const standard: readonly string[] = MODEL_API_PRICED_MODELS.standard
  if (standard.includes(modelId)) {
    return 'standard'
  }
  const contributor: readonly string[] = MODEL_API_PRICED_MODELS.contributor
  return contributor.includes(modelId) ? 'contributor' : undefined
}

/** Exact published rates and the task's HTTP attempt cap, in the installed locale. */
export function subagentTaskPrice(modelId: string, attemptLimit: number): string {
  const tier = modelApiPaidTier(modelId)
  if (tier === undefined) {
    return UI_TEXT.subagentTariffUnknown
  }
  const rates = MODEL_API_PRICES_PER_MILLION[tier]
  return fill(UI_TEXT.paidSubagentRates, {
    model: modelId,
    input: formatUsd(rates.input, MODEL_API_PRICE_DECIMALS),
    cached: formatUsd(rates.cachedInput, MODEL_API_PRICE_DECIMALS),
    output: formatUsd(rates.output, MODEL_API_PRICE_DECIMALS),
    limit: formatNumber(attemptLimit),
  })
}

/** The features that are on (setting on and price accepted), and the tally. */
export const paidStateSchema = z.object({
  features: z.array(z.enum(PAID_FEATURES)),
  tally: paidTallySchema,
  /** A Model API key is stored (M44): the Muse Code backend can use the key's paid features. */
  isKeyStored: z.boolean(),
  /** The features that are on and allowed always in this workspace (M58): they no longer ask. */
  alwaysAllowed: z.array(z.enum(PAID_FEATURES)),
})
export type PaidState = z.infer<typeof paidStateSchema>

/**
 * One paid use the user is asked about (M58, PLAN.md D48): what the popup
 * names before anything is billed. Web search asks once per prompt, since
 * Meta runs the searches inside the response and the model decides whether
 * to search at all.
 */
export type PaidUseRequest =
  | { readonly feature: 'webSearch' }
  | { readonly feature: 'voice' }
  | {
      readonly feature: 'imageGeneration'
      readonly kind: 'generate' | 'edit'
      /** Workspace-relative paths, as the popup shows them. */
      readonly path: string
      readonly sources: readonly string[]
      readonly prompt: string
    }
  | { readonly feature: 'scheduledPrompts'; readonly prompt: string; readonly modelId: string }
  | { readonly feature: 'subagents'; readonly task: SubagentTaskConfirmation }
  | {
      readonly feature: 'autoReviewer'
      /** The conversation's model, which the review runs on (M78). */
      readonly modelId: string
      /** The tool the reviewed call is for, and its command line or arguments. */
      readonly tool: string
      readonly action: string
    }
  | {
      readonly feature: 'bestOfN'
      readonly modelId: string
      readonly prompt: string
      readonly attempts: number
      readonly requestCeilingPerAttempt: number
    }

/**
 * The paid features a window can use (M44, PLAN.md D37): every one on the
 * Model API backend; on Muse Code, the ones billed to a stored key that it
 * has no subscription equivalent for; none otherwise.
 */
export function usablePaidFeatures(
  backend: BackendKind | undefined,
  isKeyStored: boolean,
): readonly PaidFeature[] {
  if (backend === 'modelApi') {
    return PAID_FEATURES
  }
  return backend === 'museCode' && isKeyStored ? MUSE_CODE_PAID_FEATURES : []
}

/** The estimated cost of one feature's use in the tally, in dollars. */
export function paidCostUsd(feature: PaidFeature, tally: PaidTally): number {
  switch (feature) {
    case 'webSearch': {
      return (tally.webSearches * PAID_PRICES_USD.webSearchPerThousand) / SEARCHES_PER_PRICE_UNIT
    }
    case 'imageGeneration': {
      return tally.images * PAID_PRICES_USD.imageGeneration
    }
    case 'voice': {
      return (tally.voiceSeconds * PAID_PRICES_USD.voicePerHour) / SECONDS_PER_HOUR
    }
    case 'scheduledPrompts': {
      // Scheduled runs use ordinary Model API tokens. UsageDialog prices those
      // tokens already; adding them to the extra-features total doubles them.
      return 0
    }
    case 'subagents': {
      return tally.subagentCostUsd ?? 0
    }
    case 'autoReviewer': {
      // Billed apart from the conversation, so counted here alone.
      return tally.autoReviewCostUsd ?? 0
    }
    case 'bestOfN': {
      // Separate worktree hosts do not contribute to the parent's token
      // estimate. Count only reported costs here, not unknown HTTP tries.
      return tally.bestOfNCostUsd ?? 0
    }
  }
}

/**
 * The paid features Account & usage lists (the review of PR #30): the ones
 * this backend can use, and any this window has already used, whatever the
 * backend now, so its total is the sum of the rows it shows.
 */
export function listedPaidFeatures(
  usable: readonly PaidFeature[],
  tally: PaidTally,
): readonly PaidFeature[] {
  return PAID_FEATURES.filter(
    (feature) =>
      usable.includes(feature) ||
      paidCostUsd(feature, tally) > 0 ||
      (feature === 'scheduledPrompts' && tally.scheduledRuns > 0) ||
      (feature === 'subagents' && (tally.subagentRequests ?? 0) > 0) ||
      (feature === 'autoReviewer' && (tally.autoReviews ?? 0) > 0) ||
      (feature === 'bestOfN' && (tally.bestOfNAttempts ?? 0) > 0),
  )
}

/** The whole tally's estimated cost. */
export function paidTotalUsd(tally: PaidTally): number {
  // Child token cost is already part of the conversation's token estimate.
  let total = 0
  for (const feature of PAID_FEATURES) {
    if (feature !== 'subagents') {
      total += paidCostUsd(feature, tally)
    }
  }
  return total
}

// Built per call, never at module load: the display language's table is
// installed after this module loads (PLAN.md D33).

/** The feature's short name, as the badge and the dialog show it. */
export function paidFeatureName(feature: PaidFeature): string {
  const names: Readonly<Record<PaidFeature, string>> = {
    webSearch: UI_TEXT.paidWebSearchName,
    imageGeneration: UI_TEXT.paidImageGenerationName,
    voice: UI_TEXT.paidVoiceName,
    scheduledPrompts: UI_TEXT.paidScheduledName,
    subagents: UI_TEXT.paidSubagentsName,
    autoReviewer: UI_TEXT.paidAutoReviewerName,
    bestOfN: UI_TEXT.paidBestOfNName,
  }
  return names[feature]
}

function tokenRatePrice(tier: keyof typeof MODEL_API_PRICES_PER_MILLION): string {
  const rates = MODEL_API_PRICES_PER_MILLION[tier]
  return fill(UI_TEXT.paidScheduledPrice, {
    input: formatUsd(rates.input, MODEL_API_PRICE_DECIMALS),
    cached: formatUsd(rates.cachedInput, MODEL_API_PRICE_DECIMALS),
    output: formatUsd(rates.output, MODEL_API_PRICE_DECIMALS),
  })
}

/** Exact scheduled-run tariff; unknown models cannot authorize a paid request. */
export function scheduledRunPrice(modelId: string): string {
  const tier = modelApiPaidTier(modelId)
  if (tier === undefined) {
    throw new Error(UI_TEXT.subagentTariffUnknown)
  }
  return tokenRatePrice(tier)
}

/** One Auto review's tariff on the conversation's model (M78); undefined without a verified price. */
export function autoReviewPrice(modelId: string): string | undefined {
  const tier = modelApiPaidTier(modelId)
  return tier === undefined ? undefined : tokenRatePrice(tier)
}

/** Every priced model's token rates, one tier a line: a feature billed by tokens. */
function tokenRatesByTier(): string {
  return [
    `${MODEL_API_PRICED_MODELS.standard.join(', ')}: ${tokenRatePrice('standard')}`,
    `${MODEL_API_PRICED_MODELS.contributor.join(', ')}: ${tokenRatePrice('contributor')}`,
  ].join('\n')
}

/**
 * What a best-of-N run may bill (M77, PLAN.md D49): the per-token rates of
 * the model, the attempt count and the request ceiling per attempt. The
 * total cannot be known in advance, so the popup quotes exactly these.
 */
export function bestOfNPrice(
  modelId: string,
  attempts: number,
  requestCeilingPerAttempt: number,
): string {
  const tier = modelApiPaidTier(modelId)
  if (tier === undefined) {
    return UI_TEXT.subagentTariffUnknown
  }
  const rates = MODEL_API_PRICES_PER_MILLION[tier]
  return fill(UI_TEXT.paidBestOfNRates, {
    model: modelId,
    input: formatUsd(rates.input, MODEL_API_PRICE_DECIMALS),
    cached: formatUsd(rates.cachedInput, MODEL_API_PRICE_DECIMALS),
    output: formatUsd(rates.output, MODEL_API_PRICE_DECIMALS),
    attempts: formatNumber(attempts),
    limit: formatNumber(requestCeilingPerAttempt),
  })
}

/** The feature's price, as its setting, confirmation, badge and dialog state it. */
export function paidFeaturePrice(feature: PaidFeature): string {
  switch (feature) {
    case 'webSearch': {
      return fill(UI_TEXT.paidWebSearchPrice, {
        price: formatUsd(PAID_PRICES_USD.webSearchPerThousand, 2),
      })
    }
    case 'imageGeneration': {
      return fill(UI_TEXT.paidImagePrice, { price: formatUsd(PAID_PRICES_USD.imageGeneration, 2) })
    }
    case 'voice': {
      return fill(UI_TEXT.paidVoicePrice, { price: formatUsd(PAID_PRICES_USD.voicePerHour, 2) })
    }
    case 'scheduledPrompts':
    case 'autoReviewer': {
      return tokenRatesByTier()
    }
    case 'subagents': {
      return [
        subagentTaskPrice(DEFAULT_MODEL_ID, SUBAGENT_TASK_MAX_REQUESTS),
        subagentTaskPrice(
          `${DEFAULT_MODEL_ID}${CONTRIBUTOR_MODEL_SUFFIX}`,
          SUBAGENT_TASK_MAX_REQUESTS,
        ),
      ].join('\n')
    }
    case 'bestOfN': {
      return [
        bestOfNPrice(
          DEFAULT_MODEL_ID,
          BEST_OF_N_DEFAULT_ATTEMPTS,
          BEST_OF_N_DEFAULT_REQUESTS_PER_ATTEMPT,
        ),
        bestOfNPrice(
          `${DEFAULT_MODEL_ID}${CONTRIBUTOR_MODEL_SUFFIX}`,
          BEST_OF_N_DEFAULT_ATTEMPTS,
          BEST_OF_N_DEFAULT_REQUESTS_PER_ATTEMPT,
        ),
      ].join('\n')
    }
  }
}

src/shared/palette.ts:
// The "/" command palette: a registry of actions grouped the way the Claude
// Code panel groups them (Context / Model / Customize / Account & usage /
// Skills / Slash commands / Support), built from the current conversation
// state so rows can show their value, toggle or slider. Pure; the webview
// renders it and routes the chosen action.

import {
  type EffortLevel,
  type ExportFormat,
  ISSUES_URL,
  MUSE_DOCS_URL,
  type PaidFeature,
  type PermissionMode,
  RESUME_SKILL_SELECTORS,
  SKILL_IMPORT_SOURCES,
  SLASH_COMMAND_NAMES,
  type SkillImportSource,
  UI_TEXT,
} from './constants'
import { effortLabel, effortLevelsFor } from './effort'
import { fill, formatNumber } from './l10n/text'
import { paidFeatureName, paidFeaturePrice, usablePaidFeatures } from './paid'
import type { BackendKind, ModelOption, SkillOption } from './protocol'
import type { ReviewRequest } from './reviewCommand'

export type PaletteWidget =
  | { readonly kind: 'value'; readonly text: string }
  | { readonly kind: 'toggle'; readonly isOn: boolean }
  | {
      readonly kind: 'slider'
      /** The tiers the current model serves, lowest first. */
      readonly levels: readonly EffortLevel[]
      readonly current: EffortLevel
    }

export type PaletteAction =
  | { readonly type: 'attachFile' }
  | { readonly type: 'mentionFile' }
  | { readonly type: 'clearConversation' }
  | { readonly type: 'openHistory' }
  | { readonly type: 'openUsage' }
  | { readonly type: 'openAgents' }
  | { readonly type: 'openModelPicker' }
  | { readonly type: 'setEffort'; readonly effort: EffortLevel }
  | { readonly type: 'toggleThinking' }
  | { readonly type: 'openPermissionModes' }
  | { readonly type: 'toggleFocusView' }
  | { readonly type: 'toggleCtrlEnterToSend' }
  | { readonly type: 'openSettings' }
  | { readonly type: 'openKeybindings' }
  | { readonly type: 'signOut' }
  | { readonly type: 'insertSkill'; readonly selector: string }
  /** `/goal ` in the prompt, for the objective (M45). */
  | { readonly type: 'startGoal' }
  | { readonly type: 'startLoop' }
  | { readonly type: 'compact' }
  /** `/handoff …` in the prompt, for the new conversation's goal (M74). */
  | { readonly type: 'startHandoff' }
  | { readonly type: 'manageSkills' }
  | { readonly type: 'importSkills' }
  | { readonly type: 'importFromAgents' }
  | { readonly type: 'showMcpServers' }
  | { readonly type: 'showHooks' }
  | { readonly type: 'showMemory' }
  /** The saved plans (M79), listed by the host to open or implement. */
  | { readonly type: 'showPlans' }
  | { readonly type: 'newWorktree' }
  | { readonly type: 'removeWorktree' }
  | { readonly type: 'exportConversation'; readonly format: ExportFormat }
  /** "Import session…" (M84): resume a portable JSON file on the Model API backend. */
  | { readonly type: 'importSession' }
  /** "Open share file…" (M84): a portable JSON file read-only in the panel. */
  | { readonly type: 'openShareFile' }
  | { readonly type: 'openLog' }
  | { readonly type: 'openExternal'; readonly url: string }
  | { readonly type: 'setPaidFeature'; readonly feature: PaidFeature; readonly isOn: boolean }
  /** `/review ` in the prompt, for what to review (M70). */
  | { readonly type: 'startReview' }
  /** A review preset (M70): the request as the host takes it. */
  | { readonly type: 'review'; readonly request: ReviewRequest }
  /** The review pane over the conversation's changes (M70). */
  | { readonly type: 'openReviewPane' }
  | { readonly type: 'none' }

export interface PaletteItem {
  readonly id: string
  readonly label: string
  readonly detail?: string
  readonly widget?: PaletteWidget
  readonly action: PaletteAction
  /**
   * The row's name in the prompt's "/" list (M38), without the slash, for a
   * row whose label is not already `/name`: Claude Code's names where it has
   * one.
   */
  readonly slashName?: string
  /** Slider rows step their value on Left/Right instead of activating. */
  readonly isSlider?: boolean
  readonly isDisabled?: boolean
}

export interface PaletteGroup {
  readonly id: string
  readonly title: string
  readonly items: readonly PaletteItem[]
}

export interface UsageTotals {
  readonly inputTokens: number
  readonly outputTokens: number
}

export interface PaletteContext {
  readonly currentModel:
    { readonly modelId: string; readonly contextLimit: number | undefined } | undefined
  readonly models: readonly ModelOption[]
  readonly effort: EffortLevel
  readonly isThinkingEnabled: boolean
  readonly permissionMode: PermissionMode
  readonly isFocusView: boolean
  readonly useCtrlEnterToSend: boolean
  readonly usage: UsageTotals | undefined
  /** undefined while the session has not been started, so nothing is known. */
  readonly skills: readonly SkillOption[] | undefined
  /** The backend in use (M7); undefined until the host has decided. */
  readonly backend: BackendKind | undefined
  /** The paid features that are on (M33, PLAN.md D30). */
  readonly paidFeatures: readonly PaidFeature[]
  /** A Model API key is stored (M44): the Muse Code backend offers the key's features. */
  readonly isKeyStored: boolean
}

/** The backend's name as the palette, the usage dialog and an export show it. */
export function backendLabel(kind: BackendKind): string {
  // Built per call, so the name is the installed table's (PLAN.md D33).
  const labels: Readonly<Record<BackendKind, string>> = {
    museCode: UI_TEXT.backendMuseCode,
    modelApi: UI_TEXT.backendModelApi,
  }
  return labels[kind]
}

const TOKENS_PER_MILLION = 1_000_000
const TOKENS_PER_THOUSAND = 1000
// Thousands are shown to one decimal: 12.3K.
const TOKENS_PER_TENTH_THOUSAND = 100
const TENTHS_PER_UNIT = 10

/** "1M" / "200K" / "12.3K" / "512" for a token count, in the display language's digits. */
export function formatTokenWindow(tokens: number): string {
  if (tokens < TOKENS_PER_THOUSAND) {
    return formatNumber(tokens)
  }
  const thousands = Math.round(tokens / TOKENS_PER_TENTH_THOUSAND) / TENTHS_PER_UNIT
  // 999,950 and up round to a thousand thousands: that is "1M", not "1,000K".
  return thousands < TOKENS_PER_THOUSAND
    ? `${formatNumber(thousands)}K`
    : `${formatNumber(Math.round(tokens / TOKENS_PER_MILLION))}M`
}

/** "200K context": a model's context window. */
export function contextWindowLabel(tokens: number): string {
  return fill(UI_TEXT.modelContextWindow, { tokens: formatTokenWindow(tokens) })
}

function contextSuffix(contextLimit: number | undefined): string {
  return contextLimit === undefined ? '' : ` (${contextWindowLabel(contextLimit)})`
}

function modelValue(context: PaletteContext): string {
  const { currentModel } = context
  return currentModel === undefined
    ? UI_TEXT.hostStarting
    : `${currentModel.modelId}${contextSuffix(currentModel.contextLimit)}`
}

function usageValue(usage: UsageTotals | undefined): string {
  return usage === undefined
    ? '—'
    : fill(UI_TEXT.sessionUsageValue, {
        input: formatTokenWindow(usage.inputTokens),
        output: formatTokenWindow(usage.outputTokens),
      })
}

function continueLabel(source: SkillImportSource): string {
  const labels: Readonly<Record<SkillImportSource, string>> = {
    claude: UI_TEXT.continueClaudeItem,
    codex: UI_TEXT.continueCodexItem,
  }
  return labels[source]
}

/** Muse Code's bundled `resume-claude` / `resume-codex`, where the session lists them (M30). */
function continueItems(skills: readonly SkillOption[] | undefined): readonly PaletteItem[] {
  return SKILL_IMPORT_SOURCES.flatMap((source) => {
    const selector = RESUME_SKILL_SELECTORS[source]
    return skills?.some((skill) => skill.selector === selector) === true
      ? [
          {
            id: `continue:${source}`,
            label: continueLabel(source),
            detail: UI_TEXT.continueDetail,
            action: { type: 'insertSkill', selector } as const,
          },
        ]
      : []
  })
}

/** The CLI's skill commands (M30); the Model API backend reads skill files itself (M10). */
function skillManagementItems(backend: BackendKind | undefined): readonly PaletteItem[] {
  return backend === 'museCode'
    ? [
        {
          id: 'manageSkills',
          label: UI_TEXT.manageSkillsItem,
          detail: UI_TEXT.manageSkillsDetail,
          action: { type: 'manageSkills' },
        },
        {
          id: 'importSkills',
          label: UI_TEXT.importSkillsItem,
          detail: UI_TEXT.importSkillsDetail,
          action: { type: 'importSkills' },
        },
      ]
    : []
}

/**
 * What Muse Code loads from its own settings (M31). The Model API backend
 * runs the same MCP servers itself (M50) and may load reviewed hooks (M51).
 */
function museConfigItems(backend: BackendKind | undefined): readonly PaletteItem[] {
  if (backend === undefined) {
    return []
  }
  const mcp: PaletteItem = {
    id: 'mcpServers',
    label: UI_TEXT.mcpItem,
    slashName: SLASH_COMMAND_NAMES.mcp,
    detail: backend === 'museCode' ? UI_TEXT.mcpItemDetail : UI_TEXT.mcpItemDetailModelApi,
    action: { type: 'showMcpServers' },
  }
  return [
    mcp,
    {
      id: 'hooks',
      label: UI_TEXT.hooksItem,
      slashName: SLASH_COMMAND_NAMES.hooks,
      detail: UI_TEXT.hooksItemDetail,
      action: { type: 'showHooks' },
    },
  ]
}

/**
 * The paid features' toggles (M33, PLAN.md D30), where they can be used: all
 * on the Model API backend, and on Muse Code the key's images and voice when
 * a key is stored (M44). Each names its price, and turning one on asks the
 * host's confirmation first.
 */
function paidItems(context: PaletteContext): readonly PaletteItem[] {
  return usablePaidFeatures(context.backend, context.isKeyStored).map((feature) => {
    const isOn = context.paidFeatures.includes(feature)
    return {
      id: `paid:${feature}`,
      label: fill(UI_TEXT.paidToggleLabel, { feature: paidFeatureName(feature) }),
      detail: paidFeaturePrice(feature),
      widget: { kind: 'toggle', isOn },
      action: { type: 'setPaidFeature', feature, isOn: !isOn },
    }
  })
}

/** "/export" on both backends; Muse Code's own JSON log where it runs (M30). */
function exportItems(backend: BackendKind | undefined): readonly PaletteItem[] {
  const markdown: PaletteItem = {
    id: 'export',
    label: UI_TEXT.exportItem,
    detail: UI_TEXT.exportDetail,
    action: { type: 'exportConversation', format: 'markdown' },
  }
  // Portable JSON (M84): importable and shareable from either backend; the
  // import itself resumes on the Model API backend only.
  const portable: PaletteItem = {
    id: 'exportJson',
    label: UI_TEXT.exportJsonItem,
    detail: UI_TEXT.exportJsonDetail,
    action: { type: 'exportConversation', format: 'json' },
  }
  const share: PaletteItem = {
    id: 'openShare',
    label: UI_TEXT.openShareItem,
    detail: UI_TEXT.openShareDetail,
    action: { type: 'openShareFile' },
  }
  // An import resumes on the Model API backend (M84), so only it lists the row.
  const importRow: readonly PaletteItem[] =
    backend === 'modelApi'
      ? [
          {
            id: 'importSession',
            label: UI_TEXT.importSessionItem,
            detail: UI_TEXT.importSessionDetail,
            action: { type: 'importSession' },
          },
        ]
      : []
  return backend === 'museCode'
    ? [
        markdown,
        {
          id: 'exportLog',
          label: UI_TEXT.exportLogItem,
          detail: UI_TEXT.exportLogDetail,
          action: { type: 'exportConversation', format: 'sessionLog' },
        },
        portable,
        share,
      ]
    : [markdown, portable, ...importRow, share]
}

/** Model API schedules are extension-owned; Muse Code's native cron has no MSP controls. */
function scheduleItems(backend: BackendKind | undefined): readonly PaletteItem[] {
  return backend === 'modelApi'
    ? [
        {
          id: 'loop',
          label: UI_TEXT.loopItem,
          detail: UI_TEXT.loopItemDetail,
          action: { type: 'startLoop' },
        },
      ]
    : []
}

/**
 * Review (M70, PLAN.md D49), the same on both backends: `/review` for what
 * to look at, the git presets, the security preset and the review pane. The
 * presets that read git say why when Restricted Mode refuses them (the host
 * answers the request).
 */
function reviewItems(): readonly PaletteItem[] {
  return [
    {
      id: 'review',
      label: UI_TEXT.reviewItem,
      detail: UI_TEXT.reviewItemDetail,
      action: { type: 'startReview' },
    },
    {
      id: 'reviewUncommitted',
      label: UI_TEXT.reviewUncommittedItem,
      detail: UI_TEXT.reviewUncommittedDetail,
      action: { type: 'review', request: { scope: 'uncommitted', focus: 'general' } },
    },
    {
      id: 'reviewBranch',
      label: UI_TEXT.reviewBranchItem,
      detail: UI_TEXT.reviewBranchDetail,
      action: { type: 'review', request: { scope: 'branch', focus: 'general' } },
    },
    {
      id: 'reviewCommit',
      label: UI_TEXT.reviewCommitItem,
      detail: UI_TEXT.reviewCommitDetail,
      action: { type: 'review', request: { scope: 'commit', focus: 'general' } },
    },
    {
      id: 'reviewSecurity',
      label: UI_TEXT.reviewSecurityItem,
      slashName: SLASH_COMMAND_NAMES.securityReview,
      detail: UI_TEXT.reviewSecurityDetail,
      action: { type: 'review', request: { scope: 'uncommitted', focus: 'security' } },
    },
    {
      id: 'reviewChanges',
      label: UI_TEXT.reviewChangesItem,
      slashName: SLASH_COMMAND_NAMES.changes,
      detail: UI_TEXT.reviewChangesDetail,
      action: { type: 'openReviewPane' },
    },
  ]
}

function skillItems(skills: readonly SkillOption[] | undefined): readonly PaletteItem[] {
  if (skills === undefined) {
    return [
      {
        id: 'skills:loading',
        label: UI_TEXT.skillsLoading,
        action: { type: 'none' },
        isDisabled: true,
      },
    ]
  }
  if (skills.length === 0) {
    return [
      {
        id: 'skills:empty',
        label: UI_TEXT.skillsEmpty,
        action: { type: 'none' },
        isDisabled: true,
      },
    ]
  }
  return skills.map((skill) => ({
    id: `skill:${skill.selector}`,
    label: `/${skill.selector}`,
    detail:
      skill.argumentHint === undefined
        ? skill.description
        : `${skill.description} — ${skill.argumentHint}`,
    action: { type: 'insertSkill', selector: skill.selector },
  }))
}

export function buildPalette(context: PaletteContext): readonly PaletteGroup[] {
  return [
    {
      id: 'context',
      title: UI_TEXT.groupContext,
      items: [
        { id: 'attachFile', label: UI_TEXT.attachFile, action: { type: 'attachFile' } },
        { id: 'mentionFile', label: UI_TEXT.mentionFile, action: { type: 'mentionFile' } },
        { id: 'clear', label: UI_TEXT.clearConversation, action: { type: 'clearConversation' } },
        {
          id: 'resume',
          label: UI_TEXT.resumeItem,
          slashName: SLASH_COMMAND_NAMES.resume,
          detail: UI_TEXT.resumeDetail,
          action: { type: 'openHistory' },
        },
        ...continueItems(context.skills),
        // Saved plans (M79): the same on both backends.
        {
          id: 'plans',
          label: UI_TEXT.plansItem,
          detail: UI_TEXT.plansItemDetail,
          action: { type: 'showPlans' },
        },
        // git worktrees (M32): the same on both backends.
        {
          id: 'newWorktree',
          label: UI_TEXT.newWorktreeItem,
          detail: UI_TEXT.newWorktreeDetail,
          action: { type: 'newWorktree' },
        },
        {
          id: 'removeWorktree',
          label: UI_TEXT.removeWorktreeItem,
          detail: UI_TEXT.removeWorktreeDetail,
          action: { type: 'removeWorktree' },
        },
      ],
    },
    {
      id: 'model',
      title: UI_TEXT.groupModel,
      items: [
        {
          id: 'switchModel',
          label: UI_TEXT.switchModel,
          slashName: SLASH_COMMAND_NAMES.model,
          widget: { kind: 'value', text: modelValue(context) },
          action: { type: 'openModelPicker' },
        },
        {
          id: 'effort',
          label: `${UI_TEXT.effortItem} (${effortLabel(context.effort)})`,
          widget: {
            kind: 'slider',
            levels: effortLevelsFor(context.currentModel?.modelId),
            current: context.effort,
          },
          action: { type: 'setEffort', effort: context.effort },
          isSlider: true,
        },
        {
          id: 'thinking',
          label: UI_TEXT.thinkingItem,
          widget: { kind: 'toggle', isOn: context.isThinkingEnabled },
          action: { type: 'toggleThinking' },
        },
      ],
    },
    {
      id: 'customize',
      title: UI_TEXT.groupCustomize,
      items: [
        {
          id: 'permissionMode',
          label: UI_TEXT.permissionModeItem,
          slashName: SLASH_COMMAND_NAMES.permissions,
          widget: { kind: 'value', text: UI_TEXT.permissionModes[context.permissionMode] },
          action: { type: 'openPermissionModes' },
        },
        {
          id: 'focusView',
          label: UI_TEXT.focusViewItem,
          widget: { kind: 'toggle', isOn: context.isFocusView },
          action: { type: 'toggleFocusView' },
        },
        {
          id: 'ctrlEnter',
          label: UI_TEXT.ctrlEnterItem,
          widget: { kind: 'toggle', isOn: context.useCtrlEnterToSend },
          action: { type: 'toggleCtrlEnterToSend' },
        },
        ...museConfigItems(context.backend),
        // From the other agents (M83): local files only, the same on both backends.
        {
          id: 'importFromAgents',
          label: UI_TEXT.agentImportItem,
          detail: UI_TEXT.agentImportDetail,
          action: { type: 'importFromAgents' },
        },
        // Muse Code's memory (M49): the same notes on both backends.
        {
          id: 'memory',
          label: UI_TEXT.memoryItem,
          slashName: SLASH_COMMAND_NAMES.memory,
          detail: UI_TEXT.memoryItemDetail,
          action: { type: 'showMemory' },
        },
        {
          id: 'settings',
          label: UI_TEXT.openSettings,
          slashName: SLASH_COMMAND_NAMES.config,
          action: { type: 'openSettings' },
        },
        { id: 'keybindings', label: UI_TEXT.openKeybindings, action: { type: 'openKeybindings' } },
      ],
    },
    {
      id: 'account',
      title: UI_TEXT.groupAccount,
      items: [
        {
          id: 'accountUsage',
          label: UI_TEXT.usageItem,
          detail: UI_TEXT.usageItemDetail,
          action: { type: 'openUsage' },
        },
        {
          id: 'usage',
          label: UI_TEXT.sessionUsage,
          widget: { kind: 'value', text: usageValue(context.usage) },
          action: { type: 'none' },
          isDisabled: true,
        },
        {
          id: 'backend',
          label: UI_TEXT.backendItem,
          detail: UI_TEXT.backendDetail,
          widget: {
            kind: 'value',
            text: context.backend === undefined ? '—' : backendLabel(context.backend),
          },
          action: { type: 'openSettings' },
        },
        ...paidItems(context),
        { id: 'signOut', label: UI_TEXT.signOutItem, action: { type: 'signOut' } },
      ],
    },
    {
      id: 'skills',
      title: UI_TEXT.groupSkills,
      items: [...skillManagementItems(context.backend), ...skillItems(context.skills)],
    },
    {
      id: 'slash',
      title: UI_TEXT.groupSlashCommands,
      items: [
        {
          id: 'agents',
          label: UI_TEXT.agentsCommand,
          detail: UI_TEXT.agentsCommandDetail,
          action: { type: 'openAgents' },
        },
        {
          id: 'compact',
          label: UI_TEXT.compactItem,
          detail: UI_TEXT.compactDetail,
          action: { type: 'compact' },
        },
        // A fresh conversation from this one's distilled brief (M74).
        {
          id: 'handoff',
          label: UI_TEXT.handoffItem,
          detail: UI_TEXT.handoffDetail,
          action: { type: 'startHandoff' },
        },
        // The session goal (M45, PLAN.md D38), on both backends.
        {
          id: 'goal',
          label: UI_TEXT.goalItem,
          detail: UI_TEXT.goalItemDetail,
          action: { type: 'startGoal' },
        },
        ...scheduleItems(context.backend),
        ...exportItems(context.backend),
        {
          id: 'clearCommand',
          label: UI_TEXT.clearItem,
          detail: UI_TEXT.clearConversation,
          action: { type: 'clearConversation' },
        },
        {
          id: 'logout',
          label: UI_TEXT.logoutItem,
          detail: UI_TEXT.signOutItem,
          action: { type: 'signOut' },
        },
        {
          id: 'usageCommand',
          label: UI_TEXT.usageCommand,
          detail: UI_TEXT.usageCommandDetail,
          action: { type: 'openUsage' },
        },
        {
          id: 'costCommand',
          label: UI_TEXT.costCommand,
          detail: UI_TEXT.costCommandDetail,
          action: { type: 'openUsage' },
        },
      ],
    },
    { id: 'review', title: UI_TEXT.groupReview, items: reviewItems() },
    {
      id: 'support',
      title: UI_TEXT.groupSupport,
      items: [
        { id: 'log', label: UI_TEXT.openLog, action: { type: 'openLog' } },
        {
          id: 'issue',
          label: UI_TEXT.reportIssue,
          action: { type: 'openExternal', url: ISSUES_URL },
        },
        {
          id: 'docs',
          label: UI_TEXT.openDocs,
          action: { type: 'openExternal', url: MUSE_DOCS_URL },
        },
      ],
    },
  ]
}

/** Case-insensitive substring filter over label and detail; empty groups drop. */
export function filterPalette(
  groups: readonly PaletteGroup[],
  query: string,
): readonly PaletteGroup[] {
  const needle = query.trim().toLowerCase()
  if (needle === '') {
    return groups
  }
  return groups
    .map((group) => ({
      ...group,
      items: group.items.filter(
        (item) =>
          item.label.toLowerCase().includes(needle) ||
          (item.detail?.toLowerCase().includes(needle) ?? false),
      ),
    }))
    .filter((group) => group.items.length > 0)
}

/** Every enabled row in display order, for keyboard navigation. */
export function flattenPalette(groups: readonly PaletteGroup[]): readonly PaletteItem[] {
  return groups.flatMap((group) => group.items.filter((item) => item.isDisabled !== true))
}

