// A browser-safe PDF signature check shared by the picker, paste/drop, and
// host parser. The signature may appear within the first 1 KiB.

import { PDF_HEADER_SIGNATURE, PDF_HEADER_WINDOW_BYTES } from './constants'

const PDF_HEADER_BYTES = new TextEncoder().encode(PDF_HEADER_SIGNATURE)

export function hasPdfHeader(bytes: Uint8Array): boolean {
  const last = Math.min(bytes.length, PDF_HEADER_WINDOW_BYTES) - PDF_HEADER_BYTES.length
  for (let start = 0; start <= last; start += 1) {
    if (PDF_HEADER_BYTES.every((byte, index) => bytes[start + index] === byte)) {
      return true
    }
  }
  return false
}

src/shared/permissionModes.ts:
// Claude Code permission modes → Muse Session Protocol approval modes.
//
// MSP is "select, never create": a client picks one of four host-defined
// modes and cannot describe a policy on the wire. The Claude Code vocabulary
// is richer, so two of its modes are compositions:
//
//   manual            → promptUnmatched   (the CLI's `--approval-mode untrusted`:
//                                          ask for every action no rule allows;
//                                          Muse Code still edits workspace
//                                          files without asking, M4)
//   acceptEdits       → promptUnmatched + the extension answers file-edit
//                                          approvals itself (M4); Muse Code
//                                          asks none under `muse serve`, so on
//                                          it this is Manual (PLAN.md D69)
//   plan              → denyUnmatched     (read and reason only)
//   auto              → onRequest         (under `muse serve` Muse Code skips
//                                          only the commands it classifies as
//                                          simple and asks for the rest: the
//                                          LLM judge `muse --help` names runs
//                                          only in its interactive and `exec`
//                                          commands, D69; the panel's own
//                                          reviewer answers what it can, M90)
//   bypassPermissions → allowAll          (the CLI's `never`)
//
// The CLI names come from `muse --help` (Muse Code 1.3.0, 2026-09-21):
// "Tool approval mode: untrusted|on-request|never (default: on-request)".
// What each mode does under `muse serve` was read from the CLI's own session
// log and trace and a live probe on 1.4.2 (2026-10-03, PLAN.md D69); the Modes
// menu says it per backend (`permissionModeDetail`). Any mode that would make
// the host wait on a decision the UI cannot give collapses to `denyUnmatched`
// while `hasApprovalUi` is false, which is what M2 shipped with.
//
// Bypass permissions is offered only while the
// `museSpark.allowDangerouslySkipPermissions` setting is on, exactly as the
// Claude Code extension gates it behind `allowDangerouslySkipPermissions`.

import { PERMISSION_MODES, type PermissionMode, UI_TEXT } from './constants'
import type { BackendKind } from './protocol'

/**
 * The Modes menu's line for a mode on the backend in use (PLAN.md D24, D69).
 * `hasReviewer`: the Auto reviewer on Muse Code is on (M90); the ACP agent
 * has none.
 */
export function permissionModeDetail(
  mode: PermissionMode,
  backend: BackendKind | undefined,
  hasReviewer = false,
): string {
  if (backend === 'modelApi') {
    // The Model API backend words only the modes that behave differently there.
    const modelApiDetails: Readonly<Partial<Record<PermissionMode, string>>> =
      UI_TEXT.modelApiPermissionModeDetails
    return modelApiDetails[mode] ?? UI_TEXT.permissionModeDetails[mode]
  }
  return mode === 'auto' && hasReviewer
    ? UI_TEXT.museCodeReviewedAutoDetail
    : UI_TEXT.permissionModeDetails[mode]
}

export const APPROVAL_MODES = ['allowAll', 'promptUnmatched', 'onRequest', 'denyUnmatched'] as const
export type ApprovalMode = (typeof APPROVAL_MODES)[number]

const FULL_MAPPING: Readonly<Record<PermissionMode, ApprovalMode>> = {
  manual: 'promptUnmatched',
  acceptEdits: 'promptUnmatched',
  plan: 'denyUnmatched',
  auto: 'onRequest',
  bypassPermissions: 'allowAll',
}

/** The MSP mode a UI permission mode selects, with approval UI present. */
export function mspApprovalMode(mode: PermissionMode): ApprovalMode {
  return FULL_MAPPING[mode]
}

/** Modes whose MSP counterpart needs the approval cards before it is safe. */
const PROMPTING_MODES: ReadonlySet<ApprovalMode> = new Set(['promptUnmatched', 'onRequest'])

/**
 * The MSP mode to select for a UI permission mode. `hasApprovalUi` is false
 * until M4 renders `approval/requested`; while it is false a prompting mode
 * would hang the turn, so it degrades to `denyUnmatched`.
 */
export function approvalModeFor(mode: PermissionMode, hasApprovalUi: boolean): ApprovalMode {
  const mapped = mspApprovalMode(mode)
  return !hasApprovalUi && PROMPTING_MODES.has(mapped) ? 'denyUnmatched' : mapped
}

/** The modes the Modes menu lists, in the Claude Code order. */
export function availablePermissionModes(
  canBypass: boolean,
): readonly [PermissionMode, ...PermissionMode[]] {
  const [first, ...rest] = PERMISSION_MODES
  return canBypass
    ? PERMISSION_MODES
    : [first, ...rest.filter((mode) => mode !== 'bypassPermissions')]
}

/**
 * Shift+Tab: the next available mode in the Claude Code order. A current mode
 * that is no longer available (Bypass after the setting was turned off)
 * cycles to the first one.
 */
export function nextPermissionMode(mode: PermissionMode, canBypass: boolean): PermissionMode {
  const modes = availablePermissionModes(canBypass)
  // Past the last mode, or a mode no longer listed (indexOf -1), the cycle
  // wraps to the first one; the list is never empty.
  return modes[modes.indexOf(mode) + 1] ?? modes[0]
}

export function isPermissionMode(value: string): value is PermissionMode {
  return (PERMISSION_MODES as readonly string[]).includes(value)
}

// The modes that ask before a command runs: Manual asks, Plan refuses.
const ASKING_MODES: ReadonlySet<PermissionMode> = new Set(['manual', 'plan'])

/**
 * The mode a conversation built on untrusted content opens in (PLAN.md D49,
 * M84): the current mode when it already asks, else Manual, or Plan when
 * `museSpark.initialPermissionMode` is Plan, whatever else that setting
 * says. Only the user's own mode change relaxes it.
 */
export function untrustedStartMode(
  current: PermissionMode,
  initial: PermissionMode,
): PermissionMode {
  if (ASKING_MODES.has(current)) {
    return current
  }
  return initial === 'plan' ? 'plan' : 'manual'
}

src/shared/privateFiles.ts:
// A file that may hold secrets, by its name alone (M54's attachment rule,
// shared since M70): environment files, keys and credentials. It is never
// attached to a message, and a review leaves its changes out of the diff it
// sends. No `vscode`, Node or DOM imports: the webview uses it too.

import {
  PRIVATE_ATTACHMENT_EXTENSIONS,
  PRIVATE_ATTACHMENT_NAMES,
  PRIVATE_ENV_PREFIX,
} from './constants'

const SEPARATORS = /[/\\]/

/** The name's extension, lower case with its dot; empty when it has none. */
function extensionOf(name: string): string {
  const dot = name.lastIndexOf('.')
  return dot <= 0 ? '' : name.slice(dot)
}

/** Whether the file a path (or a bare name) names may hold secrets. */
export function isPrivateFileName(pathOrName: string): boolean {
  const name = (pathOrName.split(SEPARATORS).at(-1) ?? '').toLowerCase()
  return (
    name.startsWith(PRIVATE_ENV_PREFIX) ||
    PRIVATE_ATTACHMENT_NAMES.has(name) ||
    PRIVATE_ATTACHMENT_EXTENSIONS.has(extensionOf(name))
  )
}

src/shared/reviewCommand.ts:
// `/review …` typed in the prompt (M70, PLAN.md D49), and the request it
// becomes on the wire to the host:
//
//   /review                        the uncommitted changes
//   /review branch [base]          the branch against its base (picked when absent)
//   /review commit [revision]      one commit (picked when absent)
//   /review <what to look at>      custom instructions; git is not needed
//   /review security …             any of the above, for security
//
// A keyword counts only where the grammar puts it and is followed by at most
// one revision word, so `/review branch naming in utils` is custom text.
// Pure; the webview posts the request instead of sending a message.

import * as z from 'zod/mini'
import {
  REVIEW_FOCUSES,
  REVIEW_INSTRUCTIONS_MAX_CHARS,
  REVIEW_KEYWORDS,
  REVIEW_REF_MAX_CHARS,
  REVIEW_SLASH_COMMAND,
} from './constants'

// A git revision word: no whitespace or control character, never a leading
// dash, so it cannot be read as one of git's options, and at most
// REVIEW_REF_MAX_CHARS long. A word after a keyword that is not one makes the
// prompt custom text, so the parser never asks for what the schema refuses.
const REVISION = /^[^\s\-\p{Cc}][^\s\p{Cc}]*$/u
const revisionSchema = z.string().check(z.maxLength(REVIEW_REF_MAX_CHARS), z.regex(REVISION))
const focusSchema = z.enum(REVIEW_FOCUSES)

export const reviewRequestSchema = z.discriminatedUnion('scope', [
  z.object({ scope: z.literal('uncommitted'), focus: focusSchema }),
  z.object({ scope: z.literal('branch'), focus: focusSchema, base: z.optional(revisionSchema) }),
  z.object({ scope: z.literal('commit'), focus: focusSchema, commit: z.optional(revisionSchema) }),
  z.object({
    scope: z.literal('custom'),
    focus: focusSchema,
    instructions: z
      .string()
      .check(z.trim(), z.minLength(1), z.maxLength(REVIEW_INSTRUCTIONS_MAX_CHARS)),
  }),
])
export type ReviewRequest = z.infer<typeof reviewRequestSchema>

const PROMPT = new RegExp(String.raw`^\/${REVIEW_SLASH_COMMAND}(?:\s+([\s\S]*))?$`)
const WORDS = /\s+/

/** Whether `word` is the keyword, whatever its case. */
function isKeyword(word: string | undefined, keyword: string): boolean {
  return word?.toLowerCase() === keyword
}

/** The scope the words after the focus name; undefined when they are custom text. */
function gitScopeOf(
  words: readonly string[],
  focus: ReviewRequest['focus'],
): ReviewRequest | undefined {
  const [first, revision, ...rest] = words
  if (first === undefined) {
    return { scope: 'uncommitted', focus }
  }
  if (rest.length > 0 || (revision !== undefined && !revisionSchema.safeParse(revision).success)) {
    return undefined
  }
  if (isKeyword(first, REVIEW_KEYWORDS.branch)) {
    return { scope: 'branch', focus, ...(revision !== undefined && { base: revision }) }
  }
  return isKeyword(first, REVIEW_KEYWORDS.commit)
    ? { scope: 'commit', focus, ...(revision !== undefined && { commit: revision }) }
    : undefined
}

/**
 * The review a prompt asks for, or undefined for any other text. Text too
 * long for custom instructions is still a review request; the host is never
 * sent more than the schema allows, so the caller checks it.
 */
export function parseReviewPrompt(text: string): ReviewRequest | undefined {
  const match = PROMPT.exec(text.trim())
  if (match === null) {
    return undefined
  }
  const rest = (match[1] ?? '').trim()
  const words = rest === '' ? [] : rest.split(WORDS)
  const isSecurity = isKeyword(words[0], REVIEW_KEYWORDS.security)
  const focus = isSecurity ? 'security' : 'general'
  const scoped = isSecurity ? words.slice(1) : words
  const gitScope = gitScopeOf(scoped, focus)
  if (gitScope !== undefined) {
    return gitScope
  }
  const instructions = isSecurity ? rest.slice(words[0]?.length ?? 0).trim() : rest
  return { scope: 'custom', focus, instructions }
}

/** The prompt that asks for `request`: what its card shows when a palette row started it. */
export function reviewCommandText(request: ReviewRequest): string {
  const words: string[] = [`/${REVIEW_SLASH_COMMAND}`]
  if (request.focus === 'security') {
    words.push(REVIEW_KEYWORDS.security)
  }
  switch (request.scope) {
    case 'uncommitted': {
      break
    }
    case 'branch': {
      words.push(REVIEW_KEYWORDS.branch, ...(request.base === undefined ? [] : [request.base]))
      break
    }
    case 'commit': {
      words.push(REVIEW_KEYWORDS.commit, ...(request.commit === undefined ? [] : [request.commit]))
      break
    }
    case 'custom': {
      words.push(request.instructions)
      break
    }
  }
  return words.join(' ')
}

/** Whether the review reads git's changes, which Restricted Mode does not run. */
export function isGitReview(request: ReviewRequest): boolean {
  return request.scope !== 'custom'
}

src/shared/schedule.ts:
// The extension's Model API scheduled prompt, shared by the host, webview and
// persistent workspace store (PLAN.md M52). Muse Code's native cron jobs do
// not use this shape; MSP has no scheduler contract.

import * as z from 'zod/mini'

export const scheduleCadenceSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('interval'), everyMs: z.number() }),
  z.object({ kind: z.literal('cron'), expression: z.string() }),
])
export type ScheduleCadence = z.infer<typeof scheduleCadenceSchema>

export const scheduledPromptSchema = z.object({
  id: z.string(),
  sessionId: z.string(),
  workspaceRoot: z.string(),
  accountId: z.string(),
  prompt: z.string(),
  cadence: scheduleCadenceSchema,
  createdAtMs: z.number(),
  expiresAtMs: z.number(),
  nextFireAtMs: z.number(),
  fireCount: z.number(),
  lastFireAtMs: z.optional(z.number()),
})
export type ScheduledPrompt = z.infer<typeof scheduledPromptSchema>

/** The prompt, model and session the user accepted for one due occurrence. */
export interface ScheduleRunConfirmation {
  readonly sessionId: string
  readonly modelId: string
  readonly prompt: string
}

/** Safe panel projection: key identity and workspace path stay in the host. */
export const scheduleViewSchema = z.object({
  id: z.string(),
  prompt: z.string(),
  cadence: scheduleCadenceSchema,
  nextFireAtMs: z.number(),
  fireCount: z.number(),
  lastFireAtMs: z.optional(z.number()),
})
export type ScheduleView = z.infer<typeof scheduleViewSchema>

export function scheduleViewOf(job: ScheduledPrompt): ScheduleView {
  return {
    id: job.id,
    prompt: job.prompt,
    cadence: job.cadence,
    nextFireAtMs: job.nextFireAtMs,
    fireCount: job.fireCount,
    ...(job.lastFireAtMs !== undefined && { lastFireAtMs: job.lastFireAtMs }),
  }
}

export interface ScheduleStore {
  create(job: ScheduledPrompt): Promise<void>
  list(sessionId: string): Promise<readonly ScheduledPrompt[]>
  remove(sessionId: string, jobId: string): Promise<boolean>
  /** Atomic, durable receipt. False means this occurrence was already admitted. */
  claim(job: ScheduledPrompt, occurrenceMs: number): Promise<boolean>
}

src/shared/sessions.ts:
// Session history (M6): the row the History dialog shows for one stored
// session, its title, the time groups and the archive policy. Shared by
// the host (which builds rows from `session/list`) and the webview (which
// groups and filters them). No `vscode`, Node or DOM imports.

import * as z from 'zod/mini'
import {
  IDE_CONTEXT_TAGS,
  MILLISECONDS_PER_SECOND,
  SECONDS_PER_MINUTE,
  MINUTES_PER_HOUR,
  HOURS_PER_DAY,
  DAYS_PER_WEEK,
  UI_TEXT,
} from './constants'
import { formatDate, formatRelativeTime } from './l10n/text'

/** The activity fields a `session/list` row carries through to the dialog. */
export const sessionActivityFields = {
  /** RFC 3339 instants from the host. */
  createdAt: z.string(),
  updatedAt: z.string(),
  lastActivityAt: z.optional(z.string()),
  branch: z.optional(z.string()),
  /** `notLoaded`, `idle`, `running` (open on the wire). */
  status: z.string(),
  turnCount: z.number(),
} as const

export const sessionRowSchema = z.object({
  sessionId: z.string(),
  /** The allocated name, else the first prompt without IDE context, else "Untitled". */
  title: z.string(),
  /** True when the host allocated a name (renaming is then meaningful). */
  isNamed: z.boolean(),
  ...sessionActivityFields,
  isFork: z.boolean(),
})
export type SessionRow = z.infer<typeof sessionRowSchema>

const IDE_CONTEXT_BLOCKS = new RegExp(
  String.raw`<(${IDE_CONTEXT_TAGS.selection}|${IDE_CONTEXT_TAGS.openedFile})>[\s\S]*?</\1>`,
  'g',
)
const WHITESPACE_RUNS = /\s+/g

/** The prompt as the user typed it: the IDE reminders the host appended are dropped. */
export function stripIdeContext(text: string): string {
  return text.replaceAll(IDE_CONTEXT_BLOCKS, ' ').replaceAll(WHITESPACE_RUNS, ' ').trim()
}

export interface SessionTitleSource {
  readonly name?: string | undefined
  readonly title?: string | undefined
  readonly firstUserPrompt?: string | undefined
}

/** The dialog row label; `session/list` builds `title` from the whole prompt. */
export function sessionTitle(source: SessionTitleSource): string {
  if (source.name !== undefined && source.name.trim() !== '') {
    return source.name.trim()
  }
  const prompt = stripIdeContext(source.title ?? source.firstUserPrompt ?? '')
  return prompt === '' ? UI_TEXT.untitledConversation : prompt
}

/** The instant the row is grouped and aged by. */
export function activityOf(row: SessionRow): number {
  return Date.parse(row.lastActivityAt ?? row.updatedAt)
}

const MS_PER_MINUTE = MILLISECONDS_PER_SECOND * SECONDS_PER_MINUTE
const MS_PER_DAY = MS_PER_MINUTE * MINUTES_PER_HOUR * HOURS_PER_DAY

/** Days of inactivity after which a session is hidden; 0 never hides. */
export function isStale(row: SessionRow, nowMs: number, archiveAfterDays: number): boolean {
  return archiveAfterDays > 0 && nowMs - activityOf(row) > archiveAfterDays * MS_PER_DAY
}

export type SessionGroupId = 'today' | 'yesterday' | 'week' | 'older'

export interface SessionGroup {
  readonly id: SessionGroupId
  readonly title: string
  readonly rows: readonly SessionRow[]
}

function startOfDay(ms: number): number {
  const date = new Date(ms)
  date.setHours(0, 0, 0, 0)
  return date.getTime()
}

function groupIdOf(row: SessionRow, nowMs: number): SessionGroupId {
  const today = startOfDay(nowMs)
  const activity = activityOf(row)
  if (activity >= today) {
    return 'today'
  }
  if (activity >= today - MS_PER_DAY) {
    return 'yesterday'
  }
  return activity >= today - DAYS_PER_WEEK * MS_PER_DAY ? 'week' : 'older'
}

const GROUP_ORDER: readonly SessionGroupId[] = ['today', 'yesterday', 'week', 'older']

/** A group's heading, read when the list is built so it is in the installed table. */
function groupTitle(id: SessionGroupId): string {
  const titles: Readonly<Record<SessionGroupId, string>> = {
    today: UI_TEXT.historyToday,
    yesterday: UI_TEXT.historyYesterday,
    week: UI_TEXT.historyWeek,
    older: UI_TEXT.historyOlder,
  }
  return titles[id]
}

export interface SessionListOptions {
  readonly nowMs: number
  readonly query: string
  readonly archivedIds: ReadonlySet<string>
  readonly archiveAfterDays: number
  readonly isShowingArchived: boolean
}

/** Case-insensitive substring match on the title and the branch. */
export function isMatch(row: SessionRow, query: string): boolean {
  const needle = query.trim().toLowerCase()
  return (
    needle === '' ||
    row.title.toLowerCase().includes(needle) ||
    (row.branch?.toLowerCase().includes(needle) ?? false)
  )
}

/** Whether the row is hidden from the default listing (archived or stale). */
export function isArchived(row: SessionRow, options: SessionListOptions): boolean {
  return (
    options.archivedIds.has(row.sessionId) || isStale(row, options.nowMs, options.archiveAfterDays)
  )
}

/** The rows to show, newest first inside Today / Yesterday / Previous 7 days / Older. */
export function groupSessions(
  rows: readonly SessionRow[],
  options: SessionListOptions,
): readonly SessionGroup[] {
  const shown = rows
    .filter((row) => isMatch(row, options.query))
    .filter((row) => options.isShowingArchived || !isArchived(row, options))
    .toSorted((a, b) => activityOf(b) - activityOf(a))
  return GROUP_ORDER.flatMap((id) => {
    const members = shown.filter((row) => groupIdOf(row, options.nowMs) === id)
    return members.length === 0 ? [] : [{ id, title: groupTitle(id), rows: members }]
  })
}

/**
 * How long ago, in the display language (PLAN.md D33): "now", "5 min. ago",
 * "3 hr. ago", "yesterday", "2 days ago"; past a week, the date. A time in
 * the future (a clock ahead of this one) reads as now.
 */
export function relativeTime(iso: string, nowMs: number): string {
  const thenMs = Date.parse(iso)
  const minutes = Math.floor(Math.max(0, nowMs - thenMs) / MS_PER_MINUTE)
  if (minutes < 1) {
    // Zero seconds is the language's "now"; zero minutes would read "this minute".
    return formatRelativeTime(0, 'second')
  }
  if (minutes < MINUTES_PER_HOUR) {
    return formatRelativeTime(-minutes, 'minute')
  }
  const hours = Math.floor(minutes / MINUTES_PER_HOUR)
  if (hours < HOURS_PER_DAY) {
    return formatRelativeTime(-hours, 'hour')
  }
  const days = Math.floor(hours / HOURS_PER_DAY)
  return days < DAYS_PER_WEEK ? formatRelativeTime(-days, 'day') : formatDate(thenMs)
}

src/shared/textFileDisplay.ts:
// Muse Code persists displayText but not picked text-file chips. This readable
// suffix survives History. The full text remains visible so a user-authored
// identical line is never silently removed; even a damaged suffix flags the
// card as a file so rewind cannot silently lose its bytes.

import * as z from 'zod/mini'
import { TEXT_FILE_DISPLAY_MARKER } from './constants'

const FILE_NAMES = z.array(z.string())

/** Append a readable, structured annotation to the MSP display text. */
export function textFileDisplay(visibleText: string, names: readonly string[]): string {
  return `${visibleText}${TEXT_FILE_DISPLAY_MARKER}${JSON.stringify(names)}]`
}

/** `undefined` means no marker; empty names means malformed but file-bearing. */
export function readTextFileDisplay(displayText: string): readonly string[] | undefined {
  const markerAt = displayText.lastIndexOf(TEXT_FILE_DISPLAY_MARKER)
  if (markerAt === -1) {
    return undefined
  }
  const suffix = displayText.slice(markerAt + TEXT_FILE_DISPLAY_MARKER.length)
  if (!suffix.endsWith(']')) {
    return []
  }
  try {
    const parsed: unknown = JSON.parse(suffix.slice(0, -1))
    const result = FILE_NAMES.safeParse(parsed)
    return result.success && result.data.length > 0 ? result.data : []
  } catch {
    return []
  }
}

src/shared/usage.ts:
// Subscription usage (M8): the shape Muse Code reports through `usage/read`
// and `usage/changed` (the SDK's `SubscriptionUsage`), shared by the host,
// the webview protocol and the Account & usage dialog, plus the pure
// formatting the dialog needs. Percentages are the provider's verbatim
// integers and may exceed 100; times are epoch milliseconds. `observedAtMs`
// is when the CLI received the numbers, so the dialog says "as of", never
// implies live data.

import * as z from 'zod/mini'
import {
  HOURS_PER_DAY,
  MILLISECONDS_PER_SECOND,
  MINUTES_PER_HOUR,
  SECONDS_PER_MINUTE,
  UI_TEXT,
} from './constants'
import { type DurationUnit, formatUnit, plural } from './l10n/text'

export const subscriptionUsageSchema = z.object({
  observedAtMs: z.number(),
  tier: z.string(),
  window: z.object({
    usedPercent: z.number(),
    resetsAtMs: z.number(),
    windowDurationMins: z.number(),
  }),
  weekly: z.object({ usedPercent: z.number(), resetsAtMs: z.number() }),
})
export type SubscriptionUsage = z.infer<typeof subscriptionUsageSchema>

/** `usage/read` result: `{ usage? }`, the member absent when nothing was observed. */
export const usageReadResultSchema = z.object({ usage: z.optional(subscriptionUsageSchema) })

/** What drove the account's usage over a window (M14): model attempts by origin. */
export const usageInsightsSchema = z.object({
  attempts: z.number(),
  sessions: z.number(),
  reminderAttempts: z.number(),
  subagentAttempts: z.number(),
  longSessionAttempts: z.number(),
})
export type UsageInsights = z.infer<typeof usageInsightsSchema>

export const SIGN_IN_METHOD_FACTS = ['cli', 'apiKey', 'none'] as const

/** The Account section of the usage modal (M14). */
export const accountFactsSchema = z.object({
  signInMethod: z.enum(SIGN_IN_METHOD_FACTS),
  cliVersion: z.optional(z.string()),
  /** Muse Code's `run.subagent_delegation_mode`; absent on the Model API backend. */
  delegationMode: z.optional(z.string()),
  /** Muse Code's `run.workflow_trigger_mode` (M47); absent on the Model API backend. */
  workflowTriggerMode: z.optional(z.string()),
})
export type AccountFacts = z.infer<typeof accountFactsSchema>

export const FULL_PERCENT = 100
const MILLISECONDS_PER_MINUTE = MILLISECONDS_PER_SECOND * SECONDS_PER_MINUTE

/** The bar's fill: the percent clamped to the bar; the label keeps the real number. */
export function barValue(usedPercent: number): number {
  return Math.min(Math.max(usedPercent, 0), FULL_PERCENT)
}

/** A larger unit and, when it is not zero, the smaller one after it: "2h 5m", "3d". */
function unitPair(
  large: number,
  largeUnit: DurationUnit,
  small: number,
  smallUnit: DurationUnit,
): string {
  const head = formatUnit(large, largeUnit)
  return small > 0 ? `${head} ${formatUnit(small, smallUnit)}` : head
}

/**
 * "2h 5m", "3d 4h", "1m" in the display language's short units (PLAN.md
 * D33); its word for "now" once the moment has passed.
 */
export function formatDuration(untilMs: number, nowMs: number): string {
  if (untilMs <= nowMs) {
    return UI_TEXT.durationNow
  }
  const totalMinutes = Math.ceil((untilMs - nowMs) / MILLISECONDS_PER_MINUTE)
  const days = Math.floor(totalMinutes / (MINUTES_PER_HOUR * HOURS_PER_DAY))
  const hours = Math.floor(totalMinutes / MINUTES_PER_HOUR) % HOURS_PER_DAY
  if (days > 0) {
    return unitPair(days, 'day', hours, 'hour')
  }
  const minutes = totalMinutes % MINUTES_PER_HOUR
  return hours > 0 ? unitPair(hours, 'hour', minutes, 'minute') : formatUnit(minutes, 'minute')
}

const OPAQUE_TIER = /^[\d-]+$/

/**
 * The plan line: the tier id verbatim when it reads as a name, or a generic
 * label when Meta sends an opaque numeric id (verified live 2026-09-22:
 * `tier: "27681393394859588"`).
 */
export function planLabel(tier: string): string {
  return tier === '' || OPAQUE_TIER.test(tier) ? UI_TEXT.usagePlanSubscription : tier
}

/** "5-hour window" / "90-minute window" from the provider's duration. */
export function formatWindowLength(windowDurationMins: number): string {
  return windowDurationMins % MINUTES_PER_HOUR === 0
    ? plural(UI_TEXT.usageWindowHours, windowDurationMins / MINUTES_PER_HOUR)
    : plural(UI_TEXT.usageWindowMinutes, windowDurationMins)
}

src/shared/verifyText.ts:
// The verify loop's words for the user (M68, PLAN.md D49), shared by the
// transcript's rows and the Markdown export so both say the same (the M68
// review): the line under a "Check edits" or "Run checks" row, and how an
// edit's `then_run` ended. Shared by host and webview: no `vscode`, Node or
// DOM imports.

import type { ThenRunResult, VerifySummary } from './agentEvents'
import { UI_TEXT } from './constants'
import { fill, formatNumber, plural } from './l10n/text'

const PART_SEPARATOR = ' · '
const DETAIL_SEPARATOR = ': '

/**
 * "2 errors, 1 warning · 1 file not checked · lint failed · test passed", or
 * undefined for nothing to say. Errors and warnings count only the files
 * whose diagnostics were read.
 */
export function verifySummaryText(summary: VerifySummary | undefined): string | undefined {
  if (summary === undefined) {
    return undefined
  }
  const parts: string[] = []
  const { errors, warnings, unchecked } = summary
  if (errors !== undefined && warnings !== undefined) {
    parts.push(
      errors === 0 && warnings === 0
        ? UI_TEXT.verifyClean
        : `${plural(UI_TEXT.verifyErrors, errors)}, ${plural(UI_TEXT.verifyWarnings, warnings)}`,
    )
  }
  if (unchecked !== undefined && unchecked > 0) {
    parts.push(plural(UI_TEXT.verifyUnchecked, unchecked))
  }
  for (const check of summary.checks) {
    parts.push(fill(UI_TEXT.checkOutcomes[check.outcome], { name: check.name }))
  }
  return parts.length === 0 ? undefined : parts.join(PART_SEPARATOR)
}

/** How a `then_run` command ended, in words: never "Stopped" for one that failed. */
export function thenRunOutcomeText(result: ThenRunResult): string {
  switch (result.outcome) {
    case 'notRun': {
      const reason = result.skip === undefined ? '' : UI_TEXT.checkSkips[result.skip]
      return fill(UI_TEXT.thenRunNotRun, {
        reason:
          result.detail === undefined ? reason : `${reason}${DETAIL_SEPARATOR}${result.detail}`,
      })
    }
    case 'timedOut': {
      return UI_TEXT.thenRunTimedOut
    }
    case 'cancelled': {
      return UI_TEXT.toolStopped
    }
    case 'passed':
    case 'failed': {
      return result.exitCode === undefined
        ? UI_TEXT.thenRunNoExitCode
        : fill(UI_TEXT.userShellExitCode, { code: formatNumber(result.exitCode) })
    }
  }
}
